ALTER TABLE public.films ADD COLUMN IF NOT EXISTS posters_i18n JSONB DEFAULT '{}'::jsonb;

UPDATE public.films SET tmdb_id = 98, titoli_i18n = '{"it":"Il Gladiatore","en":"Gladiator","fr":"Gladiator","de":"Gladiator","es":"Gladiator"}'::jsonb, trame_i18n = '{"it":"Il generale romano Massimo Decimo Meridio viene tradito dal perfido Commodo, figlio dell''imperatore Marco Aurelio, che usurpa il trono e fa sterminare la famiglia di Massimo. Catturato e ridotto in schiavitù, Massimo viene addestrato come gladiatore dal lanista Prossimo. La sua straordinaria abilità nell''arena lo condurrà fino al Colosseo a Roma, dove cercherà la sua vendetta contro il nuovo imperatore.","en":"After the death of Emperor Marcus Aurelius, his devious son takes power and demotes Maximus, one of Rome''s most capable generals who Marcus preferred. Eventually, Maximus is forced to become a gladiator and battle to the death against other men for the amusement of paying audiences.","fr":"Le général romain Maximus est le plus fidèle soutien de l''empereur Marc Aurèle, qu''il a conduit de victoire en victoire avec une bravoure et un dévouement exemplaires. Jaloux du prestige de Maximus, et plus encore de l''amour que lui voue l''empereur, le fils de Marc Aurèle, Commode, s''arroge brutalement le pouvoir, puis ordonne l''arrestation du général et son exécution. Maximus échappe à ses assassins mais ne peut empêcher le massacre de sa famille. Capturé par un marchand d''esclaves, il devient gladiateur et prépare sa vengeance.","de":"Der gefeierte römische Feldherr Maximus wird vom sterbenden Kaiser Marcus Aurelius gebeten, seine Nachfolge anzutreten. Um dies zu verhindern, tötet Aurelius’ Sohn seinen Vater und ordnet die Exekution von Maximus und seiner Familie an. Maximus gelingt die Flucht. Verwundet wird er von einem Sklavenhändler gefangen genommen und muss sich fortan als Gladiator beweisen. Als Kampfmaschine hat er schließlich nur noch ein Ziel: Rache an seinem Peiniger zu nehmen …","es":"En el año 180, el Imperio Romano domina todo el mundo conocido. Tras una gran victoria sobre los bárbaros del norte, el anciano emperador Marco Aurelio decide transferir el poder a Máximo, bravo general de sus ejércitos y hombre de inquebrantable lealtad al imperio. Pero su hijo Cómodo, que aspiraba al trono, no lo acepta y trata de asesinar a Máximo."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/euOKjQaV1QXtzLyNZAa1PMHGJlJ.jpg","en":"https://image.tmdb.org/t/p/w500/aDb548BOkFfI4nFm0kx8A3Ezh7H.jpg","fr":"https://image.tmdb.org/t/p/w500/56Yb1T9GgYqMBM9nI8JxfmPSN8v.jpg","de":"https://image.tmdb.org/t/p/w500/32wJunadteAxUkXnbQ1lHjjp5pa.jpg","es":"https://image.tmdb.org/t/p/w500/90QFOG5zSN4cbrIVs4DL4ePAuA5.jpg"}'::jsonb WHERE id = 2;
UPDATE public.films SET tmdb_id = 7191, titoli_i18n = '{"en":"Cloverfield","es":"Monstruoso","it":"Cloverfield","fr":"Cloverfield","de":"Cloverfield"}'::jsonb, trame_i18n = '{"en":"Five young New Yorkers throw their friend a going-away party the night that a monster the size of a skyscraper descends upon the city. Told from the point of view of their video camera, the film is a document of their attempt to survive the most surreal, horrifying event of their lives.","es":"La noche en que varios jóvenes neoyorquinos celebran la fiesta de despedida de un amigo en Manhattan, un monstruo del tamaño de un rascacielos llega a la ciudad. Contada desde el punto de vista de la videocámara de uno de ellos, este es el escalofriante documento sobre sus intentos por sobrevivir durante los momentos más increíbles y terroríficos de sus vidas.","it":"Durante una festa di addio a New York per Rob, un ragazzo in partenza per il Giappone, la città viene scossa dall''attacco improvviso di un mostro gigante di origine sconosciuta. Rob e i suoi amici si avventurano tra le rovine di Manhattan per salvare Beth, la ragazza di cui Rob è innamorato, rimasta intrappolata nel suo appartamento. L''intera vicenda è raccontata attraverso il punto di vista di una videocamera amatoriale che documenta in tempo reale il caos e la sopravvivenza del gruppo.","fr":"New York - Ses amis et relations ont organisé chez Rob une fête en l''honneur de son départ pour le Japon. Parmi eux, Hud, vidéaste d''un soir, chargé d''immortaliser l''événement. Soudain une violente secousse ébranle l''immeuble. Les invités se précipitent dans la rue où une foule inquiète s''est rassemblée en quelques instants. Une ombre immense se profile dans le ciel, un grondement sourd se fait entendre... et la tête de la Statue de la Liberté s''effondre brutalement sur la chaussée. L''attaque du siècle vient de commencer...","de":"Eine ausgelassene Abschiedsparty mitten in Manhattan, doch plötzlich wackeln sprichwörtlich die Wände und Explosionen ziehen eine Schneise durch Manhattan, infernalisches Gebrüll tönt durch die Straßenschluchten und etwas, das dem Meer entstiegen ist, hat der Freiheitsstatue den Kopf abgerissen und schleudert diesen zur Begrüßung quer durch die halbe Stadt.  Das Monstrum wird „Cloverfield“ genannt und für die gerade eben noch Feiernden bedeutet das erst mal nur eins: Raus aus der Stadt, möglichst lebendig, und auch ohne in die Schusslinie der Army zu geraten, die „Cloverfield“ alles entgegen feuert, was verfügbar ist."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/qIegUGJqyMMCRjkKV1s7A9MqdJ8.jpg","es":"https://image.tmdb.org/t/p/w500/8FBpammgqlX9j9yQt301PHh4sJb.jpg","it":"https://image.tmdb.org/t/p/w500/z8CrCAEsLSdvrbZ1OjkvOmmAlYa.jpg","fr":"https://image.tmdb.org/t/p/w500/zyzGgP5IIkO9d3PQz7me0pPl2vm.jpg","de":"https://image.tmdb.org/t/p/w500/lmQPopu8A4W9HuskcaGTpqILRsj.jpg"}'::jsonb WHERE id = 3;
UPDATE public.films SET tmdb_id = 3049, titoli_i18n = '{"it":"Ace Ventura - L''acchiappanimali","es":"Ace Ventura, un detective diferente","en":"Ace Ventura: Pet Detective","fr":"Ace Ventura, détective chiens et chats","de":"Ace Ventura - Ein tierischer Detektiv"}'::jsonb, trame_i18n = '{"it":"Ace Ventura è un eccentrico e stravagante investigatore privato specializzato nel ritrovare animali scomparsi. Alla vigilia del Super Bowl, viene ingaggiato per ritrovare Snowflake, il delfino mascotta dei Miami Dolphins, finito al centro di un misterioso complotto di vendetta legato all''ex giocatore Ray Finkle.","es":"El detective Ace Ventura, especializado en rescatar animales secuestrados, recibe el encargo de localizar y rescatar el delfin Copo de Nieve, mascota del equipo de fútbol de Miami, que ha sido secuestrado el día anterior a la gran final que debe disputar el equipo.","en":"He''s Ace Ventura: Pet Detective. The Ace is on the case to find the Miami Dolphins'' missing mascot and quarterback Dan Marino. He goes eyeball to eyeball with a man-eating shark, stakes out the Miami Dolphins and woos and wows the ladies. Whether he''s undercover, under fire or underwater, he always gets his man… or beast!","fr":"Ace Ventura, un jeune homme décontracté à la banane arrogante et à la démarche élastique, est le Sherlock Holmes de la gent animale. Le voici à nouveau sur les dents quand le dauphin nommé Flocon de neige, mascotte de l''équipe de football américain de Miami, manque à l''appel.","de":"Detektiv Ace Ventura ist darauf spezialisiert, verlorengegangene Haustiere aufzuspüren. Als ihm der Fall des entführten Delphins Snowflake, dem Maskottchen der Footballmannschaft Miami Dolphins, übertragen wird, erweisen sich die animalischen Instinkte des Schnüfflers als äußerst hilfreich. Bei seinen Ermittlungen stößt Ace zwischen Liebesabenteuern und handgreiflichen Auseinandersetzungen mit den Cops schließlich auf einen ehemaligen Dolphins-Spieler, der nach einem Irrenhausaufenthalt untergetaucht ist."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ptTaBr68fiHfjDVNmQRoOantMDy.jpg","es":"https://image.tmdb.org/t/p/w500/zByKfhPuFUEymc0uzHGdIfO7dx5.jpg","en":"https://image.tmdb.org/t/p/w500/pqiRuETmuSybfnVZ7qyeoXhQyN1.jpg","fr":"https://image.tmdb.org/t/p/w500/tquh5DEbgRPFBHukUp9mcPbjEBb.jpg","de":"https://image.tmdb.org/t/p/w500/h8fixwTBtiEHRHFLjzgulZeHXwp.jpg"}'::jsonb WHERE id = 4;
UPDATE public.films SET tmdb_id = 238, titoli_i18n = '{"en":"The Godfather","it":"Il Padrino","fr":"Le Parrain","de":"Der Pate","es":"El padrino"}'::jsonb, trame_i18n = '{"en":"Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.","it":"A New York, nel 1945, Don Vito Corleone è il capo di una potente famiglia mafiosa. Dopo aver rifiutato di entrare nel business della droga proposto da un clan rivale, Don Vito subisce un grave attentato. Suo figlio minore Michael, un eroe di guerra fino ad allora estraneo alle attività criminali della famiglia, decide di intervenire per proteggere il padre e vendicarsi. Questo evento darà inizio alla sua inesorabile ascesa e trasformazione nel nuovo spietato Padrino.","fr":"La Seconde Guerre mondiale vient de s''achever. À New York, le « parrain » Don Corleone, l''un des chefs respectés de la mafia, se sent vieillir. Il refuse de s''adapter à son temps et de se lancer, comme ses pairs, dans le trafic de drogue. Une frilosité qui entrave la bonne marche des affaires des autres « familles » et qui lui vaut d''être la cible d''un attentat. Don Corleone survit à ses blessures, mais reste très diminué. Mike, son plus jeune fils, qui jusque-là se tenait à l''écart des affaires de son père, devient le plus dévoué de ses héritiers. Plus efficace que ses frères, Sonny et Fredo, il venge son père et organise l''élimination de ses adversaires…","de":"Don Vito Corleone ist der Kopf einer der einflußreichsten Mafia-Familien New Yorks. Als die anderen Familien der Stadt beschließen, neben Glücksspiel und Schutzgelderpressungen nun auch den Handel mit Drogen als Erwerbsquelle zu nutzen und sich Don Corleone diesem Vorhaben nicht anschließen möchte, wird er zum Ziel eines hinterhältigen Mordanschlags. Nun steht Vitos Sohn Michael in der Verantwortung, in die Fußstapfen seines Vaters zu treten, obwohl er mit den Geschäften der Familie bis dato nichts zu tun haben wollte.","es":"Don Vito Corleone, conocido dentro de los círculos del hampa como \"El Padrino\", es el patriarca de una de las cinco familias que ejercen el mando de la Cosa Nostra en Nueva York (Estados Unidos) durante la década de 1940. Don Corleone tiene cuatro hijos: una chica, Connie, y tres varones; Sonny, Michael y Fredo. Cuando Vito reclina intervenir en el negocio de estupefacientes, empieza una cruenta lucha de violentos episodios entre las distintas familias del crimen organizado."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg","it":"https://image.tmdb.org/t/p/w500/gemuM3FvVaWSEBrfk6nVFIOBhBY.jpg","fr":"https://image.tmdb.org/t/p/w500/k3uIbYtiuK8pwbCcbma29nTqmgG.jpg","de":"https://image.tmdb.org/t/p/w500/uumEbSnYqeV1oennyVx8DPVjujF.jpg","es":"https://image.tmdb.org/t/p/w500/5HlLUsmsv60cZVTzVns9ICZD6zU.jpg"}'::jsonb WHERE id = 6;
UPDATE public.films SET tmdb_id = 240, titoli_i18n = '{"en":"The Godfather Part II","fr":"Le Parrain, 2e partie","es":"El padrino II","it":"Il Padrino - Parte II","de":"Der Pate - Teil II"}'::jsonb, trame_i18n = '{"en":"In the continuing saga of the Corleone crime family, a young Vito Corleone grows up in Sicily and in 1910s New York. In the 1950s, Michael Corleone attempts to expand the family business into Las Vegas, Hollywood and Cuba.","fr":"Depuis la mort de Don Vito Corleone, son fils Michael règne sur la famille. Amené à négocier avec la mafia juive, il perd alors le soutien d''un de ses lieutenants, Frankie Pentageli. Échappant de justesse à un attentat, Michael tente de retrouver le coupable, soupçonnant Hyman Roth, le chef de la mafia juive. Vito Corleone, immigrant italien, arrive à New York au début du siècle ; très vite, il devient un des caïds du quartier, utilisant la violence comme moyen de régler toutes les affaires. Seul au départ, il bâtit peu à peu un véritable empire, origine de la fortune de la famille des Corleone.","es":"Continuación de la saga de los Corleone con dos historias paralelas: la elección de Michael Corleone como jefe de los negocios familiares y los orígenes del patriarca, el ya fallecido Don Vito, primero en Sicilia y luego en Estados Unidos, donde, empezando desde abajo, llegó a ser un poderosísimo jefe de la mafia de Nueva York.","it":"Il film sviluppa due linee narrative parallele: da un lato segue la giovinezza di Vito Corleone, dalla fuga dalla Sicilia ai primi del Novecento fino alla sua ascesa come ''Padrino'' a New York; dall''altro racconta le vicende del figlio Michael negli anni ''50, intenzionato ad espandere l''impero di famiglia a Las Vegas e a Cuba, affrontando tradimenti interni, indagini governative e una progressiva disgregazione morale e familiare.","de":"Michael Corleone ist jetzt der Pate seiner Familie und führt diese Aufgabe mit der nötigen Gnadenlosigkeit aus. Als er in Las Vegas und auf Kuba expandieren will, weil ihm die alten Geschäftsideen nichts mehr einbringen, treten Schwierigkeiten auf. Um diese zu klären, veranlaßt Michael eine große Säuberungsaktion, die auch vor den Familienmitgliedern nicht halt macht."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/8a1lJs7mFyGhGhZZDT1azJUoQiZ.jpg","fr":"https://image.tmdb.org/t/p/w500/fATmEcLwO3tTiisa8gYxhV3x4sS.jpg","es":"https://image.tmdb.org/t/p/w500/mbry0W5PRylSUHsYzdiY2FSJwze.jpg","it":"https://image.tmdb.org/t/p/w500/jftmAcdl5D94eANbhHugbUJDULI.jpg","de":"https://image.tmdb.org/t/p/w500/ydzBlAMJTo9jOG5i8aRpZec0jF3.jpg"}'::jsonb WHERE id = 7;
UPDATE public.films SET tmdb_id = 242, titoli_i18n = '{"it":"Il Padrino - Parte III","es":"El padrino III","fr":"Le Parrain, 3e partie","de":"Der Pate - Teil III","en":"The Godfather Part III"}'::jsonb, trame_i18n = '{"it":"Ormai anziano e tormentato dai sensi di colpa per i crimini del passato, in particolare per l''omicidio del fratello Fredo, Michael Corleone cerca di legalizzare le attività della famiglia e di ripulire il proprio nome attraverso una colossale donazione alla Chiesa Cattolica. Mentre tenta di districarsi dalle trame di potere e corruzione all''interno del Vaticano, Michael deve anche gestire la successione dinastica, designando come suo erede l''irrequieto e violento nipote Vincent Mancini, figlio naturale di suo fratello Sonny.","es":"Michael Corleone, heredero del imperio de don Vito Corleone, intenta rehabilitarse socialmente y legitimar todas las posesiones de la familia negociando con el Vaticano. Después de luchar toda su vida se encuentra cansado y centra todas sus esperanzas en encontrar un sucesor que se haga cargo de los negocios. Vincent, el hijo ilegítimo de su hermano Sonny, parece ser el elegido.","fr":"Atteignant la soixantaine, Michael Corleone désire à la fois renouer avec les siens et se réhabiliter aux yeux de la société, surtout de l''Église. Il arrivera presque à ses fins, mais sa vie passée et ses anciens ennemis le rattraperont plus vite. Michael Corleone est fatigué. Il veut prendre ses distances avec les activités mafieuses de sa famille. Il veut convertir ces activités en affaires légales. Kay, son ex-femme, lui fait même accepter que leur fils devienne un chanteur d''opéra et ne reprenne pas les activités familiales. Pendant ce temps, la fille de Michael, Mary, et son neveu, le fils de Sonny, Vincent, nouent une idylle qui n''est pas la bienvenue dans la famille. Il décide d''aider le Vatican à renflouer ses caisses et reçoit en échange le contrôle d''une entreprise immobilière leur appartenant. Attisant la jalousie de ses pairs, Michael échappe de justesse à un attentat commis par l''un d''eux. Vincent se propose alors pour reprendre les affaires de la famille en main.","de":"Der alternde Don Michael Corleone möchte den Familienbetrieb legalisieren und sich langsam aus dem Geschäft zurückziehen. Während er sich als Förderer der katholischen Kirche versucht, macht ihm vor allem ein Mensch zu schaffen: Vincent Mancini, Michaels zukünftiger Schwiegersohn und potentieller Nachfolger. Dieser schmiedet nämlich ganz andere Pläne.","en":"In the midst of trying to legitimize his business dealings in 1979 New York and Italy, aging mafia don, Michael Corleone seeks forgiveness for his sins while taking a young protege under his wing."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/niNFWEtPFgawysw20luHEonC4WI.jpg","es":"https://image.tmdb.org/t/p/w500/l2D8Gzuzw8hN41UthdqM9Osu9I3.jpg","fr":"https://image.tmdb.org/t/p/w500/6qDyBIl9vizY5pneZ2tREaa86UC.jpg","de":"https://image.tmdb.org/t/p/w500/iVjSuqHFFOqCFM4rdhUyysYWnnj.jpg","en":"https://image.tmdb.org/t/p/w500/lm3pQ2QoQ16pextRsmnUbG2onES.jpg"}'::jsonb WHERE id = 8;
UPDATE public.films SET tmdb_id = 87, titoli_i18n = '{"it":"Indiana Jones e il tempio maledetto","en":"Indiana Jones and the Temple of Doom","de":"Indiana Jones und der Tempel des Todes","fr":"Indiana Jones et le Temple maudit","es":"Indiana Jones y el templo maldito"}'::jsonb, trame_i18n = '{"it":"Nel 1935, l''archeologo Indiana Jones sfugge a un agguato della malavita a Shanghai e si ritrova precipitato in India insieme alla cantante Willie Scott e al piccolo Short Round. Raggiunto un povero villaggio oppresso dalla sfortuna, accetta di aiutare gli abitanti a recuperare una pietra sacra Sankara rubata e a liberare tutti i bambini rapiti. La sua missione lo porterà al palazzo di Pankot, nascondiglio della spietata setta dei Thuggee, dedita a sacrifici umani e al culto della dea Kali.","en":"After arriving in India, Indiana Jones is asked by a desperate village to find a mystical stone. He agrees – and stumbles upon a secret cult plotting a terrible plan in the catacombs of an ancient palace.","de":"Indiana Jones kehrt zurück! Nachdem er bei der Erringung eines Diamanten in einem Nachtclub in Shanghai beinahe vergiftet, erdolcht und erschossen wurde, flieht er mit einer halbhysterischen Clubsängerin und seinem jungen asiatischen Freund Short Round mit einem Flugzeug. Doch über Indien wird auch hier ein Mordversuch gegen sie ausgeführt und alle drei müssen abspringen. Sie gelangen in ein Dorf, aus dem heilige Steine und sämtliche Kinder entführt wurden. Die Spur führt zu einem Fürstenpalast im Dschungel, wo sie einem machtgierigen Jungfürsten auf die Spur kommen, der die Kinder in den Minen arbeiten läßt. Doch hinter ihm steht ein noch machtvollerer Sektenführer...","fr":"L''archéologue Indiana Jones est obligé de fuir un cabaret de Shanghai après une négociation houleuse. En compagnie de la chanteuse Willie Scott et du petit Demi-Lune, il se retrouve sur un glacier himalayen, dans un village dont une secte a dérobé le diamant magique et enlevé les enfants afin de les sacrifier.","es":"1935. Shanghai. El intrépido arqueólogo Indiana Jones, tras meterse en jaleos en un local nocturno, consigue escapar junto a una bella cantante y su joven acompañante. Tras un accidentado vuelo, los tres acaban en la India, donde intentarán ayudar a los habitantes de un pequeño poblado, cuyos niños han sido raptados."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/xrLwCgzIcxg8sYr9uuTLdeqtg3Z.jpg","en":"https://image.tmdb.org/t/p/w500/gpdVNUaa4LhRMLfJOPj1AZdhAZ3.jpg","de":"https://image.tmdb.org/t/p/w500/7NBTcdNtaTEYoKRP8VdXRgWO6rk.jpg","fr":"https://image.tmdb.org/t/p/w500/oiUd1KUXWZeDPGMr8TrtZcXzpQU.jpg","es":"https://image.tmdb.org/t/p/w500/tLEaz41vKyKY7AgCTGgijLGWzbk.jpg"}'::jsonb WHERE id = 10;
UPDATE public.films SET tmdb_id = 89, titoli_i18n = '{"es":"Indiana Jones y la última cruzada","it":"Indiana Jones e l''ultima crociata","en":"Indiana Jones and the Last Crusade","fr":"Indiana Jones et la dernière croisade","de":"Indiana Jones und der letzte Kreuzzug"}'::jsonb, trame_i18n = '{"es":"En 1938, dos años después de encontrar el Arca de la Alianza, Indiana Jones es convencido por un millonario para que lo ayude a encontrar el Santo Grial antes de que caiga en manos del ejército nazi. Sin embargo, el verdadero motivo para involucrarse es encontrar a su padre, el doctor Henry Jones, con quien ha mantenido una fría relación desde su juventud y que ha desaparecido mientras seguía la pista del tesoro bíblico.","it":"Nel 1938, l''archeologo Indiana Jones viene contattato dal magnate Walter Donovan per ritrovare il Santo Graal, la coppa che donerebbe la vita eterna. L''incarico assume una valenza personale quando Indy apprende che il precedente capo della spedizione, misteriosamente scomparso, è suo padre, il professor Henry Jones Sr., uno studioso da sempre ossessionato dalla reliquia. Raggiunta Venezia con l''aiuto dell''affascinante dottoressa Elsa Schneider, Indy ritrova il diario del genitore e scopre che l''uomo è tenuto prigioniero dai nazisti in un castello al confine tra Germania e Austria. Dopo aver liberato il padre, padre e figlio fuggono attraverso l''Europa e il Medio Oriente, affrontando tradimenti e letali trappole millenarie all''interno del tempio segreto di Alessandretta per impedire a Hitler di impadronirsi del potere del Graal.","en":"In 1938, an art collector appeals to eminent archaeologist Dr. Indiana Jones to embark on a search for the Holy Grail. Indy learns that a medieval historian has vanished while searching for it, and the missing man is his own father, Dr. Henry Jones Sr.. He sets out to rescue his father by following clues in the old man''s notebook, which his father had mailed to him before he went missing. Indy arrives in Venice, where he enlists the help of a beautiful academic, Dr. Elsa Schneider, along with Marcus Brody and Sallah. Together they must stop the Nazis from recovering the power of eternal life and taking over the world!","fr":"Indiana Jones se lance cette fois‐ci à la recherche du Saint Graal, accompagné de l''éminent et très maladroit Dr Henry Jones, son père. Malheureusement, ils ne sont pas les seuls lancés sur la trace du trésor, les nazis le convoitent également.","de":"Wir schreiben das Jahr 1938: Doktor Jones wird vom Mäzen eines Museums beauftragt, den Heiligen Gral und somit die wichtigste Reliquie der Christenheit zu finden. Jones'' Einwand, es würde der falsche Jones gefragt werden, denn der eigentliche Experte sei sein Vater Henry, fördert nur die Erkenntnis zu Tage, dass Jones senior bereits die Spur aufgenommen hatte, mittlerweile aber verschwunden ist. Nun ist des Doktors Jagdinstinkt geweckt. Besorgt um das Wohlergehen des Vaters und mit dem Museumskurator Marcus Brody im Gepäck tritt Jones eine Reise in die alte Welt an, um das zustande zu bringen, was die mittelalterlichen Kreuzzüge nicht geschafft hatten: den Kelch zu finden, der beim letzten Abendmahl gereicht worden war und das Blut Jesu am Kreuz aufgefangen hatte. Erwartungsgemäß ist aber nicht nur der Doktor auf der Suche - auch die Schergen Hitlers wollen sich die Sagen umwobenen Kräfte des Kelches sichern, verheißt er doch das ewige Leben…"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/5h45gK147AAJpLLC7Cicr597urz.jpg","it":"https://image.tmdb.org/t/p/w500/bPcdsUvGwyeIfyFkzebJdUcw8Fd.jpg","en":"https://image.tmdb.org/t/p/w500/sizg1AU8f8JDZX4QIgE4pjUMBvx.jpg","fr":"https://image.tmdb.org/t/p/w500/73gYk4vShggfajlthEcOsY5ZhQI.jpg","de":"https://image.tmdb.org/t/p/w500/kaAhHlHv2SU7AK5xOMYzsqe2mrr.jpg"}'::jsonb WHERE id = 11;
UPDATE public.films SET tmdb_id = 217, titoli_i18n = '{"it":"Indiana Jones e il regno del teschio di cristallo","en":"Indiana Jones and the Kingdom of the Crystal Skull","de":"Indiana Jones und das Königreich des Kristallschädels","fr":"Indiana Jones et le royaume du crâne de cristal","es":"Indiana Jones y el reino de la calavera de cristal"}'::jsonb, trame_i18n = '{"it":"Nel 1957, in piena Guerra Fredda, l''anziano archeologo Indiana Jones viene rapito insieme al collega George McHale da agenti sovietici guidati dalla spietata Irina Spalko. Costretto ad aiutarli a penetrare in un magazzino segreto nell''Area 51 per recuperare i resti mummificati di un essere extraterrestre, Indy riesce a fuggire. Poco dopo viene avvicinato dal giovane ribelle Mutt Williams, il quale gli chiede aiuto per trovare il professor Harold Oxley e sua madre, misteriosamente rapiti in Perù. I due si mettono sulle tracce di un leggendario teschio di cristallo dai poteri sconosciuti, finendo per scontrarsi nuovamente con i sovietici lungo una pericolosa spedizione nella giungla amazzonica alla volta della mitica città di Akator.","en":"Set during the Cold War, the Soviets—led by sword-wielding Irina Spalko—are in search of a crystal skull which has supernatural powers related to a mystical Lost City of Gold. Indy is coerced to head to Peru at the behest of a young man whose friend—and Indy''s colleague—Professor Oxley has been captured for his knowledge of the skull''s whereabouts.","de":"1957 in der Wüste Nevadas, der Kalte Krieg ist in vollem Gange und Indiana Jones den Russen in die Hände gefallen. Indy gelingt die Flucht, doch die Russen – unter der Führung von Irina Spalko, Stalins Lieblingsagentin und ihres Zeichens Parapsychologin, - entwenden ein mysteriöses Skelett, das offenbar in Verbindung mit dem Verschwinden von Indys altem Freund und Kollegen Harold Oxleys steht, der in Peru verschollen ist. Gemeinsam mit Oxleys Ziehsohn Mutt macht sich Indy im Dschungel des Amazonas auf die Suche nach dem legendären Kristallschädel, dem magische Kräfte nachgesagt werden und der Oxley offenbar in den Wahnsinn getrieben hat. Eine Schatzsuche auf Leben und Tod beginnt.","fr":"La nouvelle aventure d’Indiana Jones débute dans un désert du sud‐ouest des États‐Unis. Nous sommes en 1957, en pleine guerre froide. Indy et son copain Mac viennent tout juste d’échapper à une bande d’agents soviétiques à la recherche d’une mystérieuse relique surgie du fond des temps. De retour au Marshall College, le Professeur Jones apprend une très mauvaise nouvelle : ses récentes activités l’ont rendu suspect aux yeux du gouvernement américain. Le doyen Stanforth, qui est aussi un proche ami, se voit contraint de le licencier. À la sortie de la ville, Indiana fait la connaissance d’un jeune motard rebelle, Mutt, qui lui fait une proposition inattendue.","es":"Indiana Jones y el joven Mutt se proponen encontrar la Calavera de Cristal de Akator. Los agentes soviéticos tienen ese mismo objetivo. Liderados por la bella Irina Spalko, creen que el artilugio ayudará a su país a dominar el mundo si consiguen descifrar su secreto."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qkQf6FVvtRKKk1JQAWTJZDPiy5r.jpg","en":"https://image.tmdb.org/t/p/w500/56As6XEM1flWvprX4LgkPl8ii4K.jpg","de":"https://image.tmdb.org/t/p/w500/2ycEOvqsjdvKqQkybBtLUmcqxLK.jpg","fr":"https://image.tmdb.org/t/p/w500/hwLaM3EaV7QvYhSFHbZ0VpuUY7Y.jpg","es":"https://image.tmdb.org/t/p/w500/caC98g0VyWVztBStLu46rpKlbGw.jpg"}'::jsonb WHERE id = 12;
UPDATE public.films SET tmdb_id = 335977, titoli_i18n = '{"it":"Indiana Jones e il quadrante del destino","fr":"Indiana Jones et le Cadran de la destinée","es":"Indiana Jones y el dial del destino","en":"Indiana Jones and the Dial of Destiny","de":"Indiana Jones und das Rad des Schicksals"}'::jsonb, trame_i18n = '{"it":"Nel 1969, l''archeologo Indiana Jones è ormai prossimo al pensionamento e vive una vita tranquilla. Tutto cambia quando viene visitato dalla sua figlioccia Helena Shaw, che è alla ricerca di un raro e potente manufatto che suo padre aveva affidato a Indy anni prima: il Quadrante di Archimede, un dispositivo capace di individuare fessure temporali. Helena ruba l''oggetto per venderlo al miglior offerente, costringendo Indy a mettersi al suo inseguimento. Nel frattempo, anche Jürgen Voller, un ex scienziato nazista che ora lavora per la NASA, è sulle tracce del Quadrante con l''obiettivo di riscrivere la storia.","fr":"1969. Après avoir passé plus de dix ans à enseigner au Hunter College de New York, l''estimé docteur Jones, professeur d''archéologie, est sur le point de prendre sa retraite et de couler des jours paisibles. Tout bascule après la visite surprise de sa filleule Helena Shaw, qui est à la recherche d''un artefact rare que son père a confié à Indy des années auparavant : le fameux cadran d''Archimède, une relique qui aurait le pouvoir de localiser les fissures temporelles. En arnaqueuse accomplie, Helena vole l’objet et quitte précipitamment le pays afin de le vendre au plus offrant. Indy n''a d''autre choix que de se lancer à sa poursuite. Il ressort son fédora et son blouson de cuir pour une dernière virée...","es":"El arqueólogo Indiana Jones deberá emprender otra aventura contra el tiempo para intentar recuperar un dial legendario que puede cambiar el curso de la historia. Acompañado por su ahijada, Jones pronto se encuentra enfrentándose a Jürgen Voller, un ex nazi que trabaja para la NASA.","en":"Finding himself in a new era, and approaching retirement, Indy wrestles with fitting into a world that seems to have outgrown him. But as the tentacles of an all-too-familiar evil return in the form of an old rival, Indy must don his hat and pick up his whip once more to make sure an ancient and powerful artifact doesn''t fall into the wrong hands.","de":"Indy befindet sich in einer neuen Ära und nähert sich dem Ruhestand. Er ringt damit, sich in eine Welt einzufügen, die über ihn hinausgewachsen zu sein scheint. Doch als die Tentakel eines allzu vertrauten Bösen in Form eines alten Rivalen zurückkehren, muss Indy erneut seinen Hut aufsetzen und seine Peitsche in die Hand nehmen, um sicherzustellen, dass ein uraltes und mächtiges Artefakt nicht in die falschen Hände gerät."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cavpmNgWlOIRENlEscbg1bJ2mX2.jpg","fr":"https://image.tmdb.org/t/p/w500/64TyGedJPmfwfO0dIQWFDLIw1U7.jpg","es":"https://image.tmdb.org/t/p/w500/vb6NkmZbOtdNj4ZbmHwNsiyaHMc.jpg","en":"https://image.tmdb.org/t/p/w500/Af4bXE63pVsb2FtbW8uYIyPBadD.jpg","de":"https://image.tmdb.org/t/p/w500/scZQqSJjHw4mdsz7YfIUvOaRi7O.jpg"}'::jsonb WHERE id = 13;
UPDATE public.films SET tmdb_id = 15014, titoli_i18n = '{"it":"Bianca","es":"Bianca","fr":"Bianca","en":"Bianca","de":"Bianca"}'::jsonb, trame_i18n = '{"it":"Michele Apicella, un giovane e nevrotico professore di matematica con numerose manie ossessive, viene assunto presso l''atipico liceo sperimentale ''Marilyn Monroe''. Michele tende a spiare e giudicare la vita dei suoi vicini e amici, cercando una perfezione ideale nei rapporti umani. Quando inizia una storia d''amore con la nuova collega di francese, Bianca, la sua stabilità mentale viene messa a dura prova. Contemporaneamente, un commissario di polizia indaga su una serie di misteriosi omicidi che colpiscono le persone vicine a Michele.","es":"Michele (Nanni Moretti) es un profesor de matemáticas que acaba de conseguir un nuevo trabajo en un colegio. Tras el asesinato de una mujer en su barrio, Michele conoce a Bianca (Laura Morante), una atractiva compañera de trabajo. (FILMAFFINITY)","fr":"Michele Apicella, professeur de mathématiques, a une curieuse manie : épier de sa terrasse tous ses voisins et les mettre en fiche. Il s''intéresse plus particulièrement à Bianca, adorable professeur de français. Quand une série de meurtres se produit autour de lui, Michele devient le suspect idéal.","en":"Michele, a young mathematics professor, moves into a new flat. Lonely, depressed and neurotic, he spends his time obsessively monitoring the couples around him, especially his neighbors, a young pair struggling to make their relationship work. When Bianca, a new teacher at the local high school, enters his life, Michele finds himself falling in love. At the same time, a string of murders rocks the neighborhood, casting suspicion on him.","de":"Michele ist Mathematikprofessor und hat gerade eine neue Stelle in einer Schule mit einigen eigentümlichen Lehrmethoden angetreten. Nachdem eine Frau in seiner Nachbarschaft ermordet wird, lernt Michele die schöne Kollegin Bianca kennen, und es beginnt eine Beziehung zwischen den beiden. Wohin soll diese Beziehung führen, und wird Michele der Polizei helfen können, den Mörder zu fassen?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg","es":"https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg","fr":"https://image.tmdb.org/t/p/w500/kLp1GFBAy0fFCsP4NXLec8PnEjF.jpg","en":"https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg","de":"https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg"}'::jsonb WHERE id = 14;
UPDATE public.films SET tmdb_id = 11319, titoli_i18n = '{"it":"Le avventure di Bianca e Bernie","es":"Los rescatadores","fr":"Les Aventures de Bernard et Bianca","de":"Bernard & Bianca - Die Mäusepolizei","en":"The Rescuers"}'::jsonb, trame_i18n = '{"it":"All''interno delle Nazioni Unite ha sede la Società Internazionale di Salvataggio, un''organizzazione segreta composta da topi da tutto il mondo incaricata di prestare soccorso a chi ne ha bisogno. Quando viene ritrovato un messaggio in bottiglia inviato da Penny, una bambina orfana rapita, la determinata topina ungherese Bianca si offre volontaria per salvarla e sceglie come compagno di viaggio il timido e superstizioso usciere Bernie. I due scoprono che Penny è stata rapita dalla spietata Madame Medusa, intenzionata a usarla per farsi strada nelle strette cavità sotterranee della Baia del Diavolo e recuperare il diamante più grande del mondo, ''L''Occhio del Diavolo''. Con l''aiuto dell''albatros Orville, della libellula Evinrude e degli stravaganti abitanti della palude, Bianca e Bernie affronteranno alligatori e insidie per liberare la bambina.","es":"Una niña huérfana que ha sido secuestrada envía una nota dentro de una botella pidiendo ayuda. Bernardo y Bianca, dos valientes ratones, miembros de la Sociedad Internacional de Rescate, reciben el mensaje que los llevará al peligroso \"Pantano del Diablo\". Allí, ayudados por la libélula Evinrude y los habitantes del pantano, vivirán un sinfín de emocionantes aventuras luchando contra la malvada Madame Medusa","fr":"Dans les sous‐sols des Nations Unies à New York, un groupe de souris tient conseil. Il s’agit du comité de soutien aux personnes en difficulté. Bianca, déléguée coquette, choisit Bernard tendre souriceau timide et courageux pour voler au secours d’une petite orpheline séquestrée, Penny.","de":"Die Vollwaise Penny wird von der bösen Madame Medusa entführt. Mit Hilfe des Mädchens plant die gierige Alte, in den Besitz des größten Diamanten der Welt zu gelangen. Penny schafft es jedoch, eine Flaschenpost abzuschicken. Als die abenteuerlustige Artgenossin Bianca von dem Hilferuf erfährt, entschließt sie sich, das Kind zu retten. Zusammen mit dem verschmitzten Mäuse-Hausmeister Bernard und dem unbeholfenen Albatros Orville sucht sie Medusas Versteck auf.","en":"Two agents of the mouse-run International Rescue Aid Society search for a little orphan girl kidnapped by sinister treasure hunters."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qf2w4N26UeoS6aXcwtMGRy4zTJU.jpg","es":"https://image.tmdb.org/t/p/w500/4Vi5VEkVWdqJgbG3pGdREFOwZdJ.jpg","fr":"https://image.tmdb.org/t/p/w500/lIlr6NuCZvYO62M6at27cclPSed.jpg","de":"https://image.tmdb.org/t/p/w500/pm501ckgnaNRl3itHGEVjZlOtvL.jpg","en":"https://image.tmdb.org/t/p/w500/9jpDjrRyvv9Nw0piXOpHHQTfxw9.jpg"}'::jsonb WHERE id = 15;
UPDATE public.films SET tmdb_id = 11135, titoli_i18n = '{"it":"Bianca e Bernie nella terra dei canguri","en":"The Rescuers Down Under","es":"Los rescatadores en Cangurolandia","fr":"Bernard et Bianca au pays des kangourous","de":"Bernard & Bianca im Känguruland"}'::jsonb, trame_i18n = '{"it":"Nell''Outback australiano, un ragazzino di nome Cody fa amicizia con Marahute, una gigantesca e rarissima aquila dorata. Quando il crudele bracconiere Percival McLeach lo scopre, rapisce Cody con l''intento di farsi rivelare l''ubicazione del nido dell''animale. La Società Internazionale di Salvataggio allerta immediatamente i due celebri agenti speciali a quattro zampe, Bianca e Bernie. Volando in Australia a bordo dell''albatros Wilbur e affiancati dalla guida locale Jake, un vivace topo saltatore, i due intraprenderanno una rischiosa missione per liberare Cody e salvare Marahute.","en":"A lawless poacher wants to capture a majestic and rare golden eagle, so he kidnaps the boy who knows where to find the bird. Not to worry -- the Rescue Aid Society''s top agents, heroic mice Miss Bianca and Bernard, fly to Australia to save the day. Accompanying the fearless duo are bumbling albatross Wilbur and local field operative Jake the Kangaroo Rat.","es":"Esta vez, nuestros ratoncitos agentes secretos se encuentran en el corazón de la indomable selva australiana cuando tienen que acudir en ayuda de Cody, un jovencito que lucha por salvar un águila de un despiadado cazador furtivo.","fr":"Au cœur imprévisible de l''Australie, Cody, un jeune garçon, développe une amitié incroyable avec un aigle royal. Mais quand un impitoyable braconnier tente de capturer l''aigle, Cody le défend. Comme il ne peut y arriver seul, il demande l''aide des souris les plus braves, Bernard et Bianca. Avec leur hilarant ami Wilbur, ces souris se lancent dans la plus dangereuse des missions.","de":"Bernard und Bianca werden nach Australien beordert, um den Jungen Cody aus den Fängen des üblen Wilderes McLeach und seiner Gefährtin, der Eidechse Joanna zu befreien. Cody, der dem goldenen Adler Marahute aus einer Leach-Falle zur Freiheit verholfen hat, soll dem Bösewicht das Versteck des Adlers und seiner Brut verraten. Mit Hilfe des charmanten Busmaus-Machos Jake - auf deren Avancen gegenüber Bianca der gute Bernard mit stiller Eifersucht reagiert - und dem Albatros Wilbur gelingt es den deiden Mäusepolizisten Cody und die Tiere aus McLeachs Gewalt zu befreien und den Schurken zur Strecke zu bringen. Auch Bernard winkt das Happy End, er darf endlich die geliebte Bianca heiraten."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/awNvQik4yvfEZWOfT13DTpNmyEn.jpg","en":"https://image.tmdb.org/t/p/w500/5koTDBmMAkJOgAe4PL4163UKjvG.jpg","es":"https://image.tmdb.org/t/p/w500/hyuP9jI0Q6bBDEvvsYD8ka27QD0.jpg","fr":"https://image.tmdb.org/t/p/w500/59b4X60bwEYgZ4BfSE56oKqoYBK.jpg","de":"https://image.tmdb.org/t/p/w500/l9JUGkPc3WoNRLaghZUGe6KshTV.jpg"}'::jsonb WHERE id = 16;
UPDATE public.films SET tmdb_id = 182415, titoli_i18n = '{"en":"White as Milk, Red as Blood","es":"Blanca como la nieve, roja como la sangre","fr":"Bianca come il latte, rossa come il sangue","de":"Bianca come il latte, rossa come il sangue","it":"Bianca come il latte, rossa come il sangue"}'::jsonb, trame_i18n = '{"en":"Like all sixteen-year-olds, Leo prefers the company of friends, motorbike rides and music to school. None of the teachers seem to be able to arouse his interest until the arrival in his class of a young history and philosophy substitute who, with his modern methods, helps him see the world with different eyes. In love with Beatrice, the ethereal girl of his dreams, Leo divides the world by colours. Beatrice is the red of love but he is forced to confront his own beliefs and fears when he discovers that the girl is suffering from leukemia, a disease that he links to white, a symbol of emptiness and loss.","es":"Entre mensajes de móvil, deberes, pósters, canciones, partidos, motos, miradas y sonrisas se encuentra Leo, un joven inmerso en el torbellino de la adolescencia. Está enamorado de Beatrice, pero no sabe ni cómo acercarse. Pronto descubrirá que la chica de sus sueños sufre un gran dolor.","fr":"Un adolescent névrosé et incapable d''apprécier les plaisirs de la vie voit son existence bouleversée par sa rencontre avec une jeune fille atteinte d''une grave maladie.","it":"Leo è un sedicenne che vive la scuola e la vita con passione, associando le sue emozioni ai colori: il bianco rappresenta il vuoto e la paura, mentre il rosso è il colore dell''amore e della passione per Beatrice, la ragazza di cui è innamorato. Quando scopre che Beatrice è gravemente malata di leucemia, il mondo di Leo crolla. Nel tentativo di aiutarla e di farla sorridere, il ragazzo intraprende un percorso di crescita personale affrontando la sofferenza, sostenuto dall''amica di sempre Silvia e da un professore di filosofia che lo stimola a trovare il proprio posto nel mondo."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg","es":"https://image.tmdb.org/t/p/w500/cbnB5DQ9kuqCxNw4JmojKwTHyAl.jpg","fr":"https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg","de":"https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg","it":"https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg"}'::jsonb WHERE id = 17;
UPDATE public.films SET tmdb_id = 64032, titoli_i18n = '{"en":"The White Ship","es":"La nave bianca","it":"La nave bianca","fr":"Le Navire blanc","de":"La nave bianca"}'::jsonb, trame_i18n = '{"en":"Although released anonymously, as was the custom with all films produced by the Italian Navy, La Nave Bianca is the first feature-length effort directed by Roberto Rossellini; it is also very much the work of its co-writer and supervisor Francesco De Robertis. The film combines a documentary look at the Italian Navy during World War II with newsreel combat footage and a scripted love story performed by non-professional actors.","it":"Durante la seconda guerra mondiale, un giovane marinaio imbarcato su una nave da guerra italiana rimane ferito all''addome durante uno scontro navale nel Mediterraneo. Dopo essere stato operato d''urgenza a bordo, viene trasferito sulla nave ospedale ''Arno'' (la nave bianca del titolo) per le cure successive. A bordo della nave troverà assistenza e conforto grazie alle cure di un''infermiera volontaria della Croce Rossa, la quale scoprirà essere proprio la ragazza con cui il giovane intratteneva una romantica corrispondenza epistolare senza averla mai incontrata prima.","fr":"La vie à bord d''un navire hôpital de la marine italienne."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg","es":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg","it":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg","fr":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg","de":"https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg"}'::jsonb WHERE id = 18;
UPDATE public.films SET tmdb_id = 16219, titoli_i18n = '{"it":"Gladiator","es":"Gladiator","en":"Gladiator","fr":"Gladiator","de":"Fäuste - Du musst um dein Recht kämpfen"}'::jsonb, trame_i18n = '{"it":"Un giovane di Chicago si trasferisce in un quartiere difficile e si ritrova coinvolto nel giro delle scommesse clandestine di pugilato per saldare i debiti del padre. Per uscire dal tunnel dovrà affrontare sul ring il suo amico più caro e un promotore privo di scrupoli.","es":"Un chico de clase media se traslada a la dura zona sur de Chicago, donde se introducirá como luchador en el mundo ilegal de las peleas de boxeo no autorizadas.","en":"Tommy Riley has moved with his dad to Chicago from a ''nice place''. He keeps to himself, goes to school. However, after a street fight, he''s noticed and quickly falls into the world of illegal underground boxing — where punches can kill.","fr":"Chicago. Pour payer les dettes de son père, Tommy Riley, adolescent secret et doué pour les sports de combat, accepte de participer a des matches de boxe clandestins organises par Horn, ancien boxeur sans scrupule. Ce dernier rêve de faire monter sur le ring un jeune Blanc qui déchainera les passions raciales et l''enrichira un peu plus.","de":"College-Boy Tommy kann ganz schön hinlangen, wenn’s sein muss. Und es muss sein. Schießereien und Überfälle stehen im Viertel an der Tagesordnung. Für Tommy die härteste Schule. Der zwielichtige Box-Promoter Horn erkennt schnell, dass der Junge mit dem ungeheuren Punch bares Geld wert ist. Mr. Horn, “The Power”, zwingt Tommy zu illegalen Fights in den Ring. Der Tod kämpft in jeder Runde mit."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/S708nk4QDy5PU5c4Xc61SXZTzM.jpg","es":"https://image.tmdb.org/t/p/w500/o5333m4CcButz0I7NrxDXlTRB70.jpg","en":"https://image.tmdb.org/t/p/w500/w0YjBWVfu689txEXZG3xa4Aev3i.jpg","fr":"https://image.tmdb.org/t/p/w500/6bGrJkzRZxF8rOWZxX5roE6d89Q.jpg","de":"https://image.tmdb.org/t/p/w500/oPWaj3kqbhBlaQpVsT2dhjM44E3.jpg"}'::jsonb WHERE id = 20;
UPDATE public.films SET tmdb_id = 137548, titoli_i18n = '{"it":"Gladiatori di Roma","es":"Gladiatori di Roma","de":"Die Gladiatoren von Rom","fr":"Gladiateurs de Rome","en":"Gladiators of Rome"}'::jsonb, trame_i18n = '{"it":"Rimasto orfano dopo l''eruzione di Pompei, il piccolo Timo viene adottato dal generale Chirone e cresciuto nell''accademia di gladiatori più famosa di Roma. Senza alcuna passione per il combattimento, dovrà trasformarsi in un vero eroe per conquistare il cuore della bella Lucilla.","es":"Un nuevo héroe nace en este hilarante, aventura animada de proporciones épicas. Timo, un estudiante de la Academia de los Gladiadores ''en Roma, no tiene ningún deseo de convertirse en un gladiador legendario como su ...","de":"Es ist die Zeit des römischen Imperiums. Der junge Timo wurde durch die Zerstörung Pompejis zum Waisenkind, doch der gütige General Chirone adoptiert ihn und bildet ihn an der besten Gladiatorenschule Roms aus. Doch so ganz zum legendären Krieger taugt Timo nicht - im Gegenteil. Er möchte lieber mit seinen Freunden Ciccius und Mauritius rumhängen als sich den Gängelungen und absurden Trainingsmethoden seines Stiefvaters aussetzen. Bis er eines Tages die wundervolle Lucilla trifft und plötzlich sein Kampfgeist geweckt wird. Wird er der größte Gladiator werden, den Rom je gesehen hat?","fr":"Dans la Rome impériale, devenu orphelin suite à la terrible éruption qui a détruit Pompéi, le petit Timo est adopté par le général Chirone et élevé à l’académie des gladiateurs la plus célèbre de Rome. La vie de gladiateur n’est pas du tout faite pour Timo, dont la seule aspiration consiste à se payer du bon temps avec ses amis Ciccius et Mauritius pour échapper aux sessions d’entraînements de son père adoptif. Tout change lorsque Lucilla, la fille de Chirone, revient de Grèce. Désormais, Timo ne souhaite qu’une chose : devenir un valeureux gladiateur dans le but de conquérir le cœur de sa belle amie d’enfance et de convaincre Chirone de l’accepter comme futur gendre…","en":"A new hero is born in this hilarious, animated adventure of epic proportions! Timo, a student at the Gladiators? Academy in Rome, has no desire to become a legendary gladiator like his stepfather. That is, until the mesmerizing Lucilla walks into his life.  With the help of an unlikely band of sidekicks, Timo is determined to be the gladiator of her dreams and embarks on an action-packed journey to become the Colosseum?s first victor!"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/7F35x1EAYjZ4REVBDxGCX4f9ByS.jpg","es":"https://image.tmdb.org/t/p/w500/7F35x1EAYjZ4REVBDxGCX4f9ByS.jpg","de":"https://image.tmdb.org/t/p/w500/wSyJQ5bIcdL6W15whJEgvseYUM3.jpg","fr":"https://image.tmdb.org/t/p/w500/tIOzh5MzmvE6RxKy3rhPbJNnHdL.jpg","en":"https://image.tmdb.org/t/p/w500/9Qyx97TwsPQ1uR82wwQ2dzY0wOU.jpg"}'::jsonb WHERE id = 21;
UPDATE public.films SET tmdb_id = 164728, titoli_i18n = '{"it":"Il gladiatore invincibile","en":"The Invincible Gladiator","de":"Der unbesiegbare Gladiator","es":"Il gladiatore invincibile","fr":"Il gladiatore invincibile"}'::jsonb, trame_i18n = '{"en":"A Roman warrior leads a revolt against an evil ruler. A young, diminutive ruler makes a big decision to unseat a nobleman whose ego has outgrown him. But can the 10-year-old take on such an impressive nemesis?","it":"Il gladiatore Rezius viene inviato in una provincia imperiale per sedare una ribellione, ma scopre che i ribelli stanno lottando contro un tiranno corrotto. Deciderà di schierarsi dalla parte degli oppressi per riportare la giustizia."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/bc8Hy1jtLAAiQ1n8PeiIngxUqlp.jpg","en":"https://image.tmdb.org/t/p/w500/zela8yXh9bWUBab7911vSLb9OGm.jpg","de":"https://image.tmdb.org/t/p/w500/bc8Hy1jtLAAiQ1n8PeiIngxUqlp.jpg","es":"https://image.tmdb.org/t/p/w500/bc8Hy1jtLAAiQ1n8PeiIngxUqlp.jpg","fr":"https://image.tmdb.org/t/p/w500/bc8Hy1jtLAAiQ1n8PeiIngxUqlp.jpg"}'::jsonb WHERE id = 22;
UPDATE public.films SET tmdb_id = 5714, titoli_i18n = '{"it":"Il gladiatore che sfidò l''impero","en":"Challenge of the Gladiator","es":"Il Gladiatore che sfidò l''impero","fr":"Il Gladiatore che sfidò l''impero","de":"Die Rache des Spartakus"}'::jsonb, trame_i18n = '{"it":"Durante l''impero di Marco Aurelio, il corrotto senatore Lucio Quintilio trama per impossessarsi di un leggendario tesoro e usurpare il potere. A contrastare i suoi piani diabolici si erge il valoroso gladiatore Marco che, alleatosi con i ribelli e i fedeli all''imperatore, affronterà duri scontri e insidie nell''arena per ristabilire la giustizia e salvare l''impero.","en":"Treacherous Roman senator Lucius Quintilius plans a secret journey into Thrace to recover a legendary treasure. He is accompanied by his daughter Livia posing as a Christian slave girl, his cruel henchman Commodio, and Terenzius, an ex-gladiator and Nero look-alike who fools the local Thracians into believing he is the real Emperor. But Lucius''s plans are thwarted by Spartacus and his band of rebels who succeed in capturing the treasure for Thrace. When news arrives from Rome that the real Nero has died, local Roman governor Consul Metellus joins forces with Spartacus to defeat the traitors.","de":"Unter dem Pseudonym Rock Stevens rettet Peter Lupus als muskelstrotzender Thraker Spartacus sein Volk vor der Vernichtung und befreit die Römer von einem verräterischen Tyrannen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8h2SzRMQhza5IVQCIv30nLIyXEV.jpg","en":"https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg","es":"https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg","fr":"https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg","de":"https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg"}'::jsonb WHERE id = 23;
UPDATE public.films SET tmdb_id = 93492, titoli_i18n = '{"it":"I sette gladiatori","es":"Los siete espartanos","fr":"I sette gladiatori","en":"Gladiators 7","de":"Die sieben Gladiatoren"}'::jsonb, trame_i18n = '{"it":"Marcus, un valoroso gladiatore, fugge da Roma per fare ritorno a Sparta, la sua terra natale. Al suo arrivo scopre che il suo popolo è sottomesso alla tirannia di un governatore spietato. Per liberare la sua gente, Marcus decide di reclutare altri sei abili e forti gladiatori, unendo le forze per guidare una rivolta contro l''oppressore.","es":"Darío regresa a Esparta después de haber alcanzado la libertad por su valentía en una lucha, como gladiador en el circo romano. Al llegar a Esparta descubre que su padre ha sido asesinado por Hiarbaa. Este quiere asesinar también a Darío para afianzarse en el poder y casarse con Aglaia, prometida de Darío e hija de Milone... (FILMAFFINITY)","en":"Framed for the escape of five gladiators from the arena, the son of one of Sparta''s leading citizens is sentenced to the arena as gladiator himself and forced to fight for his life in the Roman Colosseum. Years later he manages to escape and return to Sparta, only to find out that his father has been murdered--even though it was ruled a \"suicide\"--and the woman he loves is about to marry the evil king who has usurped the throne. He sets out to find six of his fellow gladiators and return to Sparta to save his woman and place the rightful king on the throne.","de":"Als der Spartaner Darius chancenlos in der Arena kämpft, bricht er blutüberströmt zusammen. Doch der Kaiser schenkt ihm trotzdem die Freiheit und Darius kehrt in seine Heimat zurück, wo er auch schon von einem weiteren Märtyrer erwartet wird, der ihn töten möchte. Darius bildet eine Gruppe von sieben Gladiatoren, um den Tyrannen Hierba zu stoppen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kKdn10PWQKCpVgE5w01yg24wnQo.jpg","es":"https://image.tmdb.org/t/p/w500/2h3DwYZOXIjKgXxYpQnULwPMCAY.jpg","fr":"https://image.tmdb.org/t/p/w500/kKdn10PWQKCpVgE5w01yg24wnQo.jpg","en":"https://image.tmdb.org/t/p/w500/jAQg4h3AhSgOH3jLRlcRCzagFXW.jpg","de":"https://image.tmdb.org/t/p/w500/u9JTB147rHHC4IOjyr0GkF1tU31.jpg"}'::jsonb WHERE id = 24;
UPDATE public.films SET tmdb_id = 134998, titoli_i18n = '{"en":"Messalina Against the Son of Hercules","it":"L''ultimo gladiatore","es":"El último gladiador","de":"Der letzte der Gladiatoren","fr":"Hercule contre les mercenaires"}'::jsonb, trame_i18n = '{"en":"While fighting in Britain, Roman forces commanded by Caligula capture the noble warrior, Glaucus. Seeing in him gladiator material, Caligula takes Glaucus back to Rome along with other hostages including Glaucus''s girlfriend, Ena. A man seeking to restore the Roman Republic then assassinates Caligula after which Claudius is proclaimed emperor. Messalina -- Claudius''s beautiful but evil wife -- then maneuvers to replace Claudius with her lover, Silio. She forces Glaucus to help her in this quest by threatening to harm the enslaved Ena.  Written by dinky-4 of Minneapolis","it":"Nell''antica Roma, oppressa dalla follia e dal dispotismo dell''imperatore Caligola, il valoroso gladiatore Cassio Cherone decide di ribellarsi alla tirannia. Coinvolto negli intrighi di palazzo e nelle congiure senatorie, Cassio affronta pericoli nell''arena e scontri mortali, lottando per rovesciare il sovrano crudele, proteggere la donna che ama e restituire dignità e pace al popolo romano.","es":"Roma, año 41 DC. El emperador Calígula (Charles Borromel) conquista Bretaña y hace esclavo al bárbaro Glauco (Richard Harrison), llevándole a la capital con la intención de verle morir en la arena frente a los gladiadores. El bretón resulta ser un guerrero excepcional que conseguirá acabar con todos y escapar, liberando también a sus compañeros de encierro. Pero las aventuras de Glauco no han hecho más que empezar; aún tendrá que afrontar muchos combates antes de poder liberar a su mujer, Hena (Marilú Tolo) y volver a Bretaña.","de":"Caligula, der wahnsinnige römische Imperator, führt einen sinnlosen Krieg gegen Britannien. Glaucus, ein britischer Sklave, kämpft derart beeindruckend, dass er bald unbesiegter Gladiator der römischen Arenen wird. Als er jedoch Caligula töten will, lässt dieser ihn in den Kerker werfen. Die intrigante Messalina sieht nun ihre Chance, den heldenhaften Briten einzusetzen, den Herrscher vom Thron zu stürzen.","fr":"L''ambitieuse Messaline souhaite plus que tout le pouvoir. Pour parvenir à ses fins, elle demande l''aide d''Hercule, un esclave d''une incroyable force. Mais celui-ci refuse. Pour obliger Hercule a accepter son offre, Messaline fait emprisonner Ena, sa fiancée..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg","it":"https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg","es":"https://image.tmdb.org/t/p/w500/rILHj2xmI19KeKw6GexyXM9981m.jpg","de":"https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg","fr":"https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg"}'::jsonb WHERE id = 25;
UPDATE public.films SET tmdb_id = 211179, titoli_i18n = '{"it":"Il magnifico gladiatore","en":"The Magnificent Gladiator","es":"Il magnifico gladiatore","fr":"Le gladiateur magnifique","de":"Der größte der Gladiatoren"}'::jsonb, trame_i18n = '{"it":"Attalo, gladiatore da tutti stimato, si trova vittima degli intrighi di palazzo dell''imperatore Gallieno. Dovrà far valere il suo valore sia nell''arena che contro i cospiratori politicamente corrotti.","en":"Attalus, a war prisoner by Rome, proves his valor in the arena, becomes a gladiator trainer, conquers the women''s hearts and the men''s envy, and saves Rome from a political plot to a usurper to occupy the throne.","fr":"Hercule, fils du roi de Dacie, se fiance a Velida, fille de l''empereur Galien Zudo qui veut le trône enlève l''empereur et le remplace par un sosie qui annule le mariage et fiance Velida avec Zudo. Hercule découvre la vérité et délivre l''empereur. Zudo est tue. Hercule peut alors épouser Velida avec la bénédiction de l''empereur.","de":"Als die römischen Truppen unter Cesar Galienius (Franco Cobianchi) Dacien erobern, fällt dem Imperator auch Attalus (Mark Forest), der Prinz von Dacien in die Hände. Dessen großes Talent zum Kämpfen bleibt Galienius nicht verborgen so dass er ihn zum Gladiator ausbilden lässt. Durch seinen Mut in der Arena gewinnt Attalus nicht nur schnell an Popularität beim römischen Volk, sondern auch das Herz von Valida, der jungen Tochter des Imperators. Die aufkeimende Liebe der beiden wird aber nicht von jedem kommentarlos hingenommen. Der Oberbefehlshaber der Truppen Zullo (Paolo Gozlino) hat nämlich schon lange ein Auge auf die römische Jungfer geworfen, und spinnt ein Komplott, dass ihm nicht nur Attalus vom Hals schaffen und Valida in seine Arme treiben, sondern auch die Macht des Imperators sichern soll."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ePP3X8YRlXaQm5ERlX2W5o0rX0Z.jpg","en":"https://image.tmdb.org/t/p/w500/7iJtohz1AiSKaV8uOp23smvnO3J.jpg","es":"https://image.tmdb.org/t/p/w500/ePP3X8YRlXaQm5ERlX2W5o0rX0Z.jpg","fr":"https://image.tmdb.org/t/p/w500/ePP3X8YRlXaQm5ERlX2W5o0rX0Z.jpg","de":"https://image.tmdb.org/t/p/w500/ePP3X8YRlXaQm5ERlX2W5o0rX0Z.jpg"}'::jsonb WHERE id = 26;
UPDATE public.films SET tmdb_id = 238033, titoli_i18n = '{"en":"Spartacus and the Ten Gladiators","es":"Espartaco y los diez gladiadores","it":"Spartacus e i 10 gladiatori","fr":"Spartacus et les dix Gladiateurs","de":"Spartacus und die zehn Gladiatoren"}'::jsonb, trame_i18n = '{"en":"The story of Spartacus and 10 other gladiators who rebelled against the bloody coliseum sports. They escape and are faced at every turn by Roman soldiers bent on taking them back to the Coliseum - dead or alive!","es":"Espartaco es un esclavo noble y honrado, a quien los patricios obligan a luchar en brutales peleas de gladiadores. Un buen día decide poner fin a esta injusticia y lidera una rebelión que, por un momento, consigue poner en jaque la paz interior del Imperio Romano.","it":"Dieci gladiatori inviati per dare la caccia al ribelle Spartacus scoprono la nobiltà della sua causa. Decideranno di unire le forze con gli schiavi in rivolta contro le legioni romane.","fr":"Pour construire un aqueduc, le sénateur romain Varron engage dix gladiateurs. En chemin, ils portent secours à la fille de Varron qui est attaquée par une bande de coupe-jarrets. Devant cet exploit, Varron leur propose de capturer Spartacus, chef des esclaves révoltés, en échange de la liberté…","de":"Einen Überfall auf eine Reisegruppe können die zehn Gladiatoren gerade noch verhindern. Auch das Leben von Livia, der hübschen Tochter des römischen Senators Varro, ist gerettet. Der beeindruckte Senator beauftragt daraufhin die zehn Gladiatoren, den berüchtigten Rebellen Spartacus und seine Bande gefangen zu nehmen. Doch hinter diesem Auftrag verbirgt sich ein finsterer Plan. Er lässt die Gladiatoren in die Verliese seines Palastes sperren, um einen feigen Überfall auf das Lager verüben zu können. Dies ist für Spartacus und die zehn Gladiatoren das Signal zum großen Aufstand."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/gZsGyRcXRCICiSlnBfyH5SecIad.jpg","es":"https://image.tmdb.org/t/p/w500/a7IdTHSJ0aIsqBIHX1V6jIYmYQB.jpg","it":"https://image.tmdb.org/t/p/w500/gZsGyRcXRCICiSlnBfyH5SecIad.jpg","fr":"https://image.tmdb.org/t/p/w500/3nVbJy4v2sJXpk63SaN0vNUO2En.jpg","de":"https://image.tmdb.org/t/p/w500/bFPGWSo1FRa5v4M1gJ3Ur95conX.jpg"}'::jsonb WHERE id = 27;
UPDATE public.films SET tmdb_id = 158093, titoli_i18n = '{"es":"El retorno de Maciste","it":"Il gladiatore di Roma","en":"Gladiator of Rome","de":"Der Gladiator von Rom","fr":"Il gladiatore di Roma"}'::jsonb, trame_i18n = '{"es":"Una princesa silesiana cuya familia ha sido cruelmente asesinada, es vendida como esclava por los romanos. Lo mismo ocurre con su sirviente Marcus, quien recibe la formación de un gladiador.","it":"Nell''antica Roma sotto Caracalla, la giovane erede al trono di Cilicia viene protetta da uno schiavo gladiatore che difenderà la sua vita dai traditori e dai pretendenti al trono.","en":"A warrior protecting a slave girl, who is really a princess, winds up as a gladiator in the Roman arenas.","de":"Die schöne Nisa ist die Sklavin einer reichen römischen Familie. Sie ist in Wirklichkeit eine Königstochter und wird von Marcus, einem übermenschlich starken Mann, beschützt. Valerius, der Sohn der Familie, ist in Nisa verliebt und möchte sie heiraten. Durch einen heimtückischen Angriff auf das Haus seiner Eltern werden Marcus und Nisa entführt. Marcus soll als Gladiator in der Arena Roms kämpfen und Nisa soll als Christin zum Tode verurteilt werden. Valerius versucht alles, um sie zu befreien. Marcus steht ihm bei, nachdem er seine Fesseln gesprengt hat und mit den anderen Gladiatoren geflohen ist."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/smcfYvcMixH12ZlMM3M9RG7q50l.jpg","it":"https://image.tmdb.org/t/p/w500/smcfYvcMixH12ZlMM3M9RG7q50l.jpg","en":"https://image.tmdb.org/t/p/w500/bnYYCgn7hBtV6Xq4PF8GttGMvI3.jpg","de":"https://image.tmdb.org/t/p/w500/ovxKFqNMOoSJoZ6APUM6bEvvzjN.jpg","fr":"https://image.tmdb.org/t/p/w500/smcfYvcMixH12ZlMM3M9RG7q50l.jpg"}'::jsonb WHERE id = 28;
UPDATE public.films SET tmdb_id = 329964, titoli_i18n = '{"it":"Ursus il gladiatore ribelle","fr":"Ursus, il gladiatore ribelle","es":"Ursus, il gladiatore ribelle","en":"The Rebel Gladiators","de":"Kampf der Giganten"}'::jsonb, trame_i18n = '{"it":"Ursus accetta di combattere come gladiatore per salvare la vita della donna che ama, prigioniera di un governatore crudele. La sua forza sovrumana scatenerà una rivolta nell''arena.","en":"In order to persuade the Emperor to spare his village, the mighty Ursus is forced to fight the greatest gladiator in Rome in the Roman Arena."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg","fr":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg","es":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg","en":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg","de":"https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg"}'::jsonb WHERE id = 29;
UPDATE public.films SET tmdb_id = 169925, titoli_i18n = '{"es":"La carga de los jinetes indios","it":"L''indiana bianca","de":"Der brennende Pfeil","en":"The Charge at Feather River","fr":"La Charge sur la rivière rouge"}'::jsonb, trame_i18n = '{"es":"Una expedición de rescate, formada por hombres inexpertos, debe liberar a dos mujeres blancas que han sido secuestradas por los indios cheyenne. (FILMAFFINITY)","de":"Der Ex-Offizier Miles Archer (Guy Madison) soll mit einer zusammengewürfelten Gruppe von Männern zwei Schwestern aus den Händen der Cheyenne befreien. Zwar glückt die Aktion,\r doch die Indianer verfolgen den Trupp. Weitere Schwierigkeiten ergeben sich, als die jüngere (Vera Miles) der Schwestern, wieder zurück zu den Indianern will...","en":"A frontier scout leads prisoners on a death mission to save a railroad and rescue two women.","fr":"Sur le territoire du Colorado, Miles Archer est demandé par la cavalerie à Fort Soufflet pour aider à sauver deux femmes blanches enlevés par le Cheyenne et à assurer la sécurité pour les équipes de construction de chemin de fer.","it":"Nel selvaggio West, Sharon Purcell, una giovane donna per metà bianca e per metà nativa americana, vive al confine tra le due culture affrontando il disprezzo e il pregiudizio di entrambe le comunità. La situazione degenera quando un potente e avido proprietario terriero tenta con ogni mezzo di sottrarre le terre alla tribù indiana locale per espandere il proprio dominio. In mezzo alle crescenti tensioni e allo scoppio delle ostilità, Sharon cercherà disperatamente di favorire la convivenza pacifica, aiutata da un coraggioso funzionario governativo determinato a ristabilire la giustizia e a far rispettare i trattati."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/8A87PHLaDCEyeqTVBzHhQJ6R22p.jpg","it":"https://image.tmdb.org/t/p/w500/awt4WEDwcKuTw4oaiLwzfh7xnt7.jpg","de":"https://image.tmdb.org/t/p/w500/leM8HYHS8exQzmMVzoSa4Z4oIts.jpg","en":"https://image.tmdb.org/t/p/w500/awt4WEDwcKuTw4oaiLwzfh7xnt7.jpg","fr":"https://image.tmdb.org/t/p/w500/j1PTX1nMkaKnIMMPnPKOLUiFZMR.jpg"}'::jsonb WHERE id = 30;
UPDATE public.films SET tmdb_id = 85, titoli_i18n = '{"en":"Raiders of the Lost Ark","it":"Indiana Jones e i predatori dell''arca perduta","fr":"Les Aventuriers de l''arche perdue","es":"En busca del arca perdida","de":"Jäger des verlorenen Schatzes"}'::jsonb, trame_i18n = '{"en":"When Dr. Indiana Jones – the tweed-suited professor who just happens to be a celebrated archaeologist – is hired by the government to locate the legendary Ark of the Covenant, he finds himself up against the entire Nazi regime.","it":"Nel 1936, l''archeologo e avventuriero Indiana Jones viene incaricato dai servizi segreti dell''esercito statunitense di trovare la leggendaria Arca dell''Alleanza, lo scrigno sacro contenente i Dieci Comandamenti, prima che cada nelle mani delle forze naziste di Adolf Hitler, intenzionate a sfruttarne il presunto potere sovrannaturale per dominare il mondo. Affiancato dalla sua fiera ex compagna Marion Ravenwood e dal fidato amico Sallah, Jones affronta una pericolosa caccia al tesoro tra le montagne del Nepal e le sabbie dell''Egitto, sfidando trappole mortali e il suo rivale senza scrupoli, l''archeologo francese René Belloq.","fr":"L''Arche d''Alliance contenant les tables de la Loi brisées par Moïse, voici 3.000 ans, est l''objet de la convoitise des nazis. L''archéologue aventurier Indiana Jones se lance à sa recherche, poursuivi par son ennemi Belloq.","es":"Año 1936, Indiana Jones es un profesor de arqueología, dispuesto a correr peligrosas aventuras con tal de conseguir valiosas reliquias históricas. Después de una infructuosa misión en Sudamérica, el gobierno estadounidense le encarga la búsqueda del Arca de la Alianza, donde se conservan las Tablas de la Ley que Dios entregó a Moisés. Según la leyenda, quien las posea tendrá un poder absoluto, razón por la cual también la buscan los nazis.","de":"Der Archäologe Dr. Henry Jones wird von Regierungsagenten auf die Bundeslade angesetzt, das Behältnis, in dem Moses Gesetzestafeln aufbewahrt wurden. Laut Geheiminformationen suchen auch die Nazis nach der Lade, da sie den Besitzer unbesiegbar machen soll. Jones, genannt Indiana Jones, reist daraufhin nach Nepal, wo er einen alten Kollegen aufspüren will, jedoch nur dessen Tochter findet, die sich ihm anschließt. Ein altes Schmuckstück führt sie nach Ägypten, wo die Nazis mit Belloqs Hilfe bereits Ausgrabungen vornehmen. So kommt es zum Wettlauf um die Auffindung der Quelle der Seelen…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/ceG9VzoRAVGwivFU403Wc3AHRys.jpg","it":"https://image.tmdb.org/t/p/w500/g7brmwhpIPZoRLlHSU9sDbyGW3D.jpg","fr":"https://image.tmdb.org/t/p/w500/by5xmwAUVzXc3WyIyjMYCVaL5Lj.jpg","es":"https://image.tmdb.org/t/p/w500/tECLVwLCMexSkls33RTCwedRZ6d.jpg","de":"https://image.tmdb.org/t/p/w500/8cWx3s2Wfo15DzUyIE8scg3eNdb.jpg"}'::jsonb WHERE id = 31;
UPDATE public.films SET tmdb_id = 558449, titoli_i18n = '{"it":"Il gladiatore II","en":"Gladiator II","es":"Gladiator II","fr":"Gladiator II","de":"Gladiator II"}'::jsonb, trame_i18n = '{"it":"Anni dopo aver assistito alla tragica morte del venerato eroe Massimo Decimo Meridio per mano del suo perfido zio, Lucio si ritrova costretto a fare il suo ingresso nel Colosseo. La sua patria è stata infatti conquistata dai tirannici imperatori che ora governano Roma con il pugno di ferro. Con la rabbia nel cuore e il destino dell''Impero in bilico, Lucio deve scavare nel proprio passato per trovare la forza e l''orgoglio necessari a restituire la gloria di Roma al suo popolo.","en":"Years after witnessing the death of the revered hero Maximus at the hands of his uncle, Lucius is forced to enter the Colosseum after his home is conquered by the tyrannical Emperors who now lead Rome with an iron fist. With rage in his heart and the future of the Empire at stake, Lucius must look to his past to find strength and honor to return the glory of Rome to its people.","es":"Dieciséis años después de la muerte de Marco Aurelio, Roma está gobernada por los despiadados emperadores gemelos Geta y Caracalla. El nieto de Aurelio, Lucio Vero, vive bajo el seudónimo de Hanno con su esposa Arishat en el reino norteafricano de Numidia. El ejército romano dirigido por el general Acacio invade y conquista el reino, esclavizando a Lucio junto con otros supervivientes. Los esclavos son llevados a Ostia, donde Lucio es comprado por el maestro de cuadra Macrinus, que le promete la oportunidad de vengarse matando a Acacio si gana suficientes combates para llegar al Coliseo.","fr":"Des années après avoir assisté à la mort du héros vénéré Maximus aux mains de son oncle, Lucius est forcé d''entrer dans le Colisée lorsque son pays est conquis par les empereurs tyranniques qui gouvernent désormais Rome d''une main de fer. La rage au cœur et l''avenir de l''Empire en jeu, Lucius doit se tourner vers son passé pour trouver la force et l''honneur de rendre la gloire de Rome à son peuple.","de":"Jahre nachdem er Zeuge des Todes des verehrten Helden Maximus durch die Hand seines Onkels wurde, wird Lucius gezwungen, das Kolosseum zu betreten, nachdem seine Heimat von den tyrannischen Kaisern erobert wurde, die Rom nun mit eiserner Faust regieren. Mit Wut in seinem Herzen und der Zukunft des Imperiums auf dem Spiel muss Lucius in seine Vergangenheit blicken, um Kraft und Ehre zu finden, um den Ruhm Roms an sein Volk zurückzugeben."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tVBCG6qHQQaq2doZsOvpGNcwMuP.jpg","en":"https://image.tmdb.org/t/p/w500/2cxhvwyEwRlysAmRH4iodkvo0z5.jpg","es":"https://image.tmdb.org/t/p/w500/ckTXrwlr4cRVxpBFEZcEmDzrmea.jpg","fr":"https://image.tmdb.org/t/p/w500/sUnGXbEdXlgHlK3EkmB5w2NiLlc.jpg","de":"https://image.tmdb.org/t/p/w500/kLkMt9bB7XDzwQ5wy6OWtdpwgcD.jpg"}'::jsonb WHERE id = 32;
UPDATE public.films SET tmdb_id = 120, titoli_i18n = '{"it":"Il Signore degli Anelli - La Compagnia dell''Anello","en":"The Lord of the Rings: The Fellowship of the Ring","fr":"Le Seigneur des anneaux : La Communauté de l''anneau","es":"El señor de los anillos: La comunidad del anillo","de":"Der Herr der Ringe - Die Gefährten"}'::jsonb, trame_i18n = '{"it":"Un giovane hobbit di nome Frodo Baggins eredita un anello magico di inestimabile potere dal suo zio Bilbo. Per evitare che il Signore Oscuro Sauron lo riconquisti e sottometta la Terra di Mezzo, Frodo deve intraprendere un periglioso viaggio verso il Monte Fato insieme a una variegata compagnia di eroi.","en":"Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.","fr":"Le jeune hobbit Frodon Sacquet hérite d''un anneau. Il s''agit de l''Anneau Unique, instrument de pouvoir absolu qui permettrait à Sauron, de régner sur la Terre du Milieu et de réduire en esclavage ses peuples… À moins que Frodon et ses fidèles compagnons ne parviennent à emporter l''Anneau jusqu''en Mordor, lieu où il a été forgé, et à le détruire pour toujours…","es":"En la Tierra Media, el Señor Oscuro Saurón creó los Grandes Anillos de Poder, forjados por los herreros Elfos. Tres para los reyes Elfos, siete para los Señores Enanos, y nueve para los Hombres Mortales. Secretamente, Saurón también forjó un anillo maestro, el Anillo Único, que contiene en sí el poder para esclavizar a toda la Tierra Media. Con la ayuda de un grupo de amigos y de valientes aliados, Frodo emprende un peligroso viaje con la misión de destruir el Anillo Único. Pero el Señor Oscuro Sauron, quien creara el Anillo, envía a sus servidores para perseguir al grupo. Si Sauron lograra recuperar el Anillo, sería el final de la Tierra Media.","de":"Dem Hobbit Bilbo Beutlin fällt zufällig ein machtvoller Ring in die kleinen Hände. Dieses Schmuckstück erlaubte es dem finsteren Herrscher Sauron einst, die Welt zu unterjochen. Der Ring schien über Jahrhunderte verloren, bis Bilbo ihn an sich nahm und seinen „Schatz“ sechzig Jahre lang bewahrte. An seinem 111. Geburtstag gibt er ihn schweren Herzens an seinen Neffen Frodo weiter und verlässt seine Heimat Mittelerde. Für den jungen Hobbit Frodo wird der Ring jedoch zur schweren Bürde. Der böse Geist Saurons, der in dem „Einen“ gefangen ist, wird immer stärker. Frodo bleibt nur eine Möglichkeit: Er muss ihn vernichten. Allerdings ist das nicht gerade einfach. Nur in den ewigen Feuern des Schicksalsberges im Lande Mordor, wo der Ring geschmiedet wurde, kann er auch vernichtet werden. Doch bis dahin muss Frodo an der Seite des Zauberers Gandalf und seiner Gefährten durch Feindesland ziehen, immer verfolgt von Saurons Lakaien …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/iZTDPQYgr3rhL7hPIYFt17ATp8.jpg","en":"https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg","fr":"https://image.tmdb.org/t/p/w500/5OPg6M0yHr21Ovs1fni2H1xpKuF.jpg","es":"https://image.tmdb.org/t/p/w500/9xtH1RmAzQ0rrMBNUMXstb2s3er.jpg","de":"https://image.tmdb.org/t/p/w500/k6lw7hhaMDzJ170bfZfBbnipxcW.jpg"}'::jsonb WHERE id = 33;
UPDATE public.films SET tmdb_id = 121, titoli_i18n = '{"it":"Il Signore degli Anelli - Le due torri","es":"El señor de los anillos: Las dos torres","en":"The Lord of the Rings: The Two Towers","fr":"Le Seigneur des anneaux : Les Deux Tours","de":"Der Herr der Ringe - Die zwei Türme"}'::jsonb, trame_i18n = '{"it":"La Compagnia si è divisa: Frodo e Sam proseguono verso Mordor guidati dalla subdola creatura Gollum, mentre Aragorn, Legolas e Gimli accorrono in aiuto del regno di Rohan. Insieme dovranno affrontare le schiere oscure di Saruman nella leggendaria battaglia del Fosso di Helm.","es":"La Compañía del Anillo se ha disuelto. El portador del anillo Frodo y su fiel amigo Sam se dirigen hacia Mordor para destruir el Anillo Único y acabar con el poder de Sauron. Mientras, y tras la dura batalla contra los orcos donde cayó Boromir, el hombre Aragorn, el elfo Legolas y el enano Gimli intentan rescatar a los medianos Merry y Pipin, secuestrados por los ogros de Mordor. Por su parte, Saurón y el traidor Sarumán continúan con sus planes en Mordor, en espera de la guerra contra las razas libres de la Tierra Media.","en":"Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers - Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron''s fortress at Barad-dur, deep within the dark lands of Mordor.","fr":"La Communauté est dissoute, mais la quête pour détruire l''Anneau Unique se poursuit. Accompagné par son fidèle Sam et guidé par l''étrange Gollum, Frodon cherche un moyen d''entrer en Mordor. Alors que l''armée de Saroumane se met en marche, les autres compagnons de la Communauté se préparent à la bataille. La Guerre de l''Anneau a commencé !","de":"Der Weg der Gefährten hat sich geteilt. Ringträger Frodo und sein treuer Begleiter Sam treffen in den Bergen von Emyn Muil auf Gollum, dem einst Bilbo Beutlin den Einen Ring wegnahm. Gollums Versuch, den mächtigen Ring von Frodo zu stehlen, misslingt, doch die Hobbits bringen es nicht übers Herz, die Kreatur zu töten. Stattdessen soll Gollum die beiden nach Mordor an die Pforten von Barad-Dûr, Saurons Festung, führen, wo Frodo den Ring vernichten will. Währenddessen folgen Aragorn, Elben-Bogenschütze Legolas und Zwerg Gimli den Spuren der von Orks verschleppten Hobbits. Im Menschenkönigreich Rohan ersuchen sie Unterstützung. Doch König Theoden steht unter einem tödlichen Bann Saurons. Erst als Gandalf als wiedergeborener weißer Zauberer zurückkehrt, wendet sich das Blatt. Er befreit Theoden von dem Fluch und bringt die Menschen von Rohan hinter sich. Unterdessen rückt Saurons Verbündeter Saruman mit einer 10.000 Mann starken Armee von Uruk-hais in RIchtung der Menschenstadt vor..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jIhivyKlNwLmFJ2W6X98vh2XFwu.jpg","es":"https://image.tmdb.org/t/p/w500/up6gIHZlfEQZkHIfQwcOOaGOzOt.jpg","en":"https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg","fr":"https://image.tmdb.org/t/p/w500/qVHBqQYLDRs7ESjP9q6o9iPHLWj.jpg","de":"https://image.tmdb.org/t/p/w500/tgBCeAjPwXeUaf8LsRL0LzBIcdR.jpg"}'::jsonb WHERE id = 34;
UPDATE public.films SET tmdb_id = 122, titoli_i18n = '{"it":"Il Signore degli Anelli - Il ritorno del re","fr":"Le Seigneur des anneaux : Le Retour du roi","es":"El señor de los anillos: El retorno del rey","en":"The Lord of the Rings: The Return of the King","de":"Der Herr der Ringe - Die Rückkehr des Königs"}'::jsonb, trame_i18n = '{"it":"L''epico scontro finale per la salvaguardia della Terra di Mezzo ha inizio. Mentre Aragorn reclami il suo trono e conduce l''esercito dei popoli liberi ai Cancelli Nero per distrarre le armate oscure, Frodo e Sam affrontano il massacrante tratto finale del viaggio verso il Monte Fato.","fr":"La bataille pour la Terre du Milieu a commencé. Frodon et Sam, guidés par Gollum, poursuivent leur mission à travers les terres du Mordor pour détruire l''Anneau Unique. Tandis que le pouvoir de Sauron grandit, Aragorn, l''héritier du trône du Gondor, rassemble l''armée des Hommes contre les forces du Mal, afin de laisser une chance au porteur de l''Anneau d''accomplir sa quête…","es":"Las fuerzas de Saruman han sido destruidas, y su fortaleza sitiada. Ha llegado el momento de que se decida el destino de la Tierra Media, y por primera vez en mucho tiempo, parece que hay una pequeña esperanza. La atención del señor oscuro Sauron se centra ahora en Gondor, el último reducto de los hombres, y del cual Aragorn tendrá que reclamar el trono para ocupar su puesto de rey. Pero las fuerzas de Sauron ya se preparan para lanzar el último y definitivo ataque contra el reino de Gondor, la batalla que decidirá el destino de todos. Mientras tanto, Frodo y Sam continuan su camino hacia Mordor, a la espera de que Sauron no repare en que dos pequeños Hobbits se acercan cada día más al final de su camino, el Monte del Destino.","en":"As armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.​","de":"Saurons Heer will Minas Tirith angreifen, die in Felsen errichtete Hauptstadt von Gondor. Angesichts der Bedrohlichkeit des feindlichen Heeres wiegt es umso schwerer, dass Gondors König fehlt und nur der schwächliche Truchsess Denethor über das einst mächtige Königreich wacht. Wird Aragorn die Kraft aufbringen, jene Aufgabe zu übernehmen, für die sein Schicksal ihn bestimmt hat? Während Gandalf verzweifelt versucht, die mutlosen Kämpfer von Gondor zu motivieren, sammelt Théoden die Krieger von Rohan, um am Kampf teilzunehmen. Aber obwohl sie tapfer und leidenschaftlich Widerstand leisten, haben die Streitkräfte der Menschen dem überwältigenden Ansturm der feindlichen Legionen gegen das Königreich kaum etwas entgegenzusetzen. Jeder Sieg fordert große Opfer. Trotz der starken Verluste stellen sich die Gefährten der größten Schlacht ihres Lebens - vereint durch ein einziges Ziel: Sauron muss so lange abgelenkt werden, bis Frodo den Ring vernichtet hat..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/eCua9No8HqVxGajDQrG8mvRCtJM.jpg","fr":"https://image.tmdb.org/t/p/w500/ypUCFOvOf07bcHy81jng9LyMUfi.jpg","es":"https://image.tmdb.org/t/p/w500/mWuFbQrXyLk2kMBKF9TUPtDwuPx.jpg","en":"https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg","de":"https://image.tmdb.org/t/p/w500/uFjlP9U9UOZAzGB25HUtmlEpXbc.jpg"}'::jsonb WHERE id = 35;
UPDATE public.films SET tmdb_id = 123, titoli_i18n = '{"it":"Il Signore degli Anelli","en":"The Lord of the Rings","fr":"Le Seigneur des anneaux","es":"El Señor de los Anillos","de":"Der Herr der Ringe"}'::jsonb, trame_i18n = '{"it":"Adattamento animato classico realizzato tramite la tecnica del rotoscopio che ripercorre le vicende della Compagnia dell''Anello. Frodo e i suoi compagni intraprendono un lungo viaggio per sconfiggere l''oscurità che minaccia la Terra di Mezzo.","en":"Young Hobbit Frodo Baggins is thrown into an amazing adventure when he''s tasked with destroying the One Ring, created by the dark lord Sauron. Frodo must travel in a small fellowship of nine warriors and accomplices. But it won''t be an easy journey for the Fellowship of the Ring, on the ultimate quest to rid Middle-earth of evil.","fr":"Dans les Terres du Milieu, l''Anneau unique forgé par Sauron le maléfique pour dominer les hommes, les elfes et les nains est tombé par inadvertance dans les mains de Frodon, paisible hobbit. Ce n''est qu''une question de temps avant que les sinistres Cavaliers Noirs, les Servants de l''Anneau, retrouvent sa trace. Sous la direction de Gandalf le magicien, une expédition est alors montée avec pour mission une tâche quasi-impossible : détruire l''Anneau, en le jetant dans le feu de la Montagne du Destin, au coeur du territoire de l''ennemi...","es":"Adaptación en dibujos animados de la extraordinaria novela de Tolkien, centrada en la primera mitad de la trilogía: \"The Fellowhip of the Ring\" y la primera parte de \"The Two Towers\". En la Tierra Media, desde las verdes praderas de la Comarca, Frodo Bolsón, sobrino de Bilbo Bolsón, se embarca en una larga y peligrosa aventura para evitar que un anillo mágico que perteneció a su tío caiga ahora en poder del malvado Sauron, dueño de Mordor.","de":"Der junge Hobbit Frodo Beutlin bekommt von Gandalf die Aufgabe, den Einen Ring zu zerstören, der die Macht des Dunklen Herrschers Sauron enthält. Frodo schließt sich der Gemeinschaft des Rings an, zu der auch seine Freunde Sam, Merry und Pippin, der Grenzgänger Aragorn, der Krieger Boromir, der Elf Legolas, der Zwerg Gimli und Gandalf der Graue gehören. Die Gemeinschaft bricht nach Bruchtal auf, wird aber von den Schwarzen Reitern verfolgt. Sie durchqueren die gefährlichen Zwergenminen von Moria, treffen auf den undurchschaubaren Gollum und kämpfen in der Schlacht von Helms Klamm."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zC18JY8JMNw4xZFjaaEYZw6H3A8.jpg","en":"https://image.tmdb.org/t/p/w500/liW0mjvTyLs7UCumaHhx3PpU4VT.jpg","fr":"https://image.tmdb.org/t/p/w500/lH5at1RvvglQmnoBkytTTPZfw94.jpg","es":"https://image.tmdb.org/t/p/w500/6SHIZpuZ2cGoTGq5nbihIgy43rC.jpg","de":"https://image.tmdb.org/t/p/w500/k0YO6bHkPOyhnw3nn17k6LVXbrO.jpg"}'::jsonb WHERE id = 36;
UPDATE public.films SET tmdb_id = 185, titoli_i18n = '{"it":"Arancia Meccanica","en":"A Clockwork Orange","es":"La naranja mecánica","fr":"Orange mécanique","de":"Uhrwerk Orange"}'::jsonb, trame_i18n = '{"it":"In una Gran Bretagna distopica e futuristica, il giovane Alex DeLarge è il leader dei Drughi, una banda di criminali dedita ad atti brutali di ''ultraviolenza''. Dopo essere stato arrestato per omicidio e condannato al carcere, Alex accetta di sottoporsi alla ''Cura Ludovico'', un innovativo e controverso trattamento di condizionamento psicologico promosso dal governo. Il trattamento lo rende fisicamente incapace di compiere o persino di pensare ad azioni violente, ma al contempo lo priva del suo libero arbitrio, lasciandolo del tutto indifeso di fronte alla società e alla vendetta delle sue vecchie vittime.","en":"In a near-future Britain, young Alexander DeLarge and his pals get their kicks beating and raping anyone they please. When not destroying the lives of others, Alex swoons to the music of Beethoven. The state, eager to crack down on juvenile crime, gives an incarcerated Alex the option to undergo an invasive procedure that''ll rob him of all personal agency. In a time when conscience is a commodity, can Alex change his tune?","es":"Gran Bretaña, en un futuro indeterminado. Alex es un joven muy agresivo que tiene dos pasiones: la violencia desaforada y Beethoven. Es el jefe de la banda de los drugos, que dan rienda suelta a sus instintos más salvajes apaleando, violando y aterrorizando a la población. Cuando esa escalada de terror llega hasta el asesinato, Alex es detenido y, en prisión, se someterá voluntariamente a una innovadora experiencia de reeducación que pretende anular drásticamente cualquier atisbo de conducta antisocial.","fr":"Au XXIe siècle, où règnent la violence et le sexe, Alex, jeune chef de bande, exerce avec sadisme une terreur aveugle. Après son emprisonnement, des psychanalystes l''emploient comme cobaye dans des expériences destinées à juguler la criminalité…","de":"Die Handlung spielt im London einer nicht allzu weit entfernten Zukunft und kreist um den jungen Alex. Der liebt Beethoven und ist Anführer der Droogs, einer Jugendgang. Die Gruppe selbst fällt mit nur durch den Akt an sich motivierten Gewalttaten und Vergewaltigungen Wehrloser auf. Nachdem die Jungs wieder mal einen Einbruch nebst Mord begangen haben, wird Alex von einem rebellierenden Gangmitglied niedergeschlagen und der Polizei überlassen. Der ehemalige Anführer kommt ins Gefängnis. Zwei Jahre später muss er als Versuchsobjekt an einer neuartigen, von der Regierung initiierten Aversionstherapie teilnehmen. Die Therapie dauert 14 Tage lang und konfrontiert Alex immer wieder mit Filmszenen stärkster Brutalität. Anschließend kommt er frei, ist nun allerdings nichts weiter als eine willenlose Hülle."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/7dbLsJo2DiyhPZO3iQc70LwDMzv.jpg","en":"https://image.tmdb.org/t/p/w500/4sHeTAp65WrSSuc05nRBKddhBxO.jpg","es":"https://image.tmdb.org/t/p/w500/p40pYh2EBPoyVyqw6qy2PAZkFVA.jpg","fr":"https://image.tmdb.org/t/p/w500/n2oKNiEq9DZljqs6xsxs8hnsW9p.jpg","de":"https://image.tmdb.org/t/p/w500/mB07QYollr6luCA9koLaywmZWDY.jpg"}'::jsonb WHERE id = 37;
UPDATE public.films SET tmdb_id = 646, titoli_i18n = '{"en":"Dr. No","it":"Agente 007 - Licenza di uccidere","es":"Agente 007 contra el Dr. No","de":"James Bond 007 jagt Dr. No","fr":"James Bond 007 contre Dr. No"}'::jsonb, trame_i18n = '{"en":"Agent 007 battles mysterious Dr. No, a scientific genius bent on destroying the U.S. space program. As the countdown to disaster begins, Bond must go to Jamaica, where he encounters beautiful Honey Ryder, to confront a megalomaniacal villain in his massive island headquarters.","it":"L''agente segreto britannico James Bond, noto come 007, viene inviato in Giamaica per indagare sulla misteriosa scomparsa di un suo collega, lo chef della sezione di Kingston, e della sua segretaria. Con l''aiuto dell''agente della CIA Felix Leiter e del luogo Quarrel, Bond risale le tracce fino all''isola sotterranea di Crab Key. Lì fa la conoscenza della splendida Honey Ryder e scopre il covo del sinistro Dottor No, un genio del male affiliato all''organizzazione criminale SPECTRE. Dr. No intende utilizzare un''arma a raggi atomici per deviare la rotta dei missili spaziali americani lanciati da Cape Canaveral. 007 dovrà fare affidamento sulle sue abilità e sul suo fascino per distruggere la base segreta e sventare la minaccia globale.","es":"James Bond llega a Jamaica con la misión de investigar los asesinatos de un agente especial británico y su secretaria. Pero, al mismo tiempo, descubre la existencia de una siniestra organización en la isla Crab Key. En esta ocasión su enemigo es el Doctor No, que, ayudado por su cómplice, el profesor Dent, se propone ejecutar un siniestro plan: desviar la trayectoria de los cohetes de Cabo Cañaveral.","de":"Der mysteriöse Wissenschaftler Dr. No sabotiert von seiner geheimen Basis auf Jamaica aus das amerikanische Raumfahrtprogramm. Der Secret Service setzt seinen besten Agenten auf den Wissenschaftler an.","fr":"Le chef des services secrets de Sa Majesté britannique, « M », envoie en mission à la Jamaïque l''agent spécial 007, James Bond, enquêter sur la disparition d''un de ses collègues. L''espion va affronter la puissance maléfique de Spectre, organisation criminelle qui vise à la domination du monde, personnifiée par le redoutable Dr No. Au gré de ses aventures, il rencontrera la sublime Honey, qui surgit de l''eau vêtue d''un bikini blanc."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/9zCOLJmLNst0sCPZlkW1IRoH65E.jpg","it":"https://image.tmdb.org/t/p/w500/7zrD13m7zmWrJncWO5UXPLGzeW6.jpg","es":"https://image.tmdb.org/t/p/w500/51Sy8Uu8Qwz6WWeqY17zHqXZU5d.jpg","de":"https://image.tmdb.org/t/p/w500/1NN9uwOnZiw4rj3drWHo0JVGZuq.jpg","fr":"https://image.tmdb.org/t/p/w500/txWTVoO9VltSsEghOoxdn8y6UqK.jpg"}'::jsonb WHERE id = 44;
UPDATE public.films SET tmdb_id = 658, titoli_i18n = '{"en":"Goldfinger","it":"Agente 007 - Missione Goldfinger","fr":"Goldfinger","de":"James Bond 007 - Goldfinger","es":"James Bond contra Goldfinger"}'::jsonb, trame_i18n = '{"en":"Special agent 007 comes face to face with one of the most notorious villains of all time, and now he must outwit and outgun the powerful tycoon to prevent him from cashing in on a devious scheme to raid Fort Knox -- and obliterate the world''s economy.","it":"L''agente segreto James Bond viene incaricato di indagare sui loschi affari di Auric Goldfinger, un magnate ossessionato dal metallo prezioso. Bond scopre un diabolico piano denominato ''Operazione Grand Slam'': Goldfinger intende far esplodere una bomba atomica all''interno del deposito aureo di Fort Knox per contaminare l''oro degli Stati Uniti e far schizzare alle stelle il valore del proprio monopolio. Tra insidiosi nemici come il letale scagnozzo Oddjob e l''affascinante pilota Pussy Galore, 007 dovrà fare di tutto per sventare il catastrofico piano.","fr":"L''agent secret 007 est chargé d''enquêter sur les revenus d''Auric Goldfinger. La banque d''Angleterre a découvert qu''il entreposait d''énormes quantités d''or, mais s''inquiète de ne pas savoir dans quel but. Quelques verres, parties de golf, poursuites et autres aventures galantes plus loin, James Bond découvre en réalité les préparatifs du « crime du siècle », dont les retombées pourraient amener le chaos économique sur les pays développés du bloc de l''Ouest…","de":"Die teuerste Art zu töten. James Bond, der Superagent seiner Majestät, wird auf die Fährte eines verbrecherischen Genies gesetzt, das die Goldreserven von Fort Knox in seinen Besitz bringen will. Bonds Gegner Goldfinger ist der Mann, der seine abtrünnig gewordene Geliebte einem tödlichen Veredelungsprozeß aussetzte, indem er sie mit Gold überzog. Männliche Rivalen barbiert Odd-Job, der Leibwächter des exzentrischen Mulitmillionärs, mit seiner rasiermesserscharfen Hutkrempe aus Metall. Mit Hilfe von Pussy Galore will Bond den Raub des Goldes vereiteln...","es":"Un malvado magnate, Auric Goldfinger, quiere hacer estallar una bomba atómica en Fort Knox, donde está toda la reserva federal de oro de los Estados Unidos, para poder así incrementar enormemente el precio del metal dorado."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/aKNFzaqQgPzsGXnsMc4kJH5hFIV.jpg","it":"https://image.tmdb.org/t/p/w500/JcIhKJxmi7DQHsKV174WztIT4n.jpg","fr":"https://image.tmdb.org/t/p/w500/8hN3D6rsQ98jSlkeMc43kfQ9pox.jpg","de":"https://image.tmdb.org/t/p/w500/okCBHoGLpyvZq8WRUZo9cKtox2I.jpg","es":"https://image.tmdb.org/t/p/w500/tA0AqFwuFvQCzLdBzEnIlK4RayX.jpg"}'::jsonb WHERE id = 45;
UPDATE public.films SET tmdb_id = 524, titoli_i18n = '{"it":"Casino","es":"Casino","de":"Casino","fr":"Casino","en":"Casino"}'::jsonb, trame_i18n = '{"it":"Sam ''Ace'' Rothstein viene incaricato dalla mafia di gestire il casinò Tangiers a Las Vegas negli anni ''70. La sua gestione efficace viene però minacciata dall''amico d''infanzia e gangster Nikki Santoro e dalla tempestosa relazione con la moglie Ginger. Tra cupidigia, inganni e declino dell''impero mafioso, la storia ripercorre l''ascesa e la caduta dei boss nella capitale del gioco d''azzardo.","es":"Las Vegas, 1973. Sam \"Ace\" Rothstein, un profesional de las apuestas, es el eficaz director de un importante casino que pertenece a un grupo de mafiosos. Su misión es controlar el funcionamiento del negocio y garantizar que la corriente de dinero que va a parar a manos de sus jefes siga fluyendo. Las Vegas es un lugar ideal para millonarios y políticos, pero es también lugar de paso de tahúres, prestamistas, traficantes de drogas y matones. Un día el violento Nicky Santoro, al que sus jefes han encargado que cuide de Sam, llega a Las Vegas con la intención de quedarse.","de":"Sam „Ace“ Rothstein sorgt dafür, dass in den Casinos von Las Vegas alles gut läuft. Das heißt: die Politiker müssen geschmiert werden, die Spieler dürfen nicht zu viel gewinnen, und die eigenen Kassen werden immer wieder um einige Millionen erleichtert. Tatkräftige Unterstützung erhält der Manager dabei von dem Schläger Nicky Santoro. Als „Ace“ sich in die attraktive Prostituierte Ginger McKenna verliebt, beginnen die Dinge außer Kontrolle zu geraten. Denn Ginger ist nicht nur drogen-, sondern auch extrem geltungssüchtig.","fr":"Dans les années soixante-dix à Las Vegas, Ace Rothstein dirige d''une main de fer l''hôtel-casino Tangiers, financé en sous-main par le puissant syndicat des camionneurs. Le Tangiers est l''un des casinos les plus prospères de la ville et Ace est devenu le grand manitou de Las Vegas, secondé par son ami d''enfance, Nicky Santoro. Impitoyable avec les tricheurs, Rothstein se laisse un jour séduire par une virtuose de l''arnaque d''une insolente beauté, Ginger McKenna. Amoureux, il lui ouvre les portes de son paradis et l''épouse. Ses ennuis commencent alors.","en":"In Las Vegas, two best friends-a casino executive and a Mafia enforcer--compete for a gambling empire and a fast-living, fast-loving socialite."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/bUQRgD54q9OrwHrvJN36jJiWhoP.jpg","es":"https://image.tmdb.org/t/p/w500/7x8lsyTB0G7OrLzQ7qxt3ywQ4OY.jpg","de":"https://image.tmdb.org/t/p/w500/76C391pg53WIxUEH1aZjT3ve1Nl.jpg","fr":"https://image.tmdb.org/t/p/w500/4a0I37pYcdFY6HeutalHQTGs0sl.jpg","en":"https://image.tmdb.org/t/p/w500/gziIkUSnYuj9ChCi8qOu2ZunpSC.jpg"}'::jsonb WHERE id = 46;
UPDATE public.films SET tmdb_id = 36557, titoli_i18n = '{"de":"James Bond 007 - Casino Royale","es":"Casino Royale","it":"Casino Royale","en":"Casino Royale","fr":"Casino Royale"}'::jsonb, trame_i18n = '{"de":"Sein erster Auftrag, nachdem er die Lizenz zum Töten erhalten hat, führt den MI6-Agenten James Bond nach Madagaskar, wo er auf den Terroristen Mollaka angesetzt wird. Zwar verläuft nicht alles nach Plan, doch als Bond auf eigene Faust weiter ermittelt, kommt er auf die Spur von Le Chiffre, dem Bankier einer weltweit operierenden Terror-Organisation. Dieser plant, das Vermögen seiner Organisation durch ein illegales Pokerspiel im „Casino Royale“ in Montenegro um ein Vielfaches zu erhöhen, wofür natürlich auch ein hoher Einsatz nötig ist. Der MI6 sieht daher die Chance, die Terroristen in den finanziellen Ruin zu treiben und beauftragt James Bond, die Pläne von Le Chiffre zunichte zu machen.","es":"La primera misión del agente británico James Bond como agente 007 lo lleva hasta Le Chiffre, banquero de los terroristas de todo el mundo. Para detenerlo y desmantelar la red terrorista, Bond debe derrotarlo en una arriesgada partida de póquer en el Casino Royale. Al principio a Bond le disgusta Vesper Lynd, la hermosa oficial del Tesoro que debe vigilar el dinero del gobierno. Pero, a medida que Bond y Vesper se ven obligados a defenderse juntos de los mortales ataques de Le Chiffre y sus secuaces, nace entre ellos una atracción mutua.","it":"Dopo aver ottenuto lo status di agente 00 e la licenza di uccidere, James Bond viene inviato in missione per fermare Le Chiffre, un brillante e spietato banchiere che finanzia organizzazioni terroristiche internazionali. Avendo perso ingenti somme di denaro appartenenti ai suoi pericolosi clienti a causa di un attentato sventato dallo stesso Bond, Le Chiffre organizza una partita di poker Texas Hold''em ad altissima posta al Casino Royale, in Montenegro, nel tentativo disperato di recuperare i fondi. L''MI6 affida a Bond il compito di batterlo al tavolo verde per costringerlo a chiedere asilo al governo britannico in cambio di informazioni cruciali. Affiancato dall''affascinante e riservata funzionaria del Tesoro Vesper Lynd, incaricata di monitorare i fondi statali della posta in gioco, l''agente 007 si ritrova invischiato in un mortale gioco di strategia, inganni e violenza, che lo porterà a scoprire il peso emotivo del proprio mestiere e il sapore del tradimento.","en":"Le Chiffre, a banker to the world''s terrorists, is scheduled to participate in a high-stakes poker game in Montenegro, where he intends to use his winnings to establish his financial grip on the terrorist market. M sends Bond—on his maiden mission as a 00 Agent—to attend this game and prevent Le Chiffre from winning. With the help of Vesper Lynd and Felix Leiter, Bond enters the most important poker game in his already dangerous career.","fr":"Pour sa première mission, James Bond affronte le tout-puissant banquier privé du terrorisme international, Le Chiffre. Pour achever de le ruiner et démanteler le plus grand réseau criminel qui soit, Bond doit le battre lors d''une partie de poker à haut risque au Casino Royale. La très belle Vesper, attachée au Trésor, l''accompagne afin de veiller à ce que l''agent 007 prenne soin de l''argent du gouvernement britannique qui lui sert de mise, mais rien ne va se passer comme prévu. Alors que Bond et Vesper s''efforcent d''échapper aux tentatives d''assassinat du Chiffre et de ses hommes, d''autres sentiments surgissent entre eux, ce qui ne fera que les rendre plus vulnérables..."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/uvigE215SzXdsEFPN0XRFR9RPiA.jpg","es":"https://image.tmdb.org/t/p/w500/qplE2N7QWTO6w7X8zW46X3cGUBZ.jpg","it":"https://image.tmdb.org/t/p/w500/wmRTS3WrXRi8GJdpDae1NifYNwx.jpg","en":"https://image.tmdb.org/t/p/w500/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg","fr":"https://image.tmdb.org/t/p/w500/1ST7phuvQsaAIIkRyAtESZFLMx9.jpg"}'::jsonb WHERE id = 47;
UPDATE public.films SET tmdb_id = 31414, titoli_i18n = '{"it":"Sátántangó","en":"Satantango","es":"Sátántangó","fr":"Le Tango de Satan","de":"Satanstanz"}'::jsonb, trame_i18n = '{"it":"In un desolate e piovoso villaggio ungherese dopo la chiusura di una fattoria collettiva, gli abitanti vivono nell''apatia e nel sospetto reciproco. Il presunto ritorno del carismatico Irimiás, ritenuto morto da tutti, riaccende una labile speranza che si trasforma presto in una complessa danza di manipolazione e inganno.","en":"Inhabitants of a small village in Hungary deal with the effects of the fall of Communism. The town''s source of revenue, a factory, has closed, and the locals, who include a doctor and three couples, await a cash payment offered in the wake of the shuttering. Irimias, a villager thought to be dead, returns and, unbeknownst to the locals, is a police informant. In a scheme, he persuades the villagers to form a commune with him.","es":"La historia relata gradualmente los problemas de una granja colectiva durante unos pocos días de otoño en los años de la Hungría post-comunista, observada desde la perspectiva de distintos personajes. (FILMAFFINITY)","fr":"Dans un petit village hongrois, deux mystérieuses personnes que chacun croyait disparues refont parler d''elles. Une épopée de plus de sept heures sur la chute du communisme en Europe de l''Est.","de":"Am Vorabend einer großen Auszahlung sehen sich die Pläne der Bewohner einer zusammenbrechenden Kolchose in Verzweiflung verwandelt, als sie feststellen, dass Irimiás, ein ehemaliger Kollege, den sie für tot hielten, in die Gemeinschaft zurückkehrt."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg","en":"https://image.tmdb.org/t/p/w500/hySy5g6xncM3U1iRsdPgYyahXM0.jpg","es":"https://image.tmdb.org/t/p/w500/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg","fr":"https://image.tmdb.org/t/p/w500/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg","de":"https://image.tmdb.org/t/p/w500/cOrtWdUflqXL9BqoQNjv9WwQiPs.jpg"}'::jsonb WHERE id = 48;
UPDATE public.films SET tmdb_id = 24428, titoli_i18n = '{"it":"The Avengers","es":"Vengadores","en":"The Avengers","de":"Marvel''s The Avengers","fr":"Avengers"}'::jsonb, trame_i18n = '{"it":"Quando Loki, il malvagio fratellastro di Thor, minaccia la sicurezza della Terra impossessandosi del potente Tesseract, Nick Fury, direttore dell''agenzia di spionaggio S.H.I.E.L.D., decide di attivare il protocollo Avengers. Per sconfiggere la minaccia aliena, Fury riunisce una squadra di supereroi straordinari, tra cui Iron Man, Captain America, Thor, Hulk, Vedova Nera e Occhio di Falco. Nonostante le iniziali incomprensioni e i conflitti interni, il gruppo dovrà unire le forze per salvare l''umanità.","es":"Cuando un enemigo inesperado surge como una gran amenaza para la seguridad mundial, Nick Fury, director de la Agencia SHIELD, decide reclutar a un equipo para salvar al mundo de un desastre casi seguro.","en":"When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!","de":"Nick Fury ist der Anführer der Organisation S.H.I.E.L.D., einer internationalen Friedensorganisation. Die Behörde ist ein Who''s Who der Marvel Superhelden, mit Iron Man, Thor, Captain America, Hawkeye, dem Unglaublichen Hulk und Black Widow. Als die weltweite Sicherheit von Thors sinistrem Halbbruder Loki und seiner Schar bedroht wird, werden Nick Fury und sein Team all ihre Kräfte brauchen, um die Welt vor einer Katastrophe zu bewahren ...","fr":"Lorsque la sécurité et l’équilibre de la planète sont menacés par un ennemi d’un genre nouveau, Nick Fury, le directeur du SHIELD, l’agence internationale du maintien de la paix, réunit une équipe pour empêcher le monde de basculer dans le chaos. Partout sur Terre, le recrutement des nouveaux héros dont le monde a besoin commence…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/o6IvnjWsAjPja21JA1EHo0XcYTy.jpg","es":"https://image.tmdb.org/t/p/w500/ugX4WZJO3jEvTOerctAWJLinujo.jpg","en":"https://image.tmdb.org/t/p/w500/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg","de":"https://image.tmdb.org/t/p/w500/hGTqvK9WaI74szUDPMHXrrHfiH3.jpg","fr":"https://image.tmdb.org/t/p/w500/ylsAO88v2tF0iXRFojPa0UaAJf1.jpg"}'::jsonb WHERE id = 49;
UPDATE public.films SET tmdb_id = 99861, titoli_i18n = '{"it":"Avengers: Age of Ultron","en":"Avengers: Age of Ultron","fr":"Avengers : L''Ère d''Ultron","de":"Avengers: Age of Ultron","es":"Vengadores: La era de Ultrón"}'::jsonb, trame_i18n = '{"it":"Quando Tony Stark e Bruce Banner cercano di avviare un programma di mantenimento della pace inattivo chiamato Ultron, le cose vanno terribilmente storte e il sistema intelligenza artificiale sviluppa una coscienza divina, decidendo che l''unico modo per salvare la Terra è sterminare l''umanità. Gli Avengers devono riunirsi e stringere imprevedibili alleanze per fermare il temibile Ultron e i suoi piani di distruzione globale.","en":"When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.","fr":"Alors que Tony Stark tente de relancer un programme de maintien de la paix jusque-là suspendu, les choses tournent mal et les super-héros Iron Man, Captain America, Thor, Hulk, Black Widow et Hawkeye vont devoir à nouveau unir leurs forces pour combattre le plus puissant de leurs adversaires : le terrible Ultron, un être technologique terrifiant qui s’est juré d’éradiquer l’espèce humaine. Afin d’empêcher celui-ci d’accomplir ses sombres desseins, des alliances inattendues se scellent, les entraînant dans une incroyable aventure et une haletante course contre le temps…","de":"Milliardär, Lebemann und Genie Tony Stark aka Iron Man will ein inaktives Friedensprogramm in Gang bringen, doch dabei geht etwas schief. So taucht der niederträchtige Roboter-Bösewicht Ultron auf und verfolgt Pläne zur Ausrottung der Menschheit. Nun ist es an den Helden, sich wieder zu sammeln und das schreckliche Schicksal der Welt abzuwenden. Zusammen mit Iron Man treten Thor, Captain America, Hulk, Black Widow und Hawkeye dem fiesen Ultron entgegen und bekommen dabei Unterstützung von den ehemaligen S.H.I.E.L.D.-Agenten Nick Fury und Maria Hill. Außerdem kreuzen die geheimnisvollen und mit besonderen Fähigkeiten ausgestatteten Newcomer Wanda und Pietro Maximoff den Weg der Helden, wie auch ein alter Bekannter in neuer Gestalt: Vision. Die Rächer müssen ihre Kräfte vereinen, unsichere Allianzen schmieden und auf unerwartete Aktionen reagieren, um die Bewohner der Erde einmal mehr vor dem drohenden Untergang zu bewahren.","es":"Cuando Tony Stark intenta reactivar un programa caído en desuso cuyo objetivo es mantener la paz, las cosas empiezan a torcerse y los héroes más poderosos de la Tierra, incluyendo a Iron Man, Capitán América, Thor, El Increíble Hulk, Viuda Negra y Ojo de Halcón, tendrán que afrontar la prueba definitiva cuando el destino del planeta se ponga en juego. Cuando el villano Ultron emerge, le corresponderá a Los Vengadores detener sus terribles planes, que junto a incómodas alianzas llevarán a una inesperada acción que allanará el camino para una épica y única aventura."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/pYEHarIwyYSM1bXs5FtpL2GZELy.jpg","en":"https://image.tmdb.org/t/p/w500/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg","fr":"https://image.tmdb.org/t/p/w500/A0tw88n1byyR2vodhJMlFPQGQgF.jpg","de":"https://image.tmdb.org/t/p/w500/woAP8YaiVIuo7YXTeqVQEhXBdfz.jpg","es":"https://image.tmdb.org/t/p/w500/71wSx6MQm8EbMNDi3vVaD8nD9SL.jpg"}'::jsonb WHERE id = 50;
UPDATE public.films SET tmdb_id = 299536, titoli_i18n = '{"it":"Avengers: Infinity War","en":"Avengers: Infinity War","es":"Vengadores: Infinity War","fr":"Avengers : Infinity War","de":"Avengers: Infinity War"}'::jsonb, trame_i18n = '{"it":"Gli Avengers e i loro alleati supereroi devono essere pronti a sacrificare tutto nel tentativo di sconfiggere il potente Thanos, prima che il suo devastante attacco ponga fine all''universo. Il tiranno cosmico è alla ricerca delle sei Gemme dell''Infinito, manufatti di inimmaginabile potere, con l''obiettivo di dimezzare la popolazione dell''universo e portare un folle equilibrio.","en":"As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.","es":"El todopoderoso Thanos ha despertado con la promesa de arrasar con todo a su paso, portando el Guantelete del Infinito, que le confiere un poder incalculable. Los únicos capaces de pararle los pies son los Vengadores y el resto de superhéroes de la galaxia, que deberán estar dispuestos a sacrificarlo todo por un bien mayor. Capitán América e Ironman deberán limar sus diferencias, Black Panther apoyará con sus tropas desde Wakanda, Thor y los Guardianes de la Galaxia e incluso Spider-Man se unirán antes de que los planes de devastación y ruina pongan fin al universo. ¿Serán capaces de frenar el avance del titán del caos?","fr":"Les Avengers et leurs alliés devront être prêts à tout sacrifier pour neutraliser le redoutable Thanos avant que son attaque éclair ne conduise à la destruction complète de l’univers.","de":"Der mächtige Titan Thanos  hat es sich zur Aufgabe gemacht das halbe Universum auszulöschen. Um diesen perfiden Plan Realität werden zu lassen, benötigt er allerdings zuerst alle sechs Infinity-Steine, die ihm in Verbindung mit einem speziell gefertigten Handschuh, gottgleiche Kräfte verleihen. Da sich unglücklicherweise auch auf der Erde zwei dieser Steine befinden, betraut er seine treu ergebene Black Order mit deren Beschaffung. Sowohl die Avengers, als auch die Guardians of the Galaxy und Thor erfahren jedoch von Thanos'' Plänen und stellen sich dem Schurken entgegen. Doch mit einen derart mächtigen Gegner hatte es bisher keiner von ihnen zu tun..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/t24aimjQLa0dyoZQEbSws7XK1U0.jpg","en":"https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg","es":"https://image.tmdb.org/t/p/w500/ksBQ4oHQDdJwND8H90ay8CbMihU.jpg","fr":"https://image.tmdb.org/t/p/w500/hSfuKPtyEryeFzapZ8UgZd4aESu.jpg","de":"https://image.tmdb.org/t/p/w500/2hj7diAFcApL2YfWwjiYCuRI4WW.jpg"}'::jsonb WHERE id = 51;
UPDATE public.films SET tmdb_id = 299534, titoli_i18n = '{"es":"Vengadores: Endgame","en":"Avengers: Endgame","it":"Avengers: Endgame","fr":"Avengers : Endgame","de":"Avengers: Endgame"}'::jsonb, trame_i18n = '{"es":"Tras el chasquido de Thanos que eliminó a la mitad de la vida en el universo, los Vengadores supervivientes quedan devastados y divididos. Cinco años después, una inesperada oportunidad les permite intentar revertir la catástrofe. Reuniéndose una vez más, los héroes emprenden una misión extrema que los obliga a viajar al pasado, enfrentarse a sus propias pérdidas y hacer sacrificios definitivos para restaurar el equilibrio del universo.","en":"After the devastating events of Avengers: Infinity War, the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos'' actions and restore order to the universe once and for all, no matter what consequences may be in store.","it":"Dopo gli eventi devastanti di Avengers: Infinity War, l''universo è in rovina a causa delle azioni di Thanos. Con l''aiuto degli alleati rimasti, gli Avengers superstiti si riuniscono ancora una volta per annullare le azioni del Titano Pazzo. Attraverso un rischioso viaggio nel tempo nel Regno Quantico, il gruppo tenta di recuperare le Gemme dell''Infinito nel passato per riportare in vita tutti coloro che sono scomparsi e ripristinare l''ordine nell''universo.","fr":"Après leur défaite face au Titan Thanos qui dans le film précédent s''est approprié toutes les pierres du Gant de l''infini, les Avengers et les Gardiens de la Galaxie ayant survécu à son claquement de doigts qui a pulvérisé « la moitié de toute forme de vie dans l''Univers », Captain America, Thor, Bruce Banner, Natasha Romanoff, War Machine, Tony Stark, Nébula et Rocket, vont essayer de trouver une solution pour ramener leurs coéquipiers disparus et vaincre Thanos en se faisant aider par Ronin alias Clint Barton, Captain Marvel et Ant-Man.","de":"Thanos hat also tatsächlich Wort gehalten, seinen Plan in die Tat umgesetzt und die Hälfte allen Lebens im Universum ausgelöscht. Die Avengers? Machtlos. Iron Man und Nebula sitzen auf dem Planeten Titan fest, während auf der Erde absolutes Chaos herrscht. Doch dann finden Captain America und die anderen überlebenden Helden auf der Erde heraus, dass Nick Fury vor den verheerenden Ereignissen gerade noch ein Notsignal absetzen konnte, um Verstärkung auf den Plan zu rufen. Die Superhelden-Gemeinschaft bekommt mit Captain Marvel kurzerhand tatkräftige Unterstützung im Kampf gegen ihren vermeintlich übermächtigen Widersacher. Und dann ist da auch noch Ant-Man, der wie aus dem Nichts auftaucht und sich der Truppe erneut anschließt, um die ganze Sache womöglich doch noch zu einem guten Ende zu bringen …"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/br6krBFpaYmCSglLBWRuhui7tPc.jpg","en":"https://image.tmdb.org/t/p/w500/jtDv3lCnST0fZRvdYFwR5CVwK2x.jpg","it":"https://image.tmdb.org/t/p/w500/hj1xaEUGMiUxaFYoutlljtlkHSG.jpg","fr":"https://image.tmdb.org/t/p/w500/qXekTarZKRrVfnBwhS6xevt6BGU.jpg","de":"https://image.tmdb.org/t/p/w500/ibO8Pj0aA1nwj3Q9FMpMcYZkdCA.jpg"}'::jsonb WHERE id = 52;
UPDATE public.films SET tmdb_id = 12211, titoli_i18n = '{"it":"Highlander: Endgame","en":"Highlander: Endgame","de":"Highlander: Endgame","fr":"Highlander: Endgame","es":"Los inmortales IV. Juego final"}'::jsonb, trame_i18n = '{"it":"Duncan MacLeod e suo cugino Connor uniscono le forze per affrontare Jacob Kell, un malvagio immortale che ha accumulato un potere immenso eliminando centinaia di rivali nel corso dei secoli. Per sconfiggere un nemico apparentemente invincibile, i due guerrieri scozzesi dovranno affrontare il proprio passato e compiere la scelta più difficile della loro vita.","en":"Immortals Connor and Duncan Macleod join forces against a man from Connor''s distant past in the highlands of Scotland, Kell, an immensely powerful immortal who leads an army of equally powerful and deadly immortal swordsmen and assassins. No immortal alive has been able to defeat Kell yet, and neither Connor nor Duncan are skilled enough themselves to take him on and live. The two of them eventually come to one inevitable conclusion; one of them must die so that the combined power of both the Highlanders can bring down Kell for good. There can be only one... the question is, who will it be?","de":"Heute: Auf der Suche nach seinem Vetter Connor MacLeod findet der unsterbliche Highlander Duncan MacLeod das geheime Refugium. Hier werden Unsterbliche, die des Lebens müde geworden sind, in einen künstlichen Schlaf versetzt. Das Refugium ist auch dafür da, dass der Kampf der Unsterblichen um die Weltherrschaft nie ein Ende finden kann, denn solange es noch mehr als einen gibt ist nichts entschieden. Auch darum ist der Standort des Refugiums geheim. Doch der kaltblütigste Unsterbliche hat es gefunden, zerstört, seine \"Einwohner\" geköpft. Nur Connor MacLeod hat er laufen lassen, nicht um ihn zu verschonen, sondern um sich an ihm zu rächen...","fr":"Les Highlanders ont vécu à l''époque de nos ancêtres et vivent aujourd''hui à nos côtés. Depuis des siècles, Duncan MacLeod (Adrian Paul) croise le chemin de son proche ami, Connor MacLeod (Christophe Lambert), immortel également. Leur amitié a commencé au XVIIème siècle, lors de leur première rencontre sur le champ de bataille de Glen Fruin. Connor l''avait alors pris comme apprenti et lui avait enseigné les rudiments de combat et les règles des immortels. A l''aube du XXIème siècle, le destin a fait en sorte de les réunir à nouveau. Par ailleurs, les deux combattants découvrent que chacun de leurs adversaires possède un pouvoir de destruction incroyable dû à la maîtrise des arts martiaux et de l''épée. Une ultime bataille dont l''issue décidera du destin de l''espèce humaine va se dérouler entre les immortels sur la Terre. A la fin, il ne doit en rester qu''un seul.","es":"Connor MacLeod está cansado de su condición de inmortal y de ver cómo sobrevive a todos los que ama. Se recluye en un santuario en el que los inmortales pueden reposar en paz, sin tener que luchar. Pero el santuario es atacado por un viejo enemigo, Jacob Kell, que, después de asesinar a todos los que se encontraban retirados, excepto Connor, se ha convertido en el inmortal más poderoso. Ahora, Connor y su hermano Duncan tendrán que detenerlo y evitar así que sea el malvado Kell el último inmortal que quede."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jWo1Azj8JFiFAd7MAGkutWB8ZVW.jpg","en":"https://image.tmdb.org/t/p/w500/u7kIXMyagqcek2SaS9svfPTTGVT.jpg","de":"https://image.tmdb.org/t/p/w500/wATBEDL4TboulrprMaCFv34TpVY.jpg","fr":"https://image.tmdb.org/t/p/w500/u7kIXMyagqcek2SaS9svfPTTGVT.jpg","es":"https://image.tmdb.org/t/p/w500/5lVlajdAMI2WnX5X8OnguITpmZM.jpg"}'::jsonb WHERE id = 53;
UPDATE public.films SET tmdb_id = 1366, titoli_i18n = '{"en":"Rocky","it":"Rocky","es":"Rocky","de":"Rocky","fr":"Rocky"}'::jsonb, trame_i18n = '{"en":"Rocky Balboa is a Philadelphia club fighter who seems to be going nowhere. But when a stroke of fate puts him in the ring with a world heavyweight champion, Rocky knows that it''s his one shot at the big time — a once-in-a-lifetime opportunity to go the distance and come out a winner!","it":"Rocky Balboa, un pugile di poco conto di Filadelfia che vive riscuotendo crediti per un usuraio locale, ottiene una straordinaria ed inaspettata occasione: sfidare il campione del mondo dei pesi massimi, Apollo Creed. Con il duro allenamento dell''anziano Mickey e il supporto dell''amata Adriana, Rocky cercherà di riscattare la propria vita e dimostrare di non essere solo un fantoccio sul ring.","es":"Rocky Balboa es un desconocido boxeador a quien se le ofrece la posibilidad de pelear por el título mundial de los pesos pesados. Con mucha fuerza de voluntad, Rocky se preparará concienzudamente para este combate, y también para los cambios que producirá en su vida.","de":"Rocky Balboa ist ein begnadeter Boxer. Doch der Weg zum Ruhm und dem großen Geld blieb ihm immer verwehrt. Als armer Geldeintreiber muss er ein schäbiges Dasein fristen. Da geschieht das Unglaubliche: Der Amateurboxer erhält die Möglichkeit, gegen den Schwergewichtsweltmeister Apollo Creed anzutreten. Was als PR-Gag geplant ist, entpuppt sich als brutaler und gnadenloser Kampf, denn der ehrgeizige Rocky will sich die Chance seines Lebens von niemandem nehmen lassen …","fr":"Dans les quartiers populaires de Philadelphie, Rocky Balboa collecte des dettes non payées pour Tony Gazzo, un usurier, et dispute de temps à autre, pour quelques dizaines de dollars, des combats de boxe sous l''appellation de ''l''étalon italien''. Déçu de le voir gâcher son talent, son entraîneur Mickey le laisse tomber, tandis qu''Apollo Creed, champion en titre, cherche un nouveau challenger..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/1mcJmdbRLusxhoSGjFI3pbEboXt.jpg","it":"https://image.tmdb.org/t/p/w500/drkb38iICkgy712cMWJAH4IFqSQ.jpg","es":"https://image.tmdb.org/t/p/w500/yyoGappf3WxXRrHz23yNbH2MffI.jpg","de":"https://image.tmdb.org/t/p/w500/1mcJmdbRLusxhoSGjFI3pbEboXt.jpg","fr":"https://image.tmdb.org/t/p/w500/5cfUTKtLYJx8WcTRJII4JRnlg6p.jpg"}'::jsonb WHERE id = 54;
UPDATE public.films SET tmdb_id = 1374, titoli_i18n = '{"it":"Rocky IV","en":"Rocky IV","es":"Rocky IV","de":"Rocky IV - Der Kampf des Jahrhunderts","fr":"Rocky IV"}'::jsonb, trame_i18n = '{"it":"Rocky Balboa accompagna l''amico fraterno ed ex rivale Apollo Creed in un match di esibizione contro il temibile e glaciale pugile sovietico Ivan Drago. Quando Apollo muore tragicamente sul ring a causa dei colpi brutali di Drago, Rocky decide di vendicare l''amico sfidando il gigante russo a Mosca il giorno di Natale. Per prepararsi, Rocky si sottopone a un durissimo allenamento tra i ghiacci della Siberia, culminando in uno scontro epico che va oltre lo sport, diventando un simbolo della Guerra Fredda.","en":"Rocky Balboa holds the world heavyweight championship, but a new challenger has stepped forward: Drago, a six-foot-four, 261-pound fighter who has the backing of the Soviet Union. This time, Rocky''s training regimen takes him to Siberia, where he prepares for a globally televised match in the heart of Moscow. But nothing can truly prepare him for what he''s about to face – a fight to the finish, in which he must defend not only himself, but also the honor of his country!","es":"Nuevas aventuras tanto personales como deportivas del boxeador Rocky Balboa, que en esta ocasión debe enfrentarse a un duro y frío boxeador soviético, llamado Ivan Drago.","de":"Rocky ist wieder da. Nach seinem sensationellen Sieg gegen Clubber Lang ist das Leben des Champions wieder in Ordnung. Doch da möchte bereits der nächste Herausforderer eine Chance, um gegen Rocky zu boxen. Es ist der sowjetische Boxer Ivan Drago, der Rockys bisherige Gegner in den Schatten stellt. Dies bekommt in einem mörderischen Schaukampf auch Rockys Ex-Gegner und heutiger Freund Apollo Creed nur allzu deutlich zu spüren. Nun ist es unausweichlich – Rocky muss gegen den russischen Hünen antreten. Und in Moskau kommt es schließlich zu diesem Kampf – einem Kampf der Superlative, in dem beide Boxer wirklich alles geben – aber es kann nur einer gewinnen!","fr":"Apollo Creed, ancien adversaire et dorénavant ami de Rocky Balboa, est tué sur le ring par le boxeur russe Ivan Drago. Se reprochant de n''avoir pu sauver son camarade à temps, Rocky va demander un combat contre Ivan Drago afin de le venger. Une confrontation qui se déroulera sur le sol russe."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/k4mDFvQkr9CNxbK76Ih6rTnCQ4A.jpg","en":"https://image.tmdb.org/t/p/w500/2MHUit4H6OK5adcOjnCN6suCKOl.jpg","es":"https://image.tmdb.org/t/p/w500/2MHUit4H6OK5adcOjnCN6suCKOl.jpg","de":"https://image.tmdb.org/t/p/w500/stp9EQwMSsoyp7M79Hdf08lTeQH.jpg","fr":"https://image.tmdb.org/t/p/w500/bnd1dSQZyp6wL2AqtHG2PreJyZ5.jpg"}'::jsonb WHERE id = 55;
UPDATE public.films SET tmdb_id = 1367, titoli_i18n = '{"it":"Rocky II","fr":"Rocky II : La Revanche","es":"Rocky II","en":"Rocky II","de":"Rocky II"}'::jsonb, trame_i18n = '{"it":"Dopo il durissimo incontro con il campione dei pesi massimi Apollo Creed, Rocky Balboa decide di ritirarsi dal pugilato, sposa l''amata Adriana e cerca di costruirsi una vita tranquilla lontano dal ring. Ben presto però, a causa dell''inesperienza nella gestione del denaro e delle difficoltà a trovare un impiego stabile, Rocky si ritrova in gravi difficoltà economiche. Nel frattempo, Creed, tormentato dalle critiche dei tifosi e dalla stampa che insinuano che il verdetto del precedente match sia stato immeritato, lo provoca ripetutamente per convincerlo a salire di nuovo sul ring per una rivincita. Spinto dal bisogno e dal desiderio di riscatto, e confortato dal supporto di Adriana dopo un periodo critico, Rocky riprende gli allenamenti con Mickey per affrontare un drammatico secondo scontro.","fr":"Battu aux points lors de son dernier combat, Rocky n''accepte pas cette défaite et ne veut plus entendre parler de boxe. Il épouse Adrian, dépense sa fortune sans compter et bientôt se retrouve sans le sou. Poussé a bout par Apollo, qui veut disputer un vrai match il accepte de jouer la revanche...","es":"Rocky Balboa, el boxeador de Philadelphia, disfruta de su efímera fama después de estar a punto de derrotar al campeón mundial de los pesos pesados Apollo Creed. Las ofertas publicitarias para el anuncio de productos no van bien debido a la limitada educación y falta de sofisticación del púgil. Por ello, y debido a la falta de dinero y al embarazo de su mujer Adrian, acepta la demanda de revancha del \"casi derrotado\" Creed.","en":"After Rocky goes the distance with champ Apollo Creed, both try to put the fight behind them and move on. Rocky settles down with Adrian but can''t put his life together outside the ring, while Creed seeks a rematch to restore his reputation. Soon enough, the \"Master of Disaster\" and the \"Italian Stallion\" are set on a collision course for a climactic battle that is brutal and unforgettable.","de":"Obwohl Rocky seinen ersten großen Kampf gegen den Schwergewichts-Weltmeister Apollo Creed nach Punkten verloren hat, sehen ihn die meisten als den wahren Sieger. Und das hat nicht nur positive Auswirkungen auf seine finanzielle Situation, sondern auch auf das private Glück mit seiner Freundin Adrian. Doch Rocky, mit der neuen Situation überfordert, macht viele Fehler. Wieder der Armut nahe bleibt ihm nur eine Möglichkeit - die erneute Herausforderung von Apollo Creed annehmen und diesmal gewinnen. Doch die 15 Runden werden es in sich haben, und Rocky weiss das genau. Doch es geht um die Existenz von ihm ...und seiner Familie."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/vJKa9utvX1kNDCDKYdMDSzCOyX5.jpg","fr":"https://image.tmdb.org/t/p/w500/hscESJv9Gy4REpvK4aLV1Ao8dec.jpg","es":"https://image.tmdb.org/t/p/w500/nMaiiu0CzT77U4JZkUYV7KqdAjK.jpg","en":"https://image.tmdb.org/t/p/w500/nMaiiu0CzT77U4JZkUYV7KqdAjK.jpg","de":"https://image.tmdb.org/t/p/w500/xVu5e62TfXv9FFAflMxeZYm2w50.jpg"}'::jsonb WHERE id = 56;
UPDATE public.films SET tmdb_id = 22, titoli_i18n = '{"it":"Pirati dei Caraibi - La maledizione della prima luna","en":"Pirates of the Caribbean: The Curse of the Black Pearl","fr":"Pirates des Caraïbes : La Malédiction du Black Pearl","es":"Piratas del Caribe: La maldición de la Perla Negra","de":"Fluch der Karibik"}'::jsonb, trame_i18n = '{"it":"Caraibi, XVII secolo. La vita del pacifico fabbro Will Turner viene sconvolta quando l''amore della sua vita, Elizabeth Swann, figlia del governatore, viene rapita dal malvagio Capitan Barbossa e dalla sua ciurma di pirati a bordo della misteriosa nave Perla Nera. Per salvarla, Will si allea con l''eccentrico e stravagante pirata Jack Sparrow, ex capitano della Perla Nera desideroso di vendetta. I due scopriranno che Barbossa e i suoi uomini sono colpiti da una terribile maledizione azteca che li condanna a vivere come non-morti, rivelando il loro vero aspetto di scheletri solo sotto la luce della luna.","en":"When wily pirate Captain Barbossa seizes Jack Sparrow’s beloved ship, the Black Pearl, and kidnaps the governor’s daughter, Elizabeth Swann, blacksmith Will Turner reluctantly teams up with the unpredictable pirate Jack to rescue her—only to uncover a terrifying curse that turns Barbossa’s crew into the undead.","fr":"Dans la mer des Caraïbes, au XVIIe siècle, Jack Sparrow, flibustier gentleman, voit sa vie idyllique basculer le jour où son ennemi, le perfide capitaine Barbossa, lui vole son bateau, le Black Pearl, puis attaque la ville de Port Royal, enlevant au passage la très belle fille du gouverneur, Elizabeth Swann. L''ami d''enfance de celle-ci, Will Turner, se joint à Jack pour se lancer aux trousses du capitaine. Mais Will ignore qu''une malédiction frappe Barbossa et ses pirates. Lorsque la lune brille, ils se transforment en morts-vivants. Leur terrible sort ne prendra fin que le jour où le fabuleux trésor qu''ils ont amassé sera restitué…","es":"El aventurero capitán Jack Sparrow recorre las aguas caribeñas. Pero su andanzas terminan cuando su enemigo, el capitán Barbossa le roba su barco, la Perla Negra, y ataca la ciudad de Port Royal, secuestrando a Elizabeth Swann, hija del gobernador. Will Turner, el amigo de la infancia de Elizabeth, se une a Jack para rescatarla y recuperar la Perla Negra. Pero el prometido de Elizabeth, comodoro Norrington, les persigue a bordo del HMS Impávido. Además, Barbossa y su tripulación son víctimas de un conjuro por el que están condenados a vivir eternamente, y a transformarse cada noche en esqueletos vivientes, en fantasmas guerreros.","de":"Im 17.Jahrhundert sucht der Pirat Jack Sparrow nach einem sagenumwobenen Schatz in der Karibik, als ihn das Schicksal mit dem jungen Will Turner zusammenführt, der aus anderen Gründen auf derselben Fährte ist: nämlich den berüchtigten Captain Barbossa und seine Crew abzufangen, die Wills große Liebe Elizabeth, die Tochter des britischen Gouverneurs entführt haben. Doch Barbossa umhüllt selbst ein düsteres Geheimnis: er und seine Männer sind verflucht und das Licht des Mondes bringt ihre Existenz zum Vorschein: sie sind wie lebende Skelette, monströs und tödlich. Um den Fluch zu brechen, brauchen sie Elizabeth als Opfer. Ein Wettrennen zur Insel des Todes beginnt..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/r6ISuJLJ5U9MACu8lyCGmdZcHq3.jpg","en":"https://image.tmdb.org/t/p/w500/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg","fr":"https://image.tmdb.org/t/p/w500/jFmc6zbnx6mSoxejECYvdi3IHIs.jpg","es":"https://image.tmdb.org/t/p/w500/bVG48kmXuLaZYgPfSCmhs6EYFbX.jpg","de":"https://image.tmdb.org/t/p/w500/k150viTPWY84dvtw2GgWE6K1CNV.jpg"}'::jsonb WHERE id = 57;
UPDATE public.films SET tmdb_id = 58, titoli_i18n = '{"es":"Piratas del Caribe: El cofre del hombre muerto","fr":"Pirates des Caraïbes : Le Secret du coffre maudit","de":"Pirates of the Caribbean - Fluch der Karibik 2","it":"Pirati dei Caraibi - La maledizione del forziere fantasma","en":"Pirates of the Caribbean: Dead Man''s Chest"}'::jsonb, trame_i18n = '{"es":"Will Turner y Elizabeth Swann se van a casar, pero ambos son hechos prisioneros por Lord Cutler Beckett y acusados de haber liberado al capitán Jack Sparrow. Para salvar su vida, Will tendrá que encontrar a Jack y conseguir su misteriosa brújula. Esta esconde un gran poder, además de la clave de una deuda de sangre del pirata con un temible y siniestro Davy Jones, el legendario capitán del barco fantasma Holandés Errante.","fr":"Le pirate Jack Sparrow est confronté à son passé. Treize ans auparavant, il signait un pacte avec Davey Jones, le maléfique maître des sept mers. En échange de son âme, ce dernier lui promettait le commandement du mythique Black Pearl… Aujourd’hui, Jones vient donc récupérer sa dette.","de":"Diesmal sieht sich Captain Jack Sparrow, gerade erst dem Fluch der Black Pearl entkommen, mit einem neuen lebensbedrohenden Abenteuer konfrontiert: Denn Jack steht in lebenslanger Schuld bei Davy Jones, dem legendären Kapitän des Flying Dutchman und Herrscher über die Tiefen des Ozeans. Wenn er keinen Weg findet, den Bann zu brechen, ist er zu einem höllischen Leben nach dem Tode in ewiger Finsternis verdammt. Doch damit nicht genug: Jacks ausgesprochen existenzielle Probleme erweisen sich obendrein als Hindernis für die bevorstehende Hochzeit seiner Freunde Will Turner und Elizabeth Swann, die wider Willen in die andauernden Eskapaden des Kapitäns verwickelt werden. Das Abenteuer kann beginnen ...","it":"Il capitano Jack Sparrow scopre di avere un debito di sangue con il temibile Davy Jones, sovrano degli abissi e capitano del fantasmagorico Olandese Volante. Se non riuscirà a trovare una via d''uscita, Jack sarà condannato alla servitù eterna nell''equipaggio dei dannati. Per salvarsi, Jack deve rintracciare il leggendario forziere fantasma, contenente il cuore pulsante di Jones, l''unica debolezza del capitano dei mari. Nel frattempo, il matrimonio di Will Turner ed Elizabeth Swann viene interrotto dall''arresto da parte della Compagnia delle Indie Orientali guidata da Lord Cutler Beckett, il quale ricatta Will affinché rintracci Sparrow e si impossessi della sua bussola magica. I destini dei tre protagonisti si intrecciano nuovamente in una pericolosa caccia al tesoro, minacciata dalla mostruosa creatura marina al servizio di Jones: il Kraken.","en":"Captain Jack Sparrow’s got a blood debt to pay: he owes his soul to the legendary Davy Jones, ghastly Ruler of the Ocean Depths. To escape eternal servitude aboard the Flying Dutchman, ever-crafty Jack must track down the still-beating heart of Jones. But he won’t do it alone: Will Turner and Elizabeth Swann are drawn back into another one of his perilous quests—assuming they can evade execution for aiding a pirate."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/7L7H6sHAt48EfwsqFaa0dw2NJhz.jpg","fr":"https://image.tmdb.org/t/p/w500/bzOlMYEfNmgCDnFHj3zL3RBqwau.jpg","de":"https://image.tmdb.org/t/p/w500/zvfiQaOqNYvy6qVgWuvK71lv91c.jpg","it":"https://image.tmdb.org/t/p/w500/fLHFIx2gJ1vrLnzO7iiBsJdi0Z3.jpg","en":"https://image.tmdb.org/t/p/w500/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg"}'::jsonb WHERE id = 58;
UPDATE public.films SET tmdb_id = 285, titoli_i18n = '{"es":"Piratas del Caribe: En el fin del mundo","en":"Pirates of the Caribbean: At World''s End","it":"Pirati dei Caraibi - Ai confini del mondo","de":"Pirates of the Caribbean - Am Ende der Welt","fr":"Pirates des Caraïbes : Jusqu''au bout du monde"}'::jsonb, trame_i18n = '{"es":"Siguiendo la estela de lo sucedido en “Piratas del caribe: el cofre del hombre muerto”, encontramos a nuestros héroes Will Turner y Elizabeth Swann aliados con el capitán Barbossa, en una búsqueda desesperada para liberar al capitán Jack Sparrow de las manos de Davy Jones. Mientras, el terrorífico barco fantasma, el Holandés Errante, bajo el control de la Compañía de las Indias Orientales, causa estragos a lo largo de los Siete Mares. Will y Elizabeth, navegando en medio de la traición, la felonía y mares salvajes, deben seguir adelante rumbo a Singapur y enfrentarse al astuto pirata chino Sao Feng. Ahora, en los mismísimos confines de la tierra, todos ellos deben elegir un bando en la batalla final, ya que no sólo sus vidas y fortunas, sino también el futuro de la piratería clásica, pende de un hilo...","en":"After losing Captain Jack Sparrow to the locker of Davy Jones, Will Turner, Elizabeth Swann, and Captain Barbossa journey to the ends of the earth to rescue him. And as the East India Trading Company tightens its grip on the seas under Lord Cutler Beckett—now in control of Davy Jones—the fate of piracy hangs by a thread. Now, they must unite the pirate lords for one final stand. But as loyalties are tested and alliances shift, each must ultimately choose where they stand in the battle for freedom on the high seas.","it":"Il capitano Barbossa, Will Turner e Elizabeth Swann si alleano per liberare Jack Sparrow dalla prigionia nello Scrigno di Davy Jones. Nel frattempo, la Compagnia delle Indie Orientali, guidata da Lord Cutler Beckett e con il controllo dell''Olandese Volante, minaccia di eliminare per sempre la pirateria dai mari.","de":"Seitdem Cutler Beckett und die East India Trading Company das Herz von Davy Jones besitzen und so über ihn und seine scheinbar unbesiegbare Flying Dutchman gebieten, machen sie erbarmungslos Jagd auf sämtliche Piraten und deren Sympathisanten. Der hohe Rat der Piraten will sich versammeln, um über eine Taktik zu beratschlagen, doch dafür müssen alle Piratenfürsten anwesend sein - auch Captain Jack Sparrow, der nun in der Unterwelt weilt. Seine Freunde Will Turner und Elizabeth Swann machen sich mit Hilfe des wieder zum Leben erweckten Kapitän Barbossa auf die Suche nach dem Ende der Welt, an dem sich der Eingang zur Unterwelt befindet. Dafür benötigen sie die Hilfe des unbarmherzigen Piratenfürsten Sao Feng...","fr":"L’âge d’or de la piraterie touche à sa fin. Même le terrifiant Vaisseau Fantôme et son capitaine maudit servent Lord Cutler Beckett. Il écume désormais les sept mers, massacrant sans pitié les pirates de tous bords. Une seule chance de résister à Beckett et à son armada : Rassembler les Neuf Seigneurs de la Cour des Frères."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/xHcUMez2b1QiMGQYCuQTAlqwDEe.jpg","en":"https://image.tmdb.org/t/p/w500/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg","it":"https://image.tmdb.org/t/p/w500/wGv9fox3iIA7jrZxTueQnsKqwoE.jpg","de":"https://image.tmdb.org/t/p/w500/ynZqp6JiraskebRAsd9FgJCT9ww.jpg","fr":"https://image.tmdb.org/t/p/w500/3JjceHUzbtgJ4fJs6x2ow4ckH89.jpg"}'::jsonb WHERE id = 59;
UPDATE public.films SET tmdb_id = 1865, titoli_i18n = '{"it":"Pirati dei Caraibi - Oltre i confini del mare","fr":"Pirates des Caraïbes : La Fontaine de jouvence","de":"Pirates of the Caribbean - Fremde Gezeiten","en":"Pirates of the Caribbean: On Stranger Tides","es":"Piratas del Caribe: En mareas misteriosas"}'::jsonb, trame_i18n = '{"it":"Jack Sparrow incontra Angelica, una donna del suo passato che lo costringe a imbarcarsi sulla Queen Anne''s Revenge, la nave del temibile pirata Barbanera. Jack si ritrova così coinvolto in una pericolosa ricerca della leggendaria Fonte della Giovinezza, dovendo fare i conti con spietate sirene, zombie e la flotta rivale spagnola e inglese guidata da Barbossa, ora al servizio del Re.","fr":"Dans cette histoire pleine d’action, où vérité, trahison, jeunesse éternelle et mort forment un cocktail explosif, le capitaine Jack Sparrow retrouve une femme qu’il a connu autrefois. Leurs liens sont‐ils faits d’amour ou, cette femme n’est‐elle qu’une aventurière sans scrupules qui cherche à l’utiliser pour découvrir la légendaire Fontaine de Jouvence ? Lorsqu’elle l’oblige à embarquer à bord du Queen Anne’s Revenge, le bateau du terrible pirate Barbe‐Noire, Jack ne sait plus ce qu’il doit craindre le plus : Le redoutable maître du bateau ou cette femme surgit de son passé…","de":"In Pirates Of The Caribbean – Fremde Gezeiten begegnet Captain Jack Sparrow einer Frau aus seiner Vergangenheit wieder. Angelica heißt die Schöne und Sparrow war in sie verliebt. Oder hat sie ihn nur benutzt? Jedenfalls schickt Angelica den Piraten auf die Suche nach dem sagenumwobenden Jungbrunnen. Dazu muss er an Board der Queen Anne’s Revenge gehen, dem Schiff des gefürchteten Piraten Blackbeards. Captain Jack Sparrow findet sich in Fluch der Karibik 4 wie erwartet in einer abenteuerlichen Geschichte wieder, in der er nicht mehr weiß, wem er vertrauen kann: dem skrupellosen Piraten Blackbeard oder der schönen Frau aus seiner Vergangenheit. Captain Hector Barbossa kann ihm auch nicht wirklich auf die Sprünge helfen, sondern ist eher eine weitere Störung auf der Suche nach dem Jungbrunnen…","en":"When Jack crosses paths with a woman from his past, he''s not sure if it''s love...or if she''s a ruthless con artist using him to find the fabled Fountain of Youth.","es":"Cuando Jack Sparrow vuelve a encontrarse con una mujer a la que había conocido años atrás, no está seguro de si se trata de amor o si ella es una estafadora sin escrúpulos que lo está utilizando para encontrar la legendaria Fuente de la Juventud. A todo esto, Jack es capturado por el Venganza de la Reina Ana, el barco del temible pirata Barbanegra, que lo obliga a unirse a su tripulación, lo que le hará vivir una inesperada aventura en la que no sabe quién le inspira más miedo si Barbanegra o esa mujer que regresa del pasado."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/p0aMDd3EtOCfImHIeL9hgPnLRIo.jpg","fr":"https://image.tmdb.org/t/p/w500/b7bTneo0DkxTcsGN55OxuPCuZtA.jpg","de":"https://image.tmdb.org/t/p/w500/8jhWZt5N0ZuDS9b4g9NYxq13S9R.jpg","en":"https://image.tmdb.org/t/p/w500/keGfSvCmYj7CvdRx36OdVrAEibE.jpg","es":"https://image.tmdb.org/t/p/w500/2oOARbiV871kCC27FyKBmYwOM3G.jpg"}'::jsonb WHERE id = 60;
UPDATE public.films SET tmdb_id = 166426, titoli_i18n = '{"it":"Pirati dei Caraibi - La vendetta di Salazar","fr":"Pirates des Caraïbes : La Vengeance de Salazar","en":"Pirates of the Caribbean: Dead Men Tell No Tales","es":"Piratas del Caribe: La venganza de Salazar","de":"Pirates of the Caribbean - Salazars Rache"}'::jsonb, trame_i18n = '{"it":"Il capitano Jack Sparrow si ritrova al centro di una nuova e mortale caccia quando il terrificante capitano Armando Salazar e la sua ciurma di marinai fantasma fuggono dal Triangolo del Diavolo, decisi a sterminare tutti i pirati dei sette mari e a vendicarsi proprio di Jack. L''unica speranza di salvezza per Sparrow risiede nel leggendario Tridente di Poseidone, un potente artefatto capace di conferire il controllo totale sui mari e spezzare ogni maledizione. Per trovarlo, Jack stringe un''alleanza con Henry Turner, un giovane marinaio della Royal Navy intenzionato a liberare suo padre Will dalla maledizione dell''Olandese Volante, e Carina Smyth, una brillante e coraggiosa astronoma ingiustamente accusata di stregoneria.","fr":"Jack Sparrow et ses compagnons se lancent dans la quête du Trident de Poséidon, sur lequel le Capitaine Teague détient des informations précieuses. Cet artefact légendaire, qui donne tous les pouvoirs sur les océans, est leur seul moyen d''échapper aux fantômes du redoutable Capitaine Salazar, échappés du Triangle des Bermudes pour éliminer tous les pirates des océans.","en":"Thrust into an all-new adventure, a down-on-his-luck Capt. Jack Sparrow feels the winds of ill-fortune blowing even more strongly when deadly ghost sailors led by his old nemesis, the evil Capt. Salazar, escape from the Devil''s Triangle. Jack''s only hope of survival lies in seeking out the legendary Trident of Poseidon, but to find it, he must forge an uneasy alliance with a brilliant and beautiful astronomer and a headstrong young man in the British navy.","es":"El capitán Jack Sparrow se enfrentará a un grupo de piratas-fantasma comandados por una de sus viejas némesis, el terrorífico capitán Salazar, recién escapado del Triángulo de las Bermudas. La única posibilidad de Sparrow para salir con vida es encontrar el legendario Tridente de Poseidón, un poderoso artefacto que le da a su poseedor el control de los mares.","de":"Im neuen Abenteuer gerät Captain Jack Sparrow einmal mehr in große Not, als er auf eine Horde Geister-Piraten trifft, angeführt von Sparrows Nemesis Captain Salazar. Die Untoten sind aus dem Bermuda-Dreieck entkommen, in dem sie gefangen waren, und verfolgen nun nur ein Ziel: Sie wollen alle Piraten töten, zuallererst Jack Sparrow. Dessen einzige Chance liegt nun darin, Poseidons Dreizack zu finden, dessen magische Kräfte die Geister-Piraten erneut bannen können und seinem Besitzer die Kontrolle über die Weltmeere verleihen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/vvglsPQgyGogyTu2e59dJYGlJNE.jpg","fr":"https://image.tmdb.org/t/p/w500/fVMudKQfhosujwgAKhfxNGfS9sL.jpg","en":"https://image.tmdb.org/t/p/w500/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg","es":"https://image.tmdb.org/t/p/w500/AookkwjZfWdigGtaEwy5IfOnBku.jpg","de":"https://image.tmdb.org/t/p/w500/qTyT5kSJ7Jw0iJy7lxyA695XBK8.jpg"}'::jsonb WHERE id = 61;
UPDATE public.films SET tmdb_id = 106646, titoli_i18n = '{"it":"The Wolf of Wall Street","es":"El lobo de Wall Street","en":"The Wolf of Wall Street","fr":"Le Loup de Wall Street","de":"The Wolf of Wall Street"}'::jsonb, trame_i18n = '{"it":"Jordan Belfort è un giovane e ambizioso broker di New York che fonda la Stratton Oakmont, diventando rapidamente milionario grazie a truffe e speculazioni finanziarie spregiudicate. Immerso in un vortice di edonismo, droga e avidità sfrenata, la sua vita di eccessi attira presto l''attenzione dell''FBI. La sua inarrestabile ascesa nel mondo della finanza rischia così di trasformarsi in una rovinosa e inevitabile caduta.","es":"Película basada en hechos reales del corredor de bolsa neoyorquino Jordan Belfort. A mediados de los años 80, Belfort era un joven honrado que perseguía el sueño americano, pero pronto en la agencia de valores aprendió que lo más importante no era hacer ganar a sus clientes, sino ser ambicioso y ganar una buena comisión. Su enorme éxito y fortuna le valió el mote de \"El lobo de Wall Street\". Dinero. Poder. Mujeres. Drogas. Las tentaciones abundaban y el temor a la ley era irrelevante. Jordan y su manada de lobos consideraban que la discreción era una cualidad anticuada; nunca se conformaban con lo que tenían.","en":"A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort''s autobiography.","fr":"Sa licence de courtier en poche, et les narines déjà pleines de cocaïne, Jordan Belfort est prêt à conquérir Wall Street. Ce jour d''octobre, un krach, le plus important depuis 1929, vient piétiner ses rêves de grandeur. C''est finalement à Long Island qu''il échoue et qu''il monte sa propre affaire de courtage. Son créneau : le hors-cote. Sa méthode : l''arnaque. Son équipe : des vendeurs ou des petits trafiquants.","de":"New York in den frühen 1990er Jahren. Der aufstrebende Aktienhändler Jordan Belfort gründet mit Anfang 20 die Maklerfirma \"Stratton Oakmont\", mit der er schnell zum Multimillionär aufsteigt und zum Shootingstar der New Yorker Börse wird. Schon bald ist er hauptsächlich unter seinem neuen Spitznamen \"Wolf of Wall Street\" bekannt. Mit seinem Reichtum finanziert er einen ausschweifenden Lebensstil, der von Alkohol, Drogen, Sex und Dekadenz geprägt ist. Jordans Siegeszug scheint nicht zu stoppen zu sein, doch dies lässt ihn übermütig werden. Von unstillbarer Gier getrieben und mit dem Gefühl der Unbesiegbarkeit im Rücken lassen er und seine \"Wolfsbande\", darunter sein Kumpel Donnie Azoff, sich auf illegale Geschäfte ein. Das zieht schon bald die Aufmerksamkeit der Justiz auf sich, besonders der FBI-Agent Patrick Denham schaut aufmerksam hinter die Fassade von Belforts Firmengeflecht. Als die Gesetzeshüter Jordan langsam auf die Schliche kommen, droht sein gesamtes Kartenhaus einzustürzen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hwg3pXw2m4HfRGbyRMIP8laf5Lf.jpg","es":"https://image.tmdb.org/t/p/w500/uthRoUeTtiep5HCoySlOjQSPCbJ.jpg","en":"https://image.tmdb.org/t/p/w500/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg","fr":"https://image.tmdb.org/t/p/w500/dQIQZbJXn1pflQw3nwvXLJX0dHa.jpg","de":"https://image.tmdb.org/t/p/w500/uuLLAJ9JEJd4o0F9fnJhV1weisr.jpg"}'::jsonb WHERE id = 62;
UPDATE public.films SET tmdb_id = 71066, titoli_i18n = '{"es":"Robin de los Bosques","fr":"Robin des Bois","en":"Robin Hood","de":"Robin Hood","it":"Robin Hood"}'::jsonb, trame_i18n = '{"es":"Ricardo Corazón de León, rey amado y respetado por su pueblo, decide ir a las Cruzadas al frente de su ejército, dejando temporalmente a su hermano, el príncipe Juan (Sam De Grasse), como regente del trono. En ausencia de Ricardo, el príncipe y traicionero Juan gobierna despiadadamente con mano de hierro, convirtiendo Inglaterra en un lugar donde impera la crueldad y la violencia. A está tiranía hará frente el Conde de Huntington, un valiente guerrero que, informado de la situación del país, pondrá en peligro su vida y honor para oponerse al traidor. Por ello, se verá fuera de la ley, teniendo que ejercer como el forajido Robin Hood, campeón de los débiles y oprimidos, que defenderá al pueblo frente al cruel príncipe Juan y tendrá que ocultarse en el bosque de Sherwood.","fr":"Les aventures de Robin des Bois confronté au Prince John. Celui-ci est devenu tyrannique envers son peuple depuis le départ de son père, le Roi Richard.","en":"The dashing Earl of Huntingdon excels in courtly life and jousting before King Richard departs for the Crusades. While away, Richard''s treacherous brother, Prince John, seizes power and inflicts brutal tyranny on the civilians. Huntingdon transforms into the heroic outlaw Robin Hood, gathers his ''merry men'', and battles to restore the true king and protect lovely Lady Marian.","de":"Für seinen Glauben begibt sich König Richard Löwenherz auf einen Kreuzzug. An seiner Stelle soll Prinz John, sein Bruder, das Land regieren. Dieser entpuppt sich als Tyrann, der das Volk unterdrückt und ausbluten lässt. Die schöne Lady Marian schickt eine verzweifelte Nachricht an ihren Geliebten, der mit auf den Kreuzzug gegangen ist. Der Earl of Huntington kehrt zurück und muss mit Entsetzen feststellen, was in seiner Abwesenheit geschehen ist. Um unerkannt zu bleiben, beginnt er als Robin Hood für Gerechtigkeit zu sorgen. Schnell wird er zum Volkshelden, dem die Häscher des Regenten stets dicht auf den Fersen sind.","it":"Il Conte di Huntingdon parte per la Terza Crociata insieme a Re Riccardo Cuor di Leone. Durante la loro assenza, il perfido Principe Giovanni usurpa il trono d''Inghilterra instaurando un regime di terrore ed estorsione ai danni del popolo. Informato delle ingiustizie, il Conte torna in patria sotto le spoglie del fuorilegge Robin Hood e si rifugia nella foresta di Sherwood. Insieme alla sua banda di fedeli compagni, comincia a rubare ai ricchi per dare ai poveri, combattendo il tiranno per proteggere la sua amata Lady Marian e attenderne il ritorno del legittimo re."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg","fr":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg","en":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg","de":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg","it":"https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg"}'::jsonb WHERE id = 63;
UPDATE public.films SET tmdb_id = 10907, titoli_i18n = '{"it":"La leggenda di Robin Hood","en":"The Adventures of Robin Hood","de":"Die Abenteuer des Robin Hood","es":"Robin de los Bosques","fr":"Les Aventures de Robin des Bois"}'::jsonb, trame_i18n = '{"it":"Robin di Locksley, un nobile sassone, si ribella contro l''usurpatore Principe Giovanni, che ha preso il controllo dell''Inghilterra approfittando della prigionia di Re Riccardo Cuor di Leone. Rifugiatosi nella foresta di Sherwood con una banda di fuorilegge, Robin ruba ai ricchi normanni per dare ai poveri sassoni oppressi, conquistando anche il cuore di Lady Marian e lottando per il ritorno del legittimo sovrano.","en":"Robin Hood fights nobly for justice against the evil Sir Guy of Gisbourne while striving to win the hand of the beautiful Maid Marian.","de":"Als Robin von Locksley erfährt, dass Prinz John seinem Bruder Richard Löwenherz den Thron von England rauben will, flieht er in den Sherwood Forest, wo er bald seine Truppe von getreuen Gesetzlosen um sich sammelt, um es John, dem grausamen Guy von Gisbourne und dem Sheriff von Nottingham, heimzuzahlen. Nebenbei bemüht er sich natürlich auch noch um seine Jugendliebe Marian.","es":"Robin de Locksey regresa a Inglaterra tras combatir contra los infieles en las Cruzadas, pero Juan sin Tierra, el hermano del Rey Ricardo I, ha usurpado el trono y gobierna como un tirano, por lo que el noble sajón decide refugiarse en el bosque de Sherwood y luchar contra él para devolverle la corona a Ricardo.","fr":"Alors que le prince Jean, aidé de son bras droit, l''infâme Guy de Gisbourne, règne sur l''Angleterre, Robin de Loxley proclame sa fidélité à Richard Coeur de Lion, retenu prisonnier en Autriche. Dépossédé de ses biens par le prince Jean, Robin, que l''on nomme désormais Robin des Bois, a formé avec quelques hommes audacieux et courageux une bande de hors-la-loi, qui assaillent et dévalisent sans relâche les hommes du prince. L''attaque d''un convoi d''or conduit par Guy de Gisbourne permet à Robin de nouer de tendres liens avec lady Marian, la filleule du roi Richard, dont les beaux yeux s''ouvrent soudain sur la misère des Saxons et l''arrogance des Normands…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ks9KEeASeyeOFDnwbOBW9WDIbfE.jpg","en":"https://image.tmdb.org/t/p/w500/c7LX3GMf9uXQTgVm3uxpm7E6Woc.jpg","de":"https://image.tmdb.org/t/p/w500/fWXhBHv0HsRYl5j47HbkgWoGe3s.jpg","es":"https://image.tmdb.org/t/p/w500/bCXYN015wb10UTPgXZxcd2RAjBI.jpg","fr":"https://image.tmdb.org/t/p/w500/5wZdLyo6SEV7L1g5gF3VcOIHilM.jpg"}'::jsonb WHERE id = 64;
UPDATE public.films SET tmdb_id = 10786, titoli_i18n = '{"en":"Robin and Marian","es":"Robin y Marian","de":"Robin und Marian","fr":"La Rose et la Flèche","it":"Robin e Marian"}'::jsonb, trame_i18n = '{"en":"Robin Hood, aging none too gracefully, returns exhausted from the Crusades to woo and win Maid Marian one last time.","es":"Desilusionados por los años que perdieron luchando como cruzados en Tierra Santa, Robin Hood y su amigo Little John regresan a Inglaterra y se dan cuenta de que todo ha vuelto a ser como antes.","de":"Um 1190. Seit zwanzig Jahren ziehen Robin Hood und sein treuer Freund Little John für den machtgierigen König Richard Löwenherz auf Kreuzzügen durch die halbe Welt. Als sie in Frankreich eine Burg plündern sollen, in der Richard einen Goldschatz vermutet, die jedoch nur noch von einem Greis, Frauen und Kindern bewohnt wird, weigert sich Robin, den Befehl auszuführen. Der König ist außer sich und befiehlt seine Hinrichtung. Doch bevor es dazu kommen kann, trifft der Greis Richard Löwenherz mit einem Pfeil. Wenige Tage später stirbt er an Wundbrand.","fr":"Après des années d''exil, Robin des Bois revient avec son fidèle ami Petit Jean à Sherwood. Dame Marianne est entrée au couvent, le Roi Richard et son frère Jean sont devenus fous, le temps de l''aventure semble définitivement terminé pour le valeureux cambrioleur. Mais le shérif de Nottingham revient troubler la paix de Sherwood. Afin de se battre contre l''opression et la terreur qu''inspire le shérif aux habitants, Robin rassemble ses vieux amis.","it":"Un invecchiato Robin Hood ritorna in Inghilterra dopo vent''anni trascorsi a combattere nelle Crociate al seguito di Re Riccardo. Trova la sua amata Marian che, nel frattempo, si è ritirata in convento diventando badessa. Nonostante il tempo trascorso e le ferite della vita, il loro antico amore si riaccende. Tuttavia, Robin si ritrova ben presto a dover affrontare nuovamente il suo storico avversario, lo Sceriffo di Nottingham, in un ultimo e tragico scontro che segnerà il destino dei due amanti."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/y2UlVt6U8mFeegVL42rZjD5y6c7.jpg","es":"https://image.tmdb.org/t/p/w500/eRaYiNt0piwfB1LdeUJnMnFcxXs.jpg","de":"https://image.tmdb.org/t/p/w500/vIyA3bNfZj1aThwkGjtyTVUfRA2.jpg","fr":"https://image.tmdb.org/t/p/w500/yNSnZAgKFgJ8Qdnf69nUReXJDXk.jpg","it":"https://image.tmdb.org/t/p/w500/2gTw2pwqUNtdnfWb2elA1HvmmNx.jpg"}'::jsonb WHERE id = 65;
UPDATE public.films SET tmdb_id = 8367, titoli_i18n = '{"es":"Robin Hood. Príncipe de los ladrones","en":"Robin Hood: Prince of Thieves","it":"Robin Hood - Principe dei ladri","de":"Robin Hood - König der Diebe","fr":"Robin des Bois, prince des voleurs"}'::jsonb, trame_i18n = '{"es":"Robin Hood regresa a su país de origen, cansado tras haber pasado los últimos cinco años luchando en las Cruzadas. A su vuelta se topa con el terror de la población ante el gobierno déspota del hermano Juan del rey Ricardo Corazón de León, un tirano que está en el poder, aprovechando la ausencia de éste. El guerrero, ante esta situación, jura defender a los pobres y para ello se une a las bandas de proscritos que han tomado el bosque de Sherwood como su único hogar libre.","en":"Nobleman crusader Robin of Locksley breaks out of a Jerusalem prison with the help of Moorish fellow prisoner Azeem and travels back home to England. But upon arrival he discovers his dead father in the ruins of his family estate, killed by the vicious sheriff of Nottingham, Robin and Azeem join forces with outlaws Little John and Will Scarlett to save the kingdom from the sheriff''s villainy.","it":"Robin di Locksley ritorna in Inghilterra dopo essere fuggito dalla prigionia a Gerusalemme durante le Crociate. Trova la sua terra natale oppressa dal tirannico Sceriffo di Nottingham, che ha fatto assassinare suo padre. Rifugiatosi nella foresta di Sherwood, Robin si unisce a una banda di fuorileggi e, affiancato dal fedele amico saraceno Azeem, assume la guida della ribellione per sconfiggere lo Sceriffo, salvare la bella Lady Marian e restituire la giustizia al popolo oppresso.","de":"Jerusalem im Jahre 1194: die Kreuzzüge im Heiligen Land haben die Gefängnisse der Stadt mit englischen Rittern gefüllt, unter denen sich auch der junge britische adelige Robin von Locksley befindet. Durch Zufall gelingt ihm gemeinsam mit dem ebenfalls zum Tode verurteilten Azeem die Flucht. Die Beiden machen sich auf den Weg in Robins englische Heimat. Dort angekommen muss Robin feststellen, dass inzwischen der machtgierige Sheriff von Nottingham die Herrschaft über das Land übernommen hat. Er führt ein brutales Regime, unterdrückt die Armen und treibt auf brutale Weise immer höher werdende Steuern ein. Gemeinsam mit den in den Wäldern lebenden Gesetzlosen setzt Robin zum Gegenschlag an: Er formt eine schlagkräftige Truppe aus den Waldbewohnern und kämpft von nun an für Gerechtigkeit und gegen den Sheriff und seine Männer, die das Land tyrannisieren …","fr":"XIIème siècle, en Angleterre. En l''absence du roi Richard, le shérif de Nottingham règne en tyran sur le pays, aidé par son cousin Guy de Gisbourne, la sorcière Mortianna et le corrompu évêque de Hereford. Lors de son retour en Angleterre aux côtés d''Azeem, Robin revient au château de son père. Mais ce dernier a été tué par les hommes du shérif après avoir refusé de se joindre à eux. Robin jure de venger son père."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/b0pJ0SZ9xAEpqo0tx7WOQ9xv8Ns.jpg","en":"https://image.tmdb.org/t/p/w500/hbRnWUNJkKKVN5mkcuC5ooqjE4e.jpg","it":"https://image.tmdb.org/t/p/w500/2l7W3jvfiVfmpJDPpfJWg2YBGJm.jpg","de":"https://image.tmdb.org/t/p/w500/d48KIeuz1eO56onjHrWx29Oilnr.jpg","fr":"https://image.tmdb.org/t/p/w500/rOdM5PqRLLMjS8DaN5dnsU4b5Fp.jpg"}'::jsonb WHERE id = 66;
UPDATE public.films SET tmdb_id = 8005, titoli_i18n = '{"it":"Robin Hood - Un uomo in calzamaglia","es":"Las locas, locas aventuras de Robin Hood","fr":"Sacré Robin des bois","de":"Robin Hood - Helden in Strumpfhosen","en":"Robin Hood: Men in Tights"}'::jsonb, trame_i18n = '{"it":"Tornato in Inghilterra dopo essere fuggito da una prigione a Gerusalemme durante le crociate, il nobile Robin di Locksley trova il suo castello confiscato e il paese sotto il giogo oppressivo del vile principe Giovanni e del goffo sceriffo di Ruttingham. Deciso a ristabilire la giustizia, Robin recluta un improbabile gruppo di fuorilegge nella foresta di Sherwood, gli ''Uomini in calzamaglia''. Tra frecce telecomandate, numeri musicali e situazioni demenziali, Robin tenterà di rovesciare il tiranno e conquistare il cuore della bella Lady Marian, la quale custodisce gelosamente la propria virtù protetta da una quasi indistruttibile cintura di castità.","es":"Robin de Loxley es un valiente arquero de la Edad Media que regresa a Inglaterra. El reino está bajo el poder del avaricioso rey Juan, que no hacer más que subir los impuestos a los empodrecidos habitantes.Robin robará a los ricos para dárselo a los pobres, a la ves que vive numerosas aventuras.","fr":"Pendant que le peuple subit l''oppression du prince Jean, Robin des Bois vole aux riches pour donner aux pauvres dans cette parodie du célèbre conte signée Mel Brooks.","de":"Robin von Loxley wird bei den Kreuzzügen unter König Richards Fahne gefangen genommen und ins Verlies gesperrt. Mit Hilfe eines arabischen Mitgefangenen namens El Niesreiz gelingt ihm die Flucht. Beim Abschied verspricht er ihm, sich um dessen Sohn Hatschi zu kümmern, der sich zur als Austauschstudent in England aufhält. Während König Richard auf den Kreuzzügen war, hat sich dessen Bruder, der kaltherzige Prinz John selber zum Alleinherrscher über England ernannt. Mit Unterstützung des skrupellosen Sheriffs von Nuttingham unterdrückt er das arme Volk und beutet es nach Strich und Faden aus. Als Robin zu seinem Schloss zurückkehrt, erfährt von Blinzler dass seine Eltern gestorben sind. Gemeinsam mit Little John und Will stellt er sich den reichen Emporkömmlingen.","en":"Robin Hood comes home after fighting in the Crusades to learn that the noble King Richard is in exile and that the despotic King John now rules England, with the help of the Sheriff of Rottingham. Robin Hood assembles a band of fellow patriots to do battle with King John and the Sheriff."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zqPpJmTjgTjMwCjCqb4PaAZovom.jpg","es":"https://image.tmdb.org/t/p/w500/5Fgy9DD8LMCb6QKzTy18rY7Tts5.jpg","fr":"https://image.tmdb.org/t/p/w500/a2zVlgn1AvVjfT6GLsCpFN9T5kj.jpg","de":"https://image.tmdb.org/t/p/w500/cGLsbxMh8KMiwn3aWnn754ra5do.jpg","en":"https://image.tmdb.org/t/p/w500/woexOLEkUlYsPLLuZRK6LjZaF38.jpg"}'::jsonb WHERE id = 67;
UPDATE public.films SET tmdb_id = 375588, titoli_i18n = '{"en":"Robin Hood","it":"Robin Hood - L''origine della leggenda","fr":"Robin des Bois","de":"Robin Hood","es":"Robin Hood"}'::jsonb, trame_i18n = '{"en":"A war-hardened Crusader and his Moorish commander mount an audacious revolt against the corrupt English crown.","it":"Tornato in Inghilterra dopo aver combattuto nelle Crociate, il nobile Robin di Loxley scopre che la sua casa è stata confiscata e che la contea di Nottingham è caduta sotto il giogo del corrotto Sceriffo. Insieme a Little John, un comandante moro conosciuto in guerra, Robin decide di combattere le ingiustizie. Addestrato nel combattimento furtivo e nell''uso dell''arco, Robin assume l''identità dell''incappucciato ''Robin Hood'' per rubare il denaro dello Sceriffo, guidare una rivolta popolare e riconquistare il suo amore, Marian.","fr":"Récit des débuts de Robin des Bois et de la formation du gang de Sherwood. Robin de Loxley, combattant aguerri revenu des croisades, et un chef maure prennent la tête d’une audacieuse révolte contre la corruption des institutions.","de":"Robin Hood hat in den Kreuzzügen gekämpft, doch als er in seine Heimat zurückkehrt, erkennt er das Land nicht wieder: England ist zu einer von Korruption und Intrigen gezeichneten Gesellschaft geworden, die Reichen schwelgen in Luxus, während es bei den Armen kaum zum Überleben reicht. Robin beschließt, dass er nicht länger wegschauen kann, und nimmt – ausgerüstet mit Maske, Pfeil und Bogen – den Kampf gegen die Ungerechtigkeit im Land und die tyrannische Oberschicht auf. Dabei findet er mit Little John einen Verbündeten und verliebt sich in die ebenso schöne wie willensstarke Marian. Doch die herrschende Klasse will Robins Raubzüge und seinen Kampf für Gerechtigkeit nicht einfach hinnehmen und setzt den gnadenlosen Sheriff von Nottingham auf ihn an …","es":"Cuando el joven Robin Hood (Taron Egerton) regresa a su hogar, endurecido, tras luchar como guerrero en Las Cruzadas, descubre un reino en el que la corrupción es la moneda de cambio de la corona inglesa. En ese momento, junto a su compañero Little John (Jamie Foxx), toma la decisión de formar una banda de bandidos y liderar una audaz rebelión en la que se enfrentarán al malvado Sheriff de Nottingham (Ben Mendelsohn)."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/AiRfixFcfTkNbn2A73qVJPlpkUo.jpg","it":"https://image.tmdb.org/t/p/w500/9kJzfDEl8zVBvNtiqpXZBsS8XDk.jpg","fr":"https://image.tmdb.org/t/p/w500/tSls6dSMuXz7AHjDuuFvRaNbxHx.jpg","de":"https://image.tmdb.org/t/p/w500/9Cm7Ue54ONtK3sCEoXR4RZyMC75.jpg","es":"https://image.tmdb.org/t/p/w500/tSxcUPAC1ihAtDpAQX2rydOucns.jpg"}'::jsonb WHERE id = 68;
UPDATE public.films SET tmdb_id = 20662, titoli_i18n = '{"it":"Robin Hood","en":"Robin Hood","fr":"Robin des Bois","es":"Robin Hood","de":"Robin Hood"}'::jsonb, trame_i18n = '{"it":"Nell''Inghilterra del XIII secolo, dopo la morte di re Riccardo Cuor di Leone, l''arciere Robin Longstride torna in patria dalla Francia. Giunto a Nottingham, assume l''identità del defunto cavaliere Robert Loxley e si innamora della vedova Marion. Di fronte alla minaccia di un''invasione francese e alla tirannia del nuovo re Giovanni, Robin unisce i baroni ribelli e il popolo per difendere il paese, gettando le basi per la nascita della leggenda di Robin Hood.","en":"When soldier Robin happens upon the dying Robert of Loxley, he promises to return the man''s sword to his family in Nottingham. There, he assumes Robert''s identity; romances his widow, Marion; and draws the ire of the town''s sheriff and King John''s henchman, Godfrey.","fr":"À l’aube du treizième siècle, Robin Longstride, humble archer au service de la Couronne d’Angleterre, assiste, en Normandie, à la mort de son monarque, Richard Cœur de Lion, tout juste rentré de la Troisième Croisade et venu défendre son royaume contre les Français. De retour en Angleterre et alors que le prince Jean, frère cadet de Richard et aussi inepte à gouverner qu’obnubilé par son enrichissement personnel, prend possession du trône, Robin se rend à Nottingham où il découvre l’étendue de la corruption qui ronge son pays. Il se heurte au despotique shérif du comté, mais trouve une alliée et une amante en la personne de la belle et impétueuse Lady Marianne, qui avait quelques raisons de douter des motifs et de l’identité de ce croisé venu des bois.","es":"Inglaterra, siglo XIII. Robin Longstride, un magnífico arquero al servicio del rey Ricardo Corazón de León, vuelve de las cruzadas en tierra santa saqueando poblados mientras lucha contra las tropas francesas. Cuando Ricardo muere bajo una fecha francesa, Robin se traslada a Nottingham con el objetivo de cumplir una promesa que hizo a Sir Robert Loxley antes de morir: devolver una espada a su padre, Sir Walter Loxley. Allí conoce a lady Marion, su viuda, una mujer con carácter. Mientras tanto, en un país debilitado por una larga guerra, regido por Juan, un rey débil y poco eficaz, contra las rebeliones internas y las amenazas externas maquinadas por el pérfido Godfrey, Robin y sus hombres se dejan llevar hacia una aventura mayor: deciden ayudar a impedir que el país caiga irremediablemente en una sangrienta guerra civil, y devolver la gloria a Inglaterra.","de":"Nach dem Tode König Richards lässt der begnadete Bogenschütze Robin den Krieg gegen die Franzosen hinter sich und kehrt zurück nach England, in ein durch Korruption und einen brutalen Sheriff gebeuteltes Nottingham. Schnell verliebt er sich in die willensstarke Witwe Lady Marion, die anfangs allerdings überaus skeptisch ist, was ihn und seine Beweggründe angeht. Nicht zuletzt um ihre Hand zu gewinnen, versammelt er eine Truppe Gleichgesinnter und gemeinsam mit seinen Männern macht er dem Sheriff einen Strich durch seine gierige Rechnung und macht jagt auf die Reichen, wobei er die Beute an die Armen verteilt. Doch seine von Jahrzehnten des Krieges geschwächte Heimat hält noch eine weitaus größere Aufgabe für Robin parat. So machen sich ausgerechnet dieser unwahrscheinlichste aller Helden und seine Verbündeten auf, einen blutigen Bürgerkrieg zu verhindern und England wieder zu neuem Ruhm und Glanz zu verhelfen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/dXIFYV8PR8WS5nnxspSFnMdZIGZ.jpg","en":"https://image.tmdb.org/t/p/w500/9NS5QGOfck24yL3bZqWeW06PgPC.jpg","fr":"https://image.tmdb.org/t/p/w500/77ibaylBuzhqfFBKQ2qStQUeLyM.jpg","es":"https://image.tmdb.org/t/p/w500/8jI4VDUWPVM4I91xBhObCLMQhnM.jpg","de":"https://image.tmdb.org/t/p/w500/3u492UeXuQMFDTOrHenpLOMwb6t.jpg"}'::jsonb WHERE id = 69;
UPDATE public.films SET tmdb_id = 1891, titoli_i18n = '{"it":"Star Wars: Episodio V - L''Impero colpisce ancora","en":"The Empire Strikes Back","es":"El imperio contraataca","fr":"L''Empire contre-attaque","de":"Das Imperium schlägt zurück"}'::jsonb, trame_i18n = '{"it":"Mentre l''Impero contrattacca duramente contro l''Alleanza Ribelle, Luke Skywalker inizia l''addestramento Jedi sotto la guida del maestro Yoda. Nel frattempo, i suoi amici vengono braccati da Darth Vader attraverso la galassia.","en":"The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.","es":"Tras un ataque sorpresa de las tropas imperiales a las bases camufladas de la alianza rebelde, Luke Skywalker, en compañía de R2D2, parte hacia el planeta Dagobah en busca de Yoda, el último maestro Jedi, para que le enseñe los secretos de la Fuerza. Mientras, Han Solo, la princesa Leia, Chewbacca, y C3PO esquivan a las fuerzas imperiales y piden refugio al antiguo propietario del Halcón Milenario, Lando Calrissian, en la ciudad minera de Bespin, donde les prepara una trampa urdida por Darth Vader.","fr":"Malgré la destruction de l’Étoile Noire, l''Empire maintient son emprise sur la galaxie, et poursuit sans relâche sa lutte contre l''Alliance rebelle. Basés sur la planète glacée de Hoth, les rebelles essuient un assaut des troupes impériales. Parvenus à s''échapper, la princesse Leia, Han Solo, Chewbacca et C-3P0 se dirigent vers Bespin, la cité des nuages gouvernée par Lando Calrissian, ancien compagnon de Han. Suivant les instructions d''Obi-Wan Kenobi, Luke Skywalker se rend quant à lui vers le système de Dagobah, planète marécageuse où il doit recevoir l''enseignement du dernier maître Jedi, Yoda. Apprenant l''arrestation de ses compagnons par les stormtroopers de Dark Vador après la trahison de Lando, Luke décide d''interrompre son entraînement pour porter secours à ses amis et affronter le sombre seigneur Sith...","de":"Nach der Zerstörung des Todessterns geht der Kampf zwischen den Rebellen und dem herrschenden Imperium weiter. Die Rebellen haben sich auf den Eisplaneten Hoth zurückgezogen, doch das Imperium spürt sie auf und zerstört nach hartem Kampf die dortige Basis. Daraufhin teilen sich unsere Freunde auf: Luke gerät mit R2-D2 auf den Sumpfplaneten Dagobah, wo er von dem alten Jedi-Meister Yoda eine Ausbildung im Umgang mit der Macht erhält, während Leia, Han Solo und die anderen sich nach Bespin durchschlagen, wo in einer Wolkenstadt ein alter Freund von Han residiert. Doch dort geraten sie in eine Falle des Imperiums, und Luke muß ihnen zu Hilfe kommen und Darth Vader zu einem Duell herausfordern..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/6vzDHECuUbKiqSSXHcIKb9LPcQs.jpg","en":"https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg","es":"https://image.tmdb.org/t/p/w500/eU7KcNAOeZj9PBIcGUMSsuJz8qj.jpg","fr":"https://image.tmdb.org/t/p/w500/qDvctAykmNWAmi9G2GrVrwWx3pr.jpg","de":"https://image.tmdb.org/t/p/w500/mi08uIh7ZqYlJEMrc5l2986geSU.jpg"}'::jsonb WHERE id = 71;
UPDATE public.films SET tmdb_id = 1892, titoli_i18n = '{"it":"Star Wars: Episodio VI - Il ritorno dello Jedi","en":"Return of the Jedi","es":"El retorno del Jedi","de":"Die Rückkehr der Jedi-Ritter","fr":"Le Retour du Jedi"}'::jsonb, trame_i18n = '{"it":"I Ribelli intraprendono una missione decisiva per distruggere la seconda Morte Nera e sconfiggere l''Imperatore. Luke affronta per l''ultima volta Darth Vader nel tentativo di redimere il padre caduto nel Lato Oscuro.","en":"Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, the Emperor prepares to crush the Rebellion with a more powerful Death Star, and the Rebel fleet mounts a massive attack on the space station. Luke Skywalker confronts Darth Vader in a final climactic duel before the evil Emperor.","es":"Luke Skywalker y la princesa Leia deben viajar a Tatooine para liberar a Han Solo. Para conseguirlo, deben infiltrarse en la peligrosa guarida de Jabba the Hutt, el gángster más temido de la galaxia. Una vez reunidos, el equipo recluta a tribus de Ewoks para combatir a las fuerzas imperiales en los bosques de la luna de Endor. Mientras tanto, el Emperador y Darth Vader conspiran para convertir a Luke al lado oscuro, pero el joven Skywalker, por su parte, está decidido a reavivar el espíritu del Jedi en su padre. La guerra civil galáctica culmina en un último enfrentamiento entre las fuerzas rebeldes unificadas y una segunda Estrella de la Muerte, indefensa e incompleta, en una batalla que decidirá el destino de la galaxia.","de":"Wesen aus allen Ecken der Galaxis treffen die Vorbereitungen für die entscheidende Schlacht gegen die Streitkräfte des Imperiums. Ziel der Aktion ist die totale Zerstörung des zweiten Todessterns, dessen unvorstellbare Feuerkraft ganze Planeten vernichten kann. Inzwischen ist Han Solo immer noch in der Wüstenfestung des mächtigsten und skrupellosesten Verbechers des Universums, Jabba the Hutt, gefangen. Luke Skywalker gelingt es schließlich zusammen mit seinen Gefährten Prinzessin Leia, Chewbacca und Lando Calrissian, sowie den beiden Robotern C3PO und R2D2 mit Han zu fliehen. Aber Luke steht die schwerste Prüfung noch bevor: Während auf dem Waldmond Endor und beim Todesstern die alles entscheidende Schlacht entbrennt, muß er sich seinem Erzfeind Darth Vader zu einem Zweikampf auf Leben und Tod stellen...","fr":"L''Empire galactique est plus puissant que jamais : la construction de la nouvelle arme, l’Étoile de la Mort, menace l''univers tout entier... Arrêté après la trahison de Lando Calrissian, Han Solo est remis à l''ignoble contrebandier Jabba Le Hutt par le chasseur de primes Boba Fett. Après l''échec d''une première tentative d''évasion menée par la princesse Leia, également arrêtée par Jabba, Luke Skywalker et Lando parviennent à libérer leurs amis. Han, Leia, Chewbacca, C-3PO et Luke, devenu un Jedi, s''envolent dès lors pour une mission d''extrême importance sur la lune forestière d''Endor, afin de détruire le générateur du bouclier de l’Étoile de la Mort et permettre une attaque des pilotes de l''Alliance rebelle. Conscient d''être un danger pour ses compagnons, Luke préfère se rendre aux mains de Dark Vador, son père et ancien Jedi passé du côté obscur de la Force."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/rMcCqpaWEUBmATmpZilDTKOyVbL.jpg","en":"https://image.tmdb.org/t/p/w500/jQYlydvHm3kUix1f8prMucrplhm.jpg","es":"https://image.tmdb.org/t/p/w500/rKMmXzdm7eRgmlwYo7iq3klT7wJ.jpg","de":"https://image.tmdb.org/t/p/w500/xwwbeCWW1jMSDPfRPJp8X4oySPr.jpg","fr":"https://image.tmdb.org/t/p/w500/tEQlCGiiWvMvfD7Sz8d99Pouy39.jpg"}'::jsonb WHERE id = 72;
UPDATE public.films SET tmdb_id = 1893, titoli_i18n = '{"it":"Star Wars: Episodio I - La minaccia fantasma","fr":"Star Wars, épisode I - La Menace fantôme","es":"La guerra de las galaxias. Episodio I: La amenaza fantasma","en":"Star Wars: Episode I - The Phantom Menace","de":"Star Wars: Episode I - Die dunkle Bedrohung"}'::jsonb, trame_i18n = '{"it":"Due cavalieri Jedi scoprono il giovane e straordinariamente dotato Anakin Skywalker mentre tentano di sventare l''invasione del pacifico pianeta Naboo. Nel frattempo, una minaccia creduta estinta da millenni, i Sith, fa la sua ricomparsa.","fr":"Il y a bien longtemps, dans une galaxie très lointaine... La République connaît de nombreux tourments : la corruption fait vaciller ses bases, le Sénat s''embourbe dans des discussions politiques sans fin et de nombreux pouvoirs dissidents commencent à émerger, annonçant la chute d''un système autrefois paisible. Puissante et intouchable, la Fédération du Commerce impose par la force la taxation des routes commerciales. Refusant de céder, la pacifique planète Naboo, dirigée par la jeune Reine Amidala, subit un blocus militaire de la Fédération. Dépêchés par le Sénat pour régler cette affaire, les chevaliers Jedi Qui-Gon Jinn et Obi-Wan Kenobi découvrent qu''une véritable offensive de la Fédération est imminente. Libérant la Reine et ses proches, ils quittent la planète mais doivent se poser sur Tatooine pour réparer leur vaisseau...","es":"La Federación de Comercio ha bloqueado el pequeño planeta de Naboo, gobernado por la joven Reina Amidala, como parte de un plan ideado por Sith Darth Sidious, que manteniéndose en el anonimato dirige a los neimoidianos, que están al mando de la Federación. Amidala es convencida por los Jedis Qui-Gon Jinn y su aprendiz, o padawan, Obi-Wan Kenobi a viajar hasta Coruscant, capital de la República y sede del Consejo Jedi para intentar mediar esta amenaza. Pero esquivando el bloqueo, la nave real resulta dañada, obligando a la tripulación a aterrizar en el desértico y remoto planeta de Tatooine...","en":"Anakin Skywalker, a young slave strong with the Force, is discovered on Tatooine. Meanwhile, the evil Sith have returned, enacting their plot for revenge against the Jedi.","de":"Nachdem der friedliche Planet Naboo von der Handelsföderation angegriffen wurde, müssen die Jedi-Ritter Qui-Gon Jinn und Obi-Wan Kenobi gemeinsam mit Königin Amidala auf dem Wüstenplaneten Tatooine notlanden. Dort bekommen sie Hilfe von Anakin Skywalker, einem Sklavenjungen, in dem die Macht ungewöhnlich stark ist. Als es Königin Amidala nicht gelingt, den Senat gegen die Handelsföderation zu mobilisieren, kehrt sie mit den Jedi-Rittern und Anakin nach Naboo zurück, um den Kampf allein fortzusetzen. Eine gewaltige Schlacht beginnt!"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/iHitEFiK8udC0GcsWUU6szWzc5K.jpg","fr":"https://image.tmdb.org/t/p/w500/fpEC910v5DrMvZteRNlKzXeHiHY.jpg","es":"https://image.tmdb.org/t/p/w500/4rjatbWmGGmu0DZs6WNpXaUWqWN.jpg","en":"https://image.tmdb.org/t/p/w500/6wkfovpn7Eq8dYNKaG5PY3q2oq6.jpg","de":"https://image.tmdb.org/t/p/w500/4e0X8XDjgLu3H2iKiCz44WEl7dA.jpg"}'::jsonb WHERE id = 73;
UPDATE public.films SET tmdb_id = 1894, titoli_i18n = '{"es":"La guerra de las galaxias. Episodio II: El ataque de los clones","en":"Star Wars: Episode II - Attack of the Clones","de":"Star Wars: Episode II - Angriff der Klonkrieger","it":"Star Wars: Episodio II - L''attacco dei cloni","fr":"Star Wars, épisode II - L''Attaque des clones"}'::jsonb, trame_i18n = '{"es":"Corren tenebrosos tiempos para la República. Ésta continúa envuelta en luchas y sumida en el caos. Un movimiento separatista, formado por centenares de planetas y poderosas alianzas y y lideradas por el misterioso conde Dooku, abre nuevas amenazas para la galaxia, a la que ni siquiera los Jedi parecen poder poner freno. Estas maniobras, planeadas hace mucho por una poderosa fuerza, conducen al estallido de las guerras clones y al principio del fin de la República. Para allanar el camino, los separatistas intentan asesinar a la senadora Padme Amidala. Para evitar futuros atentados, su seguridad es encomendada a dos caballeros Jedi...","en":"Following an assassination attempt on Senator Padmé Amidala, Jedi Knights Anakin Skywalker and Obi-Wan Kenobi investigate a mysterious plot into the heart of the Separatist movement and the beginning of the Clone Wars.","de":"Der junge Jedi-Schüler Anakin Skywalker beginnt sich allmählich zu einem grossen und ernstzunehmenden Jediritter zu entwickeln, der unter der Führung von Obi Wan-Kenobi steht. Jedoch hat er auch seine Problemzonen - diese bestehen aus der eigenen Arroganz, seiner nicht wissentlich vorhandenen grenzenlosen Macht, und der ihm verbotenen Liebe zu Königin Amidala. Auf diese werden kurz vor wichtigen Entscheidungen im Senat der Republik mehrere Attentate verübt, die jedoch vereitelt werden können. Daraufhin teilen sich Anakin und Obi-Wan auf: während Anakin auf Amidala aufpaßt, verfolgt Kenobi den Attentäter Jango Fett. Er kommt einer erschaffenen Klon-Armee auf die Spur, die mittels mysteriösem Auftrag geschaffen wurde und findet in dem ehemaligen Jedi Count Dooku einen neuen Gegner für die Hüter der Macht...","it":"Anakin Skywalker, ormai cresciuto, viene incaricato di proteggere la senatrice Padmé Amidala da una serie di attentati, mentre tra i due sboccia un amore proibito. Nel frattempo, Obi-Wan Kenobi scopre la creazione di un misterioso esercito di cloni pronto a combattere i separatisti.","fr":"Depuis le blocus de la planète Naboo par la Fédération du commerce, la République, gouvernée par le Chancelier Palpatine, connaît une véritable crise. Un groupe de dissidents, mené par le sombre Jedi comte Dooku, manifeste son mécontentement envers le fonctionnement du régime. Le Sénat et la population intergalactique se montrent pour leur part inquiets face à l''émergence d''une telle menace.Certains sénateurs demandent à ce que la République soit dotée d''une solide armée pour empêcher que la situation ne se détériore davantage. Parallèlement, Padmé Amidala, devenue sénatrice, est menacée par les séparatistes et échappe de justesse à un attentat. Le Padawan Anakin Skywalker est chargé de sa protection. Son maître, Obi-Wan Kenobi, part enquêter sur cette tentative de meurtre et découvre la constitution d''une mystérieuse armée de clones..."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/pwwBIUqVSWrCBuUAvbaNdf7VajF.jpg","en":"https://image.tmdb.org/t/p/w500/oZNPzxqM2s5DyVWab09NTQScDQt.jpg","de":"https://image.tmdb.org/t/p/w500/q090XcaB783cXdRBOU9TfsmGGP8.jpg","it":"https://image.tmdb.org/t/p/w500/zW4eR9utiKPnTHcIP4xuy0t09nT.jpg","fr":"https://image.tmdb.org/t/p/w500/3nqpcTkODCBhuKuDQJ1dtRhgTqZ.jpg"}'::jsonb WHERE id = 74;
UPDATE public.films SET tmdb_id = 1895, titoli_i18n = '{"en":"Star Wars: Episode III - Revenge of the Sith","it":"Star Wars: Episodio III - La vendetta dei Sith","es":"La guerra de las galaxias. Episodio III: La venganza de los Sith","de":"Star Wars: Episode III - Die Rache der Sith","fr":"Star Wars, épisode III - La Revanche des Sith"}'::jsonb, trame_i18n = '{"en":"When the sinister Sith unveil a thousand-year-old plot to rule the galaxy, the Republic crumbles and from its ashes rises the evil Galactic Empire. Jedi hero Anakin Skywalker must choose a side.","it":"Le Guerre dei Cloni giungono al termine e il Cancelliere Palpatine seduce Anakin con le promesse del Lato Oscuro. Traditi i Jedi, la Repubblica crolla, dando vita al tirannico Impero Galattico e alla nascita di Darth Vader.","es":"Último capítulo de la saga de Star Wars, en el que Anakin Skywalker definitivamente se pasa al lado oscuro. En el Episodio III aparecerá el General Grievous, un ser implacable mitad-alien mitad-robot, el líder del ejército separatista Droid. Los Sith son los amos del lado oscuro de la Fuerza y los enemigos de los Jedi. Ellos fueron prácticamente exterminados por los Jedi hace mil años, pero la orden del mal sobrevivió en la clandestinidad.","de":"Nach drei Jahren nähern sich die Klonkriege endlich dem Ende. Um die Separatisten endgültig zu besiegen, soll Obi-Wan Kenobi ihren Anführer General Grevious und Count Dooku ihrer gerechten Strafe zuführen. Zur Beunruhigung der schwangeren Padme nutzt daheim der endgültig vom Bösen korrumpierte Kanzler Palpatine die Gelegenheit, um den jungen Anakin Skywalker mit Versprechungen von unbegrenzter Macht auf die dunkle Seite zu ziehen. Ratlos und hin- und hergerissen wem er dienen soll, erliegt er geblendet von deren Machtverheißungen, den Versuchungen der dunklen Seite, schwört dem bösen Darth Sidious die Treue und nimmt die Identität von Darth Vader an. Die Sith-Lords beginnen zusammen einen Rachefeldzug, der in der Ermordung der Jedi seinen Anfang nimmt...","fr":"La Guerre des Clones fait rage. Une franche hostilité oppose désormais le Chancelier Palpatine au Conseil Jedi. Anakin Skywalker, jeune Chevalier Jedi pris entre deux feux, hésite sur la conduite à tenir. Séduit par la promesse d''un pouvoir sans précédent, tenté par le côté obscur de la Force, il prête allégeance au maléfique Darth Sidious et devient Dark Vador. Les Seigneurs Sith s''unissent alors pour préparer leur revanche, qui commence par l''extermination des Jedi. Seuls rescapés du massacre, Yoda et Obi-Wan se lancent à la poursuite des Sith. La traque se conclut par un spectaculaire combat au sabre entre Anakin et Obi-Wan, qui décidera du sort de la galaxie…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/xfSAoBEm9MNBjmlNcDYLvLSMlnq.jpg","it":"https://image.tmdb.org/t/p/w500/jM5jU9JzxnyE8CXqiOpc2ZPIbEd.jpg","es":"https://image.tmdb.org/t/p/w500/5dj0ERxM8NxoiWBdlY6TT9PJmKi.jpg","de":"https://image.tmdb.org/t/p/w500/kW3v2VS0kRvMTS6atR4MzjrzxAP.jpg","fr":"https://image.tmdb.org/t/p/w500/2RcBuU8cdxFxCJibbiYCGNLApfz.jpg"}'::jsonb WHERE id = 75;
UPDATE public.films SET tmdb_id = 140607, titoli_i18n = '{"it":"Star Wars: Il risveglio della Forza","es":"Star Wars: El despertar de la fuerza","fr":"Star Wars : Le Réveil de la Force","en":"Star Wars: The Force Awakens","de":"Star Wars: Das Erwachen der Macht"}'::jsonb, trame_i18n = '{"it":"Trent''anni dopo la caduta dell''Impero, sorge una nuova minaccia nota come Primo Ordine guidata da Kylo Ren. Una giovane orfana di nome Rey scopre la sua potente connessione con la Forza e parte alla ricerca dello scomparso Luke Skywalker.","es":"Treinta años después de la victoria de la Alianza Rebelde sobre la segunda Estrella de la Muerte, la galaxia está todavía en guerra. Una nueva República se ha constituido, pero una siniestra organización, la Primera Orden, ha resurgido de las cenizas del Imperio Galáctico. A los héroes de antaño, que luchan ahora en la Resistencia, se suman nuevos héroes: Poe Dameron, un piloto de caza, Finn, un desertor de la Primera Orden, Rey, una joven chatarrera, y BB-8, un androide rodante. Todos ellos luchan contra las fuerzas del Mal: el Capitán Phasma, de la Primera Orden, y Kylo Ren, un temible y misterioso personaje que empuña un sable de luz roja.","fr":"Il y a bien longtemps, dans une galaxie lointaine… Luke Skywalker est porté disparu. Le pilote Poe est en mission secrète sur une planète pour le retrouver. Au moment où la diabolique armée \"Premier Ordre\" apparaît en détruisant tout sur son passage, il arrive à cacher la position géographique de l''ancien maître Jedi dans son droïde BB-8. Capturé par les larbins du machiavélique Kylo Ren, Poe est libéré par le soldat ennemi Finn qui est en pleine crise existentielle. Pendant ce temps, BB-8 est recueillie par Rey, une pilleuse d''épaves qui sera bientôt plongée dans une quête qui la dépasse.","en":"Thirty years after defeating the Galactic Empire, Han Solo and his allies face a new threat from the evil Kylo Ren and his army of Stormtroopers.","de":"Über 30 Jahre sind vergangen, seitdem die Rebellen den zweiten Todesstern über Endor zerstört und damit die entscheidende Schlacht gegen die finsteren Mächte des Imperiums gewonnen haben. Doch aus der Asche des Bösen ist die Erste Ordnung empor gestiegen und hat die Herrschaft wieder an sich gerissen. Während Supreme Leader Snoke die Zügel im Hintergrund in den Händen hält, schickt er den Lichtschwert schwingenden Kylo Ren ins Feld, um die neue Weltordnung auch in den verstecktesten Winkeln der Galaxis zu verbreiten. Von großer Politik aber weiß Rey auf dem Wüstenplaneten Jakku zunächst nicht viel. Die junge Frau verbringt ihre Tage damit, die karge Landschaft nach Schrott abzusuchen, den sie danach verkauft. Sie ist allein, wartet auf ihre Familie – bis sie die Bekanntschaft von Finn macht, einem ehemaligen Sturmtruppler, den die Untaten der Ersten Ordnung abgeschreckt haben."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/uEDFRwKiTOsIsN5dkEPCj1laIAK.jpg","es":"https://image.tmdb.org/t/p/w500/vI86GLIkT5pP3ZfNs2EvmTrBLBm.jpg","fr":"https://image.tmdb.org/t/p/w500/zKZ1iF1ABqL7a16u6Im8JTQKp7H.jpg","en":"https://image.tmdb.org/t/p/w500/wqnLdwVXoBjKibFRR5U3y0aDUhs.jpg","de":"https://image.tmdb.org/t/p/w500/6EyJ3fxzjDr0Ly4i4u9VD8sja1N.jpg"}'::jsonb WHERE id = 76;
UPDATE public.films SET tmdb_id = 181808, titoli_i18n = '{"it":"Star Wars: Gli ultimi Jedi","en":"Star Wars: The Last Jedi","fr":"Star Wars : Les Derniers Jedi","de":"Star Wars: Die letzten Jedi","es":"Star Wars: Los últimos Jedi"}'::jsonb, trame_i18n = '{"it":"Rey sviluppa le sue abilità con l''aiuto di un riluttante Luke Skywalker, tormentato dagli errori passati. Nel frattempo, la Resistenza è sull''orlo dell''annientamento totale sotto il fuoco implacabile della flotta del Primo Ordine.","en":"Rey develops her newly discovered abilities with the guidance of Luke Skywalker, who is unsettled by the strength of her powers. Meanwhile, the Resistance prepares to do battle with the First Order.","fr":"Le Premier Ordre étend ses tentacules aux confins de l’univers, poussant la Résistance dans ses retranchements. Il est impossible de se sauver à la vitesse de la lumière avec cet ennemi continuellement aux trousses. Cela n’empêche pas Finn et ses camarades de tenter d’identifier une brèche chez leur adversaire. Pendant ce temps, Rey se trouve toujours sur la planète Ahch‐To pour convaincre Luke Skywalker de lui enseigner les rudiments de la Force.","de":"Die planetenvernichtende Starkiller-Basis der Ersten Ordnung ist zwar zerstört, die Neue Republik nach der vorherigen Zerstörung von fünf Welten aber massiv geschwächt. Sie steht am Abgrund und wird nur noch von Generalin Leias Widerstand verteidigt, für den auch Pilot Poe Dameron und der desertierte Ex-Sturmtruppler Finn kämpfen. Rey, mit den Erfahrungen ihres ersten großen Abenteuers in den Knochen, geht unterdessen bei Luke Skywalker auf dem Inselplaneten Ahch-To in die Lehre. Luke ist der letzte Jedi, der letzte Vertreter des Ordens, auf dem die Hoffnung ruht, dass Frieden in der Galaxis einkehrt. Doch die Erste Ordnung wirft ihren Schatten auch auf Luke und Rey: Der verlorene, ehemalige Schützling des alten Meisters, Kylo Ren, hat die finstere Mission noch längst nicht beendet, die ihm der sinistere Strippenzieher Snoke auftrug ...","es":"La malvada Primera Orden se ha vuelto más poderosa y tiene contra las cuerdas a la Resistencia, liderada por la General Leia Organa. El piloto Poe Dameron encabeza una misión para intentar destruir un acorazado de la Primera Orden. Mientras tanto, la joven Rey tendrá que definir su futuro y su vocación, y el viejo jedi Luke Skywalker revaluar el significado de su vida."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8qOzSPUWlBGfteuKFWJJTRpiFxI.jpg","en":"https://image.tmdb.org/t/p/w500/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg","fr":"https://image.tmdb.org/t/p/w500/prV3qBW4CqFsH14CEQNslnwvqWi.jpg","de":"https://image.tmdb.org/t/p/w500/6LyUrFO0i5AgpWVQlAQyA01Euhy.jpg","es":"https://image.tmdb.org/t/p/w500/7SNzh1fY3YJ8Y8MX93pZF5cJHaH.jpg"}'::jsonb WHERE id = 77;
UPDATE public.films SET tmdb_id = 181812, titoli_i18n = '{"it":"Star Wars: L''ascesa di Skywalker","fr":"Star Wars : L''Ascension de Skywalker","es":"Star Wars: El ascenso de Skywalker","en":"Star Wars: The Rise of Skywalker","de":"Star Wars: Der Aufstieg Skywalkers"}'::jsonb, trame_i18n = '{"it":"Un anno dopo gli eventi de ''Gli ultimi Jedi'', i sopravvissuti della Resistenza affrontano ancora una volta il Primo Ordine. Rey, Finn e Poe Dameron guidano la battaglia finale contro il Leader Supremo Kylo Ren e il redivivo Imperatore Palpatine, giungendo alla conclusione della storica saga degli Skywalker.","fr":"Environ un an après la mort de Luke Skywalker, la Résistance tente de survivre face au Premier Ordre, désormais mené par un nouveau Suprême Leader, Kylo Ren. Une rumeur agite cependant toute la galaxie : l''Empereur Palpatine serait de retour. Tandis que Rey s''entraîne sous la houlette de la générale Leia Organa, Kylo Ren cherche à défier Palpatine, qu''il considère comme une menace à son pouvoir.","es":"Los restos de la Resistencia se enfrentan una vez más a la Primera Orden, involucrando conflictos del pasado y del presente. Mientras tanto, el antiguo conflicto entre los Jedi y los Sith llegará a su clímax, lo que llevará a la saga de los Skywalker a un final definitivo.","en":"The surviving Resistance faces the First Order once again as the journey of Rey, Finn and Poe Dameron continues. With the power and knowledge of generations behind them, the final battle begins.","de":"Etwa ein Jahr, nachdem der letzte Rest des Widerstands durch Luke Skywalkers Opfertat aus dem Griff der Ersten Ordnung entkommen konnte, kämpfen die völlig unterlegenen Rebellen aus dem Hinterhalt gegen Kylo Ren und dessen Truppen. Zum ersten Mal gehen dabei die neuen Helden Rey, Finn und der Super-Pilot Poe gemeinsam auf eine lange Mission ..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3drtqLOARQEuFgEmGRlMlWpV3Eb.jpg","fr":"https://image.tmdb.org/t/p/w500/1pQc75SdFOKpo2AqoL58z5kF3YI.jpg","es":"https://image.tmdb.org/t/p/w500/oeQxq6If4DcW6ADIYCF9SQwKov.jpg","en":"https://image.tmdb.org/t/p/w500/db32LaOibwEliAmSL2jjDF6oDdj.jpg","de":"https://image.tmdb.org/t/p/w500/dAk1ClViS20eUEjfxjeknceMBi7.jpg"}'::jsonb WHERE id = 78;
UPDATE public.films SET tmdb_id = 11, titoli_i18n = '{"it":"Guerre stellari: Episodio IV - Una nuova speranza","es":"La guerra de las galaxias","en":"Star Wars","fr":"La Guerre des étoiles","de":"Krieg der Sterne"}'::jsonb, trame_i18n = '{"it":"Il giovane Luke Skywalker entra in possesso di droidi contenenti i piani segreti della Morte Nera, la potente arma dell''Impero Galattico. Guidato dal saggio maestro Jedi Obi-Wan Kenobi e affiancato dal contrabbandiere Han Solo, Luke intraprende un''audace missione per salvare la Principessa Leila. Insieme, guideranno l''Alleanza Ribelle nel disperato tentativo di distruggere la stazione imperiale.","es":"La princesa Leia, líder del movimiento rebelde que desea reinstaurar la República en la galaxia en los tiempos ominosos del Imperio, es capturada por las malévolas Fuerzas Imperiales, capitaneadas por el implacable Darth Vader, el sirviente más fiel del emperador. El intrépido Luke Skywalker, ayudado por Han Solo, capitán de la nave espacial \"El Halcón Milenario\", y los androides, R2D2 y C3PO, serán los encargados de luchar contra el enemigo y rescatar a la princesa para volver a instaurar la justicia en el seno de la Galaxia.","en":"Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.","fr":"Il y a bien longtemps, dans une galaxie très lointaine... La guerre civile fait rage entre l''Empire galactique et l''Alliance rebelle. Capturée par les troupes de choc de l''Empereur menées par le sombre et impitoyable Dark Vador, la princesse Leia Organa dissimule les plans de l’Étoile Noire, une station spatiale invulnérable, à son droïde R2-D2 avec pour mission de les remettre au Jedi Obi-Wan Kenobi. Accompagné de son fidèle compagnon, le droïde de protocole C-3PO, R2-D2 s''échoue sur la planète Tatooine et termine sa quête chez le jeune Luke Skywalker. Rêvant de devenir pilote mais confiné aux travaux de la ferme, ce dernier se lance à la recherche de ce mystérieux Obi-Wan Kenobi, devenu ermite au cœur des montagnes désertiques de Tatooine...","de":"Seit der Vernichtung der Jedi-Ritter steht die Galaxie unter der grausamen Herrschaft des Imperiums. Nur eine kleine Gruppe von Rebellen, angeführt von der schönen Prinzessin Leia, widersetzt sich der dunklen Macht. Als es ihnen gelingt, die geheimen Baupläne für den gefährlichen Todesstern zu entwenden, gerät das Imperium in Aufruhr. Durch Zufall gelangen die Pläne ausgerechnet in die Hände des Farmerjungen Luke Skywalker, der spürt, dass er sein bisheriges Leben hinter sich lassen muss. Gemeinsam mit dem weisen Obi-Wan Kenobi, den Weltraumabenteurern Han Solo und Chewbacca sowie den Droiden R2-D2 und C-3PO nimmt er den Kampf gegen das mächtige Imperium auf. Es beginnt ein Wettlauf gegen die Zeit, denn der Kampfstern kann nur vor seiner Fertigstellung zerstört werden..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/fVqKwpvobwWy0P1UImZWIDuw4RI.jpg","es":"https://image.tmdb.org/t/p/w500/4hOUzmButYUeON0prG3RpbqS7ag.jpg","en":"https://image.tmdb.org/t/p/w500/fai0rspsNeJCS69wHNjOdWxcI7P.jpg","fr":"https://image.tmdb.org/t/p/w500/rLi9cokiFU20mLUPvQ0IRok3ELY.jpg","de":"https://image.tmdb.org/t/p/w500/crUUE14AROxNWsMdmyyqZNcUB6L.jpg"}'::jsonb WHERE id = 79;
UPDATE public.films SET tmdb_id = 1891, titoli_i18n = '{"en":"The Empire Strikes Back","it":"Guerre stellari: Episodio V - L''Impero colpisce ancora","es":"El imperio contraataca","de":"Das Imperium schlägt zurück","fr":"L''Empire contre-attaque"}'::jsonb, trame_i18n = '{"en":"The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.","it":"Dopo la distruzione della Morte Nera, le forze imperiali inseguono implacabilmente i Ribelli attraverso la galassia. Mentre Han Solo e Leila sfuggono alla flotta nemica rifugiandosi nella Città delle Nuvole, Luke si reca sul pianeta Dagobah per addestrarsi con il maestro Yoda. Lo scontro imminente con Dart Fener porterà alla luce una sconvolgente verità sul suo passato.","es":"Tras un ataque sorpresa de las tropas imperiales a las bases camufladas de la alianza rebelde, Luke Skywalker, en compañía de R2D2, parte hacia el planeta Dagobah en busca de Yoda, el último maestro Jedi, para que le enseñe los secretos de la Fuerza. Mientras, Han Solo, la princesa Leia, Chewbacca, y C3PO esquivan a las fuerzas imperiales y piden refugio al antiguo propietario del Halcón Milenario, Lando Calrissian, en la ciudad minera de Bespin, donde les prepara una trampa urdida por Darth Vader.","de":"Nach der Zerstörung des Todessterns geht der Kampf zwischen den Rebellen und dem herrschenden Imperium weiter. Die Rebellen haben sich auf den Eisplaneten Hoth zurückgezogen, doch das Imperium spürt sie auf und zerstört nach hartem Kampf die dortige Basis. Daraufhin teilen sich unsere Freunde auf: Luke gerät mit R2-D2 auf den Sumpfplaneten Dagobah, wo er von dem alten Jedi-Meister Yoda eine Ausbildung im Umgang mit der Macht erhält, während Leia, Han Solo und die anderen sich nach Bespin durchschlagen, wo in einer Wolkenstadt ein alter Freund von Han residiert. Doch dort geraten sie in eine Falle des Imperiums, und Luke muß ihnen zu Hilfe kommen und Darth Vader zu einem Duell herausfordern...","fr":"Malgré la destruction de l’Étoile Noire, l''Empire maintient son emprise sur la galaxie, et poursuit sans relâche sa lutte contre l''Alliance rebelle. Basés sur la planète glacée de Hoth, les rebelles essuient un assaut des troupes impériales. Parvenus à s''échapper, la princesse Leia, Han Solo, Chewbacca et C-3P0 se dirigent vers Bespin, la cité des nuages gouvernée par Lando Calrissian, ancien compagnon de Han. Suivant les instructions d''Obi-Wan Kenobi, Luke Skywalker se rend quant à lui vers le système de Dagobah, planète marécageuse où il doit recevoir l''enseignement du dernier maître Jedi, Yoda. Apprenant l''arrestation de ses compagnons par les stormtroopers de Dark Vador après la trahison de Lando, Luke décide d''interrompre son entraînement pour porter secours à ses amis et affronter le sombre seigneur Sith..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg","it":"https://image.tmdb.org/t/p/w500/6vzDHECuUbKiqSSXHcIKb9LPcQs.jpg","es":"https://image.tmdb.org/t/p/w500/eU7KcNAOeZj9PBIcGUMSsuJz8qj.jpg","de":"https://image.tmdb.org/t/p/w500/mi08uIh7ZqYlJEMrc5l2986geSU.jpg","fr":"https://image.tmdb.org/t/p/w500/qDvctAykmNWAmi9G2GrVrwWx3pr.jpg"}'::jsonb WHERE id = 80;
UPDATE public.films SET tmdb_id = 1892, titoli_i18n = '{"en":"Return of the Jedi","es":"El retorno del Jedi","fr":"Le Retour du Jedi","de":"Die Rückkehr der Jedi-Ritter","it":"Guerre stellari: Episodio VI - Il ritorno dello Jedi"}'::jsonb, trame_i18n = '{"en":"Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, the Emperor prepares to crush the Rebellion with a more powerful Death Star, and the Rebel fleet mounts a massive attack on the space station. Luke Skywalker confronts Darth Vader in a final climactic duel before the evil Emperor.","es":"Luke Skywalker y la princesa Leia deben viajar a Tatooine para liberar a Han Solo. Para conseguirlo, deben infiltrarse en la peligrosa guarida de Jabba the Hutt, el gángster más temido de la galaxia. Una vez reunidos, el equipo recluta a tribus de Ewoks para combatir a las fuerzas imperiales en los bosques de la luna de Endor. Mientras tanto, el Emperador y Darth Vader conspiran para convertir a Luke al lado oscuro, pero el joven Skywalker, por su parte, está decidido a reavivar el espíritu del Jedi en su padre. La guerra civil galáctica culmina en un último enfrentamiento entre las fuerzas rebeldes unificadas y una segunda Estrella de la Muerte, indefensa e incompleta, en una batalla que decidirá el destino de la galaxia.","fr":"L''Empire galactique est plus puissant que jamais : la construction de la nouvelle arme, l’Étoile de la Mort, menace l''univers tout entier... Arrêté après la trahison de Lando Calrissian, Han Solo est remis à l''ignoble contrebandier Jabba Le Hutt par le chasseur de primes Boba Fett. Après l''échec d''une première tentative d''évasion menée par la princesse Leia, également arrêtée par Jabba, Luke Skywalker et Lando parviennent à libérer leurs amis. Han, Leia, Chewbacca, C-3PO et Luke, devenu un Jedi, s''envolent dès lors pour une mission d''extrême importance sur la lune forestière d''Endor, afin de détruire le générateur du bouclier de l’Étoile de la Mort et permettre une attaque des pilotes de l''Alliance rebelle. Conscient d''être un danger pour ses compagnons, Luke préfère se rendre aux mains de Dark Vador, son père et ancien Jedi passé du côté obscur de la Force.","de":"Wesen aus allen Ecken der Galaxis treffen die Vorbereitungen für die entscheidende Schlacht gegen die Streitkräfte des Imperiums. Ziel der Aktion ist die totale Zerstörung des zweiten Todessterns, dessen unvorstellbare Feuerkraft ganze Planeten vernichten kann. Inzwischen ist Han Solo immer noch in der Wüstenfestung des mächtigsten und skrupellosesten Verbechers des Universums, Jabba the Hutt, gefangen. Luke Skywalker gelingt es schließlich zusammen mit seinen Gefährten Prinzessin Leia, Chewbacca und Lando Calrissian, sowie den beiden Robotern C3PO und R2D2 mit Han zu fliehen. Aber Luke steht die schwerste Prüfung noch bevor: Während auf dem Waldmond Endor und beim Todesstern die alles entscheidende Schlacht entbrennt, muß er sich seinem Erzfeind Darth Vader zu einem Zweikampf auf Leben und Tod stellen...","it":"Luke Skywalker e i suoi compagni salvano Han Solo dalla fortezza del malvagio Jabba the Hutt prima di affrontare la minaccia definitiva dell''Impero. I Ribelli pianificano un attacco coordinato contro una seconda e più potente Morte Nera in costruzione nei pressi della luna boscosa di Endor. Nel frattempo, Luke deve confrontarsi direttamente con l''Imperatore Palpatine e tentare di redimere suo padre Dart Fener."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/jQYlydvHm3kUix1f8prMucrplhm.jpg","es":"https://image.tmdb.org/t/p/w500/rKMmXzdm7eRgmlwYo7iq3klT7wJ.jpg","fr":"https://image.tmdb.org/t/p/w500/tEQlCGiiWvMvfD7Sz8d99Pouy39.jpg","de":"https://image.tmdb.org/t/p/w500/xwwbeCWW1jMSDPfRPJp8X4oySPr.jpg","it":"https://image.tmdb.org/t/p/w500/rMcCqpaWEUBmATmpZilDTKOyVbL.jpg"}'::jsonb WHERE id = 81;
UPDATE public.films SET tmdb_id = 36670, titoli_i18n = '{"en":"Never Say Never Again","es":"Nunca digas nunca jamás","it":"Mai dire mai","fr":"Jamais plus jamais","de":"Sag niemals nie"}'::jsonb, trame_i18n = '{"en":"James Bond returns as the secret agent 007 to battle the evil organization SPECTRE. Bond must defeat Largo, who has stolen two atomic warheads for nuclear blackmail. But Bond has an ally in Largo''s girlfriend, the willowy Domino, who falls for Bond and seeks revenge.","es":"La temible organización criminal Spectra ha ideado un ingenioso plan que le permite conseguir dos proyectiles nucleares, los cuales harán estallar si el gobierno no cede a su chantaje. El agente 007 se encargará del caso.","it":"James Bond, ormai vicino all''età pensionabile e mandato in una clinica per rimettersi in forma, scopre una cospirazione ordita dall''organizzazione criminale SPECTRE. Guidato dal malvagio Maximilian Largo sotto gli ordini di Ernst Stavro Blofeld, il gruppo riesce a rubare due testate nucleari cruise della NATO per ricattare il mondo. L''agente 007 viene richiamato in servizio d''urgenza da M e si mette sulle tracce delle armi, scontrandosi con la letale assassina Fatima Blush e cercando di conquistare la fiducia della bellissima Domino Petachi, amante di Largo, per sventare l''olocausto nucleare.","fr":"M, le chef des services secrets britanniques, n''aime pas les méthodes expéditives de James Bond, au contraire de son prédécesseur. De plus, il le trouve en petite forme, à l''issue des tests qu''il lui a fait subir. C''est ainsi que Bond a été \"poignardé\" par la fille d''un milliardaire qu''il venait de tirer des griffes de révolutionnaires qui l''avaient enlevée. Le résultat de cette simulation conduit M à envoyer Bond dans la clinique de Shrublands, non loin de Londres, pour s''y refaire une santé et éliminer ses toxines. Là, entre deux jus de céleri et une tisane au persil, il surprend, une nuit, une lutte entre Jack Petachi, un officier américain, et son infirmière, la troublante Fatima Blush. La jeune femme, membre du Spectre, a pour mission de surveiller Petachi dont l''œil droit a été opéré, de manière à en faire la réplique exacte de celui du Président. Élément clé d''une opération baptisée \"Les larmes d''Allah\".","de":"Von einem Nato-Stützpunkt in England werden auf spektakuläre Weise zwei Atomraketen gestohlen. Als die Nato damit erpresst werden soll, schicken die Briten ihren Topagenten James Bond, um die nukleare Bedrohung abzuwenden, und die Gangster dingfest zu machen."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/zhoAL4o1STGgLbLxJ9r1ijfyHC9.jpg","es":"https://image.tmdb.org/t/p/w500/iLfAIRwbd14HihotsomoVZbIt2K.jpg","it":"https://image.tmdb.org/t/p/w500/lyPIv08a0VPrJxpGu5pvyUE0bB3.jpg","fr":"https://image.tmdb.org/t/p/w500/j8fcChPA88YlLdXMryDQwNPngPI.jpg","de":"https://image.tmdb.org/t/p/w500/im3FnMct3LKIqzYdQqKMR3tkKKX.jpg"}'::jsonb WHERE id = 82;
UPDATE public.films SET tmdb_id = 157336, titoli_i18n = '{"it":"Interstellar","en":"Interstellar","es":"Interstellar","de":"Interstellar","fr":"Interstellar"}'::jsonb, trame_i18n = '{"it":"In un futuro non lontano, un''inarrestabile piaga sta distruggendo i raccolti terrestri, condannando l''umanità alla fame. Un gruppo di esploratori e scienziati, guidati dall''ex pilota della NASA Cooper, intraprende una missione interstellare attraverso un wormhole recentemente scoperto nei pressi di Saturno, nel disperato tentativo di trovare un nuovo pianeta abitabile per salvare la specie umana.","en":"The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.","es":"Un grupo de exploradores hacen uso de un agujero de gusano recientemente descubierto para superar las limitaciones de los viajes espaciales tripulados y vencer las inmensas distancias que tiene un viaje interestelar.","de":"Was Wissenschaftler, Politiker und Aktivisten seit Jahrzehnten prophezeien, ist eingetreten: Die Menschheit steht kurz davor, an einer globalen Nahrungsknappheit zugrunde zu gehen. Die einzige Hoffnung der Weltbevölkerung besteht in einem geheimen Projekt der US-Regierung, das von dem findigen Wissenschaftler Professor Brand geleitet wird. Der Plan sieht vor, eine Expedition in ein anderes Sternensystem zu starten, wo bewohnbare Planeten, Rohstoffe und vor allem Leben vermutet werden. Der Ingenieur und ehemalige NASA-Pilot Cooper und Brands Tochter Amelia führen die Besatzung an, die sich auf eine Reise ins Ungewisse begibt: Wurmlöcher sind so gut wie unerforscht und niemand kann mit Sicherheit sagen, was die Crew auf der anderen Seite erwartet. Ebenso ist unsicher, ob und wann Cooper und Brand wieder auf die Erde zurückkehren. Coopers Kinder, Tochter Murph und Sohn Tom, müssen mit Schwiegervater Donald zurückbleiben und auf seine Wiederkehr hoffen...","fr":"Dans un futur proche, face à une Terre exsangue, un groupe d’explorateurs utilise un vaisseau interstellaire pour franchir un trou de ver permettant de parcourir des distances jusque‐là infranchissables. Leur but : trouver un nouveau foyer pour l’humanité."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/bMKiLh0mES4Uiococ240lbbTGXQ.jpg","en":"https://image.tmdb.org/t/p/w500/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg","es":"https://image.tmdb.org/t/p/w500/d1QKiYtceF3GDtxvTFXFAqwwah9.jpg","de":"https://image.tmdb.org/t/p/w500/hHdhfkkzt0Mwec33Ux177Z7CO8w.jpg","fr":"https://image.tmdb.org/t/p/w500/1pnigkWWy8W032o9TKDneBa3eVK.jpg"}'::jsonb WHERE id = 83;
UPDATE public.films SET tmdb_id = 25237, titoli_i18n = '{"en":"Come and See","es":"Masacre (Ven y mira)","it":"Va'' e vedi","fr":"Requiem pour un massacre","de":"Komm und sieh"}'::jsonb, trame_i18n = '{"en":"The invasion of a village in Belarus by German forces sends young Flyora into the forest to join the weary Resistance fighters, against his family''s wishes. There he meets a girl, Glasha, who accompanies him back to his village. On returning home, Flyora finds his family and fellow peasants massacred. His continued survival amidst the brutal debris of war becomes increasingly nightmarish, a battle between despair and hope.","es":"Tras encontrar un viejo rifle, un joven se une a las fuerzas de la resistencia soviética, que lucha por expulsar a las fuerzas nazis del frente oriental. Allí, será testigo de algunos los mayores horrores cometidos en la Segunda Guerra Mundial.","it":"Durante la seconda guerra mondiale, nella Bielorussia del 1943 occupata dalle forze naziste, il giovane Florya decide di unirsi alla resistenza partigiana contro l''invasore. Attraverso il suo tragico viaggio, il ragazzo sarà testimone diretto delle atrocità più disumane, dei massacri sistematici dei villaggi e della devastazione psicologica e fisica causata dalla guerra, perdendo prematuramente la propria innocenza in un crescendo di orrore.","fr":"Pendant la Seconde Guerre mondiale, Fliora, jeune garçon d''un village de Biélorussie occupé par les troupes nazies, s''engage, bien que trop jeune, chez les partisans. Il va découvrir l''amour, la fraternité, la souffrance, la guerre.","de":"Weißrußland, 1943. Der 14jährige Fljora schließt sich gegen den Protest seiner Mutter den Partisanen an. Für ihn ist der Krieg noch ein Kinderspiel. Als es in den Kampf geht, darf er nicht mit an die Front. Fljora soll statt dessen mit Alten und Kindern ein Reservelager einrichten. Der Junge fühlt sich alleingelassen. In den Wäldern trifft er auf das Mädchen Glascha, die Geliebte des Partisanenführers. Fljora versucht sie zu trösten, als die Hölle über beide hereinbricht: Sie sind in einen Angriff der deutschen Wehrmacht geraten! Nur knapp können die beiden dem Tod entrinnen. Aber die Schrecken haben noch kein Ende…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/qNbMsKVzigERgJUbwf8pKyZogpb.jpg","es":"https://image.tmdb.org/t/p/w500/j2hzNkmwYT184eP9qYdjViiYxCO.jpg","it":"https://image.tmdb.org/t/p/w500/nGTKjc3PDPz7WcsdEAI7U0iVIjo.jpg","fr":"https://image.tmdb.org/t/p/w500/aT7fV0q7mbsN0HCrcC41NeYQoCU.jpg","de":"https://image.tmdb.org/t/p/w500/6QTr0ljSaBVYN4T865QtQDzpdbQ.jpg"}'::jsonb WHERE id = 84;
UPDATE public.films SET tmdb_id = 62, titoli_i18n = '{"en":"2001: A Space Odyssey","fr":"2001 : L''Odyssée de l''espace","es":"2001. Una odisea del espacio","de":"2001: Odyssee im Weltraum","it":"2001: Odissea nello spazio"}'::jsonb, trame_i18n = '{"en":"Humanity finds a mysterious object buried beneath the lunar surface and sets off to find its origins with the help of HAL 9000, the world''s most advanced super computer.","fr":"Aux temps préhistoriques, une petite tribu d’hommes‐singes installée au milieu de rochers arides lutte difficilement pour la vie. Un matin, ils trouvent devant eux une mystérieuse dalle noire monolithique. L’un des singes touche la pierre et apprend alors à se servir d’un os de quadrupède pour tuer ses ennemis. Quatre millions d’années plus tard, en 2001, un savant de l’espace, le Dr Heywood Floyd, débarque sur la lune pour examiner une dalle noire semblable à celle des singes, qui était enterrée sous la surface de l’astre. Selon les premières observations, l’objet émettrait un signal mystérieux…","es":"Mientras investigan la aparición de misteriosos monolitos en el universo, dos astronautas luchan contra la inteligencia artificial de su nave.","de":"Als im Jahr 2001 ein Monolith auf dem Mond entdeckt wird, wird diese Entdeckung als der Beweis für außerirdisches Leben gedeutet. Eineinhalb Jahre nach der Entdeckung des Monoliths werden 2 Astronauten, Bowman und Poole, mit dem Raumschiff Discovery zum Jupiter geschickt, um weitere Erkenntnisse zu gewinnen. Das Raumschiff ist mit dem Supercomputer HAL-9000 ausgerüstet. Bald ergeben sich erste Komplikationen mit dem Computer...","it":"Un misterioso monolite nero guida ed influenza i passaggi chiave dell''evoluzione umana dalla preistoria al futuro. Nel 2001, una missione spaziale diretta verso Giove a bordo della Discovery One entra in rotta di collisione con la propria intelligenza artificiale, l''infallibile e inquietante computer HAL 9000."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg","fr":"https://image.tmdb.org/t/p/w500/uwd79G32FPIL5B9UkRgSZvS0gbe.jpg","es":"https://image.tmdb.org/t/p/w500/pGabanxaE2YvN4jhZuSN3oXO0mi.jpg","de":"https://image.tmdb.org/t/p/w500/g16ONGwG7l3R94JFPKCx1orZvYD.jpg","it":"https://image.tmdb.org/t/p/w500/uvSRVMXGHaCeYAj2pCYNdC31b2u.jpg"}'::jsonb WHERE id = 85;
UPDATE public.films SET tmdb_id = 1368, titoli_i18n = '{"it":"Rambo","fr":"Rambo","es":"Acorralado","en":"First Blood","de":"Rambo"}'::jsonb, trame_i18n = '{"it":"John Rambo, un reduce della guerra del Vietnam psicologicamente segnato, arriva in una piccola città alla ricerca di un vecchio amico. Ingiustamente perseguitato dallo sceriffo locale, Rambo si rifugia nei boschi scatenando una caccia all''uomo senza tregua.","fr":"Après la guerre du Viêt Nam à l''issue humiliante pour les États Unis, les vétérans envoyés au combat et salués en héros par l''Amérique de Kennedy sûrs de leur bon droit, pour retrouver une Amérique hippie et moralisatrice sous Johnson et les traités d''assassins, sont laissés pour compte, devenus des indésirables qu''il faut cacher, enfermer. John Rambo est l''un d''eux, médaillé par le Congrès, dernier survivant d''un commando des Bérets Verts. Il est arrêté à Hope, une petite ville par le shérif Will Teasle pour vagabondage parce qu''il voulait trouver un restaurant pour s''alimenter. Jeté en cellule, maltraité, battu par les hommes du shérif, il se défend en appliquant ce qui lui a permis de survivre à la guerre, mets ces hommes à terre et s''évade du commissariat. La chasse à l’homme contre Rambo commence...","es":"John Rambo es un veterano de la guerra de Vietnam que sufre de estrés postraumático. Un día, llega a un pequeño pueblo de Oregón, donde el sheriff Will Teasle le detiene por vagabundear. Rambo logra escapar de la comisaría y se refugia en el bosque, donde usa sus habilidades de supervivencia y combate para enfrentarse a los policías que le persiguen. El coronel Samuel Trautman, el antiguo jefe de Rambo, llega al pueblo para intentar negociar con él y evitar una masacre. Rambo tendrá que luchar contra sus propios demonios y contra las fuerzas del orden que le quieren capturar o matar.","en":"When former Green Beret John Rambo is harassed by local law enforcement and arrested for vagrancy, he is forced to flee into the mountains and wage an escalating one-man war against his pursuers.","de":"John Rambo, ein vom Krieg verstörter Vietnamveteran, irrt trampend durch die Vereinigten Staaten. Unterwegs gerät er an den bösartigen Sheriff Teasle, der ihn ohne Grund in Haft nimmt. Als Rambo in der Zelle von den Cops misshandelt wird, dreht er durch, und flüchtet in den Wald. Jetzt haben die Provinzbullen endlich einen Grund, ihn zu jagen. Doch da haben sie sich den falschen ausgesucht…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/dff9LLsvZWA6fKDlVkWeayK04od.jpg","fr":"https://image.tmdb.org/t/p/w500/gjb4xVMld19M5IS4EmgVeX7HuHv.jpg","es":"https://image.tmdb.org/t/p/w500/sYHRcd9p3rV3t3w8MHGaA7wdIBl.jpg","en":"https://image.tmdb.org/t/p/w500/a9sa6ERZCpplbPEO7OMWE763CLD.jpg","de":"https://image.tmdb.org/t/p/w500/hJWuFpjvMuz9kDuoSFMnLPTg7Vm.jpg"}'::jsonb WHERE id = 86;
UPDATE public.films SET tmdb_id = 1369, titoli_i18n = '{"en":"Rambo: First Blood Part II","de":"Rambo II - Der Auftrag","es":"Rambo: Acorralado Parte II","it":"Rambo 2 - La vendetta","fr":"Rambo II : La Mission"}'::jsonb, trame_i18n = '{"en":"John Rambo is released from prison by the government for a top-secret covert mission to the last place on Earth he''d want to return - the jungles of Vietnam.","de":"John Rambo wird von seinem alten Freund Col. Trautman aus dem Gefängnis geholt – doch nicht ohne Hintergedanken. Der Einzelkämpfer soll nach Vietnam zurückkehren, wo auch zehn Jahre nach Kriegsende immer noch amerikanische Soldaten gefangen gehalten werden. Rambo soll ein mögliches Gefangenenlager auskundschaften. Doch der Einsatz läuft gar nicht nach Plan und bald findet sich Rambo nur mit einem Messer und der Vietnamesin Co Bao im tiefsten Dschungel wieder um alleine den Kampf zu gewinnen, den Amerika vor einem Jahrzehnt verloren hat.","es":"Rambo es excarcelado y enviado de vuelta al Vietnam con una nueva misión: averiguar el paradero de unos soldados norteamericanos desaparecidos. Tras saltar en paracaídas en la jungla, portando únicamente un cuchillo y un arco con flechas, se le dice que no ataque al enemigo y que sólo haga fotografías de reconocimiento. Pero el plan no saldrá como estaba previsto.","it":"Fatto uscire di prigione per una missione ricognitiva in Vietnam, Rambo ha il compito di fotografare un campo di prigionieri americani. Violando gli ordini ricevuti, il veterano decide di intervenire per liberarli affrontando le forze nemiche.","fr":"John Rambo purge une peine de prison lorsque le Colonel Trautman lui donne la possibilité de sortir pour une mission délicate : avoir la preuve qu''il reste bel et bien des prisonniers américains au Vietnam.Supposé n''être qu''un observateur, Rambo désobéit aux ordres et tente de sauver un prisonnier. Murdock, le responsable de la mission, décide alors de l''abandonner en territoire ennemi, Rambo, seul, sans armes et face à l''ennemi, prépare sa vengeance et son retour au pays."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/fVwRtWqEPdsCH21BVDGqgkAQcff.jpg","de":"https://image.tmdb.org/t/p/w500/sJ3Hl3M6JsNFktzxxcWmQyh8GUh.jpg","es":"https://image.tmdb.org/t/p/w500/dUWHNWzrmCSTIj9zdI5b3HeO0o5.jpg","it":"https://image.tmdb.org/t/p/w500/mRV0Ac9EJuMRsEso9fBbJr4lExZ.jpg","fr":"https://image.tmdb.org/t/p/w500/jPMoYbpY8faABzeE8dRAfprlfTW.jpg"}'::jsonb WHERE id = 87;
UPDATE public.films SET tmdb_id = 1370, titoli_i18n = '{"it":"Rambo III","es":"Rambo III","de":"Rambo III","fr":"Rambo III","en":"Rambo III"}'::jsonb, trame_i18n = '{"it":"Ritiratosi in un monastero in Thailandia, Rambo viene a sapere che il suo ex comandante Trautman è stato catturato dai sovietici in Afghanistan. L''ex berretto verde parte da solo per un''audace missione di salvataggio nel territorio nemico.","es":"Cuando descubre que el coronel Trautman ha caído en manos soviéticas en Afganistán, Rambo regresa al servicio para intentar liberar a su amigo. Después de contactar a la resistencia afgana, entra en la zona sitiada por las tropas enemigas.","de":"Colonel Trautman bittet seinen alten Freund John Rambo, der sich mittlerweile aus seinem tödlichen Geschäft zurückgezogen hat, um einen Gefallen: Er soll ihn bei einem Einsatz hinter sowjetischen Linien in Afganistan zur Seite stehen. Rambo lehnt zunächst ab, doch als Trautman gefangengenommen wird, eilt er natürlich zu dessen Rettung flugs hinter her…","fr":"Le Colonel Trautman contacte Rambo dans sa retraite en Thaïlande pour qu''il l''accompagne dans une mission périlleuse en Afghanistan. Mais l''ex-soldat refuse afin de se consacrer aux moines bouddhistes qui l''ont recueilli. Lorsque, quelques jours plus tard, l''agent Griggs lui explique que Trautman a été capturé par le Colonel Zaysen, Rambo décide de sauver son ami. Il s''infiltre dans les lignes ennemies et découvre toute l''horreur du conflit qui oppose les moudjahidin à l''armée soviétique. Déterminé, il s''attaque à toute une armée sans oublier son objectif premier : récupérer Trautman.","en":"Combat has taken its toll on Rambo, but he''s finally begun to find inner peace in a monastery. When Rambo''s friend and mentor Col. Trautman asks for his help on a top secret mission to Afghanistan, Rambo declines but must reconsider when Trautman is captured."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/1eSQvGuD25ezKaiaQsyDDG3e9iN.jpg","es":"https://image.tmdb.org/t/p/w500/1eSQvGuD25ezKaiaQsyDDG3e9iN.jpg","de":"https://image.tmdb.org/t/p/w500/6BjMW2tLVizIpF57RQXv4EDE73T.jpg","fr":"https://image.tmdb.org/t/p/w500/gCZktvZDPltMyad4UsCZYNCIW7F.jpg","en":"https://image.tmdb.org/t/p/w500/1eSQvGuD25ezKaiaQsyDDG3e9iN.jpg"}'::jsonb WHERE id = 88;
UPDATE public.films SET tmdb_id = 7555, titoli_i18n = '{"it":"John Rambo","es":"John Rambo","en":"Rambo","fr":"John Rambo","de":"John Rambo"}'::jsonb, trame_i18n = '{"it":"Rambo vive isolato nel nord della Thailandia finché un gruppo di missionari non lo ingaggia per guidarli in Birmania. Quando i missionari vengono catturati dalle truppe militari locali, il veterano guida un gruppo di mercenari in una sanguinosa operazione di recupero.","es":"John Rambo, el ex-boina verde con una ajetreada vida marcada por la guerra, vive ahora una solitaria y apacible existencia en la jungla del norte de Tailandia, pescando y cazando cobras para luego venderlas. Todo cambia cuando un grupo de misioneros católicos necesita que les guíe hasta la frontera con Birmania para suministrar medicinas y alimentos a unos refugiados asediados por el ejército birmano, que ha hecho de las torturas y los asesinatos algo habitual. Rambo no tendrá más remedio que volver a involucrarse. Se verá obligado a hacer lo que mejor sabe porque, muy a su pesar, lleva la guerra en la sangre.","en":"In Thailand, ex-Green Beret John James Rambo joins a group of mercenaries to venture into war-torn neighboring Myanmar to rescue a group of Christian aid workers who have been kidnapped by a ruthless local infantry unit.","fr":"John Rambo s''est retiré dans le nord de la Thaïlande, où il mène une existence simple dans les montagnes et se tient à l''écart de la guerre civile qui fait rage non loin de là, sur la frontière entre la Thaïlande et le Myanmar. Il pêche et capture des serpents venimeux pour les vendre. La violence du monde le rattrape lorsqu''un groupe de volontaires humanitaires mené par Sarah et Michael Bennett vient le trouver pour qu''il les guide jusqu''à un camp de réfugiés auquel ils veulent apporter une aide médicale et de la nourriture. Rambo finit par accepter et leur fait remonter la rivière, vers l''autre côté de la frontière. Deux semaines plus tard, le pasteur Arthur Marsh lui apprend que les volontaires ne sont pas revenus et que les ambassades refusent de l''aider à les retrouver. Rambo sait mieux que personne ce qu''il faut faire dans ce genre de situation…","de":"John Rambo lebt seit langer Zeit zurückgezogen in Thailand. Das benachbarte Birma ist seit 60 Jahren im Würgegriff eines blutigen Bürgerkrieges. Im Kampf gegen die dort herrschende Unmenschlichkeit sucht ein Team von freiwilligen Helfern Rambo auf um sich von ihm ins Zielgebiet bringen zu lassen. Zunächst abgeneigt willigt Rambo schließlich ein. Bereits kurze Zeit später wird das besuchte Dorf brutal niedergemacht. Fast alle Einwohner werden getötet, nur das Helferteam gerät in Gefangenschaft. Da von offizieller Seite keine Hilfe zu erwarten ist, wird ein Trupp Söldner zur Befreiung der Gefangenen entsandt. Obwohl wieder nur als Fährmann gedacht, schließt sich Rambo der Eingreiftruppe an…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3RIDyg4aUasjfZRdk6oLab0C0Ch.jpg","es":"https://image.tmdb.org/t/p/w500/qp9Q0JeHQ6JShQPm6KA8euYhWLF.jpg","en":"https://image.tmdb.org/t/p/w500/3mInub5c8o00H7EJ1TrjAqOzIuc.jpg","fr":"https://image.tmdb.org/t/p/w500/eH4KkHYHA7CkWnHb0qoFbsOIV6V.jpg","de":"https://image.tmdb.org/t/p/w500/3ZKMR799BsDAOU5zKsXQwsg4OQ9.jpg"}'::jsonb WHERE id = 89;
UPDATE public.films SET tmdb_id = 522938, titoli_i18n = '{"de":"Rambo - Last Blood","fr":"Rambo : Last Blood","en":"Rambo: Last Blood","it":"Rambo: Last Blood","es":"Rambo: Last Blood"}'::jsonb, trame_i18n = '{"de":"John Rambo hat viele große Schlachten in seinem Leben geschlagen – nun soll endlich Schluss sein. Zurückgezogen lebt der Kriegsveteran inzwischen auf einer abgelegenen Farm in Arizona. Doch der einstige Elitekämpfer kommt nicht zur Ruhe. Als die Enkeltochter seiner Haushälterin Maria verschleppt wird, begibt sich Rambo auf eine Rettungsmission nach Mexiko. Schon bald sieht er sich dort einem der mächtigsten und skrupellosesten Drogenkartelle gegenüber. Die vielen Jahre im Kampf mögen Rambo gezeichnet haben, aber sie haben ihn nicht weniger gefährlich gemacht…","fr":"John Rambo doit sauver une jeune fille retenue captive par des trafiquants de drogues à la frontière entre le Mexique et les Etats-Unis.","en":"After fighting his demons for decades, John Rambo now lives in peace on his family ranch in Arizona, but his rest is interrupted when Gabriela, the granddaughter of his housekeeper María, disappears after crossing the border into Mexico to meet her biological father. Rambo, who has become a true father figure for Gabriela over the years, undertakes a desperate and dangerous journey to find her.","it":"Ormai anziano, John Rambo cerca di condurre una vita tranquilla nel ranch di famiglia in Arizona. Quando la sua giovane nipote viene rapita in Messico da un cartello della droga, Rambo si reca oltre confine scatendando un''ultima, spietata vendetta.","es":"Después de luchar contra sus demonios durante décadas, John Rambo vive ahora en paz en su rancho familiar en Arizona, pero su descanso se ve interrumpido cuando Gabriela, la nieta de su ama de llaves María, desaparece después de cruzar la frontera con México con el propósito de conocer a su padre biológico. Rambo, que con los años se ha convertido para Gabriela en una verdadera figura paterna, emprende un desesperado y peligroso viaje para encontrarla."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/mVMm6BGBdB1HOpTyBCXaO2Nlt2T.jpg","fr":"https://image.tmdb.org/t/p/w500/q6h6ZK0JykZ1Jl736SM9zBZN3by.jpg","en":"https://image.tmdb.org/t/p/w500/kTQ3J8oTTKofAVLYnds2cHUz9KO.jpg","it":"https://image.tmdb.org/t/p/w500/qs5u7sQLLZZGvLu0yQ9alCmV7wm.jpg","es":"https://image.tmdb.org/t/p/w500/kG3pY61LWGAzcaSne12CGEeRvtg.jpg"}'::jsonb WHERE id = 90;
UPDATE public.films SET tmdb_id = 4780, titoli_i18n = '{"it":"Obsession - Complesso di colpa","en":"Obsession","es":"Fascinación (Obsession)","fr":"Obsession","de":"Schwarzer Engel"}'::jsonb, trame_i18n = '{"it":"Un uomo d''affari di New Orleans subisce un grave trauma quando la moglie e la figlia muoiono durante un tragico tentativo di riscatto. Anni dopo, durante un viaggio a Firenze, incontra una giovane donna identica alla defunta moglie, sprofondando in un vortice di ossessione e inganni.","en":"A wealthy New Orleans businessman becomes obsessed with a young woman who resembles his late wife.","es":"Michael Courtland (Cliff Robertson), un importante hombre de negocios de Nueva Orleáns, pierde a su mujer Elizabeth (Genevieve Bujoid) y a su hija de nueve años en el fatal desenlace de un trágico secuestro. Muchos años después, durante un viaje por Italia con un socio suyo (John Lithgow), queda fascinado al conocer a Sandra, una joven que es el vivo retrato de su esposa.","fr":"Ayant vu sa femme mourir faute d''avoir payé la rançon exigée par leurs kidnappeurs, Michael Courtland, homme d''affaires américain, rencontre un jour en Italie une femme lui ressemblant comme deux gouttes d''eau. Malgré les avertissements de son entourage, il y voit une seconde chance qu''il ne veut pas laisser passer. Au risque de réveiller un passé douloureux...","de":"1959 werden Frau und Tochter von Immobilienmakler Michael Courtland entführt. Die Kidnapper entkommen, sterben bei einem Unfall. Michael sieht die Familie nie wieder. Sechzehn Jahre später reist er nach Florenz und begegnet in der Kirche, in der er getraut wurde, Restauratorin Sandra, die seiner Frau ähnlich sieht. Er verliebt sich in sie. Bei der Hochzeit in New York wiederholt sich die Geschichte. Sandra ist in Wahrheit seine Tochter, die sich mit Courtlands Partner verschworen hat, der auch damals für die Entführung verantwortlich war..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/g0kwlD4KLYCJ4AcCPg0yyvPhv7G.jpg","en":"https://image.tmdb.org/t/p/w500/a0bOKTldOJVJivmPNGBHfMYJU9x.jpg","es":"https://image.tmdb.org/t/p/w500/9160yxML0m3XiBdwdfrJwBlS356.jpg","fr":"https://image.tmdb.org/t/p/w500/9BsjHxDY6mYzbm34yuA25QCJf0Q.jpg","de":"https://image.tmdb.org/t/p/w500/8RlB98ebtU2m5PiuDQ2FZuOcdmK.jpg"}'::jsonb WHERE id = 91;
UPDATE public.films SET tmdb_id = 5155, titoli_i18n = '{"en":"Obsession","fr":"Les Amants diaboliques","de":"Von Liebe besessen","es":"Obsesión","it":"Ossessione"}'::jsonb, trame_i18n = '{"en":"Gino, a drifter, begins an affair with inn-owner Giovanna as they plan to get rid of her older husband.","fr":"Bragana tient un café-garage sur la route qui longe le Po. Gino, chômeur et vagabond, demande du travail à Bragana. D''abord méfiant, celui-ci le prend en amitié quand il découvre ses talents de mécanicien. Gino a d''autres talents et devient l''amant de la femme de Bragana, Giovanna. Très vite ils vont se débarrasser du mari gênant. Mais ce meurtre transformera leur passion en enfer.","de":"Der junge Gelegenheitsarbeiter Gino kehrt in einer abgelegenen Trattoria in der Po-Ebene ein. Sie wird von dem grobschlächtigen Bragana und seiner jungen Frau Giovanna bewirtschaftet. Schon bei ihrer ersten Begegnung ist ein erotisches Knistern zwischen Giovanna und Gino zu spüren. Giovanna überredet ihren Mann, Gino als Mechaniker einzustellen. Und kaum ist der Wirt außer Haus, wird Gino zum Geliebten Giovannas. Besessen von ihrer Leidenschaft sehen die Liebenden nur einen Weg zu ihrem gemeinsamen Glück: Bragana muß sterben ...","es":"Giovanna (Clara Calamai) es una hermosa joven malcasada con el viejo propietario de un restaurante. Su sórdida vida cambiará con la aparición de un vagabundo que se convierte en su amante y al que inducirá a matar a su marido. Adaptación de la novela de James Cain \"El cartero siempre llama dos veces\".","it":"Gino, un girovago senza meta, si innamora ricambiato di Giovanna, una donna insoddisfatta sposata con il proprietario di una trattoria. La passione travolgente tra i due li spinge a eliminare il marito, ma il senso di colpa e il destino distruggeranno il loro legame."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/dHB6NdsOxO0dc71ciP2hsv3nTPf.jpg","fr":"https://image.tmdb.org/t/p/w500/zDaZRT5GO6KPP1JiF4ZhLbwWiX8.jpg","de":"https://image.tmdb.org/t/p/w500/3iXqrbHty7fnDndMlKha3ddtxPk.jpg","es":"https://image.tmdb.org/t/p/w500/dZtbu1ObXnfO0RcM5RghIrfcHQd.jpg","it":"https://image.tmdb.org/t/p/w500/qgDF8yuJa9eEcfBqEQrqbJuxe5z.jpg"}'::jsonb WHERE id = 92;
UPDATE public.films SET tmdb_id = 35852, titoli_i18n = '{"it":"Obsession","es":"Obsession","en":"Obsession","fr":"Obsession","de":"Der Wahnsinn des Dr. Clive"}'::jsonb, trame_i18n = '{"it":"Un medico londinese scopre che la moglie lo tradisce e decide di attuare una macabra vendetta. Rapisce l''amante della donna e lo tiene nascosto in un garage abbandonato, pianificando di scioglierlo gradualmente nell''acido.","es":"La hermosa esposa del Dr. Clive Riordan llega a casa una noche con el diplomático estadounidense Bill Kronin. Riordan, consumido por los celos que le producen las repetidas aventuras de su mujer, decide liquidar a su nuevo rival y planea, utilizando sus conocimientos de psiquiatría, el asesinato perfecto.","en":"A British psychiatrist devises a devilish revenge plot against his wife''s lover.","fr":"L''épouse de Dr Clive Riordan, \"Storm\", rentre une nuit en compagnie d''un diplomate américain, Bill Kronin. Riordan, obsédé par la jalousie, décide d''assassiner son plus récent rival et projette, comme seul un psychiatre le ferait, non seulement de tuer Bill, mais de commettre le crime parfait dans le processus.","de":"Der Psychiater Dr. Clive Riordan erfährt, dass seine Frau Storm eine Affäre mit dem amerikanischen Schriftsteller Bill Cronin hat. Aus Eifersucht und verletztem Stolz fasst er einen mörderischen Plan.  Clive entführt Cronin und sperrt ihn in einem abgelegenen Raum seines Hauses ein. Er will den Rivalen nicht einfach töten, sondern ihn psychisch und körperlich zugrunde richten. Dabei entwickelt sich zwischen Täter und Opfer ein gefährliches Katz-und-Maus-Spiel.  Während Clive seinen Plan immer weiter verfolgt, beginnt seine scheinbar perfekte Kontrolle über die Situation zu zerbrechen. Storm wird zunehmend misstrauisch, und die Gefahr wächst, dass seine Tat ans Licht kommt.  Der Film ist ein düsterer Psychothriller über Eifersucht, Besessenheit und Rache, bei dem weniger körperliche Gewalt als die psychologische Manipulation im Mittelpunkt steht."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/rEOBZMcw29R0kGQJkrUDgtXCU2Z.jpg","es":"https://image.tmdb.org/t/p/w500/7BlzTHGLBxxCiqY0fTvPqaE2hcX.jpg","en":"https://image.tmdb.org/t/p/w500/7BlzTHGLBxxCiqY0fTvPqaE2hcX.jpg","fr":"https://image.tmdb.org/t/p/w500/7BlzTHGLBxxCiqY0fTvPqaE2hcX.jpg","de":"https://image.tmdb.org/t/p/w500/2Ml9uCOJnCv9fGb117RmFON5gNT.jpg"}'::jsonb WHERE id = 93;
UPDATE public.films SET tmdb_id = 98544, titoli_i18n = '{"es":"Obsesión","en":"Obsession","it":"Obsession","fr":"Berlin Niagara","de":"Obsession"}'::jsonb, trame_i18n = '{"es":"Una historia de dos pasiones. En la ciudad de Berlín, en vías de crecimiento y expansión, Myriam (Heike Makatsch), una trompetista, vive con Pierre (Charles Berling), a quien ama profundamente. También se siente irresistiblemente atraída hacia John (Daniel Craig), quien trata de resolver un misterio alrededor de una vieja fotografía de periódico, que muestra a un equilibrista cruzando las Cataratas del Niágara. Los tres acaban en París, tras la pista de un anciano que conoce el secreto detrás de la fotografía; un secreto que tendrá un hondo efecto en sus vidas y en el amor.","en":"Two men become entangled in a torrid love affair with the same woman. Pierre is Miriam''s longtime lover. John is desperately searching for clues about his past when he and Miriam have a fateful encounter in a Berlin train station. The allure of forbidden love becomes irresistible, and an intense love triangle is ignited. Who will Miriam choose? Who will walk away? For two men who desperately adore the same woman and for the woman who loves them equally...there is no easy way out.","fr":"Un été à Berlin. Trois jeunes gens sont pris dans les filets d''une étrange attirance. Myriam, la Berlinoise, étudie l''orgue et joue de la trompette dans un orchestre de salsa rock féminin. Elle rêve de pouvoir voler et veut un enfant. Pierre, le Français, est médecin biologiste et coureur de marathon. John, le blond sculpteur du Zimbabwe, vient à Berlin pour résoudre une énigme.","de":"Obsession ist ein französisch-deutsches Filmdrama aus dem Jahr 1997.","it":"Una giovane musicista si trova divisa tra l''amore per due uomini completamente differenti tra loro a Berlino. La situazione sfocia in un complesso triangolo amoroso guidato da passione, insicurezze e scelte dolorose."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg","en":"https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg","it":"https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg","fr":"https://image.tmdb.org/t/p/w500/gXMKIGR1meZxMnKiQiUhTCjmVBh.jpg","de":"https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg"}'::jsonb WHERE id = 94;
UPDATE public.films SET tmdb_id = 1339713, titoli_i18n = '{"it":"Obsession","en":"Obsession","es":"Obsession","fr":"Obsession","de":"Obsession – Du sollst mich lieben"}'::jsonb, trame_i18n = '{"it":"Un thriller psicologico ad alta tensione che esplora i confini della mente umana, le relazioni tossiche e le conseguenze estreme del desiderio inconfessabile e del possesso.","en":"After breaking the mysterious \"One Wish Willow\" to win his crush''s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.","es":"El anhelo romántico desesperado de un chico por su amor platónico de toda la vida desencadena un siniestro hechizo: Nikki se vuelve irracionalmente obsesiva hasta convertirse en la sombra de Bear. Una fantasía aparentemente inofensiva que se convertirá en una perturbadora pesadilla.","fr":"Et si vous pouviez réaliser votre rêve le plus fou ? Un jeune introverti met la main sur un objet magique capable d’exaucer n’importe quel souhait. Son crush de toujours tombe alors raide dingue de lui… jusqu’à l’obsession la plus totale. Faites attention à ce que vous souhaitez !","de":"Als der hoffnungslose Romantiker Bear einen magischen Gegenstand nutzt, damit sein Crush endlich Gefühle für ihn entwickelt, muss er feststellen, dass manche Wünsche einen finsteren, unheimlichen Tribut fordern."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kwprCwsIV4LvAqJC1dmiTAdZDJ1.jpg","en":"https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg","es":"https://image.tmdb.org/t/p/w500/p1QFjQ8wwlXXlxwaWlehJ37uXVj.jpg","fr":"https://image.tmdb.org/t/p/w500/mDCR1frpUvGfIKksuM440VLb7X9.jpg","de":"https://image.tmdb.org/t/p/w500/1bAhSRf3BVOCI9zNzTLrsJA1LAq.jpg"}'::jsonb WHERE id = 95;
UPDATE public.films SET tmdb_id = 1083381, titoli_i18n = '{"it":"The Backrooms","es":"Backrooms","en":"Backrooms","fr":"Backrooms","de":"Backrooms"}'::jsonb, trame_i18n = '{"it":"Un giovane precipita accidentalmente oltre i confini della realtà ritrovandosi intrappolato nelle Backrooms, una dimensione parallela costituita da uno sconfinato e inquietante labirinto di uffici vuoti, pareti gialle, moquette umida e luci al neon ronzanti. Mentre tenta disperatamente di trovare una via d''uscita, deve eludere spietate entità ostili che cacciano all''interno di questo spazio liminale.","es":"Una extraña puerta aparece en el sótano de una tienda de muebles. Cuando el paciente de una terapeuta desaparece en una dimensión más allá de la realidad, ella deberá adentrarse en lo desconocido para intentar rescatarlo.","en":"A strange doorway appears in the basement of a furniture showroom.","fr":"Une étrange porte apparaît dans le sous-sol d''un magasin de meubles.","de":"Kahle, verschachtelte Büroflure, endlose beige-gelbe Wände, ein unaufhörliches, unerträglich lautes Surren von Leuchtstoffröhren: Die „Backrooms“ beschreiben eine neue Art von Albtraum, eine menschenleere Parallelwelt sich wiederholender, fensterloser Stockwerke, die unsere Realität auf den ersten Blick spiegelt und sich ihr doch mit jedem Schritt weiter entzieht. Verstörend verlassen wirken die labyrinthischen Räume, doch allein ist man dort nicht..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/MIINS3Q31PEYGM7d3mwJE5mV4L.jpg","es":"https://image.tmdb.org/t/p/w500/ur2yYTVGPkEDmLdoQ1Obm2RKXuU.jpg","en":"https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg","fr":"https://image.tmdb.org/t/p/w500/thQQ3BBBhGDtWm3UTtabhyDJd8U.jpg","de":"https://image.tmdb.org/t/p/w500/nsp6DZb0Z2CAHcaRTsw2kwsN6ul.jpg"}'::jsonb WHERE id = 96;
UPDATE public.films SET tmdb_id = 31510, titoli_i18n = '{"it":"Ben-Hur: A Tale of the Christ","es":"Ben-Hur","en":"Ben-Hur: A Tale of the Christ","fr":"Ben-Hur","de":"Ben Hur"}'::jsonb, trame_i18n = '{"it":"Un giovane principe ebreo viene ingiustamente accusato di aver attentato alla vita del governatore romano dal suo amico d''infanzia Messala. Ridotto in schiavitù, cercherà il riscatto e la vendetta.","es":"En los años del Imperio Romano del reinado de Augusto y su sucesor Tiberio, Judá Ben-Hur, hijo de una familia noble de Jerusalén, y Mesala, tribuno romano que dirige los ejércitos de ocupación, se han convertido en enemigos irreconciliables. Acusado de atentar contra la vida del nuevo gobernador romano, Mesala le encarcela junto a su familia. Cuando se llevan a Ben-Hur a galeras, un joven llamado Jesús de Nazaret se apiada de él y le da de beber.","en":"Judah Ben-Hur, a wealthy Jewish prince in Jerusalem, is betrayed by his childhood friend, Roman tribune Messala, and wrongfully sent to the galley slaves.","fr":"Parce qu’il a refusé à son ami Messala de collaborer avec l’occupant romain, Ben-Hur est envoyé aux galères, tandis que sa sœur Tirzah et sa mère sont jetées au cachot. Il est adopté par le tribun Quintus Arrius, qui lui doit la vie.","de":"Basierend auf dem selben Buch von Lew Wallace, das auch Vorlage für die gleichnamige Monumentalverfilmung von 1959 mit Charlton Heston war, geht es in diesem Stummfilm um einen Juden, der zu Unrecht wegen eines Anschlags auf einen Römer festgenommen und in einem Sklavenschiff aus seiner Heimat Jerusalem fortgebracht wird. Da auch seine Familie festgenommen wird, schwört er, sich an den Verantwortlichen zu rächen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg","es":"https://image.tmdb.org/t/p/w500/x65AGnMC5gS1VVf6BKbhJMQ3F6t.jpg","en":"https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg","fr":"https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg","de":"https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg"}'::jsonb WHERE id = 97;
UPDATE public.films SET tmdb_id = 665, titoli_i18n = '{"en":"Ben-Hur","it":"Ben-Hur","es":"Ben-Hur","fr":"Ben-Hur","de":"Ben Hur"}'::jsonb, trame_i18n = '{"en":"In ancient Judea, a Jewish aristocrat opposing Roman occupation of his homeland reunites with his childhood friend, now a Roman commander — setting in motion a saga of betrayal, adventure, tragedy, revenge, and faith.","it":"Giuda Ben-Hur, un ricco principe ebreo di Gerusalemme, viene tradito dall''amico d''infanzia Messala e inviato come schiavo sulle galere. Dopo essere sopravvissuto e aver salvato un console romano, torna in patria per vendicarsi sfidando Messala in un''epica corsa con i carri.","es":"Antigua Roma, bajo el reinado de los emperadores Augusto y Tiberio (s. I d.C.). Judá Ben-Hur, hijo de una familia noble de Jerusalén, y Mesala, tribuno romano que dirige los ejércitos de ocupación, son dos antiguos amigos, pero un accidente involuntario los convierte en enemigos irreconciliables: Ben-Hur es acusado de atentar contra la vida del nuevo gobernador romano, y Mesala lo encarcela a él y a su familia. Mientras Ben-Hur es trasladado a galeras para cumplir su condena, un hombre llamado Jesús de Nazaret se apiada de él y le da de beber. En galeras conocerá al comandante de la nave y más tarde a un jeque árabe que participa con sus magníficos caballos en carreras de cuadrigas.","fr":"Judas Ben-Hur, prince de Judée, retrouve son ami d’enfance Messala, venu prendre la tête de la garnison de Jérusalem. Mais leur amitié ne peut résister à leurs caractères différents. Alors qu’une pierre tombe du balcon de la maison familiale de Ben‐Hur, manquant de tuer le gouverneur qui paradait plus bas, Messala trahit son ami qu’il sait innocent en l’envoyant aux galères et en jetant en prison sa mère et sa sœur. Ben-Hur jure alors de reconquérir sa liberté et prépare sa vengeance.","de":"Als Judah Ben-Hurs Jugendfreund Messala, der ihm einst das Leben rettete, nach Jerusalem kommt, um dort neuer römischer Kommandant zu werden, ist die Wiedersehensfreude auf beiden Seiten groß. Die Freundschaft zwischen Messala und Judah wird auf die Probe gestellt, als Judah die jüdischen Aufständischen verraten soll. Nachdem bei einer römischen Parade der neue Statthalter vor Judahs Haus schwer verletzt wird, verdächtigt man Judah und seine Familie des Attentats. Unschuldig in den Kerkern gefangen, schwört Judah sich blutig für das begangene Unrecht an Messala zu rächen. Mit seiner Verbannung auf eine Galeere beginnt für den stolzen Judah eine Odyssee, die ihn von den Meeren über die Wagenrennen in Rom Jahre später wieder nach Jerusalem bringt, wo Judah hofft, seine Familie zu finden und seine Rachepläne zu vollenden."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/m4WQ1dBIrEIHZNCoAjdpxwSKWyH.jpg","it":"https://image.tmdb.org/t/p/w500/4pHkQ4rY44zbgXh9grnqn0UzUgr.jpg","es":"https://image.tmdb.org/t/p/w500/bG0yaRTC7N0bWhlaPXsyi3ZnbMo.jpg","fr":"https://image.tmdb.org/t/p/w500/4KH7VM5YyGwxe4kLSNxix2PNTn6.jpg","de":"https://image.tmdb.org/t/p/w500/mn4GERBRBWmkGOYXFibcOlURpCV.jpg"}'::jsonb WHERE id = 98;
UPDATE public.films SET tmdb_id = 271969, titoli_i18n = '{"it":"Ben-Hur","en":"Ben-Hur","es":"Ben-Hur","de":"Ben Hur","fr":"Ben-Hur"}'::jsonb, trame_i18n = '{"it":"Rivisitazione moderna del classico di Lew Wallace: Giuda Ben-Hur viene accusato ingiustamente di tradimento dal fratello adottivo Messala, ufficiale dell''esercito romano. Dopo anni trascorsi in mare come schiavo, torna per cercare la resa dei conti nella grande arena dei carri.","en":"A falsely accused nobleman survives years of slavery to take vengeance on his best friend who betrayed him.","es":"Judah Ben-Hur es un príncipe falsamente acusado de traición por su hermano adoptivo Messala, un oficial del ejército romano. Desposeído de su título y separado de su familia y de la mujer que ama, Judah es condenado a la esclavitud en las galeras. Después de varios años, Judah regresa a su tierra natal en busca de venganza, pero encontrará su propia redención.","de":"Der jüdische Prinz Judah Ben-Hur und der Sohn eines römischen Steuereintreibers Messala wachsen gemeinsam zu jener Zeit auf, zu der auch Jesus Christus lebt. Sie sind beste Freunde, bis Messala eines Tages nach Rom geht, um sich dort weiterzubilden. Jahre später kommt er als völlig veränderter Mensch zurück, hat nur noch Spott für Judah und vor allem für dessen Religion übrig. Schon bald intrigiert er gegen seinen einstigen Freund und sorgt dafür, dass dessen Familie im Gefängnis landet und Judah auf ein Sklavenschiff gebracht wird. Der dort dem sicheren Tod geweihte Ben-Hur überlebt wie durch ein Wunder und kennt nur noch ein Ziel: Rache. Die bietet sich schließlich bei einem Wagenrennen in Rom, an welchem Ben-Hur im Dienste des ihm wohlgesonnenen Scheichs Ilderim teilnimmt …","fr":"Le prince Judah Ben-Hur est accusé à tort de trahison par Messala, son frère adoptif, officier de l’armée romaine. Déchu de son titre, séparé de sa famille et de la femme qu’il aime, Judah est réduit à l’esclavage. Après des années en mer, Judah revient sur sa terre natale dans le but de se venger. Il va y rencontrer son destin."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/vKtbuybPbG2DuMieD0FGU3aVcGs.jpg","en":"https://image.tmdb.org/t/p/w500/c9CoGrBA5yw8A7YBMz0hGzfzpNq.jpg","es":"https://image.tmdb.org/t/p/w500/wBGgyiRfj7poy0BBCGa0kDDRlmf.jpg","de":"https://image.tmdb.org/t/p/w500/eKDp1MndIye89hAfAq5Fykn2bPC.jpg","fr":"https://image.tmdb.org/t/p/w500/xo6niyf90QTimKOppsIiKPuDhIL.jpg"}'::jsonb WHERE id = 99;
UPDATE public.films SET tmdb_id = 653, titoli_i18n = '{"es":"Nosferatu","fr":"Nosferatu","it":"Nosferatu il vampiro (Nosferatu eine Symphonie des Grauens)","de":"Nosferatu, eine Symphonie des Grauens","en":"Nosferatu"}'::jsonb, trame_i18n = '{"es":"Año 1838. En la ciudad de Wisborg viven felices el joven Hutter y su mujer Ellen, hasta que el oscuro agente inmobiliario Knock decide enviar a Hutter a Transilvania para cerrar un negocio con el conde Orlok. Se trata de la venta de una finca de Wisborg, que linda con la casa de Hutter. Durante el largo viaje Hutter pernocta en una posada, donde hojea un viejo tratado sobre vampiros que encuentra en su habitación. Una vez en el castillo, es recibido por el siniestro conde. Al día siguiente, Hutter amanece con dos pequeñas marcas en el cuello, que interpreta como picaduras de mosquito. Una vez firmado el contrato, descubre que el conde es, en realidad, un vampiro. Al verle partir hacia su nuevo hogar, Hutter teme por Ellen.","fr":"En 1838, Hutter, jeune clerc de notaire, part conclure une vente avec un châtelain des Carpathes. Après des rencontres menaçantes et de funestes présages, il est reçu par le comte Orlock qui n''est autre que la réincarnation du vampire Nosferatu, créature qui ne peut vivre qu''en suçant le sang des humains. Ce chef-d''œuvre du cinéma muet d''épouvante tourné en décors naturels est la première adaptation fidèle du célèbre roman de Bram Stocker, Dracula, publié en 1897.","it":"Il misterioso Conte Orlok decide di acquistare una casa a Wisborg, portando con sé la peste e il terrore. Il giovane Thomas Hutter e sua moglie Ellen cercheranno di fermare la letale minaccia.","de":"Stummfilm aus dem Jahr 1922 von Regisseur F. W. Murnau, basierend auf dem Roman „Dracula“ von Bram Stoker. Ein Immobilienagent erhält den Auftrag, für einen Kunden namens Graf Dracula nach Transsylvanien zu reisen, der sich für den Kauf eines Hauses in Wisborg (und seine Frau) interessiert. Klassiker der Stummfilmzeit, der vielfach kopiert wurde.","en":"The mysterious Count Orlok summons a happily married real estate agent to his castle, located up in the Transylvanian mountains, to finalise a terrifying deal."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/z45rXmIF0zl4uxRc5XcSfz6hYO6.jpg","fr":"https://image.tmdb.org/t/p/w500/9WUpFfsUIHuiY4MwTEw46Rvf1Od.jpg","it":"https://image.tmdb.org/t/p/w500/zx24O7VAs6NbJhiIrUhWysAiHS0.jpg","de":"https://image.tmdb.org/t/p/w500/zEzQTngP7F4qVmLDCWg5Hby6cgX.jpg","en":"https://image.tmdb.org/t/p/w500/zv7J85D8CC9qYagAEhPM63CIG6j.jpg"}'::jsonb WHERE id = 100;
UPDATE public.films SET tmdb_id = 6404, titoli_i18n = '{"es":"Nosferatu. Vampiro de la noche","fr":"Nosferatu, fantôme de la nuit","en":"Nosferatu the Vampyre","it":"Nosferatu, il principe della notte (Nosferatu: Phantom der Nacht)","de":"Nosferatu – Phantom der Nacht"}'::jsonb, trame_i18n = '{"es":"Jonathan Harker viaja desde Wismar a Transilvania, al castillo del legendario conde Drácula, con el fin de venderle una mansión en su ciudad. Atraído por una fotografía de Lucy, la mujer de Harker, Nosferatu parte inmediatamente hacia Wismar, llevando con él muerte y el horror.","fr":"Au XIXe siècle, Jonathan Harker se rend en Transylvanie pour vendre un manoir au comte Dracula. Sur la route, les villageois lui conseillent de rebrousser chemin mais le jeune homme refuse. Au moment de la signature, Dracula aperçoit un portrait de la fiancée de Harker, identique en tous points à sa défunte épouse. Jonathan est fait prisonnier et le comte se rend à Londres pour retrouver la jeune femme.","en":"A real estate agent leaves behind his beautiful wife to go to Transylvania to visit the mysterious Count Dracula and formalize the purchase of a property in Wismar.","it":"In questo celebre remake del film di Murnau, il tormentato Conte Dracula viaggia dalla Transilvania a Wismar, diffondendo la peste e cercando ossessivamente l''amore della giovane Lucy Harker.","de":"Jonathan Harker ist alles andere als begeistert, als er den Auftrag erhält, von Wismar ins ferne Transsylvanien zu reisen. Dort interessiert sich ein gewisser Graf Dracula für den Kauf eines Hauses in der Hansestadt. Schweren Herzens verabschiedet er sich von seiner geliebten Frau und reitet los. Er ahnt nicht, welches Grauen ihn erwartet."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ej8BnlGwoiWmugLLsNrRUdjCm4t.jpg","fr":"https://image.tmdb.org/t/p/w500/sIWTseJwPMTXuOC3wCAhkGP4VEt.jpg","en":"https://image.tmdb.org/t/p/w500/jHKzGYwf7P34vz8MhJBTN6cnaYD.jpg","it":"https://image.tmdb.org/t/p/w500/kiwmmJIX7eUcUoR5CBxGW0xruJO.jpg","de":"https://image.tmdb.org/t/p/w500/enHF1OyflcvJHcJsJ8RttNYqfv1.jpg"}'::jsonb WHERE id = 101;
UPDATE public.films SET tmdb_id = 426063, titoli_i18n = '{"en":"Nosferatu","es":"Nosferatu","fr":"Nosferatu","de":"Nosferatu - Der Untote","it":"Nosferatu"}'::jsonb, trame_i18n = '{"en":"A gothic tale of obsession between a haunted young woman and the terrifying vampire infatuated with her, causing untold horror in its wake.","es":"Historia gótica de obsesión entre una joven hechizada y el aterrador vampiro encaprichado de ella que causa un indescriptible terror a su paso.","fr":"Dans l''Allemagne de 1838, Thomas Hutter, agent immobilier, est envoyé en Transylvanie pour rencontrer le mystérieux comte Orlok, intéressé par l''achat d''une propriété à Wisborg. Laissant derrière lui sa jeune épouse, Ellen, sujette à des visions inquiétantes, Thomas découvre rapidement la véritable nature du comte : un vampire terrifiant. Pendant ce temps, à Wisborg, Ellen est de plus en plus tourmentée par des cauchemars prémonitoires liés à Orlok. Lorsque le comte s''installe dans sa nouvelle demeure, une série d''événements horrifiques se déclenche, plongeant la ville dans la terreur et la désolation.","de":"Eine Geschichte über die Besessenheit zwischen einer gequälten jungen Frau und dem furchteinflößenden Vampir, der in sie vernarrt ist und unbeschreiblichen Schrecken hinterlässt.","it":"Una rivisitazione gotica e terrificante della classica leggenda, incentrata sull''ossessione tra una giovane donna tormentata e il mostruoso vampiro infatuato di lei."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/d0B8xDdqBZlzlPEzES8lu5LlNQn.jpg","es":"https://image.tmdb.org/t/p/w500/jivUhECegXI3OYtPVflWoIDtENt.jpg","fr":"https://image.tmdb.org/t/p/w500/A8UIMJTwSaflmWmUlfPOFdenSBT.jpg","de":"https://image.tmdb.org/t/p/w500/yig53WzBjX84iSYWKb2BCYYxFLM.jpg","it":"https://image.tmdb.org/t/p/w500/1SftujfE9iqZpGJfnREO4IBeeqV.jpg"}'::jsonb WHERE id = 102;
UPDATE public.films SET tmdb_id = 9361, titoli_i18n = '{"it":"L''ultimo dei mohicani","en":"The Last of the Mohicans","es":"El último mohicano","de":"Der letzte Mohikaner","fr":"Le Dernier des Mohicans"}'::jsonb, trame_i18n = '{"it":"Durante la guerra franco-indiana nel 1757, tre cacciatori, tra cui l''inglese adottato dai Mohicani Occhio di Falco, si ritrovano a proteggere le figlie di un colonnello britannico dall''attacco dei feroci Uroni guidati dal vendicativo Magua.","en":"In war-torn colonial America, in the midst of a bloody battle between British, the French and Native American allies, the aristocratic daughter of a British Colonel and her party are captured by a group of Huron warriors. Fortunately, a group of three Mohican trappers comes to their rescue.","es":"En 1757, a orillas del río Hudson, tropas francesas e inglesas luchan por el dominio de la región. Los ingleses reclutan a los granjeros asentados en esas tierras para formar un ejército capaz de enfrentarse a las tropas franco-indias. Hawkeye -Ojo de halcón- (Daniel Day-Lewis) es un hombre blanco adoptado por los indios mohicanos que vive con su padre (Russell Means) y su hermano Uncas (Eric Schweig). Tras rescatar de una emboscada de los hurones a Cora Munro (Madeleine Stowe) y a su hermana pequeña Alice (Jodhi May), hijas de un oficial británico, los tres deciden acompañarlas al fuerte inglés William Henry, que está siendo asediado por franceses y hurones. Allí les obligan a quedarse con un grupo de británicos que acaban de llegar de las colonias...","de":"1757 streiten Engländer und Franzosen um die Vorherrschaft in Nordamerika. Leidtragende sind die Indianer, die als Hilfstruppen verheizt werden. Chingachgooks weißer Adoptivsohn Hawkeye weigert sich, für die englische Miliz zu kämpfen, und verliebt sich in Colonelstochter Cora …","fr":"En 1757 dans l’État de New York, alors que la guerre fait rage entre Français et Anglais pour l’appropriation des territoires indiens, un jeune officier anglais, Duncan Heyward, est chargé d’escorter deux sœurs, Cora et Alice, jusqu’a leur père. Ils sont sauvés d’une embuscade par Hawkeye, un frontalier d’origine européenne, élevé par le Mohican Chingachgook et son fils Uncas. Les trois hommes acceptent d’escorter les deux jeunes filles jusqu’à leur destination finale."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/rGQUmxjKg0Hx9kHkSPTm0D3dcE.jpg","en":"https://image.tmdb.org/t/p/w500/qzJMPWRtZveBkxXOv3ucWhoJuyj.jpg","es":"https://image.tmdb.org/t/p/w500/mM9ewvwSZM5DdHFeSaFtRJYDCij.jpg","de":"https://image.tmdb.org/t/p/w500/miGwamVR6zd9ADwCsrdZ6aPniE3.jpg","fr":"https://image.tmdb.org/t/p/w500/tWaGxm8LkneIICsM8FvcTSUKvMB.jpg"}'::jsonb WHERE id = 103;
UPDATE public.films SET tmdb_id = 1204680, titoli_i18n = '{"en":"Coyote vs. Acme","es":"Coyote vs. Acme","fr":"Coyote vs. Acme","de":"Coyote vs. ACME","it":"Coyote vs. Acme"}'::jsonb, trame_i18n = '{"en":"After Acme products fail him one too many times in his dogged pursuit of the Roadrunner, Wile E. Coyote decides to hire a billboard lawyer to sue the Acme Corporation.","es":"Después de que todos los productos fabricados por ACME Corporation le salgan mal a Wile E. Coyote, en su persecución del Correcaminos, contrata a un abogado humano igualmente desafortunado para demandar a la empresa. Cuando el abogado de Wile E. descubre que el intimidante jefe de su antiguo bufete es el director general de ACME, se une a Wile E. para ganar el juicio contra él.","fr":"L''avocat Kevin Avery est engagé par Vil Coyote, un personnage des Looney Tunes qui veut attaquer en justice le conglomérat ACME. D''après lui, l''entreprise fabriquerait des produits défectueux. Kevin va découvrir que son ancien patron, Buddy Crane, est désormais le représentant légal de ladite société...","de":"Nach all den Jahren vergeblicher Liebesmüh hat Willi Kojote es satt, dass bisher jedes einzelne Produkt der ACME Corporation eine erfolgreiche Jagd auf den Road Runner vereitelt hat. Kojote beschließt deshalb, das Unternehmen für seine mangelhafte Ware in die Verantwortung zu nehmen, und engagiert den ebenso glück- wie mittellosen Anwalt Kevin Avery, um gegen ACME vor Gericht zu ziehen. Als der herausfindet, dass die Rechtsabteilung des Konzerns von Buddy Crane geleitet wird, dem selbstgefälligen Chef seiner ehemaligen Kanzlei, gibt er alles, um den Prozess zu gewinnen.","it":"Wile E. Coyote decide di fare causa alla Acme Corporation per via dei suoi prodotti costantemente difettosi. Per farlo, assume un avvocato umano di scarso successo che si ritroverà a rappresentarlo in tribunale contro il potente CEO della Acme."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg","es":"https://image.tmdb.org/t/p/w500/vWFz9spZFBkJvForuYrKK2ntOLB.jpg","fr":"https://image.tmdb.org/t/p/w500/dFwseuSlDUNiwMuElDb3OAOQ8En.jpg","de":"https://image.tmdb.org/t/p/w500/lHiLrnVKMZS4RmPYOFgXaCh0tQb.jpg","it":"https://image.tmdb.org/t/p/w500/x2AtkVKU8IDgeScz354aqoYjUQG.jpg"}'::jsonb WHERE id = 104;
UPDATE public.films SET tmdb_id = 385704, titoli_i18n = '{"es":"Farewell Oak Street","en":"Farewell Oak Street","it":"Farewell Oak Street","de":"Farewell Oak Street","fr":"Farewell Oak Street"}'::jsonb, trame_i18n = '{"en":"This documentary presents a before-and-after picture of people in a large-scale public housing project in Toronto. Due to a housing shortage, they were forced to live in squalid, dingy flats and ramshackle dwellings on a crowded street in Regent Park North; now they have access to new, modern housing developments designed to offer them privacy, light and space.","it":"Questo documentario canadese analizza le degradate condizioni di vita nel quartiere di Regent Park a Toronto prima della sua ricostruzione. Attraverso il contrasto tra i vecchi slum di Oak Street e i nuovi complessi di edilizia popolare, l''opera illustra l''impatto positivo che una pianificazione urbana moderna e alloggi dignitosi hanno sulla salute, sulla sicurezza e sul benessere sociale delle famiglie."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg","en":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg","it":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg","de":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg","fr":"https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg"}'::jsonb WHERE id = 106;
UPDATE public.films SET tmdb_id = 1101383, titoli_i18n = '{"en":"The End of Oak Street","it":"Oak Street","es":"El final de Oak Street","de":"The End of Oak Street","fr":"La fin d''Oak Street"}'::jsonb, trame_i18n = '{"en":"After a mysterious cosmic event rips Oak Street from suburbia and transports their neighborhood to someplace unknown, the Platt family soon discovers that their very survival depends on them sticking together as they navigate their now unrecognizable surroundings.","it":"Un intenso thriller psicologico ambientato in una tranquilla periferia americana. Quando un''intera famiglia scompare misteriosamente dal civico 42 di Oak Street senza lasciare alcuna traccia, un investigatore in pensione decide di condurre un''indagine autonoma. Con il passare dei giorni, l''uomo porterà alla luce una complessa rete di oscuri segreti e menzogne sepolte da decenni all''interno dell''apparentemente impeccabile comunità locale.","es":"Después de que un misterioso fenómeno cósmico arranque Oak Street de su entorno suburbano y transporte a sus habitantes a un lugar desconocido, la familia Platt pronto descubre que su propia supervivencia depende de que permanezcan unidos mientras se orientan en un entorno que ya no reconocen.","de":"Ein unerklärliches kosmisches Ereignis reißt die Oak Street aus ihrem Vorstadtidyll heraus und befördert die gesamte Nachbarschaft an einen unbekannten Ort. Die Mitglieder der Familie Platt müssen in dieser für sie völlig fremden Umgebung schnell feststellen, dass sie nur dann überleben können, wenn sie eng zusammenstehen.","fr":"Lorsqu’un mystérieux événement cosmique arrache Oak Street à sa paisible banlieue et la transporte vers un lieu inconnu, la famille Platt, désorientée dans ce nouvel environnement hostile, comprend vite qu’il leur faudra rester unis pour survivre."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/7DmtuAK5gYGlMFA45Oxkl1bEpIC.jpg","it":"https://image.tmdb.org/t/p/w500/54mt6Tg2Hj4M9A4mpkGrLktTiJR.jpg","es":"https://image.tmdb.org/t/p/w500/g9DUGw8ufetrwhCIrwq3h1NlpWO.jpg","de":"https://image.tmdb.org/t/p/w500/4XS0AJqgcl9uNS67hRsrO7Ff4ya.jpg","fr":"https://image.tmdb.org/t/p/w500/yZINaQysj32K2DS2EW4Iy1bK4Bm.jpg"}'::jsonb WHERE id = 107;
UPDATE public.films SET tmdb_id = 1101383, titoli_i18n = '{"it":"La fine di Oak Street","es":"El final de Oak Street","fr":"La fin d''Oak Street","en":"The End of Oak Street","de":"The End of Oak Street"}'::jsonb, trame_i18n = '{"it":"In una tranquilla e apparentemente perfetta via residenziale chiamata Oak Street, una serie di eventi inspiegabili e sparizioni misteriose scatena la paranoia tra i residenti, costringendo una madre a fare i conti con un oscuro segreto del passato per salvare la sua famiglia.","es":"Después de que un misterioso fenómeno cósmico arranque Oak Street de su entorno suburbano y transporte a sus habitantes a un lugar desconocido, la familia Platt pronto descubre que su propia supervivencia depende de que permanezcan unidos mientras se orientan en un entorno que ya no reconocen.","fr":"Lorsqu’un mystérieux événement cosmique arrache Oak Street à sa paisible banlieue et la transporte vers un lieu inconnu, la famille Platt, désorientée dans ce nouvel environnement hostile, comprend vite qu’il leur faudra rester unis pour survivre.","en":"After a mysterious cosmic event rips Oak Street from suburbia and transports their neighborhood to someplace unknown, the Platt family soon discovers that their very survival depends on them sticking together as they navigate their now unrecognizable surroundings.","de":"Ein unerklärliches kosmisches Ereignis reißt die Oak Street aus ihrem Vorstadtidyll heraus und befördert die gesamte Nachbarschaft an einen unbekannten Ort. Die Mitglieder der Familie Platt müssen in dieser für sie völlig fremden Umgebung schnell feststellen, dass sie nur dann überleben können, wenn sie eng zusammenstehen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/54mt6Tg2Hj4M9A4mpkGrLktTiJR.jpg","es":"https://image.tmdb.org/t/p/w500/g9DUGw8ufetrwhCIrwq3h1NlpWO.jpg","fr":"https://image.tmdb.org/t/p/w500/yZINaQysj32K2DS2EW4Iy1bK4Bm.jpg","en":"https://image.tmdb.org/t/p/w500/7DmtuAK5gYGlMFA45Oxkl1bEpIC.jpg","de":"https://image.tmdb.org/t/p/w500/4XS0AJqgcl9uNS67hRsrO7Ff4ya.jpg"}'::jsonb WHERE id = 108;
UPDATE public.films SET tmdb_id = 9273, titoli_i18n = '{"it":"Ace Ventura - Missione Africa","en":"Ace Ventura: When Nature Calls","es":"Ace Ventura II. Operación África","fr":"Ace Ventura en Afrique","de":"Ace Ventura - Jetzt wird''s wild"}'::jsonb, trame_i18n = '{"it":"L''acchiappanimali Ace Ventura si reca in Africa per ritrovare Chicca, un raro pipistrello bianco sacro alla tribù dei Ciakaka, la cui scomparsa rischia di scatenare una guerra tribale.","en":"Summoned from an ashram in Tibet, Ace finds himself on a perilous journey into the jungles of Africa to find Shikaka, the missing sacred animal of the friendly Wachati tribe. He must accomplish this before the wedding of the Wachati''s Princess to the prince of the warrior Wachootoos. If Ace fails, the result will be a vicious tribal war.","es":"Intentando superar el trauma que le ha dejado el fracaso de su última misión, donde no pudo evitar que muriera la mofeta que tenía que rescatar, el inefable detective Ace Ventura es requerido en su retiro en un monasterio de monjes budistas por un extraño personaje que le ofrece una fuerte suma de dinero para que trate de encontrar el animal sagrado de una tribu.","fr":"Parce qu’il n’a pu sauver un raton laveur perdu en haute montagne, Ace Ventura s’est retiré dans une lamaserie au Tibet. Mais, à la faveur d’une nouvelle mission, Ace Ventura part en Afrique mettre la main sur une chauve‐souris blanche sacrée disparue avant qu’un conflit n’éclate entre les tribus Wachati et Wachootoo.","de":"Nach dem tragischen Unfall eines Klienten hat sich Tierdetektiv Ace Ventura zum Meditieren in ein tibetanisches Kloster zurückgezogen. Doch schon bald muß der gefragte Schnüffler seine spirituelle Enklave wieder verlassen, um im tiefsten Afrika eine entführte Albino-Fledermaus auftreiben - immerhin steht der Friede zwischen zwei Urwaldstämmen auf dem Spiel. Nach einigen haarsträubenden Dschungelerlebnissen macht der Meisterdetektiv die Gauner dingfest."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5Ygaz8czBDmTGKtACnFFauUKCOC.jpg","en":"https://image.tmdb.org/t/p/w500/wcinCf1ov2D6M3P7BBZkzQFOiIb.jpg","es":"https://image.tmdb.org/t/p/w500/899yWih4ic8AyczedYiX41g7TvQ.jpg","fr":"https://image.tmdb.org/t/p/w500/pfe3WBJzufMawUiQ9agzitTFcei.jpg","de":"https://image.tmdb.org/t/p/w500/5qWRDf3nYfneEnrIQRoUXqBnLY6.jpg"}'::jsonb WHERE id = 109;
UPDATE public.films SET tmdb_id = 197, titoli_i18n = '{"it":"Braveheart - Cuore impavido","es":"Braveheart","fr":"Braveheart","en":"Braveheart","de":"Braveheart"}'::jsonb, trame_i18n = '{"it":"Nel XIII secolo, dopo l''uccisione della sua amata da parte dei soldati inglesi, il patriota scozzese William Wallace guida una sanguinosa ribellione contro il tirannico re Edoardo I d''Inghilterra per conquistare la libertà della Scozia.","es":"¿Qué clase de hombre desafiaría a un rey? ''Braveheart'' es una historia épica medieval sobre la independencia de Escocia en el siglo XIII, basada en la leyenda de William Wallace, un montañés escocés que arrastra a su clan a luchar contra la tiranía del rey Eduardo I de Inglaterra. Después del brutal asesinato de su joven esposa por los ingleses, Wallace sólo busca venganza. Hambrientos y en inferior número, Wallace lidera a los patriotas escoceses y consigue organizar un ejército de guerreros sedientos de libertad logrando recuperar con ello el espíritu que haría a Escocia libre para siempre.","fr":"À la fin du XIIIe siècle, le roi Edward 1er d''Angleterre s''empare du trône d’Écosse, réduisant son peuple à la misère. William Wallace donne le signe de la révolte et, à la tête d''une armée de gueux, parvient à reconquérir plusieurs places fortes. Mais les nobles écossais sont lâchés et par deux fois trahissent le héros de leur peuple…","en":"Enraged at the slaughter of Murron, his new bride and childhood love, Scottish warrior William Wallace slays a platoon of the local English lord''s soldiers. This leads the village to revolt and, eventually, the entire country to rise up against English rule.","de":"Ende des 13. Jahrhunderts ermorden britische Besatzer die geliebte Frau des in Schottland lebenden William Wallace. Von dieser Tat aufgestachelt und blind vor Rache, mobilisiert er seine schottischen Landleute für einen Feldzug gegen die übermächtigen Engländer. Trotz ihrer nicht nur zahlenmäßigen Unterlegenheit schafft man das Unfassbare und besiegt die Armee des britischen Königs. Nach dem Sieg stehen jedoch nicht alle Schotten hinter Wallace und verraten ihren Freiheitskämpfer."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/gZvvrgehgqYNy12Z2sP333nn5Nw.jpg","es":"https://image.tmdb.org/t/p/w500/cDMYybBU4COJfTwcPgnihwY5EiP.jpg","fr":"https://image.tmdb.org/t/p/w500/jMDUKicyulag7KeTWVrblElCMZq.jpg","en":"https://image.tmdb.org/t/p/w500/or1gBugydmjToAEq7OZY0owwFk.jpg","de":"https://image.tmdb.org/t/p/w500/5MiqFuwgBrvIF3KJ6nWaqUeAe52.jpg"}'::jsonb WHERE id = 110;
UPDATE public.films SET tmdb_id = 597, titoli_i18n = '{"it":"Titanic","es":"Titanic","de":"Titanic","en":"Titanic","fr":"Titanic"}'::jsonb, trame_i18n = '{"it":"Un giovane artista di umili origini e una ricca nobildonna promessa sposa si innamorano a bordo del transatlantico Titanic durante il suo tragico viaggio inaugurale nel 1912.","es":"Jack, un joven artista, gana en una partida de cartas un pasaje para viajar a América en el Titanic, el transatlántico más grande y seguro jamás construido. A bordo conoce a Rose, una joven de una buena familia venida a menos que va a contraer un matrimonio de conveniencia con Cal, un millonario engreído a quien sólo interesa el prestigioso apellido de su prometida. Jack y Rose se enamoran, pero el prometido y la madre de ella ponen todo tipo de trabas a su relación. Mientras, el gigantesco y lujoso transatlántico se aproxima hacia un inmenso iceberg.","de":"Atlantischer Ozean, 1912: Auf der Jungfernfahrt der Titanic trifft der mittellose Maler Jack Dawson auf die schöne, aber unglückliche Erste-Klasse-Passagierin Rose DeWitt Bukater. Rose reist gemeinsam mit ihrer Mutter und ihrem versnobten Verlobten Cal, den sie aus finanziellen Gründen heiraten soll, aber nicht liebt. Als Jack beobachtet, wie Rose über die Reling klettert, um sich ins Meer zu stürzen, und ihren sicheren Tod abwenden kann, beginnt für beide eine Liebesgeschichte über Klassengrenzen hinweg. Gemeinsam mit Jack entdeckt Rose das ausgelassene Leben der einfachen Passagiere unter Deck der Titanic und das wahre Wesen der Liebe. Währenddessen steuert die als unsinkbar geltende Titanic geradewegs auf einen Eisberg zu.","en":"101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic''s departure through to its death—on its first and last voyage—on April 15, 1912.","fr":"Southampton, 10 avril 1912. Le paquebot le plus grand et le plus moderne du monde, réputé pour son insubmersibilité, le « Titanic », appareille pour son premier voyage. Quatre jours plus tard, il heurte un iceberg. À son bord, un artiste pauvre et une grande bourgeoise tombent amoureux."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/i87I2HPumcMkX5Vl48n2XkS5Os7.jpg","es":"https://image.tmdb.org/t/p/w500/2tltWMvvTqscFtdujTXDsRFTqKQ.jpg","de":"https://image.tmdb.org/t/p/w500/MlnPG3oxhfmuiDwcoeElQWui9m.jpg","en":"https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg","fr":"https://image.tmdb.org/t/p/w500/vpsvHLkoeKUjceIMeNSqCp3xEyY.jpg"}'::jsonb WHERE id = 111;
UPDATE public.films SET tmdb_id = 333371, titoli_i18n = '{"it":"10 Cloverfield Lane","es":"Calle Cloverfield 10","de":"10 Cloverfield Lane","en":"10 Cloverfield Lane","fr":"10 Cloverfield Lane"}'::jsonb, trame_i18n = '{"it":"Dopo un incidente d''auto, una giovane donna si risveglia in un bunker sotterraneo insieme a un uomo che sostiene di averle salvato la vita da un attacco chimico apocalittico.","es":"Una joven sufre un accidente de coche. Cuando despierta se encuentra encerrada en una celda bajo tierra, secuestrada por un hombre extraño que dice haberla salvado del día del juicio final. El excéntrico captor asegura que el exterior es inhabitable por culpa de un terrible ataque químico, algo que no sabe si creer. Es así como comienza su pesadilla, en una espiral de desconocimiento. La mente del criminal es infranqueable, y ella tendrá que intentar analizar a su enemigo para conseguir sobrevivir.","de":"Michelle verlässt nach einem Streit New Orleans und fährt davon. Doch dann kommt es auf der wenig befahrenen nächtlichen Straße zu einem schweren Unfall. Die junge Frau verliert das Bewusstsein. Als sie später wieder aufwacht, findet sie sich nicht in einem Krankenhaus wieder, sondern in einem Bunker tief unter der Erde. Howard behauptet, dass er sie gerettet hat und die Umgebung angegriffen wird. Die meisten Menschen sollen demnach schon tot sein. Doch Michelle möchte nicht ewig auf engstem Raum mit fremden Personen zusammenleben. Mit Emmett, dem Dritten im Bunker, schließt sie sich zusammen und plant den Ausbruch aus den Fängen des immer paranoider werdenden Howard. Noch wissen sie nicht, was sie an der Oberfläche erwartet …","en":"After a catastrophic car crash, a young woman wakes up in a survivalist''s underground bunker, where he claims to have saved her from an apocalyptic attack that has left the outside world uninhabitable.","fr":"Une jeune femme se réveille dans une cave après un accident de voiture. Ne sachant pas comment elle a atterri dans cet endroit, elle pense tout d''abord avoir été kidnappée. Son gardien tente de la rassurer en lui disant qu''il lui a sauvé la vie après une attaque chimique d''envergure. En l''absence de certitude, elle décide de s''échapper…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/266EUEBypO6shSfYwUpaCeNPCAb.jpg","es":"https://image.tmdb.org/t/p/w500/ksLwEavVceUxYyF8LOjTewmpTp4.jpg","de":"https://image.tmdb.org/t/p/w500/kbrhW3WfutKdIPd70orhh1gVZ8n.jpg","en":"https://image.tmdb.org/t/p/w500/q8A39vcBDruhvoDTJd6L8a4lnTi.jpg","fr":"https://image.tmdb.org/t/p/w500/gAw5nJGNDI2hyw2ghBLoD6rSk3Y.jpg"}'::jsonb WHERE id = 112;
UPDATE public.films SET tmdb_id = 384521, titoli_i18n = '{"it":"The Cloverfield Paradox","en":"The Cloverfield Paradox","fr":"The Cloverfield Paradox","es":"The Cloverfield Paradox","de":"The Cloverfield Paradox"}'::jsonb, trame_i18n = '{"it":"Un gruppo di scienziati a bordo di una stazione spaziale testa un acceleratore di particelle per risolvere una crisi energetica globale, ma si ritrova in una dimensione alternativa.","en":"Orbiting above a planet on the brink of war, scientists test a device to solve an energy crisis and end up face-to-face with a dark alternate reality.","fr":"Une équipe de scientifiques envoyée en orbite pour sauver la planète d''une destruction imminente se retrouve face à une sombre réalité alternative.","es":"Con la Tierra en guerra y en mitad de una crisis energética, un equipo de astronautas se encuentra en el espacio tratando de dar con una solución a los problemas del planeta. Pero durante una maniobra fallida, quedan flotando sin saber muy bien qué o cómo volver a su lugar de origen, y las cosas dentro de la nave ocultan una realidad mucho más terrorífica.","de":"In fünf Jahren werden die Energieressourcen der Erde komplett erschöpft sein. Im Orbit vor der Erde treibend, versuchen Wissenschaftler auf einer Raumstation, die Energiekrise zu lösen. Ein riskantes Experiment mit dem Shepard-Teilchenbeschleuniger soll die Lösung bringen: Funktioniert es, wäre die Energiekrise gelöst! Doch etwas geht schief – die Wissenschaftler entdecken eine alternative Realität und kämpfen bald um ihr Leben."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hxKqEX748hwOkgcxs498x5qQ7Vk.jpg","en":"https://image.tmdb.org/t/p/w500/vJi2ExTcWdJR3150VPKqqtdGxsT.jpg","fr":"https://image.tmdb.org/t/p/w500/vJi2ExTcWdJR3150VPKqqtdGxsT.jpg","es":"https://image.tmdb.org/t/p/w500/hyeJDZxsXatr2XoPtH46NRrQ6aW.jpg","de":"https://image.tmdb.org/t/p/w500/3YZmwZirewbDyucLNMWZr3BZYMK.jpg"}'::jsonb WHERE id = 113;
UPDATE public.films SET tmdb_id = 763400, titoli_i18n = '{"en":"The Making of ''The Big Lebowski''","it":"Il grande Lebowski","es":"The Making of ''The Big Lebowski''","fr":"The Making of ''The Big Lebowski''","de":"The Making of ''The Big Lebowski''"}'::jsonb, trame_i18n = '{"en":"A short documentary about the production of \"The Big Lebowski\" (1998).","it":"Jeffrey ''Drugo'' Lebowski, un fannullone pacifista di Los Angeles, viene scambiato per un miliardario suo omonimo. Dopo che dei sicari urinano sul suo tappeto preferito, Drugo si mette alla ricerca di un risarcimento, finendo invischiato in un bizzarro mistero tra rapimenti e nichilisti."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg","it":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg","es":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg","fr":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg","de":"https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg"}'::jsonb WHERE id = 114;
UPDATE public.films SET tmdb_id = 680, titoli_i18n = '{"it":"Pulp Fiction","en":"Pulp Fiction","es":"Pulp Fiction","fr":"Pulp Fiction","de":"Pulp Fiction"}'::jsonb, trame_i18n = '{"it":"Le vite di due killer della mafia, della moglie del loro capo, di un pugile in fuga e di una coppia di rapinatori si intrecciano in una serie di bizzarri e drammatici eventi a Los Angeles.","en":"A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.","es":"Jules y Vincent, dos asesinos a sueldo con muy pocas luces, trabajan para Marsellus Wallace. Vincent le confiesa a Jules que Marsellus le ha pedido que cuide de Mia, su mujer. Jules le recomienda prudencia porque es muy peligroso sobrepasarse con la novia del jefe. Cuando llega la hora de trabajar, ambos deben ponerse manos a la obra. Su misión: recuperar un misterioso maletín.","fr":"L’odyssée sanglante et burlesque de petits malfrats dans la jungle d’Hollywood : Deux petits tueurs, un dangereux gangster marié à une camée, un boxeur roublard, des prêteurs sur gages sadiques, un caïd élégant et dévoué, un dealer bon mari et deux tourtereaux à la gâchette facile.","de":"Vincent Vega und Jules Winnfield holen für ihren Boss Marsellus Wallace eine schwarze Aktentasche aus einer Wohnung ab. Drei Jungs, die ihnen dabei im Weg stehen, lassen ihr Leben. Die Killer machen sich mit einem vierten Jungen als Geisel auf den Weg ins Hauptquartier. Doch als das Auto über eine Straßenerhöhung schaukelt, erschießt Vincent aus Versehen die Geisel. Um den blutverspritzten Wagen zu reinigen, machen die beiden einen Abstecher zu Jules''s Freund Jimmie, wo auf Befehl vom Boss ein Spezialist für schwierige Aufträge zu ihnen stößt: The Wolf..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hOpN58hkQGZph5LHhyRrryy1hzF.jpg","en":"https://image.tmdb.org/t/p/w500/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg","es":"https://image.tmdb.org/t/p/w500/hNcQAuquJxTxl2fJFs1R42DrWcf.jpg","fr":"https://image.tmdb.org/t/p/w500/4TBdF7nFw2aKNM0gPOlDNq3v3se.jpg","de":"https://image.tmdb.org/t/p/w500/hOg9USqmQmglmr5kGvpyg1XkhqN.jpg"}'::jsonb WHERE id = 115;
UPDATE public.films SET tmdb_id = 152601, titoli_i18n = '{"it":"Lei","fr":"Her","en":"Her","es":"Her","de":"Her"}'::jsonb, trame_i18n = '{"it":"In un futuro non troppo lontano, Theodore, un uomo solitario e introverso che scrive lettere d''amore per conto terzi, acquista un nuovo sistema operativo basato su un''intelligenza artificiale estremamente avanzata. Ben presto, tra Theodore e la voce del sistema operativo, che si autodefinisce Samantha, nasce una profonda e insolita relazione sentimentale.","fr":"Los Angeles, dans un futur proche. Theodore Twombly, un homme sensible au caractère complexe, est inconsolable suite à une rupture difficile. Il fait alors l''acquisition d''un programme informatique ultramoderne, capable de s''adapter à la personnalité de chaque utilisateur. En lançant le système, il fait la connaissance de ''Samantha'', une voix féminine intelligente, intuitive et étonnamment drôle. Les besoins et les désirs de Samantha grandissent et évoluent, tout comme ceux de Theodore, et peu à peu, ils tombent amoureux…","en":"In the not so distant future, Theodore, a lonely writer, purchases a newly developed operating system designed to meet the user''s every need. To Theodore''s surprise, a romantic relationship develops between him and his operating system. This unconventional love story blends science fiction and romance in a sweet tale that explores the nature of love and the ways that technology isolates and connects us all.","es":"En un futuro cercano, Theodore, un hombre solitario a punto de divorciarse que trabaja en una empresa como escritor de cartas para terceras personas, compra un día un nuevo sistema operativo basado en el modelo de Inteligencia Artificial, diseñado para satisfacer todas las necesidades del usuario. Para su sorpresa, se crea una relación romántica entre él y Samantha, la voz femenina de ese sistema operativo.","de":"In was verliebt man sich bei seinem Gegenüber zuerst? Die Augen, das Gesicht, die Hände, die Stimme? Im Falle von Theodore Twombly ist es die Stimme. Ihm bleibt auch nichts anderes als die Stimme, denn Samantha ist körperlos. Sie ist die Stimme von Theodores neuem Betriebssystem, das über eine künstliche Intelligenz verfügt – und anscheinend auch über Emotionen. Bis vor kurzem noch trudelte Theodore, professioneller Verfasser einfühlsamer Briefe für Kunden, denen die passenden Worte fehlen, recht haltlos durchs Leben, nachdem seine langjährige Beziehung mit Catherine in die Brüche gegangen ist. Doch zu seiner Verwunderung entwickelt Theodore zur Computerstimme Samantha Gefühle, die schnell über eine bloße Schwärmerei hinausgehen. Von seiner Umwelt kritisch beäugt muss sich Theodore die Frage gefallen lassen: Ist solch eine Liebe möglich?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ptoIaqRBgyBVMKXRG2V2afFqDut.jpg","fr":"https://image.tmdb.org/t/p/w500/nkWXW5blXGmOEoDejRgy83sSb6T.jpg","en":"https://image.tmdb.org/t/p/w500/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg","es":"https://image.tmdb.org/t/p/w500/xPby6SuDafflEL7EWVHTFmhJsDp.jpg","de":"https://image.tmdb.org/t/p/w500/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg"}'::jsonb WHERE id = 116;
UPDATE public.films SET tmdb_id = 207, titoli_i18n = '{"en":"Dead Poets Society","fr":"Le Cercle des poètes disparus","es":"El club de los poetas muertos","it":"L''attimo fuggente","de":"Der Club der toten Dichter"}'::jsonb, trame_i18n = '{"en":"At an elite, old-fashioned boarding school in New England, a passionate English teacher inspires his students to rebel against convention and seize the potential of every day, courting the disdain of the stern headmaster.","fr":"Todd Anderson est un garçon plutôt timide. Désormais élève de la prestigieuse académie Welton, réputée pour être l''une des plus fermées et austères des États-Unis, tout le monde attend de lui qu''il suive les traces de son frère, qui avait fait à Welton de brillantes études.  C''est là qu''il va faire la rencontre de M. Keating, un professeur de lettres anglaises qui, c''est le moins que l''on puisse dire, sort des sentiers battus. Jour après jour, M. Keating encourage ses élèves à penser par eux-mêmes et à refuser l''ordre établi. Cette rencontre va bouleverser la vie du jeune Todd, mais aussi celle de ses amis.","es":"En un elitista y estricto colegio privado de Nueva Inglaterra, un grupo de alumnos descubrirá la poesía, el significado de \"Carpe Diem\" -aprovechar el momento- y la importancia de perseguir los sueños, gracias a un excéntrico profesor que despierta sus mentes por medio de métodos poco convencionales.","it":"In un rigido collegio maschile del Vermont nel 1959, l''arrivo di un nuovo professore di letteratura, John Keating, sconvolge le vite degli studenti. Con i suoi metodi d''insegnamento anticonformisti, Keating insegna ai ragazzi ad amare la poesia, a pensare con la propria testa e a cogliere l''attimo.","de":"Der neue Literaturlehrer John Keating bringt 1959 frischen Wind in das Traditionsinternat Welton und inspiriert seine ansonsten zur Disziplin erzogenen Schüler durch sein unorthodoxes Vermitteln von Poesie zu freiem Denken. Des Nachts treffen sie sich zu Lesungen in einer alten Höhle. Der Junge Neil entdeckt seine Liebe zur Schauspielerei. Als sein gestrenger Vater davon erfährt, nimmt er Neil von der Schule. Seiner Träume beraubt, erschießt sich Neil. Keating wird verantwortlich gemacht und der Schule verwiesen. Als er seine Bücher abholt, sprechen ihm seine Schüler durch kollektive Verweigerung ihren Dank für seine Menschlichkeit aus."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/erzbMlcNHOdx24AXOcn2ZKA7R1q.jpg","fr":"https://image.tmdb.org/t/p/w500/oHBdsvdlPhzkJZOfax7Oy3X5mm7.jpg","es":"https://image.tmdb.org/t/p/w500/vsLcmuk8KBN73spAIEwm1nLNSjc.jpg","it":"https://image.tmdb.org/t/p/w500/nIH9ZI4aA8zd0tQSduMWtpniyyH.jpg","de":"https://image.tmdb.org/t/p/w500/qUV8UUGa1596hbOWzJ8AfppjpGd.jpg"}'::jsonb WHERE id = 117;
UPDATE public.films SET tmdb_id = 273248, titoli_i18n = '{"it":"The Hateful Eight","es":"Los odiosos ocho","en":"The Hateful Eight","de":"The Hateful 8","fr":"Les Huit Salopards"}'::jsonb, trame_i18n = '{"it":"Qualche anno dopo la guerra civile americana, una diligenza si fa strada nel paesaggio innevato del Wyoming. I passeggeri, tra cui il cacciatore di taglie John Ruth e la sua prigioniera Daisy Domergue, cercano rifugio da una tempesta di neve in un emporio, dove si imbattono in altri loschi personaggi. La diffidenza e la tensione tra i presenti porteranno a una sanguinosa resa dei conti.","es":"Seis, ocho o doce años después de la Guerra de Secesión, una diligencia avanza a toda velocidad por el invernal paisaje de Wyoming. Los pasajeros, el cazarrecompensas John Ruth y su fugitiva Daisy Domergue, intentan llegar rápidamente al pueblo de Red Rock, donde Ruth, conocido en estos lares como ''el Verdugo'', entregará a Domergue a la justicia. Por el camino, se encuentran con dos desconocidos: el mayor Marquis Warren, un antiguo soldado negro de la Unión convertido en cazarrecompensas de mala reputación, y Chris Mannix, un renegado sureño que afirma ser el nuevo sheriff del pueblo. Como una ventisca está a punto de alcanzarlos, Ruth, Domergue, Warren y Mannix se refugian en la Mercería de Minnie, una parada para diligencias de un puerto de montaña. Cuando llegan al local de Minnie, en lugar de recibirlos su dueña, se topan con cuatro rostros desconocidos.","en":"Bounty hunters seek shelter from a raging blizzard and get caught up in a plot of betrayal and deception.","de":"Irgendwo im verschneiten Wyoming, einige Jahre nach dem Bürgerkrieg: Eine Postkutsche kämpft sich auf dem Weg zum Städtchen Red Rock durch die Landschaft. An Bord sind der Kopfgeldjäger John Ruth, seine Gefangene Daisy Domergue und zwei erst auf dem Weg zugestiegene Passagiere: der Ex-Soldat und nun ebenfalls als Kopfgeldjäger tätige Marquis Warren sowie Chris Mannix, der angibt, der neue Sheriff von Red Rock zu sein. Aufgrund eines heftigen Schneesturms sind sie jedoch dazu gezwungen, in einer Hütte Zuflucht zu suchen. Dort verstecken sich bereits der Mexikaner Bob, der undurchsichtige Oswaldo Mobray, der Cowboy Joe Gage und der in die Jahre gekommene Südstaaten-General Sanford Smithers vor dem Wetter. Schnell nehmen die Spannungen in der Gruppe von misstrauischen Raubeinen zu, nachdem man sich anfangs noch bestens unterhalten hat. Und bald wird klar, dass längst nicht jeder von ihnen die Hütte lebend verlassen wird.","fr":"Après la Guerre de Sécession, huit voyageurs se retrouvent coincés dans un refuge au milieu des montagnes. Alors que la tempête s''abat au-dessus du massif, ils réalisent qu''ils n''arriveront peut-être pas à rallier Red Rock comme prévu…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2ogVOei8k5WPixP2RVJFMn16zII.jpg","es":"https://image.tmdb.org/t/p/w500/7DYGdFT4gtiD5BI6xyOU6v0XXvi.jpg","en":"https://image.tmdb.org/t/p/w500/jIywvdPjia2t3eKYbjVTcwBQlG8.jpg","de":"https://image.tmdb.org/t/p/w500/kicXJhMpeB5xFbBG4EHcfIyOnyK.jpg","fr":"https://image.tmdb.org/t/p/w500/kV6ogsiIYzV2qZ43bLuDKuEAIR.jpg"}'::jsonb WHERE id = 118;
UPDATE public.films SET tmdb_id = 315635, titoli_i18n = '{"en":"Spider-Man: Homecoming","it":"Spider-Man: Homecoming","es":"Spider-Man: Homecoming","fr":"Spider-Man : Homecoming","de":"Spider-Man: Homecoming"}'::jsonb, trame_i18n = '{"en":"Following the events of Captain America: Civil War, Peter Parker, with the help of his mentor Tony Stark, tries to balance his life as an ordinary high school student in Queens, New York City, with fighting crime as his superhero alter ego Spider-Man as a new threat, the Vulture, emerges.","it":"Il giovane Peter Parker, entusiasta della sua esperienza con gli Avengers, torna a casa dove vive con la zia May. Sotto l''occhio vigile del suo mentore Tony Stark, Peter cerca di trovare un equilibrio tra la sua vita da normale studente e la sua identità segreta di Spider-Man, ma l''arrivo del villain Avvoltoio metterà tutto a rischio.","es":"Peter Parker comienza a experimentar su recién descubierta identidad como el superhéroe Spider-Man. Después de la experiencia vivida con los Vengadores, Peter regresa a casa, donde vive con su tía. Bajo la atenta mirada de su mentor Tony Stark, Peter intenta mantener una vida normal como cualquier joven de su edad, pero interrumpe en su rutina diaria el nuevo villano Vulture y, con él, lo más importante de la vida de Peter comenzará a verse amenazado.","fr":"Après ses spectaculaires débuts dans Captain America : Civil War, le jeune Peter Parker découvre peu à peu sa nouvelle identité, celle de Spider-Man, le super-héros lanceur de toile. Galvanisé par son expérience avec les Avengers, Peter rentre chez lui auprès de sa tante May, sous l’œil attentif de son nouveau mentor, Tony Stark. Il s’efforce de reprendre sa vie d’avant, mais au fond de lui, Peter rêve de se prouver qu’il est plus que le sympathique super héros du quartier. L’apparition d’un nouvel ennemi, le Vautour, va mettre en danger tout ce qui compte pour lui...","de":"Nach seinem Aufeinandertreffen mit den Avengers ist Peter Parker alias Spider-Man wieder zurück in New York, wo er bei seiner Tante May wohnt. Seitdem er mit bzw. gegen die anderen Helden kämpfte, fragt er sich, ob er mit seinen herausragenden Fähigkeiten nicht mehr machen sollte, als nur die freundliche Spinne aus der Nachbarschaft zu sein, die den einen oder anderen Einbruch verhindert und Taschendiebe stoppt. Doch daneben muss der von seinem neuen Mentor Tony Stark geförderte Jugendliche auch noch den Alltag auf die Reihe bekommen, den Alltag als Teenager an einer Highschool, wo er sich in Liz verguckt hat. Blöd, dass ausgerechnet in dieser Situation ein Bösewicht für Unruhe sorgt, der technisch bestens ausgestattet ist und von Rachedurst getrieben: der Vogelmann Vulture."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/c24sv2weTHPsmDa7jEMN0m2P3RT.jpg","it":"https://image.tmdb.org/t/p/w500/9OYK3q83z0LmFOx3xZXfdaVck2d.jpg","es":"https://image.tmdb.org/t/p/w500/bRl6C6FwzTndk0MBGZZ68nRFlw3.jpg","fr":"https://image.tmdb.org/t/p/w500/wFNNv1ZHglNdXJLYiEgpLY5sa9S.jpg","de":"https://image.tmdb.org/t/p/w500/elU7H73qN3WEQmmfdn0CdH3q8H8.jpg"}'::jsonb WHERE id = 119;
UPDATE public.films SET tmdb_id = 429617, titoli_i18n = '{"it":"Spider-Man: Far From Home","en":"Spider-Man: Far From Home","es":"Spider-Man: Lejos de casa","fr":"Spider-Man : Far From Home","de":"Spider-Man: Far From Home"}'::jsonb, trame_i18n = '{"it":"Peter Parker decide di unirsi ai suoi migliori amici per una vacanza in Europa. Tuttavia, il piano di Peter di lasciarsi i superpoteri alle spalle per qualche settimana viene sventato quando accetta di aiutare Nick Fury a svelare il mistero degli attacchi di diverse creature elementali.","en":"Peter Parker and his friends go on a summer trip to Europe. However, they will hardly be able to rest - Peter will have to agree to help Nick Fury uncover the mystery of creatures that cause natural disasters and destruction throughout the continent.","es":"Peter Parker decide irse junto a MJ, Ned y el resto de sus amigos a pasar unas vacaciones a Europa. Sin embargo, el plan de Parker por dejar de lado sus superpoderes durante unas semanas se ven truncados cuando Nick Fury contacta con él para solicitarle ayuda para frenar el ataque de unas criaturas elementales que están causando el caos en el continente. En ese momento, Parker vuelve a ponerse el traje de Spider-Man para cumplir con su labor.","fr":"Peter et ses amis passent leurs vacances d’été en Europe. Mais ils n’auront pas vraiment l’occasion de se reposer puisque Peter accepte d’aider Nick Fury pour débusquer les mystérieuses créatures qui sont la cause des catastrophes naturelles qui frappent le continent.","de":"Nach der epischen Schlacht gegen Thanos und den schicksalshaften Ereignissen um die Avengers ist Peter zurück an seiner alten Schule. Um vom Superheldendasein etwas auszuruhen, kommt ihm eine Klassenfahrt nach Europa gerade recht, auch um seiner heimlichen Liebe \"MJ\" endlich seine Gefühle gestehen zu können. Die erste Station ist Venedig in Italien. Nach einer entspannten Gondelfahrt mit der Reisegruppe bricht aber plötzlich das Chaos los: Ein riesiges Monster kommt aus dem Wasser und greift die Stadt an. Dem stellt sich ein bisher unbekannter Superheld namens Mysterio entgegen. Und als wäre das nicht genug, taucht dann noch Nick Fury auf, um Spider-Man für eine Mission zu rekrutieren..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/blWCg2gs0uQiEl4e3ml6j3yDSKg.jpg","en":"https://image.tmdb.org/t/p/w500/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg","es":"https://image.tmdb.org/t/p/w500/iKVR1ba3W1wCm9bVCcpnNvxQUWX.jpg","fr":"https://image.tmdb.org/t/p/w500/xVYGzjMaHVwNQ9STT5ZXcz7knsB.jpg","de":"https://image.tmdb.org/t/p/w500/mp2rchOm2nchJ3E3fPzTFzkuLd3.jpg"}'::jsonb WHERE id = 120;
UPDATE public.films SET tmdb_id = 634649, titoli_i18n = '{"en":"Spider-Man: No Way Home","fr":"Spider-Man : No Way Home","it":"Spider-Man: No Way Home","de":"Spider-Man: No Way Home","es":"Spider-Man: No Way Home"}'::jsonb, trame_i18n = '{"en":"Peter Parker is unmasked and no longer able to separate his normal life from the high-stakes of being a super-hero. When he asks for help from Doctor Strange the stakes become even more dangerous, forcing him to discover what it truly means to be Spider-Man.","fr":"Après les événements liés à l''affrontement avec Mysterio, l''identité secrète de Spider-Man a été révélée. Il est poursuivi par le gouvernement américain, qui l''accuse du meurtre de Mysterio, et traqué par les médias. Cet événement a également des conséquences terribles sur la vie de sa petite-amie M.J. et de son meilleur ami Ned. Désemparé, Peter Parker demande alors de l''aide au docteur Strange. Ce dernier lance un sort pour que tout le monde oublie que Peter est Spider-Man. Mais les choses ne se passent pas comme prévu, et cette action altère la stabilité de l''espace-temps. Cela ouvre le « multivers », un concept terrifiant dont ils ne savent quasiment rien...","it":"Per la prima volta nella storia cinematografica di Spider-Man, viene rivelata l''identità del nostro amichevole eroe di quartiere. Quando Peter chiede aiuto al Dottor Strange per ripristinare il suo segreto, l''incantesimo squarcia un buco nel loro mondo, liberando i più potenti nemici mai affrontati da uno Spider-Man in qualsiasi universo.","de":"Peter Parker ist demaskiert und kann sein normales Leben nicht mehr von den hohen Einsätzen als Superheld trennen. Als er Doctor Strange um Hilfe bittet, wird die Lage noch gefährlicher und er muss entdecken, was es wirklich bedeutet, Spider-Man zu sein.","es":"Peter Parker es desenmascarado y por tanto no es capaz de separar su vida normal de los enormes riesgos que conlleva ser un súper héroe. Cuando pide ayuda a Doctor Strange, los riesgos pasan a ser aún más peligrosos, obligándole a descubrir lo que realmente significa ser Spider-Man."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg","fr":"https://image.tmdb.org/t/p/w500/jwfDFqzxBkXC5bERBZrCEfK9iii.jpg","it":"https://image.tmdb.org/t/p/w500/xLnZ0DB06H0MuGXcF0uhJxr6b8y.jpg","de":"https://image.tmdb.org/t/p/w500/iNKf4D0AzOj9GLq8ZyG3WZaqibL.jpg","es":"https://image.tmdb.org/t/p/w500/accAPImdjUwgNgocDNWXCGFEcvL.jpg"}'::jsonb WHERE id = 121;
UPDATE public.films SET tmdb_id = 603, titoli_i18n = '{"es":"Matrix","fr":"Matrix","de":"Matrix","en":"The Matrix","it":"Matrix"}'::jsonb, trame_i18n = '{"es":"Thomas Anderson lleva una doble vida: por el día es programador en una importante empresa de software, y por la noche un hacker informático llamado Neo. Su vida no volverá a ser igual cuando unos misteriosos personajes le inviten a descubrir la respuesta a la pregunta que no le deja dormir: ¿qué es Matrix?","fr":"Programmeur anonyme dans un service administratif le jour, Thomas Anderson devient Neo la nuit venue. Sous ce pseudonyme, il est l''un des pirates les plus recherchés du cyber‐espace. À cheval entre deux mondes, Neo est assailli par d''étranges songes et des messages cryptés provenant d''un certain Morpheus. Celui‐ci l''exhorte à aller au‐delà des apparences et à trouver la réponse à la question qui hante constamment ses pensées : qu''est‐ce que la Matrice ? Nul ne le sait, et aucun homme n''est encore parvenu à en percer les défenses. Mais Morpheus est persuadé que Neo est l''Élu, le libérateur mythique de l''humanité annoncé selon la prophétie. Ensemble, ils se lancent dans une lutte sans retour contre la Matrice et ses terribles agents…","de":"Der Hacker Neo wird übers Internet von einer geheimnisvollen Untergrund-Organisation kontaktiert. Der Kopf der Gruppe – der gesuchte Terrorist Morpheus – weiht ihn in ein entsetzliches Geheimnis ein: Die Realität, wie wir sie erleben, ist nur eine Scheinwelt. In Wahrheit werden die Menschen längst von einer unheimlichen virtuellen Macht beherrscht – der „Matrix“, deren Agenten Neo bereits im Visier haben …","en":"Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.","it":"Un programmatore e hacker di nome Neo scopre che la realtà che vive è una simulazione virtuale creata da macchine senzienti, unendosi a un gruppo di ribelli per liberare l''umanità."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/tpW2X2DvxtTHJ61iJ7zNYYrJihs.jpg","fr":"https://image.tmdb.org/t/p/w500/pEoqbqtLc4CcwDUDqxmEDSWpWTZ.jpg","de":"https://image.tmdb.org/t/p/w500/iVmDLujHcV1zaMnaahKWn4TcCS6.jpg","en":"https://image.tmdb.org/t/p/w500/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg","it":"https://image.tmdb.org/t/p/w500/3vmTUXJHlKkvenf8G35dr5HlTEh.jpg"}'::jsonb WHERE id = 122;
UPDATE public.films SET tmdb_id = 604, titoli_i18n = '{"it":"Matrix Reloaded","en":"The Matrix Reloaded","fr":"Matrix Reloaded","es":"Matrix Reloaded","de":"Matrix Reloaded"}'::jsonb, trame_i18n = '{"it":"Mentre l''esercito delle macchine prepara un attacco contro Zion, Neo scopre maggiori dettagli sul suo destino come l''Eletto e affronta una minaccia crescente rappresentata dall''Agente Smith.","en":"The Resistance builds in numbers as humans are freed from the Matrix and brought to the city of Zion. Neo discovers his superpowers, including the ability to see the code inside the Matrix. With machine sentinels digging to Zion in 72 hours, Neo, Morpheus and Trinity must find the Keymaker to ultimately reach the Source.","fr":"Neo apprend à mieux contrôler ses dons naturels, alors même que Sion s''apprête à tomber sous l''assaut de l''Armée des Machines. D''ici quelques heures, 250 000 Sentinelles programmées pour anéantir notre espèce envahiront la dernière enclave humaine de la Terre. Mais Morpheus galvanise les citoyens de Sion en leur rappelant la Parole de l''Oracle : il est encore temps pour l’Élu d''arrêter la guerre contre les Machines. Tous les espoirs se reportent dès lors sur Neo. Au long de sa périlleuse plongée au sein de la Matrice et de sa propre destinée, ce dernier sera confronté à une résistance croissante, une vérité encore plus aveuglante, un choix encore plus douloureux que tout ce qu''il avait jamais imaginé.","es":"Las máquinas avanzan imparables hacia Zion en su afán por destruir a toda la humanidad y todas las naves se preparan para la dura batalla. Neo junto con Morfeo y Trinity buscan el camino del elegido dentro de Matrix para vencer a las máquinas y se encuentran con dificultades inesperadas: el agente Smith ha vuelto y no sólo eso, otros programas dentro de Matrix intentarán acabar con su misión. Mientras tanto Neo se tendrá que adaptar a la vida real y a la fama de ser el elegido.","de":"Die Wächter schwärmen aus. Smith klont sich. Neo fliegt … aber vielleicht kann selbst der Auserwählte mit seinen atemberaubenden neuen Fähigkeiten den Angriff der Maschinen nicht mehr aufhalten.  Neo. Morpheus. Trinity. Zurück im spannenden zweiten Kapitel der Matrix-Trilogie treffen sie auf außergewöhnliche Verbündete: Gemeinsam bekämpfen sie ihre Gegner, die sich klonen, durch Upgrades immer stärker werden und die letzte Festung der Menschheit belagern."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/uWkkhMhJKBsjPkbPcRm4nlYUZxH.jpg","en":"https://image.tmdb.org/t/p/w500/8xEVAe84zlL9rkfYT6dZXero4KK.jpg","fr":"https://image.tmdb.org/t/p/w500/lF5HiiRmBlL3mc5SnO4QsdmlvOb.jpg","es":"https://image.tmdb.org/t/p/w500/7IZk3Xp3HIpRJGXFYNvzmyRwDlt.jpg","de":"https://image.tmdb.org/t/p/w500/eq7GAThE7piM4SsUIgRJQzU4lLB.jpg"}'::jsonb WHERE id = 123;
UPDATE public.films SET tmdb_id = 605, titoli_i18n = '{"it":"Matrix Revolutions","en":"The Matrix Revolutions","es":"Matrix Revolutions","de":"Matrix Revolutions","fr":"Matrix Revolutions"}'::jsonb, trame_i18n = '{"it":"L''assedio a Zion raggiunge il culmine mentre Neo stringe un patto con la città delle macchine per fermare l''Agente Smith, divenuto un virus capace di distruggere entrambi i mondi.","en":"The human city of Zion defends itself against the massive invasion of the machines as Neo fights to end the war at another front while also opposing the rogue Agent Smith.","es":"Quedan veinte horas para la irrupción de las máquinas en Sión, el último bastión de los humanos libres. Mientras el cuerpo de Neo permanece en coma, su consciencia se encuentra en tierra de nadie, en un lugar entre el mundo humano y el de las máquinas.","de":"Die letzte Schlacht gegen die Maschinen kämpfen Neo, der Auserwählte, Rebellionsführer Morpheus und ihre Verbündeten – ein Krieg, der in den Ruinen der realen Welt geführt wird, der das Schicksal der Menschheit besiegelt und dessen Sieg in den Händen von Neo liegt, der seinerseits eine Reihe von Überraschungen zu erwarten hat.","fr":"La longue quête de liberté des rebelles culmine en une bataille finale explosive. Tandis que l''armée des Machines sème la désolation sur Sion, ses citoyens organisent une défense acharnée. Mais pourront-ils retenir les nuées implacables des Sentinelles en attendant que Neo s''approprie l''ensemble de ses pouvoirs et mette fin à la guerre ? L''agent Smith est quant à lui parvenu à prendre possession de l''esprit de Bane, l''un des membres de l''équipage de l''aéroglisseur. De plus en plus puissant, il est désormais incontrôlable et n''obéit plus aux Machines : il menace de détruire leur empire ainsi que le monde réel et la Matrice…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cGprSBfxwOxgExQnwFz39XKl3H2.jpg","en":"https://image.tmdb.org/t/p/w500/qEWiBXJGXK28jGBAm8oFKKTB0WD.jpg","es":"https://image.tmdb.org/t/p/w500/zi1UMF9jIM2JnQz0u2AyUw8QFZi.jpg","de":"https://image.tmdb.org/t/p/w500/8lVaiIfbyZ5Oe3nLJoeAVRUXKAb.jpg","fr":"https://image.tmdb.org/t/p/w500/xOCeckuZDzqydvt3vLlzftZkef1.jpg"}'::jsonb WHERE id = 124;
UPDATE public.films SET tmdb_id = 624860, titoli_i18n = '{"it":"Matrix Resurrections","es":"Matrix Resurrections","fr":"Matrix Resurrections","de":"Matrix Resurrections","en":"The Matrix Resurrections"}'::jsonb, trame_i18n = '{"it":"Neo vive una vita ordinaria a San Francisco sotto l''identità di Thomas Anderson, finché non viene risvegliato da un nuovo gruppo di ribelli per liberare Trinity da una versione aggiornata di Matrix.","es":"En un mundo compuesto por dos realidades, lo cotidiano y lo oculto tras ella, Thomas Anderson se ve obligado de nuevo a ir tras el conejo blanco. Dicha elección continúa siendo la vía de acceso a Matrix, que esta vez es más poderosa e intrincada que en ocasiones anteriores.","fr":"Dix-huit ans après les événements de Matrix Revolutions, Thomas A. Anderson (alias Neo) ne se souvient plus de rien et mène une vie d''apparence normale à San Francisco. Il se rend régulièrement chez un psychiatre à qui il raconte ses rêves étranges et qui lui prescrit des pilules bleues. Après la réapparition de visages familiers et en quête de réponses, Neo repart à la recherche du lapin blanc. Il rencontre un certain Morpheus, qui lui offre le choix entre rester dans la Matrice et prendre son envol.","de":"Thomas Anderson lebt ein normales Leben, arbeitet für eine große Firma und geht regelmäßig zur Therapie, wo sein Therapeut versucht, ihm seine Traumata auszutreiben. Denn Thomas hat Probleme damit, Realität und Fiktion auseinanderzuhalten. Er kann doch nicht wirklich einst als Auserwählter Neo in den Krieg gegen die Maschinen gezogen sein, oder?","en":"Plagued by strange memories, Neo''s life takes an unexpected turn when he finds himself back inside the Matrix."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/sZCT1D5yLNVHarTpv157FaLzPCc.jpg","es":"https://image.tmdb.org/t/p/w500/dLIwpCTf4QoW01pp85KP9jcfTpu.jpg","fr":"https://image.tmdb.org/t/p/w500/kCF43aQ77ShTfKyY8vAJBVHN5j3.jpg","de":"https://image.tmdb.org/t/p/w500/hF7jgEhP4ypR2oS5BQD1pxbg7QY.jpg","en":"https://image.tmdb.org/t/p/w500/8c4a8kE7PizaGQQnditMmI1xbRp.jpg"}'::jsonb WHERE id = 125;
UPDATE public.films SET tmdb_id = 429, titoli_i18n = '{"en":"The Good, the Bad and the Ugly","it":"Il buono, il brutto, il cattivo","es":"El bueno, el feo y el malo","de":"Zwei glorreiche Halunken","fr":"Le Bon, la Brute et le Truand"}'::jsonb, trame_i18n = '{"en":"While the Civil War rages on between the Union and the Confederacy, three men – a quiet loner, a ruthless hitman, and a Mexican bandit – comb the American Southwest in search of a strongbox containing $200,000 in stolen gold.","it":"Durante la guerra di secessione americana, tre cinici fuorilegge - il ''Buono'' (Joe), il ''Brutto'' (Tuco) e il ''Cattivo'' (Sentenza) - cercano un tesoro nascosto contenente 200.000 dollari in oro confederato, muovendosi tra alleanze precarie, inganni e scontri mortali.","es":"Durante la Guerra de Secesión, tres cazadores de recompensas se lanzan a la búsqueda de un tesoro que ninguno de los tres truhanes puede localizar sin la ayuda de los otros dos. Tuco sabe que el tesoro se encuentra en un cementerio, mientras que Joe conoce el nombre inscrito en la tumba que lo esconde. Mientras tanto, Sentenza no duda en matar a mujeres y niños para conseguir su meta. De esta forma, los tres hombres colaboran en apariencia, pero al final intentarán eliminarse mutuamente.","de":"Ein mysteriöser Fremder, der mexikanische Revolverschütze Tuco und Sentenza, ein sadistischer Krimineller, sind auf der Jagd nach einer Geldkassette. Inhalt: 200.000 Dollar. Die drei Desperados haben untereinander nichts gemeinsam - werden aber zu Komplizen, wenn es die Situation erfordert. Doch jeder verfolgt nur ein Ziel: die Geldkassette. Und keiner von ihnen ist bereit, zu teilen...","fr":"Pendant la guerre de Sécession, Tuco et Joe se lancent à la recherche d''un coffre contenant 200 000 dollars en pièces d''or volés à l''armée sudiste. Ayant des indices complémentaires sur la cache, chacun a besoin de l''autre. Mais un troisième homme entre dans la course : Sentenza, un tueur qui ne recule devant rien pour parvenir à ses fins."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg","it":"https://image.tmdb.org/t/p/w500/n9HRt5Uq6iY9u6rdaFUHCBg14sg.jpg","es":"https://image.tmdb.org/t/p/w500/71HKV5F9bfm05ZZnjGmRuFpUVCo.jpg","de":"https://image.tmdb.org/t/p/w500/fKjmsSd6lLIanV252zqIPANfCaz.jpg","fr":"https://image.tmdb.org/t/p/w500/qEr65B4yGlsmLQjcM0xjSUMfZS2.jpg"}'::jsonb WHERE id = 126;
UPDATE public.films SET tmdb_id = 335, titoli_i18n = '{"it":"C''era una volta il West","fr":"Il était une fois dans l''Ouest","en":"Once Upon a Time in the West","es":"Hasta que llegó su hora","de":"Spiel mir das Lied vom Tod"}'::jsonb, trame_i18n = '{"it":"Una giovane vedova difende la propria terra dalle mire di un magnate delle ferrovie, aiutata da un misterioso uomo con l''armonica e da un fuorilegge romantico.","fr":"Alors que les constructeurs de chemins de fer traversent sans relâche le désert de l''Arizona en direction de la mer, Jill arrive dans la petite ville de Flagstone avec l''intention de commencer une nouvelle vie.","en":"As the railroad builders advance unstoppably through the Arizona desert on their way to the sea, Jill arrives in the small town of Flagstone with the intention of starting a new life.","es":"Mientras los constructores del ferrocarril avanzan imparables por el desierto de Arizona en su camino hacia el mar, Jill llega al pequeño pueblo de Flagstone con la intención de empezar una nueva vida.","de":"Während die Eisenbahnbauer auf ihrem Weg zum Meer unaufhaltsam durch die Wüste Arizonas marschieren, kommt Jill in der kleinen Stadt Flagstone an, um ein neues Leben zu beginnen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/3MPqF2iK6ZBoagnB5H1pjImHpHc.jpg","fr":"https://image.tmdb.org/t/p/w500/xjXKy5b2M3fDelAQItIswcDNvwm.jpg","en":"https://image.tmdb.org/t/p/w500/qbYgqOczabWNn2XKwgMtVrntD6P.jpg","es":"https://image.tmdb.org/t/p/w500/upiek8u4rHTrOJW9B0woXe4A4h7.jpg","de":"https://image.tmdb.org/t/p/w500/BwLUQDesx6GW6FtUrQGUPQtzcg.jpg"}'::jsonb WHERE id = 127;
UPDATE public.films SET tmdb_id = 336, titoli_i18n = '{"it":"Giù la testa","fr":"Il était une fois… la révolution","de":"Todesmelodie","en":"Duck, You Sucker","es":"¡Agáchate, maldito!"}'::jsonb, trame_i18n = '{"it":"Durante la rivoluzione messicana, un ingenuo bandito locale e un tormentato dinamitardo irlandese uniscono le forze in una serie di rapine che si trasformeranno in gesta eroiche.","fr":"Mexique, 1913. Un pilleur de diligences, Juan Miranda, fait chanter un spécialiste en explosifs, John Mallory, pour qu''ils s''associent afin de dévaliser la banque centrale de Mesa Verde. Tous deux se trouvent plongés en plein cœur de la tourmente de la révolution mexicaine.","de":"Mexiko, zur Zeit der Revolution: Juan Miranda, Anführer einer Banditenfamilie, trifft auf Sean Mallory, einen irischen Sprengstoffexperten der Armee, der sich auf der Flucht vor den Engländern befindet. Als Juan Seans ausgesprochen nützliche Fertigkeiten in Sachen Dynamit erkennt, überredet er ihn schließlich, sich seiner Truppe anzuschließen, die gerade im Begriff ist, die Bank von Mesa Verde auszurauben. Zusammen mit dem Revolutionsführer Dr. Villega planen sie die Attacke der Bank - die jedoch, wie sich herausstellt, anstelle von Geld nur politische Gefangene beherbergt und die Banditen unfreiwillig zu Helden der Revolution macht.","en":"At the beginning of the 1913 Mexican Revolution, greedy bandit Juan Miranda and idealist John H. Mallory, an Irish Republican Army explosives expert on the lam from the British, fall in with a band of revolutionaries plotting to strike a national bank. When it turns out that the government has been using the bank as a hiding place for illegally detained political prisoners -- who are freed by the blast -- Miranda becomes a revolutionary hero against his will.","es":"Juan Miranda y John Mallory, veterano del IRA, se conocen en México y planean trabajar juntos robando bancos. Un día dinamitan lo que creían que era un banco local y resulta ser una prisión. La explosión libera a los revolucionarios que estaban presos y ambos se convierten en héroes de la revolución. Poco tiempo después, las tropas del gobierno, comandadas por el coronel Gutiérrez, comienzan a seguirles los pasos."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qTdmSJPOW3ts04BrBRTwieA3BY9.jpg","fr":"https://image.tmdb.org/t/p/w500/5oITsFaa1MQowuQhf3H3Nr1jibW.jpg","de":"https://image.tmdb.org/t/p/w500/gfVrrpCLBqA5vTsofbQECLQvppt.jpg","en":"https://image.tmdb.org/t/p/w500/nWmAtZf83qpOai0fzehf7Hn1S3R.jpg","es":"https://image.tmdb.org/t/p/w500/zHzv1nA9azV2lLR0nu8dhIsmbjY.jpg"}'::jsonb WHERE id = 128;
UPDATE public.films SET tmdb_id = 311, titoli_i18n = '{"it":"C''era una volta in America","es":"Érase una vez en América","en":"Once Upon a Time in America","fr":"Il était une fois en Amérique","de":"Es war einmal in Amerika"}'::jsonb, trame_i18n = '{"it":"La complessa epopea di un gruppo di gangster ebrei a New York, dall''infanzia nel ghetto negli anni ''20 fino al drammatico bilancio esistenziale negli anni ''60.","es":"David Aaronson \"Noodles\", un pobre joven judío, conoce en los suburbios de principios del siglo XX de Manhattan, Nueva York, a Maximilian Bercovicz \"Max\", otro joven de origen hebreo dispuesto a llegar lejos por cualquier método. Entablan una gran amistad y forman, con los 3 colegas de \"Noodles\", Patrick Goldberg \"Patsy\", Philip Stein \"Cockeye\", y Dominic una banda que prospera rápidamente. Desgraciadamente, son perseguidos por Bugsy, el tipo para el que Noodles y sus amigos trabajaban anteriormente, y en uno de sus asaltos, mata a Dominic. Rápidamente Noodles se tira encima suyo y le mata, por lo que pasará 12 años en prisión. Cuando Noodles sale de prisión le recibe Max, que sigue con su banda junto a los otros 2 amigos, Patsy y Cockeye. Rápidamente, entre los 4, llegan a convertirse, en tiempos de la prohibición, en unos de los mayores gánsteres de todo el país.","en":"A former Prohibition-era Jewish gangster returns to the Lower East Side of Manhattan over thirty years later, where he once again must confront the ghosts and regrets of his old life.","fr":"À New York, à la fin de la prohibition, Noodles se réfugie dans une fumerie d''opium après un coup qui a mal tourné. Plus de trente ans plus tard, il est de retour en ville et se remémore son passé de gangster : de sa jeunesse de voyou dans les années 20, marquée par sa rencontre avec son ami Max et leurs nombreux trafics dans le ghetto juif de la ville, jusqu''à la période de prohibition où leur bande, liée par une profonde amitié, s''enrichit et marque son ascension dans la pègre grâce au commerce illégal d''alcool. Noodles se rappelle aussi de sa relation amoureuse échouée avec Deborah durant toute sa vie.","de":"New York zur Zeit der Prohibition. Max, Noodles und ihre Freunde verdienen sich bereits als Kinder mit Erpressungen und Schmuggeleien den einen oder anderen Dollar dazu. Jahre später – Noodles wird nach einer langen Haftstrafe für einen Mord aus dem Gefängnis entlassen – haben es die Freunde von damals unter Max zu einem skrupellosen Gangstersyndikat gebracht. Doch Ehrgeiz und Habgier zerstört die jahrzehntelange Freundschaft, und am Ende steht ein entsetzlicher Verrat …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/A0Va4hHmMfuU6WPIIeSXFUl5gjN.jpg","es":"https://image.tmdb.org/t/p/w500/u4VnqaxINtKVscmdldZsBojU6jm.jpg","en":"https://image.tmdb.org/t/p/w500/i0enkzsL5dPeneWnjl1fCWm6L7k.jpg","fr":"https://image.tmdb.org/t/p/w500/qfuO1yue5bQnocFiOUM07dwLdmo.jpg","de":"https://image.tmdb.org/t/p/w500/6Vz28wZed3YDCVb14bKQV6qJ1eU.jpg"}'::jsonb WHERE id = 129;
UPDATE public.films SET tmdb_id = 25643, titoli_i18n = '{"es":"Love Happens","en":"Love Happens","de":"Love Happens","fr":"Coup de foudre à Seattle","it":"Love Happens - Qualcosa di speciale (noto anche come Brand New Day)"}'::jsonb, trame_i18n = '{"es":"El viudo Burke Ryan es un exitoso autor de libros de autoayuda que enseña cómo enfrentarse al dolor, pero es incapaz de seguir sus propios consejos. De mala gana, Burke vuelve a Seattle, ciudad que abandonó tras morir su mujer, para impartir una serie de conferencias y cerrar un importante acuerdo publicitario. Allí conoce inesperadamente a Eloise Chandler, una florista algo desencantada con el amor que asiste a sus seminarios y que, poco a poco y sin proponérselo, se convierte en la única persona capaz de ayudar a Burke a ayudarse a sí mismo; a la vez que él cada vez será más indispensable para Eloise.","en":"Dr. Burke Ryan is a successful self-help author and motivational speaker with a secret. While he helps thousands of people cope with tragedy and personal loss, he secretly is unable to overcome the death of his late wife. It''s not until Burke meets a fiercely independent florist named Eloise that he is forced to face his past and overcome his demons.","de":"Burke Ryan weiß auf alle Fragen eine Antwort. Zumindest wenn man den Millionen von Fans glauben darf, die gierig seine Ratgeberbücher verschlingen oder seine Selbsthilfeseminare besuchen, in der Hoffnung einen Weg zu finden, mit Trauer und Ängsten umzugehen. Aber was Burkes eigene Gefühle angeht, scheint er seinen Ratschlägen nicht zu trauen. Ausgerechnet da trifft er auf Eloise, die von den Männern eigentlich genug hat und sich endlich ihren Traum erfüllt und einen Blumenladen betreibt. Zwischen den beiden funkt es gleich, doch wenn die zwei richtigen Menschen zur falschen Zeit zusammentreffen, hat die Liebe dann eine Chance? Eloise und Burke merken bald, dass sie erst mit ihrer Vergangenheit abschließen müssen, um wirklich einen Neuanfang wagen zu können.","fr":"Un veuf décide d''écrire un livre sur le travail de deuil. L''ouvrage est un succès et fait passer son auteur pour une sorte de gourou. Lors de l''un de ses séminaires, il tombe amoureux d''une femme, et se rend alors compte qu''il n''a pas surmonté la perte de sa femme...","it":"Un autore di bestseller sul superamento del lutto, rimasto vedovo, tiene un seminario a Seattle. Qui incontra una fiorista disillusa dall''amore, che lo costringerà a fare i conti con il fatto che non ha ancora realmente superato la morte della moglie."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ODTuap8nZNMSDyWynCTID2lTCF.jpg","en":"https://image.tmdb.org/t/p/w500/ijRJlhAZ7QMkTIVAUkIY8stWfk1.jpg","de":"https://image.tmdb.org/t/p/w500/ijRJlhAZ7QMkTIVAUkIY8stWfk1.jpg","fr":"https://image.tmdb.org/t/p/w500/pn9B8cYuWK9ZPGHpT6UO9UzXNHK.jpg","it":"https://image.tmdb.org/t/p/w500/hUMCP4Fhwvc5CKREt86cVJAUITs.jpg"}'::jsonb WHERE id = 130;
UPDATE public.films SET tmdb_id = 969681, titoli_i18n = '{"it":"Spider-Man: Brand New Day","en":"Spider-Man: Brand New Day","fr":"Spider-Man : Brand New Day","es":"Spider-Man: Brand New Day","de":"Spider-Man: Brand New Day"}'::jsonb, trame_i18n = '{"it":"Dopo gli eventi di ''Spider-Man: No Way Home'', Peter Parker cerca di rifarsi una vita in una New York che ha dimenticato la sua vera identità. Dovrà bilanciare la sua nuova e solitaria quotidianità con le responsabilità di essere un supereroe di quartiere, affrontando nuove minacce.","en":"Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.","fr":"Quatre ans se sont écoulés, Peter, désormais adulte, vit seul, s''est volontairement effacé de la vie et des souvenirs de ses proches. Luttant contre le crime dans un New York qui ne le reconnaît plus, il se consacre entièrement à la protection de la ville - un Spider-Man à plein temps - mais à mesure que les responsabilités s''intensifient, la pression provoque une transformation physique surprenante qui menace son existence, tandis qu''une étrange nouvelle vague de crimes donne naissance à l''une des menaces les plus redoutables qu''il ait jamais affrontées.","es":"Han pasado cuatro años desde los acontecimientos de No Way Home, y Peter Parker ahora es un adulto que vive completamente solo, ha desaparecido voluntariamente de las vidas y recuerdos de quienes ama. Combatiendo el crimen en una Nueva York que ya no conoce su nombre, se ha dedicado por completo a proteger su ciudad—un Spider-Man a tiempo completo—, pero a medida que aumentan las exigencias sobre él, la presión desencadena una evolución física que amenaza su existencia, al mismo tiempo que un extraño nuevo patrón de crímenes da lugar a una de las amenazas más poderosas a las que se ha enfrentado.","de":"Vier Jahre sind seit den Ereignissen von „No Way Home“ vergangen. Peter ist nun erwachsen und lebt für sich allein, nachdem er sich freiwillig aus dem Leben und den Erinnerungen derer, die er liebt, ausgelöscht hat. Er bekämpft Verbrechen in einem New York, das ihn und seinen Namen nicht mehr kennt, und widmet sich ganz dem Schutz seiner Stadt: Spider-Man in Vollzeit. Doch mit den steigenden Anforderungen löst der Druck eine überraschende körperliche Veränderung aus, die seine Existenz bedroht – gerade als eine seltsame neue Art von Verbrechen eine der mächtigsten Bedrohungen hervorbringt, denen er je gegenüberstand."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/fRbJeDILi6nLYCT5XeFapjVTlSK.jpg","en":"https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg","fr":"https://image.tmdb.org/t/p/w500/6OEtkkzoyusZDm2uMJojlWZSLR9.jpg","es":"https://image.tmdb.org/t/p/w500/tluwRNA7k0XfTtDkdLYKX1KOSCJ.jpg","de":"https://image.tmdb.org/t/p/w500/h2R2dPbIyjxXorGL6V8Mau01hJy.jpg"}'::jsonb WHERE id = 132;
UPDATE public.films SET tmdb_id = 466272, titoli_i18n = '{"it":"C''era una volta a... Hollywood","es":"Érase una vez en… Hollywood","de":"Once Upon a Time... in Hollywood","en":"Once Upon a Time... in Hollywood","fr":"Once Upon a Time... in Hollywood"}'::jsonb, trame_i18n = '{"it":"Nella Los Angeles del 1969, un attore televisivo in declino e la sua controfigura e migliore amico cercano di navigare nei cambiamenti dell''industria cinematografica, mentre sullo sfondo si consumano le vicende legate alla setta di Charles Manson.","es":"Los Angeles, 1969. La estrella de televisión Rick Dalton, un actor en horas bajas especializado en westerns, y el doble de acción Cliff Booth, su mejor amigo, tratan de sobrevivir a una industria cinematográfica en constante cambio. Dalton es vecino de la joven y prometedora actriz y modelo Sharon Tate, que acaba de casarse con el prestigioso director polaco Roman Polanski…","de":"Es war einmal in Hollywood im Jahre 1969: Rick Dalton hat schon bessere Tage gesehen. Einst war der Schauspieler ein gefeierter Fernsehstar. Doch diese Zeiten sind längst vorbei. Inzwischen hält er sich mehr schlecht als recht mit Gastauftritten als Bösewicht in anderen TV-Produktionen über Wasser. Denn den Sprung auf die große Kinoleinwand hat er nie geschafft. Dabei ist sein Stunt-Double und Freund Cliff Booth stets an seiner Seite. Am Tiefpunkt seiner Karriere angelangt, bekommt Rick allerdings einen prominenten Nachbarn. Der Regisseur Roman Polanski ist mit seiner Frau, der Schauspielerin Sharon Tate in das Haus nebenan eingezogen. Während Tate das Leben in Amerikas Traumfabrik in vollen Zügen genießt, droht ihr Glück ein jähes Ende zu nehmen. Denn die mörderische Gruppe um Charles Manson plant eine Gräueltat, wie sie die Welt noch nicht gesehen hat …","en":"Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…","fr":"En 1969, Rick Dalton – star déclinante d''une série télévisée de western – et Cliff Booth – sa doublure de toujours – assistent à la métamorphose artistique d''un Hollywood qu''ils ne reconnaissent plus du tout en essayant de relancer leurs carrières."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/wW5t1FNg3ZHQu5sXeShyaN3oU9Z.jpg","es":"https://image.tmdb.org/t/p/w500/vKSyaptSA7zZ9H8mSfaDnvyQl9k.jpg","de":"https://image.tmdb.org/t/p/w500/5RnMRADLB7Goin16z6l4dPIBCJR.jpg","en":"https://image.tmdb.org/t/p/w500/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg","fr":"https://image.tmdb.org/t/p/w500/gG5J1KW2Gzj0Sz7al1mGkhXLSoB.jpg"}'::jsonb WHERE id = 133;
UPDATE public.films SET tmdb_id = 1371, titoli_i18n = '{"it":"Rocky III","en":"Rocky III","de":"Rocky III - Das Auge des Tigers","fr":"Rocky III : L''Œil du tigre","es":"Rocky III"}'::jsonb, trame_i18n = '{"it":"Rocky Balboa, ormai campione del mondo dei pesi massimi e ricco, perde il titolo contro il brutale sfidante Clubber Lang e subisce la dolorosa perdita del suo storico allenatore Mickey. Sarà l''ex rivale Apollo Creed ad aiutarlo a ritrovare la \"fame\" e lo \"sguardo della tigre\" per prepararsi alla rivincita.","en":"Following Rocky Balboa''s intense battle with his most powerful adversary yet – the ferocious Clubber Lang – Rocky joins forces with former rival Apollo Creed in an effort to get back his fighting spirit.","de":"Rocky ist unangefochtener Weltmeister im Schwergewicht und hat seinen Titel bislang zehn Mal erfolgreich verteidigt. Auf dem Gipfel seines Ruhmes angelangt, will der Publikumsliebling aus dem Boxsport aussteigen. Doch dann wird Rocky auf einer Pressekonferenz  von Großmaul Clubber Lang  herausgefordert. Aber Rocky fehlt der Biss alter Tage und er verliert den großen Kampf. Ausgerechnet Ex-Gegner Apollo Creed animiert ihn, für eine Revanche zu trainieren …","fr":"Rocky Balboa se fraie un chemin dans le cœur de millions de personnes et sa vie ne pourrait être meilleure. Mais lorsque \"Clubber\" Lang met Rocky KO dans une défaite humiliante, il devient évident que \"l''étalon italien\" a perdu son avantage. Alors qu''il envisage de raccrocher les gants, Rocky reçoit les encouragements d''un allié improbable : son vieil ennemi juré, Apollo Creed. Avec l''aide de Creed, Rocky s''efforce de retrouver \"l''œil du tigre\" avant d''affronter Lang dans un match de reprise exténuant !","es":"Tras haber defendido el título diez veces, el campeón mundial de boxeo Rocky Balboa ha decidido retirarse. Sin embargo Clubber Lang, un boxeador muy agresivo que ha ido escalando puestos a base de destrozar a sus rivales, desea arrebatarle el título. Pese a la negativa de Rocky, Clubber consigue provocarle para que acepte el desafío, y esta vez el resultado del combate se presume bastante incierto."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ajcNIcmwjbVO8kA22WMeCcTKf9T.jpg","en":"https://image.tmdb.org/t/p/w500/uqw16i2kmwVqkJHzjzbDU4xZ0Pl.jpg","de":"https://image.tmdb.org/t/p/w500/Gsohe9uX4fftQRcuZOmv2muEFB.jpg","fr":"https://image.tmdb.org/t/p/w500/zplg0q9s5pbJDQLWCTlIQfMxC9A.jpg","es":"https://image.tmdb.org/t/p/w500/5Mn0xgB8w9mi2Ifo7WdS8aSgA7V.jpg"}'::jsonb WHERE id = 134;
UPDATE public.films SET tmdb_id = 1375, titoli_i18n = '{"it":"Rocky V","en":"Rocky V","es":"Rocky V","fr":"Rocky V","de":"Rocky V"}'::jsonb, trame_i18n = '{"it":"Costretto al ritiro dai combattimenti a causa dei danni cerebrali riportati contro Ivan Drago e finito in rovina finanziaria, Rocky Balboa torna con la famiglia nel suo vecchio quartiere a Philadelphia. Qui comincia ad allenare un giovane e promettente pugile, Tommy Gunn, trascurando il proprio figlio. L''ambizione e l''avidità spingeranno però Tommy a voltare le spalle a Rocky, portando i due a uno scontro finale in una rissa di strada.","en":"A lifetime of taking shots has ended Rocky’s career, and a crooked accountant has left him broke. Inspired by the memory of his trainer, however, Rocky finds glory in training and takes on an up-and-coming boxer.","es":"Rocky, arruinado y retirado del boxeo, se ve obligado a volver a su barrio de siempre. Allí conoce a un joven con aptitudes para boxear y decide entrenarle.","fr":"Des séquelles physiques irréversibles amènent Rocky Balboa à prendre sa retraite. Ruiné, il devient l''entraîneur d''un champion en devenir, Tommy Gunn. Mais celui-ci ne va pas rester insensible à l''appât du gain et va quitter Rocky pour rejoindre les rangs d''un coach plus fortuné.","de":"Sein knapper Sieg gegen die russische Kampfmaschine Ivan Drago hat Box-Weltmeister Rocky Balboa eine schwere Hirnschädigung gekostet, die ihn zum Rücktritt zwingt. Aber es kommt noch schlimmer: Durch eine Fehlspekulation seines Steuerberaters ist er plötzlich mit einem Schlag pleite. Zusammen mit seiner Familie zieht Rocky notgedrungen wieder zurück in die Slums, wo er sich mit der Box-Schule seines verstorbenen Trainers über Wasser hält. Dabei lernt er den noch unerfahrenen Boxer Tommy Gunn kennen, für den er sich aus gewissen Sympathien bereit erklärt, Trainer zu sein. Als den beiden im Team dann erste Erfolge vergönnt sind, beginnt auch der geldgierige Promoter Duke, Interesse an dem Newcomer zu zeigen..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/y6xHS5icTfYXkRZtb2NvTLhVYfn.jpg","en":"https://image.tmdb.org/t/p/w500/qCARerjCFZOEeLiVdomhwRYlDSn.jpg","es":"https://image.tmdb.org/t/p/w500/kbt9oSpAX8TkmpV2T72p0Cl41vR.jpg","fr":"https://image.tmdb.org/t/p/w500/829CIMdIhYgXWUSq7OjrpgtNAR7.jpg","de":"https://image.tmdb.org/t/p/w500/tZi4FathM1vcsDtbuOFsOce2IhB.jpg"}'::jsonb WHERE id = 135;
UPDATE public.films SET tmdb_id = 17382, titoli_i18n = '{"it":"La storia del generale Custer","en":"They Died with Their Boots On","fr":"La Charge fantastique","es":"Murieron con las botas puestas","de":"Sein letztes Kommando"}'::jsonb, trame_i18n = '{"it":"La vita romanzata di George Armstrong Custer, dalla sua giovinezza all''accademia militare di West Point, attraverso le sue eroiche imprese durante la Guerra di Secessione, fino alla sua tragica morte nella celebre battaglia di Little Bighorn.","en":"The story follows General George Armstrong Custer''s adventures from his West Point days to his death. He defies orders during the Civil War, trains the 7th Cavalry, appeases Chief Crazy Horse and later engages in bloody battle with the Sioux nation.","fr":"Un jeune élève nommé Custer se distingue par son talent et son insubordination dans le camp militaire de West Point. Durant la guerre de Sécession, la bataille d''Hanovre est remportée, bien que soldée par un véritable massacre. Il est envoyé par ses supérieurs dans le Dakota, à Fort Lincoln. Mais il se heurte à la fois aux politiciens et aux chercheurs d''or, jusqu''à ce que les indiens de Crazy Horse se soulèvent à leur tour. L''affrontement aura lieu à Little Big Horn...","es":"George Custer (Errol Flynn) llega a la Academia de West Point lleno de arrogancia y vanidad. Su carácter indisciplinado le ocasionará numerosos problemas con sus superiores. A pesar de todo, y debido a la acuciante necesidad de oficiales para la Guerra de Secesión (1861-1865), es enviado al frente. Terminada la guerra, se casa con Beth (Olivia de Havilland), pero pronto le asignan un nuevo destino: la guerra contra los indios. Al frente del Séptimo de Caballería, el Teniente Coronel Custer se enfrentará a los indios de Caballo Loco. La campaña termina con la famosa batalla de Little Big Horn (Montana, 1876).","de":"George Armstrong Custer absolviert die Militärschule West Point und nimmt am Bürgerkrieg teil. Als Kommandant des 7. Kavallerie-Regiments bewährt er sich in Dakota, sorgt für Frieden mit den Sioux: Kein Weißer werde ihr Gebiet in den Black Hills betreten. Eine Handelsgesellschaft durchkreuzt seine Politik, er wird suspendiert. Die Gesellschaft provoziert einen Aufstand der Krieger von Häuptling Crazy Horse. Custer wird wieder eingesetzt und reitet mit seinem Regiment am 25. Juni 1876 in die Schlacht am Little Big Horn, wo er und alle seine Leute fallen"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5cZLUtSWiz0LWK1H0EZSH5RkL1L.jpg","en":"https://image.tmdb.org/t/p/w500/gx8jknFwZRuQwTPooe14Dsx5uTO.jpg","fr":"https://image.tmdb.org/t/p/w500/gxPyXi7XCwdpa98cJOVl3R1hEYC.jpg","es":"https://image.tmdb.org/t/p/w500/UXrWYewjH3KNEU7IAKyynEYTYf.jpg","de":"https://image.tmdb.org/t/p/w500/djt8CMaxDQkpcYGyGo3N3jj60d0.jpg"}'::jsonb WHERE id = 136;
UPDATE public.films SET tmdb_id = 8195, titoli_i18n = '{"es":"Ronin","en":"Ronin","de":"Ronin","it":"Ronin","fr":"Ronin"}'::jsonb, trame_i18n = '{"es":"Cuando un equipo internacional de ex-agentes de inteligencia y ex-guerreros de la guerra fría se reunen en una bodega, su aventura de amor, amistad y traición apenas comienza. Al igual que el honorable e independiente samurai de hace cientos de años, estos ronin modernos se embarcan en su más peligrosa misión secreta: recobrar una misteriosa maleta y entregársela a su desconocido jefe y a la vez conservar sus vidas. Un criminal que se vende al mejor postor lidera un grupo de profesionales del crimen que busca un misterioso maletín, cuyo contenido es desconocido incluso para el espectador.","en":"A briefcase with undisclosed contents – sought by Irish terrorists and the Russian mob – makes its way into criminals'' hands. An Irish liaison assembles a squad of mercenaries, or ''ronin'', and gives them the thorny task of recovering the case.","de":"Die geheimnisvolle Dierdre heuert mehrere Ronins (Samurais ohne Meister), käufliche Spezialisten für alle Fälle, an, um eine Tasche zu stehlen, ehe der momentane Besitzer sie an den KGB verkaufen kann. Die Männer kennen sich nicht, und obwohl sie unterschiedliche Berufs- und Lebensauffassungen haben, führen sie den Job aus. Doch die Tasche verschwindet kurz nach dem Coup und bald stecken alle Beteiligten in einem tödlichen Spiel, bei dem niemand sicher ist und jeder ein Verräter sein kann.","it":"Un gruppo di ex agenti segreti e mercenari provenienti da diversi paesi viene ingaggiato a Parigi per recuperare una misteriosa e pesantemente custodita valigetta. Tra tradimenti, doppi giochi e mozzafiato inseguimenti automobilistici, la squadra dovrà scoprire di chi potersi davvero fidare.","fr":"Cinq hommes et une femme qui ne se connaissent pas se rencontrent dans un entrepôt de la banlieue parisienne. Ces hommes de l’ombre sont d’anciens soldats de la guerre froide qui survivent en louant discrètement leurs services à des commanditaires anonymes. La jeune Irlandaise qui les a réunis manque d’expérience. Leur mission est d’affronter une équipe adverse, solidement armée d’une douzaine d’hommes pour lui arracher une précieuse mallette dont ils ignorent le contenu. Une chose est claire : tous devront tuer pour mener à bien leur mission, certains y laisseront leur peau."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/jPz0pJuEf44qVgSaZkER43W04Bg.jpg","en":"https://image.tmdb.org/t/p/w500/AirrhRJjHwytOV0pdLu7YZ4DEyr.jpg","de":"https://image.tmdb.org/t/p/w500/it9iwy9SfyTjx9ggxbfycESJn1S.jpg","it":"https://image.tmdb.org/t/p/w500/cNngnFz2VLJbIYQEgn3Idd20h1K.jpg","fr":"https://image.tmdb.org/t/p/w500/yiZrJDZT8Yy8bfvmwWQ7UDK1lDP.jpg"}'::jsonb WHERE id = 137;
UPDATE public.films SET tmdb_id = 184, titoli_i18n = '{"it":"Jackie Brown","es":"Jackie Brown","en":"Jackie Brown","fr":"Jackie Brown","de":"Jackie Brown"}'::jsonb, trame_i18n = '{"it":"Una hostess di volo di mezza età, che contrabbanda denaro sporco per un trafficante d''armi, viene incastrata dall''FBI. Per salvarsi, decide di fare il doppio gioco, ideando un piano rischioso per truffare sia i federali che il suo boss e fuggire con mezzo milione di dollari.","es":"Jackie Brown es una azafata de vuelo que necesita dinero y hace de correo para Robbie, un mafioso buscado por la policía. Todo parece ir bien hasta que un día es sorprendida en la aduana y acusada de tráfico de drogas y evasión de capital. Sólo podrá evitar su ingreso en prisión, si acepta una propuesta de la policía: ayudarles a llegar hasta Robbie.","en":"Jackie Brown is a flight attendant who gets caught in the middle of smuggling cash into the country for her gunrunner boss. When the cops try to use Jackie to get to her boss, she hatches a plan — with help from a bail bondsman — to keep the money for herself.","fr":"Hôtesse de l’air, Jackie Brown arrondit ses fins de mois en convoyant de l’argent liquide pour le compte de Ordell Robbie, trafiquant d’armes. Quand la police et le FBI lui signifient qu’ils comptent sur elle pour faire tomber Robbie, Jackie Brown échafaude un plan audacieux.","de":"Mit Schwarzgeld wird Jackie Brown am Flughafen gestellt. Das FBI wittert die große Chance, durch Jackies Aussage einen Schmuggler-Ring auszuheben. Die Cops sind bereit, Jackie laufen zu lassen, wenn sie den Namen ihres Auftraggebers preisgibt. Die Entscheidung fällt ihr schwer, denn Ordell Robbie, ihr Boss und Drahtzieher der dubiosen Waffen-Schmuggel-Geschäfte, würde sie umbringen, wenn er Wind von einem Deal mit dem FBI bekäme. Bevor sie sich entscheiden kann, kommt alles ganz anders: Sie lernt den Kautionsvermittler Max Cherry kennen. Die beiden schmieden einen Plan, und plötzlich hat Jackie die Idee, wie es ihr gelingen könnte, Ordell gegen die Polizei auszuspielen …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jLnXl26rUTHryy6scittB5OMUQk.jpg","es":"https://image.tmdb.org/t/p/w500/vNrJ3ODvu2dvqIdHHbzgsVjgp4X.jpg","en":"https://image.tmdb.org/t/p/w500/rOUx7qg4KmEh1juEDwqzbDSL1Nr.jpg","fr":"https://image.tmdb.org/t/p/w500/mc8lNVgDYMG2IQus5RmdcgvwOKx.jpg","de":"https://image.tmdb.org/t/p/w500/dyRpD0W6bJbdvNy9mRuviajaYPj.jpg"}'::jsonb WHERE id = 138;
UPDATE public.films SET tmdb_id = 718930, titoli_i18n = '{"it":"Bullet Train","de":"Bullet Train","fr":"Bullet Train","en":"Bullet Train","es":"Bullet Train"}'::jsonb, trame_i18n = '{"it":"Un sfortunato assassino di nome Ladybug vuole svolgere una semplice missione a bordo del treno ad alta velocità più veloce del mondo in Giappone. Tuttavia, si ritrova a doversela vedere con diversi killer professionisti provenienti da tutto il mondo, tutti con obiettivi interconnessi e contrastanti.","de":"Der vom Pech verfolgte Auftragskiller Ladybug ist entschlossen, seinen Job in Ruhe und Frieden zu erledigen, nachdem in letzter Zeit zu viele Dinge aus dem Ruder gelaufen sind. Das Schicksal hat jedoch andere Pläne, denn Ladybugs neueste Mission setzt ihn auf einen direkten Kollisionskurs mit tödlichen Gegnern aus der ganzen Welt – die alle irgendwie miteinander verbunden sind, dabei aber gegensätzliche Ziele verfolgen. Das alles passiert an Bord des schnellsten Zuges, den es gibt - und Ladybug muss einen Weg finden, wie er ihn verlassen kann.","fr":"Coccinelle est un assassin malchanceux et particulièrement déterminé à accomplir sa nouvelle mission paisiblement après que trop d''entre elles aient déraillé. Mais le destin en a décidé autrement et l''embarque dans le train le plus rapide au monde aux côtés d''adversaires redoutables qui ont tous un point commun, mais dont les intérêts divergent radicalement… Il doit alors tenter par tous les moyens de descendre du train.","en":"Unlucky assassin Ladybug is determined to do his job peacefully after one too many gigs gone off the rails. Fate, however, may have other plans, as Ladybug''s latest mission puts him on a collision course with lethal adversaries from around the globe—all with connected, yet conflicting, objectives—on the world''s fastest train.","es":"Cinco asesinos a sueldo se encuentran a bordo de un tren bala que viaja de Tokio a Morioka con unas pocas paradas intermedias. Descubren que sus misiones no son ajenas entre sí. La pregunta es quién saldrá vivo del tren y qué les espera en la estación final."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zTyMbs3zTEpDhyrel35vgpJdzFS.jpg","de":"https://image.tmdb.org/t/p/w500/kem6mZifzyIec1TDpd9srSRTpv7.jpg","fr":"https://image.tmdb.org/t/p/w500/uJvMXO1DNEER2lZocNjJy2zXtYs.jpg","en":"https://image.tmdb.org/t/p/w500/j8szC8OgrejDQjjMKSVXyaAjw3V.jpg","es":"https://image.tmdb.org/t/p/w500/kM6iLHkDfyoMsTIm567mUFzFO9e.jpg"}'::jsonb WHERE id = 139;
UPDATE public.films SET tmdb_id = 152599, titoli_i18n = '{"it":"C''era una volta a New York","es":"El sueño de Ellis","en":"The Immigrant","fr":"The Immigrant","de":"The Immigrant"}'::jsonb, trame_i18n = '{"it":"Nel 1921, le sorelle polacche Ewa e Magda arrivano a Ellis Island in cerca di una vita migliore. Quando Magda viene messa in quarantena per tubercolosi, Ewa si ritrova sola e vulnerabile, finendo sotto il controllo di un ambiguo impresario che la avvia alla prostituzione.","es":"En 1921, Ewa y su hermana Magda dejan su Polonia natal y emigran a Nueva York. Cuando llegan a Ellis Island, a Magda, enferma de tuberculosis, la ponen en cuarentena. Ewa, sola y desamparada, cae en manos de Bruno, un rufián sin escrúpulos. Para salvar a su hermana, Ewa está dispuesta a aceptar todos los sacrificios y se entrega resignada a la prostitución. La llegada de Orlando, ilusionista y primo de Bruno, le devuelve la confianza y la esperanza de alcanzar días mejores. Con lo que no cuenta es con los celos de Bruno.","en":"1921 New York. An immigrant woman is tricked into a life of burlesque and vaudeville until a dazzling magician tries to save her and reunite her with her sister who is being held in the confines of Ellis Island.","fr":"1921, Ewa et sa sœur Magda quittent leur Pologne natale pour la terre promise, New York. Arrivées à Ellis Island, Magda, atteinte de tuberculose, est placée en quarantaine. Ewa, seule et désemparée, tombe dans les filets de Bruno, un souteneur sans scrupules. Pour sauver sa sœur, elle est prête à tous les sacrifices et se livre, résignée, à la prostitution.  L’arrivée d’Orlando, illusionniste et cousin de Bruno, lui redonne confiance et l''espoir de jours meilleurs. Mais c''est sans compter sur la jalousie de Bruno...","de":"Auf der Suche nach einem Neustart und dem amerikanischen Traum beschließen Ewa Cybulski und ihre Schwester Magda im Jahre 1920, ihre Heimat Polen zu verlassen und in die USA zu emigrieren. Nach der beschwerlichen Schwiffsreise müssen die Frauen die üblichen Untersuchungen auf Ellis Island über sich ergehen lassen. Dabei stellt der zuständige Arzt fest, dass Magda krank ist, woraufhin die beiden Schwestern voneinander getrennt werden. Während Ewa orientierungslos in den Straßen von Manhattan umherzieht, wird ihre Schwester unter Quarantäne gestellt. Abgeschnitten von Magda findet Ewa Zuflucht bei Bruno, der zunächst charmant und hilfsbereit ist und Ewa bei sich aufnimmt. Doch schon bald lässt Bruno seine Maske fallen und drängt Ewa in die Prostitution. Als sie eines Tages dessen Cousin kennenlernt, den Magier Orlando, verliebt sie sich in ihn. Orlando wird zu ihrer einzigen Chance, dem Alptraum zu entfliehen…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/c0R0CIjxP7D8eA4oGoJFdtBcLzk.jpg","es":"https://image.tmdb.org/t/p/w500/AcdntsQgOPgQ1VjLlb7FMNf5flb.jpg","en":"https://image.tmdb.org/t/p/w500/ArWRRQYeXL3nG4jYpMOPoBvgmy9.jpg","fr":"https://image.tmdb.org/t/p/w500/msbOO1XTPeKSaMol3EW0JulvI6E.jpg","de":"https://image.tmdb.org/t/p/w500/svLnamg54HhbMQkU9ghWibKRjH2.jpg"}'::jsonb WHERE id = 140;
UPDATE public.films SET tmdb_id = 578, titoli_i18n = '{"en":"Jaws","es":"Tiburón","fr":"Les Dents de la Mer","de":"Der weiße Hai","it":"Lo squalo"}'::jsonb, trame_i18n = '{"en":"When the seaside community of Amity finds itself under attack by a dangerous great white shark, the town''s chief of police, a young marine biologist, and a grizzled shark hunter embark on a desperate quest to kill the beast before it strikes again.","es":"En la costa de un pequeño pueblo del Este de Estados Unidos, un enorme tiburón ataca a varias personas. Temiendo las fatales consecuencias que esto puede provocar en el negocio turístico, el alcalde se niega a cerrar las playas y a difundir la noticia. Pero un nuevo ataque del tiburón, en la propia playa, termina con la vida de otro bañista. El terror se ha hecho público, así que un veterano cazador de tiburones, un científico y el jefe de la policía local se unen para dar caza al temible escualo...","fr":"À quelques jours du début de la saison estivale, les habitants de la petite station balnéaire d''Amity sont mis en émoi par la découverte sur le littoral du corps atrocement mutilé d''une jeune vacancière. Pour Martin Brody, le chef de la police, il ne fait aucun doute que la jeune fille a été victime d''un requin. Il décide alors d''interdire l''accès aux plages mais se heurte à l''hostilité du maire uniquement intéressé par l''afflux des touristes. Pendant ce temps, le requin continue à semer la terreur le long des côtes et à dévorer les baigneurs…","de":"Ein weißer Hai terrorisiert eine Badeinsel an der amerikanischen Atlantikküste. Besonnene Einheimische unter Führung von Polizeichef Brody wollen alle Strände schließen und zur großen Jagd blasen, während die Schar der Kaufleute und Gastwirte angesichts der einträglichen Badesaison lieber zur Tagesordnung übergeht und sich damit auch durchsetzt. Als der Hai erneut zuschlägt, bildet Brody mit dem erfahrenen Haifänger Quint und dem Ozeanologen Hooper ein Jagd-Team und rückt dem Gegner auf See zu Leibe.","it":"Un grande squalo bianco terrorizza le acque di una cittadina balneare. Per fermare il predatore, il capo della polizia locale stringe un''alleanza con un giovane biologo marino e un eccentrico cacciatore di squali."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/lxM6kqilAdpdhqUl2biYp5frUxE.jpg","es":"https://image.tmdb.org/t/p/w500/aCqHb3eFQV8raX30OfGurqPlpjh.jpg","fr":"https://image.tmdb.org/t/p/w500/wuRf6gkX0JUJsu1MeECPubhMRdd.jpg","de":"https://image.tmdb.org/t/p/w500/jkchPeYVLZkGg40Co7t3FC0FUti.jpg","it":"https://image.tmdb.org/t/p/w500/zHO7LcDKgAM1sLAZ1Y9yuWc7W7B.jpg"}'::jsonb WHERE id = 141;
UPDATE public.films SET tmdb_id = 579, titoli_i18n = '{"it":"Lo squalo 2","es":"Tiburón 2","en":"Jaws 2","fr":"Les Dents de la mer, 2e partie","de":"Der weiße Hai 2"}'::jsonb, trame_i18n = '{"it":"Quattro anni dopo i tragici eventi dell''isola di Amity, la cittadina cerca di tornare alla normalità. Tuttavia, quando iniziano a verificarsi nuove e misteriose sparizioni in acqua, il capo della polizia Martin Brody si convince che un altro grande squalo bianco stia terrorizzando la zona. Nonostante lo scetticismo delle autorità locali, Brody dovrà agire in fretta per salvare un gruppo di giovani velisti, tra cui i suoi stessi figli, finiti nel mirino del predatore.","es":"Han pasado cuatro años desde que aquel gran tiburón blanco aterrorizara al pequeño pueblo costero de Amity. El jefe de policía Brody sigue preocupado, a pesar de que hay en marcha varios proyectos para reavivar el interés turístico de las playas. El alcalde Larry Vaughn da la bienvenida al inversor Len Peterson y su equipo al pueblo. Dos submarinistas exploran la zona donde apareció el peligroso escualo en el pasado, y son devorados por otro enorme tiburón no sin antes obtener uno de ellos una foto del ojo del monstruo. La desaparición de los dos buceadores alerta a Brody, ya que es verano y los turistas llegan por centenares hasta Amity. Mientras tanto, un grupo de adolescentes entre los que se encuentra Mike y Sean, los hijos del policía, hacen una excursión hasta una península cercana...","en":"Police chief Brody must protect the citizens of Amity after a second monstrous shark begins terrorizing the waters.","fr":"Au lendemain de l''inauguration d''un luxueux complexe hôtelier, Martin Brody, le chef de la police d''Amity, apprend la disparition d''une équipe de plongeurs. Il craint le pire. Un requin est déjà venu nager dans les eaux d''Amity quelques années auparavant. Ses inquiétudes ne tardent pas à se confirmer. Un autre accident se produit et le cadavre d''une baleine portant les morsures d''un requin géant échoue sur la plage. Martin Brody alerte immédiatement le maire et lui demande d''interdire la baignade. Mais le conseil municipal refuse de prendre de telles précautions. La saison s''annonce prometteuse et l''enjeu financier est trop important. Brody, devenu trop gênant, est démis de ses fonctions. Le voilà réduit à attendre le pire…","de":"Aus dem kleinen Küstenort Amity soll ein modernes Seebad gemacht werden. Plötzlich geschehen schreckliche Unglücksfälle. Polizeichef Brody befürchtet, dass so wie vor einigen Jahren wieder ein Hai dafür verantwortlich sein könnte. Aber keiner reagiert auf seine Warnungen. Auf sich allein gestellt, versucht er, die mörderische Bestie zu bekämpfen..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/6lrBNBedNIiPpFtyeFwe63OkJoz.jpg","es":"https://image.tmdb.org/t/p/w500/gQgHcjBWzjCvdfFNY6PGMEzMN93.jpg","en":"https://image.tmdb.org/t/p/w500/cN3ijEwsn4kBaRuHfcJpAQJbeWe.jpg","fr":"https://image.tmdb.org/t/p/w500/cH4ZGKS93wTl6JDDg8cwLkqt8u1.jpg","de":"https://image.tmdb.org/t/p/w500/8xA83bATuN2QW7k5BL5Z8jMCh6V.jpg"}'::jsonb WHERE id = 142;
UPDATE public.films SET tmdb_id = 17692, titoli_i18n = '{"it":"Lo squalo 3","fr":"Les Dents de la mer 3","es":"Tiburón 3","en":"Jaws 3-D","de":"Der weiße Hai 3"}'::jsonb, trame_i18n = '{"it":"Un enorme grande squalo bianco s''introduce nel parco acquatico di SeaWorld in Florida poco prima dell''inaugurazione di una nuova attrazione subacquea. Quando il cucciolo dello squalo muore all''interno della struttura, la gigantesca madre comincia a seminare il terrore e la distruzione, intrappolando i visitatori e il personale nei tunnel e nelle gallerie sottomarine.","fr":"Michael Brody et Sean Brody, les deux fils du chef de la police Martin Brody de la ville plaisancière d''Amytiville, ont bien grandi. Après que leur père ait affronté deux fois la terreur des mers, le Grand Requin Blanc, une espèce animale mangeuse d''hommes de plus de sept mètres de long, ils se sont installés en Floride où ils travaillent pour un célèbre parc aquatique englouti dans la mer, dirigé par Calvin Bouchard. Peu de temps après l''ouverture du parc, l''équipe récupère dans les fonds marins un bébé requin, qui meurt sur les tables du laboratoire scientifique du parc. La mère du requin veut récupérer son petit, et elle sait qu''il se trouve quelque part dans le parc. Celle-ci décide donc de passer à l''attaque et de détruire le Sea World…","es":"¿Te imaginas quedar atrapado en un parque acuático con un gigantesco tiburón blanco asesino? La tercera parte de la clásica saga de terror hará que pienses dos veces antes de ir a un parque acuático.","en":"A giant thirty-five-foot shark becomes trapped in a SeaWorld theme park and it''s up to the sons of police chief Brody to rescue everyone.","de":"Der Sohn von Polizeichef Brody, Michael, ist Ingenieur. Seine Arbeitsstätte: ein Unterwasser-Vergnügungspark im sonnigen Florida. Michael hat eine Freundin, Kathryn  die sich als Trainerin um die Meeresbewohner des Parks kümmert. Der kundige Filmfreund weiß, dass jetzt nur noch einer fehlt, damit der Plot halbwegs interessant wird - der weiße Hai! Er ist in diesem Fall eine Sie, ein trächtiges Weibchen. Das schwimmt in die Anlage, wo es sein drei Meter langes Junges gebärt. Mutter und Kind gehen fortan getrennt auf die Jagd. Nur wenig Zeit vergeht, bis sich Michael und Kathryn mit den ersten Leichen konfrontiert sehen. Währenddessen rückt der Eröffnungstermin des Wasserparks näher und näher..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cNNORYubcNFChvN9jAFeASNswo8.jpg","fr":"https://image.tmdb.org/t/p/w500/pgW204G6bP56grBlaCKSJpzOFYT.jpg","es":"https://image.tmdb.org/t/p/w500/QmB1j0RzqPGki8o8UfJsc6CE5t.jpg","en":"https://image.tmdb.org/t/p/w500/kqDXj53F9paqVGJLGfHtz7giJ3s.jpg","de":"https://image.tmdb.org/t/p/w500/jMWfK6gtkdOjzIijNkykUBXVv2t.jpg"}'::jsonb WHERE id = 143;
UPDATE public.films SET tmdb_id = 16869, titoli_i18n = '{"es":"Malditos bastardos","fr":"Inglourious Basterds","de":"Inglourious Basterds","it":"Bastardi senza gloria","en":"Inglourious Basterds"}'::jsonb, trame_i18n = '{"es":"Segunda Guerra Mundial. Durante la ocupación de Francia por los alemanes, Shosanna Dreyfus presencia la ejecución de su familia por orden del coronel nazi Hans Landa. Ella consigue huir a París, donde adopta una nueva identidad como propietaria de un cine. En otro lugar de Europa, el teniente Aldo Raine adiestra a un grupo de soldados judíos \"Los bastardos\" para atacar objetivos concretos. Los hombres de Raine y una actriz alemana, que trabaja para los aliados, deben llevar a cabo una misión que hará caer a los jefes del Tercer Reich. El destino quiere que todos se encuentren bajo la marquesina de un cine donde Shosanna espera para vengarse.","fr":"Dans la France occupée de 1940, un groupe de soldats juifs américains, les bâtards, mène des actions punitives particulièrement sanglantes contre les nazis du Troisième Reich. Leur chemin rencontre celui de Shosanna Dreyfus, une jeune juive réfugiée à Paris exploitante d''une salle de cinéma qui entend elle aussi assouvir sa propre vengeance envers les nazis.","de":"Im von Deutschland besetzten Frankreich muss Shosanna ansehen wie ihre Familie durch Oberst Hans Landa brutal ermordet wird. Sie kann entkommen und flieht nach Paris. Gemeinsam mit seinen 8 Männern, einer Elitetruppe aus jüdisch-amerikanischen Soldaten, will Offizier Aldo Raine systematische Vergeltungsschläge gegen Nazis durchführen. Sie werden in Frankreich abgesetzt, um dort unterzutauchen. Von den Deutschen als ‚Die Bastarde'' gefürchtet versuchen sie den Führer des III. Reichs zu töten.","it":"Nella Francia occupata dai nazisti durante la seconda guerra mondiale, un gruppo di soldati ebrei americani guidati dal tenente Aldo Raine, noti come ''I Bastardi'', viene paracadutato per seminare il terrore tra le truppe tedesche. Le loro strade si incroceranno con quelle di Shosanna Dreyfus, una giovane ebrea sopravvissuta all''eccidio della sua famiglia per mano del spietato colonnello SS Hans Landa, che pianifica una clamorosa vendetta all''interno del proprio cinema a Parigi.","en":"In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as \"The Basterds\" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/dqu7nUtKTLdpM7DaJvD4zcSXhn1.jpg","fr":"https://image.tmdb.org/t/p/w500/lPKwFzX4TiWLA4Mo5Bnf8aIIrJm.jpg","de":"https://image.tmdb.org/t/p/w500/7Nq9bqyloLwYLkrG7q0tHI6kO45.jpg","it":"https://image.tmdb.org/t/p/w500/aa1jLbxTTuA6o5ucHoZh2khwNSo.jpg","en":"https://image.tmdb.org/t/p/w500/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg"}'::jsonb WHERE id = 144;
UPDATE public.films SET tmdb_id = 500, titoli_i18n = '{"en":"Reservoir Dogs","it":"Le iene","es":"Reservoir Dogs","de":"Reservoir Dogs - Wilde Hunde","fr":"Reservoir Dogs"}'::jsonb, trame_i18n = '{"en":"A botched robbery indicates a police informant, and the pressure mounts in the aftermath at a warehouse. Crime begets violence as the survivors -- veteran Mr. White, newcomer Mr. Orange, psychopathic parolee Mr. Blonde, bickering weasel Mr. Pink and Nice Guy Eddie -- unravel.","it":"Dopo che una rapina a una gioielleria sfocia in un sanguinoso scontro a fuoco con la polizia, i sopravvissuti di una banda di criminali sconosciuti tra loro si rifugiano in un capannone abbandonato, convinti che tra di loro ci sia un infiltrato.","es":"Una banda organizada formada por seis individuos es contratada para dar un golpe. Anteriormente varios de los miembros no se conocían entre sí, por lo que entre ellos usan nombres en clave. El objetivo: atracar una empresa para llevarse unos diamantes. Pero, antes de que suene la alarma, la policía ya está allí. Algunos mueren en el atraco, y el resto se reúne en el lugar convenido.","de":"Ein perfekt geplanter Coup endet in einem rücksichtslosen Psycho-Horrortrip, der blutige Opfer fordert. Beteiligt sind sechs elegant gekleidete Profi-Gangster, die zu einem Überfall auf ein Juweliergeschäft zusammenkommen. Alles, was die Gentlemen voneinander wissen, sind die Decknamen, die ihnen ihr Auftraggeber Joe Cabot gegeben hat. Mr. White, Mr. Orange, Mr. Pink, Mr. Blonde, Mr. Blue, Mr. Brown. Doch der todsichere Coup misslingt, die Polizei war informiert. Am geheimen Treffpunkt, einem leerstehenden Lagerhaus, wird ein Verdacht zur Gewissheit: unter ihnen ist ein Spitzel. Tödliches Misstrauen macht sich breit. Während einer der Gangster zu verbluten droht, entwickeln sich die anderen zu reißenden Bestien, die weder vor der Folter an einem gekidnappten Polizisten noch vor blutiger Gewalt untereinander zurückschrecken.","fr":"Après un hold‐up manqué, des cambrioleurs de haut vol font leurs comptes dans une confrontation violente, pour découvrir lequel d’entre eux les a trahis."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg","it":"https://image.tmdb.org/t/p/w500/noWeDEXd0a8du7tWG9F16Pm3Cvv.jpg","es":"https://image.tmdb.org/t/p/w500/hxmJqXFFnXLlvPIdCW2k3UGLCgZ.jpg","de":"https://image.tmdb.org/t/p/w500/AdXZmqOq2XcJQvHN3nKIXTd6ilq.jpg","fr":"https://image.tmdb.org/t/p/w500/b62t5xsAMGZ2LOLbD0l85xQE3tr.jpg"}'::jsonb WHERE id = 145;
UPDATE public.films SET tmdb_id = 78, titoli_i18n = '{"it":"Blade Runner","en":"Blade Runner","fr":"Blade Runner","es":"Blade Runner","de":"Der Blade Runner"}'::jsonb, trame_i18n = '{"it":"In una Los Angeles distopica e piovosa del 2019, l''ex poliziotto Rick Deckard viene richiamato in servizio come ''blade runner''. Il suo compito è rintracciare e ''ritirare'' quattro replicanti della serie Nexus-6, androidi indistinguibili dagli umani, fuggiti dalle colonie extra-terrestri e giunti illegalmente sulla Terra alla ricerca del loro creatore per prolungare la propria breve vita.","en":"In the smog-choked dystopian Los Angeles of 2019, blade runner Rick Deckard is called out of retirement to terminate a quartet of replicants who have escaped to Earth seeking their creator for a way to extend their short life spans.","fr":"2019, Los Angeles. La Terre est surpeuplée et l’humanité est partie coloniser l’espace. Les nouveaux colons sont assistés de Replicants, androïdes que rien ne peut distinguer de l''être humain. Conçus comme de nouveaux esclaves, certains parmi les plus évolués s’affranchissent de leurs chaînes et s’enfuient. Rick Deckard, un ancien Blade Runner, catégorie spéciale de policiers chargés de \"retirer\" ces replicants, accepte une nouvelle mission consistant à retrouver quatre de ces individus qui viennent de regagner la Terre après avoir volé une navette spatiale.","es":"A principios del siglo XXI, la Tyrell Corporation desarrolló un nuevo tipo de robot llamado Nexus, un ser virtualmente idéntico al hombre y conocido como Replicante.  Los Replicantes Nexus-6 eran superiores en fuerza y agilidad, y al menos iguales en inteligencia, a los ingenieros de genética que los crearon.  En el espacio exterior, los Replicantes fueron usados como trabajadores esclavos en la arriesgada exploración y colonización de otros planetas.  Después de la sangrienta rebelión de un equipo de combate de Nexus-6 en una colonia sideral, los Replicantes fueron declarados proscritos en la Tierra bajo pena de muerte.  Brigadas de policías especiales, con el nombre de Unidades de Blade Runners, tenían órdenes de tirar a matar al ver a cualquier Replicante invasor.  A esto no se le llamó ejecución, se le llamó retiro.","de":"Man schreibt das Jahr 2019. Den Replikanten, künstlichen Menschen, ist bei Todesstrafe die Rückkehr zur Erde verboten. Doch trotzdem kehren eines Tages einige dieser Wesen zurück. Diese besondere Spezies verfügt über Kraft und Intelligenz mehrerer Menschen und ist von diesen kaum zu unterscheiden. Sie sollen unschädlich gemacht werden. Nur eine Spezialeinheit kann sie aufspüren: die Blade Runner. Eine atemberaubende Hetzjagd durch die futuristische Welt beginnt."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2mPclQ5v9YK0eqCefvav3YsYPYI.jpg","en":"https://image.tmdb.org/t/p/w500/63N9uy8nd9j7Eog2axPQ8lbr3Wj.jpg","fr":"https://image.tmdb.org/t/p/w500/zHKWxyG4j404HVeSYHNH4niUpkW.jpg","es":"https://image.tmdb.org/t/p/w500/pBA2J6iQMiP5Zd4ewMKdOWfq1HV.jpg","de":"https://image.tmdb.org/t/p/w500/iD88HsailBEKNBoxj82CxtXesHX.jpg"}'::jsonb WHERE id = 146;
UPDATE public.films SET tmdb_id = 9671, titoli_i18n = '{"en":"Crocodile Dundee","es":"Cocodrilo Dundee","it":"Mr. Crocodile Dundee","fr":"Crocodile Dundee","de":"Crocodile Dundee - Ein Krokodil zum Küssen"}'::jsonb, trame_i18n = '{"en":"When a New York reporter plucks crocodile hunter Mick Dundee from the Australian Outback for a visit to the Big Apple, it''s a clash of cultures and a recipe for good-natured comedy as naïve Dundee negotiates the concrete jungle. He proves that his instincts are quite useful in the city and adeptly handles everything from wily muggers to high-society snoots without breaking a sweat.","es":"Michael Dundee es un amigable y rudo cazador de cocodrilos en el salvaje outback australiano que, por su original filosofía de la vida, es considerado como un héroe entre los suyos. Su fama llega a oídos de Sue Charlton, una reportera de Nueva York que decide ir a Australia para visitarle y, una vez allí, le convence para que le acompañe en su viaje de regreso a América.","it":"Sue Charlton, una giornalista di New York, si reca nell''outback australiano per incontrare Michael J. \"Crocodile\" Dundee, un leggendario cacciatore di coccodrilli. Affascinata dal suo stile di vita, lo invita a New York, dove Dundee dovrà adattarsi alla caotica vita della metropoli.","fr":"Crocodile Dundee alias Michael J. est un aventurier qui hante les vastes étendues du Bush australien : repas de lézards, larves et fourmis, rencontres inopinées avec des serpents et crocodiles… Élevé par une tribu d’aborigènes, il « zone » dans ces terrifiantes contrées comme un poisson dans l’eau. Sue Charlton, ambitieuse journaliste américaine, découvre l’homme sauvage et veut à tout prix faire un scoop. Elle finit par le rencontrer, l’emmène à New York, succombe à ses charmes et le suit pour le meilleur et pour le pire…","de":"Die amerikanische Journalistin Sue Charlton reist nach Down Under, um Mick „Crocodile“ Dundee kennenzulernen, über den sie abenteuerliche Geschichten rund um einen Kampf gegen ein Krokodil gelesen hat. Und tatsächlich erweist sich der australische Buschmann als naturverbundener Bursche, der es mit den Gefahren der australischen Flora und Fauna locker aufnehmen kann, weil er gelernt hat, auch in schwierigen Verhältnissen zu überleben. Fasziniert von dem Hinterwäldler lädt Sue Mick ein, sie nach New York zu begleiten. Dort muss Crocodile Dundee lernen, dass die Gefahren des Natur- und die des Großstadtdschungels nicht die gleichen sind. Aber der kernige Australier weiß natürlich, wie man sich einer neuen Umgebung anpasst und seine im Busch erworbenen Fähigkeiten aus stoischer Ruhe und kämpferischem Können kann er auch in New York anwenden."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/pduPduL1ub5kok3lPYT15ryC9L6.jpg","es":"https://image.tmdb.org/t/p/w500/q0Msbpvpe6yuvIUCyJuBbQ9UhUj.jpg","it":"https://image.tmdb.org/t/p/w500/j7slCp0VJeGPpcrUNykuZS2zrhL.jpg","fr":"https://image.tmdb.org/t/p/w500/1Oghywy3zfyTu0gxbnqzrZwlwDS.jpg","de":"https://image.tmdb.org/t/p/w500/jaHYkInyWaS8c9SrSvtLX5JaP5R.jpg"}'::jsonb WHERE id = 147;
UPDATE public.films SET tmdb_id = 8619, titoli_i18n = '{"es":"Master and commander: Al otro lado del mundo","fr":"Master and Commander : De l''autre côté du monde","en":"Master and Commander: The Far Side of the World","de":"Master and Commander - Bis ans Ende der Welt","it":"Master & Commander - Sfida ai confini del mare"}'::jsonb, trame_i18n = '{"es":"Durante las guerras napoleónicas, un impetuoso capitán británico llevará su barco y a su tripulación al límite en una formidable persecución por las costas de Sudamérica tras un gran buque de guerra francés.","fr":"1805, durant les guerres napoléoniennes, la HMS Surprise, commandée par le Capitaine Jack Aubrey se lance à la poursuite du vaisseau français Acheron à travers l''océan Pacifique (affrontant notamment le cap Horn). Ils croisent par ailleurs au large des îles Galápagos, dont la faune et la flore vont beaucoup intéresser le chirurgien Stephen Maturin, naturaliste passionné et précurseur de Charles Darwin. Mais les événements vont changer les plans du capitaine.","en":"After an abrupt and violent encounter with a French warship inflicts severe damage upon his ship, a captain of the British Royal Navy begins a chase over two oceans to capture or destroy the enemy, though he must weigh his commitment to duty and ferocious pursuit of glory against the safety of his devoted crew, including the ship''s thoughtful surgeon, his best friend.","de":"Während der Napoleonischen Kriege bereist der charismatische Kapitän Jack Aubrey mit seiner HMS Surprise auf Forschungsreise die Weltmeere. Immer an seiner Seite: Der friedliebende Schiffsarzt Dr. Steven Maturin. Als das französische Kaperschiff Acheron die Surprise angreift und Schiff wie Mannschaft herbe Verluste zufügt, schwört Aubrey Rache. Es entbrennt eine gnadenlose Jagd, die die geschundene Mannschaft in einer sturmumtosten Fahrt vom Kap Horn über die Galapagos Inseln bis nach Südamerika führt.","it":"Durante le guerre napoleoniche, la fregata britannica HMS Surprise, guidata dal carismatico capitano Jack Aubrey, riceve l''ordine di intercettare e catturare la nave corsara francese Acheron. Dopo un devastante attacco a sorpresa da parte di quest''ultima, Aubrey decide di inseguire il nemico attraverso gli oceani, spingendosi fino a Capo Horn e alle isole Galápagos, in una caccia ossessiva che metterà a dura prova la lealtà e la sopravvivenza del suo equipaggio."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/6wk7lrTxk6Adnzp1mVWexM1lj5b.jpg","fr":"https://image.tmdb.org/t/p/w500/xgxlMRIrtHqmkUKv9IuMnXINYsE.jpg","en":"https://image.tmdb.org/t/p/w500/7ZUHF6P0vcA5v1Gm8NbRYyd9w4N.jpg","de":"https://image.tmdb.org/t/p/w500/wCaEKGKV8DMnAWAApWYdFN1ZpY7.jpg","it":"https://image.tmdb.org/t/p/w500/6J8Cpjaan2KfLGglruBZE7MoTo7.jpg"}'::jsonb WHERE id = 148;
UPDATE public.films SET tmdb_id = 6916, titoli_i18n = '{"en":"Watch Out, We''re Mad","es":"…Y si no, nos enfadamos","it":"...altrimenti ci arrabbiamo!","fr":"Attention, on va s''fâcher !","de":"Zwei wie Pech und Schwefel"}'::jsonb, trame_i18n = '{"en":"After a tied 1st place in a local stunt race, two drivers start a contest to decide who of them will own the prize, a dune buggy. But when a mobster destroys the car, they are determined to get it back.","es":"Kid y Ben, amigos pero rivales, participan en una carrera de coches cuyo premio es un estupendo «dune-buggy», un minibólido rojo con capota amarilla. Después de innumerables peripecias, Kid y Ben llegan juntos a la meta, por lo que el minibólido les pertenece a los dos. Kid propone que se lo jueguen a «cervezas y salchichas».","it":"Ben e Kid, un meccanico e un camionista appassionati di autocross, vincono a pari merito una fantastica Dune Buggy rossa con cappottina gialla. Non potendola dividere, decidono di giocarsela in una sfida a birra e salsicce. La gara viene però interrotta dagli scagnozzi di un gangster speculatore edilizio chiamato ''il Capo'', che distruggono il locale e danno fuoco alla macchina. I due si recano dal boss per pretendere una Dune Buggy nuova identica a quella distrutta, avvertendolo con un chiaro ''...altrimenti ci arrabbiamo!'': di fronte al rifiuto, scateneranno l''inferno a suon di memorabili scazzottate.","fr":"Kid et Ben, deux coureurs automobiles finissent ex-aequo dans une course dont le prix principal est une petite voiture. Alors que les tractations vont bon train pour savoir qui gagnera finalement le véhicule, un membre de la mafia détruit ce dernier. Kid et Ben vont alors faire équipe pour se venger...","de":"Ben und Kid – zwei begeisterte Hobbyrennfahrer – gehen bei einem Cross-Rennen gleichzeitig als Erste ins Ziel und müssen sich den Gewinn in Form eines Strandbuggys teilen. In einem benachbarten Freizeitpark soll deshalb ein Wettessen mit Bier und Würstchen den wahren Sieger ermitteln. Als eine Ganovenbande auftaucht und im Auftrag eines Grundstückspekulanten versucht, die Bewohner des Stadtviertels zu verschrecken, bilden die einstigen Rivalen sofort ein schlagkräftiges Team. Gemeinsam haben sie nicht nur vier wirksame Argumente gegen das skrupellose Vorgehen der Verbrecher, sondern schließlich auch einen Grund zur gegenseitigen Wiedergutmachung. Im Zuge ihrer Zerstörungsorgie erwischen die Ganoven nämlich auch das neue Gefährt der beiden passionierten Fahrer und sehen sich nun deren Zorn ausgesetzt. Die Gangster lassen ab jetzt nichts mehr unversucht, um Ben und Kid unter die Erde zu bringen, doch die beiden wissen sich zu wehren."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/oERikPHC3cr9UDCale6YrQxkyNW.jpg","es":"https://image.tmdb.org/t/p/w500/zjc73gfkJ3BbAuZV4xggB8X3P1W.jpg","it":"https://image.tmdb.org/t/p/w500/27bKMOKfVtOicxZPP1Nk78WyCFE.jpg","fr":"https://image.tmdb.org/t/p/w500/7uvvdb8KYc8yjpn3rkZX0s8Na7b.jpg","de":"https://image.tmdb.org/t/p/w500/ou7i8HuxEdMGqTDh90nUCFaVO7I.jpg"}'::jsonb WHERE id = 149;
UPDATE public.films SET tmdb_id = 438631, titoli_i18n = '{"it":"Dune","es":"Dune","fr":"Dune","en":"Dune","de":"Dune"}'::jsonb, trame_i18n = '{"it":"In un lontano futuro dell''umanità, il duca Leto Atreides accetta la gestione del pericoloso pianeta desertico Arrakis, noto anche come Dune, l''unica fonte della sostanza più preziosa dell''universo, la \"spezia\". Paul Atreides, il giovane erede della dinastia, dovrà viaggiare verso il pianeta più pericoloso dell''universo per assicurare il futuro della sua famiglia e del suo popolo.","es":"En un lejano futuro, la galaxia conocida es gobernada mediante un sistema feudal de casas nobles bajo el mandato del Emperador. Las alianzas y la política giran entorno a un pequeño planeta, Dune,  del que extrae la ''especia melange'', la materia prima que permite los viajes espaciales. La Casa Atreides, bajo el mandato del Duque Leto Atreides recibe el encargo de custodiar el planeta, relevando en la encomienda a sus históricos enemigos, los Harkonnen. Paul Atreides, hijo del duque, se verá atrapado en las intrigas políticas mientras descubre el destino que le deparan los desiertos de Dune.","fr":"L''histoire de Paul Atreides, jeune homme aussi doué que brillant, voué à connaître un destin hors du commun qui le dépasse totalement. Car, s''il veut préserver l''avenir de sa famille et de son peuple, il devra se rendre sur Dune, la planète la plus dangereuse de l''Univers. Mais aussi la seule à même de fournir la ressource la plus précieuse capable de décupler la puissance de l''Humanité. Tandis que des forces maléfiques se disputent le contrôle de cette planète, seuls ceux qui parviennent à dominer leur peur pourront survivre…","en":"Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence - a commodity capable of unlocking humanity''s greatest potential - only those who can conquer their fear will survive.","de":"„Dune“ erzählt die packende Geschichte des brillanten jungen Helden Paul Atreides, dem das Schicksal eine Rolle vorherbestimmt hat, von der er niemals geträumt hätte. Um die Zukunft seiner Familie und seines gesamten Volkes zu sichern, muss Paul auf den gefährlichsten Planeten des Universums reisen. Nur auf dieser Welt existiert ein wertvoller Rohstoff, der es der Menschheit ermöglichen könnte, ihr vollständiges geistiges Potenzial auszuschöpfen. Doch finstere Mächte wollen die Kontrolle über die kostbare Substanz an sich reißen. Es entbrennt ein erbitterter Kampf, den nur diejenigen überleben werden, die ihre eigenen Ängste besiegen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zolKD2yscZd86GviNa6pBPc6N9o.jpg","es":"https://image.tmdb.org/t/p/w500/szcew6yyjcDvaL0isaPBk2e3nkF.jpg","fr":"https://image.tmdb.org/t/p/w500/qpyaW4xUPeIiYA5ckg5zAZFHvsb.jpg","en":"https://image.tmdb.org/t/p/w500/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg","de":"https://image.tmdb.org/t/p/w500/34Hr4bEzF30jd6sEvI4HihEUEI8.jpg"}'::jsonb WHERE id = 150;
UPDATE public.films SET tmdb_id = 693134, titoli_i18n = '{"it":"Dune - Parte due","es":"Dune: Parte dos","en":"Dune: Part Two","de":"Dune: Part Two","fr":"Dune : Deuxième partie"}'::jsonb, trame_i18n = '{"it":"Paul Atreides si unisce a Chani e ai Fremen sul sentiero della vendetta contro i cospiratori che hanno distrutto la sua famiglia. Di fronte alla scelta tra l''amore della sua vita e il destino dell''universo conosciuto, Paul intraprende una missione per impedire un futuro terribile che solo lui è in grado di prevedere.","es":"Sigue el viaje mítico de Paul Atreides mientras se une a Chani y los Fremen en una guerra de venganza contra los conspiradores que destruyeron a su familia. Al enfrentarse a una elección entre el amor de su vida y el destino del universo conocido, Paul se esfuerza por evitar un futuro terrible que solo él puede prever.","en":"Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a path of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the known universe, Paul endeavors to prevent a terrible future only he can foresee.","de":"Paul Atreides begibt sich mithilfe von Chani und den Fremen auf einen Rachefeldzug gegen die Verschwörer, die seine Familie vernichtet haben. Der junge Paul steht vor der Wahl zwischen der Liebe seines Lebens und dem Schicksal des gesamten Universums. Mit allen Mitteln aber muss er versuchen, eine schreckliche Zukunft zu verhindern – eine Zukunft, die niemand außer ihm vorhersehen kann.","fr":"Le voyage mythique de Paul Atreides qui s''allie à Chani et aux Fremen dans sa quête de vengeance envers les conspirateurs qui ont anéanti sa famille. Devant choisir entre l''amour de sa vie et le destin de l''univers, il fera tout pour éviter un terrible futur que lui seul peut prédire."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/nhdQxDCI64rMgypYZpsF7UvbdJA.jpg","es":"https://image.tmdb.org/t/p/w500/v2NN1TMK3ifuiEyawa3ukkcSOUQ.jpg","en":"https://image.tmdb.org/t/p/w500/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg","de":"https://image.tmdb.org/t/p/w500/zYLP7Uiqz6XqoiQLAu4XQ6DRUMz.jpg","fr":"https://image.tmdb.org/t/p/w500/iRNbRAIGQQr5diGnjpwJFm0dgt4.jpg"}'::jsonb WHERE id = 151;
UPDATE public.films SET tmdb_id = 503, titoli_i18n = '{"it":"Poseidon","fr":"Poséidon","en":"Poseidon","es":"Poseidón","de":"Poseidon"}'::jsonb, trame_i18n = '{"it":"Durante la notte di Capodanno, una gigantesca onda anomala travolge e capovolge la lussuosa nave da crociera Poseidon. Un piccolo gruppo di sopravvissuti decide di non aspettare i soccorsi e tenta una disperata fuga verso la salvezza attraverso lo scafo capovolto.","fr":"Une nuit de Saint Sylvestre festive a commencé au milieu de l''Atlantique Nord, sur le luxueux navire de croisière Poséidon. De nombreux passagers se sont rassemblés dans l''opulente salle de bal pour fêter dignement l''événement avec le capitaine Bradford. Pendant ce temps, le second scrute avec inquiétude l''horizon du haut de la passerelle. La menace surgit en quelques secondes, sous la forme d''une vague géante de plus de 30 mètres de haut, fonçant à toute allure sur le navire. Le second redresse la barre pour éviter un choc frontal, mais il est déjà trop tard. La muraille d''eau se fracasse avec une violence inouïe sur le paquebot qu''elle retourne, quille en l''air. Quelques centaines de rescapés se retrouvent dans la salle de bal, encore intacte quoique située sous la ligne de flottaison…","en":"A packed cruise ship traveling the Atlantic is hit and overturned by a massive wave, compelling the passengers to begin a dramatic fight for their lives.","es":"En el Atlántico Norte, a bordo del lujoso trasatlántico Poseidón (veinte pisos, trece cubiertas) comienza la fiesta de Nochevieja. Mientras tanto, una gigantesca ola de treinta metros de altura se dirige hacia la nave a gran velocidad. Los intentos para desviar el barco y evitar el choque son inútiles. La ola lo golpea con una fuerza colosal y lo vuelca. Los pasajeros y los miembros de la tripulación caen desde una gran altura y van a parar entre los restos del naufragio o se sumergen en el mar. Tras el espectacular y dramático vuelco, las tuberías de gas quedan rotas y escupen fuego, y la electricidad falla dejando grandes secciones del buque sumergidas en la oscuridad y el caos.","de":"Auf allen Decks des Kreuzfahrtschiffes \"Poseidon\" wird kräftig Silvester gefeiert. Da erfasst eine Monsterwelle den Ozeanriesen und wirft ihn einfach um. Das kopfüber gekenterte Schiff läuft mit Wasser voll. Eine Gruppe Überlebender, darunter der Zocker Dylan, die Witwe Maggie mit ihrem Sohn Connor und der Ex-Feuerwehrmann Robert Ramsey samt Tochter und deren heimlichem Verlobten, entschließt sich, das Schicksal selbst in die Hand zu nehmen. Und so macht sie sich auf zu einem Höllentrip quer durch den Rumpf des sinkenden Luxusliners."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qWenXpjkzQ04wt5DLwzwrSjxLhl.jpg","fr":"https://image.tmdb.org/t/p/w500/4VrwxE0CDoXxfgTRD11gCFlYaFP.jpg","en":"https://image.tmdb.org/t/p/w500/fDPdjGc8SUEDWfTwMaZlCE6NSi3.jpg","es":"https://image.tmdb.org/t/p/w500/4OlwVoSxeeP9TuZ5OdKWnIPLvsO.jpg","de":"https://image.tmdb.org/t/p/w500/9SXa5QKjKeFYs6nq0zDqAzXasMX.jpg"}'::jsonb WHERE id = 152;
UPDATE public.films SET tmdb_id = 862, titoli_i18n = '{"it":"Toy Story - Il mondo dei giocattoli","en":"Toy Story","es":"Toy Story","fr":"Toy Story","de":"Toy Story"}'::jsonb, trame_i18n = '{"it":"Woody, un classico pupazzo da cowboy, è il giocattolo preferito del piccolo Andy e il leader riconosciuto di tutti gli altri giochi della cameretta. La sua posizione viene però minacciata quando per il compleanno di Andy arriva Buzz Lightyear, un supertecnologico astronauta giocattolo convinto di essere un vero spaziotraversatore. Inizialmente rivali, Woody e Buzz si ritroveranno accidentalmente divisi da Andy e dovranno unire le forze per affrontare mille pericoli e tornare a casa.","en":"Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.","es":"Los juguetes de Andy, un niño de seis años, temen que haya llegado su hora y que un nuevo regalo de cumpleaños les sustituya en el corazón de su dueño. Woody, un vaquero que ha sido hasta ahora el juguete favorito de Andy, trata de tranquilizarlos hasta que aparece Buzz Lightyear, un héroe espacial dotado de todo tipo de avances tecnológicos. Woody es relegado a un segundo plano, pero su constante rivalidad se transformará en una gran amistad cuando ambos se pierden en la ciudad sin saber cómo volver a casa.","fr":"Dans un monde où les jouets vivent leur vie quand les humains ne sont pas présents, Toy Story emmène les spectateurs dans un voyage fantastique vu principalement par les yeux de deux rivaux : Woody, un cow-boy, et Buzz l''Éclair, un ranger de l’espace. Ce duo va devoir apprendre à mettre ses différences de côté et s''allier, lorsqu’il sera séparé de son propriétaire Andy.","de":"Als Andys Lieblingspuppe hat Woody im Kinderzimmer das Sagen. Kaum ist der Junge nicht da, erwacht die Cowboy-Figur zum Leben, und mit ihm auch all das andere Spielzeug um ihn herum. Aufgeregt debattiert man über Andys bevorstehenden Geburtstag. Es wird befürchtet, daß ihr Besitzer ein neues Geschenk bevorzugen wird. Und tatsächlich: Der Neuankömmling Buzz Lightyear, ein stolzer Space Ranger, avanciert zu Andys Favoriten. Diese Herabstufung will Woody nicht hinnehmen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9E1UvfLS9PIO9c8TJEOQ7kfFq3Z.jpg","en":"https://image.tmdb.org/t/p/w500/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg","es":"https://image.tmdb.org/t/p/w500/jvn7wy3RSNEXnFSXLpH2of2LcV6.jpg","fr":"https://image.tmdb.org/t/p/w500/4cWLRhub0yY9VJpdw0nqoTPYyiN.jpg","de":"https://image.tmdb.org/t/p/w500/om4fMx3e4xkx27sAsacoFP4WiEd.jpg"}'::jsonb WHERE id = 153;
UPDATE public.films SET tmdb_id = 863, titoli_i18n = '{"en":"Toy Story 2","it":"Toy Story 2 - Woody e Buzz alla riscossa","es":"Toy Story 2: Los juguetes vuelven a la carga","fr":"Toy Story 2","de":"Toy Story 2"}'::jsonb, trame_i18n = '{"en":"Andy heads off to Cowboy Camp, leaving his toys to their own devices. Things shift into high gear when an obsessive toy collector named Al McWhiggen, owner of Al''s Toy Barn kidnaps Woody. Andy''s toys mount a daring rescue mission, Buzz Lightyear meets his match and Woody has to decide where he and his heart truly belong.","it":"Mentre Andy è via per il campeggio estivo, Woody viene rapito da Al McWhiggin, un gordo e avido collezionista di giocattoli deciso a venderlo a un museo di Tokyo insieme ai membri della classica serie TV ''Woody''s Roundup''. Buzz Lightyear e gli altri giocattoli di Andy partono immediatamente per una coraggiosa missione di salvataggio per riportare l''amico a casa.","es":"Cuando Andy se va de campamento dejando solos a los juguetes, Al McWhiggin, un compulsivo coleccionista de juguetes valiosos, secuestra a Woody. Buzz Lightyear y el resto de los juguetes de Andy deberán actuar con rapidez para rescatarlo, poniéndose al frente de una operación de rescate durante la cual se enfrentarán a múltiples peligros y divertidas situaciones.","fr":"Andy part en colonie de vacances et laisse ses jouets à la maison. Les choses se gâtent quand le collectionneur Al McWhiggin kidnappe Woody. Dans l’appartement d’Al, Woody découvre qu’il est un objet de collection d’une émission des années 50, il rencontre d’autres jouets : Jessie, Pile-Poil, Papi Pépite. Buzz et les autres vont tenter de sauver Woody, avant qu’il ne devienne une pièce de musée.","de":"Als Woody von einem fiesen Sammler entführt wird macht sich die Puppen-Clique auf, ihren Freund zu befreien - aber schon auf die andere Straßenseite zu gelangen, gestaltet sich schwierig, ganz zu schweigen von den lauernden Gefahren im Spielzeugladen gegenüber: Doppelgänger stellen sich Buzz Lightyear in den Weg, durchgeknallte Barbie-Sirenen drohen die edlen Ritter vom rechten Weg abzubringen, und obendrein entkommt Zurg, der böse Imperator, aus seiner Plastikbox..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg","it":"https://image.tmdb.org/t/p/w500/lHloXovbVaQ1tbOB1UaVQm6GgXo.jpg","es":"https://image.tmdb.org/t/p/w500/8OTDKkJv2jXg5ZHKazFxBAttKkR.jpg","fr":"https://image.tmdb.org/t/p/w500/144DDQdfZxAK5xyPTETmygzGGuH.jpg","de":"https://image.tmdb.org/t/p/w500/nS0QGWMcUFpxoML061PW50oeUS5.jpg"}'::jsonb WHERE id = 154;
UPDATE public.films SET tmdb_id = 10193, titoli_i18n = '{"it":"Toy Story 3 - La grande fuga","en":"Toy Story 3","fr":"Toy Story 3","es":"Toy Story 3","de":"Toy Story 3"}'::jsonb, trame_i18n = '{"it":"Andy, ormai cresciuto, sta per partire per il college. Woody, Buzz e gli altri giocattoli vengono accidentalmente donati a un asilo nido, il Sunnyside, che si rivelerà essere tutt''altro che un paradiso, sotto il controllo del malvagio orsetto Lotso. I giocattoli dovranno pianificare una grande fuga per tornare a casa.","en":"Woody, Buzz, and the rest of Andy''s toys haven''t been played with in years. With Andy about to go to college, the gang find themselves accidentally left at a nefarious day care center. The toys must band together to escape and return home to Andy.","fr":"Woody, Buzz l’Éclair et le reste des jouets reviennent dans une toute nouvelle aventure avec quelques nouveaux visages dont Ken et Barbie, le hérisson La Brosse et l’ours Lotso. Andy se prépare à partir pour l’université et Woody, Buzz, Jessie et les autres jouets se demandent ce qu’ils vont devenir. Quand ils arrivent à Sunnyside, c’est le début d’une nouvelle aventure.","es":"Sabiendo que su dueño Andy, que ya no es un niño, se prepara para ir a la universidad, el vaquero Woody, el astronauta Buzz y el resto de sus amigos juguetes comienzan a preocuparse ante su incierto futuro. Efectivamente todos acaban en una guardería, donde por ejemplo la muñeca Barbie conocerá al guapo Ken. Esta reunión de nuestros amigos con otros nuevos juguetes no será sino el inicio de un montón de trepidantes y divertidas aventuras.","de":"Der Moment des Abschieds ist gekommen: Andy ist den Kinderschuhen entwachsen und macht sich bereit, aufs College zu gehen. Für sein stets getreues Spielzeug hat er keine Verwendung mehr. Andys Mutter spendet die Spielsachen der Kindertagesstätte Sunnyside. Doch dieses angebliche Paradies entpuppt sich nach zuerst freundlicher Aufnahme durch die alteingesessenen Spielzeuge bald zum Gefängnis für die Freunde. Ein ausgeklügelter Ausbruchsplan wird ausgearbeitet - die Zeit drängt, denn hier geht nicht alles mit rechten Dingen zu."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tTBILVsSwLRB2CiNVSlewd5XZsW.jpg","en":"https://image.tmdb.org/t/p/w500/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg","fr":"https://image.tmdb.org/t/p/w500/zycAhl8iwRxu1NQ0tITqA6KXHIM.jpg","es":"https://image.tmdb.org/t/p/w500/yBSISwqix2z0JiwIrM3r6fiI6Cm.jpg","de":"https://image.tmdb.org/t/p/w500/aHxQdb3Ennws1EIraHnOS3BFjVJ.jpg"}'::jsonb WHERE id = 155;
UPDATE public.films SET tmdb_id = 301528, titoli_i18n = '{"it":"Toy Story 4","de":"A Toy Story: Alles hört auf kein Kommando","es":"Toy Story 4","fr":"Toy Story 4","en":"Toy Story 4"}'::jsonb, trame_i18n = '{"it":"Woody, Buzz e il resto della banda vivono felici con la loro nuova bambina, Bonnie. Quando Bonnie crea un nuovo riluttante giocattolo di nome Forky da un cucchiaio-forchetta usa e getta, Woody si assume il compito di proteggerlo. Durante un viaggio di famiglia on-the-road, Woody ritrova la sua vecchia amica Bo Peep, scoprendo una nuova prospettiva su cosa significhi essere un giocattolo.","de":"Die Cowboy-Puppe Woody und sein Freund Buzz Lightyear haben sich mit den anderen Spielsachen gut im Kinderzimmer ihrer neuen Besitzerin, Bonnie, eingerichtet. Als das Mädchen aus einem Göffel (Gabel + Löffel) ein neues Spielzeug namens Forky bastelt und es ins Herz schließt, nehmen sie den ungewöhnlichen Zuwachs mit offenen Armen in ihre Mitte auf. Doch Forky sieht sich selbst eher als Abfall an und flüchtet, woraufhin Woody sich auf die Suche nach ihm macht, um ihn zurückzubringen.  Auf dem Ausflug im Wohnwagen mit Bonnies Familie nimmt Woody außerdem einen unerwarteten Umweg und trifft so in einem Antiquitätenladen seine verlorene Freundin, die Schäferin Bo Peep, wieder. Und dann taucht auch noch ein Freizeitpark am Horizont auf, der das Leben der Spielzeuge zusätzlich ins Chaos stürzt.","es":"Woody siempre ha tenido claro cuál es su labor en el mundo y cuál es su prioridad: cuidar a su dueño, ya sea Andy o Bonnie. Sin embargo, Woody descubrirá lo grande que puede ser el mundo para un juguete cuando Forky se convierta en su nuevo compañero de habitación. Los juguetes se embarcarán en una aventura de la que no se olvidarán jamás.","fr":"Woody a toujours privilégié la joie et le bien‐être de ses jeunes propriétaires – Andy puis Bonnie – et de ses compagnons, n’hésitant pas à prendre tous les risques pour eux, aussi inconsidérés soient‐ils. L’arrivée de Forky, un nouveau jouet qui ne veut pas en être un dans la chambre de Bonnie, met toute la petite bande en émoi. C’est le début d’une grande aventure et d’un extraordinaire voyage pour Woody et ses amis. Le cowboy va découvrir à quel point le monde peut être vaste pour un jouet…","en":"Woody has always been confident about his place in the world, devoted to taking care of his kid—whether that''s Andy or Bonnie. But after Bonnie creates a reluctant new toy called \"Forky\", a road trip adventure alongside old and new friends challenges everything Woody believes about loyalty, purpose, and what it truly means to be a toy."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/lilCjgWKcwIpa55BuTzzI2BMZgP.jpg","de":"https://image.tmdb.org/t/p/w500/s1Laea6lrtQVs4HLC1Mtkjl9UAp.jpg","es":"https://image.tmdb.org/t/p/w500/yF1vPDuHVrAUMX5dy1tVMbAjkEL.jpg","fr":"https://image.tmdb.org/t/p/w500/qWtRA6rfUNm81A7ITDrq6WkfCNy.jpg","en":"https://image.tmdb.org/t/p/w500/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg"}'::jsonb WHERE id = 156;
UPDATE public.films SET tmdb_id = 1084244, titoli_i18n = '{"it":"Toy Story 5","en":"Toy Story 5","fr":"Toy Story 5","es":"Toy Story 5","de":"Toy Story 5"}'::jsonb, trame_i18n = '{"it":"In questo nuovo capitolo della celebre saga Pixar, i giocattoli si trovano ad affrontare una sfida del tutto moderna: la competizione con la tecnologia e i dispositivi elettronici, che catturano sempre di più l''attenzione dei bambini di oggi.","en":"When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.","fr":"Buzz, Woody, Jessie et le reste de la bande verront leur travail remis en question lorsqu''ils découvriront que ce qui obsède les enfants d''aujourd''hui s’appelle... l''électronique !","es":"Los juguetes de Bonnie se enfrentan a otra amenaza cuando la niña recibe una tableta llamada Lilypad, la cual absorbe toda su atención y pone en peligro el juego tradicional. Todos deben unirse para competir contra la tecnología y recuperar su lugar.","de":"Die Kult-Spielzeuge sind zurück – und diesmal trifft Spielzeug auf Technik. Woody, Buzz Lightyear, Jessie und der Rest der Bande stehen vor einer ganz neuen Herausforderung, als sie auf Lilypad treffen, ein funkelnagelneues Tablet, das sehr eigenwillige Vorstellungen davon hat, was für ihr Kind Bonnie am besten ist. Wird das Spielen jemals wieder so sein wie zuvor?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/i7eQGriXCmNpScSVzepNHn9nMPM.jpg","en":"https://image.tmdb.org/t/p/w500/sfQtVlIHljToOwYjhe21KPGzZWK.jpg","fr":"https://image.tmdb.org/t/p/w500/b2bt3UomRX41rHHZmIsSNmXzidU.jpg","es":"https://image.tmdb.org/t/p/w500/pTjZfbFVWUIwUM5OzX3LVh84ejU.jpg","de":"https://image.tmdb.org/t/p/w500/geypzdXdx8LooxB691r3bhlrybB.jpg"}'::jsonb WHERE id = 157;
UPDATE public.films SET tmdb_id = 272, titoli_i18n = '{"it":"Batman Begins","es":"Batman Begins","en":"Batman Begins","de":"Batman Begins","fr":"Batman Begins"}'::jsonb, trame_i18n = '{"it":"Dopo aver assistito all''omicidio dei suoi genitori, il giovane erede Bruce Wayne viaggia per il mondo alla ricerca di un modo per combattere le ingiustizie. Tornato a Gotham City, crea l''iconico alter ego di Batman per salvare la città dalla corruzione e dalle minacce del temibile Ra''s al Ghul e dello Spaventapasseri.","es":"¿Cómo cambia un hombre el mundo? Es una pregunta que obsesiona a Bruce Wayne al igual que el fantasma de sus padres, muertos a tiros ante sus ojos en las calles de Gotham una noche que cambió su vida para siempre. Atormentado por la culpa y la ira, el desilusionado heredero industrial desaparece de Gotham y viaja en secreto por el mundo, buscando los medios de luchar contra la injusticia y utilizar el miedo contra los que se aprovechan de los que tienen miedo. Con la ayuda de su leal mayordomo Alfred, el detective Jim Gordon - uno de los pocos buenos policías de las fuerzas del orden público de Gotham - y Lucius Fox, su aliado en la división de Ciencias Aplicadas de Wayne Enterprises, Bruce Wayne libera a su imponente alter ego: Batman, un justiciero enmascarado que utiliza la fuerza, la inteligencia y un despliegue de artefactos de alta tecnología para combatir las fuerzas siniestras que amenazan con destruir la ciudad.","en":"Driven by tragedy, billionaire Bruce Wayne dedicates his life to uncovering and defeating the corruption that plagues his home, Gotham City.  Unable to work within the system, he instead creates a new identity, a symbol of fear for the criminal underworld - The Batman.","de":"Wie wurde Bruce Wayne zu Batman? Als kleiner Junge musste Bruce Wayne mit ansehen, wie seine Eltern auf grauenhafte Weise umgebracht wurden. Deshalb kümmert sich der Butler Alfred Pennyworth um ihn und zieht ihn groß.Eines Tages macht er sich in aller Welt auf die Suche nach einem Weg, die Ungerechtigkeit zu bekämpfen. Als er nach seiner Reise wieder in seine Heimatstadt Gotham City zurückkehrt, muss er feststellen, dass die Verbrechensrate deutlich angestiegen ist. Dieser Umstand und der Drang nach Rache am Mord seiner Eltern treiben ihn langsam aber sicher dazu, sich Kampftechniken beizubringen und ein Fledermauskostüm zu entwerfen, mit deren Hilfe er Nacht für Nacht die Kriminellen der Stadt zur Strecke bringt - als Batman.","fr":"Alors que le souvenir de ses parents assassinés le hante, Bruce Wayne, désemparé, erre à travers le monde cherchant les moyens de combattre l''injustice et ses propres peurs. Avec l''aide de son dévoué majordome et homme de confiance Alfred, de l''inspecteur Jim Gordon et de son allié Lucius Fox, Wayne revient à Gotham City et révèle son alter ego : Batman, un justicier masqué qui utilise sa force, son intelligence et une batterie d''armes high-tech pour combattre les forces sinistres qui menacent la ville…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2eNeMwCncDvcJZ4AqKndWX71wDc.jpg","es":"https://image.tmdb.org/t/p/w500/6yMWU1vWkOBbNRIwOxhetd2aHhO.jpg","en":"https://image.tmdb.org/t/p/w500/sPX89Td70IDDjVr85jdSBb4rWGr.jpg","de":"https://image.tmdb.org/t/p/w500/b3UIToGx8JIpRqUTGkaoyaNLuU3.jpg","fr":"https://image.tmdb.org/t/p/w500/taKcn26BMWnsUcMFSlr5RfGDtFB.jpg"}'::jsonb WHERE id = 158;
UPDATE public.films SET tmdb_id = 155, titoli_i18n = '{"it":"Il cavaliere oscuro","de":"The Dark Knight","fr":"The Dark Knight : Le Chevalier noir","en":"The Dark Knight","es":"El caballero oscuro"}'::jsonb, trame_i18n = '{"it":"Con l''aiuto del tenente Jim Gordon e del determinato procuratore distrettuale Harvey Dent, Batman continua a combattere il crimine organizzato che affligge Gotham City. La tregua apparente viene però spezzata dall''ascesa del Joker, una mente criminale psicopatica e anarchica che sprofonda la metropoli nel terrore e costringe il Cavaliere Oscuro a camminare sul filo sottile che divide l''eroe dal vigilante.","de":"Gemeinsam mit Bezirksstaatsanwalt Harvey Dent und Lieutenant James Gordon versucht der im Fledermauskostüm agierende Milliardär Bruce Wayne dem Verbrechen in Gotham City Einhalt zu gebieten. Wie aus dem Nichts taucht plötzlich ein psychotischer Superverbrecher auf - der Joker. In seiner wahnhaften Vision möchte er die Stadt in Chaos und Anarchie stürzen und Batman scheint der einzige, der ihn stoppen kann. Bis es zum endgültigen Show-Down kommt, wird aber viel Blut fließen und auch Menschen die Bruce Wayne nahe stehen, könnten Opfer werden.","fr":"Batman aborde une phase décisive de sa guerre contre le crime à Gotham City. Avec l''aide du lieutenant de police Jim Gordon et du nouveau procureur Harvey Dent, il entreprend de démanteler les dernières organisations criminelles qui infestent les rues de la ville. L''association s''avère efficace, mais le trio se heurte bientôt à un nouveau génie du crime qui répand la terreur et le chaos dans Gotham : le Joker. On ne sait pas d''où il vient ni qui il est. Ce criminel possède une intelligence redoutable doublé d''un humour sordide et n''hésite pas à s''attaquer à la pègre locale dans le seul but de semer le chaos.","en":"Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.","es":"Batman/Bruce Wayne regresa para continuar su guerra contra el crimen. Con la ayuda del teniente Jim Gordon y del Fiscal del Distrito Harvey Dent, Batman se propone destruir el crimen organizado en la ciudad de Gotham. El triunvirato demuestra su eficacia, pero, de repente, aparece Joker, un nuevo criminal que desencadena el caos y tiene aterrados a los ciudadanos."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qIhsgno1mjbzUbs4H6DaRjhskAR.jpg","de":"https://image.tmdb.org/t/p/w500/z1DfRQf2CgnROyhVZ6ch8FbWt71.jpg","fr":"https://image.tmdb.org/t/p/w500/pyNXnq8QBWoK3b37RS6C3axwUOy.jpg","en":"https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg","es":"https://image.tmdb.org/t/p/w500/8QDQExnfNFOtabLDKqfDQuHDsIg.jpg"}'::jsonb WHERE id = 159;
UPDATE public.films SET tmdb_id = 49026, titoli_i18n = '{"es":"El caballero oscuro: La leyenda renace","fr":"The Dark Knight Rises","it":"Il cavaliere oscuro - Il ritorno","en":"The Dark Knight Rises","de":"The Dark Knight Rises"}'::jsonb, trame_i18n = '{"es":"Hace ocho años que Batman desapareció, dejando de ser un héroe para convertirse en un fugitivo. Al asumir la culpa por la muerte del fiscal del distrito Harvey Dent, el Caballero Oscuro decidió sacrificarlo todo por lo que consideraba, al igual que el Comisario Gordon, un bien mayor. La mentira funciona durante un tiempo, ya que la actividad criminal de la ciudad de Gotham se ve aplacada gracias a la dura Ley Dent. Pero todo cambia con la llegada de una astuta gata ladrona que pretende llevar a cabo un misterioso plan. Sin embargo, mucho más peligrosa es la aparición en escena de Bane, un terrorista enmascarado cuyos despiadados planes obligan a Bruce a regresar de su voluntario exilio.","fr":"Afin que l''image de l''ex-procureur Harvey Dent reste un modèle du genre pour les citoyens de Gotham City, Batman a endossé les crimes de ce dernier et a été chassé de la ville par les autorités.  Huit ans plus tard, alors que Gotham City est de nouveau sûre, le commissaire Gordon tombe sur un complot qui vise à détruire la ville de l''intérieur.  Il fait appel à Batman. Ce dernier devra faire face à la mystérieuse Selina Kyle et à Bane, un adversaire mortel, qui veut mettre en pièce le symbole Batman.","it":"Otto anni dopo la morte di Harvey Dent, Gotham City vive un periodo di pace grazie alle leggi speciali del Decreto Dent. Tuttavia, l''arrivo in città di Bane, un terrorista spietato e mascherato, e della misteriosa scassinatrice Selina Kyle, costringe un Bruce Wayne ormai ritirato e debilitato a indossare nuovamente il mantello di Batman per affrontare la minaccia definitiva alla sua città.","en":"Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.","de":"Nach dem Tod des Staatsanwalts Harvey Dent alias Two-Face nahm Batman die Schuld von dessen Verbrechen auf sich, um seinen Ruf zu schützen. Daher wurde er von dem Gotham City Police Department gejagt und verließ die Stadt. Die Handlung des Films setzt acht Jahre nach den Ereignissen von The Dark Knight ein. Nachdem der bemerkbar gealterte Batman nach Gotham zurückkehrt, muss er die Wahrheit der geheimnisvollen Selina Kyle herausfinden und den Schurken Bane davon abhalten, Gotham zu zerstören"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/rrS7K8tXVFUBliIKWaRuSq65nWr.jpg","fr":"https://image.tmdb.org/t/p/w500/ApcGBERN0p9I0nDOIwJeEmpnLU5.jpg","it":"https://image.tmdb.org/t/p/w500/p2JzxFRAlbxS4EvWMo4yiYZXu1W.jpg","en":"https://image.tmdb.org/t/p/w500/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg","de":"https://image.tmdb.org/t/p/w500/9NyCuhyvFKTqGRLcr4r8fWXnu9v.jpg"}'::jsonb WHERE id = 160;
UPDATE public.films SET tmdb_id = 240832, titoli_i18n = '{"it":"Lucy","es":"Lucy","fr":"Lucy","de":"Lucy","en":"Lucy"}'::jsonb, trame_i18n = '{"it":"Lucy è una giovane studentessa che vive a Taipei. Viene costretta a fare da corriere della droga da un cartello coreano. Le viene inserito chirurgicamente nel ventre un pacchetto contenente una nuova droga sintetica, il CPH4. A causa di un pestaggio, il pacchetto si rompe e la sostanza viene assorbita dal suo corpo, permettendole di sbloccare progressivamente le capacità del suo cervello fino al 100%.","es":"Lucy, una joven obligada a ejercer de mula de una nueva y potente droga, adquiere de repente enormes poderes sobrenaturales cuando la bolsa de la droga se rompe y los narcóticos entran en contacto con su cuerpo. Entonces, su cerebro comienza a aumentar la capacidad de uso hasta poder ser utilizado al 100%, convirtiéndose en una máquina letal con habilidades extraordinarias.","fr":"Lucy, une jeune étudiante ordinaire, se fait kidnapper. À son réveil, elle découvre que les membres d’une organisation criminelle lui ont inséré un paquet de drogue dans l’estomac dans le but de lui faire passer la frontière. Mais lorsqu’à la suite d’un coup porté à son ventre le produit se déverse dans son corps et s’implante dans son système, la jeune femme en subit les étonnants effets. Cette substance synthétique lui permet de décupler ses capacités intellectuelles et physiques. Devenue un génie autant qu’une véritable machine de guerre, Lucy dispose désormais de pouvoirs illimités et surhumains…","de":"Die junge Lucy soll eigentlich nur einen harmlos erscheinenden Koffer in einem Hotel abgeben. Bei der Übergabe wird jedoch ihr Freund ermordet und der Inhalt stellt sich als neuartige Droge heraus. Der Empfänger, ein skrupelloser Drogendealer, zwingt sie, ein Paket der Droge in ihrem Körper nach Europa zu transportieren. Doch der Kurierdienst schlägt fehl und die gesamte Drogendosis gerät in Lucys Blutbahn. Wie durch ein Wunder kommt sie dabei nicht ums Leben, stattdessen entwickelt sie ungeahnte Kräfte.","en":"A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/oQIITXMMp9mEckfFst5hySZ8DAz.jpg","es":"https://image.tmdb.org/t/p/w500/uy2TvHFwgKk6UzxxKnPsLkbQwTt.jpg","fr":"https://image.tmdb.org/t/p/w500/hLKoSzjOPC8tQaA2AmFvDjBbKTw.jpg","de":"https://image.tmdb.org/t/p/w500/vbwslYE4LAyMAGSyJch6bXwdn6s.jpg","en":"https://image.tmdb.org/t/p/w500/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg"}'::jsonb WHERE id = 161;
UPDATE public.films SET tmdb_id = 37165, titoli_i18n = '{"es":"El show de Truman","it":"The Truman Show","en":"The Truman Show","de":"Die Truman Show","fr":"The Truman Show"}'::jsonb, trame_i18n = '{"es":"Truman Burbank es un hombre corriente y algo ingenuo que ha vivido toda su vida en uno de esos pueblos donde nunca pasa nada. Sin embargo, de repente, unos extraños sucesos le hacen sospechar que algo anormal está ocurriendo. Todos sus amigos son actores, toda su ciudad es un plató, toda su vida está siendo filmada y emitida como el reality más ambicioso de la historia.","it":"Truman Burbank è un uomo apparentemente comune che vive in una tranquilla cittadina isolana. In realtà, la sua intera vita è uno show televisivo trasmesso in diretta mondiale 24 ore su 24, popolato da attori e scenografie, a sua totale insaputa. Quando inizia a notare delle anomalie, Truman decide di scoprire la verità e fuggire.","en":"In a picture-perfect seaside town, an insurance salesman begins to realize that his entire existence may be staged and observed by a vast unseen audience as part of a long-running real-time reality TV show.","de":"Die Truman Show ist seit beinahe dreißig Jahren ein TV-Klassiker auf der ganzen Welt. Seit seiner Geburt ist Truman Burbank der Hauptdarsteller der Serie – ohne es überhaupt zu wissen. Produzent Christof entwarf eine künstliche Welt, genannt Seahaven, in der Truman von über 5000 Kameras 24 Stunden am Tag bei fast jeder Kleinigkeit beobachtet wird. Um die Fassade nicht zum Einstürzen zu bringen sind seine Frau, Freunde und Verwandte allesamt Schauspieler. In Folge 10909 kommt es jedoch zu diversen versehentlichen Vorfällen die Truman misstrauisch werden lassen. Obwohl Schauspieler und Produzenten alles daran setzen Truman wieder in Zaum zu halten, lässt sich dieser nicht davon abhalten nach Ungereimtheiten zu forschen. Sein Streben nach einer echten Welt wird immer stärker, er plant seinen Ausbruch.","fr":"Il est la vedette d’un show télévisé - mais il ne le sait pas. Jim Carrey a conquis à la fois les critiques et le public pour sa prestation inoubliable dans ce chef-d''œuvre de Peter Weir. Il interprète Truman Burbank, un homme dont la vie entière est un show télévisé - Ses moindres faits et gestes sont filmés à son insu par un créateur/réalisateur/producteur avant-gardiste : la ville entière est un immense studio de cinéma ; ses voisins, ses collègues, ses amis et même sa femme sont des acteurs professionnels d’Hollywood. Un jour pourtant, Truman se doute de quelque chose. Sa réaction face à cette découverte vous fera rire, pleurer et vous émerveillera comme aucun film ne l’a jamais fait."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/8eWVXQZ6yqKfkuHhWD5RcdHnszT.jpg","it":"https://image.tmdb.org/t/p/w500/vniJPHHUpjdVPTSGxn6b3z93nyK.jpg","en":"https://image.tmdb.org/t/p/w500/vuza0WqY239yBXOadKlGwJsZJFE.jpg","de":"https://image.tmdb.org/t/p/w500/7JxsQZbcUZiYhAKeTorrFyFptQv.jpg","fr":"https://image.tmdb.org/t/p/w500/cOkoQaOPZBxqxQYlGu2i0o00sLn.jpg"}'::jsonb WHERE id = 162;
UPDATE public.films SET tmdb_id = 724406, titoli_i18n = '{"it":"Digger","en":"The Gold-digger","de":"Les michetonneuses","es":"Les michetonneuses","fr":"Les michetonneuses"}'::jsonb, trame_i18n = '{"en":"A trio of fashion-loving best friends from the Parisian suburbs dabble in sex work while pursuing freedom and luxury goods in the city of love.","de":"Drei junge Frauen. Eden ist libanesischer Herkunft, Maya ist Gallierin, und beide sind wunderschön. Anissa, die afrikanische Wurzeln hat, beginnt, deutlich an Gewicht zuzulegen.","fr":"Elles sont trois jeunes femmes venues d''horizons différents.  Si Eden et Maya sont superbes. Anissa, souffre d’obésité naissante. La première cesse de « michetonner », la seconde continue, Anissa aurait bien voulu mais ses rondeurs la freinent…  Elles tiennent à leur liberté, rêvent d’amour. Banlieusardes, elles investissent Paris en dépensant ce qu’elles gagnent en produits de luxe. La mode est leur patrie. La vie va chambouler cette situation quand Anissa est arrêtée pour avoir volé un sac de marque…  Une comédie dont les femmes sont les héroïnes.","it":"Nikitas è un padre che vive solitario in una foresta incontaminata nel nord della Grecia, resistendo con tenacia all''espansione di un colosso minerario che minaccia il suo ambiente. La sua isolata routine viene sconvolta dal ritorno improvviso di suo figlio Johnny dopo vent''anni di assenza, intenzionato a reclamare la sua parte di eredità."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kCKJt6q72hWOd6xuGXSzlzdXozc.jpg","en":"https://image.tmdb.org/t/p/w500/rm4UZ9DLXF06npLZMOTNTBNpWhk.jpg","de":"https://image.tmdb.org/t/p/w500/kCKJt6q72hWOd6xuGXSzlzdXozc.jpg","es":"https://image.tmdb.org/t/p/w500/kCKJt6q72hWOd6xuGXSzlzdXozc.jpg","fr":"https://image.tmdb.org/t/p/w500/kCKJt6q72hWOd6xuGXSzlzdXozc.jpg"}'::jsonb WHERE id = 163;
UPDATE public.films SET tmdb_id = 2024, titoli_i18n = '{"fr":"The Patriot : Le Chemin de la liberté","es":"El patriota","en":"The Patriot","it":"Il patriota","de":"Der Patriot"}'::jsonb, trame_i18n = '{"fr":"Caroline du Sud, 1776. Le conflit entre les indépendantistes et les Anglais semble inévitable. Benjamin Martin sait trop bien ce qu''est une guerre et il n''en veut pas. Cet ancien héros des combats contre les français et les indiens n''ignore rien de la violence des affrontements armés... Aujourd''hui veuf, il élève seul ses 7 enfants dans sa plantation. Son fils aîné, Gabriel, s''engage contre l''avis de son père. Lorsque les troupes anglaises, commandées par le colonel Tavington, arrivent aux portes de sa propriété, il est trop tard.","es":"Año 1776, Guerra de Independencia entre los colonos de Nueva Inglaterra y las tropas de Jorge III (1760-1820). En Carolina del Sur, el viudo Benjamin Martin (Mel Gibson), heroico soldado en Francia y en la India, renuncia a combatir para cuidar de sus siete hijos. Pero la pacífica vida de la familia Martin se ve alterada cuando Gabriel (Heath Ledger), el hijo mayor, se alista en el ejército; mientras tanto su padre se esfuerza por sacar adelante a la prole. Sin embargo, los británicos, al mando del cruel coronel Tavington (Jason Isaacs), llegarán hasta las puertas de su casa poniendo en peligro a toda la familia...","en":"After proving himself on the field of battle in the French and Indian War, Benjamin Martin wants nothing more to do with such things, preferring the simple life of a farmer. But when his son Gabriel enlists in the army to defend their new nation, America, against the British, Benjamin reluctantly returns to his old life to protect his son.","it":"Nel 1776, in Carolina del Sud, il veterano di guerra Benjamin Martin decide di non prendere parte alla guerra d''indipendenza americana per accudire i suoi sette figli. Tuttavia, quando un spietato ufficiale britannico uccide uno dei suoi ragazzi e dà alle fiamme la sua casa, Benjamin prende di nuovo le armi guidando una milizia di volontari contro l''esercito inglese.","de":"Ende des 18. Jahrhunderts, South Carolina, USA. Benjamin Martin hat sich zurückgezogen und kümmert sich nach den Tagen als Kriegsheld nur noch um sein Gut und seine Familie. Die Engländer dringen als Kolonialmacht vor und gefährden seinen Besitz, sein ältester Sohn stirbt und sein Haus wird niedergerissen. Martin möchte jedoch nur Frieden, erkennt aber relativ schnell, dass er seine Existenz samt Familie nur dann beschützen kann, wenn er gegen die Engländer zu den Waffen greift..."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/xckzQXDUceZFAWsenLSTLhFlStq.jpg","es":"https://image.tmdb.org/t/p/w500/cizgIaq65fpq2Ft08dPmZtUxDYv.jpg","en":"https://image.tmdb.org/t/p/w500/fWZd815QxUCUcrWQZwUkAp9ljG.jpg","it":"https://image.tmdb.org/t/p/w500/tAS04P7tuhnKA28QskKprmtuLwI.jpg","de":"https://image.tmdb.org/t/p/w500/1iXMmBZ0X98J8JYEeuwxXT0SaPK.jpg"}'::jsonb WHERE id = 164;
UPDATE public.films SET tmdb_id = 1248832, titoli_i18n = '{"it":"Digger","en":"Digger","es":"Digger","de":"Digger","fr":"Digger"}'::jsonb, trame_i18n = '{"it":"Incentrato sulla storia dell''uomo più potente del mondo, il quale intraprende una missione frenetica per dimostrare di essere il salvatore dell''umanità prima che la catastrofe scatenata da lui stesso distrugga ogni cosa.","en":"The most powerful man in the world embarks on a frantic mission to prove he is humanity''s savior before the disaster he''s unleashed destroys everything.","es":"El hombre más poderoso del mundo se embarca en una misión frenética para demostrar que es el salvador de la humanidad antes de que el desastre que ha desencadenado lo destruya todo.","de":"Digger Rockwell, der mächtigste Mann der Welt, begibt sich auf eine verzweifelte Mission, um zu beweisen, dass er der Retter der Menschheit ist, bevor die Katastrophe, die er selbst ausgelöst hat, alles vernichtet.","fr":"L’homme le plus puissant du monde se lance dans une mission frénétique pour prouver qu’il est le sauveur de l’humanité avant que le désastre qu’il a déclenché ne détruise tout."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/wisikjQcsvw0XqyQQYBsxudb38Z.jpg","en":"https://image.tmdb.org/t/p/w500/1ATXKrIPJyKNwnJ6lcG088Sa6zi.jpg","es":"https://image.tmdb.org/t/p/w500/koqE0V2IgIPVy5o2vVkoGJvnB8b.jpg","de":"https://image.tmdb.org/t/p/w500/d8kX0IXh42znJiBGMRb32O9Iq5w.jpg","fr":"https://image.tmdb.org/t/p/w500/gPCCGMQCrrMNM3mR3vqIdbdJxJ5.jpg"}'::jsonb WHERE id = 165;
UPDATE public.films SET tmdb_id = 1645, titoli_i18n = '{"es":"Tiempo de matar","en":"A Time to Kill","fr":"Le Droit de tuer ?","de":"Die Jury","it":"Il momento di uccidere"}'::jsonb, trame_i18n = '{"es":"En una tranquila localidad sureña de Mississippi dos jóvenes borrachos violan salvajemente a una niña negra de diez años. La mayoría blanca de la ciudad se muestra horrorizada ante tan atroz crimen. Carl Lee, el padre de la niña, armado con un rifle de asalto, decide tomarse la justicia por su mano y mata a los violadores de su hija. Mientras la tensión va creciendo y reaparecen en las calles las cruces ardiendo del Ku Klux Klan, Jake Brigance, un joven abogado blanco, hará todo lo posible por salvar la vida de Carl Lee y proteger la suya.","en":"A young lawyer defends a black man accused of murdering two white men who raped his 10-year-old daughter, sparking a rebirth of the KKK.","fr":"Dans une bourgade du Mississippi marquée par les violences racistes, Carl Lee Hailey, après le viol de sa fille de dix ans par deux Blancs, engage un jeune avocat, Jake Brigance. Il lui confie sa crainte de voir l''affaire finir en non-lieu. Quelques heures plus tard, Carl Lee se fait justice en abattant les deux violeurs. Bien décidé à sauver la tête de son client, Jake Brigance va être entrainé dans la terrible spirale de la violence.","de":"In dem kleinen Mississippi-Städtchen Canton wird ein junger Anwalt mit einem mörderischen Fall betraut, als nach der Vergewaltigung und dem Mord an einem farbigen Mädchen der Vater im Gerichtsgebäude Rache nimmt und die vermeintlichen Täter erschießt. Nun steht der Vater vor Gericht und der Klu-Klux-Klan in der Gegend wird ebenfalls wieder aktiv. Unterstützt von einer jungen Studentin gerät das Leben aller Beteiligten in Gefahr, als Anschläge verübt werden. Doch die größte Gefahr lauert vor Gericht, in Person des gewieften Staatsanwalts Buckley","it":"In una cittadina del Mississippi, un operaio afroamericano uccide i due uomini bianchi che hanno brutalmente violentato la sua figlioletta di dieci anni. Un giovane e ambizioso avvocato bianco decide di assumere la sua difesa, affrontando un processo ad altissima tensione razziale che risveglia le violenze del Ku Klux Klan."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/xqRsY5i4vAwk0bWOUToJw1pssp6.jpg","en":"https://image.tmdb.org/t/p/w500/w8UCke112E9jrhjKcwG32kyhTx5.jpg","fr":"https://image.tmdb.org/t/p/w500/re4C9X5a3obaaqikCGpGx9FbCRq.jpg","de":"https://image.tmdb.org/t/p/w500/tBPZl3rWcyzRsmXn6C5wjJzga11.jpg","it":"https://image.tmdb.org/t/p/w500/u8lpYepqSQ9d58GR7K6KS1FEhZn.jpg"}'::jsonb WHERE id = 166;
UPDATE public.films SET tmdb_id = 1317288, titoli_i18n = '{"fr":"Marty Supreme","it":"Marty Supreme","es":"Marty Supreme","de":"Marty Supreme","en":"Marty Supreme"}'::jsonb, trame_i18n = '{"fr":"Marty Mauser, 23 ans, aspire à devenir le meilleur athlète sur la scène mondiale du tennis de table. Le sport est sous-représenté aux États-Unis, ce qui rend difficile le financement de ses compétitions à l''étranger. Il est toutefois prêt à tout pour arriver à ses fins, y compris nouer des liens avec une ancienne actrice et son riche mari entrepreneur. Son entêtement pose un problème pour les personnes de son entourage, qui font souvent les frais de ses choix cavaliers.","it":"Liberamente ispirato alla vita del celebre e non convenzionale giocatore di tennistavolo Marty Reisman, il film racconta le vicende, le scommesse e l''ascesa di un eccentrico campione di ping pong nell''America degli anni Cinquanta.","es":"Biopic de Marty Reisman, un buscavidas convertido en campeón de ping pong, desde que empezó a jugar por apuestas en Manhattan hasta ganar 22 títulos importantes y convertirse en el más veterano en ganar una competición nacional de deportes de raqueta, con 67 años.","de":"Schuhverkäufer Marty hat nur ein Ziel: Weltmeister im Tischtennis zu werden und somit in den Olymp der gefeierten Athleten aufzusteigen, zu denen er sich selbst schon lange zählt. Um an einem Turnier in London teilnehmen zu können, riskiert er alles.","en":"Marty Mauser, a young man with a dream no one respects, goes to hell and back in pursuit of greatness."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/hjrvtc7UCrnsypfnLJuxx9ODKCi.jpg","it":"https://image.tmdb.org/t/p/w500/et9WEOYIel2xTEPL1xwBkifgO2V.jpg","es":"https://image.tmdb.org/t/p/w500/mijSU0Rws3tBBbhdE5udxPSaZvF.jpg","de":"https://image.tmdb.org/t/p/w500/m3Sj2vnS9o1wcHG1fCpUIhz0Y7e.jpg","en":"https://image.tmdb.org/t/p/w500/lYWEXbQgRTR4ZQleSXAgRbxAjvq.jpg"}'::jsonb WHERE id = 167;
UPDATE public.films SET tmdb_id = 6977, titoli_i18n = '{"es":"No es país para viejos","fr":"No Country for Old Men","en":"No Country for Old Men","de":"No Country for Old Men","it":"Non è un paese per vecchi"}'::jsonb, trame_i18n = '{"es":"El veterano de la Guerra de Vietnam ahora cazador Llewellyn Moss descubre por casualidad una sangrienta escena en algún lugar de la frontera entre Texas y México, mientras estaba cazando algunos animales en el árido paisaje. Se trata de un negocio que se cerró mal entre contrabandistas de drogas y algunos hombres locales de la zona, provocando la muerte de varios de ellos. Además de los cuerpos y paquetes de heroína, Llewellyn descubre en una maleta algo más de dos millones de dólares. Cuando Llewellyn toma la maleta con el dinero, provoca una reacción en cadena de catastrófica violencia y una carrera sangrienta de los que quieren darle caza.","fr":"1980, États-Unis, à la frontière qui sépare le Texas du Mexique, les trafiquants mexicains de drogue ont depuis longtemps remplacé les voleurs de bétail. Lorsque Llewelyn Moss découvre dans une plaine des véhicules abandonnés, cernée de cadavres ensanglantés, il ne sait rien de ce qui a conduit à ce drame. Mais il comprend qu''un échange a mal tourné et qu''ils se sont entre-tués. Il recherche un éventuel survivant, le piste et le retrouve mort, au pied d''un arbre avec une valise contenant deux millions de dollars qu''il emporte. Il ne se doute pas de ce que cela va provoquer, mais il se doute que les trafiquants ne vont pas abandonner l''argent. Moss a déclenché une réaction en chaîne que le shérif Ed Tom Bell, un homme proche de la retraite, lucide et clairvoyant, va suivre à la trace…","en":"Llewelyn Moss stumbles upon dead bodies, $2 million and a hoard of heroin in a Texas desert, but methodical killer Anton Chigurh comes looking for it, with local sheriff Ed Tom Bell hot on his trail. The roles of prey and predator blur as the violent pursuit of money and justice collide.","de":"Ein Mann stolpert förmlich über einen blutigen Tatort, einen Pick-up-Truck, vollgeladen mit Heroin, und unwiderstehlichen zwei Millionen Dollar in bar. Seine Entscheidung, das Geld für sich zu behalten, setzt eine gewaltvolle Kettenreaktion in Gang, die noch nicht einmal das Gesetz von West-Texas aufhalten kann.","it":"Nel Texas del 1980, Llewelyn Moss si imbatte nei resti di uno scambio di droga finito male e decide di scappare con una valigetta contenente due milioni di dollari. Sulle sue tracce si mette Anton Chigurh, uno spietato e metodico killer psicopatico armato di un fucile da macello, mentre l''anziano sceriffo Ed Tom Bell cerca disperatamente di salvare Moss e riflette sull''inarrestabile evoluzione della violenza nel mondo moderno."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/x9sQnOXhvec93L6cfWMGIx7BS4h.jpg","fr":"https://image.tmdb.org/t/p/w500/TIIk6p8BziUM5dh8DD048PmcHX.jpg","en":"https://image.tmdb.org/t/p/w500/6d5XOczc226jECq0LIX0siKtgHR.jpg","de":"https://image.tmdb.org/t/p/w500/nVaCwvzqy14tj5mBwzjWPZdDL02.jpg","it":"https://image.tmdb.org/t/p/w500/2zbXKL34bwaZ2gBygwoDE8DXHs7.jpg"}'::jsonb WHERE id = 168;
UPDATE public.films SET tmdb_id = 600, titoli_i18n = '{"de":"Full Metal Jacket","fr":"Full Metal Jacket","it":"Full Metal Jacket","es":"La chaqueta metálica","en":"Full Metal Jacket"}'::jsonb, trame_i18n = '{"de":"South Carolina 1967. Im Camp von Parris Island werden Joker und seine Kameraden auf traditionell-brutale Art zu Marines gedrillt. Der Ausbilder bezahlt seine Profiarbeit mit dem Leben: Leonard, sein Lieblingsopfer, erschießt den Schinder, bevor er sich selbst tötet. An der Dschungelfront in Vietnam, nach der Tet-Offensive, geraten Joker – der inzwischen als Journalist Heldenberichte für die Soldatenzeitung „Stars and Stripes“ schreibt – und seine Kameraden in den Hinterhalt eines Heckenschützen. Die scheinbar einfache Wiedereroberung Huếs gerät zum verlustreichen Desaster. Der Scharfschütze, ein Vietcong-Mädchen, wird von den Soldaten getötet. Und der Wahnsinn geht weiter …","fr":"Pendant la guerre du Vietnam, la préparation et l’entraînement d’un groupe de jeunes marines, jusqu’au terrible baptême du feu et la sanglante offensive du Tết à Hue, en 1968.","it":"Durante la guerra del Vietnam, un gruppo di reclute dei Marines affronta un disumanizzante e brutale addestramento nel campo di Parris Island, sotto la guida dello spietato sergente Hartman. Successivamente, il soldato Joker, diventato giornalista militare, viene inviato al fronte durante l''offensiva del Têt, toccando con mano la follia e la crudeltà del conflitto.","es":"Un grupo de reclutas se prepara en Parish Island, centro de entrenamiento de la marina Norteamericana. Allí está el sargento Hartmann, duro e implacable, cuya única misión en la vida es endurecer el cuerpo y el alma de los novatos, para que puedan defenderse del enemigo. Pero no todos los jóvenes soportan igual sus métodos...","en":"A pragmatic U.S. Marine observes the dehumanizing effects the U.S.-Vietnam War has on his fellow recruits from their brutal boot camp training to the bloody street fighting in Hue."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/hi9TcrQZ6HjFoNMhgnxTM7wF4Gy.jpg","fr":"https://image.tmdb.org/t/p/w500/cShwwkz4gBBIRj8yFy8TP2tEWZ4.jpg","it":"https://image.tmdb.org/t/p/w500/91pR97t391im33z2xnm0nvxUyv9.jpg","es":"https://image.tmdb.org/t/p/w500/6CX7BcyD8Xd5AQ7myNs0UE4mu6c.jpg","en":"https://image.tmdb.org/t/p/w500/kMKyx1k8hWWscYFnPbnxxN4Eqo4.jpg"}'::jsonb WHERE id = 169;
UPDATE public.films SET tmdb_id = 602, titoli_i18n = '{"de":"Independence Day","fr":"Independence Day","en":"Independence Day","es":"Independence Day","it":"Independence Day"}'::jsonb, trame_i18n = '{"de":"Eine gewaltige außerirdische Armee bedroht die Existenz der Erde. Die Invasion beginnt mit dem Auftauchen gigantischer Raumschiffe, die sich über den wichtigsten Zentren der Welt positionieren. Die bedrohliche Faszination schlägt schnell in unvorstellbare Panik um, als die Raumschiffe angreifen und bedingungslos zerstören. Nun liegt das Schicksal der Menschheit in den Händen der wenigen Überlebenden, die sich für den alles entscheidenden Kampf gegen die Invasoren bereit machen…","fr":"Une immense soucoupe volante envahit le ciel terrestre, libérant un nombre infini de plus petites soucoupes qui prennent position au-dessus des plus grandes villes du monde. Un informaticien new-yorkais décrypte les signaux émanant des étranges voyageurs. Ils ne sont pas du tout amicaux et ces extraterrestres se préparent à attaquer la Terre.","en":"Strange phenomena surface around the globe. The skies ignite. Terror races through the world''s major cities. As these extraordinary events unfold, it becomes increasingly clear that a force of incredible magnitude has arrived. Its mission: total annihilation over the Fourth of July weekend. The last hope to stop the destruction is an unlikely group of people united by fate and unimaginable circumstances.","es":"En víspera del 4 de julio, unas gigantescas naves espaciales aparecen en el cielo. El estupor inicial se convierte en terror al ver cómo éstas atacan al planeta lanzando rayos destructivos en las mayores ciudades de todo el mundo. Ahora la única esperanza para la salvación de la tierra está en la voluntad de algunos supervivientes, que se unen planeando el último ataque masivo contra los alienígenas, antes de que sea demasiado tarde para la humanidad.","it":"Alla vigilia del 4 luglio, enormi astronavi alieni posizionano sopra le principali metropoli della Terra e scatenano un attacco devastante. Un gruppo di sopravvissuti, tra cui un pilota di caccia della Marina e uno scienziato esperto in telecomunicazioni, elabora un piano disperato per sconfiggere gli invasori e salvare l''umanità dall''estinzione."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/xCTFGyQksFAvcmUMCc2hZG4hmdr.jpg","fr":"https://image.tmdb.org/t/p/w500/bkCauryW2TOWaEkGqyJMuJ0pRUV.jpg","en":"https://image.tmdb.org/t/p/w500/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg","es":"https://image.tmdb.org/t/p/w500/zhYisFUKLhlrbcrABMxQRzwuAM5.jpg","it":"https://image.tmdb.org/t/p/w500/dXaARuPnIVEQWM8TkPSJ8LBpc16.jpg"}'::jsonb WHERE id = 170;
UPDATE public.films SET tmdb_id = 565179, titoli_i18n = '{"it":"Il primo re","en":"The First King","es":"El primer rey","fr":"Romulus et Rémus","de":"The First King - Romulus & Remus"}'::jsonb, trame_i18n = '{"it":"Nell''VIII secolo a.C., i fratelli pastori Romolo e Remo vengono travolti dall''esondazione del Tevere e fatti prigionieri dagli abitanti di Alba Longa. Riusciti a fuggire guidando una rivolta insieme ad altri prigionieri, i due intraprendono un viaggio guidati da Remo, che sfida la volontà degli dei finendo per scontrarsi tragicamente con Romolo, destinato a fondare la città di Roma.","en":"Romulus and Remus, two shepherds and loyal brothers, end up taking part to a journey that will lead one of them to be the founder of the greatest nation ever seen. However, the fate of the chosen one will pass from killing his own brother.","es":"Rómulo y Remo son dos hermanos pastores de 18 años que viven cerca del río Tíber. Convencido de que él es más importante que los deseos de Dios, Remus cree que está destinado a ser rey de la ciudad que encontrará junto a su hermano. Pero su trágico destino ya está escrito. Este increíble viaje llevará a los dos hermanos a crear uno de los más grandes imperios que el mundo haya visto jamás.","fr":"L''histoire des jumeaux Remus et Romulus, fondateurs légendaires de Rome.","de":"Die Brüder Romulus und Remus führen ein einfaches und friedliches Leben als Schafhirten an den Ufern des Tibers, bis ihnen die Götter eines Tages nicht mehr gewogen zu sein scheinen. Die Geschwister werden von einer riesigen Flutwelle überrascht und von der Strömung mitgerissen. Fernab ihrer Heimat gelingt es den geschwächten Männern sich an Land zu retten, wo sie jedoch von Kriegern der Stadt Alba Longa aufgegriffen und als Gladiatoren versklavt werden. Doch den Brüdern gelingt es, sich und ihre Mitgefangenen zu befreien. Auf der Flucht vor ihren Verfolgern beschließen Romulus und Remus, getrieben von der Hoffnung auf Freiheit, eine neue und sichere Stadt zu errichten. Aber nur einem der Brüder ist die Herrschaft über das neue Reich bestimmt, das als eines der größten Imperien in die Geschichte eingehen wird."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/mdM3dLbzF7bVhYTRQCPQiltP4vQ.jpg","en":"https://image.tmdb.org/t/p/w500/dqBU63M3cKy7pfVsmhrbgY5X8iv.jpg","es":"https://image.tmdb.org/t/p/w500/juxZxz0KoUfk8TApxJoLHcPR9dx.jpg","fr":"https://image.tmdb.org/t/p/w500/jJCsHiR4R9ioYqoPOk2ZJkAFpwt.jpg","de":"https://image.tmdb.org/t/p/w500/mdM3dLbzF7bVhYTRQCPQiltP4vQ.jpg"}'::jsonb WHERE id = 174;
UPDATE public.films SET tmdb_id = 117, titoli_i18n = '{"de":"The Untouchables - Die Unbestechlichen","fr":"Les Incorruptibles","it":"The Untouchables - Gli intoccabili","es":"Los intocables de Eliot Ness","en":"The Untouchables"}'::jsonb, trame_i18n = '{"de":"Im Chicago der 1930er Jahre macht die Mafia um den Gangsterboss Alfred ''Al'' Capone während der Prohibition florierende Umsätze mit illegalem Alkohol. Die korrupte Polizei deckt ihn dabei. Eliot Ness, Beamter des Finanzamts, stellt eine kleine Truppe unbestechlicher Mitstreiter zusammen. Besonders der ausgefuchste Polizist Malone hilft dem unerfahrenen Eliot, Al Capone in einem ausgeklügelten Feldzug hinter Gitter zu bringen.","fr":"À Chicago en 1930, à l’époque de la prohibition, le trafic d’alcool bat son plein et permet à des truands de bâtir des fortunes colossales. Eliot Ness, jeune policier frais émoulu du FBI, est chargé de démanteler un réseau de contrebande d’alcool. L’ennemi est facilement identifiable : Al Capone, inattaquable officiellement, est pourtant impliqué dans les affaires les plus sordides. La première mission de Ness, maladroitement conduite, se solde par un échec humiliant. Loin de se laisser décourager par ce premier affront, Ness décide de s’entourer de personnes de confiance. Il recrute ainsi Jim Malone, un flic qui connaît bien le monde des truands…","it":"Durante il periodo del proibizionismo a Chicago, l''agente federale Eliot Ness crea una squadra speciale di uomini incorruttibili per fermare l''impero criminale del celebre boss mafioso Al Capone.","es":"El joven agente del tesoro Elliot Ness llega a Chicago con la determinación de detener a Al Capone. No va a ser tarea fácil, puesto que Capone tiene a la policía en el bolsillo. Ness conoce a Jimmy Malone, un guardia veterano y probablemente el más honrado de todo el cuerpo, al que Ness pide ayuda en su cruzada contra Capone.","en":"Elliot Ness, an ambitious prohibition agent, is determined to take down Al Capone. In order to achieve this goal, he forms a group given the nickname “The Untouchables”."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/tNusbeamCBBAbI9720FDzUrCtt2.jpg","fr":"https://image.tmdb.org/t/p/w500/xrdMy48NrJSJYRplKfuQT0sDfSI.jpg","it":"https://image.tmdb.org/t/p/w500/s2FtPcKNwfSQ2cHfv5p0mDjVttk.jpg","es":"https://image.tmdb.org/t/p/w500/pVcWaUbFDL76ObIsReIBQ5ILMHv.jpg","en":"https://image.tmdb.org/t/p/w500/tPq0R4jTO4Ey8ZspFaWK9wGA4Ls.jpg"}'::jsonb WHERE id = 176;
UPDATE public.films SET tmdb_id = 244, titoli_i18n = '{"en":"King Kong","de":"King Kong und die weiße Frau","it":"King Kong (King Kong)","fr":"King Kong","es":"King Kong"}'::jsonb, trame_i18n = '{"en":"Adventurous filmmaker Carl Denham sets out to produce a motion picture unlike anything the world has seen before. Alongside his leading lady Ann Darrow and his first mate Jack Driscoll, they arrive on an island and discover a legendary creature said to be neither beast nor man. Denham captures the monster to be displayed on Broadway as King Kong, the eighth wonder of the world.","de":"Ein amerikanisches Filmteam und die Diva Ann Darrow reisen zu Dreharbeiten auf eine Dschungel-Insel. Die Insel ist das Reich unzähliger Urwelttiere und der Riesenaffe King Kong wird von den Eingeborenen als Gottheit verehrt. Von Zeit zu Zeit bringen sie ihm Menschenopfer dar. Eines Nachts wird die schöne Ann entführt und von den Wilden zur Opferstätte gebracht. Der Affenkönig verschleppt sie in den Dschungel.","it":"Una troupe cinematografica si avventura su una misteriosa isola sconosciuta, Skull Island, dove scopre un gorilla gigante venerato come un dio dai nativi. La creatura si invaghisce dell''attrice Ann Darrow, ma viene catturata e portata a New York per essere esibita al pubblico.","fr":"Figurante sans travail, la blonde Ann Darrow est engagée par le réalisateur Carl Denham pour être la vedette de son prochain film. Le Venture, le navire commandé par le capitaine Englehorn et qui comprend toute l''équipe, atteint Skull Island, une île mystérieuse où vivrait une créature légendaire vénérée par les indigènes et appelée King Kong.Durant le voyage, Ann tombe amoureuse de John Driscoll, le second du bateau. Une fois débarqués, les explorateurs sont aussitôt repérés par les indigènes et font marche arrière. Mais ces derniers enlèvent Ann, la \"femme aux cheveux d''or\", et l''attachent pour l''offrir en sacrifice à King Kong.Au moment où ses compagnons arrivent pour la délivrer, un singe gigantesque saisit la jeune fille et disparaît dans la forêt. Denham et ses hommes se lancent alors à la poursuite de King Kong.","es":"Un equipo de cine va a rodar una película a la misteriosa isla de Teschio, al este de Sumatra. Allí descubren la existencia de una civilización prehistórica y de una tribu ancestral que secuestra a la atractiva Ann, la actriz protagonista, para ofrecerla en sacrificio ritual a King, un gigantesco gorila."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/lHlnxKL5GbgRibyRFI7n1Ey850i.jpg","de":"https://image.tmdb.org/t/p/w500/jr9kq0PdUmlv4AdooLvWmm7Oys0.jpg","it":"https://image.tmdb.org/t/p/w500/lHlnxKL5GbgRibyRFI7n1Ey850i.jpg","fr":"https://image.tmdb.org/t/p/w500/pFStqHTVUceciD9vineiNJ9WHpA.jpg","es":"https://image.tmdb.org/t/p/w500/wlRhyQOC67Q9dxqd2Fpsh64kFHh.jpg"}'::jsonb WHERE id = 178;
UPDATE public.films SET tmdb_id = 10730, titoli_i18n = '{"it":"King Kong (King Kong)","en":"King Kong","fr":"King Kong","de":"King Kong","es":"King Kong"}'::jsonb, trame_i18n = '{"it":"Una compagnia petrolifera organizza una spedizione su un''isola perennemente avvolta dalla nebbia. Qui trovano una gigantesca creatura antropomorfa che si invaghisce di una naufraga. Il gorilla viene catturato per scopi pubblicitari e portato nella metropoli di New York.","en":"An oil company expedition disturbs the peace of a giant ape and brings him back to New York to exploit him.","fr":"Fred Wilson dirige une expédition destinée à trouver de nouveaux gisements de pétrole sur une île inconnue. Jack Prescott, jeune savant qui veut percer les mystères de l''île du Crane et Dwan, une cover-girl recueillie en mer, se joignent à la petite troupe.","de":"Fred Wilson Angestellter eines großen amerikanischen Öl-Konzerns, hat den Auftrag, neue Erdölquellen ausfindig zu machen. Mit einem gecharterten Boot macht er sich auf die Reise zu einer noch unbewohnten Insel. Mit an Bord ist auch ein blinder Passagier: Der Anthropologe Jack Prescott  schmuggelte sich auf das Schiff, denn er will auf dieser Insel eine seltene Affenart untersuchen. Unterwegs nehmen sie noch die hübsche Dawn  mit an Bord, die sie in einem Rettungsboot auflesen. Als das Schiff vor der Insel vor Anker geht, stellt sich jedoch heraus, dass diese doch nicht so unbewohnt ist, wie allseits angenommen. Die dort lebenden Eingeborenen führen gerade ein merkwürdiges Ritual auf, um einem überlebensgroßen Affen namens ''Kong'' zu huldigen. Als sie die blonde Dawn erblicken, haben sie ihr ''Opfer'' gefunden...","es":"La \"Petrox Company\" envía una expedición, dirigida por Fred Wilson, a la Micronesia con la intención de encontrar petróleo. Con ellos va Jack Prescott, cuyo objetivo es encontrar un monstruo prehistórico. Durante la travesía, se encuentran un bote con una mujer que se ha salvado del naufragio del barco en que viajaba con un productor de cine. Cuando desembarcan, descubren una gran empalizada, y dentro observan que unos nativos colocan a una mujer nativa en una plataforma, mientras invocan a una misteriosa deidad animal."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/6iSU6sfjQ2fT0wcL3AqruXErVw1.jpg","en":"https://image.tmdb.org/t/p/w500/paYKhEwUaxKA05vmOfU7FlleTln.jpg","fr":"https://image.tmdb.org/t/p/w500/sjVMeRoobHilaw0BIWlL9ccuvUy.jpg","de":"https://image.tmdb.org/t/p/w500/xzRTGHQlve8ezLwBIbZKjrXMuai.jpg","es":"https://image.tmdb.org/t/p/w500/5uNO9Ip3RE9JyaBKjAxEhut9DIV.jpg"}'::jsonb WHERE id = 179;
UPDATE public.films SET tmdb_id = 254, titoli_i18n = '{"es":"King Kong","fr":"King Kong","en":"King Kong","de":"King Kong","it":"King Kong (King Kong)"}'::jsonb, trame_i18n = '{"es":"La suerte de Ann Darrow cambia cuando conoce a Carl Denham, un empresario que lucha para abrirse camino en el mundo del espectáculo. A ellos se une Jack Driscoll, un autor de teatro neoyorquino. Los tres emprenden un viaje que los llevará hasta una remota isla, donde Denham tiene previsto dirigir una película. Allí descubren un ser increíble, un gorila gigante, King Kong, que habita en una frondosa selva, donde criaturas prehistóricas han vivido ocultas durante millones de años. Denham, con un apetito insaciable de grandeza, enseguida ve la fama que puede reportarle la captura del gorila y su exhibición en Nueva York.","fr":"Carl Denham, un cinéaste en quête de notoriété, prépare un tournage dans les mers du Sud. Il embarque avec toute son équipe à bord du «Venture». Bien que les acteurs soient persuadés de tourner un film d''amour et d''aventures, le réalisateur espère secrètement que le voyage les conduira à Skull Island (l''île du Crâne), une terre inexplorée où, dit-on, les indigènes adorent une créature mystérieuse et terrifiante. Les foules, pense-t-il, se presseront pour découvrir les images qu''il rapportera de son voyage. Ann Darrow, artiste de music-hall au chômage, a été embauchée au dernier moment pour pallier la défection de l''actrice principale.","en":"In 1933 New York, an overly ambitious movie producer coerces his cast and hired ship crew to travel to mysterious Skull Island, where they encounter Kong, a giant ape who is immediately smitten with the leading lady.","de":"Amerika in den 30er Jahren: Für seinen neuen Film will der Regisseur Carl Denham eine ganz besondere Kulisse haben. Diese hat er auch schon in einer abgelegenen Insel, \"Skull Island\", im Gegensatz zu der weiblichen Hauptrolle gefunden. Erst kurz vor der Abreise findet sie sich in der schönen Ann Darrow, die sofort auf das Angebot einsteigt und mitreist. Keiner des Filmteams, nicht mal Denham, war bisher auf der Insel und schnell müssen sie dort feststellen, dass es ein Fehler war, sie dafür auszuwählen. Denn auf ihr lebt ein Eingeborenenstamm, der einen riesigen Gorilla, \"King Kong\", anbetet und ihm von Zeit zu Zeit Menschen opfert. Die Eingeborenen sind so von Ann beeindruckt, dass sie das nächste Opfer sein soll...","it":"Nel 1933, un regista di spettacoli sull''orlo del fallimento convince una troupe e una giovane attrice a salpare verso l''esotica e pericolosa Isola del Teschio. Lì si scontreranno con creature preistoriche e con King Kong, un gorilla gigantesco che svilupperà un profondo legame con la donna."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/tSfZ6LoZgnz8BOrSQVo24vqv4nW.jpg","fr":"https://image.tmdb.org/t/p/w500/pSmIr47IDD72IboEi8SZztN0cR7.jpg","en":"https://image.tmdb.org/t/p/w500/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg","de":"https://image.tmdb.org/t/p/w500/y68X15hwEJTW2PaJkl5rrJpnHyt.jpg","it":"https://image.tmdb.org/t/p/w500/3YoB2B7JMn8mJ8IsZDn80Zuyocq.jpg"}'::jsonb WHERE id = 180;
UPDATE public.films SET tmdb_id = 1362, titoli_i18n = '{"es":"El Hobbit","fr":"Bilbo le hobbit","it":"Lo Hobbit (The Hobbit)","de":"The Hobbit","en":"The Hobbit"}'::jsonb, trame_i18n = '{"es":"Adaptación de la novela \"El Hobbit\". Es además la primera parte de la trilogía animada basada en la obra de Tolkien, formada por El Hobbit (Jules Bass, 1977), El señor de los anillos (Ralph Bakshi, 1978) y El retorno del Rey (Jules Bass, 1980).","fr":"L''histoire de Bilbon Sacquet, hobbit paisible de la Comté, entrainé malgré lui dans une formidable aventure. Accompagné du magicien Gandalf et de treize nains, il devra récupérer un trésor dérobé par le terrible dragon Smaug...Adapté du roman de J.R.R. Tolkien \"Bilbo le hobbit ou l''Histoire d''un aller et retour\" (\"The Hobbit: There and back again\").","it":"Un pacifico hobbit di nome Bilbo Baggins viene reclutato dal mago Gandalf e da una compagnia di nani per recuperare un tesoro custodito dal drago Smaug.","de":"Im idyllischen, im Westen des fiktiven Kontinents Mittelerde gelegenen Auenland wohnt das Volk der kleinen, gemütlichen, friedfertigen, menschenähnlichen Hobbits. Als eines Tages der Zauberer Gandalf auftaucht und in seinem Gefolge 13 Zwerge in der Wohnhöhle des Hobbits Bilbo Beutlin einkehren, stellt sich die bisher wohlgeordnete Welt für den Hobbit auf den Kopf. Weil ihn selbst kurz die Abenteuerlust packt, sieht er sich plötzlich zum Meisterdieb ernannt: Er soll den Zwergen helfen, ihren von dem Drachen Smaug gestohlenen Schatz wieder zurückzugewinnen. Als Bezahlung soll er ein 14tel des Schatzes erhalten. Nicht nur, dass für Hobbits die Existenz von Drachen fraglich erscheint und Abenteuer von ihnen verabscheut werden: Der Berg Erebor, in dem der Drache mit dem gestohlenen Schatz lebt, befindet sich noch dazu in einem weit entfernten Land im Osten von Mittelerde.","en":"The story follows the adventures of Bilbo Baggins, a diminutive creative who resides in a place called Middle-Earth before he is compelled to go on a quest to find a treasure buried deep in the heart of the Lonely Mountain."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/jDSUPyCbyJbFEyysXVSowHhRQWl.jpg","fr":"https://image.tmdb.org/t/p/w500/2ohvyMPhvjftLrM6S6Ljr6QrL0u.jpg","it":"https://image.tmdb.org/t/p/w500/qTU84nwRmfBnukCdjoJaXZwD4qw.jpg","de":"https://image.tmdb.org/t/p/w500/oIBShv7BS22r2DIXUG0G3EVCVIK.jpg","en":"https://image.tmdb.org/t/p/w500/2ohvyMPhvjftLrM6S6Ljr6QrL0u.jpg"}'::jsonb WHERE id = 181;
UPDATE public.films SET tmdb_id = 49051, titoli_i18n = '{"es":"El hobbit: Un viaje inesperado","fr":"Le Hobbit : Un voyage inattendu","en":"The Hobbit: An Unexpected Journey","de":"Der Hobbit - Eine unerwartete Reise","it":"Lo Hobbit - Un viaggio inaspettato (The Hobbit: An Unexpected Journey)"}'::jsonb, trame_i18n = '{"es":"Precuela de la trilogía \"El Señor de los Anillos\", obra de J.R.R. Tolkien. En compañía del mago Gandalf y de trece enanos, el hobbit Bilbo Bolsón emprende un viaje a través del país de los elfos y los bosques de los trolls, desde las mazmorras de los orcos hasta la Montaña Solitaria, donde el dragón Smaug esconde el tesoro de los Enanos. Finalmente, en las profundidades de la Tierra, encuentra el Anillo Único, hipnótico objeto que será posteriormente causa de tantas sangrientas batallas en la Tierra Media.","fr":"Dans un voyage inattendu, Bilbon Sacquet cherche à reprendre le Royaume perdu des Nains d''Erebor, conquis par le redoutable dragon Smaug. Alors qu''il croise par hasard la route du magicien Gandalf le Gris, Bilbon rejoint une bande de 13 nains dont le chef n''est autre que le légendaire guerrier Thorin Écu-de-Chêne. Leur périple les conduit au cœur du Pays Sauvage, où ils devront affronter des Gobelins, des Orques, des Ouargues meurtriers, des Araignées géantes, des Métamorphes et des Sorciers… Bien qu''ils se destinent à mettre le cap sur l''Est et les terres désertiques du Mont Solitaire, ils doivent d''abord échapper aux tunnels des Gobelins, où Bilbon rencontre la créature qui changera à jamais le cours de sa vie : Gollum.","en":"Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.","de":"Mit dem Besuch des weisen Zauberers Gandalf verändert sich das beschauliche Leben eines Hobbits für immer. Zögerlich schließt sich der unbedarfte Bilbo mit Gandalf der Mission von 13 mutigen Zwergen an, die ihr Reich zurückerobern wollen. Der furchterregende Drache Smaug, der es einst zerstörte, ist seit Jahrzehnten verschwunden. Doch ist das Monstrum wirklich tot und können die großen Gefahren dieses Abenteuers, darunter gefräßige Orks und wütende Trolle, wirklich von so kleinen Helden überwunden werden?","it":"Bilbo Baggins viene convinto dal mago Gandalf a unirsi a tredici nani guidati da Thorin Scudodiquercia in un''epica impresa per riconquistare il regno perduto di Erebor dal drago Smaug."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/1id2xLxg750ojOWvGWeqPIxmOIF.jpg","fr":"https://image.tmdb.org/t/p/w500/mdy9mG31U7jSB8edfRELv53Yfjp.jpg","en":"https://image.tmdb.org/t/p/w500/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg","de":"https://image.tmdb.org/t/p/w500/bPYCAzOB3M3PZ91BpQzJeReKkP8.jpg","it":"https://image.tmdb.org/t/p/w500/uoMnJrqlUmEc9etXvD2swUr1Tvu.jpg"}'::jsonb WHERE id = 182;
UPDATE public.films SET tmdb_id = 57158, titoli_i18n = '{"fr":"Le Hobbit : La Désolation de Smaug","it":"Lo Hobbit - La desolazione di Smaug (The Hobbit: The Desolation of Smaug)","es":"El hobbit: La desolación de Smaug","en":"The Hobbit: The Desolation of Smaug","de":"Der Hobbit - Smaugs Einöde"}'::jsonb, trame_i18n = '{"fr":"Bilbon Sacquet est entraîné dans une quête épique pour reconquérir le Royaume perdu des Nains d''Erebor et l''arracher aux griffes de l''effroyable dragon Smaug. Accompagné de 13 Nains et du Magicien Gandalf le Gris, Bilbon s''introduit dans la Montagne Solitaire armé du ''précieux'' anneau de Gollum et de Dard, sa lame affûtée.","it":"Bilbo Baggins e la compagnia di nani proseguono il loro viaggio verso la Montagna Solitaria, affrontando pericoli come ragni giganti, elfi silvani e infine il temibile drago Smaug.","es":"Tras sobrevivir al inicio de su inesperado viaje, la Compañía sigue hacia el este y se encuentra por el camino con Beorn, el cambiador de piel, y con un enjambre de Arañas gigantes en el peligroso monte Mirkwood. Tras evitar que los Elfos del Bosque los capturen, los Enanos prosiguen su viaje hacia Ciudad del Lago, y finalmente llegan a la Montaña Solitaria, donde tienen que enfrentarse al mayor de los peligros, una criatura más terrorífica que cualquier otra que pondrá a prueba no solo lo profundo de su valentía sino también los límites de su amistad y la sabiduría del viaje: el dragón Smaug.","en":"The Dwarves, Bilbo and Gandalf have successfully escaped the Misty Mountains, and Bilbo has gained the One Ring. They all continue their journey to get their gold back from the Dragon, Smaug.","de":"Die Gefährten haben den Beginn ihrer unerwarteten Reise überstanden – auf ihrem Weg gen Osten begegnen sie nun dem Hautwechsler Beorn und im trügerischen Düsterwald einem Schwarm gigantischer Spinnen. Sie werden von den gefährlichen Waldelben gefangen genommen, können aber entkommen, erreichen Seestadt und schließlich den Einsamen Berg selbst, wo sie sich der größten Gefahr stellen müssen – einem Monster, das alle bisherigen an Grässlichkeit übertrifft: Der Drache Smaug fordert nicht nur den ganzen Mut der Gefährten heraus, sondern stellt auch ihre Freundschaft auf eine harte Probe – bis sie sich schließlich fragen müssen, ob ihre Reise überhaupt noch einen Sinn ergibt."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/9JPVtscMdWGmOoWxNmc1hGdkxtM.jpg","it":"https://image.tmdb.org/t/p/w500/8AG3NTGNQ4613o7XB8NUFSNW28W.jpg","es":"https://image.tmdb.org/t/p/w500/1s8xZDmG5IkDU0m1LeW28YcwTRx.jpg","en":"https://image.tmdb.org/t/p/w500/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg","de":"https://image.tmdb.org/t/p/w500/60O2sdzZcPX8vXyDOYHi7exrnil.jpg"}'::jsonb WHERE id = 183;
UPDATE public.films SET tmdb_id = 122917, titoli_i18n = '{"en":"The Hobbit: The Battle of the Five Armies","fr":"Le Hobbit : La Bataille des cinq armées","it":"Lo Hobbit - La battaglia delle cinque armate (The Hobbit: The Battle of the Five Armies)","es":"El hobbit: La batalla de los cinco ejércitos","de":"Der Hobbit - Die Schlacht der fünf Heere"}'::jsonb, trame_i18n = '{"en":"Following Smaug''s attack on Laketown, Bilbo and the dwarves try to defend Erebor''s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo''s hands.","fr":"Atteignant enfin la Montagne Solitaire, Thorin et les Nains, aidés par Bilbon le Hobbit, ont réussi à récupérer leur royaume et leur trésor. Ils ont également réveillé le dragon Smaug qui déchaîne désormais sa colère sur les habitants de Lac-ville. À présent, les Nains, les Elfes, les Humains mais aussi les Wrags et les Orques menés par le Nécromancien, convoitent les richesses de la Montagne Solitaire.","it":"Mentre Smaug scatena la sua ira su Pontelagolungo, nani, elfi, umani e orchi si scontrano in una titanica battaglia ai piedi della Montagna Solitaria per il controllo del tesoro di Erebor.","es":"Después de haber recuperado el reino del Dragón Smaug, la Compañía ha desencadenado, sin querer, una potencia maligna. Un Smaug enfurecido vuela hacia la Ciudad del Lago para acabar con cualquier resto de vida. Obsesionado sobre todo con el reino recuperado, Thorin sacrifica la amistad y el honor para mantenerlo mientras que Bilbo intenta frenéticamente hacerle ver la razón por la que el hobbit toma una decisión desesperada y peligrosa. Pero hay aún mayores peligros por delante. Sin la ayuda aparente del mago Gandalf, su gran enemigo Sauron ha enviado legiones de orcos hacia la Montaña Solitaria en un ataque furtivo. Cuando la oscuridad se cierna sobre ellos, las razas de los Enanos, Elfos y Hombres deben decidir si unirse o ser destruidos. Bilbo se encontrará así en la batalla épica de los Cinco Ejércitos, donde el futuro de la Tierra Media está en juego.","de":"Nachdem Smaug besiegt wurde, sitzt Thorin endlich auf dem Zwergenthron und hat sein Reich wieder. Doch der Kampf gegen den Drachen hat Spuren hinterlassen. Die Stadt Esgaroth wurde zerstört, ihre Bewohner sind nun obdachlos. Doch Thorin verweigert jede Hilfe genauso wie die Rückgabe von Teilen des Schatzes, die Smaug gestohlen hatte. Hobbit Bilbo versucht zwischen Zwergen, Elben und den Bürgern zu vermitteln, doch vergeblich. Thorin hält ihn für einen Verräter und auch Gandalf kann nichts mehr ausrichten. Es wird aufgerüstet und bald stehen sich die Armeen gegenüber…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/xT98tLqatZPQApyRmlPL12LtiWp.jpg","fr":"https://image.tmdb.org/t/p/w500/h4wjbuC61iMaCqrO3bmGQ3ibuJE.jpg","it":"https://image.tmdb.org/t/p/w500/A2RkCwo2gcWX6OXL2B46eOU7Wv6.jpg","es":"https://image.tmdb.org/t/p/w500/6OiNSLcRKJsBLXwb6DEi6IQ0JFk.jpg","de":"https://image.tmdb.org/t/p/w500/mNZ4MxL0KdW9VBMXSAhiiGFDYaa.jpg"}'::jsonb WHERE id = 184;
UPDATE public.films SET tmdb_id = 3589, titoli_i18n = '{"en":"It Happened Tomorrow","fr":"C''est arrivé demain","es":"Sucedió mañana","de":"Was morgen geschah","it":"Avvenne domani (It Happened Tomorrow)"}'::jsonb, trame_i18n = '{"en":"A young turn-of-the-century newspaper man finds he can get hold of the next day''s paper. This brings more problems than fortune, especially as his new girlfriend is part of a phony clairvoyant act.","fr":"Larry Stevens, journaliste à l''Evening News, rencontre par hasard un journaliste retraité qui lui remet un journal, il découvre avec stupéfaction qu''il s''agit d''un journal prémonitoire : daté du lendemain et annonçant des événements à venir...","es":"Larry Stevens trabaja como reportero del Evening News de Nueva York y está a punto de celebrar sus bodas de oro con su esposa Sylvia y toda su familia. Durante la fiesta, cuenta un extraño hecho que le sucedió a fines del siglo XIX, cuando el viejo Benson, el encargado de la hemeroteca del periódico, al que apenas conocía, le entregó un ejemplar del Evening News que vaticinaba con un día de antelación las noticias que iban a producirse","de":"Ein junger Reporter kommt dreimal in den Besitz einer Zeitung vom nächsten Tag und weiß dadurch die Neuigkeiten von morgen schon heute. Seine sensationellen Berichte machen ihn stadtbekannt, da liest er auf der Titelseite die Nachricht von seinem eigenen Tod.","it":"Un giovane giornalista riceve da un anziano archivista defunto copie del giornale del giorno successivo. Grazie a questa straordinaria opportunità, riesce a realizzare scoop sensazionali, ma le cose si complicano quando legge la notizia della propria morte imminente."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/byWjI8SYnATh0OdnaCCKhO9nY0R.jpg","fr":"https://image.tmdb.org/t/p/w500/wquWfiCLZqKoWR9s6tpyCkmrGKJ.jpg","es":"https://image.tmdb.org/t/p/w500/gkaZb6YyihQKX9NSSDV5hUFgHJK.jpg","de":"https://image.tmdb.org/t/p/w500/iIQ3CSZT2d84S6fZY2MPuvcKVwT.jpg","it":"https://image.tmdb.org/t/p/w500/hWKQ54scA6qCU6Wtl3euUJJCKAq.jpg"}'::jsonb WHERE id = 185;
UPDATE public.films SET tmdb_id = 11352, titoli_i18n = '{"es":"Always (Para Siempre)","it":"Always - Per sempre (Always)","de":"Always - Der Feuerengel von Montana","en":"Always","fr":"Always"}'::jsonb, trame_i18n = '{"es":"Pete Sandich, un temerario piloto que se dedica a la extinción de incendios, muere en acto de servicio tras salvarle la vida a un amigo. En el cielo, se encuentra con un ángel femenino que lo conmina a regresar a la Tierra para proteger la vida y convertir en un experto piloto al novato Ted Baker. El único problema es que Ted está enamorado de la antigua novia de Pete.","it":"Un audace pilota di aerei antincendio muore in un incidente di volo, ma ritorna sulla Terra sotto forma di spirito guida per aiutare un giovane pilota alle prime armi e vegliare sulla donna che amava, faticando ad accettare che lei debba rifarsi una vita senza di lui.","de":"Pete Sandich ist ein legendärer Pilot mit einer Leidenschaft für waghalsige Löscheinsätze aus der Luft. Dorinda, der Frau seines Herzens, und seinem besten Freund Al ist aber längst schmerzlich bewusst, dass auch Legenden nicht ewig auf Risiko fliegen können. Als Sandich bei einem Einsatz sein Leben gibt, um Al zu retten, steht das Fliegerass plötzlich vor seiner größten Herausforderung: Pete muss Dorinda helfen, ins Leben zurückzukehren.","en":"The spirit of a recently deceased expert pilot mentors a newer pilot while watching him fall in love with the girlfriend that he left behind.","fr":"Pete Sandich est l’as des “Pompiers volants” du Montana. Casse-cou invétéré malgré son amour pour son amie Dorida et son amitié pour son complice de toujours, Al, l’heure de l’ultime vol arrive… Cinq mois plus tard, Pete se réveille dans une forêt carbonisée. Une femme lui sourit et lui ordonne de regagner la Terre et d’insuffler sa “Divine inspiration” à ceux qu’il aime."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/eKl56eFm2ZI0TYST1Ld82IZrOVD.jpg","it":"https://image.tmdb.org/t/p/w500/gV89aOidilmkQBa75HVEZwRMp1W.jpg","de":"https://image.tmdb.org/t/p/w500/z5lYFt4Qi9W3EtZAMkD032t2VSh.jpg","en":"https://image.tmdb.org/t/p/w500/r7LTwkgqUPPABnHpxceVylMf8M0.jpg","fr":"https://image.tmdb.org/t/p/w500/7YLy9VwVwIDXohRYyAIjFyqZRaq.jpg"}'::jsonb WHERE id = 186;
UPDATE public.films SET tmdb_id = 86000, titoli_i18n = '{"it":"Always (Ojik geudaeman)","de":"Always","es":"Siempre / Solo tú","fr":"Always","en":"Always"}'::jsonb, trame_i18n = '{"de":"Cheol-min nimmt einen Teilzeitjob als Nachtwärter auf einem Parkplatz an. Dort trifft er zufällig auf die blinde und lebensfrohe Jung-hwa, zu der er sich immer mehr hingezogen fühlt. Als sie ihn nach seiner Vergangenheit fragt, die er anderen gegenüber verheimlicht, reagiert er aggressiv und ihr Verhältnis kühlt ab. Als Jung-hwa bedroht wird, kann er sie aber beschützen und ihr beider Leben ändert sich radikal. Bei einer Untersuchung stellt sich aber heraus, dass Jung-hwa ohne eine sofortige Operation ihr Augenlicht für immer verlieren könnte. Cheol-min erkennt, dass ihre beiden Leben auf tragische Art und Weise miteinander zusammenhängen. Um die Operation zu finanzieren, macht er bei einem gefährlichen Boxkampf mit.","es":"Cheol Min, un ex-boxeador con un pasado oscuro y misterioso, acepta el trabajo nocturno atendiendo un parking. Un día,conoce a una chica llamada Jung Hwa que quedó ciega a consecuencias de un accidente de tráfico,ella entra en la cabina donde trabaja y sin saber que es él, le da caramelos y mandarinas. Pasan asi los días y entre ellos surgirá un amor mutuo. Jun Hwa, al hacerse un chequeo médico pone en conocimiento de Cheol Min que de no hacerse la operación pronto para recobrar la vista más adelante seria demasiado tarde. Cheol Min hara lo imposible por conseguir que Jun Hwa se opere, pero ¿será suficiente? ¿Que hará para poder conseguir todo el dinero de la operación?","fr":"Une histoire d''amour entre un ancien boxeur Chul-min et une spécialiste en télémarketing aveugle Jung-hwa.","en":"A former boxer turned parking lot attendant finds hope in the love of the blind telemarketer who walks into his booth one day.","it":"Un ex pugile dal passato tormentato, che ora lavora come guardiano di un parcheggio, incontra una ragazza non vedente ma piena di vitalità. Tra i due nasce un profondo legame d''amore, ma il passato dell''uomo tornerà a minacciare la loro felicità e la vista della donna."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zqw49pO0FndPZL5LVkq85JCNIVH.jpg","de":"https://image.tmdb.org/t/p/w500/zqw49pO0FndPZL5LVkq85JCNIVH.jpg","es":"https://image.tmdb.org/t/p/w500/zqw49pO0FndPZL5LVkq85JCNIVH.jpg","fr":"https://image.tmdb.org/t/p/w500/zqw49pO0FndPZL5LVkq85JCNIVH.jpg","en":"https://image.tmdb.org/t/p/w500/7PaCGnjY87sc9088zxFf34Tamcz.jpg"}'::jsonb WHERE id = 187;
UPDATE public.films SET tmdb_id = 144231, titoli_i18n = '{"en":"Always … But Not Forever","it":"Always","de":"Always … But Not Forever","es":"Always … But Not Forever","fr":"Always … But Not Forever"}'::jsonb, trame_i18n = '{"en":"A middle-aged couple, on the verge of proceeding with a divorce, find themselves questioning their decision to separate when fellow friends and neighbors, oblivious to their marital troubles, assemble at their house for a 4th of July Weekend party.","it":"Un regista e la sua ex moglie trascorrono insieme il fine settimana del Giorno dell''Indipendenza per formalizzare il loro divorzio, ma la convivenza temporanea riaccende vecchi sentimenti e costringe entrambi a confrontarsi con i motivi della fine del loro matrimonio."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg","it":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg","de":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg","es":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg","fr":"https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg"}'::jsonb WHERE id = 188;
UPDATE public.films SET tmdb_id = 639, titoli_i18n = '{"de":"Harry und Sally","es":"Cuando Harry encontró a Sally","fr":"Quand Harry rencontre Sally…","en":"When Harry Met Sally...","it":"Harry, ti presento Sally... (When Harry Met Sally...)"}'::jsonb, trame_i18n = '{"de":"Harry nervt Sally und Sally nervt Harry. Das war während ihrer gemeinsamen unfreiwilligen 18-Stunden-Fahrt nach New York so, und bleibt auch so fünf Jahre später, als sie sich zufällig im Flugzeug treffen. Weitere fünf Jahre später – beide im Beziehungsfrust – tritt das ungleiche Paar mehr aus Not den Gegenbeweis für Harrys Lieblingsthese an: „Männer und Frauen können nie Freunde sein – der Sex kommt ihnen immer in die Quere.“ Und wie in jeder guten Komödie merken die beiden als allerletzte, dass sie im Grunde füreinander geschaffen sind.","es":"Harry Burns y Sally Albright se conocen fortuitamente cuando ella se ofrece para llevarle en su coche hasta la ciudad, entablan una conversación sobre la amistad entre personas de diferente sexo; la conversación acaba en discusión, pero entre ellos nace algo muy especial. Son un hombre y una mujer que se han pasado mucho tiempo intentando averiguar cómo seguir siendo amigos. Sin embargo, Harry tiene una firme creencia: que dos personas de sexo opuesto no pueden ser simplemente amigos, la relación siempre acaba en la cama o en el altar.","fr":"Lorsqu''ils se rencontrent pour la première fois dans les années 70, Harry et Sally ne s''apprécient pas, mais alors pas du tout. Ils se quittent, jurant de ne plus se revoir. Cinq ans plus tard, ils se retrouvent mais rien n''a changé : leurs avis sur les relations hommes-femmes divergent du tout au tout. Cinq autres années passent, et Harry rencontre Sally à nouveau. Ils se racontent leurs expériences, leurs déceptions et se rendent compte que leur vie amoureuse est un désastre. Mais l''amitié entre Harry et Sally est-elle possible ?","en":"Sex always gets in the way of friendships between men and women. At least, that''s what Harry Burns believes. So when Harry meets Sally Albright and a deep friendship blossoms between them, Harry''s determined not to let his attraction to Sally destroy it. But when a night of weakness ends in a morning of panic, can the pair avoid succumbing to Harry''s fears by remaining friends and admitting they just might be the perfect match for each other?","it":"Harry Burns e Sally Albright si incontrano per la prima volta nel 1977 durante un viaggio in auto da Chicago a New York. Nel corso di dodici anni si ritrovano casualmente più volte, sviluppando una profonda amicizia che mette alla prova la teoria di Harry secondo cui un uomo e una donna non possono essere amici senza che il sesso si metta di mezzo."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/i6L2FanSxToy4OxGDUYxzST4FwR.jpg","es":"https://image.tmdb.org/t/p/w500/dHUhjAPViRGTU9CFBt4JoANWHiK.jpg","fr":"https://image.tmdb.org/t/p/w500/ghvbClWDXje0ksaL6ad2k7IZHCc.jpg","en":"https://image.tmdb.org/t/p/w500/rFOiFUhTMtDetqCGClC9PIgnC1P.jpg","it":"https://image.tmdb.org/t/p/w500/9FntiimMchiZBjuklFfMuIinRnC.jpg"}'::jsonb WHERE id = 189;
UPDATE public.films SET tmdb_id = 166, titoli_i18n = '{"en":"The Party","de":"La Boum - Die Fete","it":"Il tempo delle mele (La Boum)","fr":"La Boum","es":"La fiesta"}'::jsonb, trame_i18n = '{"en":"A thirteen-year-old French girl deals with moving to a new city and school in Paris, while at the same time her parents are getting a divorce.","de":"Die 13-jährige Vic zieht mit ihren Eltern, einem Zahnarzt und einer Comiczeichnerin, nach Paris. Dort findet Vic schnell Freunde, unter anderem Pénélope, die im Gegensatz zu Vic schon Erfahrungen mit Jungs hat, und deren kleine Schwester Samantha. Auf einer Fete findet Vic ihre erste große Liebe, Mathieu, mit dem sie schon nach kurzer Zeit ausgeht. Die Familienidylle zerbricht, als herauskommt, dass Vics Vater eine Affäre mit einer Parfumhändlerin hatte. Wütend trennt sich Vics Mutter vorübergehend von ihm und demoliert aus Rache das Geschäft der Geliebten. Wenig später beginnt sie eine Affäre mit Vics Lehrer.","it":"La quattordicenne Vic affronta i primi amori, le prime feste e le difficoltà dell''adolescenza nella Parigi degli anni ''80, mentre i suoi genitori attraversano una profonda crisi coniugale.","fr":"Vic, treize ans, inscrite au lycée Henri-IV, est à l''âge des premières sorties et des premiers émois. Vic n''a guère l''occasion de parler avec ses parents, trop occupés par leur carrière respective, et dont le couple subit les assauts classiques du temps. Elle se confie donc à son arrière-grand-mère, la pétillante Poupette, ou à sa meilleure amie, Pénélope. Elle partagera donc avec elles son amour pour le beau Mathieu. Mais cet amour-là aussi connaîtra quelques difficultés...","es":"Vic tiene 13 años y es nueva en el instituto, pero pronto se hace amiga de Penélope. Las dos están ansiosas por encontrar un chico del que enamorarse; el problema es que los padres de Vic no la dejan todavía ir a fiestas."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/usGV1Q7KWR0Uq4dOIppGZ0ba8kz.jpg","de":"https://image.tmdb.org/t/p/w500/5FC0Js9guGK8MPxDhWcxvSiv0Iw.jpg","it":"https://image.tmdb.org/t/p/w500/lDxr4hi1El5SLIArgGAhjyOzREk.jpg","fr":"https://image.tmdb.org/t/p/w500/s2d4P7XZUA4rwNK4il7gMptxd7M.jpg","es":"https://image.tmdb.org/t/p/w500/rZwEKic3lnftp9M7TjAsTW2pDEh.jpg"}'::jsonb WHERE id = 190;
UPDATE public.films SET tmdb_id = 171, titoli_i18n = '{"en":"The Party 2","fr":"La Boum 2","de":"La Boum 2 - Die Fete geht weiter","it":"Il tempo delle mele 2 (La Boum 2)","es":"La Boum 2"}'::jsonb, trame_i18n = '{"en":"After moving to a new city, a young French teenage girl falls in love with a boy and thinks of having sex with him, since her girl friends have already done it.","fr":"Deux ans ont passé, Vic, maintenant âgée de 15 ans (et 3 mois) entre en classe de seconde au lycée Henri-IV. Ses amis aussi ont grandi. Cela fait maintenant un an qu''elle n''est pas \"sortie\" avec un garçon. Dans le train, en rentrant d''Autriche avec Poupette, lors du contrôle des Douanes, ce n''est pas son passeport qui lui est rendu, mais celui d''un certain Philippe Berthier, un jeune homme de 18 ans dont elle va vite devenir amoureuse. Dans le même temps, ses parents François et Françoise évoluent dans leurs carrières respectives et des choix devront être faits...","de":"Vic Beretton ist inzwischen 15; während ihre Freundin Pénélope jede Woche mit einem anderen Jungen geht und auch schon die Pille nimmt, ist Vic noch immer Jungfrau und führt ein relativ entspanntes Leben ohne Freund. Eines Tages jedoch trifft sie Philippe im Zug und vertauscht versehentlich seinen Pass mit ihrem. Später sucht sie ihn, um ihm seinen Pass zurückzugeben. Die beiden werden Freunde und gehen miteinander aus. Doch Vic ist sich nicht sicher, ob Philippe der richtige für das „erste Mal“ ist, zumal sie Philippes Beziehung zu dessen Exfreundin Catherine mit Misstrauen betrachtet. Währenddessen bändelt Pénélope, nachdem sie von Thibaut (mit dem sie geschlafen hat) verlassen wurde, mit dem Neffen des Schwagers des neuen Freundes ihrer Mutter an, wechselt jedoch später auf Didier und schließlich auf Philippes Freund Frédo. Ihre Schwester Samantha vernachlässigt inzwischen die Schule und konzentriert sich ganz auf ihr Training als Balletttänzerin.","it":"Vic ha ormai sedici anni e, di ritorno da un viaggio, incontra il giovane Philippe. Tra i due nasce una romantica storia d''amore che la porterà a confrontarsi con nuove gelosie e le prime vere scelte della maturità."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/pbkccDoxH1H1VdqWcQYycZxHTIK.jpg","fr":"https://image.tmdb.org/t/p/w500/eN2xx8aRd4sjelfunSLmtZXCKfd.jpg","de":"https://image.tmdb.org/t/p/w500/AkZfQry3QngGZbQ3RmrNF4XTs2M.jpg","it":"https://image.tmdb.org/t/p/w500/ixRF6arqUqSHqvruUxbLFaSkK2L.jpg","es":"https://image.tmdb.org/t/p/w500/eN2xx8aRd4sjelfunSLmtZXCKfd.jpg"}'::jsonb WHERE id = 191;
UPDATE public.films SET tmdb_id = 52286, titoli_i18n = '{"es":"La estudiante","it":"Il tempo delle mele 3 (L''étudiante)","en":"The Student","de":"Die Studentin","fr":"L''Étudiante"}'::jsonb, trame_i18n = '{"es":"Tres meses antes de sus exámenes finales, la ambiciosa Valentine se concentra totalmente en sus estudios. Cuando el músico de jazz Edouard la corteja, ella está de acuerdo, aunque sólo para una noche de diversión. Pero cuando llega a conocerlo mejor, se da cuenta de que no es tan superficial como ella pensaba ... y el deseo se convierte en amor. Sin embargo, entre los preparativos de su examen y los de una gira con una banda de jazz de Edouard casi no les queda tiempo para estar juntos.","it":"Valentine è una studentessa universitaria determinata a superare i suoi esami di abilitazione all''insegnamento. La sua vita rigorosa viene sconvolta dall''incontro con Ned, un musicista jazz con ritmi di vita opposti ai suoi.","en":"An ambitious teaching student''s finals studies are interrupted by a passionate affair with a jazz musician.","de":"Die Lehramtskandidatin Valentine läßt sich kurz vor dem Examen auf einen Flirt mit dem Musiker Eduard ein. Nach der gemeinsam verbrachten Nacht zieht sie sich zum Büffeln zuirück, während Eduard mit seiner Band auf Frankreich-Tournee geht. Die Liebe führt die beiden unterschiedlichen Charaktere trotz Stress und Terminschwierigkeiten wieder zusammen, und am Ende schafft die Studentin ihre Abschlußprüfung trotz aller Hindernisse.","fr":"Valentine prépare avec acharnement son agrégation, l''aboutissement de 5 années d''études difficiles. Elle ne dispose donc pas de loisirs et doit beaucoup travailler. Elle va cependant tomber amoureuse d''Édouard, un jeune musicien…"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/jR8L6MtUwuv9ZI0KyOUhoeCvUVd.jpg","it":"https://image.tmdb.org/t/p/w500/wGx196d9fMsWwItWTK3WpUkzY1T.jpg","en":"https://image.tmdb.org/t/p/w500/tDx9zW0Edb83qh9PAGrgP3Zh9RP.jpg","de":"https://image.tmdb.org/t/p/w500/reGOKVmhkdueUQUBDUU57JcyE35.jpg","fr":"https://image.tmdb.org/t/p/w500/jR8L6MtUwuv9ZI0KyOUhoeCvUVd.jpg"}'::jsonb WHERE id = 192;
UPDATE public.films SET tmdb_id = 1813, titoli_i18n = '{"en":"The Devil''s Advocate","it":"L''avvocato del diavolo (Des Teufels Advokat)","fr":"L''Associé du diable","de":"Im Auftrag des Teufels","es":"Pactar con el diablo"}'::jsonb, trame_i18n = '{"en":"Aspiring Florida defense lawyer Kevin Lomax accepts a job at a New York law firm. With the stakes getting higher every case, Kevin quickly learns that his boss has something far more evil planned.","it":"Un sacerdote affetto da un male incurabile viene inviato in un piccolo paese della Calabria per indagare sulla vita e sui presunti miracoli di un uomo giustiziato nel 1944.","fr":"Kevin Lomax, jeune et brillant avocat, est approché par l''un des plus puissants cabinets New-Yorkais dirigé par l''étrange John Milton. Assoiffé de pouvoir et d''argent, poussé par une ambition dévorante, prêt à tout pour réussir, il accepte l''offre et gravit les marches de la réussite de façon fulgurante. Mais l''ambition a un prix : sans le savoir, Kevin vient de vendre son âme au diable...","de":"Der junge Staatsanwalt Kevin Lomax bekommt die Chance seines Lebens: Die größte und mächtigste Kanzlei des Landes holt ihn nach New York. Und damit nicht genug: Sein neuer Boß, der geheimnisvolle John Milton, nimmt ihn persönlich unter seine Fittiche. Unaufhaltsam verfällt Kevin dem Rausch von Macht, Ruhm, Sex und dem ganz großen Geld. Doch nach einer Serie unheimlicher Vorfälle wird Kevin klar, daß ihn der Leibhaftige persönlich unter Vertrag genommen hat.","es":"Kevin Lomax (Keanu Reeves) es un joven y brillante abogado que nunca ha perdido un caso. Vive en Florida y parece feliz con su esposa, Mary Ann (Charlize Theron). Un día, recibe la visita de un abogado de Nueva York, que representa a un poderoso bufete que tiene la intención de contratarlo. Al frente de la prestigiosa empresa se encuentra John Milton (Al Pacino), un hombre mundano, brillante y carismático, que alberga planes muy oscuros con respecto a Lomax."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/5ZzBGpxy55OQzHxKVY11IpY6a0o.jpg","it":"https://image.tmdb.org/t/p/w500/6wq4owkyGkdXqehBsgcPOfeVVOE.jpg","fr":"https://image.tmdb.org/t/p/w500/dwRco8u0IrVfiWzSH8HLUjgRdNR.jpg","de":"https://image.tmdb.org/t/p/w500/9deaag4AgDAgo6sG2pBfeV8BOgG.jpg","es":"https://image.tmdb.org/t/p/w500/rOXciqRgEXqRvvYS6Dk2im3NF7H.jpg"}'::jsonb WHERE id = 193;
UPDATE public.films SET tmdb_id = 1813, titoli_i18n = '{"fr":"L''Associé du diable","en":"The Devil''s Advocate","it":"L''avvocato del diavolo (The Devil''s Advocate)","es":"Pactar con el diablo","de":"Im Auftrag des Teufels"}'::jsonb, trame_i18n = '{"fr":"Kevin Lomax, jeune et brillant avocat, est approché par l''un des plus puissants cabinets New-Yorkais dirigé par l''étrange John Milton. Assoiffé de pouvoir et d''argent, poussé par une ambition dévorante, prêt à tout pour réussir, il accepte l''offre et gravit les marches de la réussite de façon fulgurante. Mais l''ambition a un prix : sans le savoir, Kevin vient de vendre son âme au diable...","en":"Aspiring Florida defense lawyer Kevin Lomax accepts a job at a New York law firm. With the stakes getting higher every case, Kevin quickly learns that his boss has something far more evil planned.","it":"Un giovane e imbattuto avvocato della Florida viene ingaggiato da un imponente studio legale di New York. L''uomo si rende presto conto che il suo carismatico capo, John Milton, e la societa stessa nascondono un''oscura origine demoniaca.","es":"Kevin Lomax (Keanu Reeves) es un joven y brillante abogado que nunca ha perdido un caso. Vive en Florida y parece feliz con su esposa, Mary Ann (Charlize Theron). Un día, recibe la visita de un abogado de Nueva York, que representa a un poderoso bufete que tiene la intención de contratarlo. Al frente de la prestigiosa empresa se encuentra John Milton (Al Pacino), un hombre mundano, brillante y carismático, que alberga planes muy oscuros con respecto a Lomax.","de":"Der junge Staatsanwalt Kevin Lomax bekommt die Chance seines Lebens: Die größte und mächtigste Kanzlei des Landes holt ihn nach New York. Und damit nicht genug: Sein neuer Boß, der geheimnisvolle John Milton, nimmt ihn persönlich unter seine Fittiche. Unaufhaltsam verfällt Kevin dem Rausch von Macht, Ruhm, Sex und dem ganz großen Geld. Doch nach einer Serie unheimlicher Vorfälle wird Kevin klar, daß ihn der Leibhaftige persönlich unter Vertrag genommen hat."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/dwRco8u0IrVfiWzSH8HLUjgRdNR.jpg","en":"https://image.tmdb.org/t/p/w500/5ZzBGpxy55OQzHxKVY11IpY6a0o.jpg","it":"https://image.tmdb.org/t/p/w500/6wq4owkyGkdXqehBsgcPOfeVVOE.jpg","es":"https://image.tmdb.org/t/p/w500/rOXciqRgEXqRvvYS6Dk2im3NF7H.jpg","de":"https://image.tmdb.org/t/p/w500/9deaag4AgDAgo6sG2pBfeV8BOgG.jpg"}'::jsonb WHERE id = 194;
UPDATE public.films SET tmdb_id = 9659, titoli_i18n = '{"it":"Interceptor (Mad Max)","en":"Mad Max","de":"Mad Max","es":"Mad Max. Salvajes de la autopista","fr":"Mad Max"}'::jsonb, trame_i18n = '{"it":"In un''Australia distopica e violenta al collasso sociale, il poliziotto Max Rockatansky cerca vendetta contro una spietata banda di motociclisti che ha sterminato la sua famiglia.","en":"In the ravaged near-future, a savage motorcycle gang rules the road. Terrorizing innocent civilians while tearing up the streets, the ruthless gang laughs in the face of a police force hell-bent on stopping them.","de":"Die Erde ist wüst, die Ordnung zerfallen, und auf den Highways liefern sich Banden und Polizei wilde Rennen. Den grausamen Motorradrockern \"Glory Riders\" stehen schwerstbewaffnete Cops mit 600 PS-starken Karossen gegenüber. Einer der letzten aufrechten Gesetzeshüter ist Max. Als bei einer Jagd auf die Rocker sein bester Freund stirbt, quittiert Max den Dienst. Mit seiner Frau Jessie und seinem Sohn zieht er durchs Land, kann dem Endzeitkrieg jedoch nicht entkommen. Der sadistische Toecutter tötet Max'' Kind und schlägt Jessie zum Krüppel. Aus Max wird \"Mad Max\" und bis an die Zähne bewaffnet startet er seinen Rachefeldzug...","es":"En las autopistas desiertas de una Australia desconocida, tiene lugar una guerra sin merced entre motoristas forajidos y policías Interceptor, que intentan triunfar sobre la gentuza al volante de coches con motores trucados. En un mundo en plena decadencia, la moral se difuminará en el escenario post apocalíptico donde lo único que tiene valor es el bien más preciado: la gasolina. La depravación, crueldad y salvajismo reinan en las bandas que no dudarán en perseguir y acabar con cualquiera que se ponga entre ellos y su ansia destruir y ser los amos de la carretera. Max se cruzará en su camino y lo que empieza como un acto de justicia no tardará en tornarse una lucha personal para acabar con ellos.","fr":"Sur les autoroutes désertées d''une Australie méconnaissable, une guerre sans merci oppose motards hors-la-loi et policiers Interceptor, qui tentent de triompher de la vermine au volant de voitures aux moteurs surgonflés. Dans ce monde en pleine décadence, les bons, les méchants, le manichéisme disparaissent…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/4vkHxaW8mGTQuhl6BAkUu2WnxfR.jpg","en":"https://image.tmdb.org/t/p/w500/5LrI4GiCSrChgkdskVZiwv643Kg.jpg","de":"https://image.tmdb.org/t/p/w500/nlyVSuwvacjEDdnDZVqsJaTdeJU.jpg","es":"https://image.tmdb.org/t/p/w500/vWa1DEwV5RbAOiuAm0WNXD3Aydw.jpg","fr":"https://image.tmdb.org/t/p/w500/nv5DtpzgjrILNusr3JiTE3O4tlL.jpg"}'::jsonb WHERE id = 195;
UPDATE public.films SET tmdb_id = 8810, titoli_i18n = '{"it":"Interceptor - Il guerriero della strada (Mad Max 2)","de":"Mad Max II - Der Vollstrecker","fr":"Mad Max 2 : Le Défi","en":"Mad Max 2","es":"Mad Max II. El guerrero de la carretera"}'::jsonb, trame_i18n = '{"it":"Divenuto un vagabondo solitario nelle desolate terre post-apocalittiche, Max accetta di difendere una comunità assediata che gestisce una preziosa raffineria di petrolio da un gruppo di predoni sanguinari.","de":"Das Ende der Zivilisation steht bevor. Brutale Motorrad-Gangs diktieren das Geschehen. Für einen Tropfen Benzin, sind sie bereit zu töten. Auch die Familie des Ex-Polizisten Max wurde ermordet. Auf der Suche nach Benzin gelangt er zu einer heiß umkämpften Raffinerie, zu der er sich Zugang verschafft. Die Leute dort planen den Ausbruch mit einem riesigen Benzintank, um irgendwo ein neues Leben zu beginnen. Max soll dafür einen Sattelschlepper besorgen und ihn samt Tank steuern. Als sich die Tore öffnen, beginnt eine höllische Jagd auf Leben und Tod.","fr":"Dans un futur non défini, les réserves de pétrole sont épuisées et la violence règne sur le monde. Max, un ancien de la sécurité routière, se porte aux secours d''une communauté de fuyards aux prises avec des pirates de la route. La bataille se concentre autour d''une citerne de raffinerie.","en":"Max Rockatansky returns as the heroic loner who drives the dusty roads of a postapocalyptic Australian Outback in an unending search for gasoline. Arrayed against him and the other scraggly defendants of a fuel-depot encampment are the bizarre warriors commanded by the charismatic Lord Humungus, a violent leader whose scruples are as barren as the surrounding landscape.","es":"Tras el holocausto nuclear, la gasolina se ha convertido en un bien escaso y muy codiciado. Mad Max, héroe solitario, inicia una lucha sin cuartel para ayudar a una colonia de supervivientes constantemente atacada por un grupo de violentos guerreros que intenta arrebatarle un tanque de gasolina. Max decide ayudar a los defensores del tanque utilizando un enorme camión como trampa. La banda de guerreros persigue al camión, pensando que transporta miles de litros de gasolina."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/i313vatvaMM67gi1B3YqJtl295Q.jpg","de":"https://image.tmdb.org/t/p/w500/c0LcCMUcMMImdYYbfHchfTUF29j.jpg","fr":"https://image.tmdb.org/t/p/w500/oNI8l7GL3fvDIP9mtBSMku4gQde.jpg","en":"https://image.tmdb.org/t/p/w500/l1KVEhkGDpWRzQ0VqIhZqDDuOim.jpg","es":"https://image.tmdb.org/t/p/w500/udpVgRB3xz5ZN553apthn4TyT6G.jpg"}'::jsonb WHERE id = 196;
UPDATE public.films SET tmdb_id = 9355, titoli_i18n = '{"it":"Mad Max oltre la sfera del tuono (Mad Max Beyond Thunderdome)","en":"Mad Max Beyond Thunderdome","fr":"Mad Max :  Au-delà du dôme du tonnerre","de":"Mad Max - Jenseits der Donnerkuppel","es":"Mad Max III. Más allá de la cúpula del trueno"}'::jsonb, trame_i18n = '{"it":"Esiliato dall''avida dominatrice della città di Bartertown dopo essersi rifiutato di uccidere un gladiatore, Max viene salvato da una tribù di bambini sopravvissuti a un incidente aereo che lo credono il loro salvatore.","en":"Mad Max becomes a pawn in a decadent oasis of a technological society, and when exiled, becomes the deliverer of a colony of children.","fr":"Max, de retour, s''est fait dépouiller de son maigre bien. Suivant le voleur, il arrive à la Ville du Troc, où règne Entity. Celle-ci l''engage pour qu''il la débarrasse de Master et Blaster, rois du Monde souterrain. N''ayant voulu tuer Blaster, Max est abandonné en plein désert, d''où il ressurgit à la tête d''une troupe d''enfants pour faire exploser la Ville du Troc.","de":"Mad Max, der letzte wahre Kämpfer nach der barbarischen Apokalypse, gelangt auf der Suche nach seinem gestohlenen Dromedargespann an den Wüstenhandelsplatz Bartertown. Hier herrscht Aunty Entity mit Strenge und Gewalt. Sie schlägt Max einen Handel vor: wenn er den riesenhaften Blaster im Zweikampf unter der Donnerkuppel besiegt, soll er seine Ausrüstung zurückerhalten. Max gewinnt die erbarmungslose Auseinandersetzung, bei der alle Waffen erlaubt sind, doch er schenkt Blaster und seinem Herrn Master, einem Gnom, das Leben. Wütend läßt Aunty ihn fesseln und in die Wüste jagen. Aber Mad Max kehrt zurück nach Bartertown. Härter und unerbittlicher als je zuvor. Bei einer rasanten Verfolgungsjagd durch die unendliche Wüste kommt es zur spektakulären Entscheidung...","es":"Tras la catástrofe nuclear, Mad Max cruza un desierto donde pierde su caravana de camellos. Llega a una ciudad donde le proponen cambiárselos a cambio de que ataque al tirano de la ciudad subterránea, un enano que fabrica gas metano con excrementos de cerdo."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zEFrGhYPkE0taW1cGgmfMoOWQ4t.jpg","en":"https://image.tmdb.org/t/p/w500/jJlxcEVVUHnrUeEkQ0077VeHQpb.jpg","fr":"https://image.tmdb.org/t/p/w500/fHo2AJ9brsXKWbYJ2LA087UDBwZ.jpg","de":"https://image.tmdb.org/t/p/w500/n3TM8ZHG4R6aZSbt3GhSTigRzaD.jpg","es":"https://image.tmdb.org/t/p/w500/u9gVwCajHkJpVAaVRau2xSOeHcl.jpg"}'::jsonb WHERE id = 197;
UPDATE public.films SET tmdb_id = 76341, titoli_i18n = '{"it":"Mad Max: Fury Road","en":"Mad Max: Fury Road","fr":"Mad Max : Fury Road","es":"Mad Max: Furia en la carretera","de":"Mad Max: Fury Road"}'::jsonb, trame_i18n = '{"it":"In fuga attraverso le distese desertiche controllate dal tiranno Immortan Joe, Max unisce le forze con l''Imperatrice Furiosa per scortare cinque donne verso la libertà a bordo di una potente autocisterna.","en":"An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order.","fr":"Hanté par un lourd passé, Mad Max estime que le meilleur moyen de survivre est de rester seul. Cependant, il se retrouve embarqué par une bande qui parcourt le désert à bord d’un véhicule militaire piloté par l’Impératrice Furiosa. Ils fuient la Citadelle où sévit le terrible Immortan Joe qui s’est fait voler un objet irremplaçable. Enragé, ce Seigneur de guerre envoie ses hommes pour traquer les rebelles impitoyablement…","es":"Perseguido por su turbulento pasado, Mad Max cree que la mejor forma de sobrevivir es ir solo por el mundo. Sin embargo, se ve arrastrado a formar parte de un grupo que huye a través del desierto en un War Rig conducido por una Emperatriz de élite: Furiosa. Escapan de una Ciudadela tiranizada por Immortan Joe, a quien han arrebatado algo irreemplazable. Enfurecido, el Señor de la Guerra moviliza a todas sus bandas y persigue implacablemente a los rebeldes en una ''guerra de la carretera'' de altas revoluciones.","de":"Bei seinen Reisen durch die postapokalyptische Ödnis der Zukunft wird Max von den Schergen des Warlords Immortan Joe gefangen genommen und als lebende Blutkonserve für den schwerkranken Krieger Nux verwendet. Als Imperator Furiosa, eine wichtige Handlangerin Joes, den Herrscher hintergeht, indem sie seine fünf Frauen befreit und während einer Handelsmission mit ihnen an Bord ihres Kriegslasters flieht, ruft der Warlord sein Heer zur Verfolgung auf. Zu den Kriegern gehört auch Nux, der Max zur Blutversorgung an seinen Wagen schnallt. Doch während des ersten Gefechts zwischen Joes Leuten und Furiosa kann sich Max befreien und bildet von da eine Zweckgemeinschaft mit Furiosa und den Frauen, während sie weiter unerbittlich von den Truppen Joes gejagt werden …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5gbm8m1gYvOmVGRcxteiplDLWdg.jpg","en":"https://image.tmdb.org/t/p/w500/ulcAi4dKpAjHwYGS08vNyx9H6I9.jpg","fr":"https://image.tmdb.org/t/p/w500/oLy2V6AWSEfdPgKOtrSGnwB3Q2R.jpg","es":"https://image.tmdb.org/t/p/w500/fnY0VRsb31A5RLVCBjuR6EFUlo2.jpg","de":"https://image.tmdb.org/t/p/w500/6zI7lI5Usf5z6wXH9KPWvGWvKS7.jpg"}'::jsonb WHERE id = 198;
UPDATE public.films SET tmdb_id = 786892, titoli_i18n = '{"it":"Furiosa: A Mad Max Saga","en":"Furiosa: A Mad Max Saga","de":"Furiosa: A Mad Max Saga","fr":"Furiosa — Une saga Mad Max","es":"Furiosa: De la saga Mad Max"}'::jsonb, trame_i18n = '{"it":"Rapita da bambina dal Luogo Verde delle Molte Madri e finita nelle mani della brutale Orda di Motociclisti guidata dal Signore della Guerra Dementus, la giovane Furiosa combatte per anni per sopravvivere e trovare la via di casa.","en":"As the world falls, young Furiosa is snatched from the Green Place of Many Mothers into the hands of a great biker horde led by the warlord Dementus. Sweeping through the wasteland, they encounter the citadel presided over by Immortan Joe. The two tyrants wage war for dominance, and Furiosa must survive many trials as she puts together the means to find her way home.","de":"Als die Welt untergeht, wird die junge Furiosa vom Grünen Ort der vielen Mütter entführt und fällt in die Hände einer großen Bikerhorde unter der Führung des Warlords Dementus. Bei ihrem Streifzug durch das Ödland stoßen sie auf die Zitadelle, die vom Immortan Joe beherrscht wird. Während die beiden Tyrannen um die Vorherrschaft kämpfen, muss Furiosa viele Prüfungen überstehen, während sie die Mittel zusammenstellt, um ihren Weg nach Hause zu finden.","fr":"Alors que le monde s''écroule, la jeune Furiosa tombe entre les mains d''une horde de motards dirigée par le seigneur de la guerre Dementus. En traversant le Wasteland, ils tombent sur la Citadelle présidée par l''Immortan Joe. Alors que les deux tyrans se battent pour la domination, Furiosa doit survivre à de nombreuses épreuves pour trouver le moyen de rentrer chez elle.","es":"En un mundo postapocalíptico donde todo ha perdido su valor, los pocos supervivientes se guían por la ley del más fuerte. Sin aprecio por la vida, lo único que despierta un brutal interés es la gasolina, sinónimo de poder y objetivo de bandas armadas hasta los dientes y sin escrúpulos. En este contexto conoceremos la  historia de la arrebatadoramente despiadada, salvaje y joven Furiosa, quien cae en manos de una horda de motoristas y debe sobrevivir a muchas pruebas mientras reúne los medios para encontrar el camino de vuelta a casa. Precuela de ''Mad Max: Furia en la carretera'' (2015)."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/fMG7ALVMYT8mVY9zQyVPIFCzQnN.jpg","en":"https://image.tmdb.org/t/p/w500/iADOJ8Zymht2JPMoy3R7xceZprc.jpg","de":"https://image.tmdb.org/t/p/w500/jhq0IGZLeWwJbj2gCAevaT8MlSS.jpg","fr":"https://image.tmdb.org/t/p/w500/hbxqFdWXHeLIJfagMMhVG5SV5tb.jpg","es":"https://image.tmdb.org/t/p/w500/tGHUlykWn9V2IIQ4ZaATIAq9VLB.jpg"}'::jsonb WHERE id = 199;
UPDATE public.films SET tmdb_id = 968, titoli_i18n = '{"de":"Hundstage","es":"Tarde de perros","it":"Quel pomeriggio di un giorno da cani (Dog Day Afternoon)","en":"Dog Day Afternoon","fr":"Un après-midi de chien"}'::jsonb, trame_i18n = '{"de":"An einem heißen Sommertag will der arbeitslose New Yorker Sonny gemeinsam mit zwei Freunden eine Bank überfallen, um die Geschlechtsumwandlung seines Geliebten finanzieren zu können. Was als Ex-und-Hopp-Aktion geplant war, läuft gründlich schief: Sonny findet sich mit seinem Komplizen Sal, einem Haufen Geiseln und minimaler Beute in der Bank wieder, während draußen Polizei und Fernsehteams Stellung beziehen. Nervenaufreibende Verhandlungen über einen Abzug beginnen.","es":"Unos delincuentes de poca monta deciden atracar la sucursal de un banco de Brooklyn. Sin embargo, debido a su inexperiencia, el robo, que había sido planeado para ser ejecutado en apenas diez minutos, se convierte en una trampa para los atracadores y en un espectáculo para la televisión en directo.","it":"A New York, tre rapinatori poco esperti tentano di svaligiare una filiale bancaria in un torrido pomeriggio estivo. Quando il colpo fallisce, la situazione si trasforma in un lungo assedio con ostaggi che cattura l''attenzione della polizia e dei media dell''intera nazione.","en":"Based on the true story of would-be Brooklyn bank robbers John Wojtowicz and Salvatore Naturile. Sonny and Sal attempt a bank heist which quickly turns sour and escalates into a hostage situation and stand-off with the police. As Sonny''s motives for the robbery are slowly revealed and things become more complicated, the heist turns into a media circus.","fr":"Des gangsters débutants braquent une banque et se retrouvent cernés par la police et les médias. Ils prennent en otage les employés de la banque. Débute alors un cauchemar qui va durer des heures…"}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/x4D5hmh2QKzZfCeUH4cmGNisR03.jpg","es":"https://image.tmdb.org/t/p/w500/ctcUXNlnddo9ndUK0w7w6CZQpig.jpg","it":"https://image.tmdb.org/t/p/w500/kxVjqcrWGoysfBsrXPQHVLRf1o2.jpg","en":"https://image.tmdb.org/t/p/w500/mavrhr0ig2aCRR8d48yaxtD5aMQ.jpg","fr":"https://image.tmdb.org/t/p/w500/wx54osROfinN2F522AD8ppFwR77.jpg"}'::jsonb WHERE id = 200;
UPDATE public.films SET tmdb_id = 14384, titoli_i18n = '{"es":"Soldado azul","it":"Soldato blu (Soldier Blue)","en":"Soldier Blue","fr":"Soldat bleu","de":"Das Wiegenlied vom Totschlag"}'::jsonb, trame_i18n = '{"es":"Un grupo de soldados de la caballería es atacado por los Cheyennes. Tan sólo Honus, un soldado raso completamente entregado a su deber, y Cresta, una jovencita que había vivido anteriormente con los indios durante dos años y que simpatiza más con ellos que con el ejército americano consiguen sobrevivir a la masacre. Juntos, deberán encontrar el campamento base de la caballería.","it":"Dopo un massacro compiuto dai Cheyenne, gli unici due sopravvissuti, una giovane donna bianca che ha vissuto a lungo con i nativi e un giovane soldato idealista, intraprendono un difficile viaggio per raggiungere la salvezza. Lungo il cammino, si scontreranno con le rispettive visioni del mondo, fino ad assistere al brutale e tragico massacro di un villaggio indiano inerme da parte dell''esercito statunitense.","en":"After a cavalry group is massacred by the Cheyenne, only two survivors remain: Honus, a naive private devoted to his duty, and Cresta, a young woman who had lived with the Cheyenne two years and whose sympathies lie more with them than with the US government. Together, they must try to reach the cavalry''s main base camp. As they travel onward, Honus is torn between his growing affection for Cresta.","fr":"Le 29 Novembre 1864, une unité de volontaires de la Cavalerie du Colorado, comprenant 900 hommes, attaque un paisible village Cheyenne à Sand Creek. Les indiens levèrent un drapeau blanc et un drapeau américain. La cavalerie attaqua néanmoins, massacrant sept cents indiens - dont plus de 350 femmes et enfants. Plus de cent scalps indiens furent pris, des corps furent démembrés et il y eu de nombreux viols…","de":"Der junge Yankee-Soldat Honus Gran und die schöne Cresta Lee sind die einzigen Überlebenden eines Überfalls der Cheyenne-Indianer auf einen Geldtransporter. Honus hasst die Indianer und hat für Cresta, die einst mit dem Häuptling der Cheyenne verheiratet war, nur Verachtung übrig. Cresta sieht das kriegstreiberische Verhalten der US-Kavallerie sehr kritisch und bringt dies offen zum Ausdruck. Als Honus verletzt wird, lässt Cresta ihn zurück, um Hilfe zu holen. Honus schlägt sich allein bis zum Fort durch und wird zum Feldzug gegen die Cheyenne eingesetzt. Er muss miterleben, wie seine geliebte Kavallerie sich des Völkermordes schuldig macht. Obwohl Häuptling Gefleckter Wolf den Soldaten mit einer weißen Fahne entgegenreitet, wird sein Stamm brutal niedergemetzelt."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/6vqJyrOleRoP716Sl2n7xog6w4i.jpg","it":"https://image.tmdb.org/t/p/w500/gk71DcCAhdoNux7Zt5vovmJyCRB.jpg","en":"https://image.tmdb.org/t/p/w500/2fRfVQpdrjAhvxwytG0scOqdQOJ.jpg","fr":"https://image.tmdb.org/t/p/w500/uIXhFUi5wPeRl8emnXH9KOVWwpj.jpg","de":"https://image.tmdb.org/t/p/w500/x6R24XtcDN3aIcfgXoSRT7Mj99I.jpg"}'::jsonb WHERE id = 201;
UPDATE public.films SET tmdb_id = 70160, titoli_i18n = '{"it":"Hunger Games (The Hunger Games)","es":"Los Juegos del Hambre","fr":"Hunger Games","en":"The Hunger Games","de":"Die Tribute von Panem – The Hunger Games"}'::jsonb, trame_i18n = '{"it":"In un futuro distopico, la sedicenne Katniss Everdeen si offre volontaria al posto della sorella minore per partecipare agli Hunger Games, un brutale reality show televisivo in cui ventiquattro adolescenti combattono all''ultimo sangue.","es":"Lo que en el pasado fueron los Estados Unidos, ahora es una nación llamada Panem; un imponente Capitolio ejerce un control riguroso sobre los 12 distritos que lo rodean y que están aislados entre sí. Cada distrito se ve obligado a enviar anualmente un chico y una chica entre los doce y los dieciocho años para que participen en los Hunger Games, unos juegos que son transmitidos en directo por la televisión. Se trata de una lucha a muerte, en la que sólo puede haber un superviviente. Katniss Everdeen, una joven de dieciséis años, decide sustituir a su hermana en los juegos; pero para ella, que ya ha visto la muerte de cerca, la lucha por la supervivencia es su segunda naturaleza.","fr":"Dans un proche futur, les États‐Unis sont devenus un gouvernement fédéral dystopique dans lequel chacun des 12 districts doit envoyer un garçon et une fille combattre lors d’un événement annuel télévisé, « Les Hunger Games ». La seule issue à ces jeux pour les « Tributs » est de tuer ou d’être tué. Lorsque la petite sœur de Katniss est tirée au sort pour y participer, celle‐ci décide de prendre sa place.","en":"In a dystopian society where the Capitol forces each district to send two young tributes to fight to the death in a televised spectacle, a girl volunteers to take her sister’s place, setting the stage for a struggle of survival and defiance.","de":"Die Tribute von Panem bringt uns in eine ferne Zukunft. Die Vereinigten Staaten sind schon lange im Staub der Geschichte versunken. Das Volk leidet unter schrecklichen Hungersnöten, da Jahrhunderte von Kriegen und Naturkatstrophen nur Staub und Verzweiflung zurückgelassen haben. Um die Bevölkerung an die blutigen Folgen eines früheren Aufstandes zu erinnern, inszeniert die Regierung eine grausame Show: Jedes Jahr werden in jedem Distrikt ein Junge und ein Mädchen zwischen 13 und 18 Jahren ausgelost, welche als Tribute von Panem an den Hunger-Games teilnehmen müssen. Dort müssen die 24 Kandidaten mehrere Tage lang auf Leben und Tod gegeneinander kämpfen, bis es am Ende nur noch einen Überlebenden gibt. Um ihre Schwester aus ihrer Tributspflicht zu lösen, meldet sich die 16jährige Katniss freiwillig für die Hunger Games."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/azsm2nqX2eMJQ2eI6FjCIk17ncx.jpg","es":"https://image.tmdb.org/t/p/w500/nmwpp0ykPbddqGW8WmOdBEYFImC.jpg","fr":"https://image.tmdb.org/t/p/w500/fWG9Jqqintc8jQj4XzWNMPjIxzf.jpg","en":"https://image.tmdb.org/t/p/w500/apa5G43Hha7kH7wJG0gkkHT7FA9.jpg","de":"https://image.tmdb.org/t/p/w500/8o3MlFkqI9O8PXRXDApyoN4HNPc.jpg"}'::jsonb WHERE id = 202;
UPDATE public.films SET tmdb_id = 101299, titoli_i18n = '{"it":"Hunger Games: La ragazza di fuoco (The Hunger Games: Catching Fire)","fr":"Hunger Games : L''Embrasement","es":"Los Juegos del Hambre: En llamas","en":"The Hunger Games: Catching Fire","de":"Die Tribute von Panem – Catching Fire"}'::jsonb, trame_i18n = '{"it":"Dopo aver vinto i settantaquattresimi Hunger Games, Katniss e Peeta diventano il simbolo della ribellione contro Capitol City e vengono costretti a partecipare all''Edizione della Memoria degli Hunger Games.","fr":"Après les premiers Hunger Games, Katniss est devenue le symbole de la rébellion. Le peuple de Panem est impatient de la retrouver pour la grande Tournée de la victoire. Mais Katniss va devoir prouver au Capitole et au Président Snow que ses sentiments envers Peeta étaient sincères afin de sauver ceux qu’elle aime…","es":"Tras vencer en los 74º Juegos del Hambre anuales, la joven Katniss Everdeen y su compañero Peeta Mellark regresan a casa. Atrás dejaron a sus amigos y su familia, teniendo ambos que participar en la ''gira de la victoria'' por todos los distritos. Durante ese largo viaje, Katniss se da cuenta de que se está gestando una rebelión, pero en el Capitolio todo sigue igual y bajo estricto control del Presidente Snow, que está organizando los 75º Juegos del Hambre, denominados ''El Vasallaje de los Veinticinco'': una competición especial con una inesperada novedad que cambiará Panem para siempre.","en":"After surviving the Hunger Games, Katniss and Peeta struggle with the consequences of their victory as unrest spreads across Panem. Forced back into the spotlight, they become symbols of hope and resistance while the Capitol prepares a new and deadly challenge that will change the future of the nation forever.","de":"Katniss Everdeen hat nach den Ereignissen des ersten Teils den Zorn von Präsident Snow auf sich gezogen. Um sie endgültig auszuschalten wird sie gemeinsam mit Peeta Mellark anlässlich der 75. Hungerspiele (auch Quarter Quell genannt) gezwungen, abermals gegeneinander anzutreten. Sie müssen dabei gegen andere ehemalige Gewinner der Hungerspiele um ihr Überleben kämpfen. Katniss weiß, dass diesmal nicht nur ihr Leben, sondern auch die Sicherheit ihrer Familie auf dem Spiel steht, denn eine erneute Blamage wird Präsident Snow nicht dulden. Auch außerhalb der Arena hat Katniss Aufbegehren gegen die blutigen Regeln dieses Turniers Wirkung gezeigt. Immer mehr Menschen verweigern sich den Befehlen der totalitären Regierung und erblicken in Katniss das Symbol ihres gemeinsamen Widerstandes. Der Keim der Revolution ist gesät und Katniss’ Mocking Jay ist ihr gemeinsames Erkennungszeichen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/oFQj7SBn9pGGc6ZuadhmQoSYWaD.jpg","fr":"https://image.tmdb.org/t/p/w500/lHdbNb8GEuMXCwar9wENzVu5eQI.jpg","es":"https://image.tmdb.org/t/p/w500/oxnKI1qiHz7xC0mNthC7dSqTcot.jpg","en":"https://image.tmdb.org/t/p/w500/vrQHDXjVmbYzadOXQ0UaObunoy2.jpg","de":"https://image.tmdb.org/t/p/w500/goLUaKDwTip1fikpCHDA6oCIfkV.jpg"}'::jsonb WHERE id = 203;
UPDATE public.films SET tmdb_id = 131631, titoli_i18n = '{"es":"Los Juegos del Hambre: Sinsajo - Parte 1","fr":"Hunger Games : La Révolte, partie 1","de":"Die Tribute von Panem – Mockingjay Teil 1","it":"Hunger Games: Il canto della rivolta - Parte 1 (The Hunger Games: Mockingjay - Part 1)","en":"The Hunger Games: Mockingjay - Part 1"}'::jsonb, trame_i18n = '{"es":"Katniss Everdeen se encuentra en el Distrito 13 después de destrozar los Juegos para siempre. Bajo el liderazgo de la comandante Coin y el consejo de sus amigos más leales, Katniss extiende sus alas mientras lucha por salvar a Peeta Mellark y a una nación alentada por su valentía...","fr":"Katniss Everdeen s’est réfugiée dans le District 13 après avoir détruit à jamais l’arène et les Jeux. Sous le commandement de la Présidente Coin, chef du district, et suivant les conseils de ses amis en qui elle a toute confiance, Katniss déploie ses ailes pour devenir le symbole de la rébellion. Elle va se battre pour sauver Peeta et libérer le pays tout entier, à qui son courage a redonné espoir.","de":"Katniss erwacht nach dem zweiten Hunger-Games-Turnier im Schiff der Rebellen. Da District 12 von der Regierung zerstört wurde, wird sie im unterirdischen District 13 versteckt. Sie erfährt, dass der District 13 entgegen der offiziellen Geschichtsschreibung noch immer existiert und jetzt die Anführer der Revolution stellt. Auch wenn Katniss zögert, sich der Truppe anzuschließen, erkennt sie, dass sie kaum andere Möglichkeiten hat. Die Rebellen wollen Katniss’ Popularität für ihre Zwecke ausnutzen und sie zum ‘Mockingjay’ aufbauen, dem Propagandaidol der Opposition gegen das Capitol. Gleichzeitig wird Peeta, der nicht aus der Arena gerettet werden konnte, von der Regierung gefangen gehalten. Er wird gezwungen, sich vor Kameras von Katniss und den Rebellen loszusagen und einen Waffenstillstand zu fordern. In einer letzten Mission begibt sich Katniss ins Capitol, um Präsident Snow zu töten.","it":"Katniss si ritrova nel Distretto 13 dopo aver distrutto l''arena. Guidata dalla Presidente Coin, accetta di diventare la Ghiandaia Imitatrice, simbolo della rivoluzione contro Panem.","en":"After surviving the Quarter Quell, Katniss finds herself in the hidden stronghold of District 13, where the rebellion against the Capitol is gaining momentum. Struggling with the weight of becoming the symbol of resistance, she must navigate fragile alliances while trying to protect those she loves. As propaganda battles rage and Panem moves closer to full-scale war, Katniss is forced to confront the true cost of revolution."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/wfLsciidZamFPeOb4FD8ywk1Q9c.jpg","fr":"https://image.tmdb.org/t/p/w500/xWQfZgnjaH2fmjGSCWFYicTPwwv.jpg","de":"https://image.tmdb.org/t/p/w500/uK1ZjmrwugzDBSRMx8pi9ZEQDEV.jpg","it":"https://image.tmdb.org/t/p/w500/9LZSYohDOJkLU2TyRvPM1zIo62e.jpg","en":"https://image.tmdb.org/t/p/w500/meSGXQ8MXqiC8bXxkKu7lPqnu0L.jpg"}'::jsonb WHERE id = 204;
UPDATE public.films SET tmdb_id = 131634, titoli_i18n = '{"it":"Hunger Games: Il canto della rivolta - Parte 2 (The Hunger Games: Mockingjay - Part 2)","de":"Die Tribute von Panem – Mockingjay Teil 2","en":"The Hunger Games: Mockingjay - Part 2","es":"Los Juegos del Hambre: Sinsajo - Parte 2","fr":"Hunger Games : La Révolte, partie 2"}'::jsonb, trame_i18n = '{"it":"Con Panem in guerra totale, Katniss guida la squadra d''assalto verso Capitol City per affrontare direttamente il Presidente Snow e porre fine alla tirannia.","de":"Katniss, die sich im 13. Distrikt versteckt hält, wird von den Revolutionsführern gegen das Capitol als Propagandainstrument ausgenutzt. Sie erwacht in einem Krankenhaus und erfährt, dass Peeta das Opfer einer Gedankenmanipulation des Capitols war. Doch die eigentliche Bedrohung geht nicht vom Capitol aus, sondern auch in den eigenen Reihen wird schon für die Zeit nach dem Krieg geplant, in der die Revolutionsikone Katniss für viele, die selbst auf die Macht hoffen, zu beliebt bei der Bevölkerung geworden ist. Katniss gelingt es nur schwer, Peeta zumindest ansatzweise wieder zu heilen. Trotzdem begibt sie sich mit ihm und einer kleinen Einheit in einer letzten geheimen Mission ins Capitol, um Präsident Snow zu töten. Seine Hinrichtung soll live im Fernsehen zu sehen sein, da die Anführer der Revolution glauben, die werde den Krieg beenden. Doch gerade ihren Anführern kann Katniss schon lange nicht mehr trauen. Alles was ihr bleibt, ist das Vertrauen auf ihren Instinkt.","en":"As the war between the Capitol and the districts reaches its peak, Katniss Everdeen embarks on a perilous mission to liberate Panem and confront President Snow. Joined by a team of trusted allies, she navigates deadly traps, shifting loyalties, and the heavy cost of rebellion, determined to bring freedom to her people and end the Hunger Games once and for all.","es":"La última entrega de ''Los Juegos del Hambre'' nos muestra a una nación en guerra, en la que Katniss se enfrenta con uñas y dientes al presidente Snow. Con la ayuda de algunos amigos, entre ellos Gale, Finnick y Peeta, arriesgará la vida para salir del Distrito 13 y eliminar al presidente Snow.","fr":"Alors que Panem est ravagé par une guerre désormais totale, Katniss et le Président Snow vont s’affronter pour la dernière fois. Katniss et ses plus proches amis – Gale, Finnick, et Peeta – sont envoyés en mission pour le District 13 : ils vont risquer leur vie pour tenter d’assassiner le Président Snow, qui s’est juré de détruire Katniss. Les pièges mortels, les ennemis et les choix déchirants qui attendent Katniss seront des épreuves bien pires que tout ce qu’elle a déjà pu affronter dans l’arène…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/aQvME1wpAZpjdyg5Xfe35lINmwt.jpg","de":"https://image.tmdb.org/t/p/w500/gGkGiNZ98aztaHtKxuvtWpNOwoD.jpg","en":"https://image.tmdb.org/t/p/w500/lImKHDfExAulp16grYm8zD5eONE.jpg","es":"https://image.tmdb.org/t/p/w500/3qQPBc7JVGXJGo0Av5jrqndcdTm.jpg","fr":"https://image.tmdb.org/t/p/w500/hsHLkjIs3RKcUAOuJbvb19Q4ZiZ.jpg"}'::jsonb WHERE id = 205;
UPDATE public.films SET tmdb_id = 695721, titoli_i18n = '{"fr":"Hunger Games : La Ballade du serpent et de l''oiseau chanteur","en":"The Hunger Games: The Ballad of Songbirds & Snakes","it":"Hunger Games - La ballata dell''usignolo e del serpente (The Hunger Games: The Ballad of Songbirds & Snakes)","de":"Die Tribute von Panem – The Ballad of Songbirds and Snakes","es":"Los Juegos del Hambre: Balada de pájaros cantores y serpientes"}'::jsonb, trame_i18n = '{"fr":"Le jeune Coriolanus est le dernier espoir de sa lignée, la famille Snow autrefois riche et fière est aujourd’hui tombée en disgrâce dans un Capitole d''après-guerre. À l’approche des 10e Hunger Games, il est assigné à contrecœur à être le mentor de Lucy Gray Baird, un tribut originaire du District 12, le plus pauvre et le plus méprisé de Panem. Le charme de Lucy Gray ayant captivé le public, Snow y voit l’opportunité de changer son destin, et va s’allier à elle pour faire pencher le sort en sa faveur. Luttant contre ses instincts, déchiré entre le bien et le mal, Snow se lance dans une course contre la montre pour survivre et découvrir s’il deviendra finalement un oiseau chanteur ou un serpent.","en":"64 years before he becomes the tyrannical president of Panem, Coriolanus Snow sees a chance for a change in fortunes when he mentors Lucy Gray Baird, the female tribute from District 12.","it":"Decenni prima di diventare il tirannico presidente di Panem, il diciottenne Coriolanus Snow viene assegnato come mentore a Lucy Gray Baird, il tributo del Distretto 12 per i decimi Hunger Games.","de":"Jahre bevor er der tyrannische Präsident von Panem werden würde, ist der 18-jährige Coriolanus Snow die letzte Hoffnung für seine verblassende Abstammung, eine einst stolze Familie, die in einem Nachkriegskapitol in Ungnade gefallen ist. Da die 10. jährlichen Hungerspiele immer näher rücken, ist der junge Snow alarmiert, als er als Mentor für Lucy Gray Baird eingesetzt wird, die Mädchenehrung aus dem verarmten Distrikt 12. Aber nachdem Lucy Gray die ganze Aufmerksamkeit von Panem auf sich gezogen hat, indem sie während der Erntezeremonie trotzig singt, glaubt Snow, dass er in der Lage sein könnte, die Chancen zu ihren Gunsten zu wenden. Snow und Lucy vereinen ihren Instinkt für Selbstdarstellung und ihr neu entdecktes politisches Geschick. Ihr Überlebensrennen gegen die Zeit beginnt, um letztendlich zu enthüllen, wer ein Singvogel und wer eine Schlange ist.","es":"Ambientada en un Panem postapocalíptico, nos traslada varias décadas antes del comienzo de las aventuras de Katniss Everdeen. El joven Coriolanus Snow será el mentor de Lucy Gray Baird, la chica elegida para ser homenajeada del empobrecido Distrito 12. La joven sorprenderá a todos cantando en la ceremonia de apertura de los Décimos Juegos del Hambre en los que Snow intentará aprovecharse de su talento y encanto para sobrevivir."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/q4EDvPcf956FgakWwcXiWdQEgxU.jpg","en":"https://image.tmdb.org/t/p/w500/mBaXZ95R2OxueZhvQbcEWy2DqyO.jpg","it":"https://image.tmdb.org/t/p/w500/bk2Bh5mD3uvyKDaXKTAOGfoCTq5.jpg","de":"https://image.tmdb.org/t/p/w500/itogxOvIcuF1pUQbfAaRTC74nCE.jpg","es":"https://image.tmdb.org/t/p/w500/2vIK81ikjvdewSLmrwIg7AMoJIv.jpg"}'::jsonb WHERE id = 206;
UPDATE public.films SET tmdb_id = 20352, titoli_i18n = '{"en":"Despicable Me","es":"Gru Mi villano favorito","it":"Cattivissimo me (Despicable Me)","fr":"Moi, moche et méchant","de":"Ich - Einfach unverbesserlich"}'::jsonb, trame_i18n = '{"en":"Determined to prove he''s the world''s greatest supervillain, Gru hatches an audacious plan to steal the Moon. To pull it off, he adopts three orphaned girls—Margo, Edith, and Agnes—intending to use them as pawns in his scheme. But the unexpected bond they form forces him to question the criminal life he''s always known.","es":"En una alegre urbanización con cuidados jardines rodeados por verjas de madera pintadas de blanco y llenos de rosales, sobresale una casa negra con el césped amarillento. Los vecinos ignoran que debajo de la vivienda hay un enorme escondite secreto. Allí está Gru, rodeado por un pequeño ejército de lacayos, planeando el mayor robo de toda la historia. ¡Va a hacerse con la luna!","it":"Il supercattivo Gru pianifica di rubare la Luna con l''aiuto dei suoi piccoli assistenti gialli, i Minions, ma il suo piano viene scompaginato dall''incontro con tre bambine orfane.","fr":"Dans un charmant quartier résidentiel délimité par des clôtures de bois blanc et orné de rosiers fleurissants se dresse une bâtisse noire entourée d’une pelouse en friche. Cette façade sinistre cache un secret : Gru, un méchant vilain, entouré d’une myriade de sous‐fifres et armé jusqu’aux dents, qui, à l’insu du voisinage, complote le plus gros casse de tous les temps : voler la lune (Oui, la lune !)… Gru affectionne toutes sortes de sales joujoux. Il possède une multitude de véhicules de combat aérien et terrestre et un arsenal de rayons immobilisants et rétrécissants avec lesquels il anéantit tous ceux qui osent lui barrer la route… jusqu’au jour où il tombe nez à nez avec trois petites orphelines qui voient en lui quelqu’un de tout à fait différent : un papa. Le plus grand vilain de tous les temps se retrouve confronté à sa plus dure épreuve : trois fillettes prénommées Margo, Édith et Agnès.","de":"Der verschrobene Gru führt ein zurückgezogenes Leben – unscheinbar lebt er in einer kleinen Nachbarschaft irgendeines Vorortes. Aber was seine Nachbarn nicht wissen: Er plant das größte Verbrechen der Menschheitsgeschichte und will den Mond klauen. Auf dem Vormarsch mit technisch raffinierten Waffen und von der Polizei nicht zu stoppen, findet er aber dann doch – vielleicht – seine Bezwinger. Drei Waisenmädchen entdecken in ihm einen potentiellen Vater. Ist es nun mit seinem Verbrecherleben vorbei … oder stiehlt er doch noch den Mond?"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg","es":"https://image.tmdb.org/t/p/w500/AsaaPLSfisdFDeasEd9r0GiZVss.jpg","it":"https://image.tmdb.org/t/p/w500/t6hBb0Iz8TkY6JNxaUCE30es3iT.jpg","fr":"https://image.tmdb.org/t/p/w500/wuhJx9bTbxHfJHeeR3L8uRjAZ7C.jpg","de":"https://image.tmdb.org/t/p/w500/tgQAiavJYM1vGcNVeKZHr35F4WB.jpg"}'::jsonb WHERE id = 207;
UPDATE public.films SET tmdb_id = 93456, titoli_i18n = '{"es":"Gru 2. Mi villano favorito","it":"Cattivissimo me 2 (Despicable Me 2)","de":"Ich - Einfach unverbesserlich 2","fr":"Moi, moche et méchant 2","en":"Despicable Me 2"}'::jsonb, trame_i18n = '{"es":"La película de animación de los estudios Universal, giraba en torno a una apacible y colorida población en la que vivía el malvado Gru. Ayudado por su batallón de Minions, unos pequeños seres de color amarillo, intentaron robar la Luna, aunque no todo acabó como esperaban. Tres niñas curiosas y algo traviesas se cruzaron en su camino, entorpeciéndole todos sus planes y conviertiendo su objetivo en una alocada hazaña interestelar.  Ahora, ''Gru, mi villano favorito 2'', narra una nueva aventura en la que Gru volverá a estar acompañado de simpáticos humanoides.","it":"Gru viene reclutato dalla Lega Anti-Cattivi per indagare sulla scomparsa di un laboratorio segreto e sulla trasformazione dei suoi Minions in mostri viola indistruttibili.","de":"Nachdem der Superschurke Gru die drei Waisenkinder Margo, Edith und Agnes adoptiert hat, hat sich in seinem Leben viel geändert. Anstatt als Griesgram Verbrechen zu begehen, dreht sich sein Leben nun um Gute-Nacht-Geschichten, Kindergeburtstage und erste Verehrer der Mädchen. Sein neues Leben wird plötzlich gestört, als Lucy, eine Agentin der geheimen Anti-Villain League, Gru gegen seinen Willen zu deren Zentrale führt. Dort bekommt Gru den Auftrag, die Welt vor einem neuen Bösewicht zu retten. Eifrig macht sich Gru ans Werk und bekommt dabei erneut Hilfe von Dr. Nefario  und seinen meist sehr tollpatschigen Minions. Doch seine neue Aufgabe mit der Erziehung seiner Adoptivtöchter in Einklang zu bringen ist nicht leicht und auch mit der Situation, dass Lucy auch außerhalb der Arbeit sehr von Gru angetan ist, überfordert den ehemaligen Einzelgänger.","fr":"Ayant abandonné la super‐criminalité et mis de côté ses activités funestes pour se consacrer à la paternité et élever Margo, Édith et Agnès, Gru, et avec lui, le Professeur Néfario et les Minions, doivent se trouver de nouvelles occupations. Alors qu’il commence à peine à s’adapter à sa nouvelle vie tranquille de père de famille, une organisation ultrasecrète, menant une lutte acharnée contre le Mal à l’échelle planétaire, vient frapper à sa porte. Soudain, c’est à Gru, et à sa nouvelle coéquipière Lucy, que revient la responsabilité de résoudre une série de méfaits spectaculaires. Après tout, qui mieux que l’ex plus méchant de tous les temps, pourrait attraper celui qui rivalise pour lui voler la place qu’il occupait encore récemment…","en":"Gru is recruited by the Anti-Villain League to help deal with a powerful new super criminal."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/hhksXOBVJ6Mu2BwAFgPJwZxNisd.jpg","it":"https://image.tmdb.org/t/p/w500/cAHjd4n5dmBnKf6eHcXbqi4CSrJ.jpg","de":"https://image.tmdb.org/t/p/w500/e9uMneUxEN8vb3lS2wU9Pie597B.jpg","fr":"https://image.tmdb.org/t/p/w500/PCd21fTyaJN9ge1MpYUfF5Zcmb.jpg","en":"https://image.tmdb.org/t/p/w500/5Fh4NdoEnCjCK9wLjdJ9DJNFl2b.jpg"}'::jsonb WHERE id = 208;
UPDATE public.films SET tmdb_id = 211672, titoli_i18n = '{"es":"Los minions","fr":"Les Minions","en":"Minions","de":"Minions","it":"Minions"}'::jsonb, trame_i18n = '{"es":"Los minions empezaron siendo organismos amarillos unicelulares que evolucionaron a través del tiempo, poniéndose siempre al servicio de los amos más despreciables. Ante su incapacidad para mantener a esos amos – desde el T. Rex a Napoleón –, los minions acaban encontrándose solos y caen en una profunda depresión. Sin embargo, uno de ellos, tiene un plan. Emprende un emocionante viaje para conseguir una jefa a quien servir, la terrible Scarlet Overkill. Pasarán de la helada Antártida, a la ciudad de Nueva York (Estados Unidos) en la década de 1960 para acabar en Londres (Reino Unido), donde deberán enfrentarse al mayor reto hasta la fecha: salvar a la raza ninion de la aniquilación.","fr":"À la nuit des temps des temps. À l’origine, de simples organismes monocellulaires de couleur jaune, les Minions ont évolué au cours des âges au service de maîtres plus abjects les uns que les autres. Les disparitions répétitives de ceux‐ci, des tyrannosaures à Napoléon, ont plongé nos mignons personnages dans une profonde dépression. Mais l’un d’eux, prénommé Kevin, a une idée. Flanqué de Stuart, l’adolescent rebelle et de l’adorable petit Bob, Kevin part à la recherche d’un nouveau patron malfaisant pour guider les siens. Nos trois Minions se lancent dans un palpitant voyage qui va les conduire à leur nouveau maître… qui s’avère être une maîtresse : Scarlet Overkill, la première super‐vilaine de l’histoire. De l’Antarctique au New York des années 60, nos trois compères arrivent finalement à Londres, à l’apogée des mods, où ils vont devoir faire face à la plus terrible menace de leur existence : l’annihilation de leur espèce.","en":"Minions Stuart, Kevin and Bob are recruited by Scarlet Overkill, a super-villain who, alongside her inventor husband Herb, hatches a plot to take over the world.","de":"Seit dem Anfang des Anfang gab es die Minions schon: kleine, gelbe Helferlein, deren einziger Existenzgrund ist, einem Bösewicht zu Diensten zu stehen. Als all ihre Meister jedoch zerstört wurden, zogen sie sich in die Antarktis zurück und verharrten dort viele, viele Jahre in Depression - bis schließlich in den Sechziger Jahren der mutigste Minion und zwei Gefährten den Entschluss fassen, einen neuen Meister finden zu gehen. Und so machen sie sich auf zu einer Bösewicht-Convention. Dort laufen sie der verrückten Super-Bösewichtin Scarlett Overkill und ihrem Ehemann, dem Wissenschaftler Herb Overkill in die Arme. Sie will die erste weibliche Oberbösewichtin werden und die kleinen gelben Helferlein für ihre finsteren Pläne missbrauchen.","it":"Evolutisi da organismi unicellulari gialli, i Minions cercano disperatamente un padrone malvagio da servire. Nel 1968, Kevin, Stuart e Bob partono per una missione che li condurrà da Scarlet Sterminator."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/nmqLwaTfgyWLQWbYd82w159cAqJ.jpg","fr":"https://image.tmdb.org/t/p/w500/sGuZHYvu0mXeQCwvJ5yzk2Yoytq.jpg","en":"https://image.tmdb.org/t/p/w500/dr02BdCNAUPVU07aOodwPYv6HCf.jpg","de":"https://image.tmdb.org/t/p/w500/4WdMdylQUwF534UU5FXHocCbw6e.jpg","it":"https://image.tmdb.org/t/p/w500/bQ92zNRkeD7SL2awyHPsC5PCjkF.jpg"}'::jsonb WHERE id = 209;
UPDATE public.films SET tmdb_id = 324852, titoli_i18n = '{"it":"Cattivissimo me 3 (Despicable Me 3)","de":"Ich - Einfach unverbesserlich 3","fr":"Moi, moche et méchant 3","es":"Gru 3. Mi villano favorito","en":"Despicable Me 3"}'::jsonb, trame_i18n = '{"it":"Dopo essere stato licenziato dalla Lega Anti-Cattivi, Gru scopre di avere un fratello gemello ricco e stravagante di nome Dru, mentre i Minions affrontano una breve ribellione.","de":"Der einstmals finstere Gru hat sich im zweiten Teil in Agentin Lucy Wilde verguckt und aus Liebe zu ihr und seinen drei Adoptivtöchtern Margo, Edith und Agnes die Seiten gewechselt: Gemeinsam mit seiner Angetrauten bekämpft er nun Bösewichte. Zu diesen gehört auch Balthazar Bratt, ein Super-Bösewicht und 80er-Jahre-Fan mit Schulterpolstern und Vokuhila, der hinter einem riesigen rosa Diamanten her ist. Während Gru mit der Jagd auf Bratt beschäftigt ist, bekommt er Besuch von seinem Zwillingsbruder Dru. Dieser hat nicht nur volles Haar, sondern ist auch noch erfolgreicher und selbstbewusster als Gru, der nicht mal seine Minions unter Kontrolle hat – und das nervt diesen gewaltig! Doch dann holt Balthazar Bratt zu einem teuflischen Schlag aus und die ungleichen Brüder müssen sich zusammenraufen, um die Welt zu retten.","fr":"Après avoir été licencié de la Ligue Anti‐Villain pour avoir échoué à capturer le dernier méchant capable de menacer l’humanité, Gru se trouve confronté à une crise d’identité majeure. Mais quand se présente un étranger mystérieux qui l’informe du décès de son père mais aussi de l’existence d’un frère jumeau – un frère qui veut désespérément suivre les traces méprisables de son jumeau – un ancien super‐méchant va redécouvrir à quel point c’est bon d’être mauvais.","es":"A Gru lo han despedido. Se ha quedado sin trabajo porque ha dejado escapar al supervillano Balthazar Bratt, estrella infantil de los años 80 que con la llegada de la pubertad lo perdió todo y ha estado creando el caos en todo el planeta.  Además, Gru va a conocer a su hermano gemelo Dru y tendrá que decidir si está listo para continuar la tradición familiar de dedicarse al crimen, y unirse a el para llevar a cabo un último golpe. Aunque ha dejado esa vida atrás… ¿volverá a convertirse Gru en un villano?","en":"Gru and his wife Lucy must stop former ''80s child star Balthazar Bratt from achieving world domination."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/w5UQOIVconX1rmmGgUch9a1SMuG.jpg","de":"https://image.tmdb.org/t/p/w500/f2QpHiuMjQ5J9olQVIJBDLV8Hr4.jpg","fr":"https://image.tmdb.org/t/p/w500/sXRCdFPzlQeRGPO6wWhCOnVI0wR.jpg","es":"https://image.tmdb.org/t/p/w500/mz3zTmsnySgFWGc3ZsBbCQbalut.jpg","en":"https://image.tmdb.org/t/p/w500/e72KCMHNkbZ6USRJmABeqwmaJ5n.jpg"}'::jsonb WHERE id = 210;
UPDATE public.films SET tmdb_id = 438148, titoli_i18n = '{"it":"Minions 2 - Come Gru diventa cattivissimo (Minions: The Rise of Gru)","en":"Minions: The Rise of Gru","es":"Minions: El origen de Gru","fr":"Les Minions 2 : Il était une fois Gru","de":"Minions - Auf der Suche nach dem Mini-Boss"}'::jsonb, trame_i18n = '{"it":"Negli anni ''70, il dodicenne Gru tenta di entrare a far parte di un gruppo di supercattivi chiamato I Malefici 6. Quando il suo colloquio va male, i Minions intervengono per aiutarlo.","en":"A fanboy of a supervillain supergroup known as the Vicious 6, Gru hatches a plan to become evil enough to join them, with the backup of his followers, the Minions.","es":"En la década de 1970, Gru crece siendo un gran admirador de \"Los salvajes seis\", un supergrupo de villanos. Para demostrarles que puede ser malvado, diseña un plan con la esperanza de formar parte de la banda.","fr":"Alors que les années 70 battent leur plein, Gru qui grandit en banlieue au milieu des jeans à pattes d’éléphants et des chevelures en fleur, met sur pied un plan machiavélique à souhait pour réussir à intégrer un groupe célèbre de super méchants, connu sous le nom de Vicious 6, dont il est le plus grand fan. Il est secondé dans sa tâche par les Minions, ses petits compagnons aussi turbulents que fidèles. Avec l’aide de Kevin, Stuart, Bob et Otto – un nouveau Minion arborant un magnifique appareil dentaire et un besoin désespéré de plaire – ils vont déployer ensemble des trésors d’ingéniosité afin de construire leur premier repaire, expérimenter leurs premières armes, et lancer leur première mission. Gru passe l’audition pour intégrer l’équipe. Le moins qu’on puisse dire c’est que l’entrevue tourne mal, et soudain court quand Gru leur démontre sa supériorité et se retrouve soudain leur ennemi juré.","de":"In den 70er-Jahren, lange bevor er zu einem Meister des Bösen aufsteigt, ist Gru einfach ein zwölfjähriger Vorstadtjunge, der in seinem Keller von der Weltherrschaft träumt. Als die berüchtigte Schurkenbande \"Die fiesen 6\" ihren Anführer rauswirft, bewirbt Gru sich um dessen Nachfolge, endet alsbald jedoch als Todfeind der Bande. Während Gru fliehen muss, lernen die Minions Kampfsport, um ihn zu retten, und Gru findet heraus, dass selbst Schurken manchmal ein bisschen Hilfe von ihren Freunden gebrauchen können."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/qfJeCjOVYYfy8uYqF711qV8Usqe.jpg","en":"https://image.tmdb.org/t/p/w500/4dBDk1LPdvdhcZdjQBmdXwiVKUA.jpg","es":"https://image.tmdb.org/t/p/w500/fzwG3cukayxKpCK0lqS1jkSBqJk.jpg","fr":"https://image.tmdb.org/t/p/w500/pA05WmBZLEu32peDDh3I4VuVPsu.jpg","de":"https://image.tmdb.org/t/p/w500/nHJDZsad536CYI6RK9n97rNjqUN.jpg"}'::jsonb WHERE id = 211;
UPDATE public.films SET tmdb_id = 519182, titoli_i18n = '{"es":"Gru 4. Mi villano favorito","it":"Cattivissimo me 4 (Despicable Me 4)","en":"Despicable Me 4","fr":"Moi, moche et méchant 4","de":"Ich - Einfach unverbesserlich 4"}'::jsonb, trame_i18n = '{"es":"Gru, Lucy y las niñas -Margo, Edith y Agnes- dan la bienvenida a un nuevo miembro en la familia: Gru Junior, que parece llegar con el propósito de ser un suplicio para su padre. Gru tendrá que enfrentarse en esta ocasión a su nueva némesis Maxime Le Mal y su sofisticada y malévola novia Valentina, lo que obligará a la familia a tener que darse a la fuga. Cuarta entrega de ''Gru, mi villano favorito''.","it":"Gru, Lucy e le loro figlie accolgono un nuovo membro in famiglia, Gru Jr., ma sono costretti alla fuga quando il supercriminale Maxime Le Mal evade di prigione per vendicarsi.","en":"Gru and Lucy and their girls—Margo, Edith and Agnes—welcome a new member to the Gru family, Gru Jr., who is intent on tormenting his dad. Gru also faces a new nemesis in Maxime Le Mal and his femme fatale girlfriend Valentina, forcing the family to go on the run.","fr":"Gru, Lucy et les filles, Margo, Édith et Agnès accueillent le petit dernier de la famille, Gru Junior, qui semble n’avoir qu’une passion : faire tourner son père en bourrique. Mais Gru est confronté à un nouvel ennemi, Maxime Le Mal, qui avec l’aide de sa petite amie, la fatale Valentina, va obliger toute la famille à fuir.","de":"Ein ehemaliger Erzschurke verwandelt sich in einen Vorstadtvater – eine Veränderung, die Gru widerfährt, nachdem er bei einem Klassentreffen auf seinen größten Widersacher stößt, ein Konflikt ausbricht und er sich gezwungen sieht, unterzutauchen. Doch die ungestörte Idylle findet ein jähes Ende, als Baby Gru Junior entführt wird. Zusammen mit seiner Familie begibt sich Gru auf eine abenteuerliche und verrückte Rettungsmission. Im Team sind auch die Minions, die durch ein Superserum in fünf Mega Minions mit einzigartigen Kräften verwandelt wurden und für noch mehr Chaos sorgen!"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/b6JX0fBne5yPFNBtdp4Imi3CpiE.jpg","it":"https://image.tmdb.org/t/p/w500/gIV7DbvWUwPN4lxSk3dMNkXzgX7.jpg","en":"https://image.tmdb.org/t/p/w500/wWba3TaojhK7NdycRhoQpsG0FaH.jpg","fr":"https://image.tmdb.org/t/p/w500/bYovCvLV1RxB0zAR5cXu699P9P7.jpg","de":"https://image.tmdb.org/t/p/w500/t8fh33Rx3YithmYJ2xqAjdVsBUh.jpg"}'::jsonb WHERE id = 212;
UPDATE public.films SET tmdb_id = 205775, titoli_i18n = '{"en":"In the Heart of the Sea","fr":"Au cœur de l''Océan","de":"Im Herzen der See","es":"En el corazón del mar","it":"Heart of the Sea - Le origini di Moby Dick (In the Heart of the Sea)"}'::jsonb, trame_i18n = '{"en":"In the winter of 1820, the New England whaling ship Essex is assaulted by something no one could believe—a whale of mammoth size and will, and an almost human sense of vengeance.","fr":"À l''hiver 1820, le baleinier Essex, originaire de Nouvelle-Angleterre, est attaqué par une créature redoutable : une baleine aux dimensions hors normes et à la volonté de fer qui semble animée par une terrible soif de vengeance.  Cette catastrophe maritime inspirera \"Moby Dick\" d''Herman Melville. Mais cet ouvrage n''a pas relaté l''intégralité des événements. \"Au cœur de l''océan\" s''attache aux conséquences épouvantables de ce désastre, alors que les survivants de l''équipage sont acculés et contraints de commettre l''impensable pour rester en vie. Affrontant les tempêtes, la faim, la panique et le désespoir, ces hommes remettent en question leurs convictions les plus profondes et leurs valeurs morales, tandis que le capitaine du navire cherche à retrouver le cap et que son second croit encore pouvoir mater l''énorme mammifère qui les a pris pour cible…","de":"1820 wird ein Walfängerschiff, die Essex, von einem riesigen Wal angegriffen. Das Ungewöhnliche daran ist, dass das Tier aus einem bisher nur Menschen zugeschriebenen Vergeltungsdrang angetrieben zu sein scheint. Die Essex entgeht nur knapp dem Untergang und ein großer Teil der Besatzung kommt ums Leben. Doch damit ist der Alptraum noch nicht vorbei, denn nun muss es das Schiff erst einmal wieder ans sichere Ufer schaffen. Die Besatzung, zerrüttet durch den Verlust der Kameraden, steht vor einer schwierigen Aufgabe: Der unerfahrene Kapitän George Pollard  versucht, in den tobenden Gewässern einen sicheren Kurs in die Heimat zu bestimmen, während der abgebrühte erste Offizier Owen Chase nur auf Rache gegen den Wal sinnt. 30 Jahre nach den Ereignissen recherchiert Autor Herman Melville das Schicksal der Essex und schreibt ein Buch darüber - den Klassiker \"Moby Dick\"...","es":"En el invierno de 1820, el ballenero de Nueva Inglaterra Essex fue agredido por algo a lo que nadie podía dar crédito: una ballena de tamaño y voluntad descomunal, con un sentido de la venganza casi humano. Este hecho real que supuso un desastre marítimo fue la inspiración para Moby-Dick de Melville. Pero la novela solo contó la mitad de la historia. “En el corazón del mar” revela las horribles consecuencias del encuentro, cuando los supervivientes de la tripulación fueron forzados hasta el límite y se vieron obligados a hacer lo impensable para mantenerse vivos. Enfrentándose a las tormentas, el hambre, el pánico, y la desesperación, los hombres llegan a dudar hasta de sus creencias más profundas, desde el valor de sus vidas a la moralidad de su oficio, mientras el capitán intenta orientarse en el mar abierto y su primer oficial sigue empeñado en conquistar a la gran ballena.","it":"Nel inverno del 1820, la baleniera del New England Essex viene assalita da una creatura incredibile: una balena dalle dimensioni e dalla forza mastodontiche, con un senso quasi umano di vendetta. Il disastro marittimo realmente accaduto avrebbe ispirato Herman Melville a scrivere Moby Dick."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/weVvNPfk6FM9vBg3BXtRtNAmiYM.jpg","fr":"https://image.tmdb.org/t/p/w500/dRQPhD7RUMa290dzQtmu0NFobvR.jpg","de":"https://image.tmdb.org/t/p/w500/rvT4BXWwq2ReNmCNuOo1tBit3VX.jpg","es":"https://image.tmdb.org/t/p/w500/ajcrkYTl8p55LGXYfGzx4d5XIco.jpg","it":"https://image.tmdb.org/t/p/w500/wAN0GViqoyT1616y1fBq0hNB2HR.jpg"}'::jsonb WHERE id = 213;
UPDATE public.films SET tmdb_id = 146233, titoli_i18n = '{"es":"Prisioneros","it":"Prisoners","en":"Prisoners","fr":"Prisoners","de":"Prisoners"}'::jsonb, trame_i18n = '{"es":"Keller Dover se enfrenta a la peor de las pesadillas: Anna, su hija de seis años, ha desaparecido con su amiga Joy y, a medida que pasa el tiempo, el pánico lo va dominando. Desesperado, decide ocuparse personalmente del asunto. Pero, ¿hasta dónde está dispuesto a llegar para averiguar el paradero de su hija?","it":"Dopo la scomparsa della figlia di sei anni e della sua amica durante il Giorno del Ringraziamento, Keller Dover affronta il peggior incubo di ogni genitore. Il detective Loki guida le indagini e arresta l''unico sospettato, ma è costretto a rilasciarlo per mancanza di prove. Preso dalla disperazione e vedendo la polizia brancolare nel buio, Keller decide di farsi giustizia da solo, spingendosi oltre ogni limite pur di salvare le bambine.","en":"After his six-year-old daughter is abducted, a desperate father takes justice into his own hands when he loses faith in the detective leading the investigation, setting both men on a collision course as the search descends into obsession and moral compromise.","fr":"Dans la banlieue de Boston, deux fillettes de 6 ans, Anna et Joy, ont disparu. Le détective Loki privilégie la thèse du kidnapping suite au témoignage de Keller, le père d’Anna. Le suspect numéro 1 est rapidement arrêté mais est relâché quelques jours plus tard faute de preuve, entrainant la fureur de Keller. Aveuglé par sa douleur, le père dévasté se lance alors dans une course contre la montre pour retrouver les enfants disparus. De son côté, Loki essaie de trouver des indices pour arrêter le coupable avant que Keller ne commette l’irréparable… Les jours passent et les chances de retrouver les fillettes s’amenuisent…","de":"Keller Dover ist ein bibeltreuer Kriegsveteran. Der harte Kerl steht mit beiden Beinen fest im Leben. Dovers Welt gerät jedoch aus den Fugen, als seine sechsjährige Tochter Anna und deren Freundin Joy an Thanksgiving entführt werden. Es beginnt eine fieberhafte Suche, die von dem jungen und ambitionierten Detektiv Loki angeführt wird, dessen primäres Ziel es jedoch ist, endlich der Kleinstadt zu entfliehen und in eine Großstadt versetzt zu werden. Alle Spuren zu der Entführung verlaufen im Nichts. Auch den einzigen Verdächtigen, den geistig zurückgebliebenen Alex Jones, muss Loki aus Mangel an Beweisen wieder laufen lassen. Familienvater Dover fasst daraufhin einen folgenschweren Entschluss: Er will die Wahrheit auf eigene Faust herausfinden und begibt sich auf einen verhängnisvollen und gnadenlosen Weg der Selbstjustiz um die beiden kleinen Mädchen vielleicht doch noch zu finden."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/i6CcmOvJxBFH3mfhCHa3Njtelix.jpg","it":"https://image.tmdb.org/t/p/w500/h1rj4wTATjxeqFMtEOuZyk1czis.jpg","en":"https://image.tmdb.org/t/p/w500/uhviyknTT5cEQXbn6vWIqfM4vGm.jpg","fr":"https://image.tmdb.org/t/p/w500/fUk1f0iOAezl5PZ7gQW6nrguOXk.jpg","de":"https://image.tmdb.org/t/p/w500/d7DS20nwYT6WzbN2IvTvXvKPWjT.jpg"}'::jsonb WHERE id = 214;
UPDATE public.films SET tmdb_id = 10376, titoli_i18n = '{"en":"The Legend of 1900","es":"La leyenda del pianista en el océano","de":"Die Legende vom Ozeanpianisten","fr":"La Légende du pianiste sur l''océan","it":"La leggenda del pianista sull''oceano (The Legend of 1900)"}'::jsonb, trame_i18n = '{"en":"Musician Max Tooney goes to sell his prized Conn trumpet to a music shop, where he plays the instrument one last time. The shopkeeper recognises the song as one on a record matrix he found and asks who the piece is by. Tooney tells the story of an infant found abandoned in the first class dining room of the four-stacker ocean-liner SS Virginian on 1 January 1900. Danny Boodman, a coal-man from the boiler room, names the boy Danny Boodman T. D. Lemon 1900, after himself, the fruit crate the boy was found in, and the year, and raises him as his own.","es":"Historia de un niño que fue abandonado sobre el piano del Virginia, un enorme trasatlántico. El niño es adoptado por un maquinista y le pone por nombre \"Novecento\", ya que lo encuentra justo en el cambio de siglo. Novecento se convertirá en un fabuloso pianista y amenizará las noches del Virginia. Pero nunca pisará tierra firme, ni tan sólo tras las súplicas de su amigo Max.","de":"Im Jahre 1900 findet der Seemann Danny Boodmann eine Kiste mit der Aufschrift \"T.D. Lemon\" in der sich ein Baby befindet, das er folglich Danny Boodmann T.D. Lemon 1900 nennt. Der kleine Junge wird im Heizraum des Schiffes grossgezogen und entwickelt sich zu einem der besten Pianisten.","fr":"À bord du \"Virginian\", paquebot de croisière, Danny, un mécanicien, découvre un nouveau-né abandonné dans la salle de bal désertée. Il décide de l''élever et le baptise du nom de 1900.  À la mort de Danny, l''enfant, adopté par l''équipage, grandit sur le navire, voguant d''un continent à l''autre. Un jour, 1900 s''assoit au piano et révèle un don extraordinaire pour la musique. Adulte, il devient un pianiste virtuose. Les plus grands jazzmen lui rendent visite. 1900 refuse de quitter le navire.\r Jusqu''au jour où celui-ci est promis à la démolition.","it":"La storia di Danny Boodmann T.D. Lemon Novecento, un pianista straordinario nato e cresciuto a bordo del transatlantico Virginian, senza mai mettere piede sulla terraferma. La sua vita e il suo incredibile talento vengono raccontati dal suo grande amico, il trombettista Max Tooney."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/iOcbJ5pxokOPDRgieVDbsFMrCc6.jpg","es":"https://image.tmdb.org/t/p/w500/8rttNpb83qdHFMPMgFlcspVGaio.jpg","de":"https://image.tmdb.org/t/p/w500/kYFOxIiEvxJxI8BMO1oNghKjSPw.jpg","fr":"https://image.tmdb.org/t/p/w500/tamGferK68ppVyOrM8jiqF5vbjJ.jpg","it":"https://image.tmdb.org/t/p/w500/8rttNpb83qdHFMPMgFlcspVGaio.jpg"}'::jsonb WHERE id = 216;
UPDATE public.films SET tmdb_id = 115036, titoli_i18n = '{"it":"The Book of Boba Fett","en":"The Book of Boba Fett","fr":"Le Livre de Boba Fett","es":"El libro de Boba Fett","de":"Das Buch von Boba Fett"}'::jsonb, trame_i18n = '{"it":"Il leggendario cacciatore di taglie Boba Fett e la mercenaria Fennec Shand tornano sulle sabbie di Tatooine per rivendicare il territorio un tempo controllato da Jabba the Hutt e dal suo sindacato criminale.","en":"Legendary bounty hunter Boba Fett and mercenary Fennec Shand must navigate the galaxy’s underworld when they return to the sands of Tatooine to stake their claim on the territory once ruled by Jabba the Hutt and his crime syndicate.","fr":"Après s’être hasardés dans les bas-fonds de la galaxie, le légendaire chasseur de primes et la mercenaire Fennec Shand reviennent au milieu des dunes de Tatooine pour y revendiquer le territoire autrefois dirigé par Jabba le Hutt et son syndicat du crime.","es":"El legendario cazarrecompensas Boba Fett y la mercenaria Fennec Shand deben navegar por el inframundo de la galaxia cuando regresen a las arenas de Tatooine para reclamar el territorio que una vez gobernó Jabba el Hutt y su sindicato del crimen.","de":"Der Kopfgeldjäger Boba Fett und der Söldner Fennec Shand reisen durch die Unterwelt der Galaxis."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/lQqbnWsGt9RBGBWrmUKUOXZkl7N.jpg","en":"https://image.tmdb.org/t/p/w500/gNbdjDi1HamTCrfvM9JeA94bNi2.jpg","fr":"https://image.tmdb.org/t/p/w500/bumvJZvV3p98VOvdkGIkGVz6utk.jpg","es":"https://image.tmdb.org/t/p/w500/4bffB2YV4UxNfEifp4HxdhfJulK.jpg","de":"https://image.tmdb.org/t/p/w500/fz9fn1Aa4PkAEH6eSe39mBPQEqF.jpg"}'::jsonb WHERE id = 217;
UPDATE public.films SET tmdb_id = 114166, titoli_i18n = '{"en":"Quo Vadis?","de":"Quo Vadis?","es":"Quo Vadis?","it":"Quo Vadis?","fr":"Quo Vadis?"}'::jsonb, trame_i18n = '{"en":"During the latter years of the reign of the tyrannical Roman emperor Nero, Marcus Vinicius, one of Nero''s officers, falls in love with a young Christian named Lygia, attempting to enslave her. Lygia''s protector, the noble and  burly Ursus, works to save her from Vinicius'' clutches. Pursuing Lygia, Vinicius finds himself at a catacomb prayer meeting led by the apostle Peter and finds his conscience stirring-- just as Nero orders Rome burned. A landmark in epic film, Enrico Guazzoni’s grand-scale masterpiece laid the foundations for what colossal Italian spectacles would become. The film had tremendous influence on Giovanni Pastrone’s Cabiria (1914) and D.W. Griffith’s Intolerance (1916).","it":"Nella Roma dell''imperatore Nerone, il giovane tribuno Marco Vinicio si innamora della cristiana Licia. Tra intrighi di corte, l''incendio della città e il martirio dei primi cristiani, il loro amore affronterà terribili prove."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg","de":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg","es":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg","it":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg","fr":"https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg"}'::jsonb WHERE id = 219;
UPDATE public.films SET tmdb_id = 184499, titoli_i18n = '{"it":"Quo Vadis?","es":"Quo Vadis?","en":"Quo Vadis?","de":"Quo Vadis?","fr":"Quo Vadis?"}'::jsonb, trame_i18n = '{"en":"\"The Roman Banquet, the golden glories, the unrivaled luxuries, the wine, the dance, the song, the beautiful women, the sumptuous splendors that taxed a barbaric world for a night of feasting and revel-- Re-created for your entertainment in the most colossal drama produced\", reads an ad in the Daily Argus of New York. Unione Cinematografica Italiana''s lavish production of the oft-told tale stars Emil Jannings as Nero.","it":"Imponente kolossal muto che mette in scena la follia dell''imperatore Nerone e il tragico destino dei primi cristiani a Roma, intrecciato con la storia d''amore tra Marco Vinicio e la giovane Licia."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","es":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","en":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","de":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","fr":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg"}'::jsonb WHERE id = 220;
UPDATE public.films SET tmdb_id = 11620, titoli_i18n = '{"it":"Quo Vadis","fr":"Quo Vadis","es":"Quo Vadis","de":"Quo Vadis","en":"Quo Vadis"}'::jsonb, trame_i18n = '{"it":"Di ritorno dalle campagne militari, il comandante romano Marco Vinicio si innamora della cristiana Licia. Quando l''imperatore Nerone incendia Roma e accusa i cristiani, la coppia viene travolta dalle persecuzioni.","fr":"À Rome, le général Marcus Vinicius rencontre Lygia, une esclave, dont il tombe amoureux. Mais elle est chrétienne et ne veut rien avoir à faire avec un homme de guerre. Marcus la rachète pourtant à l''empereur Néron, mais elle s''échappe avec l''aide d''un ami. En la retrouvant, Marcus va apprendre à connaître les Chrétiens.","es":"Cuando regresa a Roma, después de tres años en el campo de batalla, el general Marco Vinicio se enamora de Lygia. Pero ella es cristiana y sus creencias le impiden enamorarse de un guerrero. Aunque fue adoptada por un general retirado, jurídicamente es una esclava de Roma. Pero Marco consigue que el emperador Nerón se la ceda en pago por sus servicios.","de":"Rom brennt. Nero spielt dazu auf der Leier. Das Christentum strebt empor.. Robert Taylor spielt den Kommandanten einer Legion, dessen Liebe zu einer christlichen Sklavin die Kluft zwischen Römischem Reich und der zutiefst im Glauben verwurzelten Religionsgemeinschaft überbrückt. Und über allem waltet Nero . Er ist Caesar, Verrückter, Mörder ein kaiserlicher Gebieter über die spektakuläre, dem Untergang geweihte Pracht, die Rom einst war.","en":"After fierce Roman commander Marcus Vinicius becomes infatuated with beautiful Christian hostage Lygia, he begins to question the tyrannical leadership of the despotic emperor Nero."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/5fU3X1zTK5fL5rfAHWfzi06STVN.jpg","fr":"https://image.tmdb.org/t/p/w500/gBDK3a9krq7iDJzFzq1g3avK4n8.jpg","es":"https://image.tmdb.org/t/p/w500/4O7Jb5jtoAttqzhZCSwicjAWrQw.jpg","de":"https://image.tmdb.org/t/p/w500/hMNtH77NvAAMtlEInbuxJ7OJO7m.jpg","en":"https://image.tmdb.org/t/p/w500/dqF1dattMNiwGjPSphu2VSi558Q.jpg"}'::jsonb WHERE id = 221;
UPDATE public.films SET tmdb_id = 184499, titoli_i18n = '{"es":"Quo Vadis?","en":"Quo Vadis?","fr":"Quo Vadis?","it":"Quo Vadis?","de":"Quo Vadis?"}'::jsonb, trame_i18n = '{"en":"\"The Roman Banquet, the golden glories, the unrivaled luxuries, the wine, the dance, the song, the beautiful women, the sumptuous splendors that taxed a barbaric world for a night of feasting and revel-- Re-created for your entertainment in the most colossal drama produced\", reads an ad in the Daily Argus of New York. Unione Cinematografica Italiana''s lavish production of the oft-told tale stars Emil Jannings as Nero.","it":"Adattamento televisivo del capolavoro di Henryk Sienkiewicz che racconta l''ascesa del cristianesimo nella Roma imperiale e la deriva tirannica e folle di Nerone."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","en":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","fr":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","it":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg","de":"https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg"}'::jsonb WHERE id = 222;
UPDATE public.films SET tmdb_id = 59219, titoli_i18n = '{"it":"Quo Vadis","es":"Quo Vadis","en":"Quo Vadis","fr":"Quo Vadis","de":"Quo Vadis"}'::jsonb, trame_i18n = '{"es":"Siglo I d.C.. El oficial romano Marco Vinicio regresa de la guerra en Asia Menor y visita a su tío Petronio, amigo del emperador Nerón. Vinicio le confiesa que se ha enamorado de una joven misteriosa, Ligia, a quien ha conocido en la casa del general Aulus Plaucius. En una fiesta, Vinicio trata de aprovecharse de Ligia, pero su protector, el gigantesco Ursus, la saca de palacio y la lleva al lugar donde se reúnen los cristianos. Cuando Ligia es acusada de haber asesinado a la hija de Nerón, Vinicio la busca en las catacumbas. Pero la vida de los cristianos peligra al ser acusados de haber provocado el incendio de Roma, ordenado en realidad por el emperador.","en":"Ancient Rome, during the time of Emperor Nero. Vinicius, a young patrician, falls in love with the beautiful Lygia, the daughter of a Barbarian commander who was killed in battle, and wants her for his concubine. For Lygia, a Christian, being a pagan''s concubine is a severe sin and disgrace. However, when Vinicius is wounded, Lygia cares for him, and starts to reciprocate his feelings. Vinicius, in return, becomes interested in Christian learning and asks Apostle Peter to teach him. In the meantime, Emperor Nero accuses Christians of having started a great fire in Rome. He encourages the imprisonment, torture and murder of his Christian subjects.","fr":"Marcus Vinicius rencontre Lygia à Rome et en tombe amoureux. Mais Ligia est chrétienne et ne veut rien avoir à faire avec lui. Il décide de la kidnapper mais Ursus, son garde du corps l''en empêche. Lygia, l''apprenant, tombe à son tour sous le charme de Marcus mais celui-ci doit voir Néron. Après leur entretien, Marcus rentre chez. Mais il apprend que Néron est en train de brûler Rome et décide d''y retourner et de sauver Lygia.","de":"Im Zentrum der Handlung steht die sich entwickelnde Liebe eines römischen Patriziers zu einer christlichen Jungfrau vom Volk der Lygier (Gebiet des späteren Polen), die im Kontext grausamer Christenverfolgungen unter Kaiser Nero zur inneren Bekehrung und zur Taufe führt.","it":"Produzione polacca ad alto budget altamente fedele al romanzo originale, centrata sul contrasto tra la decadenza edonistica della Roma di Nerone e la nascente fede dei primi cristiani."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg","es":"https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg","en":"https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg","fr":"https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg","de":"https://image.tmdb.org/t/p/w500/pDFO2YF2xetOd8bhmBrMpcDnbMK.jpg"}'::jsonb WHERE id = 223;
UPDATE public.films SET tmdb_id = 967, titoli_i18n = '{"it":"Spartacus","es":"Espartaco","en":"Spartacus","fr":"Spartacus","de":"Spartacus"}'::jsonb, trame_i18n = '{"it":"Nel I secolo a.C., il gladiatore trace Spartaco guida una vasta ribellione di schiavi contro la Repubblica romana. Dopo aver sconfitto diverse legioni e radunato migliaia di seguaci in cerca di libertà, l''esercito dei ribelli si scontra con le ambizioni politiche del patrizio Marco Licinio Crasso, determinato a schiacciare la rivolta per consolidare il proprio potere su Roma.","es":"Hacia el año 75 antes de Cristo, un esclavo llamado Espartaco es vendido a una escuela de gladiadores donde le adiestran para combatir en la arena de los circos romanos. Pronto, Espartaco lidera una rebelión por el maltrato sufrido.","en":"The rebellious Thracian Spartacus, born and raised a slave, is sold to Gladiator trainer Batiatus. After weeks of being trained to kill for the arena, Spartacus turns on his owners and leads the other slaves in rebellion. As the rebels move from town to town, their numbers swell as escaped slaves join their ranks. Under the leadership of Spartacus, they make their way to southern Italy, where they will cross the sea and return to their homes.","fr":"Italie, 73 av. J.C. Esclave devenu gladiateur, Spartacus est épargné par un de ses compagnons d''infortune dans un combat à mort. Ce répit soulève en lui plus que jamais le souffle de la révolte, et après avoir brisé ses chaînes, il enjoint les autres esclaves à faire de même. Rapidement à la tête d''une colossale armée, Spartacus entend rejoindre le port de Brides au sud du pays pour prendre la mer à bord des navires ciliciens. Mais l''Empire romain ne l''entend pas de cette oreille et lance ses légions à la poursuite des esclaves révoltés…","de":"Die Gladiatoren von Capua kämpfen in der Arena auf Leben und Tod zur reinen Belustigung der römischen Herrscher. Die Exekutierung eines der Sklaven durch Prätor Crassus ist für den unerschrockenen Gladiator Spartacus das Zeichen zur Rebellion. Er fasst den wahnwitzigen Entschluss, mit der ihn liebenden Sklavin Varinia  und den Sklaven des Landes in ihre Heimatländer zurückzukehren. Spartacus formiert ein ganzes Heer, um in die Freiheit zu ziehen. Aber der machthungrige Crassus, der das Römische Imperium bedroht sieht, schickt seine Legionen gegen den Rebellen und seine Armee aus. Eine blutige Schlacht beginnt."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/lHxOu8Gp1urxHgtS4o0AywrniG1.jpg","es":"https://image.tmdb.org/t/p/w500/azXoEA108BvWjeKxIW9tfYlxY2I.jpg","en":"https://image.tmdb.org/t/p/w500/xLPpQlFWE12cbqNJQ5Vf4eJU8ij.jpg","fr":"https://image.tmdb.org/t/p/w500/7jIkNQenhZdiGRcwMk8w9KhwFi6.jpg","de":"https://image.tmdb.org/t/p/w500/lCtMmNvW4VYIohi7UuVM30rl3xN.jpg"}'::jsonb WHERE id = 224;
UPDATE public.films SET tmdb_id = 616, titoli_i18n = '{"it":"L''ultimo samurai (The Last Samurai)","es":"El último samurái","en":"The Last Samurai","de":"Last Samurai","fr":"Le Dernier Samouraï"}'::jsonb, trame_i18n = '{"it":"Nel 1876 il veterano della guerra civile americana Nathan Algren viene assoldato dall''imperatore giapponese per addestrare il nuovo esercito secondo i metodi occidentali e sedare la ribellione guidata dal samurai Katsumoto. Catturato dai ribelli, Algren scopre il loro stile di vita e il codice d''onore dei samurai, finendo per abbracciare la loro causa contro la modernizzazione forzata e spietata del Paese.","es":"1870. El capitán Nathan Algren es un hombre a la deriva. Las batallas que libró en otro tiempo parecen ahora lejanas e inútiles. Una vez arriesgó su vida por el honor y por la patria, pero, en los años transcurridos desde la Guerra de Secesión estadounidense, el mundo ha cambiado. El pragmatismo ha reemplazado al valor, el interés personal ha ocupado el lugar del sacrificio y el honor no se encuentra en ninguna parte, especialmente en el Oeste, donde su papel en las campañas contra los indios acabó en desilusión y tristeza. En algún lugar de las implacables llanuras junto a la ribera del río Washita, Algren perdió su alma. En un mundo completamente distinto, otro soldado ve como su modo de vida está a punto de desintegrarse.","en":"Nathan Algren is an American hired to instruct the Japanese army in the ways of modern warfare, which finds him learning to respect the samurai and the honorable principles that rule them. Pressed to destroy the samurai''s way of life in the name of modernization and open trade, Algren decides to become an ultimate warrior himself and to fight for their right to exist.","de":"Der abgehalfterte US-Militär Captain Nathan Algren nimmt im Jahr 1875 den Auftrag an, die Armee des japanischen Kaisers auszubilden. Er soll die Truppe auf den Kampf gegen die alten Krieger des japanischen Kaiserreichs vorbereiten: den Kampf gegen die Samurai. Doch bereits im ersten Gefecht werden die Soldaten vernichtend geschlagen und Algren wird gefangen genommen. Schwer verletzt wird er in das Dorf des Anführers der Samurai Katsumoto gebracht. Er wird gesund gepflegt und lernt die Lebensweise der Samurai kennen. Wieder zurück in Tokio muss er sich entscheiden, auf welcher Seite er steht. Wird er mit den von Amerikanern geführten japanischen Soldaten kämpfen oder sich für die Seite der Samurai entscheiden?","fr":"En 1876, le capitaine Nathan Algren vit avec les souvenirs des batailles sanglantes menées contre les Sioux. Fort de son expérience au combat, il devient conseiller militaire pour le compte de l''empereur japonais soucieux d''ouvrir son pays aux traditions et au commerce occidentaux et d''éradiquer l''ancienne caste guerrière des samouraïs. Mais ceux-ci influent sur le capitaine Algren, qui se trouve bientôt pris entre deux feux, au cœur d''une confrontation entre deux époques et deux mondes avec, pour le guider, son sens de l''honneur."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hHYbOZVogfOIVg4FEF2Hs2UUNHs.jpg","es":"https://image.tmdb.org/t/p/w500/DfwutbQodAsYxdqJu7Cme5jifC.jpg","en":"https://image.tmdb.org/t/p/w500/a8jmJPs5eZBARmnuEEvZwbjwyz4.jpg","de":"https://image.tmdb.org/t/p/w500/zxUiSv7gK4VLfCyU7quE9r5S0Qt.jpg","fr":"https://image.tmdb.org/t/p/w500/dJDLjVmBNMb13wZ6lXYwe6uscel.jpg"}'::jsonb WHERE id = 225;
UPDATE public.films SET tmdb_id = 616, titoli_i18n = '{"it":"L''ultimo samurai (Ôkami yo rakujitsu o)","es":"El último samurái","en":"The Last Samurai","fr":"Le Dernier Samouraï","de":"Last Samurai"}'::jsonb, trame_i18n = '{"it":"Durante il periodo del Bakumatsu e il declino dello shogunato Tokugawa, un maestro di spada fedele alla tradizione samurai si trova diviso tra amicizia, dovere e il turbine dei conflitti sanguinosi che segnano la nascita del Giappone moderno.","es":"1870. El capitán Nathan Algren es un hombre a la deriva. Las batallas que libró en otro tiempo parecen ahora lejanas e inútiles. Una vez arriesgó su vida por el honor y por la patria, pero, en los años transcurridos desde la Guerra de Secesión estadounidense, el mundo ha cambiado. El pragmatismo ha reemplazado al valor, el interés personal ha ocupado el lugar del sacrificio y el honor no se encuentra en ninguna parte, especialmente en el Oeste, donde su papel en las campañas contra los indios acabó en desilusión y tristeza. En algún lugar de las implacables llanuras junto a la ribera del río Washita, Algren perdió su alma. En un mundo completamente distinto, otro soldado ve como su modo de vida está a punto de desintegrarse.","en":"Nathan Algren is an American hired to instruct the Japanese army in the ways of modern warfare, which finds him learning to respect the samurai and the honorable principles that rule them. Pressed to destroy the samurai''s way of life in the name of modernization and open trade, Algren decides to become an ultimate warrior himself and to fight for their right to exist.","fr":"En 1876, le capitaine Nathan Algren vit avec les souvenirs des batailles sanglantes menées contre les Sioux. Fort de son expérience au combat, il devient conseiller militaire pour le compte de l''empereur japonais soucieux d''ouvrir son pays aux traditions et au commerce occidentaux et d''éradiquer l''ancienne caste guerrière des samouraïs. Mais ceux-ci influent sur le capitaine Algren, qui se trouve bientôt pris entre deux feux, au cœur d''une confrontation entre deux époques et deux mondes avec, pour le guider, son sens de l''honneur.","de":"Der abgehalfterte US-Militär Captain Nathan Algren nimmt im Jahr 1875 den Auftrag an, die Armee des japanischen Kaisers auszubilden. Er soll die Truppe auf den Kampf gegen die alten Krieger des japanischen Kaiserreichs vorbereiten: den Kampf gegen die Samurai. Doch bereits im ersten Gefecht werden die Soldaten vernichtend geschlagen und Algren wird gefangen genommen. Schwer verletzt wird er in das Dorf des Anführers der Samurai Katsumoto gebracht. Er wird gesund gepflegt und lernt die Lebensweise der Samurai kennen. Wieder zurück in Tokio muss er sich entscheiden, auf welcher Seite er steht. Wird er mit den von Amerikanern geführten japanischen Soldaten kämpfen oder sich für die Seite der Samurai entscheiden?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hHYbOZVogfOIVg4FEF2Hs2UUNHs.jpg","es":"https://image.tmdb.org/t/p/w500/DfwutbQodAsYxdqJu7Cme5jifC.jpg","en":"https://image.tmdb.org/t/p/w500/a8jmJPs5eZBARmnuEEvZwbjwyz4.jpg","fr":"https://image.tmdb.org/t/p/w500/dJDLjVmBNMb13wZ6lXYwe6uscel.jpg","de":"https://image.tmdb.org/t/p/w500/zxUiSv7gK4VLfCyU7quE9r5S0Qt.jpg"}'::jsonb WHERE id = 226;
UPDATE public.films SET tmdb_id = 771, titoli_i18n = '{"it":"Mamma, ho perso l''aereo (Home Alone)","es":"Solo en casa","de":"Kevin - Allein zu Haus","en":"Home Alone","fr":"Maman, j''ai raté l''avion !"}'::jsonb, trame_i18n = '{"it":"Il piccolo Kevin McCallister viene sbadatamente dimenticato a casa dalla famiglia in partenza per le vacanze di Natale a Parigi. Rimasto solo, deve difendere la propria abitazione da due maldestri ladri d''appartamento usando ingegnose trappole.","es":"Kevin McAllister es un niño de ocho años, miembro de una familia numerosa, que accidentalmente se queda abandonado en su casa cuando toda la familia se marcha a pasar las vacaciones a Francia. Kevin aprende a valerse por sí mismo e incluso a protegerse de Harry y Marv, dos bribones que se proponen asaltar todas las casas cerradas de su vecindario. Cuando su madre Kate lo hecha en falta, realiza un pintoresco viaje de vuelta contra reloj a Chicago para recuperar a su hijo.","de":"Schon lange hat die Familie McCallister den Urlaub in Europa geplant, und alle sind bereit, am nächsten Morgen endlich loszufliegen. Doch leider verschlafen alle, und alles wird sehr hektisch und unübersichtlich, weil sie das Flugzeug nicht verpassen wollen. Irgendwo über dem Atlantik stellen sie fest, dass sie Kevin, den jüngsten Sohn der Familie, zu Hause vergessen haben. Und der muss nun alleine klar kommen, und das Haus gegen Einbrecher und böse Nachbarn verteidigen.","en":"Eight-year-old Kevin McCallister makes the most of the situation after his family unwittingly leaves him behind when they go on Christmas vacation. When thieves try to break into his home, he puts up a fight like no other.","fr":"La famille McCallister a décidé de passer les fêtes de Noël à Paris. Seulement Kate et Peter McCallister s''aperçoivent dans l''avion qu''il leur manque le plus jeune de leurs enfants, Kevin, âgé de 9 ans. D''abord désespéré, Kevin reprend vite les choses en main et s''organise pour vivre le mieux possible. Quand deux cambrioleurs choisissent sa maison pour commettre leurs méfaits."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/aQdJ8Q4CEUq55DTcBjItOyqMhTd.jpg","es":"https://image.tmdb.org/t/p/w500/rjc2a9N5pro1xGsSvvnJ1JDXRGm.jpg","de":"https://image.tmdb.org/t/p/w500/8PuMnVXP1l0mDh5b7CeHESodMjT.jpg","en":"https://image.tmdb.org/t/p/w500/onTSipZ8R3bliBdKfPtsDuHTdlL.jpg","fr":"https://image.tmdb.org/t/p/w500/7hvfmQ5zgwoxZZOHQ9uGMdIk43t.jpg"}'::jsonb WHERE id = 227;
UPDATE public.films SET tmdb_id = 772, titoli_i18n = '{"es":"Solo en casa 2: Perdido en Nueva York","it":"Mamma, ho riperso l''aereo - Mi sono smarrito a New York (Home Alone 2: Lost in New York)","de":"Kevin - Allein in New York","en":"Home Alone 2: Lost in New York","fr":"Maman, j''ai encore raté l''avion !"}'::jsonb, trame_i18n = '{"es":"En plenas fiestas navideñas, el pequeño Kevin y su familia están a punto de coger un avión para disfrutar de unas pequeñas vacaciones, pero Kevin se equivoca y embarca en un avión que lo lleva a Nueva York, donde vuelve a encontrarse solo y desprotegido.","it":"Durante la confusione dell''imbarco per le vacanze natalizie in Florida, Kevin si imbarca per errore su un volo diretto a New York. Nella grande mela si ritroverà ad affrontare nuovamente i ladri Harry e Marv, evasi nel frattempo dal carcere.","de":"Und wieder ist Weihnachten bei der Familie McCallister, wieder ist Ferienstimmung angesagt – diesmal soll’s ins sonnige Florida gehen. Aus den Erfahrungen des chaotischen letzten Jahres hat man gelernt; diesmal kann alles verlorengehen – wenn nur Kevin mit am Flughafen ist. Doch es kommt, wie es kommen muß: Die Familie sitzt in der Maschine nach Florida und Kevin gerät auf den Flieger in die Stadt mit der Statue. Das ist ein Heidenspaß für den liebenswerten frechen Bengel, denn New York ist eben immer noch DIE Stadt überhaupt. Eine schöne Bescherung für den kleinen Kevin – wenn da nicht die “nassen Banditen” wären, die ausgerechnet zur gleichen Zeit ihr unfreiwilliges Zuhause verlassen haben, um in der Stadt der Städte ihr neues, fieses Glück zu suchen. Und die beiden sind noch immer mächtig sauer auf den gewitzten Jungen aus Chicago.","en":"Instead of flying to Florida with his folks, Kevin ends up alone in New York, where he gets a hotel room with his dad''s credit card—despite problems from a clerk and meddling bellboy. But when Kevin runs into his old nemeses, the Wet Bandits, he''s determined to foil their plans to rob a toy store on Christmas Eve.","fr":"Après Paris, c''est à Miami que la tribu McCallister décide de passer les fêtes de Noël. À l''aube du jour J, toute la famille est sur le pied de guerre et file a l''aéroport en prenant bien garde de ne pas oublier Kevin. Mais celui-ci s''éclipse pour acheter des piles pour son walkman, il ne retrouve plus les siens et s''embarque par mégarde pour New York..."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/7sdiRUyc0ANHJptPhsgb1KL6hoq.jpg","it":"https://image.tmdb.org/t/p/w500/eYKQJmrEyANdUcE7nJ7PQ6XARaO.jpg","de":"https://image.tmdb.org/t/p/w500/y9smOLUhE5JOBjbmnESm6orPrf5.jpg","en":"https://image.tmdb.org/t/p/w500/uuitWHpJwxD1wruFl2nZHIb4UGN.jpg","fr":"https://image.tmdb.org/t/p/w500/gFhf8NwvEKCbNIOQZxLqj1i5DMy.jpg"}'::jsonb WHERE id = 228;
UPDATE public.films SET tmdb_id = 9714, titoli_i18n = '{"it":"Mamma, ho preso il morbillo (Home Alone 3)","es":"Solo en casa 3","de":"Wieder allein zu Haus","en":"Home Alone 3","fr":"Maman, je m''occupe des méchants !"}'::jsonb, trame_i18n = '{"it":"Il piccolo Alex è costretto a rimanere a casa con il morbillo. Si troverà a dover affrontare quattro pericolosi criminali internazionali intenzionati a recuperare un prezioso microchip militare nascosto all''interno di un''auto radiocomandata finita per sbaglio nelle sue mani.","es":"Cuatro espías de alta tecnología industrial roban un microchip ultrasecreto y confiadamente lo ocultan en un coche de juguete de control remoto. Por causa de una confusión de equipajes en el aeropuerto, la anciana señora Hess recoge el juguete y se lo regala a su vecino de ocho años Alex. Los espías desearán recuperar el valioso chip a toda costa, pero Alex está preparado para darles una cálida bienvenida.","de":"Vier High-Tech-Industrie-Spione schmieden einen scheinbar brillanten Plan: Beaupre, Alice, Jernigan und Unger stehlen einen neuartigen und streng geheimen Mikrochip, den ein Unternehmen aus dem Silicon Valley entworfen hat, um eine für den Radar nicht sichtbare Rakete zu steuern. Um an den Sicherheitskontrollen am Flughafen vorbeizukommen, verstecken die Ganoven den Chip in einem Spielzeugauto. Doch natürlich läuft nicht alles nach Plan. Durch eine Verwechslung an der Gepäckausgabe kommt Mrs. Hess in den Besitz des Autos. Die ältere Dame verschenkt das Spielzeug an den Nachbarsjungen Alex. Der hütet gerade das Bett: Windpocken! Während seine Eltern in der Arbeit und seine Geschwister in der Schule sind, ist der Achtjährige also ganz allein zu Haus. Einfaches Spiel für Beaupre und seine Bande, die nur in das Haus einbrechen und das Spielzeugauto an sich nehmen müssen. Oder vielleicht auch nicht. Denn Alex ist gut gerüstet für den unliebsamen Besuch…","en":"9-year-old Alex Pruitt is home alone with the chicken pox. Turns out, due to a mix-up among nefarious spies, Alex was given a toy car concealing a top-secret microchip. Now Alex must fend off the spies as they try to break into his house to get it back.","fr":"De dangereux trafiquants prennent livraison à Hong Kong d''un microprocesseur à usage militaire et le dissimulent dans un jouet électronique. À l''aéroport, Mrs Hess prend par erreur le sac contenant le jouet. Les malfrats retrouvent sa trace dans la banlieue de Chicago, mais faute de connaître son nom, s''installent dans sa rue et visitent chaque maison. Mrs Hess a offert le jouet à son petit voisin, Alex, précoce et déluré, qui ne tarde pas à remarquer le manège des gangsters."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/s1PwvbnNicaxT6wdlMZJqrW0yQt.jpg","es":"https://image.tmdb.org/t/p/w500/720eeviFT6G8SStX2lEgFsYzqAp.jpg","de":"https://image.tmdb.org/t/p/w500/eTSyZeH2TEIkqxuozZmf0KPNqCt.jpg","en":"https://image.tmdb.org/t/p/w500/6uOadrCfle0n2LOOxHbgWEdnrm2.jpg","fr":"https://image.tmdb.org/t/p/w500/jFlRBtxKgogQso43nC7t65gJeNS.jpg"}'::jsonb WHERE id = 229;
UPDATE public.films SET tmdb_id = 12536, titoli_i18n = '{"it":"Mamma, ho allagato la casa (Home Alone 4: Taking Back the House)","en":"Home Alone 4","fr":"Maman, je suis seul contre tous","de":"Kevin - Allein gegen alle","es":"Solo en casa 4"}'::jsonb, trame_i18n = '{"it":"Kevin McCallister trascorre il Natale nella villa super tecnologica della nuova fidanzata del padre. Lì dovrà impedire il rapimento di un giovane principe da parte del suo vecchio nemico Marv e della sua nuova complice.","en":"Kevin McCallister''s parents have split up. Now living with his mom, he decides to spend Christmas with his dad at the mansion of his father''s rich girlfriend, Natalie. Meanwhile robber Marv Merchants, one of the villains from the first two movies, partners up with a new criminal named Vera to hit Natalie''s mansion.","fr":"Maintenant que ses parents sont séparés, Kevin doit passer ses vacances avec son père chez la petite amie de celui-ci qui vit dans un véritable palace bourré d''une tonne de gadgets derniers cris. Mais il est loin de se douter qu''il devra mener une véritable guerre éclair pour déjouer le plan de dangereux malfaiteurs !","de":"Kevin will das Weihnachtsfest bei seinem Vater verbringen, der seit der Trennung von Kevins Mutter Kate mit der deutlich jüngeren Nathalie zusammenlebt. Deswegen macht sich Kevin auf den Weg und kommt dabei prompt dem Gaunerpärchen Marv und Vera auf die Schliche, das die Entführung zweier Kinder aus wohlhabendem Hause plant. Das Verbrechen soll bei Nathalie über die Bühne gehen. Natürlich kann der clevere Kevin das nicht zulassen und er heckt einen ausgefeilten Plan aus, wie er in Nathalies High-Tech-Haus, die beiden Gangster vertreiben kann. Da Marv und Vera nicht mit dem Einfallsreichtum und der Sturheit eines Kindes wie Kevin gerechnet haben, beginnt eine abenteuerliche Nacht, in der sich ein Kind gegen Kriminelle behaupten muss…","es":"Después del reciente divorcio de sus padres, Kevin decide pasar la Navidad en casa de Natalie, la nueva novia de su padre, una casa equipada con la más moderna tecnología. Con la ayuda de esta tecnología y haciendo uso de su habitual ingenio, Kevin deberá hacer frente a unos ladrones, además de intentar conseguir que sus progenitores se reconcilien. Nueva entrega de la popular saga de \"Solo en casa\", que en esta ocasión, y tras perder progresivamente calidad y taquilla en las anteriores, ya se hizo directamente para la televisión y el mercado de video."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zfm0UYbIpOpL8ak9tf655h3GWS2.jpg","en":"https://image.tmdb.org/t/p/w500/qRktvMOO2QaCL7gvNyvZDoxPOZj.jpg","fr":"https://image.tmdb.org/t/p/w500/5Qyhmdw7qv19J81C3mjsIb74HaR.jpg","de":"https://image.tmdb.org/t/p/w500/rno49zdgQzQWK6AhrwWfrhX1vAT.jpg","es":"https://image.tmdb.org/t/p/w500/q9BAc2Q37oQWcRlMKUkuRilJ90E.jpg"}'::jsonb WHERE id = 230;
UPDATE public.films SET tmdb_id = 134375, titoli_i18n = '{"it":"Mamma, ho visto i fantasmi! (Home Alone: The Holiday Heist)","fr":"Maman, la maison est hantée !","en":"Home Alone: The Holiday Heist","es":"Solo en casa 5","de":"Allein zu Haus: Der Weihnachts-Coup"}'::jsonb, trame_i18n = '{"it":"Finn si trasferisce con la famiglia in una nuova casa nel Maine che crede infestata dai fantasmi. Quando i genitori rimangono bloccati fuori città, Finn deve proteggere la dimora da una banda di tre ladri d''arte a caccia di un dipinto dal valore inestimabile.","fr":"Les Baxter ont quitté la Californie pour s''installer dans le Maine. Alors que Finn, 10 ans, apprend à composer avec le rude climat local, il se persuade que sa nouvelle maison est hantée par le fantôme d''un gangster. Déterminé à le capturer, il truffe la demeure de dispositifs divers.","en":"10-year-old Finn is terrified to learn his family is relocating from sunny California to Maine in the scariest house he has ever seen! Convinced that his new house is haunted, Finn sets up a series of elaborate traps to catch the “ghost” in action. Left home alone with his sister while their parents are stranded across town, Finn’s traps catch a new target – a group of thieves who have targeted Finn’s house.","es":"Finn Baxter y su familia se mudan de California a Maine a su nueva casa. Finn está aterrorizado y cree que la casa está embrujada. Mientras que instala trampas para coger al \"fantasma\", sus padres se quedan varados en la ciudad y Finn se quedá solo en casa con su hermana. Lo que no esperaban, es que su casa se convierte en el objetivo de tres ladrones en busca de un botín especial. (FILMAFFINITY)","de":"Nach dem Umzug seiner Familie aus dem sonnigen Kalifornien in ein altes Haus in Maine ist der 8-jährige Finn (Christian Martyn) überzeugt, dass es in dem Haus spukt. Deshalb baut er einige Fallen für die Gespenster. Die erweisen sich als äußerst hilfreich, als an Weihnachten ein paar Diebe in das Haus eindringen, während Finns Eltern am anderen Ende der Stadt festhängen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/nsRl6M33UjKNpHDIRoGW81WX89H.jpg","fr":"https://image.tmdb.org/t/p/w500/88gvFNRRBiAeD9CeOBnVbbdjcXJ.jpg","en":"https://image.tmdb.org/t/p/w500/aP6NPJeiv30d82lZF1baZ3qRBcZ.jpg","es":"https://image.tmdb.org/t/p/w500/nxxcHTbqNrEkrJvtCzxzm3TDtU.jpg","de":"https://image.tmdb.org/t/p/w500/ggMiHskombbsOiUJGY9E2KrNsw1.jpg"}'::jsonb WHERE id = 231;
UPDATE public.films SET tmdb_id = 654974, titoli_i18n = '{"fr":"Maman, j’ai raté l’avion ! (Ça recommence)","it":"Home Sweet Home Alone - Mamma, ho perso l''aereo (Home Sweet Home Alone)","de":"Nicht schon wieder allein zu Haus","es":"Por fin solo en casa","en":"Home Sweet Home Alone"}'::jsonb, trame_i18n = '{"fr":"Max Mercer, dix ans, se retrouve tout seul chez lui quand sa famille part en vacances au Japon en l''oubliant. Alors qu''un couple obsédé par un précieux héritage a sa maison dans le collimateur, Max doit la protéger contre ces intrus… et il ne reculera devant rien pour leur en interdire l''entrée.","it":"Il giovanissimo Max Mercer viene accidentalmente lasciato a casa da solo quando la sua famiglia parte per il Giappone. Deve proteggere la sua abitazione da una coppia di coniugi in difficoltà finanziarie che tenta di recuperare un prezioso cimelio di famiglia.","de":"Der 10-jährige Max Mercer bleibt aus Versehen zurück, als seine Familie über Weihnachten nach Japan in den Urlaub fliegt. Als ein Ehepaar, das ein kostbares Erbstück sucht, sein Zuhause ins Visier nimmt, liegt es an Max, es vor den Eindringlingen zu schützen... Und er wird alles tun, was nötig ist, damit sie auf keinen Fall hineinkommen.","es":"Max Mercer tiene 10 años. Su familia se ha ido a Japón a pasar las Navidades y se ha olvidado de él en casa. Cuando una pareja que quiere recuperar un valioso tesoro familiar decide meterse en su casa, Max tiene que protegerla de los intrusos. Y hará lo que sea para que no entren.","en":"After being left at home by himself for the holidays, 10-year-old Max Mercer must work to defend his home from a married couple who tries to steal back a valuable heirloom."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/pm9IBLHOClAjlPi8O1bvpU9lUtO.jpg","it":"https://image.tmdb.org/t/p/w500/jdMU0YJC5jTEI95iALzGm6qPis0.jpg","de":"https://image.tmdb.org/t/p/w500/2q4w8c7q0lyTGU8omBiFWnM9pny.jpg","es":"https://image.tmdb.org/t/p/w500/5K7qxX77PJXWuzkZD8rOBduCEKo.jpg","en":"https://image.tmdb.org/t/p/w500/fP3VvqUjEBjawxZHL4sYCq2ZdJD.jpg"}'::jsonb WHERE id = 232;
UPDATE public.films SET tmdb_id = 576845, titoli_i18n = '{"fr":"Last Night in Soho","de":"Last Night in Soho","en":"Last Night in Soho","it":"Ultima notte a Soho","es":"Última noche en el Soho"}'::jsonb, trame_i18n = '{"fr":"L’histoire d’une jeune femme passionnée de mode et de design qui parvient mystérieusement à retourner dans les années 60 où elle rencontre son idole, une éblouissante jeune star montante. Mais le Londres des années 60 n’est pas ce qu’il paraît, et le temps semble se désagréger entraînant de sombres répercussions.","de":"Die behütete Eloise zieht nach London, um Mode zu studieren. Dort träumt sie sich immer öfter in den glitzernden Szenebezirk Soho der Swinging Sixties, wobei Traum und Realität verschwimmen. Doch der Schein trügt und die Zeit scheint aus den Fugen zu geraten - mit düsteren Folgen.","en":"A young girl, passionate about fashion design, is mysteriously able to enter the 1960s where she encounters her idol, a dazzling wannabe singer. But 1960s London is not what it seems, and time seems to be falling apart with shady consequences.","it":"Eloise, ventenne cresciuta con la nonna dopo il suicidio della madre, arriva a Londra con il sogno di diventare stilista. Ha il mito della Swingin'' London e della musica anni ''60, che ascolta continuamente su vecchi 33 giri portatili. Dopo un''infelice esperienza nello studentato della scuola di moda in cui è stata ammessa, si trasferisce in un appartamento di Soho affittato da un''anziana signora. Qui, durante lunghe notti agitate, Eloise sogna di tornare nel passato, nella Londra che ama di più, dove incontra Sandie, un''aspirante cantante che vive il glamour di una città colorata ed esaltante. Poco alla volta, però, Eloise confonde la propria personalità con quella di Sandie e ne scopre la vita in realtà miserabile, scivolando tra realtà e incubo in un''esperienza spaventosa.","es":"Thriller psicológico sobre una joven apasionada por la moda que misteriosamente puede entrar en la década de 1960, donde se encuentra con su ídolo, un atractivo aspirante a cantante. Pero el Londres de los sesenta no es lo que parece, y el tiempo comenzará a desmoronarse con sombrías consecuencias."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/v6qAIxWYIUiid71YPWjnVOZ4U6K.jpg","de":"https://image.tmdb.org/t/p/w500/azdy7STEzLAyrhzeKZfl15jZYMN.jpg","en":"https://image.tmdb.org/t/p/w500/n1ZRmjlk1BJTY7aASqACfPAaLn2.jpg","it":"https://image.tmdb.org/t/p/w500/mNuXKuiywifooo8LnAzMy0W4ZiK.jpg","es":"https://image.tmdb.org/t/p/w500/4eSJJsBZ00qMyoWLe98ulNGvGbC.jpg"}'::jsonb WHERE id = 234;
UPDATE public.films SET tmdb_id = 16699, titoli_i18n = '{"it":"Mamma ho perso il lavoro","fr":"Smother","en":"Smother","de":"Das Muttersöhnchen","es":"La madre de él"}'::jsonb, trame_i18n = '{"en":"After he''s fired from his job, an everyday guy faces pressure from his wife to have a baby and from his mom, who has decided to move in with the young couple.","de":"Chaotische Verwirrungen sind vorprogrammiert: Noah verliert seinen Job, seine Frau Clare will endlich ein Kind und hat gerade ihre fruchtbaren Tage und Noahs Mutter Marilyn verdächtigt ihren Gatten der Untreue - woraufhin sie kurzerhand bei Noah und Clare einzieht. Eine Mischung, die schnell zur Explosion führt...","es":"Cuando lo despiden de su trabajo como fisioterapeuta, Noah Cooper piensa que no puede ocurrirle nada peor. Pero se equivoca. Al llegar a casa, su ya abarrotado hogar se vuelve aún más caótico con la presencia de Marilyn, su dominante madre, que busca un lugar donde refugiarse y que, además, trae consigo a sus cinco perros. A partir de ese momento, Noah deberá aprender a soportar la presión que implica buscar trabajo, que su mujer busque desesperadamente un hijo; y lo que es peor: que su madre no quiera pasar ni un minuto lejos de él.","it":"After he''s fired from his job, an everyday guy faces pressure from his wife to have a baby and from his mom, who has decided to move in with the young couple."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg","fr":"https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg","en":"https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg","de":"https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg","es":"https://image.tmdb.org/t/p/w500/czM99MpudQceBxcowaTGbvlhUtm.jpg"}'::jsonb WHERE id = 235;
UPDATE public.films SET tmdb_id = 63, titoli_i18n = '{"en":"Twelve Monkeys","fr":"L''Armée des 12 singes","it":"L''esercito delle 12 scimmie","de":"12 Monkeys","es":"12 monos"}'::jsonb, trame_i18n = '{"en":"In the year 2035, convict James Cole reluctantly volunteers to be sent back in time to discover the origin of a deadly virus that wiped out nearly all of the earth''s population and forced the survivors into underground communities. But when Cole is mistakenly sent to 1990 instead of 1996, he''s arrested and locked up in a mental hospital. There he meets psychiatrist Dr. Kathryn Railly and the son of a famous virus expert who may hold the key to the Army of the 12 Monkeys; thought to be responsible for unleashing the killer disease.","fr":"Nous sommes en l’an 2035. Les quelques milliers d’habitants qui restent sur notre planète sont contraints de vivre sous terre. La surface du globe est devenue inhabitable à la suite d’un virus ayant décimé 99 % de la population. Les survivants mettent tous leurs espoirs dans un voyage à travers le temps pour découvrir les causes de la catastrophe et la prévenir. C’est James Cole, hanté depuis des années par une image incompréhensible, qui est désigné pour cette mission.","it":"L''Esercito delle 12 scimmie è un piccolo gioiellino fantascientifico del 1995 che si focalizza sulla disperazione di un singolo uomo, condannato a essere il prescelto per trovare un rimedio alla situazione disastrosa dell''umanità, in un futuro ormai abitato da una razza umana rassegnata. Nel 2035 gli esseri umani vivono nel sottosuolo, terrorizzati dall''ambiente esterno, portatore di un virus mortale che li ha decimati, rendendo il pianeta Terra un luogo dove i prigionieri sono diventati loro stessi. Anche se solo in modo approssimativo, gli scienziati di quel terribile futuro hanno reso possibile il viaggio nel tempo, unica possibilità per poter mettere le mani sul virus e crearne una cura.","de":"Das Jahr 2035: Die Erdoberfläche ist entvölkert, seit eine Virenepidemie die Menschheit 1996 fast gänzlich vernichtet hat. Die wenigen Überlebenden existieren in einem Unterwelt-System. Mit der Hoffnung auf ein besseres Leben schickt man den Sträfling Cole als Zeitboten ins Jahr der Katastrophe zurück, um den Ursprung der Apokalypse herauszufinden. Versehentlich gerät er zunächst ins Jahr 1990 und in eine Irrenanstalt. Dort warnt ihn der verwirrte Jeffrey vor den \"12 Monkeys\". Haben sie mit den Viren zu tun? Endlich im Jahr 1996, spürt Cole mit der Psychiaterin Kathryn diese Vereinigung auf und macht eine verblüffende Entdeckung...","es":"En el año 2035, un virus mortal ha arrasado la humanidad y los supervivientes viven bajo tierra. Un convicto llamado James Cole se ofrece como voluntario para viajar al pasado y averiguar el origen de la plaga. Su misión es encontrar al ''Ejército de los Doce Monos'', una organización terrorista que se cree que liberó el virus. Sin embargo, su viaje se complica por los errores temporales, las visiones recurrentes y la duda sobre su propia cordura. Con la ayuda de una psiquiatra llamada Kathryn Railly y un loco llamado Jeffrey Goines, Cole intenta salvar el futuro antes de que sea demasiado tarde."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/gt3iyguaCIw8DpQZI1LIN5TohM2.jpg","fr":"https://image.tmdb.org/t/p/w500/pJ0EtnTbJyHf9XCqeiuAy3HK9Ij.jpg","it":"https://image.tmdb.org/t/p/w500/9WfkdEGHO8K0AF8ahbc34zMzM4e.jpg","de":"https://image.tmdb.org/t/p/w500/l872D4V4sl13A8UOZRUk5TMSRV6.jpg","es":"https://image.tmdb.org/t/p/w500/bXLwKCCMS2NCNlxAhSwn9HCymRl.jpg"}'::jsonb WHERE id = 236;
UPDATE public.films SET tmdb_id = 9552, titoli_i18n = '{"de":"Der Exorzist","en":"The Exorcist","fr":"L''Exorciste","es":"El exorcista","it":"L''esorcista"}'::jsonb, trame_i18n = '{"de":"Regan MacNeill, zwölfjährige Tochter der berühmten Filmschauspielerin Chris MacNeill, leidet seit kurzem unter hysterischen, von heftigen Krämpfen begleiteten Wutausbrüchen. Als die versammelte, hochdotierte Ärzteschar Hilflosigkeit demonstriert und die Anfälle eskalieren, sucht Mutter MacNeill die Hilfe katholischer Geistlicher. Zwei herbeieilende Jesuitenpater diagnostizieren teuflische Besessenheit und verschreiben dem Teenager einen klassischen Exorzismus. Der alte Kampf zwischen Gut und Böse entbricht.","en":"When a mysterious entity possesses a young girl, her mother seeks the help of two Catholic priests to save her life.","fr":"Regan, une adolescente, présente depuis quelque temps d’étranges symptômes. Après avoir épuisé les solutions médicales, la mère de Regan consulte un prêtre-psychiatre qui est rapidement convaincu que Regan est possédée et que seul un exorcisme pourra la \"guérir\".","es":"Regan es una niña de doce años víctima de fenómenos paranormales como la levitación o la manifestación de una fuerza sobrehumana. Su madre, aterrorizada, tras someter a su hija a múltiples análisis médicos que no ofrecen ningún resultado, acude a un sacerdote con estudios de psiquiatría. Éste está convencido de que el mal no es físico sino espiritual, es decir, que la niña es víctima de una posesión diabólica. Por eso, con la ayuda de otro sacerdote decide practicar un exorcismo.","it":"In un quartiere tranquillo, in una casa dotata di tutti i moderni comfort, una ragazzina modello cade ammalata. La madre non può aiutarla. I medici non riescono ad elaborare una diagnosi. Temendo che le crisi di cui soffre la figlia non riguardino solo la sfera fisica, ma anche quella spirituale, la donna si rivolge a un sacerdote. L''uomo però dubita della presenza del diavolo in quella casa, in quel corpo e la debolezza delle sue convinzioni non farà altro che rendere più forte il maligno."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/x7pwEqdrKJ7dO5qIk9bdihubC0I.jpg","en":"https://image.tmdb.org/t/p/w500/5x0CeVHJI8tcDx8tUUwYHQSNILq.jpg","fr":"https://image.tmdb.org/t/p/w500/zApG4BHUfOsCbNcPfyHk6cKDboI.jpg","es":"https://image.tmdb.org/t/p/w500/hwJvgHQ4tf9eRQec1ouAgg33dPV.jpg","it":"https://image.tmdb.org/t/p/w500/49uIBJqG4ugL7KC2yBhz0nCLeHG.jpg"}'::jsonb WHERE id = 238;
UPDATE public.films SET tmdb_id = 948, titoli_i18n = '{"it":"Halloween - La notte delle streghe","fr":"La Nuit des masques","es":"La noche de Halloween","en":"Halloween","de":"Halloween - Die Nacht des Grauens"}'::jsonb, trame_i18n = '{"it":"Micheal, a soli 6 anni ammazza la sorella e viene internato ma dopo 15 anni fugge per recarsi al suo paese. E'' il 31 Ottobre, e secondo l''antica tradizione americana è la notte in cui si esorcizzano le streghe, grazie a questa concomitanza Micheal può mietere altre vittime.","fr":"Il y a 15 ans, dans une petite ville des États-Unis, le soir d’Halloween, au cours de laquelle les enfants ont l’habitude de se déguiser, un petit garçon, Michael, épie sa sœur et son ami qui flirtent. Michael les suit et, armé d’un couteau de cuisine, assassine la jeune fille. Quinze ans plus tard, un psychiatre, le docteur Loomis qui étudie le cas du jeune meurtrier apprend que le criminel s’est échappé : il est revenu sur les lieux de son crime pour continuer son œuvre…","es":"Durante la noche de Halloween, Michael, un niño de seis años, asesina a su familia con un cuchillo de cocina. Es internado en un psiquiátrico del que huye quince años más tarde, precisamente la víspera de Halloween. El psicópata vuelve a su pueblo y comete una serie de asesinatos. Mientras, uno de los médicos del psiquiátrico le sigue la pista.","en":"Fifteen years after murdering his sister on Halloween Night 1963, Michael Myers escapes from a mental hospital and returns to the small town of Haddonfield, Illinois to kill again.","de":"1963, Halloween-Nacht im Kaff Haddonfield: Die Teenagerin Judith Myers wird in ihrem Elternhaus von ihrem sechsjährigen Bruder brutal erstochen - Michael Myers hat das erste Mal zugeschlagen! Der Junge kommt daraufhin in das Smith’s Grove Warren County Sanatorium in die Obhut von Psychiater Sam Loomis. Schon bald ist dieser davon überzeugt, dass sich in der Gestalt des Kindes das absolut Böse verbirgt. 15 Jahre danach, am Vorabend von Halloween, gelingt Michael die Flucht aus der Heilanstalt. Der maskierte Killer macht sich auf den Weg nach Haddonfield, wo sich arglose Teenager wie Laurie Strode auf ein bisschen Horrorspaß freuen..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/uxLqrN38fSQEUVpM4S1suhnW3X.jpg","fr":"https://image.tmdb.org/t/p/w500/r1ME6ZFxmZ6vFYqt9PHepiIb1t.jpg","es":"https://image.tmdb.org/t/p/w500/6bsDpDL312h6vEGPOPWoweaZWUG.jpg","en":"https://image.tmdb.org/t/p/w500/wijlZ3HaYMvlDTPqJoTCWKFkCPU.jpg","de":"https://image.tmdb.org/t/p/w500/mWm1FkerRpBFyaYtvcAMMTjz38o.jpg"}'::jsonb WHERE id = 239;
UPDATE public.films SET tmdb_id = 346364, titoli_i18n = '{"it":"It - Capitolo uno","fr":"Ça","es":"It (Eso)","en":"It","de":"Es"}'::jsonb, trame_i18n = '{"it":"Ottobre 1988, nella cittadina di Derry. Il piccolo Georgie esce di casa nella pioggia per far navigare la barchetta di carta preparatagli dal fratello maggiore Billy, costretto a casa dall''influenza. La barchetta scorre per i rivoli lungo i marciapiedi, ma finisce in uno scolo che conduce alla rete fognaria. Georgie, contrariato, si china a guardare nella feritoia e incontra lo sguardo del bizzarro clown che abita nelle fogne, Pennywise. Per quanto strano sia trovare un clown in quel luogo, Georgie si intrattiene con lui sin quando il clown non lo addenta e lo cattura portandolo giù con sé. Giugno 1989. A Derry vige il coprifuoco a causa delle numerose sparizioni di persone, soprattutto bambini.","fr":"À Derry, dans le Maine, aux États-Unis, 7 gamins, ayant du mal à s’intégrer, se sont regroupés au sein du Club des Ratés. Rejetés par leurs camarades, ils sont les cibles favorites des gros durs de l’école. Ils ont aussi en commun d’avoir éprouvé leur plus grande terreur face à un terrible prédateur métamorphe qu’ils appellent Ça…","es":"Remake del clásico de Stephen King en el que un payaso aterroriza a los niños de un vecindario. En un pequeño pueblo de Maine, siete niños conocidos como el Club de los Perdedores se encuentran cara a cara con problemas de la vida, matones y un monstruo que toma la forma de un payaso llamado Pennywise.","en":"In a small town in Maine, seven children known as The Losers Club come face to face with life problems, bullies and a monster that takes the shape of a clown called Pennywise.","de":"Die Freunde Stanley Uris, Richie Tozier, Mike Hanlon, Bill Denbrough Beverly Marsh, Eddie Kaspbrak und Ben Hanscom leben in einer Stadt namens Derry, in der immer wieder Menschen verschwinden – sowohl Erwachsene als auch vor allem Minderjährige. Schließlich erfahren die Kinder, die sich selbst auch den „Klub der Verlierer“ nennen, von einer interdimensionalen Kreatur, die Jagd auf Menschen macht und sich in die schlimmsten Alpträume ihrer Opfer verwandeln kann. Meistens tritt das Biest jedoch in Form des sadistischen Clowns Pennywise  auf. Die Kinder schwören die Kreatur zu vernichten und kehren als Erwachsene in ihre Heimatstadt zurück, in der Pennywise erneut aufgetaucht ist."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/ru0gDnxKzBjzrPxfRyZIuse9hfu.jpg","fr":"https://image.tmdb.org/t/p/w500/3SUz0F0I2Bodcj9Ev2pYSWnE9zp.jpg","es":"https://image.tmdb.org/t/p/w500/sSrj4lnhrb113DOPEPTaO2jaDk3.jpg","en":"https://image.tmdb.org/t/p/w500/9E2y5Q7WlCVNEhP5GiVTjhEhx1o.jpg","de":"https://image.tmdb.org/t/p/w500/xrqfuDX1Ei4gdjcpYPufTWjBcVN.jpg"}'::jsonb WHERE id = 240;
UPDATE public.films SET tmdb_id = 601, titoli_i18n = '{"en":"E.T. the Extra-Terrestrial","de":"E.T. – Der Außerirdische","es":"E.T., el extraterrestre","fr":"E.T. l''extra-terrestre","it":"E.T. l''extra-terrestre"}'::jsonb, trame_i18n = '{"en":"An alien is left behind on Earth and saved by the 10-year-old Elliott who decides to keep him hidden in his home. While a task force hunts for the extra-terrestrial, Elliott, his brother, and his little sister Gertie form an emotional bond with their new friend, and try to help him find his way home.","de":"Der junge Elliott traut seinen Augen kaum, als er in einem Schuppen einen kleinen Ausserirdischen findet. Der schrumpelige Kobold musste bei einem Erkundungsflug von seinen Kollegen auf der Erde zurückgelassen werden, weil sie in Gefahr gerieten, von Menschen entdeckt zu werden. Elliot versucht, seinen neuen Freund vor den Wissenschaftlern der Regierung zu verstecken, denn der will seine weit entfernten Verwandten anfunken. Doch E.T. wird vor Heimweh immer schwächer.","es":"Un pequeño ser de otro planeta se queda abandonado en la Tierra cuando su nave se marcha olvidándose de él. Tiene miedo. Está completamente solo, pero se hará amigo de un niño, que lo esconde en su casa. El niño y sus hermanos intentarán encontrar la forma de que el pequeño extraterrestre regrese a su planeta antes de que los científicos y la policía lo encuentren.","fr":"Une soucoupe volante atterrit en pleine nuit près de Los Angeles. Quelques extraterrestres, envoyés sur Terre en mission d’exploration botanique, sortent de l’engin, mais un des leurs s’aventure au-delà de la clairière où se trouve la navette. Celui-ci se dirige alors vers la ville. C’est sa première découverte de la civilisation humaine. Bientôt traquée par des militaires et abandonnée par les siens, cette petite créature apeurée se nommant E.T. se réfugie dans une résidence de banlieue. Elliot, un garçon de dix ans, le découvre et lui construit un abri dans son armoire. Rapprochés par un échange télépathique, les deux êtres ne tardent pas à devenir amis. Aidé par sa sœur Gertie et son frère aîné Michael, Elliot va alors tenter de garder la présence d''E.T. secrète.","it":"Durante un sopralluogo sulla Terra per raccogliere vegetali, un gruppo di alieni viene sorpreso e uno di loro viene lasciato erroneamente al suolo per l''affrettato decollo. L''alieno, solo e smarrito, viene trovato ed ospitato da Elliott, con la complicità della sorellina Gertie e il fratello maggiore Michael. Tra i due si instaura un profondo rapporto di amicizia che li lega anche a livello emotivo. Desideroso di tornare a casa, l''alieno costruisce un rudimentale dispositivo di comunicazione per chiedere aiuto ai suoi. Gradualmente, la salute di ET peggiora, e la situazione è aggravata dall''irruzione nell''universo dei ragazzi da parte del mondo degli adulti, che vuole impossessarsi dell''alieno."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/an0nD6uq6byfxXCfk6lQBzdL2J1.jpg","de":"https://image.tmdb.org/t/p/w500/mNbBxa6pNxr4tmOQTGzj9eBuivZ.jpg","es":"https://image.tmdb.org/t/p/w500/ojvKem8WUzRK5PLvO7wTuAFinnz.jpg","fr":"https://image.tmdb.org/t/p/w500/5jl5sfhTeAlp60rM9GxoDA2dmX9.jpg","it":"https://image.tmdb.org/t/p/w500/3DIwTC2A58WDtsgjaXjo2FYA1pW.jpg"}'::jsonb WHERE id = 241;
UPDATE public.films SET tmdb_id = 497, titoli_i18n = '{"fr":"La Ligne verte","de":"The Green Mile","en":"The Green Mile","es":"La milla verde","it":"Il miglio verde"}'::jsonb, trame_i18n = '{"fr":"Paul Edgecomb, pensionnaire centenaire d’une maison de retraite, est hanté par ses souvenirs. Gardien-chef du pénitencier de Cold Mountain en 1935, il était chargé de veiller au bon déroulement des exécutions des peines capitales, en s’efforçant d’adoucir les derniers moments des condamnés. Parmi eux, se trouvait un colosse du nom de John Coffey, accusé du viol et du meurtre de deux fillettes. Intrigué par cet homme candide et timide, aux dons magiques, Edgecomb va tisser avec lui des liens très forts.","de":"Paul Edgecomb und seine Kollegen sind Wärter im Todestrakt eines Gefängnisses in den 30ern. Paul versieht seinen Job zwar immer noch mit der größtmöglichen Menschlichkeit, doch er wird zunehmend zynischer, da er ständig Menschen sterben sieht. Außerdem ist er krank. Da kommt ein neuer Delinquent in den Trakt: John Coffey, ein farbiger Riese von friedlichster Bauart, der im Dunkeln Angst hat. Wie sich herausstellt, hat Coffey heilende Fähigkeiten, die auch Paul kennenlernt. Zunehmend gerät er in Zweifel, ob dieser Gigant sterben soll, vor allem da er die Morde, wegen der er verurteilt ist, nicht begangen zu haben scheint. Doch der Stuhl wartet und Coffeys Gabe droht für immer zu verschwinden ...","en":"A supernatural tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people''s ailments. When the cell block''s head guard, Paul Edgecomb, recognizes Coffey''s miraculous gift, he tries desperately to help stave off the condemned man''s execution.","es":"En el sur de los Estados Unidos, en plena Depresión, Paul Edgecomb es un vigilante penitenciario a cargo de la Milla Verde, un pasillo que separa las celdas de los reclusos condenados a la silla eléctrica. Esperando su ejecución está John Coffey, un gigantesco negro acusado de asesinar brutalmente a dos hermanas de nueve años. Tras una personalidad ingenua, Coffey esconde un don sobrenatural prodigioso. A medida que transcurre la historia, Paul Edgecomb aprende que los milagros ocurren... incluso en los lugares más insospechados.","it":"E'' il racconto che Paul Edgecomb fa all''amica Elaine Connelly in una casa di riposo. Sono passati circa sessanta anni da quando lavorava come capo delle guardie del braccio della morte nel penitenziario di Could Mountain. Durante la grande depressione, nel carcere del sud degli Usa, Edgecomb si occupava di quattro assassini che attendevano di compiere la loro ultima passeggiata lungo il ''Miglio verde'', il corridoio rivestito di linoleum verde che li avrebbe condotti nella stanza della sedia elettrica. Fra questi c''era anche John Coffrey, un ragazzone nero condannato per l''omicidio di due gemelline di nove anni. Nonostante avesse le dimensioni e la forza per uccidere chiunque, Coffrey aveva un carattere semplice e ingenuo: era davvero lui il colpevole?"}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/cRBUYC02CPsVa1GqBq6rfHn5a8g.jpg","de":"https://image.tmdb.org/t/p/w500/frsZNikjMbp1gfidAl3zm1PAMHk.jpg","en":"https://image.tmdb.org/t/p/w500/8VG8fDNiy50H4FedGwdSVUPoaJe.jpg","es":"https://image.tmdb.org/t/p/w500/aBQiJRxGRrX0mXFMjxyzWYFtEnf.jpg","it":"https://image.tmdb.org/t/p/w500/kptqTcldosy8JPf75JT16oTYUMB.jpg"}'::jsonb WHERE id = 256;
UPDATE public.films SET tmdb_id = 1368337, titoli_i18n = '{"en":"The Odyssey","es":"La Odisea","fr":"L''Odyssée","it":"Odissea","de":"Die Odyssee"}'::jsonb, trame_i18n = '{"en":"Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.","es":"Tras la caída de Troya, el legendario rey de Ítaca, Odiseo a.k.a. Ulises, emprende un largo y peligroso viaje para regresar junto a su esposa Penélope y su hijo Telémaco. En el camino deberá enfrentarse a criaturas mitológicas, dioses caprichosos y pruebas que pondrán a prueba su ingenio, su resistencia y su humanidad. Mientras tanto, en Ítaca, el futuro de su reino pende de un hilo ante la creciente amenaza de quienes creen que jamás volverá.","fr":"Ulysse, roi d''Ithaque, entreprend un périple périlleux pour regagner son royaume après la guerre de Troie. Alors qu''ils traversent la Méditerranée avec ses soldats, ils se retrouvent bientôt à lutter non seulement contre les éléments, mais aussi contre une multitude d''obstacles mortels et de créatures mythiques.","it":"Ogni leggenda ha un prezzo. Ogni ritorno richiede un sacrificio. Mentre il mare diventa il suo più grande nemico, Ulisse affronta un cammino fatto di illusioni, battaglie e prove impossibili. Un''epica odissea che mette alla prova il coraggio di un uomo contro il volere degli dèi.","de":"Folgt Odysseus, dem legendären griechischen König von Ithaka, auf seiner langen und gefährlichen Heimreise nach dem Trojanischen Krieg und schildert seine Begegnungen mit mythischen Wesen wie dem Zyklopen Polyphem, den Sirenen und der Hexengöttin Circe, während er versucht, wieder mit seiner Frau Penelope zusammenzukommen."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg","es":"https://image.tmdb.org/t/p/w500/sf2ke1nwFOLLcwLZiXu9VaMMv8e.jpg","fr":"https://image.tmdb.org/t/p/w500/kP8jJIkmX0vWEYiqQ9c5zU0dvcn.jpg","it":"https://image.tmdb.org/t/p/w500/qQhInj9fw3S2bMbiEujVldthgKe.jpg","de":"https://image.tmdb.org/t/p/w500/4E8Ji8jTcWNncl9PdUCauoj2qh9.jpg"}'::jsonb WHERE id = 257;
UPDATE public.films SET tmdb_id = 408, titoli_i18n = '{"en":"Snow White and the Seven Dwarfs","de":"Schneewittchen und die sieben Zwerge","fr":"Blanche-Neige et les Sept Nains","es":"Blancanieves y los siete enanitos","it":"Biancaneve e i sette nani"}'::jsonb, trame_i18n = '{"en":"A beautiful girl, Snow White, takes refuge in the forest in the house of seven dwarfs to hide from her stepmother, the wicked Queen. The Queen is jealous because she wants to be known as \"the fairest in the land,\" and Snow White''s beauty surpasses her own.","de":"Schneewittchen ist eine kleine Prinzessin, deren böse Stiefmutter sie in Lumpen hüllen und als Magd schuften ließ. Warum? Weil sie Angst hatte, dass das Mädchen eines Tages schöner sein könnte als sie selbst. Als diese Befürchtung der eitlen Königin durch ihren magischen Spiegel als wahr bestätigt wird, beauftragt sie einen Jäger, Schneewittchen im Wald zu töten. Doch der bringt den Mord nicht übers Herz und lässt das Mädchen entkommen. Schneewittchen entdeckt auf einer Lichtung ein leer stehendes Haus, in dem sie gemeinsam mit den Tieren des Waldes für Ordnung und Sauberkeit sorgt. Als die sieben Zwerge von der Arbeit heimkehren, sind sie von ihrem Hausgast schnell entzückt und nehmen Schneewittchen bei sich auf. Als die Königin erfährt, dass ihre Stieftochter noch lebt, ist sie außer sich: Mit Zauberkräften verwandelt sie sich in eine Hexe und macht sich auf den Weg in den Wald, um die böse Tat mit Hilfe eines giftigen Apfels selbst zu vollenden...","fr":"Blanche-Neige est une princesse d’une très grande beauté, ce qui rend jalouse sa belle‐mère. Celle‐ci demande quotidiennement à son miroir magique de lui dire qu’elle est la plus belle, mais un jour, le miroir affirme que la plus belle femme du royaume est Blanche-Neige. La reine décide alors de la tuer, mais le garde chargé de cette tâche ne trouve pas le courage et abandonne Blanche-Neige dans la forêt. Perdue, à bout de force, elle échoue dans une maison où habitent sept nains.","es":"La malvada madrastra de la princesa Blancanieves decide deshacerse de ella porque no puede soportar que la belleza de la joven sea superior a la de ella. Sin embargo, Blancanieves consigue salvarse y se refugia en la cabaña de los siete enanitos. A pesar de todo, su cruel madrastra consigue encontrarla y la envenena con una manzana. Pero la princesa no está muerta, sólo dormida, a la espera de que un príncipe azul la rescate.","it":"La perfida regina ordina al suo cacciatore di uccidere Biancaneve che lo specchio parlante ha definito la più bella del reame. La ragazza fugge. Guidata dagli animaletti del bosco, arriva alla casa dei sette nani. Eolo, Mammolo, Pisolo, Brontolo, Dotto, Gongolo e Cucciolo la accolgono e la proteggono. Quando la regina, trasformatasi in strega, arriva per ucciderla, i nanetti inseguono la cattiva che precipita da un burrone. Biancaneve, vegliata dai suoi amici come morta, torna in vita quando viene baciata dal giovane principe innamorato."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/3VAHfuNb6Z7UiW12iYKANSPBl8m.jpg","de":"https://image.tmdb.org/t/p/w500/9WIyHiEYjVAAXc6m0yg2J4upT8V.jpg","fr":"https://image.tmdb.org/t/p/w500/pf2dhaGRYNtBgjkw24ot3AAXfPi.jpg","es":"https://image.tmdb.org/t/p/w500/b2ZPP3bZqDOzqTHr1TlFIFPWP48.jpg","it":"https://image.tmdb.org/t/p/w500/pXji7b98MIliRsylaBeCBaRbcmA.jpg"}'::jsonb WHERE id = 258;
UPDATE public.films SET tmdb_id = 787699, titoli_i18n = '{"en":"Wonka","it":"Wonka","de":"Wonka","es":"Wonka","fr":"Wonka"}'::jsonb, trame_i18n = '{"en":"Willy Wonka – chock-full of ideas and determined to change the world one delectable bite at a time – is proof that the best things in life begin with a dream, and if you’re lucky enough to meet Willy Wonka, anything is possible.","it":"Basato sullo straordinario protagonista de La Fabbrica di Cioccolato, il romanzo per bambini più iconico dell’autore Roald Dahl nonché uno dei libri per bambini più venduti di tutti i tempi, Wonka racconta la meravigliosa storia di come il più grande inventore, mago e cioccolataio del mondo sia diventato l''amato Willy Wonka che conosciamo oggi.","de":"Bereits in jungen Jahren träumt Willy Wonka von seinem eigenen Schokoladengeschäft. Doch Schaum wie so manch anderer Traum ist das nicht. Mit dem Laden ist es ihm sehr ernst. Deshalb hat er auch viel Zeit damit verbracht, um die Welt zu reisen und an verschiedensten Orten seine Techniken zu verbessern. Doch bevor alles überhaupt richtig in Gang kommen kann, ist es schon fast wieder aus mit dem Traum vom eigenen Laden. Denn das mächtige Schokoladenkartell legt dem exzentrischen Wonka jede Menge Steine in den Weg. Aber ohne die Erlaubnis des Kartells geht nun mal leider gar nichts, die Ladentür muss verschlossen bleiben. Aber Wonka lässt sich auch davon nicht unterkriegen. Er sprudelt regelrecht vor Ideen, wie er seine schokoladigen Leckereien trotzdem unters Volk bringen kann. Alleine ist er dabei auch nicht. Die kleine Noodle ist ebenfalls mit dabei. Außerdem kann Wonka auf die Unterstützung der skurrilen Oompa Loompas setzen.","es":"Basada en el personaje que protagoniza \"Charlie y la fábrica de chocolate\", el libro infantil más emblemático de Roald Dahl y uno de los más vendidos de todos los tiempos, \"Wonka\" cuenta la historia de cómo el mayor inventor, mago y chocolatero del mundo se convirtió en el querido Willy Wonka que conocemos hoy en día.","fr":"Inspiré du personnage principal hors du commun de Charlie et la Chocolaterie, le best-seller de Roald Dahl qui est aujourd''hui l''un des livres pour enfants les plus vendus de tous les temps, « Wonka » est une histoire merveilleuse retraçant la jeunesse de Willy Wonka, et comment il est devenu ce grand inventeur, magicien et chocolatier que nous connaissons aujourd''hui. Dans ce spectacle saisissant et d''une créativité sans limites, les spectateurs découvriront un Willy Wonka jeune, la tête débordant d''idées et bien décidé à changer le monde à coups de délicieuses chocolateries. Il vous montrera que les meilleures choses de la vie commencent par un rêve, et qu''en rencontrant Willy Wonka, tout devient possible."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/qhb1qOilapbapxWQn9jtRCMwXJF.jpg","it":"https://image.tmdb.org/t/p/w500/7y2M1w0nWW0Z5Ph1XzED07OYUsa.jpg","de":"https://image.tmdb.org/t/p/w500/5ZQDRv6hw3JaNvcnhrNeaeXnQMG.jpg","es":"https://image.tmdb.org/t/p/w500/6eHcR7zwvNSvkOl9jbctU0lvZQ1.jpg","fr":"https://image.tmdb.org/t/p/w500/aKK2C3SErXIhNdT9gI93as2b8GV.jpg"}'::jsonb WHERE id = 259;
UPDATE public.films SET tmdb_id = 615457, titoli_i18n = '{"es":"Nadie","fr":"Nobody","de":"Nobody","it":"Io sono nessuno","en":"Nobody"}'::jsonb, trame_i18n = '{"es":"Hutch Mansell, un padre de familia que aguanta con resignación y sin defenderse los golpes de la vida. Un don nadie.  Una noche, cuando dos ladrones entran en su casa, Hutch decide no actuar y no trata de defenderse ni al él mismo ni a su familia, convencido de que solo así evitará una escalada de violencia. Tras el ataque, su hija adolescente Blake no oculta su decepción, y su esposa Becca se aleja todavía más.","fr":"Hutch Mansell, un père et un mari frustré, totalement déconsidéré par sa famille, se contente d’encaisser les coups, sans jamais les rendre. Il n’est rien. Une nuit, alors que deux cambrioleurs pénètrent chez lui, il fait le choix de ne pas intervenir, plutôt que de risquer une escalade sanglante. Une décision qui le discrédite définitivement aux yeux de son fils Blake, et qui semble l’éloigner encore plus de sa femme Becca. Cet incident réveille chez cet homme blessé des instincts larvés qui vont le propulser sur une voie violente, révélant des zones d’ombres et des compétences létales insoupçonnées. Dans une avalanche de coups de poings, de fusillades et de crissements de pneus, il va tout faire pour tirer sa famille des griffes d’un redoutable ennemi et s’assurer que, plus jamais, personne ne le prenne pour un moins que rien.","de":"Familienvater Hutch ist ein Niemand. Der Vorstadt-Familienvater wird von den meisten Leuten einfach ignoriert und zieht auch niemals die Aufmerksamkeit auf sich. Als zwei Verbrecher eines Nachts in sein Haus einsteigen, sieht er sich außerstande, sich oder seine Familie zu verteidigen. Schließlich will er Gewalt um jeden Preis verhindern. Sein Sohn Brady wendet sich daraufhin enttäuscht von seinem Vater ab. Seine Frau Becca tut es ihm gleich und zieht sich noch mehr zurück. Doch der Einbruch löst bei Hutch etwas aus. Er sieht plötzlich rot und enthüllt eine dunkle Seite, die ihn auf einen Pfad der Gewalt schickt …","it":"Hutch Mansell, padre e marito sottostimato e trascurato, è abituato a non reagire a nessuna umiliazione. Quando una notte due ladri irrompono nella sua abitazione in periferia, rifiuta di difendere se stesso o la sua famiglia, sperando di prevenire violenze maggiori. Il figlio adolescente Blake è deluso dal suo comportamento e la moglie Becca comincia ad allontanarsi maggiormente da lui. All''indomani dell''accaduto, la rabbia che Hutch cova esplode spingendolo a manifestare tutta la violenza di cui è capace. Si ritroverà allora a dover difendere come meglio può la sua famiglia da un pericoloso avversario e ad assicurarsi di non essere mai più sottovalutato da nessuno.","en":"Hutch Mansell, a suburban dad, overlooked husband, nothing neighbor — a \"nobody.\" When two thieves break into his home one night, Hutch''s unknown long-simmering rage is ignited and propels him on a brutal path that will uncover dark secrets he fought to leave behind."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ddO5a3tMPpQutSDQO1bESgLWadB.jpg","fr":"https://image.tmdb.org/t/p/w500/jKRzh9y5YjYNISbeh55FQwetsSu.jpg","de":"https://image.tmdb.org/t/p/w500/p64aYHMicQjIHUC5WczBHgIiWcM.jpg","it":"https://image.tmdb.org/t/p/w500/iECT5xNf72P7cx9LDMrEwhGYD5O.jpg","en":"https://image.tmdb.org/t/p/w500/oBgWY00bEFeZ9N25wWVyuQddbAo.jpg"}'::jsonb WHERE id = 260;
UPDATE public.films SET tmdb_id = 1007734, titoli_i18n = '{"it":"Io sono nessuno 2","es":"Nadie 2","en":"Nobody 2","fr":"Nobody 2","de":"Nobody 2"}'::jsonb, trame_i18n = '{"it":"Il padre di periferia Hutch Mansell, un ex assassino letale, viene riportato nel suo passato violento dopo aver sventato un''invasione domestica, innescando una catena di eventi che svela i segreti sul passato di sua moglie Becca e sul suo.","es":"Cuatro años después de enfrentarse involuntariamente a la mafia rusa, Hutch Mansell sigue intentando saldar una deuda de 30 millones de dólares con golpes a criminales internacionales. Agotado y distanciado de su familia, organiza unas vacaciones con su esposa e hijos en Plummerville, el lugar donde solía ir con su hermano de niño. Pero un pequeño altercado los convierte en el objetivo de un peligroso mafioso local y de su corrupto sheriff, poniendo en riesgo toda la familia.","en":"Former assassin Hutch Mansell takes his family on a nostalgic vacation to a small-town theme park, only to be pulled back into violence when they clash with a corrupt operator, a crooked sheriff, and a ruthless crime boss.","fr":"Quatre ans après sa malencontreuse altercation avec la mafia russe, Hutch doit toujours 30 millions de dollars à la redoutable organisation et s''efforce de la rembourser en enchaînant sans répit les contrats d''une liste de criminels à abattre aussi interminable qu''internationale. Bien qu''il apprécie le caractère intense de son travail, Hutch se retrouve vite surmené, tout comme sa femme Becca, et ils s''éloignent inexorablement l''un de l''autre.","de":"Vier Jahre nachdem er sich versehentlich mit der russischen Mafia angelegt hatte, arbeitet Hutch noch immer seinen Schuldenberg von 30 Millionen Dollar ab. Unzählige dreckige Jobs erledigt, zahllose Auftragsmorde vor sich: Ein Ende ist für den gestressten Killer nicht absehbar. Zunehmend leidet die Ehe mit seiner Frau Becca unter seinem zeitintensiven Job. Um mehr Zeit miteinander zu verbringen, machen sie einen Kurzurlaub mit ihren Kindern im Wild Bill’s Majestic Midway Wasserpark, wo Hutch schon als Kind glückliche Ferien verbrachte. Mit Hutchs Vater freuen sie sich auf eine entspannte Zeit in Plummerville. Doch eine Begegnung mit Vorstadtschlägern weckt die Aufmerksamkeit des korrupten Wasserparkbesitzers und seines zwielichtigen Sheriffs. Hutch steckt plötzlich in neuen Schwierigkeiten und trifft auf den härtesten Gangsterboss, dem er je gegenüberstand."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8RXDbeVG9Tb0z8FWPph77uJsTkd.jpg","es":"https://image.tmdb.org/t/p/w500/qwdBh0102NX5fslXv3L9MSlXqKc.jpg","en":"https://image.tmdb.org/t/p/w500/svXVRoRSu6zzFtCzkRsjZS7Lqpd.jpg","fr":"https://image.tmdb.org/t/p/w500/gmyEMJqpScyALufAMspejI6qGQx.jpg","de":"https://image.tmdb.org/t/p/w500/3szAYIIftJgBMkYJXmb3jA23ctl.jpg"}'::jsonb WHERE id = 261;
UPDATE public.films SET tmdb_id = 687163, titoli_i18n = '{"es":"Proyecto Salvación","de":"Der Astronaut – Project Hail Mary","fr":"Projet Dernière Chance","it":"L''ultima missione: Project Hail Mary","en":"Project Hail Mary"}'::jsonb, trame_i18n = '{"es":"El profesor de ciencias Ryland Grace se despierta en una nave espacial a años luz de casa sin recordar quién es ni cómo ha llegado hasta allí. A medida que recupera la memoria, empieza a descubrir su misión: resolver el enigma de la misteriosa sustancia que provoca la extinción del sol. Deberá recurrir a sus conocimientos científicos y a sus ideas poco ortodoxas para salvar todo lo que hay en la Tierra de la extinción... pero una amistad inesperada significa que quizá no tenga que hacerlo solo.","de":"Als Ryland Grace erwacht, muss er feststellen, dass er ganz allein ist. Er ist anscheinend der einzige Überlebende einer Raumfahrtmission, Millionen Kilometer von zu Hause entfernt, auf einem Flug ins Tau-Ceti-Sternsystem. Aber was erwartet ihn dort? Und warum sind alle anderen Besatzungsmitglieder tot? Nach und nach dämmert es Grace, dass von seinem Überleben nicht nur die Mission, sondern die Zukunft der gesamten Erdbevölkerung abhängt.","fr":"Le professeur de sciences Ryland Grace se réveille à bord d’un vaisseau spatial, à des années-lumière de la Terre, sans aucun souvenir de qui il est ni de la façon dont il est arrivé là. À mesure que sa mémoire lui revient, il commence à découvrir sa mission : résoudre l’énigme d’une mystérieuse substance qui provoque l’extinction du Soleil. Il doit faire appel à ses connaissances scientifiques et ses idées peu orthodoxes pour sauver toute vie sur Terre mais une amitié inattendue pourrait signifier qu’il n’aura pas à accomplir cette tâche seul.","it":"L’insegnante di scienze Ryland Grace si sveglia su un’astronave lontano anni luce da casa senza alcun ricordo di chi sia o di come sia arrivato lì. Con il riaffiorare della sua memoria, torna alla luce lo scopo della sua missione: risolvere l’enigma della misteriosa sostanza che sta causando il collasso del Sole. Dovrà fare affidamento sulle sue conoscenze scientifiche e sulle sue capacità di pensare fuori dagli schemi per salvare dall’estinzione la vita sulla Terra, mentre un''inaspettata amicizia gli farà capire che non è solo in questa impresa.","en":"Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/7lwOTxajURKEWO6gI370NTrVdBO.jpg","de":"https://image.tmdb.org/t/p/w500/qUraey7aJVaqx6NhlXl5Q7Z1rEX.jpg","fr":"https://image.tmdb.org/t/p/w500/wzyy8ZrsuHfAt4iz4iH3rT0tdoT.jpg","it":"https://image.tmdb.org/t/p/w500/gPC1X3mwqwX50Ye3qwwPt7iW3Ma.jpg","en":"https://image.tmdb.org/t/p/w500/iOb2fjXLbpJgyQXe46n1WtGCnaa.jpg"}'::jsonb WHERE id = 262;
UPDATE public.films SET tmdb_id = 1284465, titoli_i18n = '{"es":"La muerte de Robin Hood","en":"The Death of Robin Hood","fr":"On l''appelait Robin des Bois","it":"Robin Hood - Il prezzo del sangue","de":"The Death of Robin Hood"}'::jsonb, trame_i18n = '{"es":"Robin Hood intenta lidiar con sus demonios tras una larga vida de crímenes y asesinatos. Cuando en una sangrienta batalla resulta herido de gravedad, es enviado a un misterioso castillo para que curen sus heridas. Allí conocerá a una mujer que le ofrecerá una última oportunidad de redención.","en":"Grappling with his past after a life of crime and murder, Robin Hood finds himself gravely injured after a battle he thought would be his last. In the hands of a mysterious woman, he is offered a chance at salvation.","fr":"Hanté par son passé après une vie de crimes et de violence, Robin des Bois est laissé pour mort à l’issue d’un combat qu’il pensait être le dernier. Recueilli par une femme mystérieuse, il se voit offrir une ultime chance de rédemption…","it":"Il principe dei ladri, il difensore degli oppressi, l’eroe che ruba ai ricchi per dare ai poveri. Sono tutte bugie: Robin Hood non è mai stato un paladino della giustizia, ma solo un efferato bandito, e le sue “allegre scorribande” erano vere e proprie carneficine. Ma quando dedichi la tua vita al crimine, alla violenza e alla menzogna, devi essere pronto a pagarne il prezzo…","de":"Während er nach einem Leben voller Verbrechen und Mord mit seiner Vergangenheit ringt, findet sich Robin Hood schwer verwundet nach einer Schlacht wieder, die er für seine letzte hielt. In den Händen einer geheimnisvollen Frau bietet sich ihm eine Chance auf Erlösung."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/pC2hVl4J522GcMVc5OghRHSs0tq.jpg","en":"https://image.tmdb.org/t/p/w500/13MmRwmG5NmaMfU8qNrtgGXisiD.jpg","fr":"https://image.tmdb.org/t/p/w500/7MEcMhm889D8zIDINnBKOYNiSg1.jpg","it":"https://image.tmdb.org/t/p/w500/knUCsVWsLv5583lsvs2cP1VRrGx.jpg","de":"https://image.tmdb.org/t/p/w500/oR8ZW1CVADJCwCsIYPEowUI1RAU.jpg"}'::jsonb WHERE id = 263;
UPDATE public.films SET tmdb_id = 1275779, titoli_i18n = '{"it":"Disclosure Day","fr":"Disclosure Day","en":"Disclosure Day","es":"El día de la revelación","de":"Disclosure Day – Der Tag der Wahrheit"}'::jsonb, trame_i18n = '{"it":"Se scoprissi che non siamo soli, se qualcuno te lo mostrasse, te lo dimostrasse, questo ti spaventerebbe?","fr":"Si vous découvriez que nous ne sommes pas seuls, si quelqu''un vous le montrait, vous le prouvait, cela vous effraierait-il ?","en":"A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there''s life beyond our understanding.","es":"Entre conspiraciones gubernamentales y avances tecnológicos, toda la humanidad está a punto de conocer la verdad sobre la existencia extraterrestre y su devenir.","de":"Die Fernsehmeteorologin Margaret Fairchild wird live während eines TV-Auftritts plötzlich von einem unerklärlichen Phänomen heimgesucht. Während die Behörden zu vertuschen versuchen, dass Außerirdische dahinter stecken könnten, will der Aktivist Daniel Kellner mit allen Mitteln die Weltöffentlichkeit über die Wahrheit informieren."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/72Yx1uisLLJy5k2P5OzBkRdEIjp.jpg","fr":"https://image.tmdb.org/t/p/w500/8GRMeKaDFnuzXBzqGiDMzCFDnwQ.jpg","en":"https://image.tmdb.org/t/p/w500/AnJ8IQJI23hNpYXVNaythu061Ru.jpg","es":"https://image.tmdb.org/t/p/w500/dPTa7jSIeaDhie2d9JSZr7qI0Tf.jpg","de":"https://image.tmdb.org/t/p/w500/8aaV365bjSxPMZdT18RybAYGqSp.jpg"}'::jsonb WHERE id = 264;
UPDATE public.films SET tmdb_id = 546554, titoli_i18n = '{"en":"Knives Out","fr":"À couteaux tirés","es":"Puñales por la espalda","de":"Knives Out - Mord ist Familiensache","it":"Cena con delitto - Knives Out"}'::jsonb, trame_i18n = '{"en":"When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan''s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.","fr":"Célèbre auteur de polars, Harlan Thrombey est retrouvé mort dans sa somptueuse propriété, le soir de ses 85 ans. L’esprit affûté et la mine débonnaire, le détective Benoit Blanc est alors engagé par un commanditaire anonyme afin d’élucider l’affaire. Mais entre la famille d’Harlan qui s''entre-déchire et son personnel qui lui reste dévoué, Blanc plonge dans les méandres d’une enquête mouvementée, mêlant mensonges et fausses pistes, où les rebondissements s''enchaînent à un rythme effréné jusqu''à la toute dernière minute…","es":"Cuando el renombrado novelista de misterio Harlan Thrombey es encontrado muerto en su mansión justo después de su 85 cumpleaños, el inquisitivo y cortés detective Benoit Blanc es misteriosamente reclutado para investigar. Se moverá entre una red de pistas falsas y mentiras interesadas para tratar de descubrir la verdad tras la prematura muerte del escritor.","de":"Harlan Thrombey ist tot! Und nicht nur das – der renommierte Krimiautor und Familienpatriarch wurde auf der Feier zu seinem 85. Geburtstag umgebracht. Doch natürlich wollen weder die versammelte exzentrische Verwandtschaft noch das treu ergebene Hauspersonal etwas gesehen haben. Ein Fall für Benoit Blanc! Der lässig-elegante Kommissar beginnt seine Ermittlungen und während sich sämtliche anwesenden Gäste alles andere als kooperativ zeigen, spitzt sich die Lage zu und das Misstrauen untereinander wächst. Ein komplexes Netz aus Lügen, falschen Fährten und Ablenkungsmanövern muss durchkämmt werden, um die Wahrheit hinter Thrombeys vorzeitigem Tod zu enthüllen.","it":"Quando il noto scrittore di gialli Harlan Thrombey viene trovato morto nella sua tenuta poco dopo il suo 85° compleanno, il detective Benoit Blanc, curioso e disinvolto, viene misteriosamente reclutato per investigare sull''accaduto. Dalla disfunzionale famiglia della vittima al suo devoto entourage, Blanc si muove attraverso una fitta rete di bugie, segreti e non detti, per scoprire quale sia la verità dietro la prematura morte dell''autore."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/pThyQovXQrw2m0s9x82twj48Jq4.jpg","fr":"https://image.tmdb.org/t/p/w500/4kxVUW4hMurLs7ascwahF7blEUs.jpg","es":"https://image.tmdb.org/t/p/w500/7scJ3fVmwdSpGG87wvxH3kk0RPc.jpg","de":"https://image.tmdb.org/t/p/w500/ftCASOlSQ6QtjS3TIJB7xXHW5H9.jpg","it":"https://image.tmdb.org/t/p/w500/q2sh3RJ3rhRDYlJV4ZrMzzZ9Ye7.jpg"}'::jsonb WHERE id = 265;
UPDATE public.films SET tmdb_id = 661374, titoli_i18n = '{"en":"Glass Onion: A Knives Out Mystery","es":"Puñales por la espalda: El misterio de Glass Onion","fr":"Glass Onion : Une histoire à couteaux tirés","de":"Glass Onion: A Knives Out Mystery","it":"Glass Onion - Knives Out"}'::jsonb, trame_i18n = '{"en":"World-famous detective Benoit Blanc heads to Greece to peel back the layers of a mystery surrounding a tech billionaire and his eclectic crew of friends.","es":"Cuando el multimillonario Miles Bron invita a algunos de sus allegados a una escapada a su isla griega privada, pronto queda claro que no todo es perfecto en el paraíso. Y cuando alguien aparece muerto, ¿quién mejor que Benoit Blanc para desentrañar todas las capas del misterio?","fr":"Direction la Grèce pour le célèbre détective Benoit Blanc, qui doit élucider un mystère entourant un milliardaire de la technologie et son groupe d''amis hauts en couleur.","de":"Der weltberühmte Detektiv Benoit Blanc reist nach Griechenland, um das Rätsel um einen Tech-Milliardär und dessen facettenreiche Entourage zu lösen.","it":"L''egocentrico multimilardiario Miles Bron, proprietario della Alpha Industries, invita i suoi amici a una fuga sulla sua isola greca privata. Quando qualcuno viene trovato morto, l''investigatore Benoit Blanc si occupa del caso."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/vDGr1YdrlfbU9wxTOdpf3zChmv9.jpg","es":"https://image.tmdb.org/t/p/w500/yXGsWQURm614onIpb3iBcp1iLz8.jpg","fr":"https://image.tmdb.org/t/p/w500/j8mGH7DzwUD9soODpUI64PWNumg.jpg","de":"https://image.tmdb.org/t/p/w500/oprUVNuV1aLeB7fffHqCNcrs1uT.jpg","it":"https://image.tmdb.org/t/p/w500/yhCxL5ebwiBwkmYrjL8gqJBZKNS.jpg"}'::jsonb WHERE id = 266;
UPDATE public.films SET tmdb_id = 812583, titoli_i18n = '{"it":"Wake Up Dead Man - Knives Out","en":"Wake Up Dead Man: A Knives Out Mystery","es":"Puñales por la espalda III. De entre los muertos","fr":"Wake Up Dead Man : Une histoire à couteaux tirés","de":"Wake Up Dead Man: A Knives Out Mystery"}'::jsonb, trame_i18n = '{"it":"Il detective Benoit Blanc fa squadra con un giovane prete zelante per indagare su un crimine perfettamente impossibile nella chiesa di una piccola città dal passato oscuro.","en":"When young priest Jud Duplenticy is sent to assist charismatic firebrand Monsignor Jefferson Wicks, it’s clear that all is not well in the pews. After a sudden and seemingly impossible murder rocks the town, the lack of an obvious suspect prompts local police chief Geraldine Scott to join forces with renowned detective Benoit Blanc to unravel a mystery that defies all logic.","es":"El detective Benoit Blanc se une a un joven y honesto sacerdote para investigar un crimen totalmente imposible en la iglesia de un pequeño pueblo con una oscura historia.","fr":"Le détective Benoit Blanc collabore avec un jeune prêtre pour enquêter sur un crime totalement inexplicable perpétré dans l''église d''une petite ville au sombre passé.","de":"Der Detektiv Benoit Blanc arbeitet mit einem jungen Priester zusammen, um ein absolut unmögliches Verbrechen in einer Kirche mit dunkler Vergangenheit zu lösen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/db8j0xU82lzWKX0SXrPY5tFrzwA.jpg","en":"https://image.tmdb.org/t/p/w500/iV9LM8aUb83BjCCx2RUnKE5sSQg.jpg","es":"https://image.tmdb.org/t/p/w500/trGWfaYTkzkalkosXfxidpLum50.jpg","fr":"https://image.tmdb.org/t/p/w500/qlUqHz8M1x3a2gZSggXY2t1qhNo.jpg","de":"https://image.tmdb.org/t/p/w500/bIeHhOqCQysfed98TKjZhRWRc7x.jpg"}'::jsonb WHERE id = 267;
UPDATE public.films SET tmdb_id = 1054867, titoli_i18n = '{"fr":"Une Bataille après l''autre","en":"One Battle After Another","es":"Una batalla tras otra","de":"One Battle After Another","it":"Una battaglia dopo l’altra"}'::jsonb, trame_i18n = '{"fr":"Bob Ferguson est un ancien révolutionnaire paranoïaque et désabusé, qui a jadis œuvré avec son ex, Perfidia, au sein du French 75, un groupe militant voué au renversement du gouvernement américain. Seize ans plus tard, Bob vit seul avec sa fille, Willa, quand celle-ci disparaît soudainement. Bob soupçonne son vieil ennemi d’antan, le Colonel Steven J. Lockjaw, d’être responsable de sa disparition. Il décide alors de renouer avec ses anciens frères d’armes pour retrouver sa fille, quitte à confronter les fantômes de son passé.","en":"Washed-up revolutionary Bob exists in a state of stoned paranoia, surviving off-grid with his spirited, self-reliant daughter, Willa. When his evil nemesis resurfaces after 16 years and she goes missing, the former radical scrambles to find her, father and daughter both battling the consequences of his past.","es":"Un ex revolucionario, tras años apartado de la lucha, se ve obligado a volver a la acción para enfrentar a viejos enemigos en un ambiente cargado de tensión política, racismo y violencia militar... Adaptación modernizada de la novela ''Vineland'', de Thomas Pynchon (1990), sobre los movimientos radicales de los años sesenta.","de":"Vor 16 Jahren hat die Widerstandsgruppe namens „French 75“ auf einen Schlag 200 Häftlinge aus den Fängen des skrupellosen United States Immigration and Customs Enforcement – kurz: ICE – befreit. Danach verschwanden die Widerständler, darunter auch der von allen nur Ghetto Pat genannte Bob Ferguson, von der Bildfläche. Heute ist Bob getrieben von Paranoia, denn er fürchtet, dass es der damalige ICE-Colonel Steven J. Lockjaw immer noch auf ihn abgesehen hat.","it":"Un gruppo di ex rivoluzionari si riunisce quando un loro perfido nemico riemerge dal loro passato, dopo sedici anni di silenzio. Il gruppo avrà il duro compito di salvare la figlia di uno di loro, prima che accada l''inevitabile."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/vfoxYHHpSOadhOFCmNbtLG2WcUy.jpg","en":"https://image.tmdb.org/t/p/w500/lbBWwxBht4JFP5PsuJ5onpMqugW.jpg","es":"https://image.tmdb.org/t/p/w500/iZ1499F6hYxDxiqioy8oSUaxipG.jpg","de":"https://image.tmdb.org/t/p/w500/5k2WV1i6jcnbPmRhoXSEQWQGT9u.jpg","it":"https://image.tmdb.org/t/p/w500/3TjxuSfBSkhB8OvBov7Dk4L0Bcd.jpg"}'::jsonb WHERE id = 268;
UPDATE public.films SET tmdb_id = 38286, titoli_i18n = '{"es":"Tres hombres y una pierna","en":"Three Men and a Leg","it":"Tre uomini e una gamba","fr":"Tre uomini e una gamba","de":"Tre uomini e una gamba"}'::jsonb, trame_i18n = '{"es":"Aldo, Giovanni y Giacomo se dirigen a la boda de éste último cuya prometida es hermana de las dos esposas de los primeros. Aunque entre ellos no existe una buena relación su amistad se va forjando durante el viaje, en el que transportan una costosa pierna de madera obra de un famoso escultor americano llamado Michel Garpez. (FILMAFFINITY)","en":"Friends Aldo, Giovanni, and Giacomo cross Italy from north to south for Giacomo''s wedding: the father of the bride, a despotic magnate who is both their boss and father-in-law—since Aldo and Giovanni have also married into the family not for love but for money, a fate now awaiting Giacomo—has entrusted them with a priceless piece of modern art, one that looks just like a rather unremarkable wooden leg.","it":"I tre amici Aldo, Giovanni e Giacomo si mettono in viaggio verso il sud Italia per il matrimonio di uno di loro con la futura moglie. Durante il tragitto il terzetto affronta varie peripezie, tra le quali l''incontro con una ragazza di cui Giacomo si innamora e il trasporto di una gamba di legno al suocero.","fr":"Trois amis - Aldo, Giovanni et Giacomo - doivent se rendre de Milan à Gallipoli, dans les Pouilles, pour le mariage de Giacomo. Le père de la mariée, qui est aussi l''employeur et le beau-père d''Aldo et de Giovanni, est un homme d''affaires riche et vulgaire qui maltraite ses gendres et leur a confié la tâche de lui apporter une jambe de bois, œuvre d''un artiste célèbre."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/lASu78osxKRP34a4Ln1ar7VNGhZ.jpg","en":"https://image.tmdb.org/t/p/w500/yhgfM1WTHu4Uiwa47FAGmBk4V7x.jpg","it":"https://image.tmdb.org/t/p/w500/aUQhhVkB1XXUZ9MPGborY6MFYI8.jpg","fr":"https://image.tmdb.org/t/p/w500/aUQhhVkB1XXUZ9MPGborY6MFYI8.jpg","de":"https://image.tmdb.org/t/p/w500/aUQhhVkB1XXUZ9MPGborY6MFYI8.jpg"}'::jsonb WHERE id = 269;
UPDATE public.films SET tmdb_id = 38397, titoli_i18n = '{"es":"La leggenda di Al, John e Jack","fr":"La leggenda di Al, John e Jack","en":"The Legend of Al, John and Jack","de":"La leggenda di Al, John e Jack","it":"La leggenda di Al, John e Jack"}'::jsonb, trame_i18n = '{"es":"Al Caruso, John Gresco y Jack Amoruso son tres gángsters que trabajan para la familia Genovese. Sin embargo, sus esfuerzos no provocan más que dolores de cabeza a la mafia, y cuando les dan la última oportunidad, encargándoles la protección de la tía de su jefe, se meterán en el mayor lío que jamás habían imaginado.","en":"Hapless Depression-era gangsters Al, John and Jack find out their boss wants to get rid of them and come up with a plan to sell him to the FBI, but Al''s short-term memory loss could make it difficult.","it":"New York 1959. I tre gangster Al, John e Jack hanno il compito di uccidere Frankie per conto del boss. Sbagliano bersaglio e il boss da a loro un''altra possibilità: tenere d''occhio una persona a lui cara. Ma la fortuna non è dalla loro parte...."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg","fr":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg","en":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg","de":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg","it":"https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg"}'::jsonb WHERE id = 270;
UPDATE public.films SET tmdb_id = 38396, titoli_i18n = '{"en":"That''s Life","it":"Così è la vita","es":"Così è la vita","de":"Così è la vita","fr":"Così è la vita"}'::jsonb, trame_i18n = '{"en":"While on the run from the police, an unlikely companionship blossoms between a funny con man who just broke out of jail, the bumbling cop whose car he seized at gunpoint, and a nitpicking civilian he unwittingly took hostage.","it":"Soprannominato Bancomat per le sue imprese di falsificatore di carte di credito, Aldo sequestra in auto a Milano prima Giacomo, poliziotto di debole professionalità, e poi Giovanni, inventore di giocattoli. I tre se ne vanno in giro per mezza Italia (i monti dell''Abruzzo, in realtà), prima braccati dalla polizia e poi creduti morti. Diventano amici fino all''epilogo a sorpresa in chiave surrealista...","es":"Aldo cumple condena por fraude con tarjetas de crédito. Cuando es llevado al juzgado en el coche de policía, se encuentra con una pistola en la guantera y obliga al agente a cambiar el rumbo. Por el camino se encuentran a Giovanni, que detiene el vehículo para denunciar el robo de su coche ignorando la situación, y también es tomado como rehén por Aldo."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg","it":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg","es":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg","de":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg","fr":"https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg"}'::jsonb WHERE id = 271;
UPDATE public.films SET tmdb_id = 50531, titoli_i18n = '{"it":"Chiedimi se sono felice","en":"Ask Me If I''m Happy","es":"Pregúntame si soy feliz","fr":"Demandez-moi si je suis heureux","de":"Chiedimi se sono felice"}'::jsonb, trame_i18n = '{"it":"Aldo, Giovanni e Giacomo, tre grandi amici, sbarcano il lunario lavorando rispettivamente come comparsa nelle opere liriche, statua vivente ai Grandi Magazzini, doppiatore di ruoli irrelevanti. Ma sono anche tre aspiranti attori di teatro con un sogno nel cassetto: mettere in scena una loro particolare versione di \"Cyrano de Bergerac\".","en":"Aspiring thespians Aldo, Giovanni and Giacomo work dead-end jobs while nurturing their dream production of Cyrano de Bergerac, until love for the same woman tears their friendship apart. Three years later, Giovanni and Giacomo reunite after learning that Aldo is dying.","es":"Giovanni y Giacomo, después de tres años sin hablarse, viajan juntos en tren con la mujer causante de su enemistad. Viajan para ver al tercer amigo en discordia, Aldo, enfermo de gravedad. Los tres eran grandes amigos que preparaban representar una versión teatral de Cyrano de Bergerac. Grandes amigos que se ayudaban mtuamente en todo, incluído sus líos con las mujeres. Pero ellas también pueden romper grandes amistades...","fr":"James rencontre John, un ami proche de son, avec qui il avait disputé il y a trois ans et le persuade d''aller visiter leur troisième ami Aldo, qui est en train de mourir en Sicile. À travers des flashbacks, nous apprenons leur histoire: Aldo était le fantôme dans les opéras, James a été le doublage des films où il avait seulement de faire du bruit sans même parler et John vivants mannequin les Grands magasins. Insatisfait de leur carrière, ils tentent de réaliser leur rêve de mettre en scène un spectacle de leur propre. Les femmes du mal cependant les séparer ..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg","en":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg","es":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg","fr":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg","de":"https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg"}'::jsonb WHERE id = 272;
UPDATE public.films SET tmdb_id = 57112, titoli_i18n = '{"it":"Tu la conosci Claudia?","en":"Have You Met Claudia?","es":"Tu la conosci Claudia?","fr":"Tu la conosci Claudia?","de":"Tu la conosci Claudia?"}'::jsonb, trame_i18n = '{"it":"Giovanni, un uomo abitudinario la cui massima aspirazione è vedere \"Passaparola\" sul divano, magari con accanto la moglie Claudia.  Aldo, un tassista innamorato, innamoratissimo di Claudia.  Giacomo, un uomo solo, separato dalla moglie, rimasto un po'' troppo adolescente. Un giorno conosce Claudia e la sua vita cambia.  E'' la stessa Claudia a raccontarci di loro a partire da un prologo che non va perso per nessun motivo.","en":"Claudia is married with Giovanni, a rather dull type. Meek Giacomo is happily divorced, until he meets her. Aldo is a colorful cabbie with whom she had an affair. Who''ll win her heart?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg","en":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg","es":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg","fr":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg","de":"https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg"}'::jsonb WHERE id = 273;
UPDATE public.films SET tmdb_id = 88, titoli_i18n = '{"es":"Dirty Dancing","it":"Dirty Dancing - Balli proibiti","en":"Dirty Dancing","de":"Dirty Dancing","fr":"Dirty Dancing"}'::jsonb, trame_i18n = '{"es":"Johnny Castle es un experto profesor de baile y un amante consumado. Por su parte, Baby Houseman es una aburrida e inocente adolescente de 17 años. Durante el transcurso de un verano, en un balneario para clases acomodadas, el encuentro entre ambos causará más de un recelo, a causa de sus distintos orígenes sociales. Entre ambos media un abismo pero, cuando la música suena, sus cuerpos se abrazan al ritmo del dirty dancing y todos esos detalles desaparecen de repente...","it":"Aspettandosi la solita noia che accompagna un''estate nelle Catskills con la sua famiglia, la diciassettenne Frances \"Baby\" Houseman si ritrova nei panni di una ballerina professionista con l''amore che bussa inaspettatamente.","en":"Expecting the usual tedium that accompanies a summer in the Catskills with her family, 17-year-old Frances ''Baby'' Houseman is surprised to find herself stepping into the shoes of a professional hoofer—and unexpectedly falling in love.","de":"Francis „Baby“ Houseman ist ein Mädchen aus reichem Hause. Sie und ihre Familie verbringen die Sommerferien 1963 in Max Kellermans Hotel, wo Baby dem feschen Tanzlehrer Johnny Castle begegnet - seine Show lässt auch in ihr die Lust steigen, zu tanzen. Doch der Mambogott hat nichts übrig für verwöhnte Mädels aus der Oberschicht. Dann aber fällt seine Tanzpartnerin Penny wegen einer ungewollten Schwangerschaft aus und Baby bietet ihre Hilfe an. Nun soll sie im Schnelldurchgang die komplizierten Figuren des Mambos lernen. Das Paar kommt sich auch emotional schnell näher, muss auf seinem Weg aber diversen Problemen trotzen: eine Reihe von Diebstählen und die goldene Hotelregel, dass Personal und Gäste durch eine unsichtbare Linie voneinander getrennt bleiben müssen, machen Baby und Johnny zu schaffen...","fr":"En 1963. Bébé – de son vrai prénom Frédérique – fille d’une riche famille, passe ses vacances avec ses parents et sa sœur à la pension de la famille Kellerman dans l’État de l’Oregon. Elle va être confrontée à un monde qui lui est complètement étranger, celui de la danse, et vivre une histoire d’amour avec Johnny, l’un des professeurs de danse de l’établissement, issu d’un milieu social très différent. Film à petit budget d’Émile Ardolino, il deviendra l’un des plus grand succès des années 80."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/4uGWtDrtPLoMiEjotQaqZTDnqUn.jpg","it":"https://image.tmdb.org/t/p/w500/4wj0T7FSD2FohE1IHAXU3brpL4U.jpg","en":"https://image.tmdb.org/t/p/w500/9Jw6jys7q9gjzVX5zm1z0gC8gY9.jpg","de":"https://image.tmdb.org/t/p/w500/m9T9x2EXIyPssM6hFq5okkeeAk4.jpg","fr":"https://image.tmdb.org/t/p/w500/osfBQ18P0y3pwT5qVuhdPk8btbj.jpg"}'::jsonb WHERE id = 274;
UPDATE public.films SET tmdb_id = 2898, titoli_i18n = '{"it":"Qualcosa è cambiato","de":"Besser geht''s nicht","en":"As Good as It Gets","fr":"Pour le pire et pour le meilleur","es":"Mejor... imposible"}'::jsonb, trame_i18n = '{"it":"Lui è un misantropo razzista, villano, paranoico, ossessionato da tic e complessi. Ma nella sua eccentrica vita stanno per entrare un pittore omosessuale con il suo delizioso cagnolino e una ragazza-madre che fa la cameriera.","de":"Melvin Udall ist ein brillanter Autor von Liebesromanen in New York. Gleichzeitig ist er aber auch ein Misanthrop, ein Grobian und ein Neurotiker, versehen mit einer ganzen Reihe seltsamer Ticks und Vorurteilen und ungeübt im Umgang mit anderen Menschen. Sein einziger menschlicher Kontakt ist seine Stammkellnerin in seinem Stammrestaurant, die jedoch andere Sorgen als ihn hat. Auch seinem schwulen Nachbarn Simon Bishop gegenüber ist er äußerst unfreundlich, muss aber eines Tages den verhassten Hund des Nachbarn zur Pflege aufnehmen. Und der Hund schafft, was niemand für möglich gehalten hat: Melvins Panzer beginnt zu bröckeln; er fängt an, Simon zu helfen, als dieser in Not gerät und bemüht sich, seine Gefühle für die Kellnerin Carol zu formulieren. Natürlich hat er da noch eine Menge aufzuholen, doch er bemüht sich, so gut es geht.","en":"A misanthropic author, a single mother and waitress, and a gay artist form an unlikely friendship after the artist is assaulted in a robbery.","fr":"Melvin Udall, un écrivain misanthrope, écrit à la chaîne des romans sentimentaux qui comblent son sens pervers de l''autodérision et lui permettent de vivre confortablement. Sa vie est réglée comme du papier à musique, il évite le contact humain hormis celui de Carol Connelly, une jeune mère célibataire, serveuse dans un restaurant où il prend ses repas. Un jour, Simon Bishop, son voisin, artiste gay, est défiguré par deux voyous, le fils de Carol tombe malade et Melvin hérite du chien de Simon pendant son séjour à l''hôpital. Sa vie en est toute bouleversée.","es":"Melvin Udall, un escritor obsesivo y maniático, es uno de los seres más desagradables y desagradecidos que uno pueda tener como vecino. Pero, un buen día, tiene que hacerse cargo de un perro al que odia a muerte. La presencia en su vida del animal ablandará su corazón."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tmwubiSQ4IwJbRqSoyNFb7tMAVg.jpg","de":"https://image.tmdb.org/t/p/w500/nUVlD7hfxTWsYD4eTb8JDwjngTS.jpg","en":"https://image.tmdb.org/t/p/w500/xXxuJPNUDZ0vjsAXca0O5p3leVB.jpg","fr":"https://image.tmdb.org/t/p/w500/7DnNgfY9l8flUtqdF21sJCt84S6.jpg","es":"https://image.tmdb.org/t/p/w500/zr9FWAFnjeBugw725udOypnXXMY.jpg"}'::jsonb WHERE id = 275;
UPDATE public.films SET tmdb_id = 516043, titoli_i18n = '{"en":"Here Come the Teachers","fr":"Arrivano i prof","de":"Arrivano i prof","es":"Llegan los profes","it":"Arrivano i prof"}'::jsonb, trame_i18n = '{"en":"The Manzoni High School in Milan is the worst in Italy. When the percentage of those promoted falls to 12%, it''s time for the last resort: to entrust the classes to the worst of the available teachers.","es":"Mientras (casi) todos festejan el aprobado del examen de madurez, en el instituto Alessandro Manzoni hay una gran preocupación: solo el 12% de los estudiantes ha logrado obtener el diploma. El Manzoni tiene un récord absoluto: es el peor instituto de Italia. No sabiendo ya que medidas adoptar, el Director escucha la propuesta del Superintendente y decide llevar a cabo un último, extremo y arriesgado intento: reclutar a los peores profesores en activo seleccionados por un algoritmo del ministerio con la esperanza que donde han fracasado los mejores, puedan triunfar los peores. Objetivo: tener al menos un 50% de aprobados.","it":"Mentre (quasi) tutti festeggiano le promozioni all''esame di maturità, al liceo Alessandro Manzoni c''è grande preoccupazione: solo il 12% degli studenti è riuscito a conseguire il diploma. Il Manzoni ha un primato assoluto: è il peggior liceo d''Italia. Non sapendo più che soluzioni adottare, il Preside accoglie la proposta del Provveditore e decide di fare un ultimo, estremo, rischioso tentativo: reclutare i peggiori insegnanti in circolazione selezionati dall''algoritmo ministeriale nella speranza che dove hanno fallito i migliori, possano riuscire i peggiori. Obiettivo: avere almeno il 50% di promossi."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg","fr":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg","de":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg","es":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg","it":"https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg"}'::jsonb WHERE id = 276;
UPDATE public.films SET tmdb_id = 9802, titoli_i18n = '{"de":"The Rock - Fels der Entscheidung","it":"The Rock","en":"The Rock","fr":"Rock","es":"La roca"}'::jsonb, trame_i18n = '{"de":"Der Beatles-Fan und FBI-Bombenexperte Stanley Goodspeed wird zu einem Notfalleinsatz auf Alacatraz gerufen. Auf der Gefängnisinsel hat sich General Hummel mit einer Hand voll Söldnern verschanzt, um mit Geiseln und Giftgasraketen 100 Millionen Dollar für die Hinterbliebenen gefallener Golfkriegs-Soldaten zu erpressen. Goodspeed soll die Raketen entschärfen, doch nur der Ex-Agent Patrick Mason kennt den Weg in die Festung…","it":"The Rock veniva chiamata la prigione di Alcatraz, chiusa nel 1963. La leggenda racconta che mai un solo detenuto sia riuscito a evadere da quella \"rocca\" situata proprio nel mezzo della baia di San Francisco. È proprio in quella prigione, divenuta meta turistica, che un generale dei marines nasconde tre missili con testate di gas nervino: vuole protestare per come il governo ha trattato i reduci del Vietnam. Se non gli daranno un centinaio di milioni di dollari farà esplodere i missili su San Francisco. A risolvere la situazione vengono chiamati un chimico e un ex agente inglese, l''unico detenuto che sia riuscito, trent''anni prima, a evadere da Alcatraz. Complice un certo pentimento del generale, i due riescono nell''impresa.","en":"When vengeful General Francis X. Hummel seizes control of Alcatraz Island and threatens to launch missiles loaded with deadly chemical weapons into San Francisco, only a young FBI chemical weapons expert and notorious Federal prisoner have the skills to penetrate the impregnable island fortress and take him down.","fr":"Excédé par l’injustice de son gouvernement, le Général Hummel se rend maître de l’île d’Alcatraz et menace de lancer un gaz mortel sur San Francisco. Deux hommes sont chargés de le contrer : un expert en armes chimiques, Stanley Goodspeed, et John Patrick Mason, l’unique prisonnier à s’être évadé d’Alcatraz… Ils se rendent ensemble sur l’île afin de stopper les projets destructeurs du Général.","es":"Un grupo de soldados renegados roba un arma química y toma la antigua cárcel de Alcatraz con 81 turistas como rehenes. Su líder, un general del ejército muy condecorado, pide 100 millones de dólares para entregárselos a las familias de los soldados muertos en operaciones secretas llevadas a cabo por el ejército. Un equipo de élite y un recluso, que en su día pudo huir de Alcatraz, y que conoce los pasadizos que pueblan la prisión, tratarán de evitar que una gran catástrofe se produzca."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/n75Zv7O1S7acu306Njb56GoI0Fz.jpg","it":"https://image.tmdb.org/t/p/w500/leBDsXawQQ6ue7xlB6fIjXEZMZz.jpg","en":"https://image.tmdb.org/t/p/w500/eBcoxveWzzXQrCrwWMGAROcqgpP.jpg","fr":"https://image.tmdb.org/t/p/w500/5TU2NRk8aP40o7IDck0RF24TCyj.jpg","es":"https://image.tmdb.org/t/p/w500/l6PuNPsNFx1UFWfQwjk1McPce4y.jpg"}'::jsonb WHERE id = 277;
UPDATE public.films SET tmdb_id = 118, titoli_i18n = '{"it":"La fabbrica di cioccolato","es":"Charlie y la fábrica de chocolate","fr":"Charlie et la Chocolaterie","en":"Charlie and the Chocolate Factory","de":"Charlie und die Schokoladenfabrik"}'::jsonb, trame_i18n = '{"it":"Charlie Bucket, proviene da una famiglia povera, e spende la maggior parte del suo tempo a sognare la cioccolata che adora, ma che di rado può permettersela. La sua vita cambia quando Willy Wonka, proprietario di una famosissima fabbrica di cioccolato, mette in palio cinque biglietti, nascosti in cinque barrette di cioccolato. I bambini che troveranno uno di questi biglietti potranno fare un tour nella fantastica fabbrica di cioccolato. Charlie trova miracolosamente un biglietto vincente...","es":"Charlie Bucket (Freddie Highmore), un niño muy bueno de una familia muy pobre, gana un concurso, junto a otros cuatro niños de diferentes partes del mundo, para disfrutar de una visita durante todo un día a la gigantesca fábrica de chocolate dirigida por el excéntrico Willy Wonka (Johnny Depp) y su equipo de Oompa-Loompas. La fábrica se parece a un mundo fantástico y mágico lleno de diferentes sabores, todos muy dulces.","fr":"Charlie est un enfant issu d''une famille pauvre. Travaillant pour subvenir aux besoins des siens, il doit économiser chaque penny, et ne peut s''offrir les friandises dont raffolent les enfants de son âge. Pour obtenir son comptant de sucreries, il participe à un concours organisé par l''inquiétant Willy Wonka, le propriétaire de la fabrique de chocolat de la ville. Celui qui découvrira l''un des cinq tickets d''or que Wonka a caché dans les barres de chocolat de sa fabrication gagnera une vie de sucreries.","en":"A young boy wins a tour through the most magnificent chocolate factory in the world, led by the world''s most unusual candy maker.","de":"Seit langem hat niemand mehr den exzentrischen Schokoladenhersteller Willy Wonka gesehen. Eines Tages gewährt der bizarr ausstaffierte Fabrikbesitzer fünf Kindern samt Begleitperson freien Eintritt in seine Fabrik - vorausgesetzt, sie besitzen eines der goldenen Tickets, die nach dem Zufallsprinzip in den Wonka-Schokoladentafeln verteilt wurden. Gegen jede Wahrscheinlichkeit findet der bettelarme Charlie das letzte Ticket und schon am nächsten Tag geht''s los mit der abenteuerlichsten Sightseeingtour der Schokoladengeschichte."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/w2Q8Zx1RCM0aAuG36nOXXJ6pV0u.jpg","es":"https://image.tmdb.org/t/p/w500/voJEk0WNtrcawz2hN9AwdNbvhrp.jpg","fr":"https://image.tmdb.org/t/p/w500/tR4PU2wRPzGKmF665lE5wULGb3X.jpg","en":"https://image.tmdb.org/t/p/w500/iKP6wg3c6COUe8gYutoGG7qcPnO.jpg","de":"https://image.tmdb.org/t/p/w500/wdxuboDikf0srdcQ0nf2uAwbKpR.jpg"}'::jsonb WHERE id = 278;
UPDATE public.films SET tmdb_id = 105, titoli_i18n = '{"de":"Zurück in die Zukunft","en":"Back to the Future","fr":"Retour vers le futur","es":"Regreso al futuro","it":"Ritorno al futuro"}'::jsonb, trame_i18n = '{"de":"Der Teenager Marty McFly wird mit der Zeitmaschine seines Freundes, dem skurrilen Wissenschaftler Dr. Emmett Brown, versehentlich ins Jahr 1955 geschleudert. Dort verhindert er zunächst unabsichtlich, dass sich seine zukünftigen Eltern kennen lernen und in einander verlieben, womit er seine eigene Zeugung gefährdet. Zu allem Überfluss verguckt sich seine Mutter auch noch in ihn. Ihm bleibt nun eine Woche Zeit, seinen tollpatschigen Vater mit seiner Mutter zu verkuppeln und gemeinsam mit Docs dreißig Jahre jüngerem alter Ego einen Plan zu entwickeln, wie sie das bevorstehende große Gewitter nutzen können, um ihn in die Gegenwart zurück zu schicken.","en":"Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents'' first meeting and attracting his mother''s romantic interest. Marty must repair the damage to history by rekindling his parents'' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.","fr":"En 1985, Marty, un adolescent comme les autres, mène une existence morne et ennuyeuse. Heureusement, il est épris de la jolie Jennifer et entretient une profonde amitié avec Doc, un savant fou qui prétend avoir inventé une machine à explorer le temps. Un jour, Doc invite Marty à l''essayer…","es":"El adolescente Marty McFly es amigo de Doc, un científico al que todos toman por loco. Cuando Doc crea una máquina para viajar en el tiempo, un error fortuito hace que Marty llegue a 1955, año en el que sus futuros padres aún no se habían conocido. Después de impedir su primer encuentro, deberá conseguir que se conozcan y se casen; de lo contrario, su existencia no sería posible.","it":"Marty McFly è stato catapultato per errore nel 1955, grazie alla macchina del tempo ideata dal suo amico scienziato Doc. Non avendo più \"carburante\" per poter tornare nel futuro si rivolge alla versione più giovane di Doc, che nonostante l''incredulità iniziale si farà in quattro per aiutarlo. Ma nel 1955 non è solo Doc ad essere più giovane, Marty infatti si imbatte casualmente nei suoi genitori, all''epoca teenager, ma l''incontro aggiungerà altri problemi."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/i9cmMivQ8cgTYUjfrzznsFJ0GYg.jpg","en":"https://image.tmdb.org/t/p/w500/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg","fr":"https://image.tmdb.org/t/p/w500/iCgFtDUZxN8iUzNBCisjUrBmg2q.jpg","es":"https://image.tmdb.org/t/p/w500/owk40tn1sFJmC7bhamEpmhdZPKa.jpg","it":"https://image.tmdb.org/t/p/w500/isqoi7kuUsR5Drlqdh4ZfMULgox.jpg"}'::jsonb WHERE id = 279;
UPDATE public.films SET tmdb_id = 165, titoli_i18n = '{"it":"Ritorno al futuro - Parte II","es":"Regreso al futuro II","en":"Back to the Future Part II","de":"Zurück in die Zukunft II","fr":"Retour vers le futur II"}'::jsonb, trame_i18n = '{"it":"Il film comincia dove terminava il primo capitolo, ovvero con Marty e Jennifer che partono insieme allo scienziato Doc, inventore della macchina del tempo, per il 2015 allo scopo di evitare che il futuro dei loro figli possa essere in pericolo. Ma la situazione precipita e ad essere in pericolo non è più il futuro, ma il passato. Marty dovrà tornare nuovamente nel 1955 e...","es":"Aunque a Marty McFly todavía le falta tiempo para asimilar el hecho de estar viviendo dentro de la familia perfecta gracias a su anterior viaje en el tiempo, no le queda ni espacio para respirar cuando su amigo Doc aparece de improviso con la máquina del tiempo (mucho más modernizada), e insta a que le acompañen él y su novia a viajar al futuro para solucionar un problema con la ley que tendrá uno de sus futuros hijos. En la tremenda vorágine futurista, con todo lo que ello conlleva, del Hill Valley de 2015, la presencia de tales viajeros temporales causará un efecto mayor que el que iban a arreglar. Un almanaque deportivo y la posesión del secreto de la existencia de la máquina del tiempo por parte del siempre villano Biff Tannen, serán los ingredientes que conjugarán una causa-efecto en el pasado, en el presente y en el propio futuro, que hará que Marty y Doc se tengan que emplear a fondo para poner fin a la catástrofe a la que les lleva el destino.","en":"Marty and Doc are at it again as the time-traveling duo head to 2015 to nip some McFly family woes in the bud. But things go awry thanks to bully Biff Tannen and a pesky sports almanac. In a last-ditch attempt to set things straight, Marty finds himself bound for 1955 and face to face with his teenage parents -- again.","de":"Nachdem Doc Brown am Ende des ersten Teiles Marty mit in die Zukunft genommen hat, sieht er nun selbst, was aus ihm werden wird - ein abgehalfterter Angestellter, der am Ende der Karriereleiter steht.Marty und Doc Brown versuchen, der Zukunft einen kleinen Schubser in die richtige Richtung zu geben. Doch Biff gibt seiner eigenen Zukunft durch einen Fehler Martys eine neue Wendung - und dieser Fehler muß nun ausgebügelt werden...","fr":"En 1985, Marty McFly a retrouvé sa famille et sa petite amie après un voyage mouvementé dans le passé. Surgit alors Doc Brown, au volant de sa machine à explorer le temps. Il lui enjoint de le suivre dans le futur, en l''an 2015, pour secourir son fils tombé sous la coupe du sinistre Biff Tannen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/AbwX5BzdmfA0WFBxBF909Gf4Sop.jpg","es":"https://image.tmdb.org/t/p/w500/oTiQdzBOP5biNvzvrSPAvPxiSKH.jpg","en":"https://image.tmdb.org/t/p/w500/hQq8xZe5uLjFzSBt4LanNP7SQjl.jpg","de":"https://image.tmdb.org/t/p/w500/9m396LRrW2PwIKAogU19pnGpJCI.jpg","fr":"https://image.tmdb.org/t/p/w500/pvSf95zo0GZNp83QCtmK1GFLHtT.jpg"}'::jsonb WHERE id = 280;
UPDATE public.films SET tmdb_id = 196, titoli_i18n = '{"de":"Zurück in die Zukunft III","fr":"Retour vers le futur III","es":"Regreso al futuro III","en":"Back to the Future Part III","it":"Ritorno al futuro - Parte III"}'::jsonb, trame_i18n = '{"de":"Als Dr. Emmett Brown im Jahre 1955 bei einem Landeversuch mit dem DeLorean vom Blitz getroffen wird, katapultiert ihn die Zeitmaschine in das Jahr 1885. Sofort schreibt er Marty McFly einen Brief, in dem er seinen Freund darüber unterrichtet, dass es ihm gut gehe und er seinen Lebensabend gern in dieser Epoche verbringen würde. Dank des zuverlässigen Postsystems erreicht der Brief Marty 70 Jahre später, direkt nachdem dieser mit ansehen musste, wie die Zeitmaschine im bewölkten Nachthimmel von Hill Valley verschwand. Kurz darauf findet Marty allerdings heraus, dass der schrullige Wissenschaftler eine Woche nach seiner Ankunft im Wilden Westen erschossen wird. Um dies zu vereiteln, begibt er sich kurzerhand selbst auf die Reise in das Jahr 1885.","fr":"Ce troisième épisode propulse Marty sur une toute nouvelle mission… en l''an 1885, en plein Far West ! Il n''a que cinq jours pour sauver son ami Doc des griffes du terrible Buford \"Molosse\" Tannen et ainsi lui éviter la mort. Cependant, bon nombre d''embûches vont empêcher nos deux voyageurs de rentrer rapidement vers le futur : ils devront faire face à une panne de la DeLorean, leur très célèbre machine à remonter le temps, affronter une bande de hors-la-loi et croiser sur leur route une maîtresse d''école dont le charme ne laissera pas insensible ce bon vieux Doc…","es":"Marty McFly sigue en 1955 y su amigo Doc ha retrocedido al año 1885, la época del salvaje oeste. Éste le envía una carta donde comenta que la máquina del tiempo está averiada, y que es imposible repararla. Sin embargo no le preocupa estar atrapado en el pasado, pues allí es muy feliz trabajando de herrero aunque convive con malhechores. Pero Marty descubre una vieja tumba en la que lee que Doc murió en 1885 y, sin pensárselo dos veces, irá a rescatar a su amigo.","en":"The final installment finds Marty digging the trusty DeLorean out of a mineshaft and looking for Doc in the Wild West of 1885. But when their time machine breaks down, the travelers are stranded in a land of spurs. More problems arise when Doc falls for pretty schoolteacher Clara Clayton, and Marty tangles with Buford Tannen.","it":"Per questa terza, conclusiva, puntata della trilogia, Marty McFly è costretto a tornare indietro nel tempo fino al 1885 per salvare Doc, che vi era stato catapultato al termine del secondo capitolo. Questa volta tornare nel futuro sarà ancora più difficile."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/9VCSpNGyHBwwZRFF8zwgzcoA7tC.jpg","fr":"https://image.tmdb.org/t/p/w500/xormrixo6PYdjyh31JWT2LCBmjO.jpg","es":"https://image.tmdb.org/t/p/w500/yamBr3ihlWFF9jh3oOODSvjDY2e.jpg","en":"https://image.tmdb.org/t/p/w500/crzoVQnMzIrRfHtQw0tLBirNfVg.jpg","it":"https://image.tmdb.org/t/p/w500/iBfwdp2Sp4aWH9QaHUqFq25sxIU.jpg"}'::jsonb WHERE id = 281;
UPDATE public.films SET tmdb_id = 278, titoli_i18n = '{"it":"Le ali della libertà","es":"Cadena perpetua","en":"The Shawshank Redemption","de":"Die Verurteilten","fr":"Les Évadés"}'::jsonb, trame_i18n = '{"it":"Siamo nel 1946. Processato per l''omicidio della moglie e del suo amante, Andy, un bancario del New England, viene condannato a un doppio ergastolo e recluso nel penitenziario di Shawshank. All''inizio è vittima delle violenze dei reclusi, poi però diventa il consulente finanziario delle guardie. Scopre così che il direttore falsifica i libri contabili intestando i conti a un fittizio Randall Stevens. Fuggito di prigione attraverso un tunnel costruito negli anni, Andy assume l''identità di Randall Stevens, denuncia il direttore e va in Messico.","es":"Acusado del asesinato de su mujer, Andrew Dufresne, tras ser condenado a cadena perpetua, es enviado a la prisión de Shawshank. Con el paso de los años conseguirá ganarse la confianza del director del centro y el respeto de sus compañeros presidiarios, especialmente de Red, el jefe de la mafia de los sobornos.","en":"Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.","de":"Das Shawshank Gefängnis in den 30ern: der wegen Mordes an seiner Frau verurteilte Andy Dufresne kommt als Neuling lebenslänglich hinter Gittern. Zurückhaltend wie er ist, ist er ständig das Ziel sexueller Angriffe, doch als er als Banker durchblicken läßt, daß er finanziell für den Direktor und die Wärter eine Menge tun kann, ist für seine Sicherheit gesorgt. Langsam aber sicher freundet er sich mit dem Langzeitinsassen Red an, baut die Gefängnisbibliothek auf und rückt nie von seiner Überzeugung ab, unschuldig zu sein. Viele Jahre vergehen, bis etwas geschieht, was sogar Reds Leben für immer verändern wird...","fr":"En 1947, Andy Dufresne, un jeune banquier, est condamné à la prison à vie pour le meurtre de sa femme et de son amant. Ayant beau clamer son innocence, il est emprisonné à Shawshank, le pénitencier le plus sévère de l''État du Maine. Il y fait la rencontre de Red, un noir désabusé, détenu depuis vingt ans. Commence alors une grande histoire d''amitié entre les deux hommes…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9OxcvTJwZDjQTFvY2NxiwnSrQS6.jpg","es":"https://image.tmdb.org/t/p/w500/uRRTV7p6l2ivtODWJVVAMRrwTn2.jpg","en":"https://image.tmdb.org/t/p/w500/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg","de":"https://image.tmdb.org/t/p/w500/78Pb6FMLMfpm1jUOKTniwREYgAN.jpg","fr":"https://image.tmdb.org/t/p/w500/t30GjttOdb5At1sYy8b3TOwFgWV.jpg"}'::jsonb WHERE id = 282;
UPDATE public.films SET tmdb_id = 510, titoli_i18n = '{"fr":"Vol au-dessus d''un nid de coucou","es":"Alguien voló sobre el nido del cuco","it":"Qualcuno volò sul nido del cuculo","de":"Einer flog über das Kuckucksnest","en":"One Flew Over the Cuckoo''s Nest"}'::jsonb, trame_i18n = '{"fr":"Randle P. McMurphy se fait interner pour échapper à la prison. Il va être touché par la détresse et la solitude des patients. Très rapidement, il comprend que l’infirmière en chef, Mlle Ratched, a imposé des règles strictes et entend bien les faire respecter. Il décide alors de révolutionner ce petit monde, plutôt au départ par jeu.","es":"Randle McMurphy (Jack Nicholson), un violador de espíritu libre, que vive contracorriente, es recluido en un hospital psiquiátrico. La inflexible disciplina del centro acentúa su contagiosa tendencia al desorden, que acabará desencadenando una guerra entre los pacientes y el personal de la clínica con la fría y severa enfermera Ratched (Louise Fletcher) a la cabeza. La suerte de cada paciente del pabellón está en juego.","it":"Candle McMurphy, arrestato per piccoli reati, viene portato in una clinica psichiatrica: tenta di fingersi pazzo per sfuggire al carcere. Qui viene a contatto con gli altri pazienti dei quali diventa ben presto il beniamino: si prende gioco delle sedute di psicoanalisi, si improvvisa telecronista, organizza una piccola gita in barca. L''ospedale è diretto dalla ferrea capoinfermiera, la signorina Ratched che ha organizzato la vita dei pazienti secondo regole di intransigente disciplina.","de":"McMurphy ist ein krimineller gesellschaftlicher Außenseiter. Mitte dreißig, ehemaliger Korea-Kämpfer, wegen Ungehorsam aus der Armee entlassen, wird er wegen Schlägereien, Notzucht und Trunksucht in eine Strafanstalt eingeliefert. Von dort aus lässt er sich mit einem Trick zur Beobachtung in eine psychiatrische Anstalt überweisen. In die graue Welt einer anonymen Heilanstalt wird McMurphy eines Tages eingeliefert. Er findet dort ein unmenschliches System vor, das seine hilf- und willenlosen Patienten in „Chronische“ (schwere Fälle) und „Akute“ (leichte Fälle) aufteilt. Eine despotische Oberschwester unterdrückt mit einer Schar brutaler Wärter jede individualistische Regung. Der Zustand der Kranken wird mit pharmazeutischen Mitteln oder Elektroschock-Therapie „behandelt“ und dadurch noch weiter verschlechtert. In diesem System muss McMurphy wie ein Katalysator wirken … er stellt das System der Irrenanstalt in Frage und wiegelt die Insassen auf.","en":"A petty criminal fakes insanity to serve his sentence in a mental ward rather than prison. He soon finds himself as a leader to the other patients—and an enemy to the cruel, domineering nurse who runs the ward."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/r5b2ub7GMawCWDP5vHR1MXpV7vU.jpg","es":"https://image.tmdb.org/t/p/w500/lBYmCynNEPt7HVaJvuXgfHvLhbJ.jpg","it":"https://image.tmdb.org/t/p/w500/hpg2j8FhnnmbiRpoOU09M0sffJu.jpg","de":"https://image.tmdb.org/t/p/w500/8ifFMKq21P0A2xV4q7K5VfuR4Cp.jpg","en":"https://image.tmdb.org/t/p/w500/kjWsMh72V6d8KRLV4EOoSJLT1H7.jpg"}'::jsonb WHERE id = 283;
UPDATE public.films SET tmdb_id = 642, titoli_i18n = '{"fr":"Butch Cassidy et le Kid","de":"Zwei Banditen","es":"Dos hombres y un destino","it":"Butch Cassidy","en":"Butch Cassidy and the Sundance Kid"}'::jsonb, trame_i18n = '{"fr":"Au début du XXème siècle, Butch Cassidy et son ami Sundance Kid pillent les trains et les banques. Les deux malfrats élaborent un plan ingénieux qui leur permet de dévaliser deux fois le même convoi, mais les autorités sont sur leur piste. Le Kid retrouve son amie, Etta Place, une jeune institutrice, et Butch Cassidy improvise avec elle un brillant numéro à bicyclette. La seconde attaque de l''Union Pacific oblige les deux complices et Etta à abandonner leurs amis et à fuir en Bolivie. Là, ils poursuivent leurs exploits criminels et ce, malgré la défection de la jeune femme, effrayée par la tournure que prennent les événements.","de":"Um die Jahrhundertwende planen die beiden berühmt-berüchtigten Desperados Butch Cassidy  und Sundance Kid  den Zug der Union Pacific gleich zweimal zu überfallen: nämlich auf der Hin- und auf der Rückfahrt. Doch diese Dreistigkeit lässt sich die Regierung nicht gefallen: Von einer Elitetruppe werden die beiden bis zur Erschöpfung gejagt","es":"Un grupo de jóvenes pistoleros se dedica a asaltar los bancos del estado de Wyoming y el tren-correo de la Union Pacific. El jefe de la banda es el carismático Butch Cassidy, y Sundance Kid es su inseparable compañero. Un día, después de un atraco, el grupo se disuelve. Será entonces cuando Butch, Sundance y una joven maestra de Denver formen un trío de románticos forajidos que, huyendo de la ley, llegan hasta Bolivia.","it":"Butch e Sundance sono due rapinatori che dopo ogni colpo, si rifugiano da una maestra innamorata di Sundance e corteggiata da Butch. Ma un giorno la Union Pacific, bersaglio di una loro rapina assolda un gruppo di guardie private ed allora i due rapinatori sono costretti a cambiare aria...","en":"As the west rapidly becomes civilized, a pair of outlaws in 1890s Wyoming find themselves pursued by a posse and decide to flee to South America in hopes of evading the law."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/okSvpbn4OBEHfjKeaN8ccZAvLAS.jpg","de":"https://image.tmdb.org/t/p/w500/wHF7wueTLjb7dqt1MCfLeLDuUP.jpg","es":"https://image.tmdb.org/t/p/w500/2w6Ik8P1E20KOH5ykQlfTjawAIf.jpg","it":"https://image.tmdb.org/t/p/w500/7T9YNd236L9JXLeNTayHZgTrSHJ.jpg","en":"https://image.tmdb.org/t/p/w500/gFmmykF1Ym3OGzENo50nZQaD1dx.jpg"}'::jsonb WHERE id = 284;
UPDATE public.films SET tmdb_id = 9277, titoli_i18n = '{"it":"La stangata","es":"El golpe","en":"The Sting","fr":"L''Arnaque","de":"Der Clou"}'::jsonb, trame_i18n = '{"it":"Johnny Hooker e il suo amico Luther Coleman sono due truffatori di strada. Dopo aver raggirato il corriere del potente gangster Doyle Lonnegan, Luther viene ucciso per ritorsione e Hooker è costretto a fuggire e a nascondersi. Desiderando vendicare Luther, il giovane chiede aiuto ad un vecchio amico del defunto, Henry Gondorff, uno dei più bravi ed esperti truffatori degli Stati Uniti. Insieme organizzano una \"stangata\" ai danni di Lonnegan, creando una finta agenzia di scommesse in cui il boss crede di poter vincere facilmente delle ingenti somme di denaro, grazie a informazioni riservate.","es":"En Illinois, en 1936, dos ladrones dan un golpe a un hombre de confianza de un gángster y se embolsan un montón de dinero. El gángster decide vengarse y mata a uno de los que dieron el golpe, mientras que el otro logra escapar y entra en contacto con un ex compinche. Los dos deciden intentar un gran timo que hará temblar las finanzas del jefe de la mafia.","en":"A novice con man teams up with an acknowledged master to avenge the murder of a mutual friend by pulling off the ultimate big con and swindling a fortune from a big-time mobster.","fr":"À Chicago, en 1936, Johnny Hooker et son acolyte Coleman volent sans le savoir le convoyeur de fonds de Doyle Lonnegan, un dangereux gangster de New York. Coleman est aussitôt abattu par le gang de ce dernier et Hooker se réfugie chez Henry Gondorff, un spécialiste de l''arnaque. Ceux-ci décident alors de venger la mort de Coleman en montant une vaste escroquerie destinée à mettre Lonnegan sur la paille. Pour cela, Hooker fait croire au gangster qu''il est capable d''obtenir les résultats des courses avant qu''ils ne soient officiellement connus.","de":"Chicago um 1930. Kleingauner Johnny Hooker und sein schwarzer Partner erleichtern unwissentlich den Geldkurier des mächtigen Unterweltbosses Lonnegan. Der lässt Johnnys Partner ermorden. Johnny wendet sich an den abgehalfterten Gauner Gondorff. Sie fädeln einen raffinierten Racheplan ein, setzen auf Lonnegans Wettleidenschaft. Mit Kollegen, die von Lonnegan reingelegt worden sind, errichten sie ein falsches Wettbüro. Johnny wird zum Schein von Gondorff erschossen, Lonnegans Millionen wandern in ihre Hände."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jnD4EA8uULiNGxk96jfheznoEwz.jpg","es":"https://image.tmdb.org/t/p/w500/cnCv2NhtymMwq5oWSzoz6tXcjQf.jpg","en":"https://image.tmdb.org/t/p/w500/ckmYng37zey8INYf6d10cVgIG93.jpg","fr":"https://image.tmdb.org/t/p/w500/hUhnNuPZHjGDUDaLLnDVIiARLYN.jpg","de":"https://image.tmdb.org/t/p/w500/nFTKS7mPP22a0V2YSj4aE38nhg.jpg"}'::jsonb WHERE id = 285;
UPDATE public.films SET tmdb_id = 539, titoli_i18n = '{"it":"Psyco","es":"Psicosis","en":"Psycho","de":"Psycho","fr":"Psychose"}'::jsonb, trame_i18n = '{"it":"Marion Crane, impiegata in una società immobiliare, scappa con 40.000$ rubati dalle casse della ditta. Durante la fuga verso casa del fidanzato però, decide di fermarsi nel Motel gestito dal giovane Norman Bates e dalla madre, che però vive rintanata nella casa attigua al Motel stesso.  Il capolavoro di Alfred Hitchcock.","es":"Una joven secretaria, tras cometer un robo, se marcha de la ciudad y conduce durante horas, parando para descansar en un pequeño motel de carretera regentado por un joven llamado Norman. Todo parece normal y tranquilo en el apartado motel y en la casa de al lado en la que viven Norman y su madre pero, mientras está en la ducha, la joven es asesinada salvajemente a cuchilladas.","en":"When larcenous real estate clerk Marion Crane goes on the lam with a wad of cash and hopes of starting a new life, she ends up at the notorious Bates Motel, where manager Norman Bates cares for his housebound mother.","de":"Die Sekretärin Marion Crane unterschlägt 40.000 Dollar und macht auf ihrer Flucht in einem abgelegenen Motel Station, das der eigentümliche Norman Bates leitet, der mit seiner Mutter im Haus neben dem Motel lebt. Als Marion sich frisch machen will, wird sie während des Duschens erstochen. Nachdem ein Privatdetektiv, der ihre Spur gefunden hatte, ebenfalls verschwindet, begeben sich Marions Freund Sam und ihre Schwester Lila auf die Suche. Im Bates Motel machen sie eine grausige Entdeckung.","fr":"Marion Crane en a assez de ne pouvoir mener sa vie comme elle l''entend. Son travail ne la passionne plus, son amant ne peut l''épouser car il doit verser une énorme pension alimentaire le laissant sans le sou… Mais un beau jour, son patron lui demande de déposer 40 000 dollars à la banque. La tentation est trop grande, et Marion s''enfuit avec l''argent. Très vite la panique commence à se faire sentir. Partagée entre l''angoisse de se faire prendre et l''excitation de mener une nouvelle vie, Marion roule vers une destination qu''elle n''atteindra jamais. La pluie est battante, la jeune femme s''arrête près d''un motel, tenu par un sympathique gérant nommé Norman Bates, mais qui doit supporter le caractère possessif de sa mère. Après un copieux repas avec Norman, Marion prend toutes ses précautions afin de dissimuler l''argent. Pour se délasser de cette journée, elle prend une douche…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tdqX0MWaFHuGwUygYn7j6eluOdP.jpg","es":"https://image.tmdb.org/t/p/w500/xFbnc2QPG5H5gYWsGbZT4q8Akya.jpg","en":"https://image.tmdb.org/t/p/w500/yz4QVqPx3h1hD1DfqqQkCq3rmxW.jpg","de":"https://image.tmdb.org/t/p/w500/p6ST4wHG90PfHRDMhcA5WsLeh39.jpg","fr":"https://image.tmdb.org/t/p/w500/lzF8b44dAvXFagQnB1UZa2AF87q.jpg"}'::jsonb WHERE id = 286;
UPDATE public.films SET tmdb_id = 521, titoli_i18n = '{"it":"Il delitto perfetto","fr":"Le crime était presque parfait","es":"Crimen perfecto","en":"Dial M for Murder","de":"Bei Anruf Mord"}'::jsonb, trame_i18n = '{"it":"Margot è sposata con Tony, ma i loro rapporti non sono certo idilliaci: lui vive alle spalle di lei perché è benestante e perché è un fannullone, ed inoltre lei è innamorata di uno scrittore americano e medita il divorzio, che sarebbe la rovina per suo marito. Così Tony medita di uccidere Margot per intascare i suoi soldi e vivere di rendita.","fr":"Tony Wendice, une ancienne gloire du tennis, s''est marié avec Margot pour sa richesse. Mais celle-ci le trompe depuis peu avec Mark Halliday, un jeune auteur de romans policiers. Craignant que sa femme le quitte et le laisse sans le sou, Tony fait appel au capitaine Lesgate et le charge d''assassiner Margot en échange d''une grosse somme d''argent.","es":"Tony Wendice maquina un plan para deshacerse de Margot, su esposa infiel. Pero la casualidad hará que sea a ella a quien finalmente acusen de asesinato. La inestimable ayuda de un inspector de policía ayudará a resolver el misterioso crimen.","en":"When her American lover visits London, a wealthy woman’s jealous husband hatches a plan to murder her and inherit her fortune.","de":"Margot ist die reiche Ehefrau des windigen Ex-Profi-Tennisspielers und Playboys Tony Wendice. Tony fürchtet den Verlust des Geldes, weil Margots Liaison mit dem Kriminalroman-Autor Mark zu einer Scheidung führen könnte. Er zwingt einen ehemaligen Schulkameraden, der in Schwierigkeiten steckt, zum Mord an seiner Frau. Der bis ins kleinste Detail minutiös ausgefeilte Plan droht zu scheitern, als Margot es mit letzter Kraft schafft, ihren vermeintlichen Mörder mit einer Schere zu erstechen. Doch Tony schaltet schnell: Mit eiskalter Berechnung liefert er der Polizei Hinweise, die seine Frau nicht nur ins Gefängnis, sondern sogar die Todesstrafe bringen könnten …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/feVfUSdS9k39GSqJjeMLlafV8M6.jpg","fr":"https://image.tmdb.org/t/p/w500/2ikfaqVUxyPq726S8TYihSczkFF.jpg","es":"https://image.tmdb.org/t/p/w500/mRJO5slKZ2kUsTtzAeT0AJHryaY.jpg","en":"https://image.tmdb.org/t/p/w500/2gDCAgl2iBQNuJuk6p2xtuS1ewg.jpg","de":"https://image.tmdb.org/t/p/w500/sPXTBbmgqdeUJyMpPuprPOzkako.jpg"}'::jsonb WHERE id = 287;
UPDATE public.films SET tmdb_id = 571, titoli_i18n = '{"en":"The Birds","es":"Los pájaros","de":"Die Vögel","it":"Gli uccelli","fr":"Les Oiseaux"}'::jsonb, trame_i18n = '{"en":"Thousands of birds flock into a seaside town and terrorize the residents in a series of deadly attacks.","es":"Melanie, una joven rica y snob de la alta sociedad de San Francisco, conoce casualmente en una pajarería al abogado Mitch Brenner, que ha ido a comprar un regalo de cumpleaños para Kathy, su hermana pequeña. Mitch, que conoce por la prensa la alocada vida de Melanie, la trata despectivamente y se va de la tienda dejándola bastante irritada. Ella, que no está acostumbrada a que la traten así, encarga unos periquitos y los lleva a casa del abogado, pero Mitch se ha ido a pasar el fin de semana a casa de su madre. Entonces, Melanie decide ir a Bodega Bay y presentarse en casa de los Brenner con el pretexto de regalar los periquitos a Kathy. En cuanto ella llega, los pájaros, enloquecidos, empiezan a atacar salvajemente a los habitantes del lugar. La situación se agrava a medida que avanzan las horas.","de":"Melanie Daniels, gelangweilte Tochter eines Pressezaren, verliebt sich beim Einkaufen in der Stadt in den Anwalt Mitch Brenner und folgt ihm in dessen kleines Heimatnest an der Pazifikküste. Dort macht sie nicht nur unangenehme Bekanntschaft mit Mitchs reservierter Mutter, sondern auch mit den Vögeln der Umgebung, die sich just an diesem Tag ganz besonders unnatürlich geben. Was zunächst niemanden weiter besorgt, erwächst zum echten Problem, als die Vögel in militärisch anmutenden Formationen zu lebensgefährlichen Attacken auf die Menschen übergehen.","it":"Melanie Daniels incontra Mitch Brenner in un negozio di animali di San Francisco. Lui vorrebbe comprare una coppia di inseparabili per regalarli a sua sorella per il suo compleanno, lei finge di essere una commessa del negozio, lui non le crede, ma sta al gioco. Melanie decide poi di comprare una coppia di inseparabili e di andare a Bodega Bay, un tranquillo paesino costiero, dove Mitch passa i suoi fine settimana con la sorellina e la madre, per fargli una sorpresa. Al suo arrivo viene attaccata da un gabbiano, e sarà il primo di una lunga, inspiegabile serie di attacchi da parte degli uccelli...","fr":"Melanie, jeune femme quelque peu superficielle, rencontre chez un marchand d''oiseaux un brillant et séduisant avocat qui recherche des inséparables. Par jeu, Melanie achète les oiseaux et les apporte à Bodega Bay. Dès son arrivée, elle est blessée au front par une mouette..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/ADoJaT1s9Jlcfx3Tw2MIZ1BMxo.jpg","es":"https://image.tmdb.org/t/p/w500/aqMiK53QEC5UyGePN5KmgL7DLNg.jpg","de":"https://image.tmdb.org/t/p/w500/9rDGUfzKVAlUNVP2otDsnyfwMIF.jpg","it":"https://image.tmdb.org/t/p/w500/omnOJCmTGJoxCRJorWIEweu1JTN.jpg","fr":"https://image.tmdb.org/t/p/w500/pIc5nX1neiJ38R7b4e8PKqvxbkD.jpg"}'::jsonb WHERE id = 288;
UPDATE public.films SET tmdb_id = 16515, titoli_i18n = '{"fr":"Capitaines courageux","it":"Capitani coraggiosi","es":"Capitanes intrépidos","en":"Captains Courageous","de":"Manuel"}'::jsonb, trame_i18n = '{"fr":"Le jeune Harvey Cheyne est le fils d''un très riche entrepreneur américain. Il pense pouvoir tout obtenir et tout se permettre grâce à l''argent de son père. Renvoyé temporairement de son école pour avoir tenté de corrompre un professeur, il entreprend une croisière avec son père. Mais il tombe à la mer et se retrouve mousse sur le bateau de pêcheurs qui l''a recueilli. Là sa condition sociale ne lui sera pas d''une grande utilité... Il y fera son éducation d''homme notamment grâce au pêcheur Manuel (Spencer Tracy) qui le prend sous son aile. Il retrouvera finalement son père à la fin de cette aventure initiatique.","it":"Frank Burton Cheyne, un ricco industriale trascura il figlio adolescente Harvey, al punto da trasformarlo in un ribelle arrogante e raccontafrottole. Harvey per i suoi modi arroganti, a scuola viene evitato da tutti, finché un giorno nella tipografia dell''istituto è coinvolto in una zuffa con un suo coetaneo, e ha la peggio. Il Direttore e il Maestro di Harvey fanno visita al padre, comunicandogli la decisione di sospenderlo per tre mesi, raccontandogli la verità sul comportamento di suo figlio, Frank capisce che è ora di riprendere in mano la situazione, prima che sia troppo tardi. Frank porta con se il figlio Harvey in una crociera su una delle sue navi, ma anche li per fare lo sbruffone con due ragazzini ruzzola in mare. Per sua fortuna viene ripescato da Manuel Fidello, un pescatore di professione che lo tira a bordo della sua barca, lo rianima e lo porta sul peschereccio da cui è partito.","es":"Harvey, el hijo arrogante y malcriado de un padre poco cariñoso, cae por la borda de un barco de vapor transatlántico y es rescatado por un barco de pesca en el Gran Banco de Terranova. Harvey trata de convencerles para que lo lleven a tierra alardeando de su riqueza ante la tripulación, aunque nadie le toma en serio. El capitán le ofrece un trabajo mal pagado hasta que regresen a puerto. El duro trabajo como uno más de la tripulación convierte al joven en un hombre maduro y considerado.","en":"Harvey, the arrogant and spoiled son of an indulgent absentee-father, falls overboard from a transatlantic steamship and is rescued by a fishing vessel on the Grand Banks. Harvey fails to persuade them to take him ashore, nor convince the crew of his wealth. The captain offers him a low-paid job, until they return to port, as part of the crew that turns him into a mature, considerate young man.","de":"Nachdem er von der Schule geflogen ist, will der schwerreiche Vater des verzogenen, zehnjährigen Harvey Versäumtes nachholen und ihn in erzieherischer Absicht auf eine Schiffsreise nach Europa mitnehmen. Dummerweise fällt Harvey auf See über Bord, hat aber Glück im Unglück und wird von dem portugiesischen Fischer Manuel gerettet. Da dessen Schiff für die nächsten Monate keinen Hafen ansteuern wird, sieht sich Harvey gezwungen, sich unter Anleitung Manuels nützlich zu machen, was seiner charakterlichen Entwicklung nur zuträglich ist."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/ua7U0VMBrK3g5xI4lExx2q1Rxg9.jpg","it":"https://image.tmdb.org/t/p/w500/xez8YMw0BhIS7bY0f1rxfdzQcX9.jpg","es":"https://image.tmdb.org/t/p/w500/rsXZmQjSZyZQgETa2AYYQEbBnj8.jpg","en":"https://image.tmdb.org/t/p/w500/qhJNHLwIcMqDKBwsr9uMDOumO33.jpg","de":"https://image.tmdb.org/t/p/w500/vazg1O2ExJCh8uDVQUKkB0zPDkX.jpg"}'::jsonb WHERE id = 289;
UPDATE public.films SET tmdb_id = 1214931, titoli_i18n = '{"en":"Nuremberg","it":"Norimberga","es":"Núremberg","de":"Nürnberg","fr":"Nuremberg"}'::jsonb, trame_i18n = '{"en":"In postwar Germany, an American psychiatrist must determine whether Nazi prisoners are fit to go on trial for war crimes, and finds himself in a complex battle of intellect and ethics with Hermann Göring, Hitler''s right-hand man.","it":"All’indomani della Seconda guerra mondiale, mentre il mondo è ancora sconvolto dagli orrori dell’Olocausto, al tenente colonnello Douglas Kelley, psichiatra dell’esercito americano, viene affidato un incarico senza precedenti: valutare la sanità mentale di Hermann Göring, il famigerato ex braccio destro di Hitler, e di altri alti gerarchi nazisti. Allo stesso tempo, gli Alleati — guidati dal giudice Robert H. Jackson — affrontano l’impresa titanica di istituire un tribunale internazionale, per far sì che il regime nazista risponda dei propri crimini di fronte alla storia. Nel silenzio delle celle, Kelley ingaggia un intenso duello psicologico con Göring, uomo carismatico e manipolatore. Da quello scontro emerge una domanda che ancora oggi tormenta la coscienza del mondo:stavano eseguendo ordini, erano pazzi… o semplicemente malvagi? Sul palcoscenico della storia si apre così il processo di Norimberga, un evento che ha cambiato per sempre la storia e l’umanità.","es":"Tras el fin de la II Guerra Mundial, con ocasión de los cruciales e inminentes juicios de Nuremberg contra el derrotado régimen Nazi, el psiquiatra estadounidense Douglas Kelley (Malek), encargado de determinar si los oficiales nazis prisioneros son aptos para ser juzgados por sus crímenes de guerra, se ve inmerso en una compleja batalla de ingenio dialéctico con Hermann Göring (Crowe), mano derecha de Hitler. Basada en el libro \"El nazi y el psiquiatra\", de Jack El-Hai.","de":"Hermann Göring wird von den Alliierten verhaftet und soll als ranghöchster noch verbliebener Nazi für die unfassbaren Taten des NS-Regimes zur Rechenschaft gezogen werden. Der Psychiater Dr. Kelley wird beauftragt, alle Angeklagten auf ihre Prozessfähigkeit hin zu untersuchen. Schnell ist er von Görings Scharfsinn und Charisma eingenommen und obwohl er dessen Machtspiele durchschaut, kann sich Dr. Kelley der manipulativen Stärke und Faszination des Bösen nur schwer entziehen. Um Görings Vertrauen zu gewinnen, überschreitet Dr. Kelley moralische Grenzen und gefährdet sogar den Nürnberger Prozess.  Das bis in die Nebenrollen hochkarätig besetzte Justizdrama erzählt vom folgenreichsten Prozess des 20. Jahrhunderts, der zudem die Geburtsstunde des Völkerrechts markiert.","fr":"Washington, 1945. Hitler s''est suicidé, l''Allemagne a capitulé et les Alliés détiennent 22 officiers nazis, dont Hermann Göring, plus haut gradé du Troisième Reich. Contrairement à ses collègues, qui préconisent leur exécution, Robert H. Jackson, juge à la Cour suprême des États-Unis, obtient que ceux-ci soient traduits devant une cour internationale. Un an avant l''ouverture du procès à Nuremberg, Jackson confie à un psychiatre de l''armée américaine, Douglas Kelley, le mandat d''évaluer les accusés. Secondé par son traducteur, Kelley se met à la tâche, en privilégiant le cas du Reichsmarschall Göring, un pervers narcissique, qui s''engage avec lui dans un jeu du chat et de la souris."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/xthXNYltOOm80vW5Kxjzxx5gvQ6.jpg","it":"https://image.tmdb.org/t/p/w500/ucZHG8KD2A9Czl1aZz1f4bIvbLR.jpg","es":"https://image.tmdb.org/t/p/w500/7OOQRx9SmkMC3UQfdzj4QsQHtA1.jpg","de":"https://image.tmdb.org/t/p/w500/2yVfXfnROnZfPPrArz2MMWfzOSr.jpg","fr":"https://image.tmdb.org/t/p/w500/6iYLH0TjqCyEkCYadpLUMHr9S8J.jpg"}'::jsonb WHERE id = 290;
UPDATE public.films SET tmdb_id = 872585, titoli_i18n = '{"en":"Oppenheimer","es":"Oppenheimer","it":"Oppenheimer","de":"Oppenheimer","fr":"Oppenheimer"}'::jsonb, trame_i18n = '{"en":"The story of J. Robert Oppenheimer''s role in the development of the atomic bomb during World War II.","es":"Película sobre el físico J. Robert Oppenheimer y su papel como desarrollador de la bomba atómica. Basada en el libro ''American Prometheus: The Triumph and Tragedy of J. Robert Oppenheimer'' de Kai Bird y Martin J. Sherwin.","it":"La storia del ruolo di J. Robert Oppenheimer, i cui studi condussero alle scoperte legate alla bomba atomica, con il conseguente utilizzo durante le stragi di Hiroshima e Nagasaki durante la Seconda Guerra Mondiale.","de":"Als dem Physiker Julius Robert Oppenheimer während des Zweiten Weltkriegs die wissenschaftliche Leitung des Manhattan-Projekts übertragen wird, können er und seine Ehefrau Kitty sich nicht vorstellen, welche Auswirkungen Oppenheimers Arbeit nicht nur auf ihr Leben, sondern auf die ganze Welt haben wird. Im Los Alamos National Laboratory in New Mexico sollen er und sein Team unter der Aufsicht von Lt. Leslie Groves eine Nuklearwaffe entwickeln – was ihnen auch gelingt. Oppenheimer wird zum „Vater der Atombombe“ ausgerufen, doch dass seine tödliche Erfindung bald folgenschwer in Hiroshima und Nagasaki eingesetzt wird, lässt Oppenheimer Abstand von dem Projekt nehmen. Als der Krieg zu Ende geht, setzt sich Robert Oppenheimer als Berater der US-amerikanischen Atomenergiebehörde, die von Lewis Strauss mitbegründet wurde, für eine internationale Kontrolle von Kernenergie und gegen ein nukleares Wettrüsten ein – und gerät ins Visier des FBI.","fr":"En 1942, convaincus que l''Allemagne hitlérienne est en train de développer une arme nucléaire, les États-Unis initient, dans le plus grand secret, le  « Projet Manhattan » destiné à mettre au point la première bombe atomique de l’histoire. Pour piloter ce dispositif, le gouvernement engage J. Robert Oppenheimer, brillant physicien, qui sera bientôt surnommé « le père de la bombe atomique ». C''est dans le laboratoire ultra-secret de Los Alamos, au cœur du désert du Nouveau-Mexique, que le scientifique et son équipe mettent au point une arme révolutionnaire dont les conséquences, vertigineuses, continuent de peser sur le monde actuel…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg","es":"https://image.tmdb.org/t/p/w500/mJRUREPjTqqMEKwEiM2sdmIGngz.jpg","it":"https://image.tmdb.org/t/p/w500/fRtaxfyynWMJI6DhejyA6JOzVTB.jpg","de":"https://image.tmdb.org/t/p/w500/9AiHV08v8RyyuHcO5wuTaTXBxfe.jpg","fr":"https://image.tmdb.org/t/p/w500/boAUuJBeID7VNp4L7LNMQs8mfQS.jpg"}'::jsonb WHERE id = 291;
UPDATE public.films SET tmdb_id = 515001, titoli_i18n = '{"en":"Jojo Rabbit","es":"Jojo Rabbit","de":"Jojo Rabbit","it":"Jojo Rabbit","fr":"Jojo Rabbit"}'::jsonb, trame_i18n = '{"en":"Jojo, a lonely German boy during World War II has his world shaken when he learns that his single mother is hiding a Jewish girl in their home. Influenced by a buffoonish imaginary version of Adolf Hitler, he begins to question his beliefs and confront the conflict between propaganda and his own humanity.","es":"Jojo Rabbit es un niño viviendo en plena 2ª Guerra Mundial. Su única vía de escape es su amigo imaginario, una versión de Hitler étnicamente incorrecta que incita los ciegos ideales patrióticos del niño. Todo esto cambia cuando descubre que su madre Rosie está escondiendo a una joven judía en su ático.","de":"Jojo Rabbit handelt von einem kleinen Jungen, der während des Zweiten Weltkriegs lebt. Er kann der rauen Wirklichkeit nur durch seinen imaginären Freund entkommen, eine ethnisch ungenaue Version von Adolf Hitler, der die naiven patriotischen Überzeugungen des kleinen Jungen vorantreibt. Das ändert sich jedoch alles, als ein junges Mädchen diese Ansichten hinterfragt und Jojo dazu bringt, sich seinen eigenen Problemen zu stellen.","it":"Jojo, un bambino cresciuto dalla sola madre, ha come unico alleato il suo amico immaginario Adolf Hitler. Il suo ingenuo patriottismo viene però messo alla prova quando incontra una ragazzina che stravolge le sue convinzioni sul mondo, costringendolo ad affrontare le sue paure più grandi.","fr":"Jojo est un petit allemand solitaire. Sa vision du monde est mise à l’épreuve quand il découvre que sa mère cache une jeune fille juive dans leur grenier. Avec la seule aide de son ami aussi grotesque qu''imaginaire, Adolf Hitler, Jojo va devoir faire face à son nationalisme aveugle."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/1mqL7VG4Ix8wmxwypmCA1HTHBky.jpg","es":"https://image.tmdb.org/t/p/w500/5KRPe0XObWOVGVzDaGSAxG2w8bd.jpg","de":"https://image.tmdb.org/t/p/w500/mqE5oPqmT1WU1WxuOloDUIsEKto.jpg","it":"https://image.tmdb.org/t/p/w500/2vv0tEFH10YG3hMRCOhiWsw7bOk.jpg","fr":"https://image.tmdb.org/t/p/w500/t4JPW6GxKOiwqtsursgGynmPffu.jpg"}'::jsonb WHERE id = 292;
UPDATE public.films SET tmdb_id = 475557, titoli_i18n = '{"en":"Joker","de":"Joker","fr":"Joker","it":"Joker","es":"Joker"}'::jsonb, trame_i18n = '{"en":"During the 1980s, a failed stand-up comedian is driven insane and turns to a life of crime and chaos in Gotham City while becoming an infamous psychopathic crime figure.","de":"Gotham City im Jahr 1981: Der mental instabile Arthur Fleck führt wahrlich nicht das Leben, von dem man träumt: Vollgepumpt mit Medikamenten geht er seiner Arbeit als kostümierter Werbeschildträger nach und wird nicht selten das Ziel von Spott und Attacken. Abends zieht es ihn in sein heruntergekommenes Apartment, wo er sich um seine kranke Mutter kümmern muss. Gemeinsam hoffen sie auf ein besseres Leben, das Arthur als Stand-Up-Komiker realisieren will. Als plötzlich die Förderung für seine psychologische Betreuung gestrichen wird, nimmt das Unheil seinen Lauf. Die Schusswaffe eines Kollegen, die Suche nach seinem echten Vater und plötzlicher Ruhm sorgen dafür, dass der einstmals harmlose Exzentriker die ganze Stadt in Angst und Schrecken versetzt …","fr":"Dans les années 1980, à Gotham City, Arthur Fleck, un humoriste de stand‐up raté, bascule dans la folie et devient le Joker.","it":"Arthur Fleck vive con l''anziana madre in un palazzone fatiscente e sbarca il lunario facendo pubblicità per la strada travestito da clown, in attesa di avere il giusto materiale per realizzare il desiderio di fare il comico. La sua vita, però, è una tragedia: ignorato, calpestato, bullizzato, preso in giro da da chiunque, ha sviluppato un tic nervoso che lo fa ridere a sproposito incontrollabilmente, rendendolo inquietante e allontanando ulteriormente da lui ogni possibile relazione sociale. Ma un giorno Arthur non ce la fa più e reagisce violentemente, pistola alla mano. Mentre la polizia di Gotham City dà la caccia al clown killer, la popolazione lo elegge a eroe metropolitano, simbolo della rivolta degli oppressi contro l''arroganza dei ricchi.","es":"Arthur Fleck es un hombre ignorado por la sociedad, cuya motivación en la vida es hacer reír. Pero una serie de trágicos acontecimientos le llevarán a ver el mundo de otra forma. Película basada en Joker, el popular personaje de DC Comics y archivillano de Batman, pero que en este film toma un cariz más realista y oscuro."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg","de":"https://image.tmdb.org/t/p/w500/t3ZtGpIqoQgMY5hMHSLJSD8aguU.jpg","fr":"https://image.tmdb.org/t/p/w500/tWjJ3ILjsbTwKgXxEv48QAbYZ19.jpg","it":"https://image.tmdb.org/t/p/w500/y1AthYH1r2j4N4cYn2HdrEGgrnJ.jpg","es":"https://image.tmdb.org/t/p/w500/v0eQLbzT6sWelfApuYsEkYpzufl.jpg"}'::jsonb WHERE id = 293;
UPDATE public.films SET tmdb_id = 496243, titoli_i18n = '{"de":"Parasite","it":"Parasite","fr":"Parasite","en":"Parasite","es":"Parásitos"}'::jsonb, trame_i18n = '{"de":"Familie Kim ist ganz unten angekommen: Vater, Mutter, Sohn und Tochter hausen in einem grünlich-schummrigen Keller und sind sich für keinen Aushilfsjob zu schade. Erst als der Jüngste eine Anstellung als Nachhilfelehrer in der todschicken Villa der Familie Park antritt, steigen die Kims ein ins Karussell der Klassenkämpfe. Mit findigen Tricksereien, bemerkenswertem Talent und großem Mannschaftsgeist gelingt es ihnen, die bisherigen Bediensteten der Familie Park nach und nach loszuwerden. Bald schon sind die Kims unverzichtbar für ihre neuen Herrschaften. Doch dann löst ein unerwarteter Zwischenfall eine Kette von Ereignissen aus, die so unvorhersehbar wie unfassbar sind.","it":"Tutta la famiglia di Ki-taek è senza lavoro. Ki-taek è particolarmente interessata allo stile di vita della ricchissima famiglia Park. Un giorno, suo figlio riesce a farsi assumere dai Park e le due famiglie si ritrovano così intrecciate da una serie di eventi incontrollabili.","fr":"Toute la famille de Ki-taek est au chômage. Elle s’intéresse particulièrement au train de vie de la richissime famille Park. Mais un incident se produit et les deux familles se retrouvent mêlées, sans le savoir, à une bien étrange histoire…","en":"All unemployed, Ki-taek''s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.","es":"Tanto Gi Taek (Song Kang-ho) como su familia están sin trabajo. Cuando su hijo mayor, Gi Woo (Choi Woo-sik), empieza a dar clases particulares en casa de Park (Lee Seon-gyun), las dos familias, que tienen mucho en común pese a pertenecer a dos mundos totalmente distintos, comienzan una interrelación de resultados imprevisibles."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/hoqe3leVhHBgboB6G1bv1kB8K4p.jpg","it":"https://image.tmdb.org/t/p/w500/mMM8kcfspicib7AmPTvf97Rarwn.jpg","fr":"https://image.tmdb.org/t/p/w500/7hLSzZX2jROmEXz2aEoh6JKUFy2.jpg","en":"https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg","es":"https://image.tmdb.org/t/p/w500/4N55tgxDW0RRATyrZHbx0q9HUKv.jpg"}'::jsonb WHERE id = 294;
UPDATE public.films SET tmdb_id = 354912, titoli_i18n = '{"en":"Coco","it":"Coco","de":"Coco - Lebendiger als das Leben!","es":"Coco","fr":"Coco"}'::jsonb, trame_i18n = '{"en":"Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.","it":"Nonostante il divieto di musica che dura da generazioni nella sua famiglia, Miguel sogna di diventare un musicista affermato come il suo idolo, Ernesto de la Cruz. Disperato di dimostrare il suo talento, Miguel si ritrova nella splendida e colorata Terra dei Morti, seguendo una misteriosa catena di eventi. Lungo il cammino incontra il fascinante imbroglione Hector e insieme partono per un viaggio straordinario per svelare la vera storia della famiglia di Miguel.","de":"Miguel ist zwölf Jahre alt und ein großer Fan von Musik – aber leider hasst seine Schusterfamilie alles, was mit Tönen und Instrumenten zu tun hat. Miguels Ururgroßvater verließ damals seine Frau und Tochter, um Musiker zu werden, seitdem fühlen sich die Riveras durch Musik verflucht. Doch Familie hin oder her – Miguel will seinem Idol, dem Sänger Ernesto de la Cruz, trotzdem nacheifern. Aus Versehen kommt er dabei ins Reich der Toten und betritt dadurch einen wunderschönen Ort, an dem er die Seelen seiner toten Verwandten trifft. Miguels Ururgroßmutter Imelda ist darunter, und das nette Schwindler-Skelett Hector. Zusammen suchen Skelett und Junge im Totenreich nach de la Cruz, wobei allerdings die Zeit drängt: Zu lange darf Miguel nicht in der Unterwelt bleiben…","es":"Un joven aspirante a músico llamado Miguel se embarca en un viaje extraordinario a la mágica tierra de sus ancestros. Allí, el encantador embaucador Héctor se convierte en su inesperado amigo y le ayuda a descubrir los misterios detrás de las historias y tradiciones de su familia.","fr":"Depuis déjà plusieurs générations, la musique est bannie dans la famille de Miguel. Un vrai déchirement pour le jeune garçon dont le rêve ultime est de devenir un musicien aussi accompli que son idole, Ernesto de la Cruz. Bien décidé à prouver son talent, Miguel, par un étrange concours de circonstances, se retrouve propulsé dans un monde étonnant et coloré lié aux célébrations des ancêtres. Là, il se lie d’amitié avec Hector, un gentil garçon mais un peu filou sur les bords. Ensemble, ils vont accomplir un voyage extraordinaire qui leur révèlera la véritable histoire qui se cache derrière celle de la famille de Miguel…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg","it":"https://image.tmdb.org/t/p/w500/l5qUox5uroubMi8sihD9RGPbcwO.jpg","de":"https://image.tmdb.org/t/p/w500/x7YxGQGItXaLzl5eQNqGo0837fs.jpg","es":"https://image.tmdb.org/t/p/w500/vwsFGblLYxWBNjg9pdWN1Mm5YfW.jpg","fr":"https://image.tmdb.org/t/p/w500/sZqcEV3KhDITHlUBmyj1a3RRvT9.jpg"}'::jsonb WHERE id = 295;
UPDATE public.films SET tmdb_id = 290250, titoli_i18n = '{"it":"The Nice Guys","de":"The Nice Guys","en":"The Nice Guys","fr":"The Nice Guys","es":"Dos buenos tipos"}'::jsonb, trame_i18n = '{"it":"Nella Los Angeles degli anni ‘70, libertina, stravagante e decisamente trendy, un investigatore privato, Holland March (Ryan Gosling), e un detective senza scrupoli, Jackson Healy (Russell Crowe), si alleano per risolvere il caso di una ragazza scomparsa e la morte di una porno star che apparentemente non sembrerebbero correlate: scopriranno che un semplice omicidio nasconde il caso del secolo!","de":"Holland March, ein abgehalfterter Privatdetektiv, und Jackson Healy, der als Mann fürs Grobe angeheuert wird, haben nicht viel gemeinsam. Doch dann werden beide in den Fall der vermissten Amelia verstrickt. Widerwillig zur Zusammenarbeit gezwungen, streifen sie gemeinsam mit Marchs pubertierender Tochter Holly durch Los Angeles, um verworrenen Hinweisen auf den Grund zu gehen. Bis Amelias Spur sie zu einer Multi-Milliarden-Dollar-Verschwörung führt, die bis in die höchsten Kreise reicht und sie zum Ziel skrupelloser Profikiller macht...","en":"A private eye investigates the apparent suicide of a fading porn star in 1970s Los Angeles and uncovers a conspiracy.","fr":"Los Angeles. Années 70. Deux détectives privés enquêtent sur le prétendu suicide d’une starlette. Malgré des méthodes pour le moins « originales », leurs investigations vont mettre à jour une conspiration impliquant des personnalités très haut placées…","es":"Ambientada en Los Ángeles durante los años 70. El detective Holland March y el matón a sueldo Jackson Healy se ven obligados a colaborar para resolver varios casos: la desaparición de una joven, la muerte de una estrella porno y una conspiración criminal que llega hasta las altas esferas."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/clq4So9spa9cXk3MZy2iMdqkxP2.jpg","de":"https://image.tmdb.org/t/p/w500/n3CP3VtCoFuB7Wnh8Zyhx8erlnZ.jpg","en":"https://image.tmdb.org/t/p/w500/clq4So9spa9cXk3MZy2iMdqkxP2.jpg","fr":"https://image.tmdb.org/t/p/w500/p94BXHeJQagD3M8p4LuAB87RMQv.jpg","es":"https://image.tmdb.org/t/p/w500/kgMpKQMKyS7oYmPffKyyOv0VqyT.jpg"}'::jsonb WHERE id = 296;
UPDATE public.films SET tmdb_id = 395834, titoli_i18n = '{"en":"Wind River","it":"I segreti di Wind River","es":"Wind River","fr":"Wind River","de":"Wind River"}'::jsonb, trame_i18n = '{"en":"An FBI agent teams with the town''s veteran game tracker to investigate a murder that occurred on a Native American reservation.","it":"Cory Lambert, esperto inseguitore e cacciatore, scopre il corpo congelato di una ragazza adolescente. Fa allora squadra con Jane Banner, nuova agente dell''Fbi, per capire cosa sia accaduto alla giovane e chi sia il responsabile di un così macabro crimine. Man mano che l''indagine si approfondisce, la vita dei due investigatori è sempre più a rischio.","es":"Una joven agente del FBI se alía con un veterano rastreador local para investigar el asesinato de una joven ocurrido en una reserva de nativos americanos...","fr":"Cory Lambert est pisteur dans la réserve indienne de Wind River, perdue dans l’immensité sauvage du Wyoming. Lorsqu’il découvre le corps d’une femme en pleine nature, le FBI envoie une jeune recrue élucider ce meurtre. Fortement lié à la communauté amérindienne, il va l’aider à mener l’enquête dans ce milieu hostile, ravagé par la violence et l’isolement, où la loi des hommes s’estompe face à celle impitoyable de la nature…","de":"Cory Lambert arbeitet für den United States Fish and Wildlife Service und macht vor allem Jagd auf Kojoten und andere Raubtiere im Indianer-Reservat Wind River. Den kürzlichen Tod seiner Teenager-Tochter hat er noch nicht überwunden, da stolpert er in der Wildnis über die Leiche einer vergewaltigten und erfrorenen Jugendlichen. Um den Täter zu fassen, wird die noch sehr junge FBI-Agentin Jane Banner auf den Fall angesetzt. Weil sie sich in dem rauen Gelände und mit den schwierigen Wetterverhältnissen vor Ort allerdings nicht auskennt, bittet sie Cory um Hilfe bei ihren Ermittlungen und gemeinsam brechen sie auf ins Ungewisse."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/pySivdR845Hom4u4T2WNkJxe6Ad.jpg","it":"https://image.tmdb.org/t/p/w500/5OI9QQ24lrrS1IGB6RVuPL5GcZl.jpg","es":"https://image.tmdb.org/t/p/w500/8YQzSkPbJB5PJMTvTccDNo3z9K7.jpg","fr":"https://image.tmdb.org/t/p/w500/yp7ogTlvEvgUIvNXdbfwH68S3i4.jpg","de":"https://image.tmdb.org/t/p/w500/itiigTVSRWuRN5r72SN5vZNTxTm.jpg"}'::jsonb WHERE id = 297;
UPDATE public.films SET tmdb_id = 281957, titoli_i18n = '{"it":"Revenant - Redivivo","es":"El renacido","en":"The Revenant","fr":"The Revenant","de":"The Revenant - Der Rückkehrer"}'::jsonb, trame_i18n = '{"it":"Sono gli anni Venti del diciannovesimo secolo. Soldati, esploratori, cacciatori di pelli, mercenari solcano i territori ancora sconosciuti d''America per trarne profitto. Glass è l''uomo che meglio di tutti i suoi compagni di spedizione conosce la terra impervia in cui si sono inoltrati. Il suo compito è riportare la compagnia al forte e tutto ciò che lo preoccupa è proteggere suo figlio, un ragazzo indiano. Lo scontro con un grizzly lo lascia in condizioni prossime alla fine. Il più arrogante della compagnia, Fitzgerald, si offre di restare per dargli sepoltura, ma lo tradisce orribilmente. La volontà di vendicarsi rimetterà in piedi Glass e darà inizio ad un''odissea leggendaria.","es":"Durante una expedición en las tierras salvajes americanas, el legendario explorador Hugh Glass es brutalmente atacado por un oso y dado por muerto por los miembros de su propia partida de caza. En su cruzada por sobrevivir, Glass supera inimaginables tribulaciones, además de la traición de su confidente John Fitzgerald. Guiado por la pura determinación y el amor de su familia, Glass deberá superar un duro invierno mientras busca sin descanso un motivo para seguir adelante y encontrar la redención.","en":"In the 1820s, a frontiersman, Hugh Glass, sets out on a path of vengeance against those who left him for dead after a bear mauling.","fr":"Dans une Amérique profondément sauvage, le trappeur Hugh Glass est sévèrement blessé et laissé pour mort par un traître de son équipe, John Fitzgerald. Avec sa seule volonté pour unique arme, Glass doit affronter un environnement hostile, un hiver brutal et des tribus guerrières, dans une inexorable lutte pour sa survie, portée par un intense désir de vengeance.","de":"In den 1820ern zieht der legendäre Trapper Hugh Glass durch die Weiten der USA, wo er mit einer von Captain Andrew Henry angeführten Expedition dabei ist, den Missouri River zu erforschen. Am Fluss hat er einen unachtsamen Moment – den ein Grizzly ausnutzt, ihn übel zuzurichten. Glass schwebt in Lebensgefahr. Seine Begleiter, unter ihnen der raubeinige John Fitzgerald und der junge Jim Bridger, glauben nicht, dass er den Vorfall überleben wird und als sie dann Ureinwohner in der Nähe ihres Lagers erspähen, fackeln sie nicht lange. Sie nehmen dem Schwerverwundeten Gewehr, Messer und seine weitere Ausrüstung ab und überlassen ihn sich selbst. Aber überraschend überlebt Glass doch – und schwört allen Begleitern Rache, die ihn zurückgelassen haben. Auf der Suche nach ihnen schleppt sich der verletzte Abenteurer durch die eisige Bergwelt …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cw8HPomOzNql3l4xdaJJ8HGIZds.jpg","es":"https://image.tmdb.org/t/p/w500/k3Jh7J5GGMx1lmr7qmynRxOvOK5.jpg","en":"https://image.tmdb.org/t/p/w500/ji3ecJphATlVgWNY0B0RVXZizdf.jpg","fr":"https://image.tmdb.org/t/p/w500/AsDto68FNWNXD15Ov0yMXASJiSB.jpg","de":"https://image.tmdb.org/t/p/w500/fv9H7m73DKbwjowHSl1raTTwQ0d.jpg"}'::jsonb WHERE id = 298;
UPDATE public.films SET tmdb_id = 190859, titoli_i18n = '{"es":"El francotirador","fr":"American Sniper","en":"American Sniper","de":"American Sniper","it":"American Sniper"}'::jsonb, trame_i18n = '{"es":"El marine del grupo de operaciones especiales de la Marina de Estados Unidos Chris Kyle es enviado a Irak con una sola misión: proteger a sus compañeros de ejército. Su precisión milimétrica salva incontables vidas en el campo de batalla y, a medida que se extienden sus valientes hazañas, se gana el apodo de ''Leyenda''. Sin embargo, su reputación también crece detrás de las líneas enemigas, de manera que ponen precio a su cabeza y se convierte en objetivo prioritario de los insurgentes. Al mismo tiempo también se está enfrentando a otra batalla en casa: ser un buen marido y padre desde el otro lado del mundo.","fr":"Tireur d’élite des Navy SEAL, Chris Kyle est envoyé en Irak dans un seul but : protéger ses camarades. Sa précision chirurgicale sauve d’innombrables vies humaines sur le champ de bataille et, tandis que les récits de ses exploits se multiplient, il décroche le surnom de « La Légende ». Cependant, sa réputation se propage au-delà des lignes ennemies, si bien que sa tête est mise à prix et qu’il devient une cible privilégiée des insurgés. Malgré le danger, et l’angoisse dans laquelle vit sa famille, Chris participe à quatre batailles décisives parmi les plus terribles de la guerre en Irak, s’imposant ainsi comme l’incarnation vivante de la devise des SEAL : « Pas de quartier ! ». Mais en rentrant au pays, Chris prend conscience qu’il ne parvient pas à retrouver une vie normale.","en":"U.S. Navy SEAL Chris Kyle takes his sole mission—protect his comrades—to heart and becomes one of the most lethal snipers in American history. His pinpoint accuracy not only saves countless lives but also makes him a prime target of insurgents. Despite grave danger and his struggle to be a good husband and father to his family back in the States, Kyle serves four tours of duty in Iraq. However, when he finally returns home, he finds that he cannot leave the war behind.","de":"US-Navy-SEAL und Scharfschütze Chris Kyle wird mit nur einem einzigen Auftrag in den Irak geschickt, er soll seine Waffenbrüder beschützen. Seine punktgenauen Schüsse retten unzählige Leben auf dem Schlachtfeld. Als sich die Geschichten seiner mutigen Heldentaten und der unvergleichlichen Treffsicherheit verbreiten, bekommt er den Spitznamen „Legend“. Doch sein Ruf eilt ihm auch hinter die feindlichen Linien voraus und die Gegner setzen ein Kopfgeld auf ihn aus. Doch der Krieg ist nicht sein einziger Kampf: Der Scharfschütze versucht auch, ein guter Ehemann und Vater für seine Liebsten am anderen Ende der Welt zu sein. Trotz der lauernden Gefahr und seiner daheim wartenden Familie absolviert Kyle vier Einsätze im Irak – ganz nach dem Motto „lass niemanden zurück“. Aber als er dann wieder bei seiner Frau Taya Renae Kyle und seinen Kinder ist, erkennt er, dass er den Krieg nicht hinter sich lassen kann.","it":"Il cecchino Chris Kyle viene inviato in Iraq con una sola missione: proteggere i propri compagni. Grazie alla sua precisione millimetrica e alla sue gesta eroiche salverà innumerevoli vite guadagnandosi il soprannome di \"Legend\". Tuttavia, la sua reputazione cresce anche dietro le linee nemiche facendolo diventare uno degli obiettivi primari. Nonostante ciò, riuscirà a far ritorno a casa scoprendo che la guerra è qualcosa che difficilmente riuscirà a lasciarsi alle spalle."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ntso1nvAVIEdzjc4Tc9nB7MPSKu.jpg","fr":"https://image.tmdb.org/t/p/w500/9BEN7zRpoLBaBU3t97kPJkHUgnv.jpg","en":"https://image.tmdb.org/t/p/w500/i1U46OwMc6vlm7OoSUKfqUH615e.jpg","de":"https://image.tmdb.org/t/p/w500/vvujeQGFdTqVo63VXYTVsHuNGCl.jpg","it":"https://image.tmdb.org/t/p/w500/AdYOjcPT5PHyDsyxBgjCLtIepQR.jpg"}'::jsonb WHERE id = 299;
UPDATE public.films SET tmdb_id = 137113, titoli_i18n = '{"en":"Edge of Tomorrow","it":"Edge of Tomorrow - Senza domani","fr":"Edge of Tomorrow","de":"Edge of Tomorrow","es":"Al filo del mañana"}'::jsonb, trame_i18n = '{"en":"Major Bill Cage is an officer who has never seen a day of combat when he is unceremoniously demoted and dropped into combat. Cage is killed within minutes, managing to take an alpha alien down with him. He awakens back at the beginning of the same day and is forced to fight and die again... and again - as physical contact with the alien has thrown him into a time loop.","it":"La storia di “Edge of Tomorrow” si svolge in un futuro prossimo in cui una razza aliena ha colpito la Terra con un implacabile assalto che nessuno esercito al mondo riesce a respingere. Il tenente William Cage è un ufficiale che non ha mai partecipato neppure a un giorno di combattimento quando viene inviato senza tanti complimenti a compiere una missione suicida. Ucciso in pochi minuti, incredibilmente Cage si risveglia ed è costretto a combattere e a morire ancora e ancora, in un continuo loop temporale. Ma a ogni scontro Cage diventa sempre più abile nell’affrontare il nemico, insieme alla combattente delle Forze Speciali Rita Vrataski. Mentre Cage e Rita continuano la lotta contro gli alieni, la ripetizione di ogni battaglia li fa avvicinare sempre più alla soluzione per annientare il nemico.","fr":"Dans un futur proche, des hordes d’extraterrestres ont livré une bataille acharnée contre la Terre et semblent désormais invincibles : aucune armée au monde n’a réussi à les vaincre. Le commandant William Cage, qui n’a jamais combattu de sa vie, est envoyé, sans la moindre explication, dans ce qui ressemble à une mission‐suicide. Il meurt en l’espace de quelques minutes et se retrouve projeté dans une boucle temporelle, condamné à revivre le même combat et à mourir de nouveau indéfiniment…","de":"In naher Zukunft beginnt eine insektenartige Alienrasse – die sogenannten Mimics, mit einer Invasion der Erde. Mit ihrer überlegenen Technologie zerstören die Mimics unerbittlich Städte und ganze Länder, das menschliche Militär ist so gut wie machtlos. Doch noch ist nicht alle Hoffnung verloren, denn die militärischen Kräfte der ganzen Welt haben sich verbündet, um in einer letzten Offensive gegen das übermächtige Alienheer in die Schlacht zu ziehen. In diesem gigantischen Selbstmordkommando findet sich auch der degradierte Lt. Col. Bill Cage wieder. Er stirbt während der Schlacht, aber unglaublicherweise erwacht er daraufhin wieder am Morgen desselben Tages.","es":"En un futuro no muy lejano, invade la Tierra una raza de extraterrestres invencibles. Al comandante William Cage, un oficial que nunca ha entrado en combate, le encargan una misión casi suicida y resulta muerto. Entra entonces en un bucle temporal, en el que se ve obligado a luchar y morir una y otra vez. Pero las múltiples batallas que libra lo hacen cada vez más hábil y eficaz en su lucha contra los alienígenas. Su compañera de combate es Rita Vrataski, una guerrera de las Fuerzas Especiales. Adaptación del manga de Hiroshi Sakurazaka."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg","it":"https://image.tmdb.org/t/p/w500/AbzpU4ookiyWFmiq1bTZwjNl7Y1.jpg","fr":"https://image.tmdb.org/t/p/w500/mZgaULvOfCMc2MVKm0DzDLvi5ZU.jpg","de":"https://image.tmdb.org/t/p/w500/1ajE3sEyuEvfuqTTwK4XLKO8ROe.jpg","es":"https://image.tmdb.org/t/p/w500/vNjwi0STOwzmwE9laZSMYYh2JPE.jpg"}'::jsonb WHERE id = 300;
UPDATE public.films SET tmdb_id = 152747, titoli_i18n = '{"it":"All is lost - Tutto è perduto","fr":"All Is Lost","de":"All Is Lost","es":"Cuando todo está perdido","en":"All Is Lost"}'::jsonb, trame_i18n = '{"it":"Perso in mezzo all’Oceano Indiano, il viaggiatore solitario senza identità (Redford) si accorge che il suo yacht di 14 metri inizia ad imbarcare acqua dopo aver urtato contro un container che galleggiava in alto mare. Con il navigatore e la radio fuori uso, l’uomo si ritrova nel mezzo di una violenta tempesta. Nonostante la riparazione dei danni allo scafo e la sua intuizione da esperto marinaio unita ad una forza che smentisce la sua età, l’uomo riesce a malapena a sopravvivere alla tempesta. Avendo a disposizione un sestante ed alcune carte nautiche, per tracciare una rotta verso la salvezza, è costretto ad affidarsi unicamente alle correnti oceaniche nella speranza di incrociare delle barche di passaggio. Sotto un sole battente, accerchiato dagli squali e con le riserve alimentari che iniziavano a scarseggiare, l’ intraprendente marinaio si è trovato molto spesso faccia a faccia con la morte.","fr":"Au cours d''un voyage en solitaire à travers l''Océan Indien, un homme découvre à son réveil que la coque de son voilier de 12 mètres a été percée lors d''une collision avec un container flottant à la dérive. Privé de sa radio et de son matériel de navigation, l''homme se laisse prendre dans une violente tempête. Malgré ses réparations, son génie marin et une force physique défiant les années, il y survit de justesse. Avec un simple sextant et quelques cartes marines pour établir sa position, il doit s''en remettre aux courants pour espérer se rapprocher d''une voie de navigation et héler un navire de passage. Mais le soleil implacable, la menace des requins et l''épuisement de ses maigres réserves forcent ce marin forcené à regarder la mort en face.","de":"Mitten auf dem indischen Ozean wird ein Mann jäh aus dem Schlaf gerissen. Seine zwölf Meter lange Segelyacht hat einen im offenen Meer treibenden Schiffscontainer gerammt. Sein Navigations-Equipment und sein Funkgerät versagen in der Folge den Dienst und er treibt mitten in einen gewaltigen Sturm hinein. In letzter Minute gelingt es dem Mann, das Leck in seinem Boot notdürftig zu flicken. Er überlebt den Sturm dank seiner seemännischen Intuition und Erfahrung mit knapper Not. Praktisch manövrierunfähig treibt der Mann auf offener See. Seine letzte Hoffnung ist es, von der Strömung in eine der großen Schifffahrtsstrecken getrieben zu werden. Unter der unerbittlich sengenden Sonne, sieht sich der sonst so selbstbewusste und erfahrene Segler mit seiner eigenen Sterblichkeit konfrontiert und kämpft einen verzweifelten Kampf ums Überleben.","es":"En el transcurso de un viaje en solitario a través del Océano Índico, un hombre descubre al despertar que el casco de su velero de 12 metros se ha agrietado tras una colisión con un contenedor que flotaba a la deriva. A pesar de las reparaciones, su intuición de marinero y una fuerza física que desafía su edad, a duras penas logra sobrevivir a la tormenta. Pero el sol implacable, la amenaza de los tiburones y el agotamiento de sus escasas reservas obligan a este marinero sin rumbo a mirar a la muerte a los ojos.","en":"During a solo voyage in the Indian Ocean, a veteran mariner awakes to find his vessel taking on water after a collision with a stray shipping container. With his radio and navigation equipment disabled, he sails unknowingly into a violent storm and barely escapes with his life. With any luck, the ocean currents may carry him into a shipping lane -- but, with supplies dwindling and the sharks circling, the sailor is forced to face his own mortality."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/phZLbxYVfE98S0d1G3HdUCc7fqc.jpg","fr":"https://image.tmdb.org/t/p/w500/7yPNj5Xdj1Vl3Edyl3mzWYZMzgE.jpg","de":"https://image.tmdb.org/t/p/w500/9tnNyCdASD4zbKyxVKfjtdNeQfU.jpg","es":"https://image.tmdb.org/t/p/w500/f6sWgXefZXMm0fv37wgsKi4Rx4q.jpg","en":"https://image.tmdb.org/t/p/w500/9cVA4oX2xHgiglv6hemxwAaofsq.jpg"}'::jsonb WHERE id = 301;
UPDATE public.films SET tmdb_id = 68718, titoli_i18n = '{"es":"Django desencadenado","en":"Django Unchained","fr":"Django Unchained","it":"Django Unchained","de":"Django Unchained"}'::jsonb, trame_i18n = '{"es":"Dos años antes de estallar la Guerra Civil (1861-1865), Schultz, un cazarrecompensas alemán que le sigue la pista a unos asesinos, le promete al esclavo Django dejarlo en libertad si le ayuda a atraparlos. Terminado con éxito el trabajo, Django prefiere seguir al lado del alemán y ayudarle a capturar a los delincuentes más buscados del Sur. Se convierte así en un experto cazador de recompensas, pero su único objetivo es rescatar a su esposa Broomhilda, a la que perdió por culpa del tráfico de esclavos. La búsqueda llevará a Django y a Schultz hasta Calvin Candie, el malvado propietario de la plantación \"Candyland\". La presencia de ambos en los alrededores de la propiedad, despierta las sospechas de Stephen, el esclavo de confianza de Candie.","en":"With the help of a German bounty hunter, a freed slave sets out to rescue his wife from a brutal Mississippi plantation owner.","fr":"Dans le sud des États‐Unis, deux ans avant la guerre de Sécession, le Dr King Schultz, un chasseur de primes allemand, fait l’acquisition de Django, un esclave qui peut l’aider à traquer les frères Brittle, les meurtriers qu’il recherche. Schultz promet à Django de lui rendre sa liberté lorsqu’il aura capturé les Brittle – morts ou vifs. Alors que les deux hommes pistent les dangereux criminels, Django n’oublie pas que son seul but est de retrouver Broomhilda, sa femme, dont il fut séparé à cause du commerce des esclaves… Lorsque Django et Schultz arrivent dans l’immense plantation du puissant Calvin Candie, ils éveillent les soupçons de Stephen, un esclave qui sert Candie et a toute sa confiance. Le moindre de leurs mouvements est désormais épié par une dangereuse organisation de plus en plus proche… Si Django et Schultz veulent espérer s’enfuir avec Broomhilda, ils vont devoir choisir entre l’indépendance et la solidarité, entre le sacrifice et la survie…","it":"Stati Uniti del Sud, alla vigilia della guerra civile. Il cacciatore di taglie di origine tedesca dottor King Schultz, su un carretto da dentista, è alla ricerca dei fratelli Brittle, per consegnarli alle autorità piuttosto morti che vivi e incassare la ricompensa. Per scovarli, libera dalle catene lo schiavo Django, promettendogli la libertà a missione completata. Tra i due uomini nasce così un sodalizio umano e professionale che li conduce attraverso l''America delle piantagioni e degli orrori razzisti alla ricerca dei criminali in fuga e della moglie di Django, Broomhilda, venduta come schiava a qualche possidente negriero.","de":"Als das Sklavenpaar Django und seine Frau Broomhilda bei einer Auktion getrennt werden, hat Django nur noch ein Ziel vor Augen: seine Frau wiederzufinden. Die Gelegenheit ergibt sich für den in Fesseln Geschlagenen schneller als erwartet, als er vom früheren Zahnarzt und jetzigen Kopfgeldjäger Dr. Schultz befreit wird, damit er ihm bei der Identifikation steckbrieflich gesuchter Verbrecher behilflich sei. Zum Dank will Dr. Schultz ihn zum Kopfgeldjäger ausbilden und ihm helfen, seine Frau ausfindig zu machen. Schließlich führt Django und Dr. Schultz die Spur nach Candyland, wo Broomhilda in den Besitz des charismatischen und überaus gefährlichen Calvin Candie übergegangen ist. Sie erschleichen sich erfolgreich das Vertrauen von Candie. Doch der Haussklave Stephen durchschaut ihr Spiel…"}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/fIxAE6BKfAzhPRYm7DdldBaYu5T.jpg","en":"https://image.tmdb.org/t/p/w500/7oWY8VDWW7thTzWh3OKYRkWUlD5.jpg","fr":"https://image.tmdb.org/t/p/w500/vRXUnWrXUgXRoX0BaEcuNMfyeQt.jpg","it":"https://image.tmdb.org/t/p/w500/igYptikalrjsMueMx6rz15lE4Ts.jpg","de":"https://image.tmdb.org/t/p/w500/yK0qrQhi3BbOXvTNOBWHgpcbckZ.jpg"}'::jsonb WHERE id = 302;
UPDATE public.films SET tmdb_id = 87827, titoli_i18n = '{"it":"Vita di Pi","en":"Life of Pi","es":"La vida de Pi","de":"Life of Pi - Schiffbruch mit Tiger","fr":"L''Odyssée de Pi"}'::jsonb, trame_i18n = '{"it":"Il giovane Piscine Molitor Patel, detto Pi, è cresciuto con la famiglia a contatto con lo zoo paterno, mescolando fin dall''infanzia sogno e realtà. Quando il padre ha esigenze di denaro e sceglie di trasferirsi in Canada per vendere lo zoo, Pi ancora non può intuire cosa lo attenderà nelle vastità oceaniche. Di fronte a una tempesta terrificante, la nave affonda, lasciando in breve tempo Pi con un''unica compagna di viaggio: la tigre Richard Parker, l''animale più temuto dello zoo paterno. Pi potrà solo fare affidamento alla propria intelligenza per poter sopravvivere e convivere con la tigre.","en":"The story of an Indian boy named Pi, a zookeeper''s son who finds himself in the company of a hyena, zebra, orangutan, and a Bengal tiger after a shipwreck sets them adrift in the Pacific Ocean.","es":"Pi Patel es un muchacho cuyo padre es el dueño del zoológico de la ciudad de la India en la que viven. Su familia decide marcharse a Canadá, pero una tormenta hace naufragar el barco en el que viajan. Pi consigue salvarse gracias a una barcaza en la que también hay otro \"pasajero\", un tigre de Bengala al que el joven intentará domar para poder sobrevivir.","de":"Wie man 227 Tage auf hoher See mit einem Bengalischen Tiger unbeschadet überstehen kann, das zeigt Schiffbruch mit Tiger. Piscine Molitor Patel, kurz Pi, ist ein junger Inder, der mit seiner Familie in Pondicherry lebt, wo sein Vater einen Zoo besitzt. Als sie aus politischen Gründen nach Kanada auswandern müssen, wird der Zoo verkauft und mit ihm ein Großteil der Tiere. Den Rest nimmt die Familie mit an Bord eines Frachters, der sie in die neue Heimat bringen soll. Doch auf der Überfahrt kommt es zu einer Havarie und nur Pi kann sich als einziger Überlebender in ein Beiboot retten. Mit vier nicht-menschlichen Ausnahmen: Weitere „Passagiere“ im Rettungsboot sind eine Hyäne, ein am Bein verletztes Zebra, ein Orang-Utan und ein ausgewachsener Tiger namens Richard Parker. Wie und unter welchen Opfern Pi diese entbehrungsreiche Odyssee überlebt, davon berichtet der mittlerweile erwachsene Pi.","fr":"Après une enfance passée à Pondichéry en Inde, Pi Patel, 17 ans, embarque avec sa famille pour le Canada où l’attend une nouvelle vie. Mais son destin est bouleversé par le naufrage spectaculaire du cargo en pleine mer. Il se retrouve seul survivant à bord d''un canot de sauvetage. Seul, ou presque… Richard Parker, splendide et féroce tigre du Bengale est aussi du voyage. L’instinct de survie des deux naufragés leur fera vivre une odyssée hors du commun au cours de laquelle Pi devra développer son ingéniosité et faire preuve d’un courage insoupçonné pour survivre à cette aventure incroyable."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hQc6NHCshzZmi7cR6ggQMKlf17i.jpg","en":"https://image.tmdb.org/t/p/w500/iLgRu4hhSr6V1uManX6ukDriiSc.jpg","es":"https://image.tmdb.org/t/p/w500/9jpQ6BRScQmTULj10mUkjEKelhX.jpg","de":"https://image.tmdb.org/t/p/w500/eeLve6g5O99vIPXhhAxY6QE2v6r.jpg","fr":"https://image.tmdb.org/t/p/w500/bDfZiMQxm6YQxShym38sPWVm2yL.jpg"}'::jsonb WHERE id = 303;
UPDATE public.films SET tmdb_id = 59436, titoli_i18n = '{"it":"Midnight in Paris","de":"Midnight in Paris","fr":"Minuit à Paris","en":"Midnight in Paris","es":"Midnight in Paris"}'::jsonb, trame_i18n = '{"it":"Una storia romantica ambientata a Parigi, nella quale s''intrecciano le vicende di una famiglia, in Francia per affari, e di due giovani fidanzati prossimi alle nozze; tutti alle prese con esperienze che cambieranno per sempre le loro vite. Il film è anche la storia del grande amore di un giovane uomo per una città, Parigi, e dell''illusione di tutti coloro che pensano che se avessero avuto una vita diversa sarebbero stati molto più felici.","de":"Ein Wunschtraum geht für den Amerikaner Gil in Erfüllung, als er mit seiner Verlobten Inez, ein Mädchen aus wohlhabendem Hause, seinen Urlaub in Paris verbringen kann. Seit seiner Jugend schwärmt Gil von der dortigen Künstlerszene der Zwanzigerjahre. Wenn er nur damals hätte leben können! Hemingway, Fitzgerald, Gertrude Stein – das sind die Idole des erfolgreichen Hollywood-Drehbuchautoren, der sich sehnlichst wünscht, als ernst zu nehmender Schriftsteller zu reüssieren. Inez hat kein Verständnis für seine Schwärmerei. Eines Abends bricht Gil alleine auf und verirrt sich bei seinem Streifzug durch die Straßen der Stadt der Liebe. Punkt Mitternacht geschieht etwas Wundersames: Gil wird von einer Limousine aufgelesen, die ihn geradewegs in die Roaring Twenties transportiert, zu all den legendären Künstlern, die er immer schon bewundert hat! Mit einem Mal ist nichts mehr so, wie es vorher war …","fr":"Un jeune couple d’américains dont le mariage est prévu à l’automne se rend pour quelques jours à Paris. La magie de la capitale ne tarde pas à opérer, tout particulièrement sur le jeune homme amoureux de la Ville-lumière et qui aspire à une autre vie que la sienne.","en":"While on a trip to Paris with his fiancée''s family, a nostalgic screenwriter finds himself mysteriously going back to the 1920s every day at midnight.","es":"Un escritor norteamericano algo bohemio llega con su prometida Inez y los padres de ésta a París. Mientras vaga por las calles soñando con los felices años 20, cae bajo una especie de hechizo que hace que, a medianoche, en algún lugar del barrio Latino, se vea transportado a otro universo donde va a conocer a personajes que jamás imaginaría iba a conocer..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hfdsTXO6wIJ9uywIgnqzNYDWYQK.jpg","de":"https://image.tmdb.org/t/p/w500/ocOl71FjnYi0CNEzaLeY6ByKTRR.jpg","fr":"https://image.tmdb.org/t/p/w500/d8OE6ZHyisBXLs2cGzP1gqG52Cf.jpg","en":"https://image.tmdb.org/t/p/w500/4wBG5kbfagTQclETblPRRGihk0I.jpg","es":"https://image.tmdb.org/t/p/w500/paDvLnSZyrDoUVRrUZPjB19zJQZ.jpg"}'::jsonb WHERE id = 304;
UPDATE public.films SET tmdb_id = 44214, titoli_i18n = '{"en":"Black Swan","es":"Cisne negro","it":"Il cigno nero","fr":"Black Swan","de":"Black Swan"}'::jsonb, trame_i18n = '{"en":"A committed dancer struggles to maintain her sanity after winning the lead role in a production of Tchaikovsky''s \"Swan Lake.\"","es":"Nina, una brillante bailarina que forma parte de una compañía de ballet de Nueva York, vive completamente absorbida por la danza. La presión de su controladora madre, la rivalidad con su compañera Lily y las exigencias del severo director se irán incrementando a medida que se acerca el día del estreno. Esta tensión provoca en Nina un agotamiento nervioso y una confusión mental que la incapacitan para distinguir entre realidad y ficción.","it":"Nina è una ballerina del New York City Ballet che sogna il \"ruolo\" e un amore che spezzi l''adolescenza mai finita. Incalzata dalla madre, si sottopone ad un allenamento sotto lo sguardo di Thomas Leroy. Coreografo appassionato e deciso a farne una stella, Leroy le assegna la parte della protagonista nella sua versione del \"Lago dei cigni\". Sul palcoscenico Nina sarà Odette. Eterea e piena di grazia Nina incarna alla perfezione il candore del cigno bianco e con difficoltà il suo doppio nero e tenebroso, che in una superba variazione ingannerà il suo principe e la voterà al suicidio. La ricerca del suo lato oscuro e della consapevolezza della propria sessualità la condurranno verso una tempesta emozionale e all''incontro con Lily, insidiosa rivale in nero. Dietro le quinte Nina si strugge e si predispone a ''doppiare'' il suo cigno bianco.","fr":"Rivalités dans la troupe du New York City Ballet. Nina est prête à tout pour obtenir le rôle principal du Lac des cygnes que dirige l’ambigu Thomas. Mais elle se trouve bientôt confrontée à la belle et sensuelle nouvelle recrue, Lily…","de":"Nina ist eine ehrgeizige und leidenschaftliche Ballett-Tänzerin, die ihr Leben ausnahmslos ihrer Arbeit an der New Yorker Ballet Company widmet. Dabei wird sie energisch von ihrer Mutter, selbst eine ehemalige Tänzerin, gefördert. Als die Rolle der Primaballerina für die Produktion des Klassikers Schwanensee neu besetzt werden soll, wird Nina von Regisseur Thomas Leroy favorisiert. Sie bekommt jedoch schnell Konkurrenz durch die jüngere Lily, die zwar technisch schwächer ist, aber eine Leichtigkeit besitzt, die sich nicht mit Übung erreichen lässt. Zwischen den beiden entsteht eine außergewöhnliche Beziehung, die zur Zerreißprobe für Nina wird. Immer intensiver lernt sie die düstere Seite ihres Selbst kennen, das ihr bedrohlicherweise immer ähnlicher wird."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/viWheBd44bouiLCHgNMvahLThqx.jpg","es":"https://image.tmdb.org/t/p/w500/dZucAEc4JNsO6z4fvvunXgLe3b8.jpg","it":"https://image.tmdb.org/t/p/w500/dywocnQY2FhEpDeV56Vl3yHw0oy.jpg","fr":"https://image.tmdb.org/t/p/w500/PgK9d0vegvPCx92b7c15sk4x8h.jpg","de":"https://image.tmdb.org/t/p/w500/f5yFgSs9wMCP9lNnRGUM1QI0tXs.jpg"}'::jsonb WHERE id = 305;
UPDATE public.films SET tmdb_id = 27205, titoli_i18n = '{"es":"Origen","fr":"Inception","de":"Inception","it":"Inception","en":"Inception"}'::jsonb, trame_i18n = '{"es":"Dom Cobb es un ladrón hábil, el mejor de todos, especializado en el peligroso arte de extracción: el robo de secretos valiosos desde las profundidades del subconsciente durante el estado de sueño cuando la mente está más vulnerable. Esta habilidad excepcional de Cobb le ha hecho un jugador codiciado en el traicionero nuevo mundo de espionaje corporativo, pero al mismo tiempo, le ha convertido en un fugitivo internacional y ha tenido que sacrificar todo que le importaba. Ahora a Cobb se le ofrece una oportunidad para redimirse. Con un último trabajo podría recuperar su vida anterior, pero solamente si logra lo imposible.","fr":"Dom Cobb est un voleur expérimenté, le meilleur dans l''art dangereux de l''extraction, voler les secrets les plus intimes enfouis au plus profond du subconscient durant une phase de rêve, lorsque l''esprit est le plus vulnérable. Les capacités de Cobb ont fait des envieux dans le monde tourmenté de l''espionnage industriel alors qu''il devient fugitif en perdant tout ce qu''il a un jour aimé. Une chance de se racheter lui est alors offerte. Une ultime mission grâce à laquelle il pourrait retrouver sa vie passée mais uniquement s''il parvient à accomplir l''impossible inception.","de":"Beim Versuch in das Unterbewusstsein des Industriellen Saito einzudringen, stoßen Cobb und seine Mitstreiter auf unerwartete Schwierigkeiten. Saito hatte Verteidigungsstrategien gegen den Gedankendiebstahl trainiert und baut nun einen Abwehrriegel auf, doch erst der Verrat eines Kollegen lässt den Versuch scheitern, dem Schlafenden Geheimnisse zu entlocken. Da seine Auftraggeber unbedingten Erfolg gefordert hatten, muss Cobb, der auf Grund einer drohenden Verurteilung nicht mehr in die USA zurück kann, fliehen, doch Saito kommt ihm zuvor. Allerdings nicht um ihn zu bestrafen, sondern um ihm einen Deal vorzuschlagen.","it":"Dom Cobb possiede una qualifica speciale: è in grado di inserirsi nei sogni altrui per prelevare i segreti nascosti nel più profondo del subconscio. Viene contattato da Saito, un potentissimo industriale di origine giapponese, il quale gli chiede di tentare l''operazione opposta. Non deve prelevare pensieri celati ma inserire un''idea che si radichi nella mente di una persona. Costui è Robert Fischer Jr. il quale, alla morte dell''anziano e dittatoriale genitore, dovrà convincersi che l''unica cosa che può fare è distruggere l''impero ereditato. Saito avrà allora campo libero. In cambio offrirà a Cobb la possibilità di rientrare negli Stati Uniti dove è ricercato per omicidio. Cobb accetta e si fa affiancare da un team di cui entra a far parte la giovane Ariane, architetto abilissimo nella costruzione di spazi virtuali.","en":"Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: \"inception\", the implantation of another person''s idea into a target''s subconscious."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/tXQvtRWfkUUnWJAn2tN3jERIUG.jpg","fr":"https://image.tmdb.org/t/p/w500/aej3LRUga5rhgkmRP6XMFw3ejbl.jpg","de":"https://image.tmdb.org/t/p/w500/t5WUY5ZSxwVIVExaMZmmIj88BKA.jpg","it":"https://image.tmdb.org/t/p/w500/5QHWgqaBxZI1eM5e3YhyKzY5o3z.jpg","en":"https://image.tmdb.org/t/p/w500/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg"}'::jsonb WHERE id = 306;
UPDATE public.films SET tmdb_id = 11324, titoli_i18n = '{"it":"Shutter Island","en":"Shutter Island","de":"Shutter Island","fr":"Shutter Island","es":"Shutter Island"}'::jsonb, trame_i18n = '{"it":"Nel 1954, i due agenti federali Teddy Daniels e Chuck Aule vengono inviati all''istituto mentale Ashecliffe di Shutter Island, al largo della costa est, per indagare sull''improvvisa scomparsa di Rachel Solando, una pericolosa infanticida. Il direttore dell''istituto, il dottor Cawley, e i vari infermieri sostengono che la madre assassina si sia come dileguata dalla sua stanza senza lasciare alcuna traccia, ma l''agente Daniels nutre fin dal principio dei forti sospetti sullla gestione dell''ospedale da parte del dottor Cawley e del suo medico assistente, il dottor Naehring. Un uragano costringe i due agenti a protrarre il soggiorno sull''isola, durante il quale le indagini proseguono e particolari sempre più inquietanti emergono, mentre Daniels continua ad avere delle visioni che riguardano la moglie defunta e le sue esperienze di guerra contro gli ufficiali nazisti.","en":"World War II soldier-turned-U.S. Marshal Teddy Daniels investigates the disappearance of a patient from a hospital for the criminally insane, but his efforts are compromised by troubling visions and a mysterious doctor.","de":"1954 soll der U.S. Marshall Teddy Daniels das Verschwinden eines Patienten aus dem Bostoner Shutter Island Ashecliffe Hospital aufklären. Er hat sich aus persönlichen Gründen um diesen Auftrag bemüht, aber schon bald muss er sich fragen, ob er nicht durch die Ärzte manipuliert wurde, deren Methoden von unethisch über illegal bis skrupellos gehen. Teddys scharfsinnige Ermittlungsmethoden führen rasch zu einer vielversprechenden Spur, aber das Hospital verweigert ihm Zugriff auf Informationen, die den Fall erhellen könnten. Als ein Hurrikan die Verbindung zum Festland unterbricht, \"entkommen\" weitere gefährliche Kriminelle in dem Chaos und die verwirrenden Hinweise mehren sich, so dass Teddy an allem zu zweifeln beginnt - seinem Gedächtnis, seinem Partner und sogar seinem eigenen Verstand.","fr":"En 1954, le marshal Teddy Daniels et son coéquipier Chuck Aule sont envoyés enquêter sur l’île de Shutter Island, dans un hôpital psychiatrique où sont internés de dangereux criminels. L’une des patientes, Rachel Solando, a inexplicablement disparu. Comment la meurtrière a‐t‐elle pu sortir d’une cellule fermée de l’extérieur ? Le seul indice retrouvé dans la pièce est une feuille de papier sur laquelle on peut lire une suite de chiffres et de lettres sans signification apparente. Œuvre cohérente d’une malade, ou cryptogramme ?","es":"Verano de 1954. Los agentes judiciales Teddy Daniels y Chuck Aule son destinados a una remota isla del puerto de Boston para investigar la desaparición de una peligrosa asesina recluida en el hospital psiquiátrico Ashecliffe, un centro penitenciario para criminales perturbados dirigido por el siniestro doctor John Cawley. Pronto descubrirán que el centro guarda muchos secretos, y que la isla esconde algo más peligroso que los pacientes."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kgPRqDDr5RFkIly6CJrBPHYs2qS.jpg","en":"https://image.tmdb.org/t/p/w500/nrmXQ0zcZUL8jFLrakWc90IR8z9.jpg","de":"https://image.tmdb.org/t/p/w500/mm07ImVjMcrBFhcepmy63toBfax.jpg","fr":"https://image.tmdb.org/t/p/w500/fQ0vGVTtxjCdAJnxwPZ88O3Wzrh.jpg","es":"https://image.tmdb.org/t/p/w500/56utveUWJwmG12YU7c2zKw6pbRZ.jpg"}'::jsonb WHERE id = 307;
UPDATE public.films SET tmdb_id = 19995, titoli_i18n = '{"it":"Avatar","en":"Avatar","fr":"Avatar","es":"Avatar","de":"Avatar - Aufbruch nach Pandora"}'::jsonb, trame_i18n = '{"it":"Jake Sully è un marine costretto su una sedia a rotelle che accetta di trasferirsi sul pianeta Pandora in sostituzione del fratello morto, la cui missione era quella di esplorare il pianeta. Essendo l''atmosfera del pianeta tossica per gli umani sono stati creati degli esseri simili ai nativi Na''vi che possono essere ''guidati'' dagli umani. Pandora è un enorme giacimento di un minerale prezioso per la Terra dove le fonti di energia sono azzerate. Gli indigeni Na''vi non hanno intenzione di essere colonizzati. Il compito iniziale dell''avatar di Jake sarà quello di conoscerne usi e costumi e di farsi accettare all''interno delle comunità indigene. Jake conosce così Neytiri, una guerriera Na''vi figlia del capo tribù. Da lei impara a divenire un guerriero molto diverso dal marine che è stato e se ne innamora ricambiato.","en":"In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.","fr":"Un marine paraplégique, envoyé sur la lune Pandora pour une mission unique, est tiraillé entre suivre ses ordres et protéger le monde qu''il considère dorénavant comme le sien.","es":"Año 2154. Jake Sully, un exmarine en silla de ruedas, es enviado al planeta Pandora, donde se ha creado el programa Avatar, gracias al cual los seres humanos pueden controlar de forma remota un cuerpo biológico con apariencia y genética de la especie nativa. Pronto se encontrará con la encrucijada entre seguir las órdenes de sus superiores o defender al mundo que le ha acogido y siente como suyo.","de":"Ex-Marine Jake Sully nimmt auf dem Planeten Pandora an einem Experiment unter der Leitung der Wissenschaftlerin Dr. Grace Augustine teil. Als er sich im genetisch manipulierten Körper der Ureinwohner in die schöne Neytiri verliebt, gerät er zwischen die Fronten eines skrupellosen Konzerns und dem naturverbundenen Volk der Na''vi. Jake muss sich entscheiden, auf welcher Seite er steht - in einem ungleichen Kampf, in dem es um das Schicksal einer einzigartigen Welt geht ..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cu6CTvQqVvaTUmWNGWydpf7EzmV.jpg","en":"https://image.tmdb.org/t/p/w500/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg","fr":"https://image.tmdb.org/t/p/w500/7N8L80OaG8EBTDdRBjGqT8PBzCM.jpg","es":"https://image.tmdb.org/t/p/w500/t5T3LPbLLgP2OP6kloM9p2PXpJL.jpg","de":"https://image.tmdb.org/t/p/w500/8VV4YUwOGxgolFZTo2SgNwsfznR.jpg"}'::jsonb WHERE id = 308;
UPDATE public.films SET tmdb_id = 83533, titoli_i18n = '{"it":"Avatar: Fuoco e cenere","en":"Avatar: Fire and Ash","es":"Avatar: Fuego y ceniza","de":"Avatar: Fire and Ash","fr":"Avatar : De feu et de cendres"}'::jsonb, trame_i18n = '{"it":"In seguito alla devastante guerra contro la RDA e alla perdita del loro figlio maggiore, Jake Sully e Neytiri affrontano una nuova minaccia su Pandora: il Popolo della Cenere, una tribù Na''vi violenta e assetata di potere guidata dagli spietati Varang. La famiglia di Jake deve lottare per la propria sopravvivenza e per il futuro di Pandora in un conflitto che li spinge ai loro limiti emotivi e fisici.","en":"In the wake of the devastating war against the RDA and the loss of their eldest son, Jake Sully and Neytiri face a new threat on Pandora: the Ash People, a violent and power-hungry Na''vi tribe led by the ruthless Varang. Jake''s family must fight for their survival and the future of Pandora in a conflict that pushes them to their emotional and physical limits.","es":"Jake Sully y Neytiri enfrentan una nueva amenaza en Pandora: los Ash People, una tribu Na''vi violenta y sedienta de poder, liderada por la implacable Varang. Tras la devastadora guerra contra la RDA y la pérdida de su hijo mayor, la familia de Jake deberá luchar por su supervivencia y el futuro de Pandora en un conflicto que llevará a los personajes a sus límites emocionales y físicos. Con nuevos y antiguos aliados, esta épica visual y emocional redefine el destino de un mundo al borde del abismo.","de":"Nach dem verheerenden Krieg gegen die RDA und dem Verlust ihres ältesten Sohnes sehen sich Jake Sully und Neytiri mit einer neuen Bedrohung auf Pandora konfrontiert: dem Aschvolk, einem gewalttätigen und machthungrigen Na''vi-Stamm unter der Führung des skrupellosen Varang. Jakes Familie muss in einem Konflikt, der sie an ihre emotionalen und physischen Grenzen bringt, um ihr Überleben und die Zukunft von Pandora kämpfen.","fr":"Après la mort de Neteyam, Jake et Neytiri affrontent leur chagrin tout en faisant face au Peuple des Cendres, une tribu Na’vi redoutable menée par la fougueuse Varang, alors que le conflit sur Pandora s’intensifie et qu’une nouvelle quête morale s’amorce."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kvivMhuEuzXuaj0UMjAAmrXVvWn.jpg","en":"https://image.tmdb.org/t/p/w500/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg","es":"https://image.tmdb.org/t/p/w500/4n1U0Mwn7djux6VKNYDRWPgS2x6.jpg","de":"https://image.tmdb.org/t/p/w500/nB8gjQdI6RPczGcJ5mzCgAdjdH8.jpg","fr":"https://image.tmdb.org/t/p/w500/kG3N8oQ10qiw2MsnSHFGJpQNyEy.jpg"}'::jsonb WHERE id = 309;
UPDATE public.films SET tmdb_id = 76600, titoli_i18n = '{"es":"Avatar: El sentido del agua","de":"Avatar: The Way of Water","it":"Avatar: La via dell''acqua","fr":"Avatar : La Voie de l''eau","en":"Avatar: The Way of Water"}'::jsonb, trame_i18n = '{"es":"Más de una década después de los acontecimientos de ''Avatar'', los Na''vi Jake Sully, Neytiri y sus hijos viven en paz en los bosques de Pandora hasta que regresan los hombres del cielo. Entonces comienzan los problemas que persiguen sin descanso a la familia Sully, que decide hacer un gran sacrificio para mantener a su pueblo a salvo y seguir ellos con vida.","de":"Mehr als zehn Jahre nach den Ereignissen des ersten Films haben Jake und Neytiri eine Familie gegründet. Ihre Kinder sind Neteyam, Lo’ak und Tuktirey, der adoptierte Menschenjunge Miles “Spider” Socorro und die adoptierte Na’vi-Teenagerin Kiri. Doch ihre Heimat ist weiterhin nicht sicher - das müssen sie feststellen, als die Resources Development Administration (RDA) unter Führung von General Ardmore mit noch mehr Militär und einem alten Bekannten nach Pandora zurückkehrt, um den Planeten zur neuen Heimat der Menschheit zu machen. Bald sehen sich Neytiri, Jake und ihre Familie gezwungen, ihr Zuhause zu verlassen und beim Na’vi-Stamm der Metkayina Zuflucht zu suchen, der an den Küsten und Meeren des Mondes Pandora lebt und von der schwangeren Ronal und ihrem Mann Tonowari angeführt wird.","it":"Jake vive felicemente la sua vita insieme a Neytiri ma Pandora nasconde ancora numerosi misteri. Quando una vecchia, familiare minaccia torna ad affacciarsi per terminare quel che era stato iniziato un tempo, Jake dovrà nuovamente collaborare con l''esercito dei Na''vi per proteggere il loro incredibile pianeta. In veste di patriarca si ritroverà a dover combattere una dura guerra contro gli umani. Jake e Neytiri saranno pertanto costretti a lasciare la loro casa ed esplorare varie regioni di Pandora...","fr":"Une dizaine d''années s''est écoulée depuis les précédents évènements survenus sur Pandora. Jake Sully et Neytiri sont devenus parents. Leur vie idyllique, proche de la nature, est menacée lorsque la « Ressources Développement Administration », dangereuse organisation non-gouvernementale, est de retour sur Pandora. Contraints de quitter leur habitat naturel, Jake et sa famille se rendent sur les récifs, où ils pensent trouver asile. Mais ils tombent sur un clan, les Metkayina, aux mœurs différentes des leurs.","en":"Set more than a decade after the events of the first film, learn the story of the Sully family (Jake, Neytiri, and their kids), the trouble that follows them, the lengths they go to keep each other safe, the battles they fight to stay alive, and the tragedies they endure."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ckeTumMS4G31UQ9NNkmtW2QhfMF.jpg","de":"https://image.tmdb.org/t/p/w500/dsBpvG4m0uOerBOuNITL9rvaD0I.jpg","it":"https://image.tmdb.org/t/p/w500/idul2fSUPkk0EHP92EzmES6KGW4.jpg","fr":"https://image.tmdb.org/t/p/w500/6WXn6RE1NAqcP2TfPcbVRawHUfE.jpg","en":"https://image.tmdb.org/t/p/w500/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg"}'::jsonb WHERE id = 310;
UPDATE public.films SET tmdb_id = 14160, titoli_i18n = '{"fr":"Là-haut","en":"Up","es":"Up","it":"Up","de":"Oben"}'::jsonb, trame_i18n = '{"fr":"À 78 ans, Carl n''envisage plus qu''une chose : finir tranquillement sa vie dans la petite maison où il a passé toute une existence paisible auprès de son épouse Ellie. Veuf désormais, il reste, en effet, attaché à son passé en refusant les propositions mirobolantes d''un promoteur pour racheter son bien. Quand des circonstances exceptionnelles le contraignent d''intégrer une maison de retraite, il prend une ultime fois les choses en mains et, transformant sa demeure en dirigeable, s''envole pour l''aventure, vers la partie du monde où sa femme et lui s''étaient promis un jour de s''installer. Il ne se doute pas alors qu''il a emporté avec lui un jeune passager clandestin, Russell et que le voyage sera loin d''être de tout repos…","en":"Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.","es":"Tras atar miles de globos a su casa, Carl Fredricksen, un vendedor de globos jubilado, se embarca en el mundo de los sueños de la infancia. Pero sin que Carl lo sepa, Russell, un explorador de 8 años, se encuentra en el lugar equivocado en el momento equivocado: el porche delantero de la casa. El dúo más improbable conoce a fantásticos amigos como Dug, un perro con un collar especial que le permite hablar, y Kevin, un pájaro de cuatro metros de altura que no vuela. Atrapados en la selva, Carl se da cuenta de que a veces las mayores aventuras de la vida son las que menos esperabas.","it":"Carl Fredricksen ha trascorso tutta la vita sognando di esplorare il mondo e di vivere appieno ogni istante. Ma a 78 anni, la vita sembra essergli sfuggita di mano, finché un colpo di fortuna (e un tenace esploratore di 8 anni di nome Russell) non gli regala una nuova prospettiva.","de":"Carl Fredricksen hat Zeit seines Lebens mit seiner Frau davon geträumt, die Welt zu bereisen, Abenteuer zu erleben und in Südamerika die Paradise-Fälle zu besuchen. Immer ist etwas dazwischen gekommen. Nach ihrem Tod will der 78-jährige die Pläne endlich in die Tat umsetzen, zumal sein Häuschen einer neuen Immobilie den Platz machen soll. Begleitet von dem hartnäckigen Pfadfinder Russell macht er sich auf den Weg – inklusive seines Häuschens, das sich, an zahllosen Ballons aufgehängt, in die Lüfte schwingt …"}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/k55kMEPkxGej70udPcVNqhTiwBz.jpg","en":"https://image.tmdb.org/t/p/w500/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg","es":"https://image.tmdb.org/t/p/w500/1N0LtzUueXrlnpL466jQBJ6iAuj.jpg","it":"https://image.tmdb.org/t/p/w500/j3Ga41uc0y3W8KbKjSfPHQiZYVn.jpg","de":"https://image.tmdb.org/t/p/w500/gOOVHWgBmpoeYXG9tGFiNOLsSWl.jpg"}'::jsonb WHERE id = 311;
UPDATE public.films SET tmdb_id = 591, titoli_i18n = '{"en":"The Da Vinci Code","de":"The Da Vinci Code - Sakrileg","it":"Il codice da Vinci","fr":"Da Vinci Code","es":"El código Da Vinci"}'::jsonb, trame_i18n = '{"en":"A murder in Paris’ Louvre Museum and cryptic clues in some of Leonardo da Vinci’s most famous paintings lead to the discovery of a religious mystery. For 2,000 years a secret society closely guards information that — should it come to light — could rock the very foundations of Christianity.","de":"Mitten in der Nacht wird der renommierte Harvard-Symbologe Robert Langdon in den Pariser Louvre gerufen: Der Museumsdirektor wurde ermordet. Seine Leiche, die in einer Körperhaltung wie der des Vitruvischen Mannes von Leonardo da Vinci aufgefunden wird, ist der erste grausige Hinweis in einer mysteriösen Kette aus Codes und Symbolen. Unter Einsatz seines Lebens entschlüsselt Langdon mit Hilfe der Polizei- Kryptografin, Sophie Neveu versteckte Botschaften in den Kunstwerken Leonardo da Vincis. Alle verweisen auf eine sagenumwobene Bruderschaft, deren Mitglieder seit 2000 Jahren ein machtvolles Geheimnis bewahren. Die atemlose Schnitzeljagd führt Langdon und Sophie von Paris über London bis nach Schottland; währenddessen versuchen sie verzweifelt, den Code zu knacken, um mit ihm ein Geheimnis zu enthüllen, das die Menschheit in ihren Grundfesten erschüttern wird.","it":"Nel Museo del Louvre ha avuto luogo uno spettacolare omicidio e tutti gli indizi fanno pensare ad una setta religiosa che non si ferma davanti a niente pur di difendere una verità, la quale però non può essere nascosta ancora a lungo e il mistero rischia di essere decodificato. Per proteggere un segreto a volte basta chiedere a chi lo custodisce di non rivelarlo; tuttavia se può far crollare 2''000 anni di dogmi consolidati, bisogna mettere a tacere i suoi depositari, costasse anche la loro vita.","fr":"Une nuit, le professeur Robert Langdon, éminent spécialiste de l''étude des symboles, est appelé d''urgence au Louvre : le conservateur du musée a été assassiné, mais avant de mourir, il a laissé de mystérieux symboles... Avec l''aide de la cryptologue Sophie Neveu, Langdon va mener l''enquête et découvrir des signes dissimulés dans les œuvres de Léonard de Vinci. Tous les indices convergent vers une organisation religieuse aussi mystérieuse que puissante, prête à tout pour protéger un secret capable de détruire un dogme deux fois millénaire... De Paris à Londres, puis en Écosse, Langdon et Sophie vont tout tenter pour déchiffrer le code et approcher les secrets qui remettent en cause les fondements mêmes de l''humanité...","es":"El catedrático y afamado simbologista Robert Langdon se ve obligado a acudir una noche al Museo del Louvre, cuando el asesinato de un restaurador deja tras de sí un misterioso rastro de símbolos y pistas. Con la ayuda de la criptógrafa de la policía Sophie Neveu y poniendo en juego su propia vida, Langdon descubre que la obra de Leonardo Da Vinci esconde una serie de misterios que apuntan a una sociedad secreta encargada de custodiar un antiguo secreto que ha permanecido oculto durante dos mil años..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/9ejKfNk0LBhSI9AahH4f9NJNZNM.jpg","de":"https://image.tmdb.org/t/p/w500/99ef1uGXkiQU4h2wuN3xIBC2kCN.jpg","it":"https://image.tmdb.org/t/p/w500/sBqvvYq8PSNCJD3154Vdl5e7vAs.jpg","fr":"https://image.tmdb.org/t/p/w500/q6wt3HwGwRnzKbpgwNTeIZgHKkH.jpg","es":"https://image.tmdb.org/t/p/w500/r5DHVCB5AV7B7GLmXMyA71Y4Yu4.jpg"}'::jsonb WHERE id = 312;
UPDATE public.films SET tmdb_id = 13448, titoli_i18n = '{"it":"Angeli e demoni","es":"Ángeles y demonios","de":"Illuminati","en":"Angels & Demons","fr":"Anges et Démons"}'::jsonb, trame_i18n = '{"it":"Roma e il mondo sono in lutto per la morte del Santo Padre. Distrutto l''anello piscatorio, il camerlengo deve fare fronte al rapimento dei quattro cardinali favoriti alla successione pontificia e alla minaccia della distruzione della Città del Vaticano ad opera degli Illuminati, una confraternita venuta dal passato a rivendicare il primato della scienza sulla Chiesa e sullo Spirito. Riunito in Concistoro per eleggere il nuovo Papa, il collegio cardinalizio assolda Robert Langdon, docente di simbologia religiosa a Harvard. Nemico stimato della Chiesa, che non gli perdona la negazione dell''incarnazione del Verbo, il cavaliere accademico accetta l''investitura e parte alla volta della Capitale. Archiviati acredine e risentimento, il professore e gli uomini della Chiesa, armati di spirito e alabarda, collaboreranno alle indagini e alla risoluzione del mistero. Un mistero nascosto dentro le chiese e sotto le segrete della Città Eterna.","es":"Robert Langdon descubre la prueba de la reaparición de una antigua hermandad secreta conocida como los Illuminati: la más poderosa organización secreta en la historia, que a su vez también se enfrenta a una amenaza que hace que peligre su existencia: la Iglesia Católica. Cuando Langdon se entera de que los Illuminati conspiran en contra de la Iglesia intentando detonar una bomba de antimateria, él se dirige a Roma, donde une fuerzas con Vittoria Vetra.","de":"Die Gefahr lauert im Geheimen. Während in Rom die Papstwahlen Gläubige auf der ganzen Welt in Atem halten, plant der untergegangen geglaubte und einst herausragend mächtige Geheimbund „Die Illuminati“ den entscheidenden Schlag gegen seinen alten Erzfeind: die katholische Kirche. Das zumindest findet der amerikanische Wissenschaftler Robert Langdon heraus, der keine Zeit verliert und sich in Rom mit der italienischen Kollegin Vittoria Vetra verbündet. Ein Wettlauf mit der Zeit auf der Suche nach altertümlichen Symbolen und der Rettung für den Vatikan beginnt.","en":"Harvard symbologist Robert Langdon is recruited by the Vatican to investigate the apparent return of the Illuminati – a secret, underground organization – after four cardinals are kidnapped on the night of the papal conclave.","fr":"Une antique confrérie secrète parmi les plus puissantes de l''Histoire, les \"Illuminati\", qui s''était jurée autrefois d''anéantir l''Église catholique, est de retour. Cette fois, elle est sur le point de parvenir à son but : Robert Langdon, expert en religions d''Harvard, en a la certitude. Langdon a peu de temps pour comprendre ce qui se trame contre le Vatican et déjouer ces nouveaux crimes. Une course contre la montre et contre les tueurs qui démarre tel un jeu de piste : des églises romaines aux cryptes enfouies, des catacombes les plus profondes aux majestueuses cathédrales... Pour l''aider à comprendre toutes ces énigmes, Langdon va rencontrer Vittoria Vetra, une scientifique aussi belle que mystérieuse. Cette fois, il sait à qui il se confronte. Cette enquête diabolique est un piège, chaque secret est une clé, chaque révélation un danger..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/9Jc7YuiYVFpiJ7tbvXkRV7GTxTM.jpg","es":"https://image.tmdb.org/t/p/w500/kLTpEwwVyquJmWak9qKGc4icFMK.jpg","de":"https://image.tmdb.org/t/p/w500/yGVoQ7nFCDE1uuqiZL6ZVSLOZKf.jpg","en":"https://image.tmdb.org/t/p/w500/tFZQAuulEOtFTp0gHbVdEXwGrYe.jpg","fr":"https://image.tmdb.org/t/p/w500/yNrMIGy1eG0cjd2WSrHz2OcUWEy.jpg"}'::jsonb WHERE id = 313;
UPDATE public.films SET tmdb_id = 13223, titoli_i18n = '{"es":"Gran Torino","fr":"Gran Torino","de":"Gran Torino","it":"Gran Torino","en":"Gran Torino"}'::jsonb, trame_i18n = '{"es":"Walt Kowalski, un veterano de la guerra de Corea, es un obrero jubilado del sector del automóvil. Su máxima pasión es cuidar de su más preciado tesoro: un coche Gran Torino de 1972. Es un hombre inflexible y con una voluntad de hierro, al que le cuesta trabajo asimilar los cambios que se producen a su alrededor. Sin embargo, las circustancias harán que se vea obligado a replantearse sus ideas.","fr":"Walt Kowalski est un ancien de la guerre de Corée, un homme inflexible, amer et pétri de préjugés surannés. Après des années de travail à la chaîne, il vit replié sur lui-même, occupant ses journées à bricoler, traînasser et siroter des bières. Avant de mourir, sa femme exprima le vœu qu''il aille à confesse, mais Walt n''a rien à avouer, ni personne à qui parler. Hormis sa chienne Daisy, il ne fait confiance qu''à son M-1, toujours propre, toujours prêt à l''usage… Ses anciens voisins ont déménagé ou sont morts depuis longtemps. Son quartier est aujourd''hui peuplé d''immigrants asiatiques qu''il méprise, et Walt ressasse ses haines, innombrables - à l''encontre de ses voisins, des ados Hmong, latinos et afro-américains « qui croient faire la loi », de ses propres enfants, devenus pour lui des étrangers. Walt tue le temps comme il peut, en attendant le grand départ, jusqu''au jour où un ado Hmong du quartier tente de lui voler sa précieuse Ford Gran Torino…","de":"Der verwitwete Koreakrieg-Veteran Walt Kowalski ist ein verbitterter Misanthrop. Für die jüngere Generation hat er ob deren angeblicher Respektlosigkeit nur Verachtung übrig, das Verhältnis zu seinen eigenen Kindern ist eisig. Liebe und Zuneigung erfahren lediglich sein Hund Daisy, sein altes Sturmgewehr sowie sein pedantisch gepflegter Ford Gran Torino. Dass Kowalskis einst geliebtes Viertel zunehmend von Migranten vor allem aus Südostasien überschwemmt wird, ist dem pensionierten Fabrikarbeiter ein massiver Dorn im Auge. Beim Einzug einer koreanischen Familie ins Nachbarhaus, macht der rassistische Rentner auch keinen Hehl aus seiner Verachtung. Als deren halbwüchsiger Sohn Taoh im Zuge eines Initiationsrituals ausgerechnet Kowalskis geliebten Gran Torino stehlen soll, droht die angespannte Situation zu eskalieren ...","it":"Walt Kowalski è un veterano della guerra in Corea e non sopporta che nell''abitazione di fianco alla sua viva una famiglia di asiatici. Le uniche sue passioni, oltre alla birra, sono il suo cane e un''auto modello Gran Torino, che viene sottoposta a continua manutenzione. La sua vita cambia il giorno in cui il giovane vicino Thao, spinto da una gang, si introduce nel suo garage. Walt lo fa fuggire, ma di lì a poco tempo assisterà a una violenta irruzione dei membri della gang con inatteso sconfinamento nella sua proprietà. In quell''occasione sottrarrà Thao alla violenza del branco, ottenendo la riconoscenza della sua famiglia.","en":"Disgruntled Korean War veteran Walt Kowalski sets out to reform his neighbor, Thao Lor, a Hmong teenager who tried to steal Kowalski''s prized possession: a 1972 Gran Torino."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/7w54KRHdRokgXqxL59GKVau8e6l.jpg","fr":"https://image.tmdb.org/t/p/w500/sVmDIIFPzbyEz87dZYpLfetn4Lm.jpg","de":"https://image.tmdb.org/t/p/w500/rotZYrCliqDaqLWCyj6HEa8yHuT.jpg","it":"https://image.tmdb.org/t/p/w500/eUepSGWIJjXeMAlSnk4CSZKOTfg.jpg","en":"https://image.tmdb.org/t/p/w500/zUybYvxWdAJy5hhYovsXtHSWI1l.jpg"}'::jsonb WHERE id = 314;
UPDATE public.films SET tmdb_id = 12163, titoli_i18n = '{"it":"The Wrestler","en":"The Wrestler","es":"El luchador","fr":"The Wrestler","de":"The Wrestler"}'::jsonb, trame_i18n = '{"it":"Randy \"The Ram\" Robinson era un wrestler professionista di rinomata fama alla fine degli anni 80''. Vent''anni dopo tira avanti esibendosi per i fans del duro wrestling nelle palestre dei licei e nelle comunità del New Jersey. Allontanatosi dalla figlia, incapace di sostenere un vero rapporto, Randy vive per il brivido dello show, per l''adrenalina del combattimento e per l''adorazione dei fans che gli rimangono. Colto da un infarto durante un combattimento, il dottore gli dice di eliminare gli steroidi e di sospendere i combattimenti di wrestling. Costretto a lasciare lo show-business, Randy comincia a riflettere sulla sua vita. Prova a riallacciare i rapporti con sua figlia e inizia una relazione con una spogliarellista ormai non più giovanissima. Per un periodo le cose funzionano; tuttavia il richiamo della ribalta è troppo forte per lui e Randy si cimenta ancora una volta nel combattimento sul ring.","en":"Aging wrestler Randy \"The Ram\" Robinson is long past his prime but still ready and rarin'' to go on the pro-wrestling circuit. After a particularly brutal beating, however, Randy hangs up his tights, pursues a serious relationship with a long-in-the-tooth stripper, and tries to reconnect with his estranged daughter. But he can''t resist the lure of the ring and readies himself for a comeback.","es":"Randy \"The Ram\" Robinson (Mickey Rourke) es un luchador profesional de wrestling que, tras haber sido una estrella en la década de los ochenta, trata de continuar su carrera en el circuito independiente, combatiendo en cuadriláteros de tercera categoría. Cuando se da cuenta de que los brutales golpes que ha recibido a lo largo de su carrera le empiezan a pasar factura, decide poner un poco de orden en su vida: intenta acercarse a Stephanie, la hija que abandonó (Evan Rachel Wood) y trata de superar la soledad con su amor por Cassidy, una streaper (Marisa Tomei).","fr":"A la fin des années 80, Randy Robinson, dit The Ram (\"Le Bélier\"), était une star du catch. Vingt ans plus tard, il ne se produit plus que dans des salles de gym de lycées ou des maisons de quartier... Brouillé avec sa fille, il est incapable d''entretenir une relation durable avec quiconque : il ne vit que pour le plaisir du spectacle et l''adoration de ses fans. Mais lorsqu''il est foudroyé par une crise cardiaque au beau milieu d''un match, son médecin lui ordonne d''abandonner le catch : un autre combat pourrait lui être fatal. Contraint de se ranger, il tente de renouer avec sa fille et, dans le même temps, entame une liaison avec une strip-teaseuse vieillissante. Pourtant, son goût du spectacle et sa passion pour le catch risquent bien de reprendre le dessus et de le propulser de nouveau sur le ring...","de":"Randy „The Ram“ Robinson steht vor den Trümmern seines Lebens: Die große Zeit als Wrestling-Star in den 80er Jahren ist längst vorbei, finanziell ist es schlecht um ihn bestellt und seine Tochter Stephanie hat nicht mehr als Enttäuschung und Verachtung für ihn übrig. Während sich Randy an seine vergangenen Erfolge klammert, weiterhin auf miesen kleinen Kampf-Events auftritt und sich mit Steroiden in körperlicher Form hält, muss der abgewrackte Profi-Wrestler feststellen, wie weit seine Vereinsamung bereits fortgeschritten ist. Nur mit Stripperin Cassidy verbindet ihn eine tiefere Freundschaft. Zu seiner miserablen Gesamtsituation kommen erschwerend gesundheitliche Probleme hinzu, die ihren vorläufigen Höhepunkt in einem Herzanfall finden. Randy muss das Wrestling an den Nagel hängen um weitere Zusammenbrüche zu vermeiden – doch im Berufsleben kann der alternde Sportler nicht mehr Fuß fassen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/A0Uq6fZG9UVbaFZmwF593ESz8LE.jpg","en":"https://image.tmdb.org/t/p/w500/7QH5p5BF582k6qHufCKjftfkqWH.jpg","es":"https://image.tmdb.org/t/p/w500/hQpBhEHCFNYgakxpP6pAVB2k3fp.jpg","fr":"https://image.tmdb.org/t/p/w500/7QpX4fwxAG6F90dCp6TgXYX0YkI.jpg","de":"https://image.tmdb.org/t/p/w500/7QH5p5BF582k6qHufCKjftfkqWH.jpg"}'::jsonb WHERE id = 315;
UPDATE public.films SET tmdb_id = 12162, titoli_i18n = '{"es":"En tierra hostil","it":"The Hurt Locker","fr":"Démineurs","en":"The Hurt Locker","de":"Tödliches Kommando - The Hurt Locker"}'::jsonb, trame_i18n = '{"es":"En Irak, una unidad de élite de artificieros norteamericanos actúa en una caótica ciudad donde cualquier persona puede ser un enemigo y cualquier objeto, una bomba. El jefe del grupo, el sargento Thompson, muere en el transcurso de una misión y es sustituido por el impredecible y temerario sargento William James. Cuando falta poco para que la brigada sea relevada, el imprudente comportamiento de James hará que dos de sus subordinados, se planteen seriamente el riesgo que corren.","it":"I 40 giorni al fronte, in Iraq, di una squadra di artificieri e sminatori dell''esercito statunitense, unità speciale con elevatissimo tasso di mortalità. Quando tutto quel che resta del suo predecessore finisce in una \"cassetta del dolore\", pronta al rimpatrio, a capo della EOD (unità per la dismissione di esplosivi) arriva il biondo William James, un uomo che ha disinnescato un numero incredibile di bombe e sembra non conoscere la paura della morte. Uno che non conta i giorni, un volontario che ha scelto quel lavoro e da esso si è lasciato assorbire fino al punto di non ritorno.","fr":"Bagdad. Le lieutenant James est à la tête de la meilleure unité de déminage de l''US Army. Leur mission: désamorcer des bombes dans des quartiers civils ou des théâtres de guerre, au péril de leur vie, alors que la situation locale est encore... explosive.","en":"During the Iraq War, a Sergeant recently assigned to an army bomb squad is put at odds with his squad mates due to his maverick way of handling his work.","de":"Als wäre der Job der Bombenexperten im Irak nicht schon gefährlich genug, müssen Sanborn und Eldridge, beides Soldaten einer kleinen Elite-Einheit, feststellen, dass ihr neuer Sergeant lebensgefährliche Alleingänge unternimmt und den Tod herauszufordern scheint. Wenn sie den Krieg überleben wollen, müssen sie ihn schnellstmöglich unter Kontrolle bringen."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/q57Kw9mCuqAa2cP2qHaU9zFxgdM.jpg","it":"https://image.tmdb.org/t/p/w500/9XaL18pWKcQO2M581832MjHlldD.jpg","fr":"https://image.tmdb.org/t/p/w500/mk9FGer03HxwLwFQeHkMiYtQi8o.jpg","en":"https://image.tmdb.org/t/p/w500/io2dfBJhasvGbgkCX9cCGVOiA99.jpg","de":"https://image.tmdb.org/t/p/w500/w1A4vVABxCyuLVjxuFFbMWcX4pC.jpg"}'::jsonb WHERE id = 316;
UPDATE public.films SET tmdb_id = 6479, titoli_i18n = '{"en":"I Am Legend","it":"Io sono leggenda","es":"Soy leyenda","de":"I Am Legend","fr":"Je suis une légende"}'::jsonb, trame_i18n = '{"en":"Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.","it":"New York, 2012. Un virus creato per curare il cancro, ha trasformato le persone in creature cannibali che temono la lice del sole. La città è deserta e l''unico sopravvissuto è il dottor Robert Neville, immune al virus che tenta di trovare un siero che potrebbe salvare l''umanità.","es":"Año 2012. Robert Neville es el último hombre vivo que hay sobre la Tierra, pero no está solo. Los demás seres humanos se han convertido en unos mutantes nocturnos llamados \"Darkseekers\" y todos ansían beber su sangre. Durante el día vive en estado de alerta, como un cazador, y busca a los muertos vivientes mientras duermen; pero durante la noche debe esconderse de ellos y esperar el amanecer. Esta pesadilla empezó hace tres años: Neville era un brillante científico, pero no pudo impedir la expansión de un terrible virus creado por el hombre. Él ha sobrevivido porque es inmune al virus; todos los días envía mensajes por radio con la esperanza de que haya otros supervivientes, pero es inútil. Lo único que puede hacer es buscar una fórmula que le permita utilizar su sangre inmune para devolverles a los hombres su naturaleza. Pero está en inferioridad de condiciones y el tiempo se acaba.","de":"Robert Neville war ein hervorragender Wissenschaftler, aber auch er konnte nicht verhindern, dass ein Virus vor 3 Jahren die gesamte Menschheit befiel. Nur er wurde aus unbekannten Gründen verschont und hat es sich inzwischen in einer immer mehr verwahrlosenden Umgebung eingerichtet. Tagsüber kann er sich verhältnismäßig frei bewegen, aber nachts lauern überall Gefahren durch vampirähnliche infizierte Gestalten, die nur das Sonnenlicht fern halten kann. Doch die Bedrohung wächst ständig und er versucht ein Gegenserum zu entwickeln...","fr":"Des années après qu''une épidémie a anéanti presque tous les êtres humains et transformé le reste en monstres, le seul survivant à New York se bat vaillamment pour trouver un remède."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/fhbiz5BsGUVEZmzPP72SoPlbMz0.jpg","it":"https://image.tmdb.org/t/p/w500/lrHsksAln0IxYFfZVgW6iRTaUsi.jpg","es":"https://image.tmdb.org/t/p/w500/pO1SrJgf5BumqcIRkYviSGIFdmX.jpg","de":"https://image.tmdb.org/t/p/w500/9rb7n00Q6KDsWH2jZOdeSHe0mvL.jpg","fr":"https://image.tmdb.org/t/p/w500/wCcC0oAsM1YHfO4sBFLSUtqCQZx.jpg"}'::jsonb WHERE id = 317;
UPDATE public.films SET tmdb_id = 7345, titoli_i18n = '{"es":"Pozos de ambición","fr":"There Will Be Blood","en":"There Will Be Blood","de":"There Will Be Blood","it":"Il petroliere"}'::jsonb, trame_i18n = '{"es":"Texas, principios del siglo XX. Una historia sobre la familia, la avaricia y la religión. Daniel Plainview (Daniel Day-Lewis) se traslada a una miserable ciudad con el propósito de hacer fortuna, pero, a medida que se va enriqueciendo, sus principios y valores desaparecen y acaba dominado por la ambición. Tras encontrar un rico yacimiento de petróleo en 1902, se convierte en un acaudalado magnate. Cuando, años después, intenta apoderarse de un nuevo yacimiento, tiene que enfrentarse al predicador Eli Sunday (Paul Dano). Adaptación de la novela de Upton Sinclair \"Petróleo\", escrita en 1927.","fr":"Lorsque Daniel Plainview entend parler d’une petite ville de Californie où l’on dit qu’un océan de pétrole coulerait littéralement du sol, il décide d’aller tenter sa chance et part avec son fils H.W. à Little Boston. Dans cet endroit perdu où chacun lutte pour survivre et où l’unique distraction est l’église animée par le charismatique prêtre Eli Sunday, Plainview et son fils voient le sort leur sourire. Même si le pétrole comble leurs attentes et fait leur fortune, plus rien ne sera comme avant : les tensions s’intensifient, les conflits éclatent et les valeurs humaines comme l’amour, l’espoir, le sens de la communauté, les croyances, l’ambition et même les liens entre père et fils sont mis en péril par la corruption, la trahison… et le pétrole.","en":"Ruthless silver miner, turned oil prospector, Daniel Plainview, moves to oil-rich California. Using his son to project a trustworthy, family-man image, Plainview cons local landowners into selling him their valuable properties for a pittance. However, local preacher Eli Sunday suspects Plainview''s motives and intentions, starting a slow-burning feud that threatens both their lives.","de":"Daniel Plainview versucht Ende des 19. Jahrhunderts sein Glück als Schürfer auf der Suche nach Silber, doch er entdeckt bei der harten Arbeit eines Tages eine Ölquelle. Für den nur auf Profit eingestellten Einzelgänger erschließt sich eine neue Obsession und schon bald beginnt er seine Arbeit im Ölgeschäft. Schon früh kommt sein Partner zu Tode, woraufhin Daniel sich dessen Sohnes annimmt, der als Waise zurück blieb. Doch auch diesen Schritt wählt Daniel nur, um sich Vorteile zu erschleichen und so steigt er durch Rücksichtslosigkeit, Betrug und harte eigene Arbeit zu einem schwerreichen Ölbaron auf. Sein Ziehsohn H.W. dagegen verliert sein Gehör bei einem Unfall an der Ölpumpe. Im Laufe der Jahre wächst Daniels Vermögen und mit ihm sein grenzenloser Hass auf die Menschen …","it":"Daniel Plainview è un cercatore d''argento che, alla fine dell''800 trova il petrolio nell''Ovest degli Stati Uniti. La sua ricchezza diventa considerevole, ma l''uomo, sempre più accecato da una misantropia assoluta, allontanerà da sé anche il figlio, precipitando sempre più nell''avidità del possesso."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/fho18jHViMUC2Ax8xdkkGwimbTe.jpg","fr":"https://image.tmdb.org/t/p/w500/fa0RDkAlCec0STeMNAhPaF89q6U.jpg","en":"https://image.tmdb.org/t/p/w500/fa0RDkAlCec0STeMNAhPaF89q6U.jpg","de":"https://image.tmdb.org/t/p/w500/r3VUQ6prbQ7O96BYd8PiMWzdQcm.jpg","it":"https://image.tmdb.org/t/p/w500/2eH78Nz708yFVrcaZAE2bspY5q5.jpg"}'::jsonb WHERE id = 318;
UPDATE public.films SET tmdb_id = 4638, titoli_i18n = '{"en":"Hot Fuzz","it":"Hot Fuzz","de":"Hot Fuzz - Zwei abgewichste Profis","fr":"Hot Fuzz","es":"Arma fatal"}'::jsonb, trame_i18n = '{"en":"Former London constable Nicholas Angel finds it difficult to adapt to his new assignment in the sleepy British village of Sandford. Not only does he miss the excitement of the big city, but he also has a well-meaning oaf for a partner. However, when a series of grisly accidents rocks Sandford, Angel smells something rotten in the idyllic village.","it":"Vittima dell''invidia dei colleghi e dei superiori, l''agente Nicholas Angel, pluridecorato, viene considerato un esaltato. Con la scusa di una promozione, così, i suoi superiori cercano di allontanarlo il più possibile da Londra, spedendolo in un paesino a 250 km di distanza, dove non accade nulla di emozionante, almeno apparentemente... Seguendo la pista di alcune morti che sembrano casuali, Angel s''imbatte finalmente in un caso \"succulento\"...","de":"Der Polizist Nicholas Angel wird von London in das Provinznest Sandford versetzt, weil er seine Kollegen immer in den Schatten stellte. Zunächst langweilt er sich - doch dann hat er mehr als nur Kleinstadtdelikte aufzudecken. Zwar gibt es an seinem neuen Einsatzort kaum Verbrechen, dafür aber jede Menge „Unfälle“.","fr":"À Londres, le policier Nicholas Angel est le meilleur de son équipe. Tellement bon qu''il fait passer ses collègues pour de simples gardiens de la paix. Le chef de la brigade décide donc de le « promouvoir » dans le petit village de Sandford, où il ne se passe rien. Aux côtés du policier local Danny Butterman qui rêve de devenir Mel Gibson, Nicholas règle quelques contraventions sans grand intérêt. Une série de crimes étranges va le remettre dans l''action…","es":"Nicholas Angel es, sin duda alguna, el mejor policía de Londres. Sus detenciones superan en un 400% al segundo mejor agente del Cuerpo. Es tan bueno que, comparado a él, cualquier poli es malo. Por eso sus superiores deciden trasladarle a un lugar en que su talento no ponga a nadie en evidencia, a Sandford, un aparentemente adormecido y pacífico pueblecito."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/zPib4ukTSdXvHP9pxGkFCe34f3y.jpg","it":"https://image.tmdb.org/t/p/w500/xY1DI4NJGgwbP5dqjPHgQWB4Elb.jpg","de":"https://image.tmdb.org/t/p/w500/2XZ5B1yTAaRur9YW1sryHEkyx7E.jpg","fr":"https://image.tmdb.org/t/p/w500/tddbD3ETiKucVg15GKWkzveU7SI.jpg","es":"https://image.tmdb.org/t/p/w500/kO2Ez6xOf5CJiQywkMo27nHzBF4.jpg"}'::jsonb WHERE id = 319;
UPDATE public.films SET tmdb_id = 1579, titoli_i18n = '{"it":"Apocalypto","en":"Apocalypto","es":"Apocalypto","fr":"Apocalypto","de":"Apocalypto"}'::jsonb, trame_i18n = '{"it":"Negli anni del declino del regno Maya, i governanti sono convinti che per tornare a prosperare basterà costruire nuovi templi e fare numerosi sacrifici umani. Ma Zampa di giaguaro, un giovane selezionato essere ucciso sull''altare, decide di tentare di sfuggire al suo destino...","en":"Set in the Mayan civilization, when a man''s idyllic presence is brutally disrupted by a violent invading force, he is taken on a perilous journey to a world ruled by fear and oppression where a harrowing end awaits him. Through a twist of fate and spurred by the power of his love for his woman and his family he will make a desperate break to return home and to ultimately save his way of life.","es":"Historia ambientada en la época del imperio maya. Cuando la idílica existencia de los mayas es brutalmente interrumpida por el ataque de una fuerza invasora, un hombre emprende un arriesgado viaje a un mundo regido por el miedo y la opresión en el que le espera un incierto final. Debido a un giro del destino y espoleado por el amor a su esposa y a su familia, emprenderá el regreso a su hogar en un desesperado esfuerzo por preservar su forma de vida...","fr":"Dans les temps turbulents précédant la chute de la légendaire civilisation Maya. Jeune père porteur de grandes espérances, chef de son petit village, Patte de Jaguar vit une existence idyllique brusquement perturbée par une violente invasion. Capturé et emmené lors d''un périlleux voyage à travers la jungle pour être offert en sacrifice aux Dieux de la Cité Maya, il découvre un monde régi par la peur et l''oppression, dans lequel une fin déchirante l''attend inéluctablement. Poussé par l''amour qu''il porte à sa femme, à sa famille et à son peuple, il devra affronter ses plus grandes peurs en une tentative désespérée pour retourner chez lui et tenter de sauver ce qui lui tient le plus à cœur.","de":"Es ist die Zeit, in der der Niedergang einer der ältesten und geheimnisvollsten Hochkulturen aller Zeiten bevorsteht: der Maya. Bis heute birgt diese Zeit offene Fragen und ungeklärte Geheimnisse. In Apocalypto skizziert Mel Gibson die Geschichte eines Mannes aus dem Volk der Maya, der in dieser Zeit um sein Leben kämpft. Nur die Liebe zu seiner Familie und zu seiner Frau gibt ihm die Kraft und den Mut zu bestehen."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8z6coUJwLrM9akjheUeTTQ8Bgxx.jpg","en":"https://image.tmdb.org/t/p/w500/cRY25Q32kDNPFDkFkxAs6bgCq3L.jpg","es":"https://image.tmdb.org/t/p/w500/yQ4uC13IYVerbxMMXeSogSQUkOT.jpg","fr":"https://image.tmdb.org/t/p/w500/5xR5OjvGQfaRZNL7GTuPAZy8tdr.jpg","de":"https://image.tmdb.org/t/p/w500/oCG3GYXIdwW1oQNz61a21xkVjuG.jpg"}'::jsonb WHERE id = 320;
UPDATE public.films SET tmdb_id = 1991, titoli_i18n = '{"it":"Grindhouse - A prova di morte","de":"Death Proof - Todsicher","es":"Death Proof","fr":"Boulevard de la mort","en":"Death Proof"}'::jsonb, trame_i18n = '{"it":"Tre ragazze Jungle Julia, Shanna e Arlene, tutte molto carine, si divertono a passare le serate tra due locali di Austin, Texas, il \"Guero''s\" e il \"Texas Chili Parlor\", dove attirano gli sguardi indiscreti degli avventori. Tra i tanti camionisti e motociclisti presenti al locale c''è Stuntman Mike un killer misogino schizofrenico che si diverte a uccidere le ragazze a bordo di una truccatissima vettura. Una sera, Mike prende di mira le tre amiche e, a loro insaputa, le seduce per poi condurle verso la sua arma, posteggiata vicino il Guero''s...","de":"Austin, Texas: Jungle Julia und ihre beiden Freundinnen Arlene und Shanna machen mal wieder ohne Männer in ihrer Lieblingsbar einen drauf. Männer kann man unterwegs ja immer noch aufreißen. Ausgerechnet an den harmlosen Stuntman Mike gerät die Truppe. Als die Damen ihn aber trotz eines Gewinns abblitzen lassen, zeigt der vernarbte Stuntman sein wahres Gesicht: Er kümmert sich auf seine Weise um das das Damentrio. Nicht zum erstenmal und nicht zum letztenmal beginnt für den Psychopathen ein tödliches Spiel auf der Straße. Ein knappes Jahr später in Lebanon, Tennessee: Wieder gerät eine Gruppe in die Schußbahn von Mike: Kim, Zoe, Abernathy und Lee. Doch diesmal hat er sich die Falschen für sein Spielchen ausgesucht, denn diese Damen haben offenbar nicht die Absicht in die Opferrolle zu schlüpfen ...","es":"\"Death Proof\", dirigida por Tarantino, gira en torno a un psicópata de la carretera llamado Especialista Mike, un asesino en serie que va aniquilando a sus víctimas, siempre chicas jóvenes, con su coche de especialista \"a prueba de muerte\".","fr":"C’est à la tombée du jour que Jungle Julia, la DJ la plus sexy d’Austin, peut enfin se détendre avec ses meilleures copines, Shanna et Arlene. Ce trio infernal, qui vit la nuit, attire les regards dans tous les bars et dancings du Texas. Mais l’attention dont ces trois jeunes femmes sont l’objet n’est pas forcément innocente. C’est ainsi que Mike, cascadeur au visage balafré et inquiétant, est sur leurs traces, tapi dans sa voiture indestructible. Tandis que Julia et ses copines sirotent leurs bières, Mike fait vrombir le moteur de son bolide menaçant…","en":"Austin''s hottest DJ, Jungle Julia, sets out into the night to unwind with her two friends Shanna and Arlene. Covertly tracking their moves is Stuntman Mike, a scarred rebel leering from behind the wheel of his muscle car, revving just feet away."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kf493fwH6DM9sNZ798Qf9NnSsBG.jpg","de":"https://image.tmdb.org/t/p/w500/4RoeXMF9nvDoLyiAP696rJdAE07.jpg","es":"https://image.tmdb.org/t/p/w500/7AEMH73JTb0qqAZgMj5orBGLUrO.jpg","fr":"https://image.tmdb.org/t/p/w500/1cajesADv9jGJAMqC2peAnxh5ar.jpg","en":"https://image.tmdb.org/t/p/w500/vtu6H4NWnQVqEp3aanUq3hNeeot.jpg"}'::jsonb WHERE id = 321;
UPDATE public.films SET tmdb_id = 1124, titoli_i18n = '{"es":"El truco final (El prestigio)","de":"Prestige - Die Meister der Magie","it":"The Prestige","fr":"Le Prestige","en":"The Prestige"}'::jsonb, trame_i18n = '{"es":"Robert Angier es un ilusionista respetado que se obsesiona con uno de los trucos de su rival Alfred Borden. Para conseguir el truco hará todo lo posible, sin saber hasta qué punto cambiará su vida...","de":"Im viktorianischen Zeitalter, zur Zeit der Jahrhundertwende, lernen sich die konkurrierenden Magier Robert Angier und Alfred Borden kennen. Aus freundschaftlicher, jugendlicher Konkurrenz erwächst jedoch bald etwas wesentlich Schlimmeres, denn nicht nur neidet jeder dem Anderen das Talent, Roberts Frau stirbt auch bei einem von Alfreds risikobewehrten Tricks. Über Jahre belauern und bekämpfen sie sich gegenseitig und reißen damit ihr gesamtes Umfeld in die Tiefe, nur um hinter die Tricks des jeweils anderen zu kommen. Dabei schrecken die beiden am Ende nicht einmal vor Mord zurück, denn das \"Prestige\", der unglaubliche letzte Teil eines perfekten Zaubertricks, ist jeden Einsatz wert...","it":"Due giovani maghi apprendisti, Robert Angier e Alfred Borden, vengono istruiti e seguiti da Cutter, un ingegnere illusionista ed ex mago, ma durante un numero in cui una donna viene legata e messa in una cassa di vetro piena d''acqua, qualcosa va storto e Angier incolperà l''amico dell''accaduto, tentando di vendicarsi. Inizia così un crudele gioco tra i due uomini su chi sia il migliore e la rivalità si trasformerà pian piano in ossessione.","fr":"Londres, au début du siècle dernier… Robert Angier et Alfred Borden sont deux magiciens surdoués, promis dès leur plus jeune âge à un glorieux avenir. Une compétition amicale les oppose d''abord l''un à l''autre, mais l''émulation tourne vite à la jalousie, puis à la haine. Devenus de farouches ennemis, les deux rivaux vont s''efforcer de se détruire l''un l''autre en usant des plus noirs secrets de leur art. Cette obsession aura pour leur entourage des conséquences dramatiques…","en":"A mysterious story of two magicians whose intense rivalry leads them on a life-long battle for supremacy -- full of obsession, deceit and jealousy with dangerous and deadly consequences."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/lIl2CrnWohGrZSO9eyKRptxZ7Hs.jpg","de":"https://image.tmdb.org/t/p/w500/rN2eGbRpbJw8ZFVDiQfDxsknirP.jpg","it":"https://image.tmdb.org/t/p/w500/1GjRCeZoE251tWkYc3erwjpdBpU.jpg","fr":"https://image.tmdb.org/t/p/w500/37Fr7lY4QBHsuxlLJIfTNxW6nGW.jpg","en":"https://image.tmdb.org/t/p/w500/Ag2B2KHKQPukjH7WutmgnnSNurZ.jpg"}'::jsonb WHERE id = 322;
UPDATE public.films SET tmdb_id = 1422, titoli_i18n = '{"it":"The Departed - Il bene e il male","es":"Infiltrados","en":"The Departed","de":"Departed - Unter Feinden","fr":"Les Infiltrés"}'::jsonb, trame_i18n = '{"it":"Boston. È in atto una guerra tra la polizia locale e una banda della malavita organizzata. Billy Costigan, giovane poliziotto in incognito, riceve l''incarico di infiltrarsi nella gang capeggiata dal boss Frank Costello. Mentre Billy guadagna rapidamente la fiducia di Costello, Colin Sullivan, giovane criminale incallito infiltrato nel dipartimento di polizia come informatore della gang, guadagna una posizione di rilievo nell''unità speciale di investigazione. Sia Billy che Colin vivono questa doppia vita come un''esperienza alienante, ma appena appare chiara l''esistenza di una talpa, sia all''interno della polizia che fra i gangster, entrambi dovranno, in una corsa contro il tempo, scoprire l''identità dell''altro per salvarsi.","es":"El Departamento de Policía de Massachussets se enfrenta a la mayor banda de crimen organizado de la ciudad de Boston. La estrategia consiste en acabar desde dentro con Frank Costello, el poderoso jefe de la mafia irlandesa. El encargado de infiltrarse en la banda es un joven novato, Billy Costigan. Mientras Billy intenta ganarse la confianza de Costello, otro joven policía, Colin Sullivan, sube rápidamente de categoría y ocupa un puesto en la unidad de Investigaciones Especiales, grupo de élite cuya misión también es acabar con Costello. Lo que nadie sabe es que Colin es un topo infiltrado en la policía por el propio Costello.","en":"To take down South Boston''s Irish Mafia, the police send in one of their own to infiltrate the underworld, not realizing the syndicate has done likewise. While an undercover cop curries favor with the mob kingpin, a career criminal rises through the police ranks. But both sides soon discover there''s a mole among them.","de":"Der brutale Bostoner Mafiaboss Frank Costello hat es geschafft, mit Colin Sullivan einen seiner treuesten Männer bei der städtischen Polizei einzuschleusen, um stets auf dem Laufenden über die geplanten Aktivitäten der Cops zu bleiben. Und weil die Taktik, den Gegner mit Hilfe eines Maulwurfs auszuspionieren, zwar alt aber effektiv ist, hatten auch Polizeichef Queenan und Sergeant Digman diese Idee. Ihr Undercover-Ermittler Billy Costigan hat sich schnell zu einem der engsten Vertrauten von Pate Costello hochgearbeitet. Als sowohl die Mafia als auch das Police-Department erfahren, dass sich ein Falschspieler in ihren Reihen befindet, ohne aber dessen Identität zu kennen, müssen Sullivan und Costigan alles daran setzen, dass der jeweils andere zuerst auffliegt, um somit ihre eigene Tarnung aufrecht erhalten zu können.","fr":"À Boston, une lutte sans merci oppose la police à la pègre irlandaise. Pour mettre fin au règne du parrain Frank Costello, la police infiltre son gang avec « un bleu » issu des bas quartiers, Billy Costigan. Tandis que Billy s’efforce de gagner la confiance du malfrat vieillissant, Colin Sullivan entre dans la police au sein de l’Unité des Enquêtes Spéciales, chargée d’éliminer Costello. Mais Colin fonctionne en « sous‑marin » et informe Costello des opérations qui se trament contre lui. Risquant à tout moment d’être démasqués, Billy et Colin sont contraints de mener une double vie qui leur fait perdre leurs repères et leur identité. Traquenards et contre‑offensives s’enchaînent jusqu’au jour où chaque camp réalise qu’il héberge une taupe. Une course contre la montre s’engage entre les deux hommes avec un seul objectif : découvrir l’identité de l’autre sous peine d’y laisser sa peau…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/oTIEFn7Xf3bZ6HZP3yRF8CzzmYQ.jpg","es":"https://image.tmdb.org/t/p/w500/hf0Hgw1snmBwinkHYLCxGIs6DgO.jpg","en":"https://image.tmdb.org/t/p/w500/nT97ifVT2J1yMQmeq20Qblg61T.jpg","de":"https://image.tmdb.org/t/p/w500/zqGdG5pcK7WZFgP9ynXd8jM7Bic.jpg","fr":"https://image.tmdb.org/t/p/w500/xHeuF5zzlx1YxkULiz0mx1TMBJ7.jpg"}'::jsonb WHERE id = 323;
UPDATE public.films SET tmdb_id = 1083658, titoli_i18n = '{"de":"Scoop - Ein royales Interview","it":"Scoop","en":"Scoop","es":"La gran exclusiva","fr":"Scoop"}'::jsonb, trame_i18n = '{"de":"Dieses von wahren Ereignissen inspirierte fiktionale Drama illustriert, wie sich die Frauen von Newsnight das skandalöse Interview mit Prinz Andrew sichern konnten.","it":"Questa drammatizzazione ispirata a eventi reali racconta come le donne di Newsnight hanno ottenuto la famigerata intervista con il principe Andrea.","en":"Inspired by real events, this fictional dramatization gives an insider account of how the women of Newsnight secured Prince Andrew''s infamous interview.","es":"Esta dramatización ficticia basada en hechos reales muestra cómo las periodistas de ''Newsnight'' consiguieron la famosa entrevista con el Príncipe Andrés.","fr":"Inspirée de faits réels, cette fiction raconte comment les collaboratrices de Newsnight ont réussi à approcher le prince Andrew pour une interview qui s''est avérée désastreuse."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/5lLVcYBTenqwYYI4rLX10P0LtjQ.jpg","it":"https://image.tmdb.org/t/p/w500/ib3H2ZSeVRTAmd7EtGWV31LswaZ.jpg","en":"https://image.tmdb.org/t/p/w500/ib3H2ZSeVRTAmd7EtGWV31LswaZ.jpg","es":"https://image.tmdb.org/t/p/w500/qKCVf0em0cYHfnfiJ1EtMjWV78m.jpg","fr":"https://image.tmdb.org/t/p/w500/gXLnc7e7eIax0OqL7GmbJqzYCOP.jpg"}'::jsonb WHERE id = 324;
UPDATE public.films SET tmdb_id = 512, titoli_i18n = '{"it":"Scoop","es":"Scoop","en":"Scoop","de":"Scoop - Der Knüller","fr":"Scoop"}'::jsonb, trame_i18n = '{"it":"Sondra è una giornalista in erba che riceve dal fantasma di un famoso reporter, appena morto, alcune informazioni su un serial killer ancora in libertà. Sebbene grazie a circostanze ben poco credibili, Sondra ha in mano l’occasione della sua vita e insieme al mago da avanspettacolo Sid Waterman inizia a seguire le tracce del presunto assassino, l’aristocratico e affascinante Peter Lyman.","es":"Sondra Pransky (Scarlett Johansson), una estudiante americana de periodismo, se encuentra en Gran Bretaña visitando a unos amigos. Durante su estancia en Londres, acude a un espectáculo de magia, donde un ilusionista (Woody Allen) la invita a subir al escenario para hacerla desaparecer. Mientras espera que el mago ponga en práctica su truco, recibe la visita del fantasma de un prestigioso periodista muerto (Ian McShane), que ha venido desde el más allá para servirle en bandeja la exclusiva del año. El espíritu afirma que Peter Lyman (Hugh Jackman), el rico y atractivo hijo de un conocido aristócrata británico, es en realidad el famoso asesino en serie conocido como \"el asesino del tarot\".","en":"An American journalism student in London scoops a big story, and begins an affair with an aristocrat as the incident unfurls.","de":"Ein echter Reporter tut alles für einen Knüller, notfalls kehrt er auch aus dem Reich der Toten zurück wie Joe Strombel, der auf dem Weg ins Jenseits einen Bombentip bekommt. Wie gut, daß gerade die aufstrebende Journalistin Sondra Pransky bei dem großen Magier Splendini im De-Materialisierer sitzt und von Strombel so von diesem Knüller erfährt: es geht um die Identität des Tarot-Killers, der überall gesucht wird. Gemeinsam mit Splendini, der in Wirklichkeit Sid Waterman heißt, reist Sondra nach London, um dem Killer auf die Spur zu kommen.Dabei könnte es sich um den Adeligen Peter Lyman handeln - nur ist der sehr charmant und schon bald verliebt sich Sondra in den Charmeur...","fr":"L''enquête du célèbre journaliste d''investigation Joe Strombel, consacrée au \"Tueur au Tarot\" de Londres, tourne court quand il meurt de façon aussi soudaine qu''inexplicable. Mais rien, pas même la mort, ne peut arrêter Joe. À peine arrivé au purgatoire, il décide de transmettre ses toutes dernières informations à la plus charmante des étudiantes en journalisme : Sondra Pransky. De passage à Londres, Sondra entend le fantôme de Joe s''adresser à elle durant un numéro de magie de l''Américain Splendini, alias Sid Waterman. Bouleversée et folle de joie à l''idée d''avoir déniché le scoop du siècle, l''effervescente créature se lance avec Sid dans une enquête échevelée, qui les mène droit au fringant aristocrate et politicien Peter Lyman. Une idylle se noue en dépit de troublants indices semblant désigner le beau Peter comme le \"Tueur au Tarot\". Le scoop de Sondra lui sera-t-il fatal ?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/vyQD8AHtA3zK5ufHI5l6CQ4o4TD.jpg","es":"https://image.tmdb.org/t/p/w500/r6HRh0NRuLWLmY4nabJCPLkqRX6.jpg","en":"https://image.tmdb.org/t/p/w500/1nF290EoEn2rs4W9VVercKa4S5o.jpg","de":"https://image.tmdb.org/t/p/w500/br9hS3DEjQguIMqoagxrqIHNafM.jpg","fr":"https://image.tmdb.org/t/p/w500/1oX193DhmZplAZ2xSBcT3cEYuzl.jpg"}'::jsonb WHERE id = 325;
UPDATE public.films SET tmdb_id = 1491, titoli_i18n = '{"de":"The Illusionist - Nichts ist wie es scheint","en":"The Illusionist","it":"The Illusionist - L''illusionista","es":"El ilusionista","fr":"L''Illusionniste"}'::jsonb, trame_i18n = '{"de":"Wien um 1900: Mit seinen fantastischen Vorstellungen macht sich der Illusionist Eisenheim zur lebenden Legende. Auf der Höhe seiner Kunst beschwört er den Geist der gerade ermordeten Herzogin Sophie. Doch bevor die Erscheinung den Namen ihres Mörders nennen kann, wird Eisenheim von Inspektor Uhl verhaftet. Was niemand ahnt: Die Herzogin war zwar die Verlobte von Kronprinz Leopold, aber auch die heimliche Liebe des Magiers. Wurde sie das Opfer des Machtkampfes zwischen dem Thronfolger und dem rätselhaften Meister der Täuschung? Nichts ist wie es scheint, die Grenzen zwischen Magie und Wirklichkeit verschwimmen.","en":"With his eye on a lovely aristocrat, a gifted illusionist named Eisenheim uses his powers to win her away from her betrothed, a crown prince. But Eisenheim''s scheme creates tumult within the monarchy and ignites the suspicion of a dogged inspector.","it":"Siamo all''inizio del XX secolo, in Austria. Eisenheim è un adolescente innamorato (e ricambiato) della bella Sophie: la ragazza però, è promessa sposa del Principe Leopoldo, erede al trono. I due sono costretti a separarsi ed Eisenheim scompare dalla circolazione. Quindici anni dopo, il ragazzo è cresciuto e strega Vienna con spettacoli nei quali mette in mostra le sue incredibili doti di illusionista: una sera incontra Sophie, e l''amore si riaccende, ma il Principe Leopoldo, aiutato dall''Ispettore Generale Uhl, capo della Polizia, fa di tutto per stroncare una volta per tutte la relazione.","es":"En la Viena de 1900, el misterioso Eisenheim cautiva al público con sus espectáculos de magia e ilusionismo. Sus poderes sobrenaturales llegan a los oídos del príncipe heredero Leopold, un hombre pragmático que acude a su espectáculo con incredulidad, acompañado de su prometida, la bella y sofisticada Sophie. Sospechando un fraude por parte de Eisenheim, el príncipe encarga al perspicaz inspector de policía Uhl que le vigile de cerca.","fr":"Vienne, dans les années 1900. Surgit un jour le charismatique et mystérieux illusionniste Eisenheim, qui ne tarda pas à devenir l''homme le plus célèbre de la ville, l''incarnation vivante d''une magie à laquelle personne n''osait plus croire... Mais la gloire d''Eisenheim est intolérable au Prince héritier Leopold, dont la popularité décroît à mesure que grandit celle de ce showman consommé. Rationaliste convaincu, avide de pouvoir, le Prince a une raison supplémentaire de jalouser Eisenheim : ce dernier fut le grand amour de jeunesse de sa fiancée, la belle Sophie von Teschen, qui nourrit encore pour lui de très tendres sentiments. Décidé à écarter ce rival, Leopold charge son homme de confiance, l''inspecteur Uhl, d''enquêter sur l''illusionniste et de dévoiler ses impostures. Une partie serrée s''engage entre les deux hommes..."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/2o9Em0cLmVl7YUAt9p0FedoRbXW.jpg","en":"https://image.tmdb.org/t/p/w500/1O9jUvqkHaGBMVRyOJz1AlkmALW.jpg","it":"https://image.tmdb.org/t/p/w500/bGvkZZtWymiN3am617tpExQ0ow1.jpg","es":"https://image.tmdb.org/t/p/w500/30Bo0pvLcKYDbIHNzduumAdbS7j.jpg","fr":"https://image.tmdb.org/t/p/w500/9i9Y201WJuuYOtnTgPABauyKRYj.jpg"}'::jsonb WHERE id = 326;
UPDATE public.films SET tmdb_id = 612, titoli_i18n = '{"en":"Munich","fr":"Munich","it":"Munich","es":"Munich","de":"München"}'::jsonb, trame_i18n = '{"en":"During the 1972 Olympic Games in Munich, eleven Israeli athletes are taken hostage and murdered by a Palestinian terrorist group known as Black September. In retaliation, the Israeli government recruits a group of Mossad agents to track down and execute those responsible for the attack.","fr":"Jeux Olympiques de Munich, 5 septembre 1972. Un commando de terroristes palestiniens prend en otages puis exécute 11 membres de l''équipe sportive israélienne, sous l''œil des téléspectateurs du monde entier. Inspiré de faits réels, Munich retrace le parcours de 5 agents israéliens chargés de traquer les 11 palestiniens considérés comme les commanditaires de l''attentat. Pour mener à bien cette mission, les 5 hommes devront renoncer du jour au lendemain à leur identité, et s’exposer à tout moment à la vengeance de leurs cibles.","it":"Durante le Olimpiadi del 1972 di Monaco il commando di estremisti palestinesi Settembre Nero prende in ostaggio e poi uccide gli atleti israeliani. A seguito dell''attentato, una squadra di cinque uomini viene segretamente incaricata dal governo di stanare e uccidere i responsabili. Avner, ex ufficiale del Mossad, figlio di un patriota, accetta di essere a capo della missione: per un lungo periodo dovrà abbandonare la sua identità e i suoi affetti...","es":"Basada en hechos reales. Tras el asesinato de varios atletas israelíes por el grupo terrorista \"Septiembre negro\" en los Juegos Olímpicos de Múnich de 1972, un agente especial del Mossad tuvo que ejecutar una misión altamente secreta: asesinar a los responsables.","de":"Nach dem Geiseldrama um die israelische Mannschaft bei der Olympiade in München 1972 wird der Geheimdienstler Avner von der israelischen Regierung auf die Hintermänner angesetzt. Mit einem kleinen Team reist er quer durch Europa und exekutiert die Organisatoren des palästinensischen Terrors. Doch immer mehr regen sich Zweifel über die Legitimität ihrer Aufträge. Das dreckige, konspirative Leben fordert seinen Tribut – und schließlich gerät die Gruppe selbst auf die Abschussliste."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/iUekaw96QLInZpsNwRTlRKrZgwm.jpg","fr":"https://image.tmdb.org/t/p/w500/mCWtxKSrdSjRWhFl4Mf3UDrkpdM.jpg","it":"https://image.tmdb.org/t/p/w500/5APB21LvvshIZFDtGBsNMOp6SJL.jpg","es":"https://image.tmdb.org/t/p/w500/6YTX9q7Rpjxwn8FxWaxAyHDbsmN.jpg","de":"https://image.tmdb.org/t/p/w500/rxzP6wJYqhALbXOuzrupILRpsft.jpg"}'::jsonb WHERE id = 327;
UPDATE public.films SET tmdb_id = 74, titoli_i18n = '{"en":"War of the Worlds","it":"La guerra dei mondi","es":"La guerra de los mundos","de":"Krieg der Welten","fr":"La Guerre des mondes"}'::jsonb, trame_i18n = '{"en":"Ray Ferrier is a divorced dockworker and less-than-perfect father. Soon after his ex-wife and her new husband drop off his teenage son and young daughter for a rare weekend visit, a strange and powerful lightning storm touches down.","it":"I marziani hanno deciso di invadere la Terra perché il loro pianeta è diventato invivibile e la razza umana è costretta ad affrontare una dura guerra per la sopravvivenza. Anche Ray Ferrier, ormai da tempo separato dalla sua famiglia, si trova coinvolto nella battaglia per difendere a tutti i costi i suoi figli dai violenti attacchi degli extra-terrestri...","es":"Ray Ferrier es un descargador de muelle, divorciado y padre nada modélico. Poco después de que su ex mujer y su nuevo marido se vayan después de dejar a Robbie, su hijo adolescente, y a su pequeña hija Rachel para una de sus contadas visitas, estalla una tremenda e inesperada tormenta eléctrica. Unos momentos después, en un cruce cerca de la casa, Ray es testigo de un acontecimiento que cambiará su vida y la de los suyos para siempre. Una enorme máquina de tres patas emerge del suelo y antes de que alguien pueda hacer algo, arrasa todo lo que está a su alcance. Un día como otro cualquiera acaba de convertirse en la fecha más extraordinaria de su vida: el primer ataque alienígena contra la Tierra.","de":"Eines windigen herbstlichen Nachmittags wird der Erde der Krieg erklärt. Ray ein Kranführer, und seine zwei Kinder, stehen plötzlich mitten im Geschehen: der Boden reißt auf und stählerne Kolosse erheben sich aus den Asphaltbrocken. Alles was um sie herumsteht verwandeln sie zu Staub. Ray beschließt mit den Kindern zu fliehen. Doch es gibt kaum einen Ort an den sie gelangen, der nicht schon unter Beschuss der Invasoren steht.","fr":"Ray Ferrier est un docker divorcé et un père rien moins que parfait, qui n’entretient plus que des relations épisodiques avec son fils Robbie, 17 ans, et sa fille Rachel, 11 ans. Quelques minutes après que son ex‐femme et l’époux de cette dernière lui ont confié la garde des enfants, un puissant orage éclate. Ray assiste alors à un spectacle qui bouleversera à jamais sa vie…"}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/6Biy7R9LfumYshur3YKhpj56MpB.jpg","it":"https://image.tmdb.org/t/p/w500/reQUXXUd0WeoIJiSvYjlGLRGpXR.jpg","es":"https://image.tmdb.org/t/p/w500/qlgvS2InG3oU8GixavRq3t3A9H7.jpg","de":"https://image.tmdb.org/t/p/w500/5YaxrCqAQ482jCixgT3PIdvf7tg.jpg","fr":"https://image.tmdb.org/t/p/w500/o7PGnP8gSLjYdN2OQH4y45Ymi4i.jpg"}'::jsonb WHERE id = 328;
UPDATE public.films SET tmdb_id = 921, titoli_i18n = '{"it":"Cinderella Man - Una ragione per lottare","fr":"De l''ombre à la lumière","es":"Cinderella Man. El hombre que no se dejó tumbar","en":"Cinderella Man","de":"Das Comeback"}'::jsonb, trame_i18n = '{"it":"Ispirato alla vera storia del pugile Jim Braddock che, nel periodo della Grande Depressione, per sfamare la famiglia tentò la fortuna con la boxe. Braddock passò velocemente dalla miseria alla gloria quando, nel 1935, riuscì a battere in un combattimento epico di 15 riprese il campione del mondo dei pesi massimi Max Baer.","fr":"Autrefois boxeur prometteur, Jim Braddock s''est vu contraint d''abandonner la compétition après une série de défaites. Alors que l''Amérique sombre dans la `Grande Dépression'', Jim accepte n''importe quel petit boulot pour faire vivre sa femme Mae et leurs enfants. Il n''abandonne pourtant pas l''espoir de remonter un jour sur le ring. Grâce à une annulation de dernière minute, Jim est appelé à combattre le deuxième challenger mondial, à la stupéfaction générale il gagne au troisième round.","es":"Basada en una historia real. Después de haberse retirado del boxeo, James J. Braddock decidió volver al cuadrilátero durante los años de la Gran Depresión para poder alimentar a su familia. No era un boxeador con talento, pero su coraje, sacrificio y dignidad lo llevaron hasta la cumbre.","en":"The true story of boxer Jim Braddock who, following his retirement in the 1930s, makes a surprise comeback in order to lift his family out of poverty.","de":"Nachdem er etliche Kämpfe hintereinander verloren hat, sieht der Halbschwergewicht-Boxer Jim Braddock keinen anderen Ausweg mehr: Er hört auf, in den Ring zu steigen und muss sich von nun an mit mickrigen Jobs begnügen, damit er, seine Frau Mae und seine Kinder über die Runden kommen.Eines Tages allerdings hat er die Chance zu seinem großen Comeback, als ein anderer Boxer einen Kampf absagen muss und Jim für ihn den Ring zurückkehrt. Hingegen aller Erwartungen gewinnt er den Kampf und wird so zum Held. Doch sein nächster Gegner wird nicht so einfach zu besiegen sein. Das Schwergewicht Max Baer stieg nämlich schon zweimal als einziger Überlebender aus dem Ring..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/6TeNVIUGkCh9ZaTysb94Blhbram.jpg","fr":"https://image.tmdb.org/t/p/w500/3WFqefpOIBmj6kqZ5zvnZw8Dy6M.jpg","es":"https://image.tmdb.org/t/p/w500/9qJlfL3fB5d8MotO4kUtDgH4Yr8.jpg","en":"https://image.tmdb.org/t/p/w500/wkeOjIcpuqLMW4GnVowlM9VI0JE.jpg","de":"https://image.tmdb.org/t/p/w500/fUfgrFi5qBVDIHsntX1E3TAehzq.jpg"}'::jsonb WHERE id = 329;
UPDATE public.films SET tmdb_id = 59, titoli_i18n = '{"it":"A History of Violence","de":"A History of Violence","fr":"A History of Violence","en":"A History of Violence","es":"Una historia de violencia"}'::jsonb, trame_i18n = '{"it":"Tom Stall è il proprietario di un piccolo ristorante in una cittadina di provincia. Conduce una vita normale con la moglie e i figli fin quando un giorno si difende dall''aggressione di due feroci criminali uccidendo entrambi. La sua immagine finisce su tutti i media e spinge Carl Fogarty, un boss della mafia irlandese di Philadelpia ad andarlo a cercare.","de":"Tom Stall, seine Frau Edie und seine zwei Kinder leben ein normales Leben in ihrem Kleinstadthaus in Millbrock, Indiana. Eines Tages jedoch wird die Familie auf eine harte Belastungsprobe gestellt.Alles beginnt mit zwei Männern, die in den Coffeeshop von Tom kommen und den Laden überfallen wollen. Damit keine unschuldige Person verletzt wird, erschießt Tom die beiden in Notwehr und wird durch diese Tat zu einem Helden in der Stadt. Auch die Presse feiert ihn, was er selbst aber eigentlich nicht möchte, sondern lieber, dass alle ihn sein geregeltes Leben weiterführen lassen. Als sich die Schlagzeilen wieder etwas legen, steht der undurchschaubare Carl Fogarty vor seiner Tür. Carl macht ihm unmissverständlich klar, dass seine letzte Stunde geschlagen hat, da er schon lange mit einem gewissen \"Joey\", für den er ihn hält, abrechnen will. Tom setzt nun alles daran, Carl davon zu überzeugen, dass er nicht Joey ist...","fr":"Père de famille dans une petite ville tranquille, Tom Stall est un jour contraint de tuer deux malfrats qui menaçaient la vie des employés et des clients de son restaurant. Proclamé héros par la presse locale, Tom essaie peu à peu de revenir à une vie normale. Mais un certain Carl Fogarty débarque, convaincu de reconnaître en Tom celui avec qui il a autrefois eu de violents démêlés.","en":"An average family is thrust into the spotlight after the father commits a seemingly self-defense murder at his diner.","es":"Tom Stall lleva una vida feliz y tranquila con su mujer –abogada– y sus dos hijos en la pequeña ciudad de Millbrook (Indiana) hasta que una noche su existencia idílica se ve destrozada cuando frustra un violento intento de robo en su restaurante. Tom percibe el peligro y salva a sus clientes y amigos matando en defensa propia a dos criminales buscados por la justicia. Aplaudido como un héroe, la vida de Tom cambia de la noche a la mañana y de repente se encuentra convertido en el centro de atención de todos los medios de comunicación. Incómodo con esta fama no buscada, intenta volver a su vida normal, pero un hombre amenazante y misterioso llega a la ciudad para enfrentarse a él porque cree que Tom es el hombre con quien tiene una cuenta pendiente del pasado."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hZRFgghyOvYkFZ6dtPtPQ97KXLg.jpg","de":"https://image.tmdb.org/t/p/w500/tYn6WVRwTyvK7B6LA6n1aU74LnB.jpg","fr":"https://image.tmdb.org/t/p/w500/A26rcvipOqptVs7i5uRmKicXRxE.jpg","en":"https://image.tmdb.org/t/p/w500/ptJKY9WGDUUL064ge3jW78zBX0t.jpg","es":"https://image.tmdb.org/t/p/w500/rZLpsfxj2qKbJzSzXiKFYrRIeB1.jpg"}'::jsonb WHERE id = 330;
UPDATE public.films SET tmdb_id = 116, titoli_i18n = '{"en":"Match Point","de":"Match Point","es":"Match Point","it":"Match Point","fr":"Match Point"}'::jsonb, trame_i18n = '{"en":"Chris, a former tennis pro, takes a job as an instructor and befriends his wealthy young student, Tom. After being introduced to his family, Chris is soon engaged to Tom''s sister, Chloe. Despite the professional and financial advantages that this relationship affords him, Chris becomes obsessed with Tom''s fiancee, American actress Nola.","de":"Chris Wilton ist jung, gut aussehend und ehrgeizig. Mit der ganz großen Tenniskarriere hat es nicht geklappt, und so verdient er sich jetzt seine Brötchen als Tennislehrer in einem feinen Londoner Club. Als er hier die Bekanntschaft des reichen Snobs Tom und dessen schüchternen Schwester Chloe macht, sieht er seine ganz große Chance gekommen, seinem Leben doch noch die entscheidende Wendung nach oben zu geben.","es":"Chris Wilton es un ambicioso y joven profesor de tenis con escasos recursos económicos. Gracias a su amistad con Tom Hewett, consigue entrar en la alta sociedad londinense y enamorar a su hermana Chloe. Tom, por su parte, sale con Nola Rice, una atractiva americana, de la que Chris se encapricha nada más verla. El azar, la pasión y, sobre todo, la ambición llevarán a Chris a cometer acciones que determinarán su vida y la de los demás para siempre.","it":"L''ascesa al successo del giovane e ambizioso istruttore di tennis Chris Wilton sembra inarrestabile, grazie anche alla conquista di due donne belle e potenti che se lo contenderanno.","fr":"Jeune professeur de tennis issu d''un milieu modeste, Chris Wilton se fait embaucher dans un club huppé des beaux quartiers de Londres. Il ne tarde pas à sympathiser avec Tom Hewett, un jeune homme de la haute société avec qui il partage sa passion pour l''opéra. Très vite, Chris fréquente régulièrement les Hewett et séduit Chloe, la sœur de Tom. Alors qu''il s''apprête à l''épouser et qu''il voit sa situation sociale se métamorphoser, il fait la connaissance de la ravissante fiancée de Tom, Nola Rice, une jeune Américaine venue tenter sa chance comme comédienne en Angleterre..."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/vHjEVTD8ucuwKSFOZJeyAnTZYli.jpg","de":"https://image.tmdb.org/t/p/w500/bOK3J1TMfYZjlM86jBoVTgcIeVz.jpg","es":"https://image.tmdb.org/t/p/w500/4JJr9zvDxys2f7dOlDdDgEsw9Yy.jpg","it":"https://image.tmdb.org/t/p/w500/vHjEVTD8ucuwKSFOZJeyAnTZYli.jpg","fr":"https://image.tmdb.org/t/p/w500/vHjEVTD8ucuwKSFOZJeyAnTZYli.jpg"}'::jsonb WHERE id = 331;
UPDATE public.films SET tmdb_id = 866, titoli_i18n = '{"fr":"Neverland","es":"Descubriendo Nunca Jamás","it":"Neverland - Un sogno per la vita","de":"Wenn Träume fliegen lernen","en":"Finding Neverland"}'::jsonb, trame_i18n = '{"fr":"Londres au début du XXe siècle, J. M. Barrie auteur de pièces de théâtre est en manque d’inspiration. Son mariage ne va pas bien, sa dernière pièce est un désastre. Mais alors qu’il est dans le parc avec son chien Porthos, il rencontre Mme Sylvia Llewelyn Davies, qui est veuve, et ses 4 garçons. Une amitié très forte naît entre J. M. Barrie, les 4 enfants et leur mère.","es":"Basada en la vida de James Barrie, el autor \"Peter Pan\". La historia comienza en Londres en 1904 y muestra el proceso que desembocó en la creación de Peter Pan, desde que a Barrie se le ocurrió la idea hasta el estreno de la obra en el teatro Duke de Nueva York, una noche en la que no sólo cambió la vida del autor, sino la de todos los que estaban con él.","it":"L’affermato drammaturgo scozzese James M. Barrie è un genio letterario dei suoi tempi ma non ne può più dei soliti vecchi temi. Inaspettatamente, trova ispirazione durante la passeggiata che fa ogni giorno per i giardini di Kensington. Lì incontra la famiglia Llewelyn Davies, quattro bambini orfani di padre e la loro bella madre. Nonostante la disapprovazione della nonna dei bambini e il risentimento di sua moglie, Barrie fa amicizia con la famiglia. Trasforma i ragazzi nei “ragazzi perduti dell’isola che non c’è”. Dalle avventure elettrizzanti dell’infanzia scaturisce il capolavoro di Barrie, Peter Pan. Al principio, la sua compagnia teatrale è scettica ma Barrie scioccherà gli attori facendoli provare con delle richieste mai sentite. Una tragica piega del destino, però, costringerà lo scrittore e le persone che ama a capire cosa davvero significa credere...","de":"London, Anfang des 19. Jahrhunderts. Auf der Suche nach Inspiration stolpert der schottische Bühnenautor J.M. Barrie im Park über eine vierköpfige Jungen-Bande, die von ihrer bezaubernden Mutter Sylvia begleitet wird. Auf Anhieb findet Barrie einen Draht zu den wilden, abenteuerlustigen Buben; Peter, der jüngste Spross, wird gar das Vorbild zu Peter Pan. Doch während beruflich alles nach Plan läuft - \"Peter Pan\" wird ein sensationeller Erfolg -, geht Barries Ehe in die Brüche, und Sylvia erkrankt unheilbar an Krebs.","en":"During a writing slump, playwright J.M. Barrie meets a widow and her four children, all young boys—who soon become an important part of Barrie’s life and the inspiration that lead him to create his masterpiece. Peter Pan."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/z1DKo16vog6RAlwqV7ERqiYMCUU.jpg","es":"https://image.tmdb.org/t/p/w500/ibdzSgStiFFXXnQc3WsMrNqv0wt.jpg","it":"https://image.tmdb.org/t/p/w500/fqfx3dcYzfK6sQVRQYn9siNzBuX.jpg","de":"https://image.tmdb.org/t/p/w500/3ErdhYRrDl7uQ9xFOvP97LzHZ3D.jpg","en":"https://image.tmdb.org/t/p/w500/A9jgLICNCEb3lvWdNaIKAG9pRdp.jpg"}'::jsonb WHERE id = 332;
UPDATE public.films SET tmdb_id = 70, titoli_i18n = '{"en":"Million Dollar Baby","de":"Million Dollar Baby","it":"Million Dollar Baby","fr":"Million Dollar Baby","es":"Million Dollar Baby"}'::jsonb, trame_i18n = '{"en":"Despondent over a painful estrangement from his daughter, trainer Frankie Dunn isn''t prepared for boxer Maggie Fitzgerald to enter his life. But Maggie''s determined to go pro and to convince Dunn and his cohort to help her.","de":"Frankie Dunn hat sein Leben lang viele unglaubliche Kämpfer im Ring trainiert. Die wichtigste Regel, die er seine Boxer lehrt, ist die, die sein eigenes Leben bestimmt: Vor allem andere, schütze dich selbst! Im Zuge einer schmerzvollen Entfremdung von seiner Tochter hat Frankie niemanden mehr an sich herangelassen. Sein einziger Freund ist Scrap, ein ehemaliger Boxer, der sich um das Studio kümmert und weiß, dass unter Frankies rauher Schale ein warmherziger Kerl steckt.","it":"Maggie Fitzgerald fa la cameriera, ha passato i trent''anni ma ancora sogna di affermarsi come boxeuse, e ha anche incontrato l''allenatore che fa al caso suo. Peccato che Frankie Dunn non voglia saperne di allenare una donna...","fr":"Rejeté depuis longtemps par sa fille, l’entraîneur Frankie Dunn s’est replié sur lui‐même et vit dans un désert affectif, en évitant toute relation qui pourrait accroître sa douleur et sa culpabilité. Le jour où Maggie Fitzgerald, 31 ans, pousse la porte de son gymnase à la recherche d’un coach, elle n’amène pas seulement avec elle sa jeunesse et sa force, mais aussi une histoire jalonnée d’épreuves et une exigence, vitale et urgente : monter sur le ring, entraînée par Frankie, et enfin concrétiser le rêve d’une vie. Après avoir repoussé plusieurs fois sa demande, Frankie se laisse convaincre par l’inflexible détermination de la jeune femme. Une relation mouvementée, tour à tour stimulante et exaspérante, se noue entre eux, au fil de laquelle Maggie et l’entraîneur se découvrent une communauté d’esprit et une complicité inattendues…","es":"Frankie Dunn, después de haber entrenado y representado a los mejores púgiles, regenta un gimnasio con la ayuda de Scrap, un ex-boxeador que, además, es su único amigo. Frankie es un hombre solitario y adusto que se refugia desde hace años en la religión buscando una redención que no llega. Un día, entra en su gimnasio Maggie Fitzgerald, una voluntariosa chica que quiere boxear y que está dispuesta a luchar denodadamente para conseguirlo. Pero lo que más desea y necesita es que alguien crea en ella. Frankie la rechaza alegando que es demasiado mayor y que, además, él no entrena a chicas. Pero Maggie no se rinde y se machaca cada día en el gimnasio, con el único apoyo de Scrap. Finalmente, convencido de la inquebrantable determinación de Maggie, Frankie decide entrenarla."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/jcfEqKdWF1zeyvECPqp3mkWLct2.jpg","de":"https://image.tmdb.org/t/p/w500/h91jhpl63wxNGNl18adInAsn3YV.jpg","it":"https://image.tmdb.org/t/p/w500/3ehWHEKe54gTpYoTZ19q2qRCCyH.jpg","fr":"https://image.tmdb.org/t/p/w500/7yWwlgq12qZ4nMLQHhEf8ITaggn.jpg","es":"https://image.tmdb.org/t/p/w500/3mNb5EaO5HfgrxZGx917c8kNp6E.jpg"}'::jsonb WHERE id = 333;
UPDATE public.films SET tmdb_id = 652, titoli_i18n = '{"en":"Troy","es":"Troya","de":"Troja","fr":"Troie","it":"Troy"}'::jsonb, trame_i18n = '{"en":"In year 1250 B.C. during the late Bronze age, two emerging nations begin to clash. Paris, the Trojan prince, convinces Helen, Queen of Sparta, to leave her husband Menelaus, and sail with him back to Troy. After Menelaus finds out that his wife was taken by the Trojans, he asks his brother Agamemnon to help him get her back. Agamemnon sees this as an opportunity for power. They set off with 1,000 ships holding 50,000 Greeks to Troy.","es":"A lo largo de los tiempos, los hombres han hecho la guerra. Unos por poder, otros por gloria o por honor, y algunos por amor. En la antigua Grecia, la pasión de dos de los amantes más legendarios de la historia, Paris, príncipe de Troya y Helena, reina de Esparta, desencadena una guerra que asolará una civilización. El rapto de Helena por Paris, separándola de su esposo, el rey Menelao, es un insulto que El orgullo familiar establece que una afrenta a Menelao es una afrenta a su hermano Agamenón, el poderoso rey de Micenas, que no tarda en reunir a todas las grandes tribus de Grecia para recuperar a Helena de manos de los troyanos y defender el honor de su hermano. La verdad es que la lucha por el honor por parte de Agamenón está corrompida por su incontenible codicia ya que necesita conquistar Troya para asumir el control del mar Egeo.","de":"Paris, der schwer verliebte Prinz von Troja, verschleppt die spartanische Königsgemahlin Helena in seine Heimat. Der spartanische König Menelaos kann diese Beleidigung nicht hinnehmen. Unter der Leitung seines Bruders Agamemnon, dem mächtigen König von Mykene, schließen sich weitere griechische Könige zusammen, um Troja zu vernichten, darunter auch der berühmteste Krieger Achilles. Das Hauptmotiv von Agamemnon ist nicht die Ehre seines Bruders wiederherzustellen, sondern seine Habgier: der Fall von Troja würde für ihn einen großen Sieg bedeuten und die Vorherrschaft seines bereits riesigen Reiches sichern. Unter der Führung des gewaltigen Prinz Hektor halten aber Trojas Mauern besser stand als von den Griechen geplant…","fr":"Dans la Grèce antique, l''enlèvement d''Hélène, reine de Sparte, par Pâris, prince de Troie, est une insulte que le roi Ménélas ne peut supporter. L''honneur familial étant en jeu, Agamemnon, frère de Ménélas et puissant roi de Mycènes, réunit toutes les armées grecques afin de faire sortir Hélène de Troie. Mais en réalité, la sauvegarde de l''honneur familial n''est qu''un prétexte pris par Agamemnon pour cacher sa terrible avidité. Celui-ci cherche en fait à contrôler Troie et à agrandir son vaste empire. Aucune armée n''a jamais réussi à pénétrer dans la cité fortifiée, sur laquelle veillent le roi Priam et le prince Hector. L''issue de la guerre de Troie dépendra notamment d''un homme, Achille, connu comme le plus grand guerrier de son époque. Arrogant, rebelle, et réputé invincible, celui-ci n''a d''attache pour rien ni personne si ce n''est sa propre gloire…","it":"Nel 1193 A.C., Paride, principe di Troia, rapisce Elena, regina di Sparta e moglie di Menelao. Questo sarŕ l''evento che scatenerŕ la guerra tra la Grecia micenea e Troia, una guerra lunga dieci anni che vedrà protagonisti due eroi contrapposti: Achille per i greci ed Ettore per i troiani."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/a07wLy4ONfpsjnBqMwhlWTJTcm.jpg","es":"https://image.tmdb.org/t/p/w500/mBiDQT28DnuYaJSL4nDD43ORE6p.jpg","de":"https://image.tmdb.org/t/p/w500/3Mt64xsMF88cRz08ysJLLV2Qhws.jpg","fr":"https://image.tmdb.org/t/p/w500/pkKBYrihVm5kuBgOH04KagSids0.jpg","it":"https://image.tmdb.org/t/p/w500/6n8BiphW9fvqC6biB0RMfblqi43.jpg"}'::jsonb WHERE id = 334;
UPDATE public.films SET tmdb_id = 1586, titoli_i18n = '{"es":"La ventana secreta","en":"Secret Window","it":"Secret Window","fr":"Fenêtre secrète","de":"Das geheime Fenster"}'::jsonb, trame_i18n = '{"es":"Thriller basado en una novela de Stephen King. Depp es un escritor que atraviesa un mal momento: a la sequía creativa se une el proceso de separación de su esposa. En tales circunstancias, aparece en su vida un extraño personaje que lo acusa de haber plagiado uno de sus relatos.","en":"Mort Rainey, a writer just emerging from a painful divorce with his ex-wife, is stalked at his remote lake house by a psychotic stranger and would-be scribe who claims Rainey swiped his best story idea. But as Rainey endeavors to prove his innocence, he begins to question his own sanity.","it":"Da quando la moglie lo ha lasciato il famoso romanziere Mort Rainey è in preda ad una forte depressione e trascorre le giornate a dormire anziché a scrivere. A peggiorare le cose arriva uno psicopatico che lo accusa di aver plagiato un suo racconto. Per vendicarsi è disposto a tutto. Persino ad uccidere.","fr":"Mort Rainey, un écrivain frappé du syndrome de la page blanche, est harcelé par un dangereux psychopathe. Ce dernier l''accuse d''avoir plagié son histoire et demande réparation. Malgré les efforts de Rainey pour le calmer, l''individu devient de plus en plus vindicatif.","de":"Der Schriftsteller Mort Rainey hatte auch schon einmal bessere Zeiten. Erst erwischt er seine Frau Amy beim Seitensprung, dann taucht der mysteriöse Shooter auf und bezichtigt Mort des Plagiats. Shooter behauptet, dass Mort seinen Roman „Das geheime Fenster“ abgeschrieben hat. Was Mort zunächst für einen Witz hält, den er schnell aufklären kann, wird nach und nach durch unheimliche Ereignisse zur Realität. Denn so sehr Mort auch versucht, eine Kopie seines Buches zu beschaffen, welches seine Unschuld beweisen könnte, es misslingt ihm ständig. Und Shooter hat ihm ein Ultimatum von drei Tagen gestellt."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/tNPnEp91xKShOIGh1VJgAIXIGT9.jpg","en":"https://image.tmdb.org/t/p/w500/hvzw4wufKZkDCTPVeG71Z7pGfZh.jpg","it":"https://image.tmdb.org/t/p/w500/5NpdcGLZuk6AgpVrAN2f4Vmw0Yr.jpg","fr":"https://image.tmdb.org/t/p/w500/mOLEDcCD3qh4jWeuwPxCEZWRW7J.jpg","de":"https://image.tmdb.org/t/p/w500/5dc63yS1CIKyMWrlTlqDqx4pja9.jpg"}'::jsonb WHERE id = 335;
UPDATE public.films SET tmdb_id = 322, titoli_i18n = '{"fr":"Mystic River","en":"Mystic River","es":"Mystic River","de":"Mystic River","it":"Mystic River"}'::jsonb, trame_i18n = '{"fr":"Jimmy Markum, Dave Boyle et Sean Devine ont grandi ensemble dans les rues de Boston. Rien ne semblait devoir altérer le cours de leur amitié jusqu''au jour où Dave se fit enlever par un inconnu sous les yeux de ses amis. Leur complicité juvénile ne résista pas à un tel événement et leurs chemins se séparèrent inéluctablement. Jimmy sombra pendant quelque temps dans la délinquance, Sean s''engagea dans la police, Dave se replia sur lui-même, se contenta de petits boulots et vécut durant plusieurs années avec sa mère avant d''épouser Celeste. Une nouvelle tragédie rapproche soudain les trois hommes : Katie, la fille de Jimmy, est retrouvée morte au fond d''un fossé. Le père endeuillé ne rêve plus que d''une chose : se venger. Et Sean, affecté à l''enquête, croit connaître le coupable : Dave Boyle...","en":"The lives of three men who were childhood friends are shattered when one of them suffers a family tragedy.","es":"Cuando Jimmy Markum, Dave Boyle y Sean Devine eran unos niños que crecían juntos en un peligroso barrio obrero de Boston, pasaban los días jugando al hockey en la calle. Pero, un día, a Dave le ocurrió algo que marcó para siempre su vida y las de sus amigos. Veinticinco años más tarde, otra tragedia los vuelve a unir: el asesinato de Katie, la hija de 19 años de Jimmy. A Sean, que es policía, le asignan el caso; pero también tiene que estar muy pendiente de Jimmy porque, en su desesperación, está intentando tomarse la justicia por su mano.","de":"Einst waren sie Jugendfreunde, Jimmy, Sean und Davey, bis ein Verbrechen alles zerstörte. Zwei Männer, die sich als Polizisten ausgeben, entführen eines Tages Davey und missbrauchen ihn daraufhin tagelang, bis er schließlich entkommen kann.30 Jahre später ist nichts davon vergessen, die Wunden sind vernarbt, aber sie schmerzen noch. Jimmy ist nach einer Gefängnisstrafe jetzt ruhiger geworden, verheiratet und Vater zweier Töchter. Davey leidet, trotz glücklicher Ehe immer noch unter den Ereignissen von damals, während Sean inzwischen Polizist geworden ist.Als Jimmys ältere Tochter Opfer eines brutalen Verbrechens wird, nutzt Sean seine beruflichen Kompetenzen für einen privaten Rachefeldzug, in den auch seine immer noch mit ihm verbundenen Freunde mit hineingezogen werden...","it":"Da ragazzini Jimmy Marcus, Sean Devine e Dave Boyle erano inseparabili. Ora, a distanza di molto tempo, i tre si ritrovano in occasione di un tragico evento: la morte della prima figlia di Jimmy. Sean, che fa il poliziotto, indaga sul fatto..."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/1z7IwJBQSKVY7BPLYOOS3ZNWM53.jpg","en":"https://image.tmdb.org/t/p/w500/hCHVDbo6XJGj3r2i4hVjKhE0GKF.jpg","es":"https://image.tmdb.org/t/p/w500/b6j7T4uBjXdG8FBMuDFsHttgIK2.jpg","de":"https://image.tmdb.org/t/p/w500/e2VNohx5jb7I6HUamCuGhKvzXDR.jpg","it":"https://image.tmdb.org/t/p/w500/3D5VS7oWduCmwNLNmRClqGKOgZa.jpg"}'::jsonb WHERE id = 336;
UPDATE public.films SET tmdb_id = 615, titoli_i18n = '{"en":"The Passion of the Christ","de":"Die Passion Christi","it":"La passione di Cristo","fr":"La Passion du Christ","es":"La pasión de Cristo"}'::jsonb, trame_i18n = '{"en":"A graphic portrayal of the last twelve hours of Jesus of Nazareth''s life.","de":"In \"Die Passion Christi\" werden die letzten zwölf Stunden im Leben von Jesus von Nazareth erzählt. Judas, einer seiner Jünger, verrät Jesus nach dem letzten Abendmahl an die pharisäischen Hohepriester, die den Prediger daraufhin gefangen nehmen. Die Hohepriester - allen voran deren Anführer Kaiphas - fürchten durch Jesus ihren gesellschaftlichen Status zu verlieren, beschuldigen ihn daher der Gotteslästerung und verlangen seinen Tod. Doch weder der römische Statthalter Pontius Pilatus, der erkennt, dass es sich bei den Anschuldigungen um eine politische Intrige handelt, noch König Herodes sind gewillt, das Todesurteil zu besiegeln...","it":"Le ultime dodici ore di vita di Gesù, dall''orto degli ulivi, all''arresto e la condanna a morte. La decisione di Ponzio Pilato di affidare la scelta alla folla, la flagellazione e, infine, la crocifissione.","fr":"Les douze dernières heures de la vie du Christ. Rendu au Mont des Oliviers, Jésus prie après avoir partagé un dernier repas avec ses apôtres. Il résiste maintenant aux tentations de Satan. Trahi par Judas, Jésus est arrêté et emmené à Jérusalem, où les chefs des Pharisiens l''accusent de blasphème et lui font un procès qui a pour issue sa condamnation à mort…","es":"Año 33 de nuestra era. En la provincia romana de Judea, un misterioso carpintero llamado Jesús de Nazareth comienza a anunciar la llegada del \"reino de Dios\" y se rodea de un grupo de humildes pescadores: los Apóstoles. Durante siglos, el pueblo judío había esperado la llegada del Mesías - personaje providencial que liberaría su sagrada patria e instauraría un nuevo orden basado en la justicia-. Las enseñanzas de Jesús atraen a una gran multitud de seguidores que lo reconocen como el Mesías. Alarmado por la situación, el Sanedrín, con la ayuda de Judas Iscariote, uno de los doce Apóstoles, arresta a Jesús. Acusado de traición a Roma, Cristo es entregado a Poncio Pilato, quien, para evitar un motín, lo condena a a morir en la cruz como un vulgar criminal."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/rBM5o2HpmCfDejuIPybI09tkY3V.jpg","de":"https://image.tmdb.org/t/p/w500/4vtMNmeBHrxFMlV39HyLW6jOrhn.jpg","it":"https://image.tmdb.org/t/p/w500/arQvRafRtfyEQqBZ4qAjuYuYsyo.jpg","fr":"https://image.tmdb.org/t/p/w500/nVjopQNIWFGQ4Kk73QxAeIw6xov.jpg","es":"https://image.tmdb.org/t/p/w500/qPSyfz3yzTHXh1s8KRNy5YMNQJL.jpg"}'::jsonb WHERE id = 337;
UPDATE public.films SET tmdb_id = 640, titoli_i18n = '{"en":"Catch Me If You Can","fr":"Arrête-moi si tu peux","de":"Catch Me If You Can","es":"Atrápame si puedes","it":"Prova a prendermi"}'::jsonb, trame_i18n = '{"en":"A true story about Frank Abagnale Jr. who, before his 19th birthday, successfully conned millions of dollars worth of checks as a Pan Am pilot, doctor, and legal prosecutor. An FBI agent makes it his mission to put him behind bars. But Frank not only eludes capture, he revels in the pursuit.","fr":"Dans les années soixante, le jeune Frank Abagnale Jr. est passé maître dans l’art de l’escroquerie, allant jusqu’à détourner 2,5 millions de dollars et à figurer sur les listes du FBI comme l’un des dix individus les plus recherchés des États‐Unis. Véritable caméléon, Frank revêt des identités aussi diverses que celles de pilote de ligne, de médecin, de professeur d’université ou encore d’assistant du procureur. Carl Hanratty, agent du FBI à l’apparence stricte, fait de la traque de Frank Abagnale Jr. sa mission prioritaire, mais ce dernier reste pendant longtemps insaisissable…","de":"Frank W. Abagnale war nicht nur als Arzt und Rechtsanwalt erfolgreich, sondern auch als Copilot einer großen Fluglinie. Das alles erreichte er vor seinem 21. Geburtstag. Er ist ein Meister der Täuschung, aber auch ein brillanter Fälscher. Durch geschickte Scheckbetrügereien ist er zu einem Vermögen von mehreren Millionen Dollar gekommen. FBI-Agent Carl Hanratty hat ihn schon länger im Visier und macht sich zur Aufgabe, Frank zu fassen und vor Gericht zu bringen. Frank ist ihm jedoch immer einen Schritt voraus und macht sich einen Spaß daraus, seinem Verfolger kleine Köder vorzuwerfen, damit die Jagd weiter geht…","es":"Frank Abagnale Jr. trabajó como médico, abogado y copiloto de una de las grandes líneas aéreas, todo ello antes de cumplir los dieciocho años. También fue un genial falsificador y sus habilidades le otorgaron una plaza en la historia. A la edad de 17 años, Frank Abagnale Jr. se convirtió en el ladrón de bancos de más éxito en la historia de Estados Unidos. El agente del FBI Carl Hanratty dedicó la mayor parte de su tiempo a perseguir a Frank para llevarle ante la justicia, pero Frank siempre estaba un paso por delante, retándole a continuar la caza.","it":"Frank W. Abagnale Jr. è il tipico ragazzo americano di buona famiglia degli anni ''60. Ma l''improvviso dissesto finanziario del padre e il divorzio dei genitori lo costringono ad andarsene di casa. Ma come sbarcare il lunario? Ad esempio ottenendo una divisa da pilota Pan Am, falsificando assegni della compagnia aerea e comprandosi una macchina marcatrice per alterare i numeri degli stessi. In poco tempo Frank, che cambia identità più velocemente dei propri abiti, diventa una delle priorità dell''Fbi ed in particolare dell''agente Hanratty, esperto in frodi bancarie e come il suo antagonista solo al mondo."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/ctjEj2xM32OvBXCq8zAdK3ZrsAj.jpg","fr":"https://image.tmdb.org/t/p/w500/nafyoqVGi87AwaV51GSJ0pk97gs.jpg","de":"https://image.tmdb.org/t/p/w500/bJLrws4RmIw6UdXQJ6Ok4UOvKo0.jpg","es":"https://image.tmdb.org/t/p/w500/WboEhiMlCsy4l2u2BweerHCLFa.jpg","it":"https://image.tmdb.org/t/p/w500/j0Ab2kETKLFISnddShJA6LffxuO.jpg"}'::jsonb WHERE id = 338;
UPDATE public.films SET tmdb_id = 3131, titoli_i18n = '{"it":"Gangs of New York","es":"Gangs of New York","fr":"Gangs of New York","de":"Gangs of New York","en":"Gangs of New York"}'::jsonb, trame_i18n = '{"it":"New York, 1846. Nel quartiere di Five Points una cruenta battaglia tra gang sancisce il trionfo di William Cutting - detto Billy the Butcher, capo dei nativi americani - e la morte di Padre Vallon, protettore degli emigranti. Sedici anni dopo il figlio di questi, Amsterdam, esce dal riformatorio fermamente deciso a ingraziarsi l’assassino di suo padre per poi ottenere vendetta. Conosciuto Billy, Amsterdam ne viene in pratica adottato e arriva a salvargli la vita. Una volta scoperto e sfigurato, si risolverà a combattere apertamente contro di lui, ma sono gli anni della Guerra Civile: l’ultimo scontro tra le gang sarà decisamente superato in violenza e ferocia dall’intervento delle truppe inviate a far rispettare la coscrizione obbligatoria.","es":"New York City, 1863. Antes de la ciudad que conocemos hoy, llena de riqueza, poder y sueños infinitos, New York era un lugar diferente, una ciudad naciente donde el deseo por una vida mejor enfurecía a su gente y generaba violencia en las calles. Mientras la superviviencia del país se debatía en la Guerra Civil, un vasto y peligroso grupo de personas crecía en el bajo mundo. Pero en la joven y naciente ciudad, llegaba el momento de luchar contra los despiadados, contra la intolerancia y el miedo. Había llegado el momento del extraordinario valor de aquellos que impulsaron al borde de la lucha la libertad de futuras generaciones.","fr":"En 1846, le quartier de Five Points, un faubourg pauvre de New York, est le théâtre d''une guerre des gangs entre émigrants irlandais d''un côté, les Dead Rabbits menés par Père Vallon, et les Native Americans de l''autre, dirigés par le sanguinaire Bill le Boucher. Ce dernier met rapidement en déroute les Dead Rabbits en assassinant leur chef, et prend par la même occasion le contrôle exclusif des rues de la \"grosse pomme\". Afin de renforcer ses pouvoirs, Bill s''allie avec Boss Tweed, un politicien influent. Seize ans plus tard, le gang des Native Americans règne toujours en maître dans New York. Devenu adulte, Amsterdam Vallon souhaite venger la mort de son père en éliminant Bill. Mais sa rencontre avec Jenny Everdeane, une énigmatique pickpocket dont l''indépendance et la beauté le fascinent, va compliquer les choses...","de":"1846, New York, das Viertel Five Points: immer wieder kommt es zu blutigen Unruhen zwischen den „Gangs“ des Viertels, zwischen irisch-katholischen Immigranten und den übrigen protestantischen Einwohnern. In einem mörderischen Zweikampf ermordet „Bill The Butcher“ Cutting seinen Gegenüber Vallon. Sein Sohn Amsterdam taucht unter, um 1862 wieder im Viertel zu erscheinen, das inzwischen unter Bills Kontrolle steht. Cutting beginnt ein Vater-Sohn-Verhältnis mit Amsterdam, der Rache für seinen Vater will. Doch in Bills Nähe findet er auch eine ganz besondere Frau, Jenny Everdeane…","en":"In early 1860s New York, Irish immigrant Amsterdam Vallon is released from prison and returns to the Five Points, seeking revenge against his father''s killer, William Cutting, a powerful anti-immigrant gang leader. He knows that revenge can only be attained by infiltrating Cutting''s inner circle. Vallon''s journey becomes a fight for personal survival and to find a place for the Irish people."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zaUzyruncix1oAQLlaG0Q8WQBbY.jpg","es":"https://image.tmdb.org/t/p/w500/gB7aaHAT1yEj49beaII6pudpode.jpg","fr":"https://image.tmdb.org/t/p/w500/UYbOQyJkfHWejmIq0k10hPb7w8.jpg","de":"https://image.tmdb.org/t/p/w500/2zJnUob8XfVxuZUFDsZF3bkPvuk.jpg","en":"https://image.tmdb.org/t/p/w500/lemqKtcCuAano5aqrzxYiKC8kkn.jpg"}'::jsonb WHERE id = 339;
UPDATE public.films SET tmdb_id = 2675, titoli_i18n = '{"es":"Señales","it":"Signs","fr":"Signes","en":"Signs","de":"Signs - Zeichen"}'::jsonb, trame_i18n = '{"es":"Graham Hess es un pastor protestante que vive con sus dos hijos y con su hermano, Merrill, una antigua estrella del béisbol que trabaja en una gasolinera. Tras la muerte de su esposa en un accidente de tráfico, Graham pierde la fe y, en consecuencia, abandona a sus feligreses. Una mañana, al despertarse, se encuentra con que sus hijos han hecho un descubrimiento escalofriante en los campos de maíz que rodean su granja.","it":"Il reverendo Graham Hess vive a Bucks County in Pennsylvania con i suoi due figlioletti e il fratello un po’ svanito. Sua moglie è morta in un incidente e da quel momento l’uomo ha perso la fede. Un giorno scopre degli ampi cerchi tracciati nei campi intorno alla sua fattoria. Il fenomeno si manifesta anche in India e, successivamente, in tutto il mondo. E’ opera di alieni particolarmente pericolosi e abili nel non farsi individuare. Qualcuno di loro si muove anche nei pressi della fattoria. Graham riuscirà a venire a capo del mistero. M. Night Shyamalan si muove con sicurezza nel territorio del paranormale e del contatto con gli alieni.","fr":"À Bucks County, en Pennsylvanie. Après la perte de sa femme, Graham Hess a rendu sa charge de pasteur. Tout en s''occupant de sa ferme, il tente d''élever de son mieux ses deux enfants, Morgan et Bo. Son jeune frère Merrill, une ancienne gloire du base-ball, est revenu vivre avec lui pour l''aider. Un matin, la petite famille découvre l''apparition dans ses champs de gigantesques signes et cercles étranges. Des extra-terrestres seraient-ils à l''origine de tels phénomènes surnaturels ? Graham et Merrill vont s''efforcer de percer le mystère qui entoure ces dessins.","en":"A family living on a farm finds mysterious crop circles in their fields which suggests something more frightening to come.","de":"Eine Familie, die auf einem Bauernhof lebt, findet auf ihren Feldern mysteriöse Kornkreise, die auf etwas noch Beängstigenderes hindeuten."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/r4q93grfe8xO28bY6MFMOZdffoo.jpg","it":"https://image.tmdb.org/t/p/w500/4Jv4RWBvi0F3DIXNfVF1Ldooy86.jpg","fr":"https://image.tmdb.org/t/p/w500/A5JFVANRBrNbkraAerHjF8h8aLI.jpg","en":"https://image.tmdb.org/t/p/w500/YtrIdrTxpRhvCnlw43dwOjfLqx.jpg","de":"https://image.tmdb.org/t/p/w500/53puwcLb51AW5iKkMwS528VMlhX.jpg"}'::jsonb WHERE id = 340;
UPDATE public.films SET tmdb_id = 180, titoli_i18n = '{"it":"Minority Report","es":"Minority Report","en":"Minority Report","de":"Minority Report","fr":"Minority Report"}'::jsonb, trame_i18n = '{"it":"Siamo nel 2054, a Washington, dove è stato messo a punto un sistema capace di prevedere i crimini, dunque prevenirli. Niente di particolarmente tecnologico: semplicemente tre umani dotati di capacità paranormali. Si chiamano pre-cog, da precognitives. Vivono in una piscina e hanno visioni che poi trasmettono a un secondo livello, a un''unità di pronto intervento, il cui eroe è John Anderton. Ma ecco che i veggenti a un certo punto indicano proprio John come futuro omicida di un tale che non conosce. Dunque il detective comincia la caccia a se stesso, naturalmente c''è la possibilità di qualche trucco, qualcuno per esempio potrebbe fabbricare non false prove, ma false visioni. Da qui una corsa contro il tempo, che è breve","es":"Washington DC, año 2054. La policía utiliza tecnología psíquica para arrestar y enjuiciar a los asesinos antes de que cometan un crimen. El futuro se puede predecir y los culpables son detenidos por la unidad de élite Precrime antes de que puedan delinquir. Las pruebas se basan en los \"precogs\", tres seres psíquicos cuyas visiones sobre los asesinatos nunca han fallado.","en":"John Anderton is a top ''Precrime'' cop in the late-21st century, when technology can predict crimes before they''re committed. But Anderton becomes the quarry when another investigator targets him for a murder charge.","de":"Im Washington, D.C., des Jahres 2054 gibt es keine Morde mehr. Die Zukunft ist bekannt und Mörder werden gefasst, bevor sie ihr Verbrechen begehen können. Dafür sorgt Pre-Crime, eine Elite-Einheit der Polizei, die die Visionen der Pre-Cogs, drei Wesen mit hellseherischen Fähigkeiten, auswertet und zur Tat schreitet. Das System ist perfekt. Und John Anderton ist sein perfekter Chef: Seit einem tragischen Verlust sechs Jahre zuvor widmet er sein Leben mit vollkommener Leidenschaft der Verbrecherjagd. Es gibt keinen Grund für ihn, am System zu zweifeln bis er in einer Vision selbst als Mörder zu sehen ist. 36 Stunden bleiben ihm bis zu dem Verbrechen. 36 Stunden, um zu beweisen, dass er unschuldig ist und das perfekte System fehlbar. Die Flucht kann beginnen.","fr":"Washington, 2054. Plus aucun meurtre ne se produit grâce au « pré-crime », l’unité policière dirigée par John Anderton. Cette unité dispose d''un système lui permettant de visualiser les meurtres avant qu''ils ne se produisent. Mais quand John découvre qu''il est lui-même accusé d''un meurtre à venir, il n''a que 36 heures pour comprendre le véritable fonctionnement de ce système."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/8EUnGlnPlleaNHt5dLGPK5GubQT.jpg","es":"https://image.tmdb.org/t/p/w500/q5qipy536mgsejg6AWPP9lmkGkG.jpg","en":"https://image.tmdb.org/t/p/w500/qtgFcnwh9dAFLocsDk2ySDVS8UF.jpg","de":"https://image.tmdb.org/t/p/w500/pW1k71rXEZoXESdg9OTuorEDfvV.jpg","fr":"https://image.tmdb.org/t/p/w500/91dfWOkpjlqPkbZDjAjrReFqXQP.jpg"}'::jsonb WHERE id = 341;
UPDATE public.films SET tmdb_id = 423, titoli_i18n = '{"it":"Il pianista","en":"The Pianist","fr":"Le Pianiste","es":"El pianista","de":"Der Pianist"}'::jsonb, trame_i18n = '{"it":"È la storia di Wladyslaw Szpilman, pianista ebreo polacco, attraverso la Seconda Guerra Mondiale, dall’occupazione di Varsavia all’arrivo dell’Armata Rossa. Il film è diviso in due parti: la prima è incentrata sulla famiglia Szpilman, dall’iniziale mix di stupore e indignazione per le leggi razziali alla reclusione nel ghetto, infine alla deportazione; col treno che parte, e Wladyslaw che rimane giù, inizia la seconda parte, la fuga del pianista, il suo continuo cambiar nascondiglio, sempre a un passo dalla cattura, a mezzo dalla morte, a nessuno dall’orrore che in quegli anni ha avvolto Varsavia – non solo Varsavia.","en":"The true story of pianist Władysław Szpilman''s experiences in Warsaw during the Nazi occupation. When the Jews of the city find themselves forced into a ghetto, Szpilman finds work playing in a café; and when his family is deported in 1942, he stays behind, works for a while as a laborer, and eventually goes into hiding in the ruins of the war-torn city.","fr":"Varsovie, au mois d’octobre 1939. Un jeune pianiste juif, Wladyslaw Szpilman, est enfermé dans le ghetto avec sa famille. Il assiste, impuissant, aux humiliations que subissent quotidiennement les siens. Grâce à une aide extérieure, il échappe de justesse à la déportation mais voit partir toute sa famille. Le jeune homme se cache alors dans les maisons vides et observe passivement les derniers habitants se révolter contre l’occupation allemande. Après avoir réussi à s’échapper miraculeusement, il se terre dans des quartiers détruits et tente de survivre, ce qui s’avère de plus en plus dur. C’est alors qu’il rencontre un nazi mélomane…","es":"Varsovia, 1939. El pianista polaco de origen judío Wladyslaw Szpilman (Adrien Brody) interpreta un tema de Chopin en la radio nacional de Polonia mientras la aviación alemana bombardea la capital. El régimen nazi ha invadido el país, y como hace en otros países invadidos, lleva a cabo la misma política con respecto a los judíos. Así Szpilman y toda su familia -sus padres, su hermano y sus dos hermanas- se ven obligados a dejar su casa y todo lo que les pertenece para trasladarse con miles de personas de origen judío al ghetto de Varsovia. Mientras Wladyslaw trabaja como pianista en un restaurante propiedad de un judío que colabora con los nazis, su hermano Henryk (Ed Stoppard) prefiere luchar contra los nazis. Pero tres años más tarde, los habitantes del ghetto son trasladados en trenes hacia campos de concentración.","de":"Warschau, 1939. Die Besetzung Polens durch die Deutschen bedeutet für den gefeierten polnisch-jüdischen Pianisten Wladyslaw Szpilman den Beginn eines langen Leidenswegs. Durch einen Glücksfall entgeht er dem Transport ins KZ, in dem seine gesamte Familie ums Leben kommt. Von nun an fristet er ein Dasein im Untergrund. Hungrig, krank und psychisch vor dem Kollaps stehend, wird er gegen Kriegsende schließlich von einem deutschen Offizier aufgespürt. Doch anstatt ihn auszuliefern, bittet er ihn, Klavier zu spielen. Szpilmans Rettung.  Der Pianist ist eine Filmadaption der Biographie „Das wunderbare Überleben“ von Wladyslaw Szpilman. Das Filmdrama des Regisseurs Roman Polanski hat mit dem Film auch ein Stück eigene Geschichte aufgearbeitet."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zK3KyPLAQl0IRIToIaQsMxm0aR3.jpg","en":"https://image.tmdb.org/t/p/w500/2hFvxCCWrTmCYwfy7yum0GKRi3Y.jpg","fr":"https://image.tmdb.org/t/p/w500/vI05JxU356MciaQeYHjXlqfjQe0.jpg","es":"https://image.tmdb.org/t/p/w500/mxfLOWnHnSlbdraKfzRn5mqoqk7.jpg","de":"https://image.tmdb.org/t/p/w500/eLWN41bCnCshV3fPqe5cuwqYCeK.jpg"}'::jsonb WHERE id = 342;
UPDATE public.films SET tmdb_id = 245, titoli_i18n = '{"it":"About A Boy - Un ragazzo","es":"Un niño grande","en":"About a Boy","de":"About a Boy oder: Der Tag der toten Ente","fr":"Pour un garçon"}'::jsonb, trame_i18n = '{"it":"Will è un single, vicino ai quarant’anni: vive di rendita e il suo unico scopo nella vita sembra essere continuare a non fare niente, impiegando la maggior parte del suo tempo a cercare nuove conquiste femminili. Infatti un giorno si reca ad un incontro di genitori single, fingendosi “ragazzo-padre” solo per conquistare qualche donna sola: invece si troverà suo malgrado coinvolto nella vita di una di queste, e soprattutto di suo figlio, Marcus.","es":"Will Lightman (Hugh Grant) es un soltero de 38 años que vive de los derechos de autor de una canción compuesta hace años por su padre. Su miedo al compromiso es tal que sólo se relaciona con madres solteras, porque piensa que es más fácil romper con ellas. Sin embargo, sus convicciones se tambalean cuando se convierte en el mejor amigo de Marcus, un niño de 12 años al que conoce en una de sus citas.","en":"Will Freeman is a good-looking, smooth-talking bachelor whose primary goal in life is avoiding any kind of responsibility. But when he invents an imaginary son in order to meet attractive single moms, Will gets a hilarious lesson about life from a bright, but hopelessly geeky 12-year-old named Marcus. Now, as Will struggles to teach Marcus the art of being cool, Marcus teaches Will that you''re never too old to grow up.","de":"Will Freeman wird von all seinen Geschlechtsgenossen beneidet – er fährt ein schnelles Auto, genießt seine Affären und kann mit 38 ohne jede Verantwortung in den Tag hinein leben… Seine neue Taktik für den Frauenfang ist der Besuch von Selbsthilfegruppen für allein erziehende Mütter und Väter, denn das ist genau der richtige Ort um auf einsame Frauen zu treffen. Doch dann begegnet Will Marcus. Dieser ungewöhnliche Zwölfjährige bringt sein Leben völlig durcheinander – mit äußerst amüsanten Folgen.","fr":"Will Freeman est un trentenaire londonien et un célibataire endurci. Vivant allègrement grâce aux droits d''auteur qu''il perçoit sur une chanson de Noël écrite par son père, il s''invente un fils pour draguer des mères célibataires. Un jour, il fait la connaissance de Marcus, un garçon de douze ans, fils de Fiona, hippie et végétarienne, et tête de Turc de l''école. Will et Marcus deviennent amis, et pendant que Will apprend à Marcus l''art d''être cool, Marcus apprend à Will l''art d''être adulte."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/hEzs1OAhc9djI69fRUHVRgXrin.jpg","es":"https://image.tmdb.org/t/p/w500/6AQlj4fIeZoDO74xhBKsEVPUa8m.jpg","en":"https://image.tmdb.org/t/p/w500/qoZ1bD0q9EFqcNiEYbEigsRcNCt.jpg","de":"https://image.tmdb.org/t/p/w500/5GxorcCulCJhcOjNGRUdkZWY2qN.jpg","fr":"https://image.tmdb.org/t/p/w500/b5uCL8EzOXe0DD2PZJjuF34eLy7.jpg"}'::jsonb WHERE id = 343;
UPDATE public.films SET tmdb_id = 1011082, titoli_i18n = '{"it":"The Greatest Hits","es":"The Greatest Hits","fr":"The Greatest Hits","de":"The Greatest Hits","en":"The Greatest Hits"}'::jsonb, trame_i18n = '{"it":"Harriet scopre che alcune canzoni la riportano indietro nel tempo, letteralmente. Mentre rivive una storia romantica del passato e, nel frattempo, scopre un nuovo amore nel presente attraverso il legame tra musica e memoria, si pone una domanda: cambierebbe il passato, se potesse?","es":"Harriet descubre que ciertas canciones la hacen viajar atrás en el tiempo y revive un romance del pasado mientras conoce a un nuevo interés amoroso en el presente. Durante el viaje a través de la hipnótica conexión entre música y recuerdos, Harriet se pregunta si cambiaría el pasado a pesar de tener el poder de hacerlo.","fr":"Harriet réalise que certaines chansons peuvent littéralement la ramener dans le passé. Elle revit une histoire d''amour passée tout en découvrant un nouvel amour dans le présent, à travers le lien entre la musique et la mémoire, et se demande si, même si cela est impossible, elle pourrait changer le passé...","de":"Harriet entdeckt, dass bestimmte Lieder sie in der Zeit zurückversetzen - im wahrsten Sinne des Wortes. Als sie eine vergangene Romanze wiedererlebt, während sie in der Gegenwart durch die Verbindung zwischen Musik und Erinnerung eine neue Liebe findet, stellt sie sich die Frage - selbst wenn sie die Vergangenheit ändern könnte, sollte sie es tun?","en":"Harriet finds art imitating life when she discovers certain songs can transport her back in time – literally. While she relives the past through romantic memories of her former boyfriend, her time travelling collides with a burgeoning new love interest in the present. As she takes her journey through the hypnotic connection between music and memory, she wonders – even if she could change the past, should she?"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg","es":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg","fr":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg","de":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg","en":"https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg"}'::jsonb WHERE id = 344;
UPDATE public.films SET tmdb_id = 64036, titoli_i18n = '{"it":"L''Esorciccio","en":"The Exorciccio","es":"L''Esorciccio","de":"L''Esorciccio","fr":"L''Esorciccio"}'::jsonb, trame_i18n = '{"it":"Durante scavi archeologici in Iran viene rinvenuto un amuleto che finisce tra le mani del figlio decenne del sindaco di un paesino del Lazio. Il ragazzino diventa un focosissimo amatore, e ricorre quindi allo stregone Esorciccio. E come lui tutti coloro che, a turno, posseggono l''amuleto si scatenano in inverecode stranezze. Ogni tanto compare addirittura il Demonio in persona, finché Esorciccio ingoia l''oggetto diabolico.","en":"A satire on the American film \"The Exorcist,\" but with an Italian twist."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg","en":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg","es":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg","de":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg","fr":"https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg"}'::jsonb WHERE id = 345;
UPDATE public.films SET tmdb_id = 807, titoli_i18n = '{"fr":"Seven","en":"Se7en","de":"Sieben","es":"Seven","it":"Seven"}'::jsonb, trame_i18n = '{"fr":"À New York, un criminel anonyme a décidé de commettre 7 meurtres basés sur les 7 pêchés capitaux énoncés dans la Bible : gourmandise, avarice, paresse, orgueil, luxure, envie et colère. Vieux flic blasé à 7 jours de la retraite, l''inspecteur Somerset mène l''enquête tout en formant son remplaçant, l''ambitieux inspecteur David Mills…","en":"Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the \"seven deadly sins\" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.","de":"Der besonnene Detective Somerset ist ein Kriminologe der „alten Schule“. Zusammen mit seinem neuen Kollegen, dem Heißsporn Mills, wird er auf den ungewöhnlichsten und erschreckendsten Fall seiner Laufbahn angesetzt. Ein unbekannter Serienkiller versucht scheinbar, die Stadt von allen Sünden zu befreien. Er tut dies, indem er auf bestialische Weise für jede der sieben Todsünden einen symbolischen Ritualmord begeht.","es":"El teniente Somerset, del departamento de homicidios, está a punto de jubilarse y ser reemplazado por el ambicioso y brillante detective David Mills. Ambos tendrán que colaborar en la resolución de una serie de asesinatos cometidos por un psicópata que toma como base la relación de los siete pecados capitales: gula, pereza, soberbia, avaricia, envidia, lujuria e ira. Los cuerpos de las víctimas, sobre los que el asesino se ensaña de manera impúdica, se convertirán para los policías en un enigma que les obligará a viajar al horror y la barbarie más absoluta.","it":"Un killer astuto e spietato sta uccidendo a raffica, nei modi più raccapriccianti, personaggi scelti con cura. Sulle sue tracce ci sono il giovane e ambizioso Mills, alla prima missione, e l''esperto Somerset, ormai prossimo alla pensione; personalità opposte che mal si tollerano a vicenda. Imparano a \"convivere\" man mano che la caccia all''assassino si fa più serrata e il mistero comincia a districarsi."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/to6jUaLJonMuKW2YovtWfQKtLYP.jpg","en":"https://image.tmdb.org/t/p/w500/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg","de":"https://image.tmdb.org/t/p/w500/79tFIrbMweqs52PxForIRJRFCIW.jpg","es":"https://image.tmdb.org/t/p/w500/uVPcVz4b2hnSGrXYLdIGRXwcivs.jpg","it":"https://image.tmdb.org/t/p/w500/1XHq0Z7BkjeQ9J5CLmWD0xX0DuB.jpg"}'::jsonb WHERE id = 346;
UPDATE public.films SET tmdb_id = 453, titoli_i18n = '{"en":"A Beautiful Mind","it":"A Beautiful Mind","de":"A Beautiful Mind - Genie und Wahnsinn","es":"Una mente maravillosa","fr":"Un homme d''exception"}'::jsonb, trame_i18n = '{"en":"From the heights of notoriety to the depths of depravity, John Forbes Nash Jr. experiences it all. As a brilliant but socially awkward mathematician, he made a groundbreaking discovery early in his career and stands on the brink of international acclaim. But as the handsome and arrogant Nash accepts secret work in cryptography, he becomes entangled in a mysterious conspiracy. His life takes a nightmarish turn and he soon finds himself on a painful and harrowing journey of self-discovery.","it":"Il film si ispira alla vita di John Forbes Nash Jr. Di origini medio borghesi, Forbes nacque in una piccola città della Virginia occidentale il 13 giugno 1928 e, per oltre cinquant''anni è stato considerato un mito negli ambienti della ricerca matematica. Grazie al suo studio della teoria dei giochi, negli anni 50 diventò l''astro nascente della \"nuova matematica\". Poco a poco, vittima di una grave forma di schizofrenia, Nash sprofondò in un mondo tutto suo, convinto che le sue allucinazioni fossero realtà. Passò diversi anni in ospedali psichiatrici, ma durante la sua assenza, la teoria dei giochi acquistò un ruolo di importanza fondamentale nei campi dell''economia e degli affari. Nel 1994, Nash aveva riacquistato il pieno controllo della sua vita e ripreso le ricerche. In quello stesso anno venne insignito del Premio Nobel per l''economia.","de":"Princeton Universität, 1947: Der hoch begabte, aber äußerst exzentrische John Nash sucht fieberhaft, fast krankhaft besessen, nach einer revolutionierenden Theorie in der Mathematik. Er schert sich wenig um seine Kommilitonen und die Konventionen der Universität. Und tatsächlich macht er eines Tages die alles entscheidende Entdeckung. Mit seiner Karriere geht es fortan steil bergauf, und Nash bekommt eine Stelle als Forscher und Dozent. Da er zudem die außergewöhnliche Fähigkeit besitzt, innerhalb weniger Sekunden komplexe Codes zu knacken, übernimmt er immer häufiger Decodier-Aufgaben für den amerikanischen Geheimdienst. Doch der Stress, die Gefahr und die Heimlichkeiten seiner Tätigkeit fordern ihren Tribut: John leidet zunehmend unter Verfolgungswahn und wittert ständig Verschwörungen. Die erschütternde Diagnose: paranoide Schizophrenie. John droht alles zu verlieren: seine geliebte Frau, seinen Job und seinen Verstand…","es":"Obsesionado con la búsqueda de una idea matemática original, el brillante estudiante John Forbes Nash llega a Princeton para realizar sus estudios de postgrado. Es un muchacho extraño y solitario, al que sólo comprende su compañero de cuarto. Por fin, Nash esboza una revolucionaria teoría y consigue una plaza de profesor en el MIT. Alicia Lardé, una de sus alumnas, lo deja fascinado al mostrarle que las leyes del amor están por encima de las de las matemáticas. Gracias a su prodigiosa habilidad para descifrar códigos es reclutado por Parcher William, del departamento de Defensa, para ayudar a los Estados Unidos en la Guerra Fría contra la Unión Soviética.","fr":"En 1947, étudiant les mathématiques à l''université de Princeton, John Forbes Nash Jr., un brillant élève, élabore sa théorie économique des jeux. Pour lui, les fluctuations des marchés financiers peuvent être calculées très précisément. Au début des années cinquante, ses travaux et son enseignement au Massachusetts Institute of Technology ne passent pas inaperçus et un représentant du Département de la Défense, William Parcher, se présente à lui pour lui proposer d''aider secrètement les États‐Unis. La mission de John consiste à décrypter dans la presse les messages secrets d’espions russes, censés préparer un attentat nucléaire sur le territoire américain. Celui‐ci y consacre rapidement tout son temps, et ce au détriment de sa vie de couple avec Alicia. Ce job n''est toutefois pas sans risques : des agents ennemis surveillent ses moindres faits et gestes. Mais personne ne le croit."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/rEIg5yJdNOt9fmX4P8gU9LeNoTQ.jpg","it":"https://image.tmdb.org/t/p/w500/bsVAjDLllFLEkuS1HwU96bbvkw5.jpg","de":"https://image.tmdb.org/t/p/w500/slNnHqV7xeXuqCfHFlqGOj9MJjK.jpg","es":"https://image.tmdb.org/t/p/w500/6zyZ6cauEgSbfii9I7gOvGNyPGv.jpg","fr":"https://image.tmdb.org/t/p/w500/AjoFwrErCHZYCx4pYqH1F0CjrcA.jpg"}'::jsonb WHERE id = 347;
UPDATE public.films SET tmdb_id = 1903, titoli_i18n = '{"fr":"Vanilla Sky","it":"Vanilla Sky","en":"Vanilla Sky","es":"Vanilla Sky","de":"Vanilla Sky"}'::jsonb, trame_i18n = '{"fr":"David Aames est un jeune et brillant éditeur new-yorkais qui a tout pour lui : l''argent, la réussite professionnelle et les femmes. Son ami Pelayo commet l''erreur de lui présenter Sofia, sa nouvelle compagne. Au premier regard, David succombe au charme de celle-ci. Tous les deux filent bientôt le parfait amour. Alors que David se dispute en voiture avec Julie, une ex folle de jalousie, la jeune femme accélère et c''est l''accident. Julie décède. Atrocement défiguré, David est transporté d''urgence à l''hôpital où les médecins ne peuvent réaliser de miracle. Sa vie bascule. Les gens ont dorénavant peur de lui et Sofia l''évite. Mais un matin, David se fait gentiment réveiller par celle-ci, qui lui déclare son amour. Les médecins lui annoncent même qu''il pourra retrouver son ancien visage. Réalité ou hallucination ?","it":"David Aames è un uomo davvero fortunato. È giovane, è bello ed è ricco, essendo l''erede di un impero editoriale. È abituato a ottenere ciò che vuole quando vuole, finché un giorno non incontra Sofia, che scompare quando lui comprende che è la donna dei suoi sogni. La vita di David non sarà più la stessa e la cercherà in modo ossessivo a rischio di perdere tutto.","en":"David Aames has it all: wealth, good looks and gorgeous women on his arm. But just as he begins falling for the warmhearted Sofia, his face is horribly disfigured in a car accident. That''s just the beginning of his troubles as the lines between illusion and reality, between life and death, are blurred.","es":"Re-boot. David Aames lo tiene todo: es apuesto, tiene dinero y una hermosa mujer a su lado. Pero justo cuando ha encontrado el verdadero amor en Sofía, sufre un accidente de automóvil que le deja la cara horriblemente desfigurada y lo pierde todo.","de":"Der New Yorker Geschäftsmann David Aames stand bislang auf der Sonnenseite des Lebens. Eines Abends jedoch verliebt er sich in die bezaubernde Sofia. Doch seine langjährige Affäre Julie hat etwas dagegen. Nach einem heftigen Streit kommt es zu einem Autounfall, bei dem Julie stirbt und Davids Gesicht aufs Grausamste entstellt wird. Etliche Operationen später scheint Aames genesen, da läuft ihm Sofia erneut über den Weg, nur um kurz darauf spurlos zu verschwinden. Stattdessen taucht Julie wieder auf und behauptet felsenfest, sie sei Sofia..."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/rP5pOnQ7kZrPOOCGay2Vc1O84Z0.jpg","it":"https://image.tmdb.org/t/p/w500/aV9cwAmpNhxlX8l64RXULc9jrqN.jpg","en":"https://image.tmdb.org/t/p/w500/cAh2pCiNPftsY3aSqJuIOde7uWr.jpg","es":"https://image.tmdb.org/t/p/w500/nphloW8RV0agLvy6iXYaITFmbuJ.jpg","de":"https://image.tmdb.org/t/p/w500/gXYUq0mqzlJV0Le0N2xG7E5QkLU.jpg"}'::jsonb WHERE id = 348;
UPDATE public.films SET tmdb_id = 676, titoli_i18n = '{"es":"Pearl Harbor","it":"Pearl Harbor","de":"Pearl Harbor","fr":"Pearl Harbor","en":"Pearl Harbor"}'::jsonb, trame_i18n = '{"es":"Rafe y Danny crecieron juntos en una zona rural estadounidense y su amistad se ha prolongado a lo largo de los años hasta las filas del ejercito del aire, donde los dos son pilotos de combate. Rafe encontró en Evelyn, una valiente enfermera, al amor de su vida, pero pronto es llamado a servir en la fuerza aérea británica para combatir a los nazis como representante del ejército estadounidense. Mientras tanto, Danny y Evelyn son enviados a la base aérea de Pearl Harbor en Hawai. Una vez allí, ambos se enamoran mientras Rafe es derribado en combate. Para sorpresa de ambos, Rafe sobrevive y regresa a Pearl Harbor pero todo se complica cuando se produce un mortal bombardeo por parte del ejercito japonés.","it":"In una tranquilla domenica mattina di dicembre, mentre i bambini sono intenti nei loro giochi e le famiglie raccolte in preghiera, squadroni di aerei da guerra giapponesi sfrecciano roboanti nei cieli del paradiso hawaiano un attacco a sorpresa contro le forze armate statunitensi di base a Pearl Harbor. Pearl Harbor è la storia di un intenso amore nato sullo sfondo degli eventi del 7 dicembre 1941. Descrive le vicende di due giovani e audaci piloti e della bella e sensibile infermiera di cui sono entrambi innamorati. E'' un imponente film sulla forza dell''amore e sul coraggio del singolo messi a dura prova da un drammatico momento storico.","de":"New Jersey 1941. Rafe McCawley und Danny Walker sind seit ihren Kindertagen beste Freunde. Wie Brüder sind sie aufgewachsen und das Fliegen war schon immer ihre große Leidenschaft. Inzwischen sind sie waghalsige junge Piloten im U.S. Army Air Corps. Bis eine eigenmächtige Entscheidung Rafes ihre Freundschaft auf die Probe stellt: Er hat sich als Freiwilliger zum \"Eagle Squadron\" gemeldet, einer Gruppe amerikanischer Soldaten, die auf Seiten der Engländer kämpft. Rafe lässt nicht nur seinen besten Freund zurück, sondern auch seine große Liebe Evelyn. Sie ist eine mutige junge Frau, die Rafe im Militärkrankenhaus kennenlernte, in dem sie als Krankenschwester arbeitet. Während Rafe in England sein Leben aufs Spiel setzt, werden Evelyn und Danny nach Pearl Harbor auf Hawaii versetzt ...","fr":"Amis depuis la plus tendre enfance, Rafe McCawley et Danny Walker sont deux brillants pilotes de l''armée de l''air américaine. La Seconde Guerre mondiale a commencé, mais les États-Unis n''ont pas encore engagé les hostilités. Rafe succombe bientôt au charme d''Evelyn Johnson, une jeune infirmière. C''est le coup de foudre. Mais ce dernier part combattre aux côtés des Britanniques. Evelyn et Danny sont, quant à eux, transférés sur la base américaine de Pearl Harbor. La paisible existence de ces deux jeunes gens bascule lorsqu''ils apprennent la mort de Rafe. Evelyn partage son chagrin avec Danny et un amour naît de leurs confidences. Rafe est pourtant vivant. En cette journée du 7 décembre 1941, les retrouvailles et les explications vont devoir être reportées à plus tard : au même moment, près de 200 bombardiers japonais surgissent dans le ciel de Hawaï pour une attaque surprise.","en":"The lifelong friendship between Rafe McCawley and Danny Walker is put to the ultimate test when the two ace fighter pilots become entangled in a love triangle with beautiful Naval nurse Evelyn Johnson. But the rivalry between the friends-turned-foes is immediately put on hold when they find themselves at the center of Japan''s devastating attack on Pearl Harbor on Dec. 7, 1941."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/ftkKVbk4sQEcekuaGJvpvXcNs32.jpg","it":"https://image.tmdb.org/t/p/w500/rU08tMQ381BRMjKSwDKiR00TNeq.jpg","de":"https://image.tmdb.org/t/p/w500/1XCLbbuhN2wFjURcY046RMTCaO.jpg","fr":"https://image.tmdb.org/t/p/w500/3oae9FJMWfvobqbl0CvXqqCftvU.jpg","en":"https://image.tmdb.org/t/p/w500/y8A0Cvp8WQmZ3bjbnsL53lY0dsC.jpg"}'::jsonb WHERE id = 349;
UPDATE public.films SET tmdb_id = 1018, titoli_i18n = '{"it":"Mulholland Drive","fr":"Mulholland Drive","es":"Mulholland Drive","de":"Mulholland Drive - Straße der Finsternis","en":"Mulholland Drive"}'::jsonb, trame_i18n = '{"it":"In tarda notte, una limousine percorre Mulholland Drive (una strada che attraversa le colline attorno a Los Angeles, California); al suo interno c''è una donna dai capelli scuri (interpretata da Laura Elena Harring) e due uomini; improvvisamente, l''auto si ferma ed uno dei due uomini punta una pistola contro la donna; subito dopo, però, dei pirati della strada si schiantano contro la limousine. La donna resta miracolosamente illesa, ma ha un''amnesia. Abbandona la scena dell''incidente e scende la collina che porta a Los Angeles, stendendosi nel giardino di un appartamento e mettendosi a dormire. Il giorno successivo, si sveglia e vede la proprietaria dell''appartamento, una donna di mezza età dai capelli rossi, che sta per partire.","fr":"À Hollywood, durant la nuit, Rita, une jeune femme, devient amnésique suite à un accident de voiture sur la route de Mulholland Drive. Elle fait la rencontre de Betty Elms, une actrice en devenir qui vient juste de débarquer à Los Angeles. Aidée par celle-ci, Rita tente de retrouver la mémoire ainsi que son identité.","es":"Betty, una joven aspirante a actriz, llega a Los Ángeles para convertirse en estrella de cine y se aloja en el apartamento de su tía. Allí conoce a Rita, una mujer que padece amnesia a causa de un accidente en Mulholland Drive. Las dos juntas deciden investigar quién es Rita y cómo llegó hasta allí.","de":"Nach einem Unfall irrt eine junge Frau, die ihr Gedächtnis verloren hat, durch das nächtliche Hollywood und findet Unterschlupf in einem Appartement, das von der jungen Schauspielerin Betty bewohnt wird. Diese will in Hollywood Karriere machen, erklärt sich aber bereit, der verstörten Schönheit bei der Suche nach ihrem düsteren Geheimnis zu helfen.","en":"Blonde Betty Elms has only just arrived in Hollywood to become a movie star when she meets an enigmatic brunette with amnesia. Meanwhile, as the two set off to solve the second woman''s identity, filmmaker Adam Kesher runs into ominous trouble while casting his latest project."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/zQKnbazscP54i6iKHfdgYdmDsLv.jpg","fr":"https://image.tmdb.org/t/p/w500/d5gefer4mHnL5kOmlOP5rGumdM7.jpg","es":"https://image.tmdb.org/t/p/w500/kLpwkbimTwTbsYixCO3eAdNCQJ8.jpg","de":"https://image.tmdb.org/t/p/w500/6XpAFxwhVZ2t30Qtn8Wz8koKlaN.jpg","en":"https://image.tmdb.org/t/p/w500/x7A59t6ySylr1L7aubOQEA480vM.jpg"}'::jsonb WHERE id = 350;
UPDATE public.films SET tmdb_id = 768, titoli_i18n = '{"es":"Desde el infierno","de":"From Hell","en":"From Hell","fr":"From Hell","it":"La vera storia di Jack lo Squartatore"}'::jsonb, trame_i18n = '{"es":"Basada en la historia de Jack el Destripador y el cómic de Alan Moore. Amanece en Whitechapel, el barrio más sórdido de Londres, donde las drogas, la enfermedad y la miseria campan a sus anchas. Cinco chicas dedicadas a la prostitución se encuentran amenazadas por un terrible monstruo que podría robarles su única posesión: la vida. El único que se toma la molestia por protegerlas es el Inspector Fred Abberline que con la ayuda de su amigo el sargento Godley, trata de desentrañar una espeluznante conspiración. A medida que los salvajes asesinatos se suceden, los dos hombres ven obstaculizado su trabajo por unos superiores más interesados en esconder los crímenes bajo la alfombra que en encontrar al verdadero asesino, un sádico loco destinado a pasar a la historia.","de":"Der Tod seiner Frau und seines Kindes hat den Scotland-Yard-Inspektor Fred Abberline endgültig aus der Bahn geworfen. Nun sucht er Vergessen in Drogen, doch was er im Opium- und Absinth-Rausch findet, sind Visionen von grausigen Verbrechen und düstere Vorahnungen, die ihn zu einem Besessenen werden lassen. Sie sind es auch, die eine Verbindung herstellen zwischen ihm und dem Prostituiertenmörder Jack the Ripper, dessen Taten das Slum-ähnliche Londoner Arbeiterviertel Whitechapel in Aufruhr versetzen. Bei seinen Nachforschungen begegnet Abberline der engelsgleichen irischen Prostituierten Mary Kelly, die mit allen Opfern des brutalen Serienmörders befreundet war.","en":"Frederick Abberline is an opium-huffing inspector from Scotland Yard who falls for one of Jack the Ripper''s prostitute targets in this Hughes brothers adaption of a graphic novel that posits the Ripper''s true identity.","fr":"En 1888, à Londres, dans les rues mal famées du quartier de Whitechapel, un tueur en série, surnommé Jack l''Éventreur, rôde. D''une étonnante précision, ce mystérieux personnage éventre, la nuit tombée, des prostituées. C''est ici qu''entre en scène l''inspecteur Fred Abberline. Cet agent de Scotland Yard comprend rapidement que ces crimes procèdent d''une mise en scène élaborée et supposent un \"doigté\" d''artiste, un sang-froid à toute épreuve et de solides connaissances en anatomie. Le policier, intuitif et visionnaire, dresse patiemment le profil de ce meurtrier hors normes et parvient à gagner la confiance de Mary Kelly, une jeune prostituée. Celle-ci va l''aider à résoudre cette périlleuse enquête.","it":"Londra, 1888. Nelle strade del quartiere di Whitechapel, Jack lo Squartatore si aggira di notte uccidendo e sventrando le prostitute. Sulle sue tracce, oltre all''intera polizia londinese, c''è l''ispettore Frederick George Abberline, l''unico che capisce subito che i delitti sono preceduti da una meticolosa e scrupolosa messa in scena. Il poliziotto, intuitivo e visionario, cerca di ricostruire il profilo di Jack anche grazie all''aiuto della prostituta Mary Kelly."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/fv29GwNS1NOgsr4NAdghOlQXkup.jpg","de":"https://image.tmdb.org/t/p/w500/uxWh7kHpeDTsiYELdw4H33ACNyM.jpg","en":"https://image.tmdb.org/t/p/w500/t2WpWM8nBO4sULXr2bDfNEt4qgr.jpg","fr":"https://image.tmdb.org/t/p/w500/yqNsZZQF4khKyCZ13yfnT4ov6uI.jpg","it":"https://image.tmdb.org/t/p/w500/pvgnEmCPie99MOZFrkEpA73QHgg.jpg"}'::jsonb WHERE id = 351;
UPDATE public.films SET tmdb_id = 392, titoli_i18n = '{"de":"Chocolat","en":"Chocolat","it":"Chocolat","es":"Chocolat","fr":"Le Chocolat"}'::jsonb, trame_i18n = '{"de":"Ein verschlafenes Dorf in Frankreich im Jahre 1959. Hier glauben die Bewohner an „Tranquillité“, an die Ruhe und Stille. Man ist ordentlich und gottesfürchtig, wie es sich gehört. Da kommt Vianne Rocher mit ihrer minderjährigen Tochter in die Stadt, mietet die leerstehende Patisserie an und eröffnet einen Schokoladenladen. Da sie nicht verheiratet ist, nicht in die Kirche geht und den Laden in der Fastenzeit öffnet, eckt sie bei vielen Leuten, besonders dem Bürgermeister an. Doch ihre Spezialitäten zeigen ihre Wirkung bei den ersten Leuten, die wie nach einem langen Winter allmählich auftauen. Vianne nimmt sich Zeit, redet mit den Leuten und gewinnt das Vertrauen einiger. Doch es gibt immer wieder Probleme, vor allem, als sie sich mit dem Zigeuner Roux anfreundet, ein Nomade wie sie selbst …","en":"In the winter of 1959, a single mother and her young daughter arrive in a rural French town, where they open an unusual chocolate shop that disrupts the moral fiber of the strictly Catholic townsfolk and mayor.","it":"L''apertura di un peccaminoso negozio di cioccolata da parte della giovane Vianne Rocher nel minuscolo villaggio di Lansquenet, scatena una vera e propria guerra all''interno della cittŕ, tra quelli che non vedono di buon occhio il negozio e quelli che desiderano assaporare la libertà che hanno appena scoperto.","es":"A Lansquenet, un pueblo francés muy tradicional, donde nada ha cambiado en los últimos cien años, el Viento del Norte lleva consigo a dos forasteras: Vianne Rocher y su hija Anouk. Vianne inaugura una chocolatería repleta de dulces capaces de despertar los ocultos apetitos de los habitantes del pueblo. Posee, además, un don especial que le permite percibir los deseos de los demás y satisfacerlos con el dulce exacto.","fr":"Durant l''hiver 1959, Vianne Rocher s''installe avec Anouk, sa petite fille, à Lansquenet, une petite bourgade française. En quelques jours, elle ouvre une confiserie à proximité de l''église. C''est une chocolatière hors pair: elle devine la gourmandise cachée de chacun et adapte ses recettes raffinées pour combler ses clients. De nombreux villageois s''abandonnent rapidement à ses irrésistibles friandises et succombent à ses délices sucrés. Mais la bourgeoisie huppée de la ville ainsi que le Comte de Reynaud sont outrés de voir les habitants envoûtés par les chocolats de Vianne. Craignant que ses friandises n''amènent les gens au péché et à l''oisiveté, le Comte s''oppose vivement au commerce de Vianne et, afin de causer sa faillite, interdit à quiconque de s''y rendre. La venue d''un autre étranger, le beau Roux, va bouleverser la donne. Il aide Vianne à tenir tête à ses détracteurs."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/meGDfWXgwbN63RJ5mhaogqLQiM8.jpg","en":"https://image.tmdb.org/t/p/w500/lnwPvyj8UR7MetG2pQ92453IIoR.jpg","it":"https://image.tmdb.org/t/p/w500/ym4zIlPCAoD0UqOBf6NmHcK0YIi.jpg","es":"https://image.tmdb.org/t/p/w500/yxaZCSXfUlkBY8WVYoeWeE8nvej.jpg","fr":"https://image.tmdb.org/t/p/w500/7RBG3RzAqQvF6XtTsQqLzdsyAvR.jpg"}'::jsonb WHERE id = 352;
UPDATE public.films SET tmdb_id = 8358, titoli_i18n = '{"es":"Náufrago","it":"Cast Away","en":"Cast Away","de":"Cast Away - Verschollen","fr":"Seul au monde"}'::jsonb, trame_i18n = '{"es":"Chuck Noland, un ejecutivo de la empresa multinacional de mensajería FedEx, se ve apartado de su cómoda vida y de su prometida a causa de un accidente de avión por el que queda aislado de la civilización en una remota isla tropical. Único superviviente y solo en la isla, tras cuatro años de subsistencia Chuck aprende todas las técnicas de supervivencia mientras sufre la tortura de la soledad. La solución: arriesgar la vida adentrándose mar adentro.","it":"È la vigilia di Natale e Chuck Noland, funzionario della Federal Express, scambia i regali con la sua fidanzata Kelly in macchina prima di salire a bordo dell''aereo per l''ennesimo viaggio di lavoro. A causa di una tempesta l''aereo si inabissa nel Pacifico. Chuck, unico sopravvissuto, naufraga su di un isola deserta dove si rende conto, poco alla volta, che dovrà restarci per molto molto tempo.","en":"Chuck Noland, a top international manager for FedEx, and Kelly, a Ph.D. student, are in love and heading towards marriage. Then Chuck''s plane to Malaysia crashes at sea during a terrible storm. He''s the only survivor, and finds himself marooned on a desolate island. With no way to escape, Chuck must find ways to survive in his new home.","de":"Als gestresster Inspektor eines Transportunternehmens reist Chuck Noland um die ganze Welt. Dann passiert das Unerwartete: Nach einem Unfall kann er sich als einziger Überlebender auf eine einsame Insel retten. Gefangen im Paradies kämpft er vier Jahre lang ums Überleben um dann, zurück in der Zivilisation, eine für ihn fremd gewordene Welt vorzufinden.","fr":"Chuck Noland, gestionnaire au service d’un transporteur international, ne vit que par son travail. Il sillonne le monde pour améliorer les performances de son entreprise et la productivité de ses équipes. Il ne voit sa compagne Kelly que quelques jours par an. Lors de l’un de ses déplacements, Chuck est victime d’un accident d''avion qui coule en plein Pacifique. Agrippé à un radeau de sauvetage, Chuck s’échoue sur un îlot désert. Seul au monde, privé de tous ses repères habituels, le naufragé doit apprendre les gestes élémentaires pour sa survie."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/BlxcYMoHMXsgf3sXcHAjLOuQ1y.jpg","it":"https://image.tmdb.org/t/p/w500/WOTDhrel5R6hDhfDhFhHmExxjO.jpg","en":"https://image.tmdb.org/t/p/w500/7lLJgKnAicAcR5UEuo8xhSMj18w.jpg","de":"https://image.tmdb.org/t/p/w500/4GHtillFPlz9DApJov5P5WMz6r4.jpg","fr":"https://image.tmdb.org/t/p/w500/w1bnhSkcT4pa2KQZzRoq0BHBn8T.jpg"}'::jsonb WHERE id = 353;
UPDATE public.films SET tmdb_id = 11983, titoli_i18n = '{"fr":"L''Échange","de":"Lebenszeichen - Proof of Life","en":"Proof of Life","es":"Prueba de vida","it":"Rapimento e riscatto"}'::jsonb, trame_i18n = '{"fr":"Peter Bowman, ingénieur américain en Amérique latine est kidnappé par les rebelles qui réclament une rançon de 3 milliards de dollars. Ne pouvant compter sur le soutien de l’employeur de son mari, sa femme Alice fait alors appel à Terry Thorne, un ancien membre des services secrets britanniques, expert en \" kidnapping et rançon \", qui a mis ses compétences au service de la compagnie d’assurance Luthan Risk International et sauvé depuis la vie de nombreux otages. Les pourparlers s’engagent dans un climat tendu. Les ravisseurs menacent périodiquement d’exécuter leur prisonnier, qu’ils transfèrent de camp et camp à travers les montagnes et la jungle, lui faisant endurer d’incessantes souffrances physiques et psychologiques. Avec l’aide d’un autre négociateur Dino et un trio de mercenaires parfaitement entraînés, Terry s’engage dans une opération commando à hauts risques pour libérer Peter Bowman.","de":"In Tecala entführen Mitglieder einer Terrororganisation mehrere Menschen, darunter auch den Ingenieur Peter Bowman. Sie verschleppen ihn in die Berge, während seine sich ebenfalls in Tecala befindliche Frau Alice mit dieser Situation kaum klar kommt. Zu allem Überfluss erfährt Alice auch noch, dass Peter''s Firma von einem anderen Konzern übernommen wird; dieser neue Arbeitgeber will Peter''s neuestes Projekt, den Bau eines Staudamms zu wohltätigen Zwecken, nicht finanzieren und hätte ihn sowieso entlassen. So zieht auch der zuerst zu Rate gezogene, dem Konzern unterstellte Kidnappingexperte Terry Thorne trotz Flehens von Alice` Seite seiner Wege. Alice hat nicht nur Schwierigkeiten das geforderte Lösegeld aufzutreiben, sondern der ortsansässige Vermittler entpuppt sich auch noch als Betrüger. Doch die Rettung naht: Terry entscheidet sich aufgrund seines schlechten Gewissens, die Verhandlungen doch noch zu übernehmen.","en":"When Peter Bowman, an American engineer working in a South American country, is captured by anti-government forces, the rebels learn his identity and demand $5 million for his safe return. However, his US employer is on the verge of insolvency and will not provide the ransom. Peter''s wife Alice is forced to deal with the matter on her own and she retains the services of freelance professional hostage negotiator Terry Thorne.","es":"Mientras construye una presa en Tecala, en el corazón de los Andes, el ingeniero norteamericano Peter Bowman es capturado por fuerzas antigubernamentales durante una incursión en la capital. Cuando los rebeldes descubren su identidad exigen tres millones de dólares de rescate. El problema es que la empresa de Peter, con sede en Houston, está al borde de la bancarrota y ha cancelado la póliza de seguros contra secuestros, así que no dispone del dinero del rescate. Viéndose abandonada por la compañía, la esposa de Peter contrata los servicios de Terry Thorne, un negociador profesional que en los últimos años ha resuelto numerosos casos de secuestro.","it":"Per liberare un importante manager americano, preso in ostaggio da alcuni guerriglieri colombiani, un negoziatore si reca in America Latina. Ed innamorandosi della moglie del prigioniero non fa che complicare la sua missione..."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/r5i4CvMAyOQ0h7A2mfHCg5OZjke.jpg","de":"https://image.tmdb.org/t/p/w500/4OiduBCxGNZgl3KBY2fN2uoXhcN.jpg","en":"https://image.tmdb.org/t/p/w500/yw8x2i3vaHZZzpvqvF75E8q2N6M.jpg","es":"https://image.tmdb.org/t/p/w500/1YoW4LJpl559Bcs8ToyFRR249R1.jpg","it":"https://image.tmdb.org/t/p/w500/4v6lGQKphnHNz3AYb72M7xfVs0a.jpg"}'::jsonb WHERE id = 354;
UPDATE public.films SET tmdb_id = 9741, titoli_i18n = '{"it":"Unbreakable - Il predestinato","en":"Unbreakable","es":"El protegido","de":"Unbreakable - Unzerbrechlich","fr":"Incassable"}'::jsonb, trame_i18n = '{"it":"David Dunn è l''unico superstite di un disastroso incidente ferroviario; non solo è stato l''unico a salvarsi su 132 passeggeri, ma non ha riportato nemmeno un graffio. Forse soltanto la folle teoria di Elijah Price, un esperto di fumetti che si è messo in contatto con David, può spiegare la sua miracolosa invulnerabilità.","en":"An ordinary man makes an extraordinary discovery when a train accident leaves his fellow passengers dead — and him unscathed. The answer to this mystery could lie with the mysterious Elijah Price, a man who suffers from a disease that renders his bones as fragile as glass.","es":"Philadelphia. Año 1961. Un niño negro acaba de nacer en unos grandes almacenes. Un médico acude a ver como se encuentran tanto la madre como el bebé, y horrorizado le pregunta a la mujer si se le ha caído el niño, ya que tiene tanto los brazos como las piernas fracturadas. Philadelphia. Año 2000. Un hombre llamado David Dunn está en el expreso que va de Nueva York a Philadelphia camino de su casa después de una entrevista de trabajo en la ciudad de los rascacielos. En el tren entabla conversación con una atractiva mujer, pero ésta cree que quiere ligar y se cambia de asiento. Un momento después se produce un dramático accidente.","de":"Ein verheerender Zugunfall vor den Toren von Philadelphia. 131 Tote. Nur ein Mann hat die Katastrophe überlebt – völlig unverletzt, ganz ohne Schrammen. Hatte David Dunn nur Glück? Oder gibt es einen tieferen Grund für sein Überleben? Er hat keine Antworten auf seine Fragen. Doch dann tritt Elijah Price in sein Leben. Er behauptet, David Dunn sei unzerbrechlich und er wüsste, warum …","fr":"Unique survivant d''une catastrophe ferroviaire à la périphérie de Philadelphie, David Dunn, un agent de sécurité à la vie des plus banales, s''interroge sur les raisons qui lui ont permis d''échapper à la mort et de sortir de ce cauchemar sans la moindre égratignure. Quelque temps plus tard, Elijah Price, un étrange personnage féru de bandes dessinées, prend contact avec David. Il souffre d''une fragilité du squelette qui l''oblige à rester au lit, le moindre choc pouvant lui causer une fracture. Price soumet à Dunn une théorie pour le moins surprenante. Cet homme aux os de verre serait inextricablement lié à Dunn qui, lui, n''a jamais contracté la moindre maladie de sa vie..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/4bbHcTViomdM0j7dM0Tm0CYQF1m.jpg","en":"https://image.tmdb.org/t/p/w500/mLuehrGLiK5zFCyRmDDOH6gbfPf.jpg","es":"https://image.tmdb.org/t/p/w500/5SlS9jMrLRB4ZhoWUmLnC5GK7aC.jpg","de":"https://image.tmdb.org/t/p/w500/8sVi8I2GS2b1xVxgXnMobKCjcNs.jpg","fr":"https://image.tmdb.org/t/p/w500/ykeSbrFsTa24jVGW6QDDb6W7SEo.jpg"}'::jsonb WHERE id = 355;
UPDATE public.films SET tmdb_id = 77, titoli_i18n = '{"it":"Memento","es":"Memento","de":"Memento","en":"Memento","fr":"Memento"}'::jsonb, trame_i18n = '{"it":"Leonard Shelby è affetto da una particolare forma di amnesia che lascia intatti i vecchi ricordi ma comporta la perdita della memoria breve. Attraverso un''affannosa ricerca compiuta per mezzo dell''azione e della scrittura, che serve a registrare ciò di cui la percezione non può farsi sicuro garante, Leonard cerca l''assassino della moglie, l''ultimo ricordo che \"non riesce a ricordare di dimenticare\".","es":"Leonard Shelby sigue la pista del hombre que violó y asesinó a su mujer. Sin embargo, la dificultad de localizar al asesino de su esposa se ve agravada por el hecho de que padece una forma rara e intratable de pérdida de memoria a corto plazo. Aunque puede recordar detalles de la vida antes de su accidente, Leonard no puede recordar qué ha pasado hace quince minutos, adónde va o por qué.","de":"Leonard Shelby hat bei einem Unfall sein Kurzeitgedächtnis verloren. Zwar weiß er, wer er ist, doch er kann sich keine Namen, keine Begegnungen länger als ein paar Minuten merken. Sein Leben besteht aus einem Berg Notizen, Fotos und Tätowierungen, mit denen sein Körper übersät ist. Der Film beginnt mit einem Mord, festgehalten auf einem Polaroid. Der einzige Hinweis, dass Shelby den Mord begangen hat. Ein Mann ohne Gedächtnis kann von seiner Umwelt leicht missbraucht werden. Shelby versucht aus dem Wirrwarr von Notizen und Fotos das Geschehen zu entschlüsseln. Wenn er vor dem Spiegel steht, sieht er die Tätowierung: Finde den Mörder deiner Frau. Töte ihn.","en":"Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife''s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he''s going, or why.","fr":"Leonard Shelby ne porte que des costumes de grands couturiers et ne se déplace qu’au volant de sa Jaguar. En revanche, il habite dans des motels miteux et règle ses notes avec d’épaisses liasses de billets. Leonard n’a qu’une idée en tête: traquer l’homme qui a violé et assassiné sa femme afin de se venger. Sa recherche du meurtrier est rendue plus difficile par le fait qu’il souffre d’une forme rare et incurable d’amnésie. Bien qu’il puisse se souvenir de détails de son passé, il est incapable de savoir ce qu’il a fait dans le quart d’heure précédent, où il se trouve, où il va et pourquoi. Pour ne jamais perdre son objectif de vue, il a structuré sa vie à l’aide de fiches, de notes, de photos, de tatouages sur le corps. C’est ce qui l’aide à garder contact avec sa mission, à retenir les informations et à garder une trace, une notion de l’espace et du temps."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/eyVdGf0QUnw1SBr1IMvZJj5kk6M.jpg","es":"https://image.tmdb.org/t/p/w500/fKTPH2WvH8nHTXeBYBVhawtRqtR.jpg","de":"https://image.tmdb.org/t/p/w500/qaXfDrZCdd3wix2XYor5HDDpFrT.jpg","en":"https://image.tmdb.org/t/p/w500/nzlv62aC0octS5AklAiWpXLX9Z0.jpg","fr":"https://image.tmdb.org/t/p/w500/nK3cJaUWx1iaQ9Cs08JPtZqVzQ6.jpg"}'::jsonb WHERE id = 356;
UPDATE public.films SET tmdb_id = 2133, titoli_i18n = '{"it":"La tempesta perfetta","es":"La tormenta perfecta","fr":"En pleine tempête","de":"Der Sturm","en":"The Perfect Storm"}'::jsonb, trame_i18n = '{"it":"Gloucester, Massachusetts: un gruppo di pescatori, guidati dal determinato capitano Billy Tyne, dopo un periodo di magra, si dirigono al largo in cerca di maggiore fortuna; l''equipaggio del peschereccio \"Andrea Gail\" naviga oltre le normali rotte di pesca del New England, fino al Flemish Cap, noto per i ricchi banchi di pesce spada. Mentre si trova già in alto mare, la barca riceve l''allarme riguardo ad una tempesta che sta montando alle loro spalle, ma, decisi a non rinunciare alla ricca battuta di pesca ed ai guadagni che con essa ne ricaveranno, ignorano l''avvertimento e procedono nel loro intento. Sfortunatamente la situazione meteoreologica peggiora e l''uragano Grace è in rotta di collisione con altre due aree di bassa pressione, una proveniente da Sud, l''altra da Nord, dalla cui unione scaturisce la cosiddetta tempesta perfetta, un evento che, secondo gli esperti meteo, si verifica molto raramente.","es":"Gloucester (Massachussetts), octubre de 1991. El Andrea Gail es un barco de pesca capitaneado por Billy Tyne, un veterano pescador cuyas últimas salidas se han saldado con paupérrimas capturas. Buscando un golpe de suerte que haga cambiar esta mala racha, se interna en el Flemish Cap, un lugar más allá de las zonas frecuentadas por los pescadores. Lo que ignora es que, a la zona donde faena, se está aproximando la tormenta más aterradora, violenta y destructiva que se pueda concebir.","fr":"Gloucester fut pendant près de quatre siècles le premier port d''Amérique. Mais l''âge d''or est révolu et les temps difficiles obligent les marins à s''aventurer dans des zones dépressionnaires à hauts risques. Aussi, après une saison décevante, Billy Tyne, capitaine de l''Andrea Gail, décide-t-il de tenter sa chance dans la zone du Cap Flemish. Mais les éléments semblent s''acharner contre lui et son équipage: une terrible tempête se lève.","de":"Die Gefahr von Sturm und Wellen auf hoher See ist ihr Alltag, für einen erfolgreichen Fischzug geben sie alles – die Schwertfischer von Gloucester riskieren täglich ihr Leben und sind stolz darauf! Aber als Captain Tyne und seine Crew dieses Mal auslaufen, um den letzten Fang der Saison einzuholen, ahnen sie nicht, welcher Macht sie sich stellen müssen.","en":"In October 1991, a confluence of weather conditions combined to form a killer storm in the North Atlantic. Caught in the storm was the sword-fishing boat Andrea Gail."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/kpQ8X4WAQJ032CYlta81B6OrZcg.jpg","es":"https://image.tmdb.org/t/p/w500/75aRoXgG74D5wbSqEQAYFpFFJ0V.jpg","fr":"https://image.tmdb.org/t/p/w500/nwbMqUD9RsJDwa9XD3n9FhU2R8l.jpg","de":"https://image.tmdb.org/t/p/w500/rTSPQuj7ufQxNhdJxa4m89WsXZt.jpg","en":"https://image.tmdb.org/t/p/w500/vJPoxqgpfFNbGi0HyoNsjFeLCio.jpg"}'::jsonb WHERE id = 357;
UPDATE public.films SET tmdb_id = 1213, titoli_i18n = '{"it":"Il talento di Mr. Ripley","es":"El talento de Mr. Ripley","de":"Der talentierte Mr. Ripley","en":"The Talented Mr. Ripley","fr":"Le Talentueux M. Ripley"}'::jsonb, trame_i18n = '{"it":"1958: Tom Ripley è un giovane americano educato di modesta estrazione. Cede il posto alle signore e ascolta rispettosamente i consigli dei più anziani. Con gli amici è allegro, non ha eguali nell''imitare i personaggi celebri, nel cantare e suonare il piano. Soprattutto tende spesso a mentire pur di mascherare la propria condizione. Un giorno durante un party la grande occasione: un ricco industriale gli chiede, dietro un cospicuo compenso, di riportare negli Stati Uniti suo figlio Dickie, che vive un esilio dorato in Italia. Tom infatti, si è sentito di spacciarsi per un suo compagno di università, avendo indossato un blazer dell''istituto fattosi prestare da un amico per l''occasione. Il giovane entra in una gigantesca avventura, raggiunge quindi Ischia, dove vive Dick Greenleaf; ne diventa amico, e conosce anche la sua bella ragazza, Marge.","es":"Ser joven y despreocupado en medio de un paisaje idílico de la Italia bañada por el sol de finales de los 50: esa es la dolce vita que Tom Ripley (Matt Damon) anhela, y que Dickie Greeleaf (Jude Law) disfruta. Cuando el padre de Dickie, un adinerado constructor de barcos, pide a Tom que traiga de vuelta a casa, a América, a su hijo, éste y su bella y expatriada compañera, Marge Sherwood (Gwyneth Paltrow), nunca hubieran sospechado a qué peligrosos extremos llegaría Ripley con tal de convertir el estilo de vida de la pareja en el suyo propio. Al fin y al cabo, es mejor ser una falsa persona importante que un don nadie auténtico.","de":"Der mittellose Tom Ripley erhält den Auftrag, nach Italien zu reisen, um seinen Altersgenossen, den jungen amerikanischen Playboy Dickie Greenleaf zu überreden, in die USA zurückzukehren. Dickie aber bleibt hartnäckig und zieht es vor, weiterhin das Dolce Vita mit seiner reizenden Verlobten Marge zu genießen. Tom beneidet Dickie um das Leben, das er führt. Eines Tages, während einer gemeinsamen Reise zum Jazzfestival von San Remo, kommt es zu einer Rauferei, die fast aus Versehen beginnt, sich aber zum todernsten Kampf ausweitet. Mit viel Talent schlüpft Tom Ripley von nun an in die Haut des getöteten Dickie Greenleaf, eignet sich seinen Lebensstil an und will alles hinter sich lassen. Er genießt sein Leben am Abgrund, denn einige Menschen, die Dickie Greenleaf nahe standen, stellen sich natürlich Fragen: Ist es möglich, dass jemand, selbst wenn er so extrem launisch ist wie Dickie, einfach verschwindet?","en":"Tom Ripley is a calculating young man who believes it''s better to be a fake somebody than a real nobody. Opportunity knocks in the form of a wealthy U.S. shipbuilder who hires Tom to travel to Italy to bring back his playboy son, Dickie. Ripley worms his way into the idyllic lives of Dickie and his girlfriend, plunging into a daring scheme of duplicity, lies and murder.","fr":"Tom Ripley, jeune homme désargenté mais ambitieux, attire l’attention d’un riche vieillard, Herbert Greenleaf, qui le charge de convaincre son fils Dickie, exilé en Italie, de rentrer aux États‐Unis. Sur place, Tom se laisse fasciner par l’existence insouciante et dorée que mène le jeune oisif. Il adopte ses goûts, imite son comportement, désire sa compagne, et va jusqu’à s’éprendre de Dickie lui‐même. Celui‐ci, dans un premier temps, traite Tom comme un ami mais, très vite, il commence à le trouver encombrant, pour ne pas dire énervant. Un jour, alors qu’ils sont seuls en mer, Tom avoue son amour à Dickie, qui le repousse violemment. Le conflit qui s’ensuit se termine par la mort de Dickie…"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/g7GOx0foFBSdrzzpNGKKeoKwdqA.jpg","es":"https://image.tmdb.org/t/p/w500/idVOOIQGbf22TF58amdYvHBL9Ua.jpg","de":"https://image.tmdb.org/t/p/w500/8YlmaxQTBiqVSAbW6Vc8VKPBdYg.jpg","en":"https://image.tmdb.org/t/p/w500/6ojHgqtIR41O2qLKa7LFUVj0cZa.jpg","fr":"https://image.tmdb.org/t/p/w500/vU4qTwtFpYF5EDsQwxqn4B83hzk.jpg"}'::jsonb WHERE id = 358;
UPDATE public.films SET tmdb_id = 2668, titoli_i18n = '{"en":"Sleepy Hollow","it":"Il mistero di Sleepy Hollow","de":"Sleepy Hollow","fr":"Sleepy Hollow, la légende du cavalier sans tête","es":"Sleepy Hollow"}'::jsonb, trame_i18n = '{"en":"Skeptical young detective Ichabod Crane gets transferred to the hamlet of Sleepy Hollow, New York, where he is tasked with investigating the decapitations of three people – murders the townsfolk attribute to a legendary specter, The Headless Horseman.","it":"1799, il poliziotto Ichabod Crane viene inviato nel piccolo paese di Sleepy Hollow per indagare su una serie di omicidi commessi da un presunto cavaliere senza testa.","de":"Der Ermittler Ichabod Crane aus New York ist auf mehrere mysteriöse Todesfälle angesetzt worden, die sich in dem unscheinbaren Städtchen Sleepy Hollow zugetragen haben. Crane ist ein Mann des Verstandes und der Vernunft und gibt sich an die Aufklärung der Verbrechen mit neuartigen kriminalistischen Methoden. Doch schon bald muss er feststellen, dass in Sleepy Hollow der Wissenschaft schnell Grenzen gesetzt sind; spätestens dann, wenn sich Ichabod Crane dem leibhaftigen Hessen ohne Kopf persönlich gegenüber stehen sieht.","fr":"En 1799, dans une bourgade de la Nouvelle-Angleterre, plusieurs cadavres sont successivement retrouvés décapités. Les têtes ont disparu. Terrifiés, les habitants sont persuadés que ces meurtres sont commis par un étrange et furieux cavalier, dont la rumeur prétend qu''il est lui-même sans tête. Les autorités new-yorkaises envoient alors leur plus fin limier pour éclaircir ce mystère. Ichabod Crane ne croit ni aux légendes, ni aux vengeances post-mortem. Mais, à peine arrivé, il succombe au charme étrange et vénéneux de la belle Katrina Van Tassel.","es":"Durante la Guerra de Secesión Americana, un policía de Nueva York que utiliza avanzados métodos de investigación es enviado al pueblo de Sleepy Hollow para descubrir qué hay de verdad en la leyenda de un jinete sin cabeza que aterroriza a los habitantes del lugar. Una vez allí adopta la identidad de un profesor de escuela y se enamora de Katrina, que mantiene relaciones con uno de los hombres más conocidos del pueblo. Realidad y ficción se darán la mano en el momento menos pensado."}'::jsonb, posters_i18n = '{"en":"https://image.tmdb.org/t/p/w500/1GuK965FLJxqUw9fd1pmvjbFAlv.jpg","it":"https://image.tmdb.org/t/p/w500/eX61VBYV1mh4AARjogZ4WIZeGaQ.jpg","de":"https://image.tmdb.org/t/p/w500/5r5qM47DQP2BGatpMzt8Jyuk8Ta.jpg","fr":"https://image.tmdb.org/t/p/w500/gBVKVccVx7mwMeAF8VChefNpXl3.jpg","es":"https://image.tmdb.org/t/p/w500/sEsDyXI4LTjS0RmlUehHUGI7Xny.jpg"}'::jsonb WHERE id = 359;
UPDATE public.films SET tmdb_id = 745, titoli_i18n = '{"es":"El sexto sentido","de":"The Sixth Sense","en":"The Sixth Sense","it":"The Sixth Sense - Il sesto senso","fr":"Sixième Sens"}'::jsonb, trame_i18n = '{"es":"El Dr. Malcom Crowe es un conocido psicólogo infantil obsesionado con el doloroso recuerdo de un joven paciente desequilibrado al que fue incapaz de ayudar. Cole Sear es un aterrorizado y confuso niño de ocho años que necesita tratamiento, y Crowe ve la oportunidad de redimirse haciendo todo lo posible por ayudarle. Sin embargo, el psicólogo infantil no está preparado para conocer la terrible verdad acerca del don sobrenatural de su paciente: recibe visitas no deseadas de espíritus atormentados.","de":"Der Kinderpsychologe Dr. Malcolm Crowe feiert mit seiner Frau eine für ihn bedeutsame Auszeichnung. An diesem Abend wird er von Vincent Grey überrascht, einem ehemaligen Patienten, dem Crowe nicht helfen konnte. Sichtlich verzweifelt schießt er auf Dr. Crowe und begeht daraufhin Selbstmord. Im darauf folgenden Jahr betreut Dr. Crowe den neunjährigen Cole. Er erinnert ihn an seinen früheren Patienten Grey. Der Junge scheint von großen Ängsten geplagt, die er niemandem anvertraut. Von seinen Klassenkameraden wird er mit „Psycho“ angesprochen und gemieden. Sogar sein Lehrer bezeichnet ihn nach einem Streit so. Coles Mutter ist verzweifelt, und Dr. Crowe scheint dem Jungen nicht helfen zu können. Nach und nach gewinnt er schließlich das Vertrauen des Jungen; Cole verrät ihm sein Geheimnis: „Ich sehe tote Menschen. Die sind wütend. Die wissen nicht, dass sie tot sind.“ Zunächst glaubt Dr. Crowe ihm nicht.","en":"Following an unexpected tragedy, child psychologist Malcolm Crowe meets a nine year old boy named Cole Sear, who is hiding a dark secret.","it":"Un famoso psichiatra infantile in un momento difficile della propria vita fa amicizia con un bambino che sembra avere dei problemi. Presosi a cuore il caso, l''uomo riesce a entrarvi in confidenza e a scoprire che è disturbato da visioni: il piccolo asserisce infatti di poter vedere la gente morta.","fr":"Cole Sear, garçonnet de huit ans est hanté par un terrible secret. Son imaginaire est visité par des esprits menaçants. Trop jeune pour comprendre le pourquoi de ces apparitions et traumatisé par ces pouvoirs paranormaux, Cole s''enferme dans une peur maladive et ne veut révéler à personne la cause de son enfermement, à l''exception d''un psychologue pour enfants. La recherche d''une explication rationnelle guidera l''enfant et le thérapeute vers une vérité foudroyante et inexplicable."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/pvjph7FouToPBY3PhTvTyOYoJDX.jpg","de":"https://image.tmdb.org/t/p/w500/mItbnCncatYHCwV2w7gXUw3xmxB.jpg","en":"https://image.tmdb.org/t/p/w500/vOyfUXNFSnaTk7Vk5AjpsKTUWsu.jpg","it":"https://image.tmdb.org/t/p/w500/1Dth4Jbh7FzPguUIddmK43deTCy.jpg","fr":"https://image.tmdb.org/t/p/w500/7s3ekiDpic8NxDjwdLdOYDIX8Pe.jpg"}'::jsonb WHERE id = 360;
UPDATE public.films SET tmdb_id = 30497, titoli_i18n = '{"fr":"Massacre à la tronçonneuse","it":"Non aprite quella porta","de":"Blutgericht in Texas","en":"The Texas Chain Saw Massacre","es":"La matanza de Texas"}'::jsonb, trame_i18n = '{"fr":"Au fin fond du Texas, des habitants font une découverte macabre : leur cimetière vient d''être profané et les cadavres exposés sous forme de trophées. Pendant ce temps, cinq amis traversent la région à bord d''un minibus. Ils croisent en chemin la route d''un auto-stoppeur et décident de le prendre à bord. Mais lorsque les jeunes gens s''aperçoivent que l''individu a un comportement inquiétant et menaçant, ils finissent par s''en débarrasser. Bientôt à court d''essence, le groupe décide d''aller visiter une vieille maison abandonnée, appartenant aux grands-parents de deux d''entre eux. Chacun leur tour, les cinq amis vont être attirés par la maison voisine. La rencontre avec ses étranges habitants va leur être fatale…","it":"Mentre è in corso una serie di misteriose razzie nei cimiteri della zona, Sally (Marilyn Burns), assieme al fratello paraplegico Franklin (Paul A. Partain) e a un gruppo di amici, parte per una vacanza in camper alla vecchia casa abbandonata del nonno. Prima di arrivarci, i ragazzi danno un passaggio a uno strano autostoppista con cui hanno un alterco prima di sbatterlo fuori. Dopo aver dato un’occhiata alla casa, i ragazzi si separano e due di loro, Pam (Teri McMinn) e Kirk (William Vail), si imbattono in un’altra casa apparentemente abbandonata che vogliono visitare. Ma Kirk viene ucciso e Pam viene trascinata dentro la casa e impalata in un gancio da macellaio da un essere gigantesco con una maschera di cuoio in faccia (Gunnar Hansen). E gli altri dovranno cercare di salvarsi lottando contro una famiglia di cannibali.","de":"Eine Gruppe junger Leute unternimmt einen Ausflug in die texanische Prärie, während der Wetterbericht von atmosphärischen Störungen kündet, welche nicht ohne Folgen auf die menschliche Psyche bleiben sollen. Als die Kids an einer scheinbar verlassenen Villa rasten, werden sie nacheinander von Mitgliedern einer in der Gegend ansässigen Metzgerfamilie attackiert, entführt oder ermordet. Lediglich einer der fünf Reisenden gelingt in letzter Sekunde die Flucht.","en":"Five friends head out to rural Texas to visit the grave of a grandfather. On the way, they stumble across what appears to be a deserted house, only to discover something sinister within. Something armed with a chainsaw.","es":"Cinco adolescentes visitan la tumba, supuestamente profanada, del abuelo de uno de ellos. Cuando llegan al lugar, donde hay un siniestro matadero, toman una deliciosa carne en una gasolinera. A partir de ese momento, los jóvenes vivirán la peor pesadilla de toda su vida."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/u61noSAr4IGVostCNbVApRXC4FZ.jpg","it":"https://image.tmdb.org/t/p/w500/8giqGVVX5UaQbmXM7ZEpGR9Xp8.jpg","de":"https://image.tmdb.org/t/p/w500/8yvocJK9DVChrdupZ7c4w87aP2U.jpg","en":"https://image.tmdb.org/t/p/w500/mpgkRPH1GNkMCgdPk2OMyHzAks7.jpg","es":"https://image.tmdb.org/t/p/w500/dDuWWq9VpBK0PFCDytlBpZhV6ca.jpg"}'::jsonb WHERE id = 361;
UPDATE public.films SET tmdb_id = 43539, titoli_i18n = '{"it":"The Next Three Days","de":"72 Stunden - The Next Three Days","fr":"Les Trois Prochains Jours","en":"The Next Three Days","es":"Los próximos tres días"}'::jsonb, trame_i18n = '{"it":"John Brennan, la moglie Lara e il loro piccolo Luke fanno colazione con amore e con gioia, quando la polizia irrompe con un mandato d''arresto per omicidio a carico della donna. Per tre anni, il marito le fa visita quotidianamente, certo che sia tutto un abbaglio, che la giustizia le ridarà la sua casa e la sua vita. Persino più certo della moglie, che lei quell''atto non l''abbia commesso, che non avrebbe mai potuto. Quando anche l''ultimo appello viene respinto e Lara tenta il sudicio, John, tranquillo insegnante di letteratura e padre di famiglia, decide che se non sarà la legge a fare uscire sua moglie di prigione, sarà lui.","de":"Lara Brennan, die Frau von College-Professor John Brennan wird aus heiterem Himmel wegen Mordes verhaftet. Der schockierten Familienmutter wird vorgeworfen ihre Chefin ermordet zu haben. Alle Indizien sprechen eindeutig gegen sie, doch John glaubt an seine Frau. Obwohl er alles daran setzt ihre Unschuld zu beweisen, wird Lara vor Gericht schuldig gesprochen. Gemeinsam mit einem ehemaligen Gefängnisinsassen entwickelt John den scheinbar perfekten Ausbruchsplan. Dann soll seine Ehefrau jedoch in ein anderes Gefängnis verlegt werden – John bleiben nur noch 72 Stunden um Lara zu befreien.","fr":"John Brennan, sa femme Lara et leur enfant vivent un bonheur sans nuage, jusqu''au jour où elle est arrêtée pour un meurtre qu''elle nie avoir commis. Trois ans après sa condamnation, John se débat pour préserver l''unité de sa famille, élevant seul leur fils, tout en se démenant pour prouver l''innocence de sa femme. Lorsque leur dernière tentative d''appel échoue, Lara s''enfonce dans la dépression au risque de mettre fin à ses jours. John n''a plus qu''une seule solution pour sauver sa femme : la faire évader. Malgré son inexpérience, John plonge dans les eaux troubles et dangereuses de l''illégalité et se lance dans l''opération de la dernière chance.","en":"Life seems perfect for John Brennan until his wife, Lara, is arrested for a murder she says she didn’t commit. Three years into her sentence, John is struggling to hold his family together, raising their son and teaching at college while he pursues every means available to prove her innocence. With the rejection of their final appeal, Lara becomes suicidal and John decides there is only one possible, bearable solution: to break his wife out of prison.","es":"La vida es perfecta para el profesor John Brennan hasta que su esposa, Laura, es acusada de un asesinato que no ha cometido. Durante tres largos años, John se ve condenado a sacar adelante a su hijo sin ninguna ayuda, a seguir dando clase en el colegio como si nada hubiera ocurrido y a reunir las pruebas necesarias para probar la inocencia de Laura.Pero su esposa está tan desesperada que intenta suicidarse. Después de esta traumática experiencia, a John no le queda otro remedio que idear un plan para ayudarle a escapar de la cárcel. Está dispuesto a dejar de ser quien es con tal de salvar a la mujer que ama."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/nCl2I0yGwKop0qBIpwXWJA7zQPP.jpg","de":"https://image.tmdb.org/t/p/w500/gmzSUgycQcTcxLjuDSGD0Pnrnz4.jpg","fr":"https://image.tmdb.org/t/p/w500/iGR71fLxh2fQpgsPN2WDtUEYYZS.jpg","en":"https://image.tmdb.org/t/p/w500/wBaRZ3aHa7qoYTSY0ONbXrXYk4B.jpg","es":"https://image.tmdb.org/t/p/w500/t9hzEgM3KJRFLHwEBbz4YZjpV6y.jpg"}'::jsonb WHERE id = 362;
UPDATE public.films SET tmdb_id = 696506, titoli_i18n = '{"it":"Mickey 17","es":"Mickey 17","en":"Mickey 17","fr":"Mickey 17","de":"Mickey 17"}'::jsonb, trame_i18n = '{"it":"Mickey 17 è un \"sacrificabile\", un impiegato usa e getta, in una spedizione umana inviata a colonizzare il mondo ghiacciato Niflheim. Dopo la morte di un''iterazione, un nuovo corpo viene rigenerato con la maggior parte dei suoi ricordi intatti.","es":"Mickey 17, un miembro de la tripulación ''expendable'' (prescindible) enviado a un planeta helado para colonizarlo, se niega a dejar que su clon de reemplazo, Mickey 18, tome su lugar... Adaptación del libro original de Edward Ashton.","en":"Unlikely hero Mickey Barnes finds himself in the extraordinary circumstance of working for an employer who demands the ultimate commitment to the job… to die, for a living.","fr":"En 2054, afin de fuir son cruel créancier, le naïf Mickey se porte volontaire pour une mission de colonisation sur Niflheim, une planète de glace. Devenu sans trop le savoir un ouvrier \"consommable\", il est régénéré chaque fois qu''il meurt lors des missions les plus dangereuses imposées par l''ex-sénateur Kenneth Marshall, dirigeant mégalomane de la colonie. Après quatre ans, Mickey en est à sa 17e incarnation. Grièvement blessé, il est laissé pour mort par son coéquipier au fond d''une crevasse. Mais contre toute attente, il est sauvé par la mère des créatures qui habitent Niflheim. Pendant son absence, un Mickey 18 est créé.","de":"Mickey Barnes, der unvermutete Held der Geschichte, befindet sich in einer außergewöhnlichen Situation, denn sein Arbeitgeber verlangt von ihm die ultimative Hingabe an den Job: Mickey verdient sich seinen Lebensunterhalt, indem er stirbt ..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/2JQBZs01ahsOiANQ7Fs8MN9zBY4.jpg","es":"https://image.tmdb.org/t/p/w500/iOKu6Hf5atv3DuXBS0jBF3OYYdu.jpg","en":"https://image.tmdb.org/t/p/w500/edKpE9B5qN3e559OuMCLZdW1iBZ.jpg","fr":"https://image.tmdb.org/t/p/w500/on60ASUpGg1xfiFucuMCv9wVqtq.jpg","de":"https://image.tmdb.org/t/p/w500/belnJtEppRZPMSvbMPAUWDm9ps7.jpg"}'::jsonb WHERE id = 363;
UPDATE public.films SET tmdb_id = 1375441, titoli_i18n = '{"es":"Primetime","it":"Primetime","fr":"Primetime","en":"Primetime","de":"Primetime"}'::jsonb, trame_i18n = '{"es":"En 2006, Chris Hansen, presentador de *To Catch a Predator*, se propone hacer historia en la televisión.","it":"Nel 2006 il giornalista Chris Hansen si prepara a fare la storia della televisione con To Catch a Predator, il controverso format che, attraverso operazioni sotto copertura e telecamere nascoste, smaschera in diretta tv predatori sessuali colti sul fatto. Mentre il programma diventa un fenomeno nazionale e il suo conduttore un’icona del pubblico, il confine tra informazione, giustizia e spettacolo si fa sempre più ambiguo e il cortocircuito fra cronaca, intrattenimento e voyeurismo televisivo sempre più insostenibile.","fr":"Chris Hansen présente l''émission policière « To Catch a Predator ». Diffusée sur NBC Dateline, cette émission tente de filmer des pédophiles présumés avec l''aide des forces de l''ordre et d''une équipe d''appâts se faisant passer pour des mineurs sur Internet. En 2006, Hansen est sur le point de révolutionner le monde de la télévision.","en":"In 2006, To Catch a Predator host Chris Hansen sets out to make television history. When a high stakes operation goes fatally wrong, his veneered dream of fame curdles into a nightmare of performative justice.","de":"Im Jahr 2006 macht sich Chris Hansen, der Moderator von „To Catch a Predator“, daran, Fernsehgeschichte zu schreiben."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/lmrulvLbmaejTix1YaMxo1oGhH1.jpg","it":"https://image.tmdb.org/t/p/w500/sqArsDFYFryd5iKuoxLvr4y5NZv.jpg","fr":"https://image.tmdb.org/t/p/w500/8W69bkus937B2OzJapRmw2uY42s.jpg","en":"https://image.tmdb.org/t/p/w500/lmrulvLbmaejTix1YaMxo1oGhH1.jpg","de":"https://image.tmdb.org/t/p/w500/iVtbZFH8QwcPB3U1xYDi9s9laOn.jpg"}'::jsonb WHERE id = 364;
UPDATE public.films SET tmdb_id = 856, titoli_i18n = '{"es":"¿Quién engañó a Roger Rabbit?","fr":"Qui veut la peau de Roger Rabbit ?","en":"Who Framed Roger Rabbit","de":"Falsches Spiel mit Roger Rabbit","it":"Chi ha incastrato Roger Rabbit"}'::jsonb, trame_i18n = '{"es":"Hollywood, 1947. Eddie Valiant, un detective de poca monta, ha sido contratado para encontrar pruebas que demuestren que Marvin Acme, magnate del negocio de los artículos de broma y dueño de Toontown, está rondando a Jessica Rabbit, mujer fatal y esposa de la superestrella del Marron Cartoon, Roger Rabbit. Cuando Acme aparece asesinado, todas las pruebas apuntan a Roger, y el siniestro y ambicioso Juez Doom está decidido a condenarlo como sea. Roger suplica a Valiant que le ayude a encontrar al verdadero culpable, pero el asunto se irá complicando a medida que Eddie va descubriendo, escándalo tras escándalo, que la propia existencia de Toontown corre peligro.","fr":"En 1947, à Hollywood, les grandes vedettes du cinéma partagent l''affiche avec les Toons, personnages animés. Roger Rabbit est amoureux transi de sa sublime femme Jessica, et son amour l''empêche de travailler correctement. Le producteur R.K. Maroon, le patron des Studios, tente de le ramener sur le droit chemin et engage Eddie Valiant, un détective privé humain et alcoolique, pour prouver à Roger Rabbit l''infidélité de Jessica. Des photos compromettantes sont prises et le présumé amant est retrouvé assassiné. Roger Rabbit est accusé du meurtre et recherché par l''ignoble juge Demort qui voue une haine féroce aux Toons.","en":"Toon star Roger is worried that his wife Jessica is playing pattycake with someone else, so the studio hires detective Eddie Valiant to snoop on her. But the stakes are quickly raised when Marvin Acme is found dead and Roger is the prime suspect.","de":"Roger Rabbit, einer der größten Stars Toontowns, wird gesucht: Er soll Marvin Acme ermordet haben, weil der angeblich ein Verhältnis mit Rogers Frau Jessica hatte. Richter Doom will ihn in seine berüchtigte “Suppe” stecken, das Einzige, was einen Toon töten kann. Roger fällt nichts anderes ein, als ausgerechnet den heruntergekommenen Privatdetektiv Eddie Valliant um Hilfe zu bitten, dessen Bruder von einem Toon getötet wurde. Seither hasst Valliant alle Zeichentrickfiguren, lässt sich aber doch dazu überreden, diesen Job anzunehmen.","it":"In uno studio cinematografico due cartoon stanno recitando una scena: Baby Herman, un poppante tutto pepe e pieno di trovate, e il suo baby-sitter, il coniglio Roger, che per togliere il piccolo da situazioni rischiose si mette in grossi guai. Nonostante l''impegno Roger non soddisfa il regista con la sua interpretazione: egli infatti è assillato da preoccupazioni familiari, teme che la sua bellissima moglie Jessica lo tradisca col padrone di Cartoonia, Marvin Acme. Viene incaricato di trovare le prove del tradimento il detective privato Eddie Valiant, sempre senza soldi e mezzo alcolizzato da quando suo fratello Teddy fu ucciso cinque anni prima da un cartoon. Eddie riesce a trovare ciò che cercava e per Roger è la disperazione: questi lascia l''ufficio del produttore Mr. Maroon in preda ad una nera desolazione e nulla può fare per consolarlo Valiant che ne ha compassione. La polizia trova il cadavere di Acme e dà subito la colpa a Roger..."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/nXqhkF0tJ1K2fglVMgimVZd5kMH.jpg","fr":"https://image.tmdb.org/t/p/w500/fJ1wJ9avrGj9VViC94CcRKL8N7w.jpg","en":"https://image.tmdb.org/t/p/w500/lYfRc57Kx9VgLZ48iulu0HKnM15.jpg","de":"https://image.tmdb.org/t/p/w500/cn0VQ9vKhdk6fr45HyOIptJOPwt.jpg","it":"https://image.tmdb.org/t/p/w500/5KZOkoKzj5wfJOGdWZYy4O4LLY2.jpg"}'::jsonb WHERE id = 365;
UPDATE public.films SET tmdb_id = 274, titoli_i18n = '{"fr":"Le Silence des agneaux","it":"Il silenzio degli innocenti","en":"The Silence of the Lambs","de":"Das Schweigen der Lämmer","es":"El silencio de los corderos"}'::jsonb, trame_i18n = '{"fr":"Un psychopathe connu sous le nom de Buffalo Bill sème la terreur dans le Middle West en kidnappant et en assassinant de jeunes femmes. Clarice Starling, une jeune stagiaire du FBI, est chargée d’interroger l’ex‐psychiatre Hannibal Lecter. Psychopathe redoutablement intelligent et porté sur le cannibalisme, Lecter est capable de lui fournir des informations concernant Buffalo Bill ainsi que son portrait psychologique. Mais il n’accepte de l’aider qu’en échange d’informations sur la vie privée de la jeune femme. Entre eux s’établit un lien de fascination et de répulsion.","it":"Dal romanzo omonimo di Thomas Harris. Una giovane recluta dell''FBI è incaricata di far visita in carcere a Hannibal Lecter, psichiatra pluriomicida, per ottenere informazioni su un assassino psicopatico che ha ucciso e scuoiato cinque donne.","en":"Clarice Starling is a top student at the FBI''s training academy.  Jack Crawford wants Clarice to interview Dr. Hannibal Lecter, a brilliant psychiatrist who is also a violent psychopath, serving life behind bars for various acts of murder and cannibalism.  Crawford believes that Lecter may have insight into a case and that Starling, as an attractive young woman, may be just the bait to draw him out.","de":"Clarice Starling, Auszubildende beim FBI, bekommt von einem ihrer Lehrer den Auftrag, sich im Gefängnis mit Dr. Hannibal Lecter, einem Massenmörder und Psychiater, zu befassen. Durch ihre Unbefangenheit hoffen sie, daß Lecter ihnen bei der Suche nach einem anderen Serienkiller hilft, aber es ist nicht leicht, an Lecter heranzukommen.","es":"Clarice Starling, del FBI, se aventura a una prisión de máxima seguridad para analizar el cerebro enfermo de Hannibal Lecter, un psiquiatra convertido en caníbal."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/sSQDxwm4r28YpJSQVyVOtpYVs0E.jpg","it":"https://image.tmdb.org/t/p/w500/jCS4Iw1bGGhSEdzFeUq8CX8UoiC.jpg","en":"https://image.tmdb.org/t/p/w500/uS9m8OBk1A8eM9I042bx8XXpqAq.jpg","de":"https://image.tmdb.org/t/p/w500/yyW5OFz5r8S81R2Afj9ILiEa70w.jpg","es":"https://image.tmdb.org/t/p/w500/8FdQQ3cUCs9goEOr1qUFaHackoJ.jpg"}'::jsonb WHERE id = 366;
UPDATE public.films SET tmdb_id = 1292695, titoli_i18n = '{"it":"Ti uccideranno","de":"They Will Kill You","fr":"They Will Kill You","en":"They Will Kill You","es":"Te van a matar"}'::jsonb, trame_i18n = '{"it":"\"Ti uccideranno\" porta sul grande schermo un horror-action-comedy ad alto tasso di adrenalina e intriso di sangue, in cui una giovane donna deve sopravvivere alla notte al Virgil, dove è stata da poco assunta come domestica, senza sapere che quell’edificio nasconde un passato inquietante fatto di inspiegabili sparizioni.  Ne nasce uno scontro cinematografico audace e senza freni, tra uccisioni efferate e un umorismo nerissimo.","de":"Eine Frau antwortet auf eine Stellenanzeige als Haushälterin in einem mysteriösen Hochhaus in New York City, ohne zu ahnen, dass sie damit in eine Gemeinschaft eintritt, in der es im Laufe der Jahre zu einer Reihe von Verschwinden gekommen ist und die möglicherweise unter dem Einfluss einer satanistischen Sekte steht.","fr":"Une jeune femme doit survivre toute une nuit, enfermée dans le mystérieux et sordide repaire d''une secte démoniaque, et tout faire pour ne pas devenir leur prochain sacrifice. Une lutte acharnée, des combats saisissants et un humour profondément noir vous attendent.","en":"A woman answers a help wanted ad to be a housekeeper in a mysterious New York City high-rise, unaware that she is entering a community that has seen a number of disappearances over the years and may be under the grip of a Satanic cult.","es":"Una mujer acepta un trabajo como ama de llaves en un rascacielos de Nueva York, sin conocer el historial de desapariciones del edificio. Pronto se da cuenta de que la comunidad está rodeada de misterio."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/jCe5etBmMuTf2TXgYvv0EDUj4BZ.jpg","de":"https://image.tmdb.org/t/p/w500/ywrFHscZl86wM0a32SR8PniIf9B.jpg","fr":"https://image.tmdb.org/t/p/w500/gyc0CMzFS91ZtXyhPcw7mE60v6Y.jpg","en":"https://image.tmdb.org/t/p/w500/6oI4oQKTWMVUlr8Ivqydp28Ruu6.jpg","es":"https://image.tmdb.org/t/p/w500/9dEn8a12dqkQw48zxQhPcpQ7D5W.jpg"}'::jsonb WHERE id = 367;
UPDATE public.films SET tmdb_id = 1242898, titoli_i18n = '{"es":"Predator: Badlands","it":"Predator: Badlands","en":"Predator: Badlands","fr":"Predator : Badlands","de":"Predator: Badlands"}'::jsonb, trame_i18n = '{"es":"Un joven Predator rechazado por su clan encuentra un aliado inesperado en Thia y emprende un peligroso viaje en busca del adversario definitivo.","it":"Nel futuro, su un pianeta remoto, un giovane Predatore, emarginato dal suo clan, trova un alleato improbabile in Thia e intraprende un viaggio pericoloso alla ricerca del nemico supremo.","en":"Cast out from his clan, a young Predator finds an unlikely ally in a damaged android and embarks on a treacherous journey in search of the ultimate adversary.","fr":"Jugé trop faible et indigne par son père, chef de la tribu des Yautja, Dek est sur le point de se faire exécuter par son frère Kwei. Mais au dernier moment, celui-ci préfère se sacrifier pour favoriser sa fuite. Décidé à prouver son courage, le jeune paria se rend sur la planète Genna pour y capturer le Kalisk, un monstre réputé invincible. Confronté à une nature hostile et imprévisible, le guerrier inexpérimenté doit sa survie à Thia, une androïde privée de la partie inférieure de son corps depuis son affrontement avec le Kalisk. Avec l''aide de celle-ci, Dek amorce sa traque de la terrible créature, convoitée par des scientifiques pour ses formidables dons de régénération.","de":"Ein noch junger Predator namens Dek wird von seinem eigenen Clan verstoßen. Die anderen sehen in ihm keinen starken, furchtlosen Krieger heranwachsen. Damit ist er für die Gemeinschaft wertlos, da niemand glaubt, dass Dek eine glorreiche Zukunft bei der Jagd bevorsteht. Fortan muss er also alleine auf einem abgelegenen Planeten klarkommen. Doch dort bleibt er nicht lange alleine. Dek stößt auf Thia mit der er eine unverhoffte Verbündete findet. Von nun an gehen die beiden also gemeinsam auf die Jagd und treffen einen weiteren Weggefährten. Zu dritt müssen sie sich schließlich auch einer scheinbar übermächtigen Bedrohung stellen. Im Laufe ihres gemeinsamen Abenteuers werden sie beste Freunde und lernen, einander auch in ausweglosen Situationen zu vertrauen. Dek wächst dabei als Jäger über sich hinaus und lernt, richtig gut zu jagen."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/8nCEJ5hFJt0h8FhXafHGhEhT8d7.jpg","it":"https://image.tmdb.org/t/p/w500/zn14Felr0VlFg6A86IUx4PDt2E7.jpg","en":"https://image.tmdb.org/t/p/w500/pHpq9yNUIo6aDoCXEBzjSolywgz.jpg","fr":"https://image.tmdb.org/t/p/w500/empQGO0pCVTndCpihyVpNfaLebl.jpg","de":"https://image.tmdb.org/t/p/w500/lxw9cD6g5Ccfml1PthmO6YT2aMp.jpg"}'::jsonb WHERE id = 368;
UPDATE public.films SET tmdb_id = 972533, titoli_i18n = '{"it":"Last Breath","de":"Last Breath","en":"Last Breath","fr":"Last Breath","es":"Sin oxígeno"}'::jsonb, trame_i18n = '{"it":"Last Breath segue un esperto sommozzatore delle profondità marine mentre combatte gli elementi furiosi per salvare il suo compagno di equipaggio intrappolato a centinaia di metri sotto la superficie dell''oceano.","de":"Erfahrene Tiefseetaucher kämpfen gegen die tobenden Elemente, um ihren Mannschaftskameraden zu retten, der Hunderte von Metern unter der Meeresoberfläche gefangen ist.","en":"Seasoned deep-sea divers battle the raging elements to rescue their crewmate trapped hundreds of feet below the ocean''s surface.","fr":"Lorsqu''un plongeur reste piégé à des centaines de mètres sous la surface de l''océan, une course contre la montre s''amorce afin de le ramener à la surface.","es":"La increíble historia real de Chris Lemons (Finn Cole), un buzo profesional que, tras un extraño accidente, queda atrapado en el fondo del Mar del Norte. Con tan solo 10 minutos de oxígeno de emergencia y a más de media hora de cualquier esperanza de rescate, esta es la lucha imposible de un hombre por sobrevivir a 90 metros de profundidad. Mientras tanto, en la superficie, sus compañeros Duncan (Woody Harrelson) y Dave (Simu Liu) lucharán contra una feroz tormenta y harán todo lo posible por rescatarlo con vida."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/mKP5zZ8NjUf68D0qte9LyIA0C6k.jpg","de":"https://image.tmdb.org/t/p/w500/7qk3yuoVqL52miBRL6iKNWGzi6c.jpg","en":"https://image.tmdb.org/t/p/w500/uB8yTnF6YLIIVKuRJAK8LNk8C6w.jpg","fr":"https://image.tmdb.org/t/p/w500/dhwOAQ9gSdiKeuVn8XT9tqok8mO.jpg","es":"https://image.tmdb.org/t/p/w500/bgcf7lci3pwWSMgHNBlqDDQbyJJ.jpg"}'::jsonb WHERE id = 369;
UPDATE public.films SET tmdb_id = 1083968, titoli_i18n = '{"it":"Locked - In trappola","es":"Blindado","en":"Locked","de":"Locked","fr":"Piégé"}'::jsonb, trame_i18n = '{"it":"Un ladruncolo riesce a forzare la serratura di un SUV di lusso, ma quando è dentro all''abitacolo si rende conto di essere incappato in una trappola complessa e mortale, tesagli da una figura misteriosa.","es":"Un ladrón irrumpe en un todoterreno de lujo y se da cuenta de que ha tropezado con una trampa compleja y mortal tendida por una misteriosa figura.","en":"When Eddie breaks into a luxury SUV, he steps into a deadly trap set by William, a self-proclaimed vigilante delivering his own brand of twisted justice. With no means of escape, Eddie must fight to survive in a ride where escape is an illusion, survival is a nightmare, and justice shifts into high gear.","de":"Als Eddie in einen luxuriösen Geländewagen einbricht, tappt er in eine tödliche Falle, die ihm William gestellt hat, ein Selbstjustizler, der seine eigene Art von verdrehter Gerechtigkeit ausübt. Ohne Fluchtmöglichkeit muss Eddie um sein Überleben kämpfen - in einer Welt, in der die Flucht eine Illusion, das Überleben ein Albtraum und die Gerechtigkeit ein hohes Tempo hat.","fr":"Les ennuis commencent pour Eddie, un jeune voleur, lorsqu''il s''introduit dans un SUV de luxe. Il découvre rapidement qu''il est pris au piège dans un jeu mortel orchestré par William, un justicier autoproclamé. Alors qu''Eddie tente désespérément de s''échapper, il se rend compte que sa situation est bien plus dangereuse qu''il ne l''imaginait..."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/nn2TyHzFpOszdqgAQuAmS2WSxYe.jpg","es":"https://image.tmdb.org/t/p/w500/xIyIiJCss0HpychoUKFQYKiZiBH.jpg","en":"https://image.tmdb.org/t/p/w500/hhkiqXpfpufwxVrdSftzeKIANl3.jpg","de":"https://image.tmdb.org/t/p/w500/ql35bug5dlqT3aMlxoPKhuYyUs1.jpg","fr":"https://image.tmdb.org/t/p/w500/w620DtlHR14olwvXiVdQK0TGN1D.jpg"}'::jsonb WHERE id = 370;
UPDATE public.films SET tmdb_id = 1137350, titoli_i18n = '{"de":"Der phönizische Meisterstreich","es":"La trama fenicia","it":"La trama fenicia","en":"The Phoenician Scheme","fr":"The Phoenician Scheme"}'::jsonb, trame_i18n = '{"de":"Düstere Spionagegeschichte über eine angespannte Vater-Tochter-Beziehung in einem Familienunternehmen. Die Wendungen drehen sich um Verrat und moralisch graue Entscheidungen.","es":"El magnate Zsa-zsa Korda es un rico empresario europeo que se ve envuelto en una trama de espionaje junto a su hija Liesl, una monja con la que mantiene una relación difícil y a la quiere dejar el negocio familiar.","it":"Sopravvissuto ad un incidente aereo per la sesta volta in tutta la sua vita, il magnate internazionale Zsa-zsa Korda tenta di ricucire i rapporti con sua figlia Liesl, nel frattempo diventata suora, che non vede da troppo tempo.","en":"Wealthy businessman Zsa-zsa Korda appoints his only daughter, a nun, as sole heir to his estate. As Korda embarks on a new enterprise, they soon become the target of scheming tycoons, foreign terrorists, and determined assassins.","fr":"Le riche homme d''affaires Zsa-zsa Korda désigne sa fille unique, une religieuse, comme seule héritière de son patrimoine. Alors que les Korda se lancent dans une nouvelle entreprise, ils deviennent rapidement la cible de magnats intrigants, de terroristes étrangers et d''assassins déterminés."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/9EhvxOvEUGTzHUJEnF2A3dWXB46.jpg","es":"https://image.tmdb.org/t/p/w500/ts8IjoVDPH4wTlhZOm8owNlPhs4.jpg","it":"https://image.tmdb.org/t/p/w500/90yhkAmFHypazSdnR0LXSf5e6h0.jpg","en":"https://image.tmdb.org/t/p/w500/iXxIUVqpQAlyy98UjUlzjkMYuj6.jpg","fr":"https://image.tmdb.org/t/p/w500/aWucFFSKSo5k6dKn4WQXCQiu6MP.jpg"}'::jsonb WHERE id = 371;
UPDATE public.films SET tmdb_id = 1035259, titoli_i18n = '{"de":"Die nackte Kanone","fr":"Y a-t-il un flic pour sauver le monde ?","it":"Una pallottola spuntata","es":"Agárralo como puedas","en":"The Naked Gun"}'::jsonb, trame_i18n = '{"de":"Nur ein einziger Mann verfügt über diese ganz besonderen Fähigkeiten … die Spezialeinheit der Polizei zu leiten und die Welt zu retten! Lt. Frank Drebin Jr. tritt in die Fußstapfen seines Vaters.","fr":"Frank Drebin est le fils du légendaire inspecteur gaffeur du même nom. Son enquête sur un accident d’auto mortel l’amène à rencontrer la séduisante Beth Davenport, sœur de l’infortunée victime. Leur investigation les conduit à Richard Cane, le richissime et génial inventeur d’une automobile électrique révolutionnaire. Au fil de son enquête, Frank découvre que Cane fomente un sombre complot : utiliser une fréquence sonore inaudible pour renvoyer l''humanité à l''état sauvage.","it":"Solo un uomo ha le pall....ottole giuste per guidare la squadra di polizia e salvare il mondo. Il tenente Frank Drebin Jr. (Liam Neeson) è pronto a raccogliere l''eredità del padre","es":"El torpe teniente Frank Drebin Jr. intenta resolver un asesinato vinculado a un magnate tecnológico. Mientras investiga, su unidad policial corre peligro de ser cerrada. Con la ayuda de una escritora de crímenes, Frank se verá envuelto en situaciones tan absurdas como explosivas. Película reboot basada en la popular franquicia de comedia \"Agárralo como puedas\" y la serie de televisión \"Police Squad!\".","en":"Only one man has the particular set of skills... to lead Police Squad and save the world: Lt. Frank Drebin Jr. Following in his father''s footsteps, he must solve a murder case to prevent Police Squad from closure."}'::jsonb, posters_i18n = '{"de":"https://image.tmdb.org/t/p/w500/gFByp0Ent85Wrks1U8p14BQe6Gu.jpg","fr":"https://image.tmdb.org/t/p/w500/dIOzuzx0CLYpNLx1Yf44cykyYX5.jpg","it":"https://image.tmdb.org/t/p/w500/tL8WM2MW87Sf48QctGHIpnnNSWK.jpg","es":"https://image.tmdb.org/t/p/w500/v8FpKw8mOsHxC0YElkgNNSCzGMl.jpg","en":"https://image.tmdb.org/t/p/w500/rwla9vqzrKVVKVKiOuROTIXGsxj.jpg"}'::jsonb WHERE id = 372;
UPDATE public.films SET tmdb_id = 1153714, titoli_i18n = '{"fr":"La Mort d''une licorne","en":"Death of a Unicorn","de":"Death of a Unicorn","es":"La muerte del unicornio","it":"Death of a Unicorn"}'::jsonb, trame_i18n = '{"fr":"Un père et sa fille percutent et tuent accidentellement une licorne, alors qu''ils sont en route pour rejoindre le patron milliardaire de ce dernier, qui cherche à exploiter les incroyables propriétés médicinales de la créature.","en":"A father and daughter accidentally hit and kill a unicorn while en route to a weekend retreat, where his billionaire boss seeks to exploit the creature’s miraculous curative properties.","de":"Ridley begleitet ihren Vater Elliot und dessen Chef Dell Leopold zu einem Geschäftstermin, als sie bei einer Fahrt durch die Natur versehentlich ein Einhorn überfahren. Leopold beschließt, das magische Wesen in sein Labor zu bringen, um dort Experimente durchzuführen. Schnell entdeckt er die heilenden Kräfte der Einhorn-Körperteile, die das Potenzial haben, die Medizin grundlegend zu verändern. Doch getrieben von grenzenloser Profitgier beginnt Leopold, immer riskantere Entscheidungen zu treffen. Währenddessen häufen sich mysteriöse Ereignisse, die eine dunkle Wendung andeuten und die Beteiligten mit den Konsequenzen ihres Handelns konfrontieren.","es":"Padre e hija, Ridley y Elliot, atropellan a un unicornio con su coche y lo llevan al refugio, en medio de la naturaleza, de un multimillonario director de una farmacéutica.","it":"Elliot, dirigente vedovo di un''azienda farmaceutica, si reca con la figlia Ridley nella fastosa tenuta del suo capo, Odell Leopold. Guidando a gran velocità per il grave ritardo accumulato, Elliot finisce per investire un animale che si era fermato in mezzo alla strada: solo che non si tratta di un animale qualsiasi, ma di un unicorno. Quando la famiglia Leopold comprende che il sangue degli animali magici ha delle proprietà curative, pensa di sfruttare la scoperta a scopo commerciale. Nessuno però ha fatto i conti con l''ira di mamma e papà unicorno, assetati di vendetta."}'::jsonb, posters_i18n = '{"fr":"https://image.tmdb.org/t/p/w500/9unIGgBrHsIuvaYhsB88oVZhVBh.jpg","en":"https://image.tmdb.org/t/p/w500/xWlF2i51zUq7BUq4iJte1g9NyIM.jpg","de":"https://image.tmdb.org/t/p/w500/tbomnwkXAOF6jGalOytrk2qRy2p.jpg","es":"https://image.tmdb.org/t/p/w500/7ONypZBnKXAAzr1zCNDo88AD6qf.jpg","it":"https://image.tmdb.org/t/p/w500/k3Nuu7Z5PuC6UxVIl2xbGhFvIjj.jpg"}'::jsonb WHERE id = 373;
UPDATE public.films SET tmdb_id = 37136, titoli_i18n = '{"it":"Una pallottola spuntata","de":"Die nackte Kanone","en":"The Naked Gun: From the Files of Police Squad!","fr":"Y a-t-il un flic pour sauver la reine ?","es":"Agárralo como puedas"}'::jsonb, trame_i18n = '{"it":"Il cattivo Vincent Ludwig organizza un attentato contro la Regina Elisabetta, in visita in città. L''imbranato tenente di polizia Frank Drebin sospetta fin dall''inizio che ci sia qualcosa di losco in quel Ludwig e, avendo capito cosa sta tramando, cerca di mettergli i bastoni fra le ruote e salvare la regina.","de":"Ihre Majestät Elizabeth II. von England will die Stadt Los Angeles mit einem Besuch beglücken. Da kommt es natürlich einer Katastrophe gleich, wenn ausgerechnet der Vorsitzende des Empfangskomitees verdächtig wird, ein Rauschgifthändler und Killer zu sein. Ein solch heikler Fall verlangt einfach nach Leutnant Frank Drebin vom L.A. Police Squad. Temperamentvoll stürzt er sich in die Ermittlungen und hinterlässt dabei eine breite Spur von Chaos und Verwüstung...","en":"When the bumbling Lieutenant Frank Drebin investigates events following the shooting of his partner, he stumbles upon an attempt to assassinate Queen Elizabeth II.","fr":"Le lieutenant Frank Drebin est le monsieur catastrophes de la police de Los Angeles. Il est l’auteur de tant de bourdes et de scandales que ses supérieurs hiérarchiques s’apprêtent à le licencier. C’est ce moment que choisit la reine d’Angleterre pour arriver à Los Angeles. Drebin apprend que Ludwig est en train d’ourdir un diabolique complot contre la reine. Il persuade son supérieur de lui donner une dernière chance de se réhabiliter en sauvant la reine…","es":"Después de que su compañero Nordberg fuera tiroteado por una banda de narcotraficantes, el incompetente teniente Frank Drebin busca al jefe de la organización para vengarse. Sospecha del magnate naviero Vincent Ludwig, pero no tiene pruebas para inculparlo. Tendrá incluso que enfrentarse a una alcaldesa, que trata de obstaculizar su investigación. Sin embargo, Drebin consigue la inesperada ayuda de Jane Spencer, una antigua novia de Ludwig."}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/psaW7ECMBTmBjI83FhLgIyhCG6e.jpg","de":"https://image.tmdb.org/t/p/w500/2EjR99blDO7dEkMfaGrMPYeIFpN.jpg","en":"https://image.tmdb.org/t/p/w500/zT0mhZqZQJE1gSY5Eg9qcGP4NYo.jpg","fr":"https://image.tmdb.org/t/p/w500/bQsieGMAodtLhVP13JznizC553.jpg","es":"https://image.tmdb.org/t/p/w500/eykTYCLnPW4quK6rqOHtc5PR8qy.jpg"}'::jsonb WHERE id = 374;
UPDATE public.films SET tmdb_id = 38251, titoli_i18n = '{"es":"Mediterráneo","fr":"Mediterraneo","it":"Mediterraneo","de":"Mediterraneo","en":"Mediterraneo"}'::jsonb, trame_i18n = '{"es":"Segunda Guerra Mundial. Ocho soldados han recibido la orden de desembarcar en una pequeña e insignificante isla griega. Su misión es custodiarla, dado que tiene un alto valor estratégico. Cuando consiguen llegar a tierra, su nave se ha hundido y la radio se ha roto. El lugar, que al principio parecía desierto, en realidad está habitado por mujeres, ancianos y niños. Los ocho hombres, aislados del frente y de la realidad, empiezan a integrarse rápidamente entre los vecinos, llegando incluso a olvidarse de que son soldados y están en guerra.","fr":"En 1941, huit soldats italiens débarquent sur une ile de la mer Égée et vont, a la suite de plusieurs quiproquos, être coupés de la guerre et du reste du monde.","it":"Avventure, amori e tribolazioni di otto soldati del Regio Esercito Italiano che nel giugno 1941 sono mandati a presidiare un''isoletta greca dell''Egeo dove rimangono sino all''inverno del 1943, dimenticandosi degli avvenimenti bellici in corso. Uno degli otto non tornerà. Senza ambizioni storiche, è una favola, un racconto di formazione, un apologo sull''amicizia virile, sul desiderio di fuga (è dedicato “a tutti quelli che stanno scappando”), sulle difficoltà di crescere. Chiude un''ideale trilogia sul viaggio e su una generazione, quella del regista, formata da Marrakech Express e Turné. Un bel gioco di squadra attoriale e un''accattivante mistura di buffo e patetico con molti stereotipi e qualche leziosaggine ruffiana. Girato nell''isola di Kastellorizo (Megisti in greco). Oscar per il film straniero.","de":"Abenteuer, Liebesgeschichten und Leiden von acht Soldaten der Königlichen Italienischen Armee, die im Juni 1941 zur Bewachung einer kleinen griechischen Insel in der Ägäis entsandt werden, wo sie bis zum Winter 1943 verbleiben und die laufenden Kriegsereignisse vergessen. Einer der acht wird nicht zurückkehren. Ohne historische Ambitionen ist es ein Märchen, eine Coming-of-Age-Geschichte, eine Fabel über männliche Freundschaft, über den Wunsch nach Flucht (der Film ist „allen gewidmet, die auf der Flucht sind“) und über die Schwierigkeiten des Erwachsenwerdens. Er bildet den Abschluss einer idealen Trilogie über das Reisen und über eine Generation - die des Regisseurs -, bestehend aus „Marrakech Express“ und „Turné“. Ein schönes Zusammenspiel der Schauspieler und eine fesselnde Mischung aus Komik und Pathos mit vielen Klischees und etwas schmeichlerischer Affektiertheit.","en":"Greek Sea, World War II. An Italian ship leaves a handful of soldiers in a little island; their mission is to spot enemy ships and to hold the island in case of attack. The village of the island seems abandoned and there isn''t a single enemy in sight, so the soldiers begin to relax a little. Things change when their ship is hit and destroyed by the enemy, and the soldiers find themselves abandoned there."}'::jsonb, posters_i18n = '{"es":"https://image.tmdb.org/t/p/w500/xspcpzfsFSRQZPL80QOHQheVvhB.jpg","fr":"https://image.tmdb.org/t/p/w500/wfJ2flMchZPQCSdt8h3ZQNSW7Ym.jpg","it":"https://image.tmdb.org/t/p/w500/wfJ2flMchZPQCSdt8h3ZQNSW7Ym.jpg","de":"https://image.tmdb.org/t/p/w500/wfJ2flMchZPQCSdt8h3ZQNSW7Ym.jpg","en":"https://image.tmdb.org/t/p/w500/omFU47TZSR7xAAZcDHKM48SmVwe.jpg"}'::jsonb WHERE id = 375;
UPDATE public.films SET tmdb_id = 120467, titoli_i18n = '{"it":"Grand Budapest Hotel","en":"The Grand Budapest Hotel","es":"El gran hotel Budapest","fr":"The Grand Budapest Hotel","de":"Grand Budapest Hotel"}'::jsonb, trame_i18n = '{"it":"Una ragazza depone una chiave di una stanza d''hotel ai piedi del busto dedicato a uno scrittore scomparso. Lo stesso scrittore racconta delle origini del suo romanzo. Un uomo oramai anziano e stanco racconta in un albergo semi deserto ad un giovane scrittore la storia di Gustave H., il leggendario concierge del Grand Budapest Hotel, e del suo giovane protetto Zero, alle prese con il furto e il recupero di un dipinto rinascimentale inestimabile e la battaglia per un enorme patrimonio di famiglia.","en":"The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.","es":"El Sr. Gustave H., un legendario conserje de un famoso hotel europeo de entreguerras, entabla amistad con Zero Moustafa, un joven empleado al que convierte en su protegido. La historia trata sobre el robo y la recuperación de una pintura renacentista de valor incalculable y sobre la batalla que enfrenta a los miembros de una familia por una inmensa fortuna. Como telón de fondo, los levantamientos que transformaron Europa durante la primera mitad del siglo XX.","fr":"Pendant l’entre‐deux guerres, le légendaire concierge d’un grand hôtel et son jeune protégé se retrouvent impliqués dans une histoire mêlant le vol d’un tableau de la Renaissance, la bataille pour une énorme fortune familiale, et le lent puis soudain bouleversement qui transforme l’Europe en cette première moitié de XXème siècle.","de":"Gustave H. ist der legendäre Concierge eines Luxushotels in Europa. In den 20er Jahren des 20. Jahrhunderts baut er eine enge Freundschaft zu einem jungen Hotelangestellten namens Zero Moustafa auf, der mit der Zeit sein engster Vertrauter und Protégé wird. In der Zwischenzeit geht ein atemberaubender Kunstdiebstahl vonstatten, bei dem ein unschätzbar wertvolles Gemälde aus der Renaissance entwendet wird, Leute werden des Mordes an Madame D. beschuldigt und Gustave H. ist in den Kampf um ein Familienerbe verwickelt, während in Europa langsam die ersten Anzeichen eines drohenden Krieges nicht mehr zu übersehen sind. Außerdem machen noch das Konkurrenzhotel des Grand Budapest – das Excelsior''s Palace – und dessen Manager M. Ivan Probleme …"}'::jsonb, posters_i18n = '{"it":"https://image.tmdb.org/t/p/w500/tY8gmrOOzhJxfBLQNOxjbuSR52b.jpg","en":"https://image.tmdb.org/t/p/w500/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg","es":"https://image.tmdb.org/t/p/w500/1wk0vpNCX5T40KsGQKjfoDAhmJw.jpg","fr":"https://image.tmdb.org/t/p/w500/qcWTuWPu6x6t2MKt0MTfbResJiV.jpg","de":"https://image.tmdb.org/t/p/w500/cnYv3px6xOUryhCvasKO40v3fPD.jpg"}'::jsonb WHERE id = 376;
